export const demos: Record<string, DemoEntry> = {
  "accordion/basic": { component: Demo0, file: "accordion/basic.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nconst faq = [\n  {\n    value: 'delivery',\n    title: 'Yetkazib berish qancha vaqt oladi?',\n    body: \"Toshkent bo'ylab 1 kun, viloyatlarga 2–3 ish kuni.\",\n  },\n  {\n    value: 'payment',\n    title: \"Qanday to'lov usullari bor?\",\n    body: \"Click, Payme, Uzum va naqd pul. Karta orqali to'lov darhol tasdiqlanadi.\",\n  },\n  {\n    value: 'return',\n    title: \"Mahsulotni qaytarsa bo'ladimi?\",\n    body: \"Ha, 14 kun ichida, qadoq buzilmagan bo'lsa.\",\n  },\n];\n\nexport default function AccordionBasic() {\n  return (\n    <Accordion defaultValue=\"delivery\" className=\"max-w-xl\">\n      {faq.map((q) => (\n        <Accordion.Item key={q.value} value={q.value} title={q.title}>\n          {q.body}\n        </Accordion.Item>\n      ))}\n    </Accordion>\n  );\n}\n" },
  "accordion/composition": { component: Demo1, file: "accordion/composition.tsx", source: "'use client';\n\nimport { Accordion, Badge } from '@akhatmirzo/ui';\n\nexport default function AccordionComposition() {\n  return (\n    <Accordion variant=\"bordered\" className=\"max-w-xl\">\n      <Accordion.Item value=\"notifications\">\n        <Accordion.Trigger>\n          <span className=\"flex items-center gap-2\">\n            Bildirishnomalar\n            <Badge color=\"primary\" size=\"sm\">\n              3 ta yangi\n            </Badge>\n          </span>\n        </Accordion.Trigger>\n        <Accordion.Content>\n          <ul className=\"m-0 flex list-disc flex-col gap-1 pl-5\">\n            <li>Buyurtma #1042 yetkazildi</li>\n            <li>Yangi sharh qoldirildi</li>\n            <li>To'lov qabul qilindi</li>\n          </ul>\n        </Accordion.Content>\n      </Accordion.Item>\n      <Accordion.Item value=\"security\">\n        <Accordion.Trigger>Xavfsizlik</Accordion.Trigger>\n        <Accordion.Content>Parolni oxirgi marta 3 oy oldin o'zgartirgansiz.</Accordion.Content>\n      </Accordion.Item>\n      <Accordion.Item value=\"billing\" disabled>\n        <Accordion.Trigger>To'lov ma'lumotlari (tez orada)</Accordion.Trigger>\n        <Accordion.Content>—</Accordion.Content>\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "accordion/controlled": { component: Demo2, file: "accordion/controlled.tsx", source: "'use client';\n\nimport { Accordion, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst sections = [\n  { value: 'profile', title: \"Shaxsiy ma'lumotlar\", body: \"Ism, telefon va tug'ilgan sana.\" },\n  { value: 'address', title: 'Manzillar', body: 'Uy: Toshkent, Chilonzor tumani, 9-mavze.' },\n  { value: 'cards', title: \"To'lov kartalari\", body: 'Uzcard •• 4521, Humo •• 9087.' },\n];\n\nexport default function AccordionControlled() {\n  const [open, setOpen] = useState<string[]>(['profile']);\n\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <div className=\"flex flex-wrap gap-2\">\n        <Button size=\"sm\" variant=\"outline\" onClick={() => setOpen(sections.map((s) => s.value))}>\n          Hammasini ochish\n        </Button>\n        <Button size=\"sm\" variant=\"outline\" onClick={() => setOpen([])}>\n          Hammasini yopish\n        </Button>\n      </div>\n      <Accordion type=\"multiple\" value={open} onValueChange={setOpen}>\n        {sections.map((s) => (\n          <Accordion.Item key={s.value} value={s.value} title={s.title}>\n            {s.body}\n          </Accordion.Item>\n        ))}\n      </Accordion>\n    </div>\n  );\n}\n" },
  "accordion/multiple": { component: Demo3, file: "accordion/multiple.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionMultiple() {\n  return (\n    <Accordion type=\"multiple\" defaultValue={['delivery', 'payment']} className=\"max-w-xl\">\n      <Accordion.Item value=\"delivery\" title=\"Yetkazib berish qancha vaqt oladi?\">\n        Toshkent bo'ylab 1 kun, viloyatlarga 2–3 ish kuni.\n      </Accordion.Item>\n      <Accordion.Item value=\"payment\" title=\"Qanday to'lov usullari bor?\">\n        Click, Payme, Uzum va naqd pul.\n      </Accordion.Item>\n      <Accordion.Item value=\"return\" title=\"Mahsulotni qaytarsa bo'ladimi?\">\n        Ha, 14 kun ichida, qadoq buzilmagan bo'lsa.\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "accordion/non-collapsible": { component: Demo4, file: "accordion/non-collapsible.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionNonCollapsible() {\n  return (\n    <Accordion collapsible={false} defaultValue=\"courier\" variant=\"bordered\" className=\"max-w-xl\">\n      <Accordion.Item value=\"courier\" title=\"Kuryer orqali\">\n        Ertasi kuni eshigingizgacha. Narxi — 25 000 so'm.\n      </Accordion.Item>\n      <Accordion.Item value=\"pickup\" title=\"Olib ketish punktidan\">\n        Toshkentdagi 12 ta punktdan bepul olib ketasiz.\n      </Accordion.Item>\n      <Accordion.Item value=\"post\" title=\"Pochta orqali\">\n        Viloyatlarga 2–3 ish kuni. Narxi — 18 000 so'm.\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "accordion/variants": { component: Demo5, file: "accordion/variants.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionVariants() {\n  return (\n    <div className=\"grid w-full gap-6 md:grid-cols-3\">\n      {(['separated', 'bordered', 'ghost'] as const).map((variant) => (\n        <div key={variant} className=\"flex flex-col gap-2\">\n          <span className=\"text-xs font-medium text-text-muted\">{variant}</span>\n          <Accordion variant={variant} defaultValue=\"a\">\n            <Accordion.Item value=\"a\" title=\"Yetkazib berish\">\n              Toshkent bo'ylab 1 kun.\n            </Accordion.Item>\n            <Accordion.Item value=\"b\" title=\"To'lov\">\n              Click, Payme yoki naqd.\n            </Accordion.Item>\n            <Accordion.Item value=\"c\" title=\"Qaytarish\">\n              14 kun ichida.\n            </Accordion.Item>\n          </Accordion>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "alert/actions": { component: Demo6, file: "alert/actions.tsx", source: "'use client';\n\nimport { Alert, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function AlertActions() {\n  const [open, setOpen] = useState(true);\n\n  if (!open) {\n    return (\n      <Button size=\"sm\" onClick={() => setOpen(true)}>\n        Xabarni qaytarish\n      </Button>\n    );\n  }\n\n  return (\n    <Alert\n      className=\"max-w-xl\"\n      color=\"danger\"\n      title=\"To'lov o'tmadi\"\n      action={\n        <Button size=\"sm\" variant=\"outline\">\n          Qayta urinish\n        </Button>\n      }\n      onClose={() => setOpen(false)}\n    >\n      Bank to'lovni rad etdi. Karta ma'lumotlarini tekshiring.\n    </Alert>\n  );\n}\n" },
  "alert/banner": { component: Demo7, file: "alert/banner.tsx", source: "'use client';\n\nimport { Alert, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function AlertBanner() {\n  const [open, setOpen] = useState(true);\n\n  return (\n    <div className=\"w-full overflow-hidden rounded-lg border border-border bg-surface\">\n      {open && (\n        <Alert banner color=\"primary\" onClose={() => setOpen(false)}>\n          Bugun 23:00 dan 01:00 gacha texnik ishlar olib boriladi.\n        </Alert>\n      )}\n      <div className=\"flex items-center justify-between gap-3 p-6 text-sm text-text-muted\">\n        Sahifa kontenti\n        {!open && (\n          <Button size=\"sm\" onClick={() => setOpen(true)}>\n            Qaytarish\n          </Button>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "alert/colors": { component: Demo8, file: "alert/colors.tsx", source: "'use client';\n\nimport { Alert } from '@akhatmirzo/ui';\n\nexport default function AlertColors() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <Alert title=\"Yangi versiya chiqdi\">\n        Sahifani yangilang — o'zgarishlar darhol kuchga kiradi.\n      </Alert>\n      <Alert color=\"success\" title=\"Buyurtma qabul qilindi\">\n        Kuryer bugun 18:00 gacha qo'ng'iroq qiladi.\n      </Alert>\n      <Alert color=\"warning\" title=\"Obuna 3 kundan keyin tugaydi\">\n        To'lovni hozir qilsangiz, ma'lumotlaringiz saqlanib qoladi.\n      </Alert>\n      <Alert color=\"danger\" title=\"To'lov o'tmadi\">\n        Kartada mablag' yetarli emas. Boshqa kartani sinab ko'ring.\n      </Alert>\n      <Alert color=\"primary\" title=\"Maslahat\">\n        Tez qidirish uchun Ctrl + K ni bosing.\n      </Alert>\n      <Alert color=\"neutral\" title=\"Qoralama saqlandi\" />\n    </div>\n  );\n}\n" },
  "alert/variants": { component: Demo9, file: "alert/variants.tsx", source: "'use client';\n\nimport { Alert } from '@akhatmirzo/ui';\n\nexport default function AlertVariants() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <Alert color=\"success\" variant=\"soft\" title=\"Soft\">\n        Yumshoq fon — standart ko'rinish.\n      </Alert>\n      <Alert color=\"success\" variant=\"outline\" title=\"Outline\">\n        Rangli chegara va oddiy fon.\n      </Alert>\n      <Alert color=\"success\" variant=\"solid\" title=\"Solid\">\n        To'q fon — eng ko'p e'tibor tortadi.\n      </Alert>\n    </div>\n  );\n}\n" },
  "app-shell/basic": { component: Demo10, file: "app-shell/basic.tsx", source: "'use client';\n\nimport { AppShell, Sidebar } from '@akhatmirzo/ui';\nimport { BarChart3, Box, Home, Settings, Store, Users } from 'lucide-react';\nimport { useState } from 'react';\n\nconst items = [\n  { id: 'home', label: 'Bosh sahifa', icon: <Home /> },\n  { id: 'orders', label: 'Buyurtmalar', icon: <Box />, badge: 12 },\n  { id: 'customers', label: 'Mijozlar', icon: <Users /> },\n  { id: 'reports', label: 'Hisobotlar', icon: <BarChart3 /> },\n];\n\nexport default function AppShellBasic() {\n  const [page, setPage] = useState('home');\n  const current = items.find((i) => i.id === page)?.label ?? 'Sozlamalar';\n\n  return (\n    // Hujjat ichida cheklangan ramka; haqiqiy ilovada AppShell butun ekranni egallaydi\n    <div className=\"h-[480px] w-full overflow-auto rounded-xl border border-border\">\n      <AppShell className=\"[--ak-app-shell-height:480px]\" sidebarStorageKey=\"docs-app-shell\">\n        <Sidebar>\n          <Sidebar.Header>\n            <span className=\"grid size-9 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground\">\n              <Store className=\"size-5\" aria-hidden=\"true\" />\n            </span>\n            <span className=\"truncate text-sm font-bold\">Chorsu Market</span>\n          </Sidebar.Header>\n          <Sidebar.Content>\n            <Sidebar.Group label=\"Do'kon\">\n              {items.map((item) => (\n                <Sidebar.Item\n                  key={item.id}\n                  icon={item.icon}\n                  badge={item.badge}\n                  active={page === item.id}\n                  onClick={() => setPage(item.id)}\n                >\n                  {item.label}\n                </Sidebar.Item>\n              ))}\n            </Sidebar.Group>\n            <Sidebar.Group label=\"Boshqaruv\">\n              <Sidebar.Item\n                icon={<Settings />}\n                active={page === 'settings'}\n                onClick={() => setPage('settings')}\n              >\n                Sozlamalar\n              </Sidebar.Item>\n            </Sidebar.Group>\n          </Sidebar.Content>\n        </Sidebar>\n        <AppShell.Main>\n          <AppShell.Header>\n            <AppShell.SidebarToggle />\n            <span className=\"text-sm font-medium\">{current}</span>\n          </AppShell.Header>\n          <div className=\"flex flex-col gap-3 p-6\">\n            <h2 className=\"m-0 text-xl font-semibold\">{current}</h2>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Tugma yoki Ctrl/⌘ + B sidebar'ni yig'adi. Holat localStorage'da saqlanadi.\n            </p>\n          </div>\n        </AppShell.Main>\n      </AppShell>\n    </div>\n  );\n}\n" },
  "app-shell/collapsed": { component: Demo11, file: "app-shell/collapsed.tsx", source: "'use client';\n\nimport { AppShell, Avatar, Sidebar } from '@akhatmirzo/ui';\nimport { FileText, Home, PieChart, Store, TrendingUp, Wallet } from 'lucide-react';\n\nexport default function AppShellCollapsed() {\n  return (\n    <div className=\"h-[480px] w-full overflow-auto rounded-xl border border-border\">\n      <AppShell\n        className=\"[--ak-app-shell-height:480px]\"\n        defaultSidebarOpen={false}\n        shortcut={false}\n      >\n        <Sidebar>\n          <Sidebar.Header>\n            <span className=\"grid size-9 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground\">\n              <Store className=\"size-5\" aria-hidden=\"true\" />\n            </span>\n            <span className=\"truncate text-sm font-bold\">Chorsu Market</span>\n          </Sidebar.Header>\n          <Sidebar.Content>\n            <Sidebar.Group>\n              <Sidebar.Item icon={<Home />} href=\"#home\" active>\n                Bosh sahifa\n              </Sidebar.Item>\n              <Sidebar.Item icon={<Wallet />} href=\"#payments\" badge={3}>\n                To'lovlar\n              </Sidebar.Item>\n            </Sidebar.Group>\n            <Sidebar.Group label=\"Hisobotlar\" collapsible>\n              <Sidebar.Item icon={<TrendingUp />} href=\"#sales\">\n                Savdo\n              </Sidebar.Item>\n              <Sidebar.Item icon={<PieChart />} href=\"#categories\">\n                Toifalar\n              </Sidebar.Item>\n              <Sidebar.Item icon={<FileText />} href=\"#tax\" disabled>\n                Soliq (tez orada)\n              </Sidebar.Item>\n            </Sidebar.Group>\n          </Sidebar.Content>\n          <Sidebar.Footer>\n            <div className=\"flex min-w-0 items-center gap-3\">\n              <Avatar name=\"Dilnoza Karimova\" size=\"sm\" />\n              <span className=\"truncate text-sm font-medium\">Dilnoza Karimova</span>\n            </div>\n          </Sidebar.Footer>\n        </Sidebar>\n        <AppShell.Main>\n          <AppShell.Header>\n            <AppShell.SidebarToggle />\n            <span className=\"text-sm font-medium\">Bosh sahifa</span>\n          </AppShell.Header>\n          <p className=\"m-0 p-6 text-sm text-text-muted\">\n            Yig'ilgan holatda faqat ikonkalar ko'rinadi — ustiga kelsangiz Tooltip chiqadi.\n            \"Hisobotlar\" guruhi to'liq holatda yig'iladi.\n          </p>\n        </AppShell.Main>\n      </AppShell>\n    </div>\n  );\n}\n" },
  "app-shell/use-app-shell": { component: Demo12, file: "app-shell/use-app-shell.tsx", source: "'use client';\n\nimport { AppShell, Button, Sidebar, useAppShell } from '@akhatmirzo/ui';\nimport { Home, Inbox } from 'lucide-react';\n\nfunction Status() {\n  const { sidebarOpen, setSidebarOpen, collapsed } = useAppShell();\n  return (\n    <div className=\"flex flex-col items-start gap-3 p-6 text-sm\">\n      <p className=\"m-0 text-text-muted\">\n        Holat: <b className=\"text-text\">{collapsed ? \"yig'ilgan\" : \"to'liq\"}</b>\n      </p>\n      <Button size=\"sm\" onClick={() => setSidebarOpen(!sidebarOpen)}>\n        {collapsed ? 'Yoyish' : \"Yig'ish\"}\n      </Button>\n    </div>\n  );\n}\n\nexport default function AppShellUseAppShell() {\n  return (\n    <div className=\"h-[360px] w-full overflow-auto rounded-xl border border-border\">\n      <AppShell className=\"[--ak-app-shell-height:360px]\" shortcut={false}>\n        <Sidebar width={220}>\n          <Sidebar.Content>\n            <Sidebar.Group label=\"Pochta\">\n              <Sidebar.Item icon={<Inbox />} href=\"#inbox\" badge={4} active>\n                Kiruvchi\n              </Sidebar.Item>\n              <Sidebar.Item icon={<Home />} href=\"#home\">\n                Bosh sahifa\n              </Sidebar.Item>\n            </Sidebar.Group>\n          </Sidebar.Content>\n        </Sidebar>\n        <AppShell.Main>\n          <AppShell.Header>\n            <AppShell.SidebarToggle />\n          </AppShell.Header>\n          <Status />\n        </AppShell.Main>\n      </AppShell>\n    </div>\n  );\n}\n" },
  "archive/v0.1/accordion/basic": { component: Demo13, file: "archive/v0.1/accordion/basic.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nconst faq = [\n  {\n    value: 'delivery',\n    title: 'Yetkazib berish qancha vaqt oladi?',\n    body: \"Toshkent bo'ylab 1 kun, viloyatlarga 2–3 ish kuni.\",\n  },\n  {\n    value: 'payment',\n    title: \"Qanday to'lov usullari bor?\",\n    body: \"Click, Payme, Uzum va naqd pul. Karta orqali to'lov darhol tasdiqlanadi.\",\n  },\n  {\n    value: 'return',\n    title: \"Mahsulotni qaytarsa bo'ladimi?\",\n    body: \"Ha, 14 kun ichida, qadoq buzilmagan bo'lsa.\",\n  },\n];\n\nexport default function AccordionBasic() {\n  return (\n    <Accordion defaultValue=\"delivery\" className=\"max-w-xl\">\n      {faq.map((q) => (\n        <Accordion.Item key={q.value} value={q.value} title={q.title}>\n          {q.body}\n        </Accordion.Item>\n      ))}\n    </Accordion>\n  );\n}\n" },
  "archive/v0.1/accordion/composition": { component: Demo14, file: "archive/v0.1/accordion/composition.tsx", source: "'use client';\n\nimport { Accordion, Badge } from '@akhatmirzo/ui';\n\nexport default function AccordionComposition() {\n  return (\n    <Accordion variant=\"bordered\" className=\"max-w-xl\">\n      <Accordion.Item value=\"notifications\">\n        <Accordion.Trigger>\n          <span className=\"flex items-center gap-2\">\n            Bildirishnomalar\n            <Badge color=\"primary\" size=\"sm\">\n              3 ta yangi\n            </Badge>\n          </span>\n        </Accordion.Trigger>\n        <Accordion.Content>\n          <ul className=\"m-0 flex list-disc flex-col gap-1 pl-5\">\n            <li>Buyurtma #1042 yetkazildi</li>\n            <li>Yangi sharh qoldirildi</li>\n            <li>To'lov qabul qilindi</li>\n          </ul>\n        </Accordion.Content>\n      </Accordion.Item>\n      <Accordion.Item value=\"security\">\n        <Accordion.Trigger>Xavfsizlik</Accordion.Trigger>\n        <Accordion.Content>Parolni oxirgi marta 3 oy oldin o'zgartirgansiz.</Accordion.Content>\n      </Accordion.Item>\n      <Accordion.Item value=\"billing\" disabled>\n        <Accordion.Trigger>To'lov ma'lumotlari (tez orada)</Accordion.Trigger>\n        <Accordion.Content>—</Accordion.Content>\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "archive/v0.1/accordion/controlled": { component: Demo15, file: "archive/v0.1/accordion/controlled.tsx", source: "'use client';\n\nimport { Accordion, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst sections = [\n  { value: 'profile', title: \"Shaxsiy ma'lumotlar\", body: \"Ism, telefon va tug'ilgan sana.\" },\n  { value: 'address', title: 'Manzillar', body: 'Uy: Toshkent, Chilonzor tumani, 9-mavze.' },\n  { value: 'cards', title: \"To'lov kartalari\", body: 'Uzcard •• 4521, Humo •• 9087.' },\n];\n\nexport default function AccordionControlled() {\n  const [open, setOpen] = useState<string[]>(['profile']);\n\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <div className=\"flex flex-wrap gap-2\">\n        <Button size=\"sm\" variant=\"outline\" onClick={() => setOpen(sections.map((s) => s.value))}>\n          Hammasini ochish\n        </Button>\n        <Button size=\"sm\" variant=\"outline\" onClick={() => setOpen([])}>\n          Hammasini yopish\n        </Button>\n      </div>\n      <Accordion type=\"multiple\" value={open} onValueChange={setOpen}>\n        {sections.map((s) => (\n          <Accordion.Item key={s.value} value={s.value} title={s.title}>\n            {s.body}\n          </Accordion.Item>\n        ))}\n      </Accordion>\n    </div>\n  );\n}\n" },
  "archive/v0.1/accordion/multiple": { component: Demo16, file: "archive/v0.1/accordion/multiple.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionMultiple() {\n  return (\n    <Accordion type=\"multiple\" defaultValue={['delivery', 'payment']} className=\"max-w-xl\">\n      <Accordion.Item value=\"delivery\" title=\"Yetkazib berish qancha vaqt oladi?\">\n        Toshkent bo'ylab 1 kun, viloyatlarga 2–3 ish kuni.\n      </Accordion.Item>\n      <Accordion.Item value=\"payment\" title=\"Qanday to'lov usullari bor?\">\n        Click, Payme, Uzum va naqd pul.\n      </Accordion.Item>\n      <Accordion.Item value=\"return\" title=\"Mahsulotni qaytarsa bo'ladimi?\">\n        Ha, 14 kun ichida, qadoq buzilmagan bo'lsa.\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "archive/v0.1/accordion/non-collapsible": { component: Demo17, file: "archive/v0.1/accordion/non-collapsible.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionNonCollapsible() {\n  return (\n    <Accordion collapsible={false} defaultValue=\"courier\" variant=\"bordered\" className=\"max-w-xl\">\n      <Accordion.Item value=\"courier\" title=\"Kuryer orqali\">\n        Ertasi kuni eshigingizgacha. Narxi — 25 000 so'm.\n      </Accordion.Item>\n      <Accordion.Item value=\"pickup\" title=\"Olib ketish punktidan\">\n        Toshkentdagi 12 ta punktdan bepul olib ketasiz.\n      </Accordion.Item>\n      <Accordion.Item value=\"post\" title=\"Pochta orqali\">\n        Viloyatlarga 2–3 ish kuni. Narxi — 18 000 so'm.\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "archive/v0.1/accordion/variants": { component: Demo18, file: "archive/v0.1/accordion/variants.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionVariants() {\n  return (\n    <div className=\"grid w-full gap-6 md:grid-cols-3\">\n      {(['separated', 'bordered', 'ghost'] as const).map((variant) => (\n        <div key={variant} className=\"flex flex-col gap-2\">\n          <span className=\"text-xs font-medium text-text-muted\">{variant}</span>\n          <Accordion variant={variant} defaultValue=\"a\">\n            <Accordion.Item value=\"a\" title=\"Yetkazib berish\">\n              Toshkent bo'ylab 1 kun.\n            </Accordion.Item>\n            <Accordion.Item value=\"b\" title=\"To'lov\">\n              Click, Payme yoki naqd.\n            </Accordion.Item>\n            <Accordion.Item value=\"c\" title=\"Qaytarish\">\n              14 kun ichida.\n            </Accordion.Item>\n          </Accordion>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/avatar/basic": { component: Demo19, file: "archive/v0.1/avatar/basic.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nconst people = [\n  'Sarvar Abduxoliqov',\n  'Malika Rahimova',\n  'Jasur Karimov',\n  \"O'tkir Hoshimov\",\n  'Dilnoza Yusupova',\n  'Rustam Qodirov',\n];\n\nexport default function AvatarBasic() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {people.map((name) => (\n        <Avatar key={name} name={name} />\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/avatar/group": { component: Demo20, file: "archive/v0.1/avatar/group.tsx", source: "'use client';\n\nimport { Avatar, AvatarGroup } from '@akhatmirzo/ui';\n\nconst team = [\n  'Sarvar Abduxoliqov',\n  'Malika Rahimova',\n  'Jasur Karimov',\n  'Dilnoza Yusupova',\n  'Rustam Qodirov',\n  'Gulnora Aliyeva',\n  'Bekzod Toshmatov',\n];\n\nexport default function AvatarGroupDemo() {\n  return (\n    <AvatarGroup max={4} aria-label=\"Loyiha ishtirokchilari\">\n      {team.map((name) => (\n        <Avatar key={name} name={name} />\n      ))}\n    </AvatarGroup>\n  );\n}\n" },
  "archive/v0.1/avatar/image": { component: Demo21, file: "archive/v0.1/avatar/image.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarImage() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Avatar size=\"lg\" src=\"https://github.com/Akhatmirzo.png\" name=\"Akhatmirzo\" />\n      <Avatar size=\"lg\" src=\"/mavjud-emas.png\" name=\"Gulnora Aliyeva\" />\n      <Avatar size=\"lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/avatar/sizes": { component: Demo22, file: "archive/v0.1/avatar/sizes.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarSizes() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Avatar size=\"xs\" name=\"Malika Rahimova\" />\n        <Avatar size=\"sm\" name=\"Malika Rahimova\" />\n        <Avatar size=\"md\" name=\"Malika Rahimova\" />\n        <Avatar size=\"lg\" name=\"Malika Rahimova\" />\n        <Avatar size=\"xl\" name=\"Malika Rahimova\" />\n      </div>\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Avatar size=\"sm\" shape=\"square\" name=\"Bahor Market\" />\n        <Avatar size=\"md\" shape=\"square\" name=\"Bahor Market\" />\n        <Avatar size=\"lg\" shape=\"square\" name=\"Bahor Market\" />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/avatar/status": { component: Demo23, file: "archive/v0.1/avatar/status.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarStatus() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Avatar name=\"Sarvar Abduxoliqov\" status=\"online\" />\n      <Avatar name=\"Malika Rahimova\" status=\"offline\" />\n      <Avatar name=\"Rustam Qodirov\" status=\"busy\" />\n      <Avatar name=\"Jasur Karimov\" shape=\"square\" size=\"lg\" status=\"online\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/badge/colors": { component: Demo24, file: "archive/v0.1/badge/colors.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeColors() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge>Qoralama</Badge>\n      <Badge color=\"primary\">Yangi</Badge>\n      <Badge color=\"success\">To'langan</Badge>\n      <Badge color=\"warning\">Kutilmoqda</Badge>\n      <Badge color=\"danger\">Bekor qilindi</Badge>\n      <Badge color=\"info\">Yo'lda</Badge>\n    </div>\n  );\n}\n" },
  "archive/v0.1/badge/dot": { component: Demo25, file: "archive/v0.1/badge/dot.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeDot() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge dot color=\"success\">\n        Onlayn\n      </Badge>\n      <Badge dot color=\"warning\" variant=\"outline\">\n        Tekshirilmoqda\n      </Badge>\n      <Badge dot color=\"danger\" variant=\"solid\">\n        To'xtatilgan\n      </Badge>\n    </div>\n  );\n}\n" },
  "archive/v0.1/badge/removable": { component: Demo26, file: "archive/v0.1/badge/removable.tsx", source: "'use client';\n\nimport { Badge, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst initial = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\"];\n\nexport default function BadgeRemovable() {\n  const [cities, setCities] = useState(initial);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      {cities.map((city) => (\n        <Badge\n          key={city}\n          variant=\"outline\"\n          onRemove={() => setCities((list) => list.filter((c) => c !== city))}\n          labels={{ remove: `${city} filtrini olib tashlash` }}\n        >\n          {city}\n        </Badge>\n      ))}\n      {cities.length < initial.length && (\n        <Button variant=\"link\" size=\"sm\" onClick={() => setCities(initial)}>\n          Qaytarish\n        </Button>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.1/badge/sizes": { component: Demo27, file: "archive/v0.1/badge/sizes.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge size=\"sm\" color=\"primary\">\n        Kichik\n      </Badge>\n      <Badge size=\"md\" color=\"primary\">\n        O'rta\n      </Badge>\n    </div>\n  );\n}\n" },
  "archive/v0.1/badge/variants": { component: Demo28, file: "archive/v0.1/badge/variants.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeVariants() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge variant=\"soft\" color=\"success\">\n          Soft\n        </Badge>\n        <Badge variant=\"solid\" color=\"success\">\n          Solid\n        </Badge>\n        <Badge variant=\"outline\" color=\"success\">\n          Outline\n        </Badge>\n      </div>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge variant=\"soft\" color=\"danger\">\n          Soft\n        </Badge>\n        <Badge variant=\"solid\" color=\"danger\">\n          Solid\n        </Badge>\n        <Badge variant=\"outline\" color=\"danger\">\n          Outline\n        </Badge>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/button/as-child": { component: Demo29, file: "archive/v0.1/button/as-child.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { ArrowRight } from 'lucide-react';\n\nexport default function ButtonAsChild() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button asChild variant=\"outline\" rightIcon={<ArrowRight />}>\n        <a href=\"#accessibility\">Accessibility bo'limiga</a>\n      </Button>\n      <Button asChild variant=\"link\">\n        <a href=\"https://github.com/Akhatmirzo/akhatmirzo-toolkit\">GitHub</a>\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/button/full-width": { component: Demo30, file: "archive/v0.1/button/full-width.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonFullWidth() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Button variant=\"primary\" fullWidth>\n        Kirish\n      </Button>\n      <Button variant=\"outline\" fullWidth>\n        Ro'yxatdan o'tish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/button/icons": { component: Demo31, file: "archive/v0.1/button/icons.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { ArrowRight, Plus, Trash2 } from 'lucide-react';\n\nexport default function ButtonIcons() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\" leftIcon={<Plus />}>\n        Qo'shish\n      </Button>\n      <Button rightIcon={<ArrowRight />}>Davom etish</Button>\n      <Button variant=\"danger\" leftIcon={<Trash2 />}>\n        O'chirish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/button/loading": { component: Demo32, file: "archive/v0.1/button/loading.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function ButtonLoading() {\n  const [saving, setSaving] = useState(false);\n\n  const save = () => {\n    setSaving(true);\n    setTimeout(() => {\n      setSaving(false);\n      toast.success('Saqlandi');\n    }, 1500);\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\" loading={saving} onClick={save}>\n        Saqlash\n      </Button>\n      <Button variant=\"outline\" loading labels={{ loading: 'Yuborilmoqda' }}>\n        Yuborish\n      </Button>\n      <Button disabled>O'chirilgan</Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/button/sizes": { component: Demo33, file: "archive/v0.1/button/sizes.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button size=\"sm\">Kichik · 32</Button>\n      <Button size=\"md\">O'rta · 40</Button>\n      <Button size=\"lg\">Katta · 48</Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/button/variants": { component: Demo34, file: "archive/v0.1/button/variants.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonVariants() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\">Saqlash</Button>\n      <Button>Soft</Button>\n      <Button variant=\"outline\">Outline</Button>\n      <Button variant=\"ghost\">Ghost</Button>\n      <Button variant=\"danger\">O'chirish</Button>\n      <Button variant=\"link\">Batafsil</Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/card/basic": { component: Demo35, file: "archive/v0.1/card/basic.tsx", source: "'use client';\n\nimport { Avatar, Badge, Button, Card } from '@akhatmirzo/ui';\n\nexport default function CardBasic() {\n  return (\n    <Card className=\"w-full max-w-md\">\n      <Card.Header\n        title=\"Buyurtma #1042\"\n        description=\"Bugun, 14:20\"\n        action={\n          <Badge color=\"primary\" dot>\n            Yangi\n          </Badge>\n        }\n      />\n      <Card.Body>\n        <div className=\"flex items-center gap-3\">\n          <Avatar name=\"Sarvar Abduxoliqov\" size=\"sm\" />\n          <div className=\"flex flex-col\">\n            <span className=\"font-medium\">Sarvar Abduxoliqov</span>\n            <span className=\"text-text-muted\">3 ta mahsulot · 245 000 so'm</span>\n          </div>\n        </div>\n      </Card.Body>\n      <Card.Footer className=\"justify-end\">\n        <Button variant=\"ghost\">Bekor qilish</Button>\n        <Button variant=\"primary\">Tasdiqlash</Button>\n      </Card.Footer>\n    </Card>\n  );\n}\n" },
  "archive/v0.1/card/interactive": { component: Demo36, file: "archive/v0.1/card/interactive.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nconst reports = [\n  { title: 'Sotuvlar', description: \"Oktyabr · 48 250 000 so'm\" },\n  { title: 'Mijozlar', description: '1 204 ta faol mijoz' },\n];\n\nexport default function CardInteractive() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-2\">\n      {reports.map((report) => (\n        <Card key={report.title} variant=\"outline\" interactive asChild>\n          <a href=\"#props\">\n            <Card.Header title={report.title} description={report.description} />\n          </a>\n        </Card>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/card/media": { component: Demo37, file: "archive/v0.1/card/media.tsx", source: "'use client';\n\nimport { Badge, Card } from '@akhatmirzo/ui';\n\nexport default function CardMedia() {\n  return (\n    <Card padding=\"none\" className=\"w-full max-w-sm overflow-hidden\">\n      <div className=\"h-32 bg-linear-to-br from-primary to-info\" />\n      <div className=\"flex flex-col gap-3 p-6\">\n        <Card.Header title=\"Samarqand bo'ylab sayohat\" description=\"2 kun · 4 ta joy\" />\n        <Card.Footer>\n          <Badge color=\"success\" size=\"sm\">\n            Joy bor\n          </Badge>\n          <Badge size=\"sm\">Guruh</Badge>\n        </Card.Footer>\n      </div>\n    </Card>\n  );\n}\n" },
  "archive/v0.1/card/padding": { component: Demo38, file: "archive/v0.1/card/padding.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nconst paddings = [\n  { padding: 'sm', px: 16 },\n  { padding: 'md', px: 24 },\n  { padding: 'lg', px: 32 },\n] as const;\n\nexport default function CardPadding() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-3\">\n      {paddings.map(({ padding, px }) => (\n        <Card key={padding} variant=\"outline\" padding={padding}>\n          <div className=\"rounded-md bg-primary-soft p-2 text-xs font-medium text-primary-soft-foreground\">\n            {padding} · {px}px\n          </div>\n        </Card>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/card/variants": { component: Demo39, file: "archive/v0.1/card/variants.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nexport default function CardVariants() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-3\">\n      <Card variant=\"elevated\" padding=\"sm\">\n        <Card.Header title=\"Elevated\" description=\"Soya va chegara (standart)\" />\n      </Card>\n      <Card variant=\"outline\" padding=\"sm\">\n        <Card.Header title=\"Outline\" description=\"Faqat chegara\" />\n      </Card>\n      <Card variant=\"soft\" padding=\"sm\">\n        <Card.Header title=\"Soft\" description=\"Och kulrang fon\" />\n      </Card>\n    </div>\n  );\n}\n" },
  "archive/v0.1/checkbox/basic": { component: Demo40, file: "archive/v0.1/checkbox/basic.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxBasic() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <Checkbox label=\"Shartlarga roziman\" />\n      <Checkbox label=\"Meni eslab qol\" defaultChecked />\n      <Checkbox label=\"Qisman tanlangan\" checked=\"indeterminate\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/checkbox/description": { component: Demo41, file: "archive/v0.1/checkbox/description.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxDescription() {\n  return (\n    <div className=\"flex max-w-sm flex-col gap-4\">\n      <Checkbox\n        label=\"Yangiliklar\"\n        description=\"Haftasiga bir marta yangi imkoniyatlar haqida xat\"\n        defaultChecked\n      />\n      <Checkbox\n        size=\"sm\"\n        label=\"Qurilmani eslab qolish\"\n        description=\"30 kun davomida qayta kod so'ralmaydi\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.1/checkbox/select-all": { component: Demo42, file: "archive/v0.1/checkbox/select-all.tsx", source: "'use client';\n\nimport { Checkbox, type CheckedState } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst channels = ['Email', 'SMS', 'Telegram'];\n\nexport default function CheckboxSelectAll() {\n  const [selected, setSelected] = useState<string[]>(['Email']);\n  const all: CheckedState =\n    selected.length === channels.length ? true : selected.length > 0 ? 'indeterminate' : false;\n\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <Checkbox\n        label=\"Barcha kanallar\"\n        checked={all}\n        onCheckedChange={(checked) => setSelected(checked ? channels : [])}\n      />\n      <div className=\"flex flex-col gap-3 pl-7\">\n        {channels.map((channel) => (\n          <Checkbox\n            key={channel}\n            label={channel}\n            checked={selected.includes(channel)}\n            onCheckedChange={(checked) =>\n              setSelected((s) => (checked ? [...s, channel] : s.filter((c) => c !== channel)))\n            }\n          />\n        ))}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/checkbox/sizes": { component: Demo43, file: "archive/v0.1/checkbox/sizes.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-6\">\n      <Checkbox size=\"sm\" label=\"Kichik · 16\" defaultChecked />\n      <Checkbox size=\"md\" label=\"O'rta · 20\" defaultChecked />\n    </div>\n  );\n}\n" },
  "archive/v0.1/checkbox/states": { component: Demo44, file: "archive/v0.1/checkbox/states.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxStates() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <Checkbox label=\"O'chirilgan\" disabled />\n      <Checkbox label=\"O'chirilgan, belgilangan\" disabled defaultChecked />\n      <Checkbox label=\"Xato\" invalid />\n    </div>\n  );\n}\n" },
  "archive/v0.1/checkbox/with-field": { component: Demo45, file: "archive/v0.1/checkbox/with-field.tsx", source: "'use client';\n\nimport { Checkbox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CheckboxWithField() {\n  const [agree, setAgree] = useState(false);\n\n  return (\n    <div className=\"max-w-sm\">\n      <Field\n        label=\"Foydalanish shartlari\"\n        required\n        error={agree ? undefined : 'Davom etish uchun rozilik kerak'}\n      >\n        <Checkbox label=\"Shartlar bilan tanishdim\" checked={agree} onCheckedChange={setAgree} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/combobox/basic": { component: Demo46, file: "archive/v0.1/combobox/basic.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst cities = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Xiva',\n  'Namangan',\n  'Andijon',\n  \"Farg'ona\",\n  \"Qo'qon\",\n  \"Marg'ilon\",\n  'Nukus',\n  'Qarshi',\n  'Termiz',\n].map((label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }));\n\nexport default function ComboboxBasic() {\n  const [city, setCity] = useState<string | null>(null);\n\n  return (\n    <Field\n      label=\"Shahar\"\n      description={city ? `Qiymat: ${city}` : 'Hali tanlanmagan'}\n      className=\"w-full max-w-xs\"\n    >\n      <Combobox\n        options={cities}\n        value={city}\n        onValueChange={setCity}\n        placeholder=\"Shahar tanlang\"\n        clearable\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.1/combobox/creatable": { component: Demo47, file: "archive/v0.1/combobox/creatable.tsx", source: "'use client';\n\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst initialTags: ComboboxOption[] = ['dizayn', 'frontend', 'backend', 'mobil'].map((t) => ({\n  value: t,\n  label: t,\n}));\n\nexport default function ComboboxCreatable() {\n  const [tags, setTags] = useState(initialTags);\n  const [chosen, setChosen] = useState<string[]>(['frontend']);\n\n  return (\n    <Field\n      label=\"Teglar\"\n      description=\"Ro'yxatda yo'q tegni yozing va Enter bosing\"\n      className=\"w-full max-w-sm\"\n    >\n      <Combobox\n        multiple\n        creatable\n        options={tags}\n        value={chosen}\n        onValueChange={setChosen}\n        onCreate={(text) => {\n          const option = { value: text.toLowerCase(), label: text };\n          setTags((prev) => [...prev, option]);\n          return option;\n        }}\n        placeholder=\"Teg qo'shing\"\n        leftIcon={null}\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.1/combobox/details": { component: Demo48, file: "archive/v0.1/combobox/details.tsx", source: "'use client';\n\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\n\nfunction Dot({ className }: { className: string }) {\n  return <span className={`size-2.5 rounded-full ${className}`} />;\n}\n\nconst statuses: ComboboxOption[] = [\n  {\n    value: 'new',\n    label: 'Yangi',\n    description: 'Buyurtma qabul qilindi',\n    icon: <Dot className=\"bg-info\" />,\n  },\n  {\n    value: 'packing',\n    label: \"Yig'ilmoqda\",\n    description: 'Omborda tayyorlanmoqda',\n    icon: <Dot className=\"bg-warning\" />,\n  },\n  {\n    value: 'shipping',\n    label: \"Yo'lda\",\n    description: 'Kuryerga topshirildi',\n    icon: <Dot className=\"bg-primary\" />,\n  },\n  {\n    value: 'cancelled',\n    label: 'Bekor qilingan',\n    description: 'Arxivlangan holat',\n    icon: <Dot className=\"bg-danger\" />,\n    disabled: true,\n  },\n];\n\nexport default function ComboboxDetails() {\n  return (\n    <Field label=\"Buyurtma holati\" className=\"w-full max-w-xs\">\n      <Combobox options={statuses} defaultValue=\"packing\" leftIcon={null} />\n    </Field>\n  );\n}\n" },
  "archive/v0.1/combobox/multiple": { component: Demo49, file: "archive/v0.1/combobox/multiple.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst branches = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Namangan',\n  'Andijon',\n  \"Farg'ona\",\n  'Nukus',\n].map((label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }));\n\nexport default function ComboboxMultiple() {\n  const [selected, setSelected] = useState<string[]>(['toshkent', 'samarqand']);\n\n  return (\n    <Field\n      label=\"Filiallar\"\n      description={`${selected.length} ta tanlangan`}\n      className=\"w-full max-w-sm\"\n    >\n      <Combobox\n        multiple\n        options={branches}\n        value={selected}\n        onValueChange={setSelected}\n        placeholder=\"Filiallarni tanlang\"\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.1/combobox/server": { component: Demo50, file: "archive/v0.1/combobox/server.tsx", source: "'use client';\n\nimport { searchMatch } from '@akhatmirzo/core';\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\nimport { useRef, useState } from 'react';\n\nconst all: ComboboxOption[] = ['Toshkent', 'Samarqand', 'Buxoro', 'Xiva', 'Nukus', 'Termiz'].map(\n  (label) => ({ value: label.toLowerCase(), label }),\n);\n\nexport default function ComboboxServer() {\n  const [options, setOptions] = useState(all.slice(0, 3));\n  const [loading, setLoading] = useState(false);\n  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);\n\n  // Server so'rovini taqlid qiladi: javob 700ms dan keyin keladi\n  const search = (query: string) => {\n    clearTimeout(timer.current);\n    setLoading(true);\n    timer.current = setTimeout(() => {\n      setOptions(query ? all.filter((o) => searchMatch(o.label, query).match) : all.slice(0, 3));\n      setLoading(false);\n    }, 700);\n  };\n\n  return (\n    <Field label=\"Shahar (serverdan)\" className=\"w-full max-w-xs\">\n      <Combobox\n        options={options}\n        loading={loading}\n        onSearch={search}\n        placeholder=\"Qidirib tanlang\"\n        searchPlaceholder=\"Shahar nomi...\"\n        emptyText=\"Server hech narsa qaytarmadi\"\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.1/combobox/sizes": { component: Demo51, file: "archive/v0.1/combobox/sizes.tsx", source: "'use client';\n\nimport { Combobox } from '@akhatmirzo/ui';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro'].map((label) => ({\n  value: label.toLowerCase(),\n  label,\n}));\n\nexport default function ComboboxSizes() {\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Combobox size=\"sm\" options={cities} aria-label=\"Shahar\" placeholder=\"sm — 32px\" />\n      <Combobox size=\"md\" options={cities} aria-label=\"Shahar\" placeholder=\"md — 40px\" />\n      <Combobox size=\"lg\" options={cities} aria-label=\"Shahar\" placeholder=\"lg — 48px\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/combobox/states": { component: Demo52, file: "archive/v0.1/combobox/states.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro'].map((label) => ({\n  value: label.toLowerCase(),\n  label,\n}));\n\nexport default function ComboboxStates() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <Field label=\"O'chirilgan\" disabled>\n        <Combobox options={cities} defaultValue=\"toshkent\" />\n      </Field>\n      <Field label=\"Shahar\" error=\"Shaharni tanlang\" required>\n        <Combobox options={cities} placeholder=\"Shahar tanlang\" />\n      </Field>\n      <Field label=\"Yuklanmoqda\">\n        <Combobox options={[]} loading placeholder=\"Ochib ko'ring\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/combobox/uzbek-search": { component: Demo53, file: "archive/v0.1/combobox/uzbek-search.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\n\nconst districts = [\n  'Gʻuzor',\n  \"G'allaorol\",\n  'Oʻrta Chirchiq',\n  \"Qo'shrabot\",\n  'Shahrisabz',\n  'Chilonzor',\n  'Yunusobod',\n  \"Mirzo Ulug'bek\",\n  'Toshkent tumani',\n].map((label, i) => ({ value: String(i), label }));\n\nexport default function ComboboxUzbekSearch() {\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field label=\"Tuman\">\n        <Combobox options={districts} placeholder=\"Tumanni tanlang\" />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Yozib ko'ring: <span className=\"font-medium text-text\">guzor</span>,{' '}\n        <span className=\"font-medium text-text\">g‘allaorol</span>,{' '}\n        <span className=\"font-medium text-text\">Чилонзор</span>,{' '}\n        <span className=\"font-medium text-text\">ulugbek</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/command-palette/basic": { component: Demo54, file: "archive/v0.1/command-palette/basic.tsx", source: "'use client';\n\nimport { Button, CommandPalette, Kbd, toast, type CommandPaletteGroup } from '@akhatmirzo/ui';\nimport {\n  ChartColumn,\n  FileSpreadsheet,\n  House,\n  Package,\n  Plus,\n  Search,\n  Settings,\n  UserPlus,\n  Users,\n} from 'lucide-react';\n\nconst run = (label: string) => () => toast(`\"${label}\" bajarildi`);\n\nconst groups: CommandPaletteGroup[] = [\n  {\n    heading: 'Sahifalar',\n    items: [\n      { label: 'Bosh sahifa', icon: <House />, onSelect: run('Bosh sahifa') },\n      {\n        label: 'Buyurtmalar',\n        icon: <Package />,\n        keywords: ['zakaz', 'savdo'],\n        onSelect: run('Buyurtmalar'),\n      },\n      { label: 'Mijozlar', icon: <Users />, onSelect: run('Mijozlar') },\n      {\n        label: 'Hisobotlar',\n        icon: <ChartColumn />,\n        keywords: ['statistika'],\n        onSelect: run('Hisobotlar'),\n      },\n      {\n        label: 'Sozlamalar',\n        icon: <Settings />,\n        shortcut: ['mod', ','],\n        onSelect: run('Sozlamalar'),\n      },\n    ],\n  },\n  {\n    heading: 'Amallar',\n    items: [\n      {\n        label: 'Yangi buyurtma',\n        icon: <Plus />,\n        shortcut: ['mod', 'N'],\n        onSelect: run('Yangi buyurtma'),\n      },\n      { label: \"Mijoz qo'shish\", icon: <UserPlus />, onSelect: run(\"Mijoz qo'shish\") },\n      {\n        label: 'Eksport (Excel)',\n        icon: <FileSpreadsheet />,\n        keywords: ['xlsx'],\n        onSelect: run('Eksport'),\n      },\n    ],\n  },\n];\n\nexport default function CommandPaletteBasic() {\n  return (\n    // Docs saytida Ctrl+K qidiruvga band, shuning uchun bu yerda mod+J\n    <CommandPalette groups={groups} hotkey=\"mod+j\">\n      <Button variant=\"outline\" leftIcon={<Search />} className=\"min-w-64 justify-start\">\n        <span className=\"flex-1 text-left text-text-muted\">Qidirish...</span>\n        <Kbd keys={['mod', 'J']} />\n      </Button>\n    </CommandPalette>\n  );\n}\n" },
  "archive/v0.1/command-palette/pages": { component: Demo55, file: "archive/v0.1/command-palette/pages.tsx", source: "'use client';\n\nimport { Button, CommandPalette, toast, type CommandPaletteGroup } from '@akhatmirzo/ui';\nimport { Globe, Moon, Sun, User } from 'lucide-react';\n\nconst customers = ['Aziza Karimova', 'Bobur Toshmatov', \"G'ayrat Usmonov\", 'Malika Yusupova'];\n\nconst groups: CommandPaletteGroup[] = [\n  {\n    heading: 'Sozlamalar',\n    items: [\n      {\n        label: 'Mavzuni almashtirish',\n        icon: <Moon />,\n        keywords: ['tungi rejim', 'dark'],\n        page: {\n          title: 'Mavzu',\n          placeholder: 'Mavzu tanlang...',\n          groups: [\n            {\n              heading: 'Mavzu',\n              items: [\n                {\n                  id: 'theme-light',\n                  label: \"Yorug'\",\n                  icon: <Sun />,\n                  onSelect: () => toast(\"Yorug' mavzu\"),\n                },\n                {\n                  id: 'theme-dark',\n                  label: \"Qorong'i\",\n                  icon: <Moon />,\n                  onSelect: () => toast(\"Qorong'i mavzu\"),\n                },\n              ],\n            },\n          ],\n        },\n      },\n      {\n        label: 'Tilni almashtirish',\n        icon: <Globe />,\n        page: {\n          title: 'Til',\n          groups: [\n            {\n              heading: 'Til',\n              items: [\n                { id: 'lang-uz', label: \"O'zbekcha\", onSelect: () => toast(\"O'zbekcha\") },\n                { id: 'lang-en', label: 'English', disabled: true },\n              ],\n            },\n          ],\n        },\n      },\n    ],\n  },\n  {\n    heading: 'Mijozlar',\n    searchOnly: true,\n    items: customers.map((name) => ({ label: name, icon: <User />, onSelect: () => toast(name) })),\n  },\n];\n\nexport default function CommandPalettePages() {\n  return (\n    <CommandPalette groups={groups} hotkey={false} recent={false}>\n      <Button variant=\"soft\">Sozlamalarni ochish</Button>\n    </CommandPalette>\n  );\n}\n" },
  "archive/v0.1/command-palette/server": { component: Demo56, file: "archive/v0.1/command-palette/server.tsx", source: "'use client';\n\nimport { Button, CommandPalette, toast, type CommandPaletteItem } from '@akhatmirzo/ui';\nimport { Plus, User } from 'lucide-react';\n\nconst customers = [\n  ['Akmal Ergashev', '+998 90 123 45 67'],\n  ['Akbar Sobirov', '+998 93 555 12 34'],\n  ['Kamola Akramova', '+998 97 700 00 11'],\n  ['Nodira Ahmedova', '+998 91 444 22 33'],\n] as const;\n\n/** Server qidiruvini taqlid qiladi (700ms); yangi so'rov eskisini bekor qiladi */\nfunction searchCustomers(query: string, { signal }: { signal: AbortSignal }) {\n  return new Promise<CommandPaletteItem[]>((resolve, reject) => {\n    const timer = setTimeout(() => {\n      const q = query.toLowerCase();\n      resolve(\n        customers\n          .filter(([name]) => name.toLowerCase().includes(q))\n          .map(([name, phone]) => ({\n            id: `customer-${name}`,\n            label: name,\n            description: phone,\n            icon: <User />,\n            onSelect: () => toast(name),\n          })),\n      );\n    }, 700);\n    signal.addEventListener('abort', () => {\n      clearTimeout(timer);\n      reject(new DOMException('Bekor qilindi', 'AbortError'));\n    });\n  });\n}\n\nexport default function CommandPaletteServer() {\n  return (\n    <CommandPalette\n      hotkey={false}\n      recentKey=\"docs:command-palette:server\"\n      placeholder=\"Mijoz yoki buyruq qidirish...\"\n      onSearch={searchCustomers}\n      labels={{ results: 'Mijozlar (serverdan)' }}\n      groups={[\n        {\n          heading: 'Amallar',\n          items: [\n            { label: \"Mijoz qo'shish\", icon: <Plus />, onSelect: () => toast(\"Mijoz qo'shish\") },\n          ],\n        },\n      ]}\n    >\n      <Button variant=\"outline\">Mijoz qidirish</Button>\n    </CommandPalette>\n  );\n}\n" },
  "archive/v0.1/core/api-errors": { component: Demo57, file: "archive/v0.1/core/api-errors.tsx", source: "'use client';\n\nimport { createApiClient, isApiError, type FetchLike } from '@akhatmirzo/core';\nimport { Badge, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\n// Haqiqiy server o'rniga: `/status/404` → 404 javob, `/sekin` → hech qachon javob bermaydi\nconst fakeFetch: FetchLike = (url, init) =>\n  new Promise((resolve, reject) => {\n    if (url.endsWith('/sekin')) {\n      init.signal?.addEventListener('abort', () => reject(new Error('aborted')));\n      return;\n    }\n    const status = Number(url.split('/').pop());\n    resolve({ ok: status < 400, status, headers: { get: () => null }, text: async () => '' });\n  });\n\nconst api = createApiClient({ baseUrl: '/api', timeout: 1500, fetch: fakeFetch });\n\nexport default function CoreApiErrors() {\n  const [result, setResult] = useState<{ code: string; message: string } | null>(null);\n\n  const request = async (path: string) => {\n    try {\n      await api.get(path);\n      setResult({ code: 'OK', message: 'Muvaffaqiyatli' });\n    } catch (error) {\n      if (isApiError(error)) setResult({ code: error.code, message: error.message });\n    }\n  };\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div className=\"flex flex-wrap gap-2\">\n        {['401', '403', '404', '422', '500'].map((s) => (\n          <Button key={s} size=\"sm\" variant=\"outline\" onClick={() => request(`/status/${s}`)}>\n            {s}\n          </Button>\n        ))}\n        <Button size=\"sm\" variant=\"outline\" onClick={() => request('/sekin')}>\n          Timeout\n        </Button>\n      </div>\n      {result && (\n        <div className=\"flex items-center gap-2 text-sm\">\n          <Badge color={result.code === 'OK' ? 'success' : 'danger'}>{result.code}</Badge>\n          <span className=\"text-text\">{result.message}</span>\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/card-validate": { component: Demo58, file: "archive/v0.1/core/card-validate.tsx", source: "'use client';\n\nimport { detectCardBrand, formatCardNumber, isValidCardNumber } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst BRANDS = { uzcard: 'Uzcard', humo: 'Humo', visa: 'Visa', mastercard: 'Mastercard' };\n\nexport default function CoreCardValidate() {\n  const [digits, setDigits] = useState('8600');\n  const brand = detectCardBrand(digits);\n  const complete = digits.length === 16;\n  const valid = isValidCardNumber(digits);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field\n        label=\"Karta raqami\"\n        description=\"To'g'ri namuna: 4111 1111 1111 1111\"\n        error={complete && !valid ? \"Karta raqami noto'g'ri\" : undefined}\n      >\n        <Input\n          value={formatCardNumber(digits)}\n          onChange={(e) => setDigits(e.target.value.replace(/\\D/g, '').slice(0, 16))}\n          inputMode=\"numeric\"\n          placeholder=\"0000 0000 0000 0000\"\n          suffix={brand ? BRANDS[brand] : undefined}\n        />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={brand ? 'info' : 'neutral'}>{brand ? BRANDS[brand] : \"Brend noma'lum\"}</Badge>\n        <Badge color={!complete ? 'neutral' : valid ? 'success' : 'danger'} dot>\n          {!complete ? `${digits.length}/16` : valid ? \"Luhn: to'g'ri\" : 'Luhn: xato'}\n        </Badge>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/date": { component: Demo59, file: "archive/v0.1/core/date.tsx", source: "'use client';\n\nimport { formatDate, parseDate } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst PATTERNS = ['dd.MM.yyyy', 'd MMMM yyyy, EEEE', 'd MMM, EEE', 'EEEE, d MMMM [soat] HH:mm'];\nconst DATE = new Date(2026, 9, 21, 14, 30);\n\nexport default function CoreDate() {\n  const [pattern, setPattern] = useState('d MMMM yyyy, EEEE');\n  const [input, setInput] = useState('31.02.2026');\n  const parsed = parseDate(input);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field\n        label=\"Shablon\"\n        description={`formatDate(sana, shablon) → ${formatDate(DATE, pattern)}`}\n      >\n        <Input value={pattern} onChange={(e) => setPattern(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        {PATTERNS.map((p) => (\n          <button key={p} type=\"button\" onClick={() => setPattern(p)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{p}</Badge>\n          </button>\n        ))}\n      </div>\n      <Field\n        label=\"parseDate (dd.MM.yyyy)\"\n        description={parsed ? formatDate(parsed, 'EEEE, d MMMM yyyy') : \"null — bunday sana yo'q\"}\n      >\n        <Input value={input} onChange={(e) => setInput(e.target.value)} invalid={!parsed} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/debounce-throttle": { component: Demo60, file: "archive/v0.1/core/debounce-throttle.tsx", source: "'use client';\n\nimport { debounce, throttle } from '@akhatmirzo/core';\nimport { Button } from '@akhatmirzo/ui';\nimport { useEffect, useMemo, useState } from 'react';\n\ntype Counts = { raw: number; throttled: number; debounced: number };\nconst ZERO: Counts = { raw: 0, throttled: 0, debounced: 0 };\nconst inc = (key: keyof Counts) => (c: Counts) => ({ ...c, [key]: c[key] + 1 });\n\nexport default function CoreDebounceThrottle() {\n  const [counts, setCounts] = useState(ZERO);\n\n  const onDebounced = useMemo(() => debounce(() => setCounts(inc('debounced')), 400), []);\n  const onThrottled = useMemo(() => throttle(() => setCounts(inc('throttled')), 400), []);\n\n  useEffect(\n    () => () => {\n      onDebounced.cancel();\n      onThrottled.cancel();\n    },\n    [onDebounced, onThrottled],\n  );\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div\n        onPointerMove={() => {\n          setCounts(inc('raw'));\n          onDebounced();\n          onThrottled();\n        }}\n        className=\"flex h-32 touch-none items-center justify-center rounded-xl border border-dashed border-border-strong bg-surface-muted text-sm text-text-muted\"\n      >\n        Sichqoncha yoki barmoqni shu yerda yurgizing\n      </div>\n      <dl className=\"grid grid-cols-3 gap-2 text-center text-sm\">\n        {(['raw', 'throttled', 'debounced'] as const).map((key) => (\n          <div key={key} className=\"rounded-lg border border-border bg-surface p-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{key}</dt>\n            <dd className=\"text-xl font-semibold text-text tabular-nums\">{counts[key]}</dd>\n          </div>\n        ))}\n      </dl>\n      <Button size=\"sm\" variant=\"ghost\" onClick={() => setCounts(ZERO)}>\n        Nolga qaytarish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/fuzzy": { component: Demo61, file: "archive/v0.1/core/fuzzy.tsx", source: "'use client';\n\nimport { fuzzyMatch, splitByRanges } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst COMMANDS = [\n  'Yangi buyurtma',\n  \"Buyurtmalar ro'yxati\",\n  \"Mijoz qo'shish\",\n  'Hisobotlar',\n  'Sozlamalar',\n  'Profilni tahrirlash',\n  'Mavzuni almashtirish',\n];\n\nexport default function CoreFuzzy() {\n  const [query, setQuery] = useState('ybu');\n  const results = COMMANDS.flatMap((label) => {\n    const result = fuzzyMatch(label, query);\n    return result ? [{ label, ...result }] : [];\n  }).sort((a, b) => b.score - a.score);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Field label=\"Buyruq\" description=\"Harflar tartibi muhim: mq, hsb, prof\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <ul className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {results.map(({ label, ranges, score }) => (\n          <li key={label} className=\"flex items-center justify-between gap-3 px-3 py-2\">\n            <span>\n              {splitByRanges(label, ranges).map((part, i) =>\n                part.match ? (\n                  <strong key={i} className=\"font-semibold text-primary-soft-foreground\">\n                    {part.text}\n                  </strong>\n                ) : (\n                  <span key={i}>{part.text}</span>\n                ),\n              )}\n            </span>\n            <span className=\"font-mono text-xs text-text-muted\">{score}</span>\n          </li>\n        ))}\n        {results.length === 0 && <li className=\"px-3 py-2 text-text-muted\">Mos buyruq yo'q</li>}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/money": { component: Demo62, file: "archive/v0.1/core/money.tsx", source: "'use client';\n\nimport { formatMoney, formatNumber, type MoneyCurrency } from '@akhatmirzo/core';\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CURRENCIES: MoneyCurrency[] = [\"so'm\", 'UZS', false];\n\nexport default function CoreMoney() {\n  const [raw, setRaw] = useState('1250000.5');\n  const [currency, setCurrency] = useState<MoneyCurrency>(\"so'm\");\n  const n = Number(raw.replace(',', '.').replace(/\\s/g, ''));\n\n  const rows = [\n    { call: 'formatNumber(n)', value: formatNumber(n) },\n    { call: 'formatNumber(n, { decimals: 2 })', value: formatNumber(n, { decimals: 2 }) },\n    { call: 'formatMoney(n, { currency })', value: formatMoney(n, { currency }) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Son\">\n        <Input value={raw} onChange={(e) => setRaw(e.target.value)} inputMode=\"decimal\" />\n      </Field>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        {CURRENCIES.map((c) => (\n          <Button\n            key={String(c)}\n            size=\"sm\"\n            variant={currency === c ? 'primary' : 'outline'}\n            onClick={() => setCurrency(c)}\n          >\n            {c === false ? 'false' : c}\n          </Button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.call} className=\"flex flex-wrap justify-between gap-x-4 gap-y-1 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.call}</dt>\n            <dd className=\"font-mono font-medium text-text tabular-nums\">{row.value || \"''\"}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/password": { component: Demo63, file: "archive/v0.1/core/password.tsx", source: "'use client';\n\nimport { passwordStrength } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst BAR = ['bg-danger', 'bg-danger', 'bg-warning', 'bg-success', 'bg-success'];\nconst COLOR = ['danger', 'danger', 'warning', 'success', 'success'] as const;\nconst CHECKS = {\n  length: 'Kamida 8 belgi',\n  lower: 'Kichik harf',\n  upper: 'Katta harf',\n  digit: 'Raqam',\n  symbol: 'Belgi (!@#…)',\n};\n\nexport default function CorePassword() {\n  const [password, setPassword] = useState('Parol123');\n  const { score, label, checks } = passwordStrength(password);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Parol\">\n        <Input type=\"password\" value={password} onChange={(e) => setPassword(e.target.value)} />\n      </Field>\n      <div className=\"flex gap-1\" aria-hidden>\n        {[1, 2, 3, 4].map((i) => (\n          <span\n            key={i}\n            className={`h-1.5 flex-1 rounded-full ${password && i <= Math.max(score, 1) ? BAR[score] : 'bg-surface-muted'}`}\n          />\n        ))}\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Badge color={COLOR[score]}>{label}</Badge>\n        <span className=\"text-xs text-text-muted\">score: {score}/4</span>\n      </div>\n      <ul className=\"flex flex-col gap-1 text-sm\">\n        {(Object.keys(CHECKS) as (keyof typeof CHECKS)[]).map((key) => (\n          <li key={key} className={checks[key] ? 'text-text' : 'text-text-muted'}>\n            {checks[key] ? '✓' : '○'} {CHECKS[key]}\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/phone-card": { component: Demo64, file: "archive/v0.1/core/phone-card.tsx", source: "'use client';\n\nimport { formatCardNumber, formatPhone } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst digitsOf = (s: string) => s.replace(/\\D/g, '');\n\nexport default function CorePhoneCard() {\n  const [phone, setPhone] = useState('90123');\n  const [card, setCard] = useState('8600 1234');\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" description={`formatPhone: ${formatPhone(phone) || '—'}`}>\n        <Input\n          prefix=\"+998\"\n          value={formatPhone(phone, 'national')}\n          onChange={(e) => setPhone(digitsOf(e.target.value).slice(0, 9))}\n          inputMode=\"tel\"\n          placeholder=\"(90) 123-45-67\"\n        />\n      </Field>\n      <Field label=\"Karta raqami\" description={`Toza qiymat: ${digitsOf(card) || '—'}`}>\n        <Input\n          value={card}\n          onChange={(e) => setCard(formatCardNumber(digitsOf(e.target.value).slice(0, 16)))}\n          inputMode=\"numeric\"\n          placeholder=\"0000 0000 0000 0000\"\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/phone-validate": { component: Demo65, file: "archive/v0.1/core/phone-validate.tsx", source: "'use client';\n\nimport { isValidEmail, parsePhone } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CorePhoneValidate() {\n  const [phone, setPhone] = useState('+998 90 123-45-67');\n  const [email, setEmail] = useState('sarvar@mail');\n  const parsed = parsePhone(phone);\n  const code = parsed.digits.slice(0, 2);\n  const phoneError =\n    code.length === 2 && !parsed.operator ? `\"${code}\" — bunday operator kodi yo'q` : undefined;\n  const emailValid = isValidEmail(email);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" error={phoneError} description={`digits: ${parsed.digits || '—'}`}>\n        <Input value={phone} onChange={(e) => setPhone(e.target.value)} inputMode=\"tel\" />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={parsed.valid ? 'success' : 'neutral'} dot>\n          {parsed.valid ? \"To'g'ri raqam\" : \"To'liq emas\"}\n        </Badge>\n        {parsed.operator && <Badge color=\"info\">Operator: {parsed.operator}</Badge>}\n      </div>\n      <Field\n        label=\"Email\"\n        error={email.trim() && !emailValid ? \"Email manzil noto'g'ri\" : undefined}\n      >\n        <Input type=\"email\" value={email} onChange={(e) => setEmail(e.target.value)} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/search": { component: Demo66, file: "archive/v0.1/core/search.tsx", source: "'use client';\n\nimport { searchMatch, splitByRanges } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CITIES = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  \"Farg'ona\",\n  'Qo‘qon',\n  'Shahrisabz',\n  'Chirchiq',\n  'Ғузор',\n  'Ўрта Чирчиқ',\n  'Шаҳрихон',\n];\n\nexport default function CoreSearch() {\n  const [query, setQuery] = useState('шаҳ');\n  const results = CITIES.map((city) => ({ city, ...searchMatch(city, query) })).filter(\n    (r) => r.match,\n  );\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Field label=\"Shahar qidirish\" description=\"Sinab ko'ring: chir, ғуз, fargona, qo'qon\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <ul className=\"flex flex-wrap gap-2\">\n        {results.map(({ city, ranges }) => (\n          <li key={city} className=\"rounded-lg border border-border bg-surface px-3 py-1.5 text-sm\">\n            {splitByRanges(city, ranges).map((part, i) =>\n              part.match ? (\n                <mark key={i} className=\"rounded-sm bg-primary-soft text-primary-soft-foreground\">\n                  {part.text}\n                </mark>\n              ) : (\n                <span key={i}>{part.text}</span>\n              ),\n            )}\n          </li>\n        ))}\n        {results.length === 0 && <li className=\"text-sm text-text-muted\">Hech narsa topilmadi</li>}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/storage": { component: Demo67, file: "archive/v0.1/core/storage.tsx", source: "'use client';\n\nimport { createStorage } from '@akhatmirzo/core';\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst store = createStorage({ prefix: 'docs-demo:' });\n\nexport default function CoreStorage() {\n  const [value, setValue] = useState('Sarvar');\n  const [result, setResult] = useState('—');\n\n  const save = (ttl?: number) => {\n    const ok = store.set('ism', value, { ttl });\n    setResult(\n      ok ? `Saqlandi${ttl ? ` (${ttl / 1000} soniya)` : ' (muddatsiz)'}` : \"Saqlab bo'lmadi\",\n    );\n  };\n\n  const read = () => {\n    const saved = store.get<string>('ism');\n    setResult(saved === null ? \"null — yo'q yoki muddati o'tgan\" : JSON.stringify(saved));\n  };\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Qiymat\" description=\"Kalit: docs-demo:ism\">\n        <Input value={value} onChange={(e) => setValue(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Button variant=\"primary\" onClick={() => save(5000)}>\n          5 soniyaga saqlash\n        </Button>\n        <Button variant=\"outline\" onClick={() => save()}>\n          Muddatsiz\n        </Button>\n        <Button variant=\"ghost\" onClick={read}>\n          O'qish\n        </Button>\n      </div>\n      <p className=\"text-sm text-text-muted\">\n        Natija: <code className=\"font-mono text-text\">{result}</code>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/time-ago": { component: Demo68, file: "archive/v0.1/core/time-ago.tsx", source: "'use client';\n\nimport { timeAgo } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst MINUTE = 60_000;\nconst NOW = new Date(2026, 9, 21, 12, 0);\nconst OFFSETS = [5, 180, 1440, 4320, 20160, 136800, -120, -1440];\n\nexport default function CoreTimeAgo() {\n  const [minutes, setMinutes] = useState('90');\n  const custom = new Date(NOW.getTime() - Number(minutes || 0) * MINUTE);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Necha daqiqa oldin\" description={`timeAgo → ${timeAgo(custom, NOW)}`}>\n        <Input\n          value={minutes}\n          onChange={(e) => setMinutes(e.target.value.replace(/[^\\d-]/g, ''))}\n          inputMode=\"numeric\"\n          suffix=\"daqiqa\"\n        />\n      </Field>\n      <ul className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {OFFSETS.map((m) => (\n          <li key={m} className=\"flex justify-between gap-4 px-3 py-2\">\n            <span className=\"font-mono text-xs text-text-muted\">{m} daqiqa</span>\n            <span className=\"text-text\">{timeAgo(NOW.getTime() - m * MINUTE, NOW)}</span>\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/translit": { component: Demo69, file: "archive/v0.1/core/translit.tsx", source: "'use client';\n\nimport { cyrToLat, latToCyr, normalizeUz } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst SAMPLES = ['Ғузор тумани', \"O'zbekiston\", 'Gʻuzor', 'ер, поезд, маъно', 'SHAHAR'];\n\nexport default function CoreTranslit() {\n  const [text, setText] = useState('Ғузор тумани');\n\n  const rows = [\n    { name: 'cyrToLat', value: cyrToLat(text) },\n    { name: 'latToCyr', value: latToCyr(text) },\n    { name: 'normalizeUz', value: normalizeUz(text) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Matn\">\n        <Input value={text} onChange={(e) => setText(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        {SAMPLES.map((s) => (\n          <button key={s} type=\"button\" onClick={() => setText(s)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{s}</Badge>\n          </button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.name} className=\"flex items-center justify-between gap-4 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.name}</dt>\n            <dd className=\"font-mono break-all text-text\">{row.value || '—'}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.1/core/truncate": { component: Demo70, file: "archive/v0.1/core/truncate.tsx", source: "'use client';\n\nimport { slugify, truncate, truncateMiddle } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst FILE = 'shartnoma-mchj-akhatmirzo-imzolangan.docx';\n\nexport default function CoreTruncate() {\n  const [title, setTitle] = useState(\"Farg'ona viloyati — 2026\");\n  const [max, setMax] = useState(24);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Sarlavha\" description={`slugify: ${slugify(title) || '—'}`}>\n        <Input value={title} onChange={(e) => setTitle(e.target.value)} />\n      </Field>\n      <label className=\"flex flex-col gap-2 text-sm font-medium text-text\">\n        Maksimal uzunlik: {max}\n        <input\n          type=\"range\"\n          min={6}\n          max={44}\n          value={max}\n          onChange={(e) => setMax(Number(e.target.value))}\n          className=\"w-full accent-primary\"\n        />\n      </label>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        <div className=\"flex flex-col gap-1 px-3 py-2\">\n          <dt className=\"font-mono text-xs text-text-muted\">truncateMiddle</dt>\n          <dd className=\"font-mono text-text\">{truncateMiddle(FILE, max)}</dd>\n        </div>\n        <div className=\"flex flex-col gap-1 px-3 py-2\">\n          <dt className=\"font-mono text-xs text-text-muted\">truncate</dt>\n          <dd className=\"font-mono text-text\">{truncate(FILE, max)}</dd>\n        </div>\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.1/data-table/basic": { component: Demo71, file: "archive/v0.1/data-table/basic.tsx", source: "'use client';\n\nimport { formatDate, formatMoney } from '@akhatmirzo/core';\nimport { Badge, Button, DataTable, toast, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Plus } from 'lucide-react';\n\ntype Status = 'paid' | 'pending' | 'shipped' | 'cancelled';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  date: Date;\n  status: Status;\n  total: number;\n}\n\nconst STATUS = {\n  paid: { label: \"To'langan\", color: 'success' },\n  pending: { label: 'Kutilmoqda', color: 'warning' },\n  shipped: { label: \"Yo'lda\", color: 'info' },\n  cancelled: { label: 'Bekor qilingan', color: 'danger' },\n} as const;\n\nconst NAMES = [\n  'Jasur Karimov',\n  'Malika Rahimova',\n  \"Bekzod G'aniyev\",\n  'Nodira Saidova',\n  'Aziz Normatov',\n];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\", 'Xorazm'];\nconst STATUSES = Object.keys(STATUS) as Status[];\n\nconst orders: Order[] = Array.from({ length: 48 }, (_, i) => ({\n  id: 1042 + i,\n  customer: NAMES[(i * 3) % NAMES.length]!,\n  region: REGIONS[(i * 7) % REGIONS.length]!,\n  date: new Date(2026, 9, 21 - (i % 30)),\n  status: STATUSES[(i * 5 + (i >> 2)) % 4]!,\n  total: 85_000 + ((i * 377_311) % 4_800_000),\n}));\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88, sortable: true, cell: (o) => `#${o.id}` },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  { key: 'region', header: 'Viloyat', sortable: true, filter: 'select' },\n  { key: 'date', header: 'Sana', sortable: true, cell: (o) => formatDate(o.date) },\n  {\n    key: 'status',\n    header: 'Holat',\n    filter: 'multiselect',\n    filterOptions: STATUSES.map((s) => ({ value: s, label: STATUS[s].label })),\n    searchValue: (o) => STATUS[o.status].label,\n    cell: (o) => (\n      <Badge dot color={STATUS[o.status].color}>\n        {STATUS[o.status].label}\n      </Badge>\n    ),\n  },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableBasic() {\n  return (\n    <DataTable\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      searchable\n      pagination={{ pageSize: 5, pageSizeOptions: [5, 10, 25] }}\n      className=\"w-full\"\n      toolbar={\n        <Button variant=\"primary\" leftIcon={<Plus />} onClick={() => toast('Yangi buyurtma')}>\n          Qo'shish\n        </Button>\n      }\n    />\n  );\n}\n" },
  "archive/v0.1/data-table/cards": { component: Demo72, file: "archive/v0.1/data-table/cards.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, toast, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  total: number;\n}\n\nconst orders: Order[] = [\n  { id: 1042, customer: 'Jasur Karimov', region: 'Toshkent', total: 1_250_000 },\n  { id: 1043, customer: 'Malika Rahimova', region: 'Samarqand', total: 480_000 },\n  { id: 1044, customer: 'Aziz Normatov', region: \"Farg'ona\", total: 2_730_000 },\n];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№' },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'region', header: 'Viloyat' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nexport default function DataTableCards() {\n  return (\n    <DataTable\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      mobileView=\"cards\"\n      selectable\n      onRowClick={(o) => toast(`Buyurtma #${o.id}`)}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.1/data-table/density": { component: Demo73, file: "archive/v0.1/data-table/density.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Employee {\n  id: number;\n  name: string;\n  position: string;\n  department: string;\n  phone: string;\n  city: string;\n  salary: number;\n}\n\nconst employees: Employee[] = [\n  {\n    id: 1,\n    name: 'Sarvar Abduxoliqov',\n    position: 'Frontend dasturchi',\n    department: 'IT',\n    phone: '+998 90 123 45 67',\n    city: 'Toshkent',\n    salary: 14_500_000,\n  },\n  {\n    id: 2,\n    name: \"Gulnora O'rinova\",\n    position: 'Buxgalter',\n    department: 'Moliya',\n    phone: '+998 93 555 12 34',\n    city: 'Samarqand',\n    salary: 9_800_000,\n  },\n  {\n    id: 3,\n    name: 'Javohir Ismoilov',\n    position: 'Dizayner',\n    department: 'Marketing',\n    phone: '+998 97 700 00 11',\n    city: 'Buxoro',\n    salary: 11_200_000,\n  },\n];\n\nconst columns: DataTableColumn<Employee>[] = [\n  { key: 'name', header: 'Xodim', width: 200, hideable: false },\n  { key: 'position', header: 'Lavozim' },\n  { key: 'department', header: \"Bo'lim\" },\n  { key: 'phone', header: 'Telefon', className: 'tabular-nums' },\n  { key: 'city', header: 'Shahar', hidden: true },\n  { key: 'salary', header: 'Maosh', numeric: true, cell: (e) => formatMoney(e.salary) },\n];\n\nexport default function DataTableDensity() {\n  return (\n    <DataTable\n      label=\"Xodimlar\"\n      data={employees}\n      columns={columns}\n      density=\"compact\"\n      stickyFirstColumn\n      selectable\n      tableClassName=\"min-w-[860px]\"\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.1/data-table/filters": { component: Demo74, file: "archive/v0.1/data-table/filters.tsx", source: "'use client';\n\nimport { formatDate, formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Payment {\n  id: number;\n  client: string;\n  method: string;\n  region: string;\n  date: Date;\n  amount: number;\n}\n\nconst METHODS = ['Click', 'Payme', 'Uzcard', 'Naqd'];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Andijon', 'Namangan'];\nconst CLIENTS = ['Dilnoza Yusupova', 'Otabek Qodirov', 'Shahnoza Ergasheva', 'Rustam Xolmatov'];\n\nconst payments: Payment[] = Array.from({ length: 40 }, (_, i) => ({\n  id: 501 + i,\n  client: CLIENTS[(i * 3) % CLIENTS.length]!,\n  method: METHODS[(i * 5) % METHODS.length]!,\n  region: REGIONS[(i + (i >> 2)) % REGIONS.length]!,\n  date: new Date(2026, 9, 25 - i),\n  amount: 50_000 + ((i * 213_457) % 3_000_000),\n}));\n\nconst columns: DataTableColumn<Payment>[] = [\n  { key: 'id', header: '№', width: 72, cell: (p) => `#${p.id}` },\n  { key: 'client', header: 'Mijoz' },\n  { key: 'method', header: \"To'lov turi\", filter: 'select' },\n  { key: 'region', header: 'Viloyat', filter: 'multiselect' },\n  { key: 'date', header: 'Sana', filter: 'date', sortable: true, cell: (p) => formatDate(p.date) },\n  {\n    key: 'amount',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    filter: 'range',\n    cell: (p) => formatMoney(p.amount),\n  },\n];\n\nexport default function DataTableFilters() {\n  return (\n    <DataTable\n      label=\"To'lovlar\"\n      data={payments}\n      columns={columns}\n      searchable\n      pagination={{ pageSize: 5 }}\n      initialState={{ filters: { method: 'Click' } }}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.1/data-table/selection": { component: Demo75, file: "archive/v0.1/data-table/selection.tsx", source: "'use client';\n\nimport {\n  DataTable,\n  DropdownMenu,\n  IconButton,\n  toast,\n  type DataTableColumn,\n  Button,\n} from '@akhatmirzo/ui';\nimport { Download, Ellipsis, Eye, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\ninterface Product {\n  id: string;\n  name: string;\n  sku: string;\n  stock: number;\n}\n\nconst initial: Product[] = [\n  { id: 'p1', name: \"Paxta ko'ylak\", sku: 'KY-001', stock: 42 },\n  { id: 'p2', name: \"Atlas ro'mol\", sku: 'RM-014', stock: 8 },\n  { id: 'p3', name: 'Choynak (1.5 l)', sku: 'CH-203', stock: 0 },\n  { id: 'p4', name: \"Do'ppi\", sku: 'DP-077', stock: 120 },\n  { id: 'p5', name: 'Sopol lagan', sku: 'LG-310', stock: 15 },\n];\n\nconst columns: DataTableColumn<Product>[] = [\n  { key: 'name', header: 'Mahsulot', sortable: true },\n  { key: 'sku', header: 'Artikul' },\n  { key: 'stock', header: 'Qoldiq', numeric: true, sortable: true },\n];\n\nexport default function DataTableSelection() {\n  const [products, setProducts] = useState(initial);\n  const remove = (ids: string[]) => setProducts((prev) => prev.filter((p) => !ids.includes(p.id)));\n\n  return (\n    <DataTable\n      label=\"Mahsulotlar\"\n      data={products}\n      columns={columns}\n      selectable\n      className=\"w-full\"\n      onRowClick={(p) => toast(`${p.name} ochildi`)}\n      bulkActions={(rows, clear) => (\n        <>\n          <Button\n            variant=\"outline\"\n            size=\"sm\"\n            leftIcon={<Download />}\n            onClick={() => toast(`${rows.length} ta eksport qilindi`)}\n          >\n            Eksport\n          </Button>\n          <Button\n            variant=\"danger\"\n            size=\"sm\"\n            leftIcon={<Trash2 />}\n            onClick={() => {\n              remove(rows.map((r) => r.id));\n              clear();\n            }}\n          >\n            O'chirish\n          </Button>\n        </>\n      )}\n      rowActions={(p) => (\n        <DropdownMenu>\n          <DropdownMenu.Trigger asChild>\n            <IconButton variant=\"ghost\" size=\"sm\" aria-label={`${p.name}: amallar`}>\n              <Ellipsis />\n            </IconButton>\n          </DropdownMenu.Trigger>\n          <DropdownMenu.Content align=\"end\">\n            <DropdownMenu.Item icon={<Eye />} onSelect={() => toast(p.name)}>\n              Ko'rish\n            </DropdownMenu.Item>\n            <DropdownMenu.Item variant=\"danger\" icon={<Trash2 />} onSelect={() => remove([p.id])}>\n              O'chirish\n            </DropdownMenu.Item>\n          </DropdownMenu.Content>\n        </DropdownMenu>\n      )}\n    />\n  );\n}\n" },
  "archive/v0.1/data-table/server": { component: Demo76, file: "archive/v0.1/data-table/server.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn, type DataTableState } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\ninterface Page {\n  rows: Order[];\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\nconst DB: Order[] = Array.from({ length: 137 }, (_, i) => ({\n  id: 2001 + i,\n  customer: NAMES[i % NAMES.length]!,\n  total: 90_000 + ((i * 271_828) % 3_500_000),\n}));\n\n/** \"Server\": qidiradi, saralaydi, sahifalaydi. Haqiqiy loyihada — fetch('/api/orders?...') */\nfunction fetchOrders({ search, sorting, pagination }: DataTableState): Promise<Page> {\n  let rows = DB.filter((o) => o.customer.toLowerCase().includes(search.toLowerCase()));\n  const sort = sorting[0];\n  if (sort) {\n    const key = sort.id as keyof Order;\n    rows = [...rows].sort((a, b) => (a[key] > b[key] ? 1 : -1) * (sort.desc ? -1 : 1));\n  }\n  const start = pagination.pageIndex * pagination.pageSize;\n  const page = { rows: rows.slice(start, start + pagination.pageSize), total: rows.length };\n  return new Promise((resolve) => setTimeout(() => resolve(page), 600));\n}\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88, sortable: true },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableServer() {\n  const [query, setQuery] = useState<DataTableState>({\n    sorting: [],\n    search: '',\n    filters: {},\n    pagination: { pageIndex: 0, pageSize: 10 },\n  });\n  const [result, setResult] = useState<Page>({ rows: [], total: 0 });\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    let active = true;\n    fetchOrders(query).then((page) => {\n      if (!active) return;\n      setResult(page);\n      setLoading(false);\n    });\n    return () => {\n      active = false;\n    };\n  }, [query]);\n\n  return (\n    <DataTable\n      label=\"Server buyurtmalari\"\n      data={result.rows}\n      rowCount={result.total}\n      columns={columns}\n      manual\n      searchable\n      pagination={{ pageSize: 10 }}\n      loading={loading}\n      onStateChange={(state) => {\n        setLoading(true);\n        setQuery(state);\n      }}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.1/data-table/states": { component: Demo77, file: "archive/v0.1/data-table/states.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { Button, DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\nimport { useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\nconst orders: Order[] = [\n  { id: 1042, customer: 'Jasur Karimov', total: 1_250_000 },\n  { id: 1043, customer: 'Malika Rahimova', total: 480_000 },\n  { id: 1044, customer: 'Aziz Normatov', total: 2_730_000 },\n];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88 },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nconst STATES = {\n  data: \"Ma'lumot\",\n  first: 'Birinchi yuklanish',\n  refetch: 'Qayta yuklanish',\n  empty: \"Bo'sh\",\n  error: 'Xato',\n} as const;\n\ntype State = keyof typeof STATES;\n\nexport default function DataTableStates() {\n  const [state, setState] = useState<State>('first');\n\n  return (\n    <div className=\"flex w-full flex-col gap-4\">\n      <div className=\"flex flex-wrap gap-2\">\n        {(Object.keys(STATES) as State[]).map((s) => (\n          <Button\n            key={s}\n            size=\"sm\"\n            variant={s === state ? 'primary' : 'outline'}\n            aria-pressed={s === state}\n            onClick={() => setState(s)}\n          >\n            {STATES[s]}\n          </Button>\n        ))}\n      </div>\n      <DataTable\n        label=\"Holatlar\"\n        data={state === 'data' || state === 'refetch' ? orders : []}\n        columns={columns}\n        columnToggle={false}\n        loading={state === 'first' || state === 'refetch'}\n        error={\n          state === 'error' ? 'Server javob bermadi. Internet aloqasini tekshiring.' : undefined\n        }\n        onRetry={() => setState('data')}\n        empty={{\n          icon: <Inbox />,\n          title: \"Hali buyurtmalar yo'q\",\n          description: \"Birinchi buyurtmani qo'shing — u shu yerda ko'rinadi.\",\n          action: (\n            <Button size=\"sm\" variant=\"primary\" leftIcon={<Plus />}>\n              Buyurtma qo'shish\n            </Button>\n          ),\n        }}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.1/data-table/virtual": { component: Demo78, file: "archive/v0.1/data-table/virtual.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { useMemo } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Farhod Tursunov', 'Mohira Nazarova'];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Buxoro', 'Navoiy', 'Xorazm'];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 96, sortable: true },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  { key: 'region', header: 'Viloyat', filter: 'select' },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableVirtual() {\n  const orders = useMemo<Order[]>(\n    () =>\n      Array.from({ length: 10_000 }, (_, i) => ({\n        id: i + 1,\n        customer: NAMES[i % NAMES.length]!,\n        region: REGIONS[(i * 3) % REGIONS.length]!,\n        total: 50_000 + ((i * 377_311) % 4_800_000),\n      })),\n    [],\n  );\n\n  return (\n    <DataTable\n      label=\"10 000 buyurtma\"\n      data={orders}\n      columns={columns}\n      virtual\n      maxHeight={400}\n      density=\"compact\"\n      searchable\n      columnToggle={false}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.1/date-picker/basic": { component: Demo79, file: "archive/v0.1/date-picker/basic.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DatePicker, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst isSunday = (date: Date) => date.getDay() === 0;\n\nexport default function DatePickerBasic() {\n  const [date, setDate] = useState<Date | null>(null);\n\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Field\n        label=\"Yetkazish sanasi\"\n        description={date ? formatDate(date, 'd MMMM yyyy, EEEE') : 'Yakshanba — dam olish kuni'}\n      >\n        <DatePicker\n          value={date}\n          onValueChange={setDate}\n          minDate={new Date()}\n          disabledDates={isSunday}\n          presets\n          clearable\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/date-picker/birthday": { component: Demo80, file: "archive/v0.1/date-picker/birthday.tsx", source: "'use client';\n\nimport { DatePicker, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DatePickerBirthday() {\n  const [birthday, setBirthday] = useState<Date | null>(new Date(1995, 4, 17));\n\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Field label=\"Tug'ilgan sana\" description=\"Sarlavhani bosing — oy va yilni tanlash\">\n        <DatePicker\n          value={birthday}\n          onValueChange={setBirthday}\n          minDate={new Date(1920, 0, 1)}\n          maxDate={new Date()}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/date-picker/calendar-range": { component: Demo81, file: "archive/v0.1/date-picker/calendar-range.tsx", source: "'use client';\n\nimport { Calendar, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);\n\nexport default function CalendarRange() {\n  const today = new Date();\n  const [range, setRange] = useState<DateRangeValue>({\n    from: addDays(today, -3),\n    to: addDays(today, 4),\n  });\n\n  return (\n    <div className=\"flex flex-col items-center gap-2\">\n      <Calendar\n        mode=\"range\"\n        numberOfMonths={2}\n        value={range}\n        onValueChange={setRange}\n        className=\"rounded-xl border border-border bg-surface p-3\"\n      />\n      <span className=\"text-sm text-text-muted\">\n        {range.from && !range.to ? 'Tugash sanasini tanlang' : 'Oraliq tanlandi'}\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.1/date-picker/calendar": { component: Demo82, file: "archive/v0.1/date-picker/calendar.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { Calendar } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CalendarInline() {\n  const [date, setDate] = useState<Date | null>(new Date());\n\n  return (\n    <div className=\"flex flex-col items-center gap-2\">\n      <Calendar\n        value={date}\n        onValueChange={setDate}\n        disabledDates={(d) => d.getDay() === 0}\n        className=\"rounded-xl border border-border bg-surface p-3\"\n      />\n      <span className=\"text-sm text-text-muted\">\n        {date ? formatDate(date, 'd MMMM yyyy, EEEE') : 'Sana tanlanmagan'}\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.1/date-picker/range-presets": { component: Demo83, file: "archive/v0.1/date-picker/range-presets.tsx", source: "'use client';\n\nimport { DateRangePicker, Field, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);\n\nexport default function DateRangePickerPresets() {\n  const [vacation, setVacation] = useState<DateRangeValue | null>(null);\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Ta'til\" description=\"Yakshanbalar yopiq\">\n        <DateRangePicker\n          value={vacation}\n          onValueChange={setVacation}\n          minDate={new Date()}\n          disabledDates={(d) => d.getDay() === 0}\n          clearable\n          name=\"tatil\"\n          presets={[\n            { label: 'Bir hafta', range: (t) => ({ from: addDays(t, 1), to: addDays(t, 7) }) },\n            { label: 'Ikki hafta', range: (t) => ({ from: addDays(t, 1), to: addDays(t, 14) }) },\n          ]}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/date-picker/range": { component: Demo84, file: "archive/v0.1/date-picker/range.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DateRangePicker, Field, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst daysAgo = (n: number) => {\n  const d = new Date();\n  return new Date(d.getFullYear(), d.getMonth(), d.getDate() - n);\n};\n\nexport default function DateRangePickerBasic() {\n  const [range, setRange] = useState<DateRangeValue | null>({ from: daysAgo(6), to: daysAgo(0) });\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field\n        label=\"Hisobot davri\"\n        description={\n          range?.from && range.to\n            ? `${formatDate(range.from, 'd MMM')} – ${formatDate(range.to, 'd MMM yyyy')}`\n            : 'Davr tanlanmagan'\n        }\n      >\n        <DateRangePicker value={range} onValueChange={setRange} presets maxDate={new Date()} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/date-picker/sizes": { component: Demo85, file: "archive/v0.1/date-picker/sizes.tsx", source: "'use client';\n\nimport { DatePicker } from '@akhatmirzo/ui';\n\nexport default function DatePickerSizes() {\n  const today = new Date();\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <DatePicker size=\"sm\" aria-label=\"Kichik\" defaultValue={today} />\n      <DatePicker size=\"md\" aria-label=\"O'rta\" defaultValue={today} />\n      <DatePicker size=\"lg\" aria-label=\"Katta\" defaultValue={today} />\n    </div>\n  );\n}\n" },
  "archive/v0.1/date-picker/states": { component: Demo86, file: "archive/v0.1/date-picker/states.tsx", source: "'use client';\n\nimport { DatePicker, Field } from '@akhatmirzo/ui';\n\nexport default function DatePickerStates() {\n  const today = new Date();\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"O'chirilgan\" disabled>\n        <DatePicker defaultValue={today} />\n      </Field>\n      <Field label=\"Faqat o'qish\">\n        <DatePicker defaultValue={today} readOnly />\n      </Field>\n      <Field label=\"Muddat\" error=\"Sanani tanlang\" required>\n        <DatePicker />\n      </Field>\n      <Field label=\"Boshqa format\" description=\"d MMMM yyyy\">\n        <DatePicker format=\"d MMMM yyyy\" defaultValue={today} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/date-picker/typing": { component: Demo87, file: "archive/v0.1/date-picker/typing.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DatePicker, Field, type DatePickerError } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst errorText: Record<DatePickerError, string> = {\n  invalid: \"Bunday sana yo'q\",\n  unavailable: \"O'tgan sanani tanlab bo'lmaydi\",\n};\n\nexport default function DatePickerTyping() {\n  const [date, setDate] = useState<Date | null>(null);\n  const [error, setError] = useState<DatePickerError | null>(null);\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field\n        label=\"Uchrashuv sanasi\"\n        required\n        error={error ? errorText[error] : undefined}\n        description=\"Sinab ko'ring: 31022026\"\n      >\n        <DatePicker\n          value={date}\n          onValueChange={setDate}\n          onErrorChange={setError}\n          minDate={new Date()}\n        />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Qiymat: <code>{date ? formatDate(date, 'yyyy-MM-dd') : 'null'}</code>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/dialog/async-submit": { component: Demo88, file: "archive/v0.1/dialog/async-submit.tsx", source: "'use client';\n\nimport { Button, Dialog, Field, Input, Textarea, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function DialogAsyncSubmit() {\n  const [open, setOpen] = useState(false);\n  const [sending, setSending] = useState(false);\n\n  const send = async () => {\n    setSending(true);\n    await wait(1500);\n    setSending(false);\n    setOpen(false);\n    toast.success('Fikringiz yuborildi');\n  };\n\n  return (\n    <Dialog open={open} onOpenChange={(next) => !sending && setOpen(next)}>\n      <Dialog.Trigger asChild>\n        <Button>Fikr bildirish</Button>\n      </Dialog.Trigger>\n      <Dialog.Content title=\"Fikr bildirish\" size=\"lg\" dismissible={!sending}>\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Mavzu\" required>\n            <Input placeholder=\"Masalan: yetkazib berish\" />\n          </Field>\n          <Field label=\"Xabar\">\n            <Textarea minRows={4} placeholder=\"Fikringizni yozing...\" />\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button disabled={sending}>Bekor qilish</Button>\n          </Dialog.Close>\n          <Button variant=\"primary\" loading={sending} onClick={send}>\n            Yuborish\n          </Button>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "archive/v0.1/dialog/basic": { component: Demo89, file: "archive/v0.1/dialog/basic.tsx", source: "'use client';\n\nimport { Button, Dialog, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DialogBasic() {\n  const [open, setOpen] = useState(false);\n  const [name, setName] = useState('Sarvar');\n  const [phone, setPhone] = useState('+998 90 123 45 67');\n\n  return (\n    <Dialog open={open} onOpenChange={setOpen}>\n      <Dialog.Trigger asChild>\n        <Button variant=\"primary\">Profilni tahrirlash</Button>\n      </Dialog.Trigger>\n      <Dialog.Content title=\"Profilni tahrirlash\" description=\"O'zgarishlar darhol saqlanadi.\">\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Ism\">\n            <Input value={name} onChange={(e) => setName(e.target.value)} />\n          </Field>\n          <Field label=\"Telefon\" description=\"Tasdiqlash uchun SMS kod yuboriladi\">\n            <Input value={phone} onChange={(e) => setPhone(e.target.value)} />\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button>Bekor qilish</Button>\n          </Dialog.Close>\n          <Button variant=\"primary\" onClick={() => setOpen(false)}>\n            Saqlash\n          </Button>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "archive/v0.1/dialog/confirm-dialog": { component: Demo90, file: "archive/v0.1/dialog/confirm-dialog.tsx", source: "'use client';\n\nimport { Button, ConfirmDialog, toast } from '@akhatmirzo/ui';\n\nexport default function DialogConfirmDeclarative() {\n  return (\n    <ConfirmDialog\n      trigger={<Button variant=\"outline\">Hisobdan chiqish</Button>}\n      title=\"Hisobdan chiqilsinmi?\"\n      description=\"Qayta kirish uchun SMS kod kerak bo'ladi.\"\n      confirmText=\"Chiqish\"\n      onConfirm={() => toast('Hisobdan chiqdingiz')}\n      onCancel={() => toast.info('Hisobda qoldingiz')}\n    />\n  );\n}\n" },
  "archive/v0.1/dialog/confirm": { component: Demo91, file: "archive/v0.1/dialog/confirm.tsx", source: "'use client';\n\nimport { Button, confirm, toast } from '@akhatmirzo/ui';\nimport { Trash2 } from 'lucide-react';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function DialogConfirm() {\n  const removeOrder = async () => {\n    const ok = await confirm({\n      title: \"Buyurtma o'chirilsinmi?\",\n      description: \"Bu amalni qaytarib bo'lmaydi.\",\n      confirmText: \"O'chirish\",\n      variant: 'danger',\n    });\n    if (ok) toast.success(\"Buyurtma #1042 o'chirildi\");\n  };\n\n  const publish = async () => {\n    const ok = await confirm({\n      title: 'Mahsulot nashr qilinsinmi?',\n      description: \"Mahsulot do'konda hammaga ko'rinadi.\",\n      confirmText: 'Nashr qilish',\n      // Promise tugaguncha tugma loading, oyna ochiq turadi\n      onConfirm: () => wait(1500),\n    });\n    if (ok) toast.success('Mahsulot nashr qilindi');\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"danger\" leftIcon={<Trash2 />} onClick={removeOrder}>\n        O'chirish\n      </Button>\n      <Button variant=\"primary\" onClick={publish}>\n        Nashr qilish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/dialog/options": { component: Demo92, file: "archive/v0.1/dialog/options.tsx", source: "'use client';\n\nimport { Button, Dialog } from '@akhatmirzo/ui';\n\nexport default function DialogOptions() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">dismissible=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content\n          title=\"Shartlarni o'qing\"\n          description=\"Tashqariga bosish yopmaydi — faqat tugma yoki Esc.\"\n          dismissible={false}\n        >\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Roziman</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">closeButton=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content title=\"✕ tugmasisiz\" closeButton={false} size=\"sm\">\n          <p className=\"m-0 text-sm text-text-muted\">Oyna faqat pastdagi tugma bilan yopiladi.</p>\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Yopish</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">hideTitle</Button>\n        </Dialog.Trigger>\n        <Dialog.Content title=\"Mahsulot rasmi\" hideTitle size=\"sm\">\n          <div className=\"grid h-40 place-items-center rounded-xl bg-surface-muted text-sm text-text-muted\">\n            Sarlavha faqat ekran o'quvchi uchun\n          </div>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">mobileSheet=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content\n          title=\"Doim markazda\"\n          description=\"Telefonda ham pastdan chiqmaydi.\"\n          mobileSheet={false}\n          size=\"sm\"\n        >\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Yaxshi</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n    </div>\n  );\n}\n" },
  "archive/v0.1/dialog/sizes": { component: Demo93, file: "archive/v0.1/dialog/sizes.tsx", source: "'use client';\n\nimport { Button, Dialog, type DialogSize } from '@akhatmirzo/ui';\n\nconst sizes: { size: DialogSize; width: string }[] = [\n  { size: 'sm', width: '400px' },\n  { size: 'md', width: '520px' },\n  { size: 'lg', width: '640px' },\n  { size: 'xl', width: '800px' },\n  { size: 'full', width: 'butun ekran' },\n];\n\nexport default function DialogSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sizes.map(({ size, width }) => (\n        <Dialog key={size}>\n          <Dialog.Trigger asChild>\n            <Button variant=\"outline\">{size}</Button>\n          </Dialog.Trigger>\n          <Dialog.Content\n            title={`O'lcham: ${size}`}\n            description={`Kenglik — ${width}.`}\n            size={size}\n          >\n            <p className=\"m-0 text-sm text-text-muted\">\n              Ekran tor bo'lsa, chetlarda 16px joy qoladi. Telefonda oyna pastdan chiqadi.\n            </p>\n            <Dialog.Footer>\n              <Dialog.Close asChild>\n                <Button variant=\"primary\">Tushunarli</Button>\n              </Dialog.Close>\n            </Dialog.Footer>\n          </Dialog.Content>\n        </Dialog>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/dialog/with-select": { component: Demo94, file: "archive/v0.1/dialog/with-select.tsx", source: "'use client';\n\nimport { Button, Combobox, Dialog, Field, Select } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro', 'Andijon', \"Farg'ona\", 'Namangan'].map(\n  (label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }),\n);\n\nexport default function DialogWithSelect() {\n  const [city, setCity] = useState<string | null>('toshkent');\n\n  return (\n    <Dialog>\n      <Dialog.Trigger asChild>\n        <Button variant=\"outline\">Yetkazib berish manzili</Button>\n      </Dialog.Trigger>\n      <Dialog.Content\n        title=\"Yetkazib berish manzili\"\n        description=\"Ro'yxatlar oyna ustida ochiladi.\"\n      >\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Shahar\">\n            <Combobox options={cities} value={city} onValueChange={setCity} clearable />\n          </Field>\n          <Field label=\"Yetkazish vaqti\">\n            <Select defaultValue=\"morning\">\n              <Select.Item value=\"morning\">Ertalab (9:00–12:00)</Select.Item>\n              <Select.Item value=\"day\">Kunduzi (12:00–17:00)</Select.Item>\n              <Select.Item value=\"evening\">Kechqurun (17:00–21:00)</Select.Item>\n            </Select>\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button>Bekor qilish</Button>\n          </Dialog.Close>\n          <Dialog.Close asChild>\n            <Button variant=\"primary\">Saqlash</Button>\n          </Dialog.Close>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "archive/v0.1/divider/basic": { component: Demo95, file: "archive/v0.1/divider/basic.tsx", source: "'use client';\n\nimport { Divider } from '@akhatmirzo/ui';\n\nexport default function DividerBasic() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3 text-sm text-text\">\n      <div className=\"flex justify-between\">\n        <span>Mahsulotlar</span>\n        <span>220 000 so'm</span>\n      </div>\n      <div className=\"flex justify-between text-text-muted\">\n        <span>Yetkazib berish</span>\n        <span>25 000 so'm</span>\n      </div>\n      <Divider />\n      <div className=\"flex justify-between font-semibold\">\n        <span>Jami</span>\n        <span>245 000 so'm</span>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/divider/label": { component: Demo96, file: "archive/v0.1/divider/label.tsx", source: "'use client';\n\nimport { Button, Divider } from '@akhatmirzo/ui';\n\nexport default function DividerLabel() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Button variant=\"primary\" fullWidth>\n        Telefon orqali kirish\n      </Button>\n      <Divider label=\"yoki\" />\n      <Button variant=\"outline\" fullWidth>\n        Google orqali kirish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/divider/vertical": { component: Demo97, file: "archive/v0.1/divider/vertical.tsx", source: "'use client';\n\nimport { Divider } from '@akhatmirzo/ui';\n\nexport default function DividerVertical() {\n  return (\n    <div className=\"flex h-5 items-center gap-3 text-sm font-medium text-text-subtle\">\n      <span>Bosh sahifa</span>\n      <Divider orientation=\"vertical\" decorative />\n      <span>Buyurtmalar</span>\n      <Divider orientation=\"vertical\" decorative />\n      <span>Sozlamalar</span>\n    </div>\n  );\n}\n" },
  "archive/v0.1/drawer/details": { component: Demo98, file: "archive/v0.1/drawer/details.tsx", source: "'use client';\n\nimport { Button, Drawer } from '@akhatmirzo/ui';\n\nconst rows = [\n  ['Mijoz', 'Sarvar Abduxoliqov'],\n  ['Telefon', '+998 90 123 45 67'],\n  ['Manzil', 'Toshkent, Chilonzor tumani, 9-mavze'],\n  [\"To'lov\", 'Naqd, yetkazib berilganda'],\n  ['Jami', \"1 250 000 so'm\"],\n];\n\nexport default function DrawerDetails() {\n  return (\n    <Drawer>\n      <Drawer.Trigger asChild>\n        <Button>Buyurtma #1042</Button>\n      </Drawer.Trigger>\n      <Drawer.Content size=\"lg\" title=\"Buyurtma #1042\" description=\"21-oktabr, 14:32\">\n        <dl className=\"m-0 grid grid-cols-[auto_1fr] gap-x-6 gap-y-3 text-sm\">\n          {rows.map(([label, value]) => (\n            <div key={label} className=\"contents\">\n              <dt className=\"text-text-muted\">{label}</dt>\n              <dd className=\"m-0 font-medium text-text\">{value}</dd>\n            </div>\n          ))}\n        </dl>\n        <Drawer.Footer>\n          <Drawer.Close asChild>\n            <Button>Yopish</Button>\n          </Drawer.Close>\n          <Button variant=\"primary\">Yetkazildi deb belgilash</Button>\n        </Drawer.Footer>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "archive/v0.1/drawer/filters": { component: Demo99, file: "archive/v0.1/drawer/filters.tsx", source: "'use client';\n\nimport { Button, Checkbox, Drawer, Field, Input, Switch } from '@akhatmirzo/ui';\nimport { SlidersHorizontal } from 'lucide-react';\nimport { useState } from 'react';\n\nconst categories = ['Elektronika', 'Kiyim-kechak', \"Uy-ro'zg'or\", 'Kitoblar'];\n\nexport default function DrawerFilters() {\n  const [open, setOpen] = useState(false);\n  const [selected, setSelected] = useState<string[]>(['Elektronika']);\n\n  const toggle = (name: string, on: boolean) =>\n    setSelected((prev) => (on ? [...prev, name] : prev.filter((x) => x !== name)));\n\n  return (\n    <Drawer open={open} onOpenChange={setOpen}>\n      <Drawer.Trigger asChild>\n        <Button variant=\"outline\" leftIcon={<SlidersHorizontal />}>\n          Filtrlar\n        </Button>\n      </Drawer.Trigger>\n      <Drawer.Content title=\"Filtrlar\" description=\"Natijalarni toraytiring.\">\n        <div className=\"flex flex-col gap-5\">\n          <div className=\"grid grid-cols-2 gap-3\">\n            <Field label=\"Narxdan\">\n              <Input inputMode=\"numeric\" placeholder=\"0\" suffix=\"so'm\" />\n            </Field>\n            <Field label=\"Narxgacha\">\n              <Input inputMode=\"numeric\" placeholder=\"1 000 000\" suffix=\"so'm\" />\n            </Field>\n          </div>\n          <div className=\"flex flex-col gap-3\">\n            {categories.map((c) => (\n              <Checkbox\n                key={c}\n                label={c}\n                checked={selected.includes(c)}\n                onCheckedChange={(on) => toggle(c, on)}\n              />\n            ))}\n          </div>\n          <Switch label=\"Faqat mavjudlari\" defaultChecked />\n        </div>\n        <Drawer.Footer>\n          <Button onClick={() => setSelected([])}>Tozalash</Button>\n          <Button variant=\"primary\" onClick={() => setOpen(false)}>\n            Qo'llash\n          </Button>\n        </Drawer.Footer>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "archive/v0.1/drawer/mobile-menu": { component: Demo100, file: "archive/v0.1/drawer/mobile-menu.tsx", source: "'use client';\n\nimport { Button, Drawer } from '@akhatmirzo/ui';\nimport { Menu } from 'lucide-react';\nimport { useState } from 'react';\n\nconst items = ['Bosh sahifa', 'Buyurtmalar', 'Mahsulotlar', 'Mijozlar', 'Hisobotlar'];\n\nexport default function DrawerMobileMenu() {\n  const [active, setActive] = useState('Buyurtmalar');\n\n  return (\n    <Drawer>\n      <Drawer.Trigger asChild>\n        <Button variant=\"ghost\" leftIcon={<Menu />}>\n          Menyu\n        </Button>\n      </Drawer.Trigger>\n      <Drawer.Content\n        side=\"left\"\n        size=\"sm\"\n        title=\"Menyu\"\n        hideTitle\n        labels={{ close: 'Menyuni yopish' }}\n      >\n        <nav aria-label=\"Asosiy menyu\" className=\"-mx-2 flex flex-col gap-1\">\n          {items.map((item) => (\n            <Drawer.Close asChild key={item}>\n              <button\n                type=\"button\"\n                aria-current={item === active ? 'page' : undefined}\n                onClick={() => setActive(item)}\n                className=\"focus-ring flex h-10 cursor-pointer items-center rounded-lg border-0 bg-transparent px-3 text-left text-sm font-medium text-text hover:bg-surface-muted aria-[current=page]:bg-primary-soft aria-[current=page]:text-primary-soft-foreground\"\n              >\n                {item}\n              </button>\n            </Drawer.Close>\n          ))}\n        </nav>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "archive/v0.1/drawer/sides": { component: Demo101, file: "archive/v0.1/drawer/sides.tsx", source: "'use client';\n\nimport { Button, Drawer, type DrawerSide } from '@akhatmirzo/ui';\n\nconst sides: { side: DrawerSide; label: string }[] = [\n  { side: 'right', label: \"O'ngdan\" },\n  { side: 'left', label: 'Chapdan' },\n  { side: 'bottom', label: 'Pastdan' },\n  { side: 'top', label: 'Tepadan' },\n];\n\nexport default function DrawerSides() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sides.map(({ side, label }) => (\n        <Drawer key={side}>\n          <Drawer.Trigger asChild>\n            <Button variant=\"outline\">{label}</Button>\n          </Drawer.Trigger>\n          <Drawer.Content side={side} title={label} description={`side=\"${side}\"`}>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Panel ekran chetidan siljib chiqadi. Pastdan chiqqanda tepada tutqich chizig'i bor.\n            </p>\n            <Drawer.Footer>\n              <Drawer.Close asChild>\n                <Button variant=\"primary\">Yopish</Button>\n              </Drawer.Close>\n            </Drawer.Footer>\n          </Drawer.Content>\n        </Drawer>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/drawer/sizes": { component: Demo102, file: "archive/v0.1/drawer/sizes.tsx", source: "'use client';\n\nimport { Button, Drawer, type DrawerSize } from '@akhatmirzo/ui';\n\nconst sizes: { size: DrawerSize; px: string }[] = [\n  { size: 'sm', px: '320px' },\n  { size: 'md', px: '420px' },\n  { size: 'lg', px: '560px' },\n];\n\nexport default function DrawerSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sizes.map(({ size, px }) => (\n        <Drawer key={size}>\n          <Drawer.Trigger asChild>\n            <Button variant=\"outline\">\n              {size} — {px}\n            </Button>\n          </Drawer.Trigger>\n          <Drawer.Content size={size} title={`O'lcham: ${size}`} description={`Kenglik ${px}`}>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Chap va o'ngda o'lcham kenglikni, past va tepada balandlikni belgilaydi.\n            </p>\n          </Drawer.Content>\n        </Drawer>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/dropdown-menu/basic": { component: Demo103, file: "archive/v0.1/dropdown-menu/basic.tsx", source: "'use client';\n\nimport { Button, DropdownMenu, toast } from '@akhatmirzo/ui';\nimport { Archive, ChevronDown, Copy, Pencil, Trash2 } from 'lucide-react';\n\nexport default function DropdownMenuBasic() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <Button variant=\"outline\" rightIcon={<ChevronDown />}>\n          Amallar\n        </Button>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content>\n        <DropdownMenu.Item\n          icon={<Pencil />}\n          shortcut={['mod', 'E']}\n          onSelect={() => toast('Tahrirlash')}\n        >\n          Tahrirlash\n        </DropdownMenu.Item>\n        <DropdownMenu.Item\n          icon={<Copy />}\n          shortcut={['mod', 'D']}\n          onSelect={() => toast('Nusxa olindi')}\n        >\n          Nusxa olish\n        </DropdownMenu.Item>\n        <DropdownMenu.Item icon={<Archive />} onSelect={() => toast('Arxivlandi')}>\n          Arxivlash\n        </DropdownMenu.Item>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\" onSelect={() => toast(\"O'chirildi\")}>\n          O'chirish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "archive/v0.1/dropdown-menu/checkbox-radio": { component: Demo104, file: "archive/v0.1/dropdown-menu/checkbox-radio.tsx", source: "'use client';\n\nimport { DropdownMenu } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DropdownMenuCheckboxRadio() {\n  const [columns, setColumns] = useState({ price: true, stock: true, sku: false });\n  const [sort, setSort] = useState('new');\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <DropdownMenu>\n        <DropdownMenu.Trigger>Ustunlar</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Label>Jadvalda ko'rsatish</DropdownMenu.Label>\n          {(\n            [\n              ['price', 'Narx'],\n              ['stock', 'Ombordagi soni'],\n              ['sku', 'Artikul'],\n            ] as const\n          ).map(([key, label]) => (\n            <DropdownMenu.CheckboxItem\n              key={key}\n              checked={columns[key]}\n              onCheckedChange={(on) => setColumns((c) => ({ ...c, [key]: on }))}\n              // Menyu yopilmasin — bir nechtasini ketma-ket belgilash uchun\n              onSelect={(e) => e.preventDefault()}\n            >\n              {label}\n            </DropdownMenu.CheckboxItem>\n          ))}\n        </DropdownMenu.Content>\n      </DropdownMenu>\n\n      <DropdownMenu>\n        <DropdownMenu.Trigger>Saralash</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Label>Tartib</DropdownMenu.Label>\n          <DropdownMenu.RadioGroup value={sort} onValueChange={setSort}>\n            <DropdownMenu.RadioItem value=\"new\">Avval yangilari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"cheap\">Avval arzonlari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"expensive\">Avval qimmatlari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"popular\" disabled>\n              Ommabop (tez orada)\n            </DropdownMenu.RadioItem>\n          </DropdownMenu.RadioGroup>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n      <span className=\"text-sm text-text-muted\">Saralash: {sort}</span>\n    </div>\n  );\n}\n" },
  "archive/v0.1/dropdown-menu/profile": { component: Demo105, file: "archive/v0.1/dropdown-menu/profile.tsx", source: "'use client';\n\nimport { Button, DropdownMenu } from '@akhatmirzo/ui';\nimport { LogOut, Send, Settings, User } from 'lucide-react';\n\nexport default function DropdownMenuProfile() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <Button variant=\"ghost\" leftIcon={<User />}>\n          Akmal Karimov\n        </Button>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content align=\"end\" className=\"w-56\">\n        <DropdownMenu.Label>akmal@misol.uz</DropdownMenu.Label>\n        <DropdownMenu.Group>\n          <DropdownMenu.Item icon={<User />} shortcut={['mod', 'P']}>\n            Profil\n          </DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Settings />} shortcut={['mod', ',']}>\n            Sozlamalar\n          </DropdownMenu.Item>\n          <DropdownMenu.Item asChild icon={<Send />}>\n            <a href=\"https://github.com/Akhatmirzo/akhatmirzo-toolkit\">Loyiha GitHub'da</a>\n          </DropdownMenu.Item>\n        </DropdownMenu.Group>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<LogOut />} variant=\"danger\">\n          Chiqish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "archive/v0.1/dropdown-menu/states": { component: Demo106, file: "archive/v0.1/dropdown-menu/states.tsx", source: "'use client';\n\nimport { Button, DropdownMenu } from '@akhatmirzo/ui';\nimport { Copy, Pencil, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function DropdownMenuStates() {\n  const [open, setOpen] = useState(false);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <DropdownMenu>\n        <DropdownMenu.Trigger>O'chirilgan elementlar</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Item icon={<Pencil />}>Tahrirlash</DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Copy />} disabled>\n            Nusxa olish (ruxsat yo'q)\n          </DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\" disabled>\n            O'chirish (ruxsat yo'q)\n          </DropdownMenu.Item>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n\n      <DropdownMenu open={open} onOpenChange={setOpen}>\n        <DropdownMenu.Trigger>Boshqariladigan</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Item>Birinchi</DropdownMenu.Item>\n          <DropdownMenu.Item>Ikkinchi</DropdownMenu.Item>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n      <Button variant=\"ghost\" onClick={() => setOpen(true)}>\n        Tashqaridan ochish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/dropdown-menu/submenu": { component: Demo107, file: "archive/v0.1/dropdown-menu/submenu.tsx", source: "'use client';\n\nimport { DropdownMenu, IconButton } from '@akhatmirzo/ui';\nimport { Archive, Ellipsis, Pencil, Share2, Trash2 } from 'lucide-react';\n\nexport default function DropdownMenuSubmenu() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <IconButton variant=\"outline\" aria-label=\"Ko'proq amallar\">\n          <Ellipsis />\n        </IconButton>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content>\n        <DropdownMenu.Item icon={<Pencil />}>Nomini o'zgartirish</DropdownMenu.Item>\n        <DropdownMenu.Sub>\n          <DropdownMenu.SubTrigger icon={<Share2 />}>Ulashish</DropdownMenu.SubTrigger>\n          <DropdownMenu.SubContent>\n            <DropdownMenu.Item>Telegram</DropdownMenu.Item>\n            <DropdownMenu.Item>Email orqali</DropdownMenu.Item>\n            <DropdownMenu.Item shortcut={['mod', 'L']}>Havolani nusxalash</DropdownMenu.Item>\n          </DropdownMenu.SubContent>\n        </DropdownMenu.Sub>\n        <DropdownMenu.Sub>\n          <DropdownMenu.SubTrigger icon={<Archive />}>Ko'chirish</DropdownMenu.SubTrigger>\n          <DropdownMenu.SubContent>\n            <DropdownMenu.Item>Kiruvchi</DropdownMenu.Item>\n            <DropdownMenu.Item>Arxiv</DropdownMenu.Item>\n          </DropdownMenu.SubContent>\n        </DropdownMenu.Sub>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\">\n          O'chirish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "archive/v0.1/field/basic": { component: Demo108, file: "archive/v0.1/field/basic.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function FieldBasic() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" required description=\"Tasdiqlash kodi SMS orqali yuboriladi\">\n        <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" />\n      </Field>\n      <Field label=\"Email\" error=\"Email manzil noto'g'ri\">\n        <Input type=\"email\" defaultValue=\"sarvar@mail\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/field/custom-control": { component: Demo109, file: "archive/v0.1/field/custom-control.tsx", source: "'use client';\n\nimport { Field, useFieldControl } from '@akhatmirzo/ui';\n\nfunction CitySelect() {\n  const { controlProps, invalid, disabled } = useFieldControl();\n  return (\n    <select\n      {...controlProps}\n      disabled={disabled}\n      data-invalid={invalid ? '' : undefined}\n      className=\"h-10 rounded-lg border border-border bg-surface px-3 text-sm text-text data-invalid:border-danger\"\n    >\n      <option value=\"\">Tanlang</option>\n      <option>Toshkent</option>\n      <option>Samarqand</option>\n      <option>Buxoro</option>\n    </select>\n  );\n}\n\nexport default function FieldCustomControl() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Shahar\" required error=\"Shaharni tanlang\">\n        <CitySelect />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/field/disabled": { component: Demo110, file: "archive/v0.1/field/disabled.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function FieldDisabled() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Hudud\" description=\"Hudud administrator tomonidan belgilanadi\" disabled>\n        <Input defaultValue=\"Toshkent shahri\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/field/horizontal": { component: Demo111, file: "archive/v0.1/field/horizontal.tsx", source: "'use client';\n\nimport { Field, Input, Textarea } from '@akhatmirzo/ui';\n\nexport default function FieldHorizontal() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-4\">\n      <Field orientation=\"horizontal\" label=\"Do'kon nomi\" description=\"Chekda ko'rinadi\">\n        <Input defaultValue=\"Bahor Market\" />\n      </Field>\n      <Field orientation=\"horizontal\" label=\"Manzil\">\n        <Textarea minRows={2} defaultValue=\"Toshkent, Chilonzor tumani, 9-kvartal\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/field/validation": { component: Demo112, file: "archive/v0.1/field/validation.tsx", source: "'use client';\n\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function FieldValidation() {\n  const [name, setName] = useState('');\n  const [submitted, setSubmitted] = useState(false);\n  const error = submitted && name.trim().length < 3 ? 'Kamida 3 ta harf kiriting' : undefined;\n\n  const submit = (event: FormEvent) => {\n    event.preventDefault();\n    setSubmitted(true);\n  };\n\n  return (\n    <form onSubmit={submit} noValidate className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"To'liq ism\" required error={error}>\n        <Input\n          value={name}\n          onChange={(e) => setName(e.target.value)}\n          placeholder=\"Sarvar Abduxoliqov\"\n          autoComplete=\"name\"\n        />\n      </Field>\n      <Button type=\"submit\" variant=\"primary\">\n        Davom etish\n      </Button>\n    </form>\n  );\n}\n" },
  "archive/v0.1/file-upload/basic": { component: Demo113, file: "archive/v0.1/file-upload/basic.tsx", source: "'use client';\n\nimport { Field, FileUpload, type FileUploadContext, type FileUploadItem } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst MB = 1024 * 1024;\n\n/** Soxta yuklash: progress bilan ~2 soniya. Nomida \"xato\" bo'lsa — tarmoq xatosi */\nfunction fakeUpload(file: File, { onProgress, signal }: FileUploadContext) {\n  return new Promise<{ url: string }>((resolve, reject) => {\n    let progress = 0;\n    const timer = setInterval(() => {\n      progress = Math.min(100, progress + 8);\n      onProgress(progress);\n      if (file.name.includes('xato') && progress > 50) {\n        clearInterval(timer);\n        reject(new Error('network'));\n      } else if (progress === 100) {\n        clearInterval(timer);\n        resolve({ url: `/uploads/${encodeURIComponent(file.name)}` });\n      }\n    }, 150);\n    signal.addEventListener('abort', () => clearInterval(timer));\n  });\n}\n\nexport default function FileUploadBasic() {\n  const [files, setFiles] = useState<FileUploadItem[]>([]);\n  const done = files.filter((f) => f.status === 'done').length;\n\n  return (\n    <div className=\"flex w-full max-w-lg flex-col gap-2\">\n      <Field label=\"Hujjatlar\">\n        <FileUpload\n          accept={['image/*', '.pdf']}\n          maxSize={5 * MB}\n          maxFiles={5}\n          multiple\n          upload={fakeUpload}\n          onFilesChange={setFiles}\n        />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Jami: {files.length} · yuklandi: {done}\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/file-upload/button": { component: Demo114, file: "archive/v0.1/file-upload/button.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadButton() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Pasport nusxasi\" description=\"Old va orqa tomoni\">\n        <FileUpload\n          variant=\"button\"\n          accept={['image/*', '.pdf']}\n          maxSize={5 * 1024 * 1024}\n          maxFiles={2}\n          multiple\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/file-upload/form": { component: Demo115, file: "archive/v0.1/file-upload/form.tsx", source: "'use client';\n\nimport { formatFileSize } from '@akhatmirzo/core';\nimport { Button, Field, FileUpload } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function FileUploadForm() {\n  const [sent, setSent] = useState<string | null>(null);\n\n  const onSubmit = (e: FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    const files = (new FormData(e.currentTarget).getAll('rezyume') as File[]).filter(\n      (f) => f.size > 0,\n    );\n    setSent(files.map((f) => `${f.name} (${formatFileSize(f.size)})`).join(', ') || \"Fayl yo'q\");\n  };\n\n  return (\n    <form onSubmit={onSubmit} className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Rezyume\" description=\"PDF yoki DOCX, 2 MB gacha\">\n        <FileUpload\n          variant=\"button\"\n          name=\"rezyume\"\n          accept={['.pdf', '.docx']}\n          maxSize={2 * 1024 * 1024}\n        />\n      </Field>\n      <div className=\"flex items-center gap-3\">\n        <Button type=\"submit\" variant=\"primary\" size=\"sm\">\n          Yuborish\n        </Button>\n        {sent && <span className=\"text-sm text-text-muted\">{sent}</span>}\n      </div>\n    </form>\n  );\n}\n" },
  "archive/v0.1/file-upload/paste": { component: Demo116, file: "archive/v0.1/file-upload/paste.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadPaste() {\n  return (\n    <div className=\"w-full max-w-lg\">\n      <Field\n        label=\"Skrinshot\"\n        description=\"Rasmni nusxalang va sahifaning istalgan joyida Ctrl+V bosing\"\n      >\n        <FileUpload accept={['image/*']} multiple maxFiles={3} paste=\"global\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/file-upload/states": { component: Demo117, file: "archive/v0.1/file-upload/states.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadStates() {\n  return (\n    <div className=\"grid w-full gap-4 md:grid-cols-2\">\n      <Field label=\"Faqat rasm\" description=\"Bitta fayl — yangisi eskisini almashtiradi\">\n        <FileUpload accept={['image/png', 'image/jpeg']} maxSize={1024 * 1024} />\n      </Field>\n      <Field label=\"Shartnoma\" error=\"Kamida bitta hujjat yuklang\" required>\n        <FileUpload accept={['.pdf']} />\n      </Field>\n      <Field label=\"O'chirilgan\" disabled>\n        <FileUpload />\n      </Field>\n      <Field label=\"O'z cheklov matni bilan\">\n        <FileUpload hint=\"Excel yoki CSV · 10 MB gacha\" accept={['.xlsx', '.csv']} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/async": { component: Demo118, file: "archive/v0.1/hooks/async.tsx", source: "'use client';\n\nimport { useAsync, useToggle } from '@akhatmirzo/hooks';\nimport { Badge, Button, Switch } from '@akhatmirzo/ui';\n\nconst CITIES = ['Toshkent', 'Samarqand', 'Buxoro', 'Xiva', 'Namangan', 'Andijon', 'Nukus'];\nconst STATUS_COLOR = {\n  idle: 'neutral',\n  loading: 'info',\n  success: 'success',\n  error: 'danger',\n} as const;\n\nfunction fetchCities(fail: boolean): Promise<string[]> {\n  const delay = 500 + Math.random() * 1000;\n  return new Promise((resolve, reject) =>\n    setTimeout(() => {\n      if (fail) reject(new Error('Server javob bermadi'));\n      else resolve(CITIES.slice(0, 2 + Math.floor(Math.random() * 5)));\n    }, delay),\n  );\n}\n\nexport default function HooksAsync() {\n  const [fail, , setFail] = useToggle(false);\n  const { status, data, error, run } = useAsync(fetchCities, [], { immediate: false });\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Button onClick={() => void run(fail)} loading={status === 'loading'}>\n          Yuklash\n        </Button>\n        <Badge color={STATUS_COLOR[status]} dot>\n          {status}\n        </Badge>\n      </div>\n      <Switch checked={fail} onCheckedChange={setFail} label=\"Xato bilan tugasin\" />\n      {status === 'error' && error instanceof Error && (\n        <p className=\"text-sm text-danger-soft-foreground\">{error.message}</p>\n      )}\n      {data && <p className=\"text-sm text-text\">{data.join(', ')}</p>}\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/click-outside": { component: Demo119, file: "archive/v0.1/hooks/click-outside.tsx", source: "'use client';\n\nimport { useClickOutside, useHotkeys, useToggle } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useRef } from 'react';\n\nexport default function HooksClickOutside() {\n  const [open, toggle, setOpen] = useToggle(false);\n  const triggerRef = useRef<HTMLButtonElement>(null);\n  const panelRef = useRef<HTMLDivElement>(null);\n\n  useClickOutside([triggerRef, panelRef], () => setOpen(false), open);\n  useHotkeys('esc', () => setOpen(false), { enabled: open });\n\n  return (\n    <div className=\"relative flex flex-col items-center gap-2\">\n      <Button ref={triggerRef} variant=\"outline\" onClick={toggle} aria-expanded={open}>\n        Filtrlar\n      </Button>\n      {open && (\n        <div\n          ref={panelRef}\n          className=\"w-64 rounded-xl border border-border bg-surface-raised p-4 text-sm text-text shadow-lg\"\n        >\n          Panel tashqarisiga bosing yoki <kbd className=\"font-mono\">Esc</kbd> ni bosing — yopiladi.\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/controllable-state": { component: Demo120, file: "archive/v0.1/hooks/controllable-state.tsx", source: "'use client';\n\nimport { useControllableState } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\ninterface StepperProps {\n  value?: number;\n  defaultValue?: number;\n  onValueChange?: (value: number) => void;\n}\n\nfunction Stepper({ value, defaultValue = 0, onValueChange }: StepperProps) {\n  const [count, setCount] = useControllableState({ value, defaultValue, onChange: onValueChange });\n  return (\n    <div className=\"flex items-center gap-2\">\n      <Button size=\"sm\" variant=\"outline\" onClick={() => setCount((n) => n - 1)}>\n        −\n      </Button>\n      <span className=\"min-w-8 text-center font-semibold text-text tabular-nums\">{count}</span>\n      <Button size=\"sm\" variant=\"outline\" onClick={() => setCount((n) => n + 1)}>\n        +\n      </Button>\n    </div>\n  );\n}\n\nexport default function HooksControllableState() {\n  const [value, setValue] = useState(10);\n\n  return (\n    <div className=\"grid w-full max-w-md gap-6 sm:grid-cols-2\">\n      <div className=\"flex flex-col gap-2\">\n        <p className=\"text-xs font-medium text-text-muted\">Boshqarilmaydigan (defaultValue=3)</p>\n        <Stepper defaultValue={3} />\n      </div>\n      <div className=\"flex flex-col gap-2\">\n        <p className=\"text-xs font-medium text-text-muted\">Boshqariladigan (0…20)</p>\n        <Stepper value={value} onValueChange={(v) => setValue(Math.min(20, Math.max(0, v)))} />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/copy": { component: Demo121, file: "archive/v0.1/hooks/copy.tsx", source: "'use client';\n\nimport { useCopyToClipboard } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { Check, Copy } from 'lucide-react';\n\nexport default function HooksCopy() {\n  const { copied, copy } = useCopyToClipboard();\n  const command = 'pnpm add @akhatmirzo/hooks';\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <code className=\"rounded-lg border border-border bg-surface-muted px-3 py-2 font-mono text-sm text-text\">\n        {command}\n      </code>\n      <Button\n        variant={copied ? 'soft' : 'outline'}\n        leftIcon={copied ? <Check /> : <Copy />}\n        onClick={() => void copy(command)}\n      >\n        {copied ? 'Nusxalandi' : 'Nusxa olish'}\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/debounce": { component: Demo122, file: "archive/v0.1/hooks/debounce.tsx", source: "'use client';\n\nimport { useDebounce } from '@akhatmirzo/hooks';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CITIES = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Xiva',\n  'Namangan',\n  'Andijon',\n  'Nukus',\n  'Termiz',\n];\n\nexport default function HooksDebounce() {\n  const [query, setQuery] = useState('');\n  const debounced = useDebounce(query, 400);\n  const results = CITIES.filter((c) => c.toLowerCase().includes(debounced.trim().toLowerCase()));\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Shahar qidirish\" description=\"Natija yozishni to'xtatganingizdan 400 ms keyin\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <Badge color={query === debounced ? 'success' : 'warning'} dot className=\"self-start\">\n        {query === debounced ? 'Yangilangan' : 'Kutilmoqda…'}\n      </Badge>\n      <div className=\"flex flex-wrap gap-2\">\n        {results.map((city) => (\n          <Badge key={city} variant=\"outline\">\n            {city}\n          </Badge>\n        ))}\n        {results.length === 0 && (\n          <span className=\"text-sm text-text-muted\">Hech narsa topilmadi</span>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/debounced-callback": { component: Demo123, file: "archive/v0.1/hooks/debounced-callback.tsx", source: "'use client';\n\nimport { useDebouncedCallback } from '@akhatmirzo/hooks';\nimport { Button, Field, Textarea } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksDebouncedCallback() {\n  const [text, setText] = useState('');\n  const [saved, setSaved] = useState<string[]>([]);\n\n  const save = useDebouncedCallback((value: string) => {\n    setSaved((list) => [`${value.length} belgi saqlandi`, ...list].slice(0, 3));\n  }, 800);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Izoh\" description=\"Avtomatik saqlash: yozishni to'xtatgach 800 ms o'tib\">\n        <Textarea\n          value={text}\n          onChange={(e) => {\n            setText(e.target.value);\n            save(e.target.value);\n          }}\n          minRows={3}\n        />\n      </Field>\n      <Button size=\"sm\" variant=\"outline\" className=\"self-start\" onClick={save.flush}>\n        Hozir saqlash\n      </Button>\n      <ul className=\"text-sm text-text-muted\">\n        {saved.map((line, i) => (\n          <li key={i}>{line}</li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/hotkeys": { component: Demo124, file: "archive/v0.1/hooks/hotkeys.tsx", source: "'use client';\n\nimport { useHotkeys } from '@akhatmirzo/hooks';\nimport { Badge, Kbd } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksHotkeys() {\n  const [last, setLast] = useState<string | null>(null);\n  const [count, setCount] = useState(0);\n\n  const hit = (name: string) => {\n    setLast(name);\n    setCount((n) => n + 1);\n  };\n\n  useHotkeys('alt+k', () => hit('alt+k'));\n  useHotkeys('?', () => hit('?'));\n  // Bir nechta kombinatsiya — vergul bilan\n  useHotkeys('g, alt+g', () => hit('g'));\n\n  return (\n    <div className=\"flex flex-col items-center gap-3 text-sm text-text\">\n      <div className=\"flex flex-wrap items-center justify-center gap-3\">\n        <Kbd keys={['Alt', 'K']} />\n        <Kbd>?</Kbd>\n        <Kbd>G</Kbd>\n      </div>\n      <p className=\"text-text-muted\">Yuqoridagi tugmalardan birini bosing</p>\n      {last && (\n        <Badge color=\"primary\">\n          {last} · {count} marta\n        </Badge>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/intersection": { component: Demo125, file: "archive/v0.1/hooks/intersection.tsx", source: "'use client';\n\nimport { useIntersection } from '@akhatmirzo/hooks';\nimport { Spinner } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\nconst MAX = 60;\n\nexport default function HooksIntersection() {\n  const [count, setCount] = useState(12);\n  const done = count >= MAX;\n  const [sentinelRef, entry] = useIntersection<HTMLDivElement>({\n    rootMargin: '40px',\n    enabled: !done,\n  });\n  const visible = entry?.isIntersecting ?? false;\n\n  useEffect(() => {\n    if (!visible || done) return;\n    // Haqiqiy ilovada — keyingi sahifani serverdan yuklash\n    const timer = setTimeout(() => setCount((n) => Math.min(MAX, n + 12)), 500);\n    return () => clearTimeout(timer);\n  }, [visible, done, count]);\n\n  return (\n    <div className=\"h-64 w-full max-w-sm overflow-auto rounded-xl border border-border bg-surface\">\n      <ul className=\"divide-y divide-border text-sm text-text\">\n        {Array.from({ length: count }, (_, i) => (\n          <li key={i} className=\"px-4 py-2\">\n            Buyurtma #{1000 + i}\n          </li>\n        ))}\n      </ul>\n      <div\n        ref={sentinelRef}\n        className=\"flex items-center justify-center gap-2 p-3 text-sm text-text-muted\"\n      >\n        {done ? (\n          'Hammasi yuklandi'\n        ) : (\n          <>\n            <Spinner size=\"sm\" /> Yuklanmoqda…\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/local-storage": { component: Demo126, file: "archive/v0.1/hooks/local-storage.tsx", source: "'use client';\n\nimport { useLocalStorage } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\n\nfunction Mirror() {\n  const [count] = useLocalStorage('docs-demo:counter', 0);\n  return (\n    <p className=\"text-sm text-text-muted\">\n      Boshqa komponent ko'rayotgan qiymat: <strong className=\"text-text\">{count}</strong>\n    </p>\n  );\n}\n\nexport default function HooksLocalStorage() {\n  const [count, setCount, remove] = useLocalStorage('docs-demo:counter', 0);\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <div className=\"flex items-center gap-2\">\n        <Button variant=\"outline\" onClick={() => setCount((n) => n - 1)}>\n          −\n        </Button>\n        <span className=\"min-w-12 text-center text-2xl font-semibold text-text tabular-nums\">\n          {count}\n        </span>\n        <Button variant=\"outline\" onClick={() => setCount((n) => n + 1)}>\n          +\n        </Button>\n        <Button variant=\"ghost\" onClick={remove}>\n          O'chirish\n        </Button>\n      </div>\n      <Mirror />\n      <p className=\"text-xs text-text-faint\">\n        Sahifani boshqa tabda oching — qiymat sinxron o'zgaradi\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/media-query": { component: Demo127, file: "archive/v0.1/hooks/media-query.tsx", source: "'use client';\n\nimport { useMediaQuery } from '@akhatmirzo/hooks';\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function HooksMediaQuery() {\n  const queries = [\n    { label: '≥ 640px', on: useMediaQuery('(min-width: 640px)') },\n    { label: '≥ 1024px', on: useMediaQuery('(min-width: 1024px)') },\n    { label: \"Tizim: qorong'i mavzu\", on: useMediaQuery('(prefers-color-scheme: dark)') },\n    { label: 'Kam animatsiya', on: useMediaQuery('(prefers-reduced-motion: reduce)') },\n    { label: 'Sichqoncha (hover)', on: useMediaQuery('(hover: hover)') },\n  ];\n\n  return (\n    <div className=\"flex flex-wrap justify-center gap-2\">\n      {queries.map(({ label, on }) => (\n        <Badge key={label} color={on ? 'success' : 'neutral'} variant={on ? 'soft' : 'outline'} dot>\n          {label}\n        </Badge>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/pagination": { component: Demo128, file: "archive/v0.1/hooks/pagination.tsx", source: "'use client';\n\nimport { usePagination } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksPagination() {\n  const [page, setPage] = useState(5);\n  const { pages, hasPrev, hasNext, from, to } = usePagination({ total: 200, pageSize: 10, page });\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <nav aria-label=\"Sahifalar\" className=\"flex flex-wrap items-center justify-center gap-1\">\n        <Button size=\"sm\" variant=\"ghost\" disabled={!hasPrev} onClick={() => setPage(page - 1)}>\n          Oldingi\n        </Button>\n        {pages.map((p, i) =>\n          p === 'ellipsis' ? (\n            <span key={`e${i}`} className=\"px-2 text-text-muted\">\n              …\n            </span>\n          ) : (\n            <Button\n              key={p}\n              size=\"sm\"\n              variant={p === page ? 'primary' : 'ghost'}\n              aria-current={p === page ? 'page' : undefined}\n              onClick={() => setPage(p)}\n            >\n              {p}\n            </Button>\n          ),\n        )}\n        <Button size=\"sm\" variant=\"ghost\" disabled={!hasNext} onClick={() => setPage(page + 1)}>\n          Keyingi\n        </Button>\n      </nav>\n      <p className=\"text-sm text-text-muted\">\n        {from}–{to} / 200 ta yozuv\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/hooks/toggle": { component: Demo129, file: "archive/v0.1/hooks/toggle.tsx", source: "'use client';\n\nimport { useToggle } from '@akhatmirzo/hooks';\nimport { Button, Switch } from '@akhatmirzo/ui';\n\nexport default function HooksToggle() {\n  const [notify, toggleNotify, setNotify] = useToggle(true);\n\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Switch\n        checked={notify}\n        onCheckedChange={setNotify}\n        label=\"SMS xabarnomalar\"\n        description={notify ? 'Yoqilgan' : \"O'chirilgan\"}\n      />\n      <div className=\"flex flex-wrap gap-2\">\n        <Button variant=\"outline\" onClick={toggleNotify}>\n          Almashtirish\n        </Button>\n        <Button variant=\"ghost\" onClick={() => setNotify(false)}>\n          O'chirish\n        </Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/icon-button/as-child": { component: Demo130, file: "archive/v0.1/icon-button/as-child.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Settings } from 'lucide-react';\n\nexport default function IconButtonAsChild() {\n  return (\n    <IconButton asChild variant=\"outline\" aria-label=\"Sozlamalar\">\n      <a href=\"#props\">\n        <Settings />\n      </a>\n    </IconButton>\n  );\n}\n" },
  "archive/v0.1/icon-button/sizes": { component: Demo131, file: "archive/v0.1/icon-button/sizes.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { X } from 'lucide-react';\n\nexport default function IconButtonSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton variant=\"outline\" size=\"sm\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n      <IconButton variant=\"outline\" size=\"md\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n      <IconButton variant=\"outline\" size=\"lg\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.1/icon-button/states": { component: Demo132, file: "archive/v0.1/icon-button/states.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Download, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function IconButtonStates() {\n  const [loading, setLoading] = useState(false);\n\n  const download = () => {\n    setLoading(true);\n    setTimeout(() => setLoading(false), 1500);\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton\n        variant=\"primary\"\n        loading={loading}\n        onClick={download}\n        aria-label=\"Hisobotni yuklab olish\"\n        labels={{ loading: 'Yuklab olinmoqda' }}\n      >\n        <Download />\n      </IconButton>\n      <IconButton variant=\"danger\" disabled aria-label=\"O'chirish\">\n        <Trash2 />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.1/icon-button/toolbar": { component: Demo133, file: "archive/v0.1/icon-button/toolbar.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Bold, Italic, Plus, Underline } from 'lucide-react';\n\nexport default function IconButtonToolbar() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <div\n        role=\"toolbar\"\n        aria-label=\"Matn formati\"\n        className=\"flex items-center gap-1 rounded-lg border border-border bg-surface p-1\"\n      >\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Qalin\">\n          <Bold />\n        </IconButton>\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Kursiv\">\n          <Italic />\n        </IconButton>\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Tagiga chizilgan\">\n          <Underline />\n        </IconButton>\n      </div>\n      <IconButton variant=\"primary\" size=\"lg\" className=\"rounded-full\" aria-label=\"Yangi buyurtma\">\n        <Plus />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.1/icon-button/variants": { component: Demo134, file: "archive/v0.1/icon-button/variants.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Heart, Pencil, Plus, Share2, Trash2 } from 'lucide-react';\n\nexport default function IconButtonVariants() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton variant=\"primary\" aria-label=\"Qo'shish\">\n        <Plus />\n      </IconButton>\n      <IconButton aria-label=\"Sevimlilarga qo'shish\">\n        <Heart />\n      </IconButton>\n      <IconButton variant=\"outline\" aria-label=\"Tahrirlash\">\n        <Pencil />\n      </IconButton>\n      <IconButton variant=\"ghost\" aria-label=\"Ulashish\">\n        <Share2 />\n      </IconButton>\n      <IconButton variant=\"danger\" aria-label=\"O'chirish\">\n        <Trash2 />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.1/input/addons": { component: Demo135, file: "archive/v0.1/input/addons.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Mail } from 'lucide-react';\n\nexport default function InputAddons() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" aria-label=\"Telefon\" />\n      <Input suffix=\"so'm\" placeholder=\"1 250 000\" inputMode=\"numeric\" aria-label=\"Narx\" />\n      <Input rightIcon={<Mail />} type=\"email\" placeholder=\"email@misol.uz\" aria-label=\"Email\" />\n      <Input prefix=\"https://\" suffix=\".uz\" placeholder=\"dokon\" aria-label=\"Sayt manzili\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/input/basic": { component: Demo136, file: "archive/v0.1/input/basic.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Search } from 'lucide-react';\n\nexport default function InputBasic() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Input leftIcon={<Search />} placeholder=\"Mahsulot qidirish\" aria-label=\"Mahsulot qidirish\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/input/clearable": { component: Demo137, file: "archive/v0.1/input/clearable.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Search } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function InputClearable() {\n  const [query, setQuery] = useState('Samarqand');\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-2\">\n      <Input\n        leftIcon={<Search />}\n        clearable\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Shahar qidirish\"\n        aria-label=\"Shahar qidirish\"\n      />\n      <p className=\"text-xs text-text-muted\">Qiymat: {query || '—'}</p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/input/password": { component: Demo138, file: "archive/v0.1/input/password.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function InputPassword() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Parol\" description=\"Kamida 8 ta belgi\">\n        <Input type=\"password\" defaultValue=\"maxfiy123\" autoComplete=\"current-password\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/input/sizes": { component: Demo139, file: "archive/v0.1/input/sizes.tsx", source: "'use client';\n\nimport { Button, Input } from '@akhatmirzo/ui';\n\nexport default function InputSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"sm\" placeholder=\"Kichik · 32\" aria-label=\"Kichik\" />\n        <Button size=\"sm\">Qo'llash</Button>\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"md\" placeholder=\"O'rta · 40\" aria-label=\"O'rta\" />\n        <Button size=\"md\">Qo'llash</Button>\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"lg\" placeholder=\"Katta · 48\" aria-label=\"Katta\" />\n        <Button size=\"lg\">Qo'llash</Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/input/states": { component: Demo140, file: "archive/v0.1/input/states.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\n\nexport default function InputStates() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-3 sm:grid-cols-2\">\n      <Input placeholder=\"Oddiy\" aria-label=\"Oddiy\" />\n      <Input invalid defaultValue=\"sarvar@mail\" aria-label=\"Xato\" />\n      <Input disabled defaultValue=\"O'chirilgan\" aria-label=\"O'chirilgan\" />\n      <Input readOnly defaultValue=\"Faqat o'qish uchun\" aria-label=\"Faqat o'qish\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/input/with-field": { component: Demo141, file: "archive/v0.1/input/with-field.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { Mail } from 'lucide-react';\n\nexport default function InputWithField() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" required description=\"Tasdiqlash kodi SMS orqali keladi\">\n        <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" />\n      </Field>\n      <Field label=\"Email\" error=\"Email manzil noto'g'ri\">\n        <Input leftIcon={<Mail />} defaultValue=\"sarvar@mail\" clearable />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/kbd/basic": { component: Demo142, file: "archive/v0.1/kbd/basic.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdBasic() {\n  return (\n    <p className=\"text-sm text-text\">\n      Qidiruvni ochish uchun <Kbd keys={['mod', 'K']} /> ni bosing, yopish uchun <Kbd>Esc</Kbd>.\n    </p>\n  );\n}\n" },
  "archive/v0.1/kbd/keys": { component: Demo143, file: "archive/v0.1/kbd/keys.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdKeys() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Kbd keys={['mod', 'K']} />\n      <Kbd keys={['mod', 'Shift', 'P']} />\n      <Kbd keys={['Alt', 'F4']} />\n      <Kbd>Esc</Kbd>\n      <Kbd>↵</Kbd>\n      <Kbd>↑</Kbd>\n      <Kbd>↓</Kbd>\n    </div>\n  );\n}\n" },
  "archive/v0.1/kbd/menu": { component: Demo144, file: "archive/v0.1/kbd/menu.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nconst items = [\n  { label: 'Nusxa olish', keys: ['mod', 'C'] },\n  { label: \"Qo'yish\", keys: ['mod', 'V'] },\n  { label: 'Hammasini tanlash', keys: ['mod', 'A'] },\n];\n\nexport default function KbdMenu() {\n  return (\n    <ul className=\"flex w-64 flex-col rounded-lg border border-border bg-surface p-1 text-sm text-text\">\n      {items.map((item) => (\n        <li key={item.label} className=\"flex items-center justify-between rounded-md px-2 py-1.5\">\n          {item.label}\n          <Kbd keys={item.keys} />\n        </li>\n      ))}\n    </ul>\n  );\n}\n" },
  "archive/v0.1/kbd/sizes": { component: Demo145, file: "archive/v0.1/kbd/sizes.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Kbd keys={['mod', 'C']} />\n      <Kbd size=\"md\" keys={['mod', 'C']} />\n    </div>\n  );\n}\n" },
  "archive/v0.1/masked-input/card": { component: Demo146, file: "archive/v0.1/masked-input/card.tsx", source: "'use client';\n\nimport { CardInput, Field, getCardDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CardInputDemo() {\n  const [card, setCard] = useState('');\n  const { complete, valid, brand } = getCardDetails(card);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field\n        label=\"Karta raqami\"\n        error={complete && !valid ? \"Karta raqami noto'g'ri\" : undefined}\n        description={\n          valid ? `Karta to'g'ri · ${brand ?? 'boshqa'}` : \"Sinab ko'ring: 4111 1111 1111 1111\"\n        }\n      >\n        <CardInput value={card} onValueChange={setCard} />\n      </Field>\n      <div className=\"flex flex-col gap-3\">\n        <CardInput aria-label=\"Uzcard\" defaultValue=\"8600123412341234\" />\n        <CardInput aria-label=\"Humo\" defaultValue=\"9860010203040506\" />\n        <CardInput aria-label=\"Luhn xato\" defaultValue=\"4111111111111112\" />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/masked-input/custom-mask": { component: Demo147, file: "archive/v0.1/masked-input/custom-mask.tsx", source: "'use client';\n\nimport { Field, MaskedInput } from '@akhatmirzo/ui';\n\nexport default function MaskedInputCustom() {\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Avtomobil raqami\" description='mask=\"99 A 999 AA\"'>\n        <MaskedInput mask=\"99 A 999 AA\" uppercase placeholder=\"01 A 123 BC\" />\n      </Field>\n      <Field label=\"JShShIR\" description=\"14 ta raqam\">\n        <MaskedInput mask=\"99999999999999\" inputMode=\"numeric\" placeholder=\"14 raqam\" />\n      </Field>\n      <Field label=\"Vaqt\" description='mask=\"99:99\"'>\n        <MaskedInput mask=\"99:99\" inputMode=\"numeric\" placeholder=\"09:30\" />\n      </Field>\n      <Field label=\"Promo-kod\" description='mask=\"****-****\"'>\n        <MaskedInput mask=\"****-****\" uppercase placeholder=\"XXXX-XXXX\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/masked-input/money": { component: Demo148, file: "archive/v0.1/masked-input/money.tsx", source: "'use client';\n\nimport { Field, MoneyInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MoneyInputDemo() {\n  const [price, setPrice] = useState<number | null>(null);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Narx\" description={`Qiymat: ${price ?? 'null'}`}>\n        <MoneyInput value={price} onValueChange={setPrice} clearable />\n      </Field>\n      <Field label=\"Kurs\" description='decimals={2}, currency=\"$\"'>\n        <MoneyInput decimals={2} currency=\"$\" defaultValue={12.5} />\n      </Field>\n      <Field label=\"Oylik to'lov\" description=\"100 000 dan 50 000 000 gacha\">\n        <MoneyInput min={100000} max={50000000} />\n      </Field>\n      <Field label=\"Valyutasiz\" description=\"currency={null}\">\n        <MoneyInput currency={null} defaultValue={980000} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/masked-input/overview": { component: Demo149, file: "archive/v0.1/masked-input/overview.tsx", source: "'use client';\n\nimport { CardInput, Field, MaskedInput, MoneyInput, PhoneInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MaskedInputOverview() {\n  const [phone, setPhone] = useState('');\n  const [sum, setSum] = useState<number | null>(1250000);\n  const [card, setCard] = useState('');\n  const [passport, setPassport] = useState('');\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Telefon\" description={`Qiymat: \"${phone}\"`}>\n        <PhoneInput value={phone} onValueChange={setPhone} />\n      </Field>\n      <Field label=\"Summa\" description={`Qiymat: ${sum ?? 'null'}`}>\n        <MoneyInput value={sum} onValueChange={setSum} />\n      </Field>\n      <Field label=\"Karta raqami\" description={`Qiymat: \"${card}\"`}>\n        <CardInput value={card} onValueChange={setCard} />\n      </Field>\n      <Field label=\"Pasport\" description={`Qiymat: \"${passport}\"`}>\n        <MaskedInput\n          mask=\"AA 9999999\"\n          uppercase\n          placeholder=\"AB 1234567\"\n          value={passport}\n          onValueChange={setPassport}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/masked-input/phone": { component: Demo150, file: "archive/v0.1/masked-input/phone.tsx", source: "'use client';\n\nimport { Field, PhoneInput, type PhoneInputDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PhoneInputDemo() {\n  const [phone, setPhone] = useState('');\n  const [details, setDetails] = useState<PhoneInputDetails | null>(null);\n\n  const badOperator = phone.length >= 2 && !details?.operator;\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Field\n        label=\"Telefon raqami\"\n        required\n        error={badOperator ? `\"${phone.slice(0, 2)}\" — bunday operator kodi yo'q` : undefined}\n        description={\n          details?.valid ? `Operator: ${details.operator}` : '+998 90 123 45 67 ni joylang'\n        }\n      >\n        <PhoneInput\n          value={phone}\n          onValueChange={(value, info) => {\n            setPhone(value);\n            setDetails(info);\n          }}\n        />\n      </Field>\n      <PhoneInput aria-label=\"Kichik\" size=\"sm\" defaultValue=\"991234567\" />\n      <PhoneInput aria-label=\"Faqat o'qish\" readOnly defaultValue=\"935554433\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/otp-input/length": { component: Demo151, file: "archive/v0.1/otp-input/length.tsx", source: "'use client';\n\nimport { OtpInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function OtpInputLength() {\n  const [promo, setPromo] = useState('');\n\n  return (\n    <div className=\"flex flex-col items-start gap-5\">\n      <OtpInput length={4} aria-label=\"4 xonali PIN\" />\n      <OtpInput length={6} groupSize={2} aria-label=\"Juft guruhli kod\" />\n      <div className=\"flex flex-col gap-2\">\n        <OtpInput\n          type=\"alphanumeric\"\n          groupSize={3}\n          aria-label=\"Harfli kod\"\n          value={promo}\n          onValueChange={setPromo}\n        />\n        <span className=\"text-sm text-text-muted\">Qiymat: {promo || '—'}</span>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/otp-input/resend": { component: Demo152, file: "archive/v0.1/otp-input/resend.tsx", source: "'use client';\n\nimport { OtpInput, toast } from '@akhatmirzo/ui';\n\nconst sendSms = () =>\n  new Promise<void>((resolve) => {\n    setTimeout(() => {\n      toast('SMS qayta yuborildi');\n      resolve();\n    }, 800);\n  });\n\nexport default function OtpResendTimer() {\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <OtpInput.ResendTimer seconds={5} onResend={() => toast('Kod qayta yuborildi')} />\n      <OtpInput.ResendTimer\n        seconds={3}\n        labels={{ resend: 'SMS ni qayta olish' }}\n        onResend={sendSms}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.1/otp-input/states": { component: Demo153, file: "archive/v0.1/otp-input/states.tsx", source: "'use client';\n\nimport { OtpInput } from '@akhatmirzo/ui';\n\nexport default function OtpInputStates() {\n  return (\n    <div className=\"flex flex-col items-start gap-5\">\n      <OtpInput invalid defaultValue=\"482913\" groupSize={3} aria-label=\"Xato kod\" />\n      <OtpInput disabled defaultValue=\"12\" groupSize={3} aria-label=\"O'chirilgan\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/otp-input/verify": { component: Demo154, file: "archive/v0.1/otp-input/verify.tsx", source: "'use client';\n\nimport { Field, OtpInput, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CORRECT = '123456';\n\nexport default function OtpInputVerify() {\n  const [code, setCode] = useState('');\n  const [status, setStatus] = useState<'idle' | 'error' | 'ok'>('idle');\n\n  return (\n    <div className=\"flex flex-col gap-2\">\n      <Field\n        label=\"Tasdiqlash kodi\"\n        description={\n          status === 'ok' ? 'Kod tasdiqlandi' : `+998 90 *** ** 67 ga yuborildi. Kod: ${CORRECT}`\n        }\n        error={status === 'error' ? \"Kod noto'g'ri. Qayta urinib ko'ring.\" : undefined}\n      >\n        <OtpInput\n          groupSize={3}\n          value={code}\n          disabled={status === 'ok'}\n          onValueChange={(value) => {\n            setCode(value);\n            if (status === 'error') setStatus('idle');\n          }}\n          onComplete={(value) => setStatus(value === CORRECT ? 'ok' : 'error')}\n        />\n      </Field>\n      <OtpInput.ResendTimer\n        onResend={() => {\n          setCode('');\n          setStatus('idle');\n          toast('Yangi kod yuborildi');\n        }}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.1/popover/color-picker": { component: Demo155, file: "archive/v0.1/popover/color-picker.tsx", source: "'use client';\n\nimport { Button, Popover } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst colors = [\n  { name: 'Asosiy', className: 'bg-primary' },\n  { name: 'Yashil', className: 'bg-success' },\n  { name: 'Sariq', className: 'bg-warning' },\n  { name: 'Qizil', className: 'bg-danger' },\n  { name: \"Ko'k\", className: 'bg-info' },\n];\n\nexport default function PopoverColorPicker() {\n  const [color, setColor] = useState(colors[0]!);\n\n  return (\n    <Popover>\n      <Popover.Trigger asChild>\n        <Button\n          variant=\"outline\"\n          leftIcon={<span className={`size-3 rounded-full ${color.className}`} />}\n        >\n          Teg rangi\n        </Button>\n      </Popover.Trigger>\n      <Popover.Content className=\"w-auto\" aria-label=\"Rang tanlash\">\n        <div className=\"flex gap-2\">\n          {colors.map((c) => (\n            <Popover.Close key={c.name} asChild>\n              <button\n                type=\"button\"\n                aria-label={c.name}\n                aria-pressed={c.name === color.name}\n                onClick={() => setColor(c)}\n                className={`focus-ring size-7 cursor-pointer rounded-full border-2 border-surface-raised ${c.className} aria-pressed:ring-2 aria-pressed:ring-primary`}\n              />\n            </Popover.Close>\n          ))}\n        </div>\n      </Popover.Content>\n    </Popover>\n  );\n}\n" },
  "archive/v0.1/popover/filter": { component: Demo156, file: "archive/v0.1/popover/filter.tsx", source: "'use client';\n\nimport { Button, Input, Popover } from '@akhatmirzo/ui';\nimport { Funnel } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function PopoverFilter() {\n  const [open, setOpen] = useState(false);\n  const [range, setRange] = useState({ from: '', to: '' });\n  const [applied, setApplied] = useState<string | null>(null);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Popover open={open} onOpenChange={setOpen}>\n        <Popover.Trigger asChild>\n          <Button leftIcon={<Funnel />}>Narx</Button>\n        </Popover.Trigger>\n        <Popover.Content align=\"start\" aria-label=\"Narx filtri\">\n          <form\n            className=\"flex flex-col gap-3\"\n            onSubmit={(e) => {\n              e.preventDefault();\n              setApplied(`${range.from || '0'} – ${range.to || '∞'} so'm`);\n              setOpen(false);\n            }}\n          >\n            <p className=\"m-0 font-semibold\">Narx oralig'i</p>\n            <Input\n              size=\"sm\"\n              inputMode=\"numeric\"\n              placeholder=\"dan\"\n              suffix=\"so'm\"\n              aria-label=\"Narx: dan\"\n              value={range.from}\n              onChange={(e) => setRange((r) => ({ ...r, from: e.target.value }))}\n            />\n            <Input\n              size=\"sm\"\n              inputMode=\"numeric\"\n              placeholder=\"gacha\"\n              suffix=\"so'm\"\n              aria-label=\"Narx: gacha\"\n              value={range.to}\n              onChange={(e) => setRange((r) => ({ ...r, to: e.target.value }))}\n            />\n            <div className=\"mt-1 flex justify-end gap-2\">\n              <Popover.Close asChild>\n                <Button size=\"sm\">Bekor</Button>\n              </Popover.Close>\n              <Button size=\"sm\" variant=\"primary\" type=\"submit\">\n                Qo'llash\n              </Button>\n            </div>\n          </form>\n        </Popover.Content>\n      </Popover>\n      <span className=\"text-sm text-text-muted\">{applied ?? \"Filtr qo'llanmagan\"}</span>\n    </div>\n  );\n}\n" },
  "archive/v0.1/popover/placement": { component: Demo157, file: "archive/v0.1/popover/placement.tsx", source: "'use client';\n\nimport { Button, Popover } from '@akhatmirzo/ui';\n\nexport default function PopoverPlacement() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {(['top', 'right', 'bottom', 'left'] as const).map((side) => (\n        <Popover key={side}>\n          <Popover.Trigger asChild>\n            <Button variant=\"outline\">{side}</Button>\n          </Popover.Trigger>\n          <Popover.Content side={side} arrow className=\"w-56\" aria-label={`Tomon: ${side}`}>\n            <p className=\"m-0 text-text-muted\">\n              Panel <b className=\"text-text\">{side}</b> tomonda, triggerdan 6px uzoqlikda.\n            </p>\n          </Popover.Content>\n        </Popover>\n      ))}\n      <Popover>\n        <Popover.Trigger asChild>\n          <Button variant=\"outline\">align=end</Button>\n        </Popover.Trigger>\n        <Popover.Content align=\"end\" className=\"w-56\" aria-label=\"O'ngga tekislangan\">\n          <p className=\"m-0 text-text-muted\">Panel triggerning o'ng chetiga tekislangan.</p>\n        </Popover.Content>\n      </Popover>\n    </div>\n  );\n}\n" },
  "archive/v0.1/popover/settings": { component: Demo158, file: "archive/v0.1/popover/settings.tsx", source: "'use client';\n\nimport { Field, IconButton, Popover, Switch } from '@akhatmirzo/ui';\nimport { Bell } from 'lucide-react';\n\nexport default function PopoverSettings() {\n  return (\n    <Popover>\n      <Popover.Trigger asChild>\n        <IconButton variant=\"outline\" aria-label=\"Bildirishnoma sozlamalari\">\n          <Bell />\n        </IconButton>\n      </Popover.Trigger>\n      <Popover.Content side=\"right\" align=\"start\" arrow aria-label=\"Bildirishnomalar\">\n        <div className=\"flex flex-col gap-3\">\n          <p className=\"m-0 font-semibold\">Bildirishnomalar</p>\n          <Field label=\"Email orqali\" orientation=\"horizontal\">\n            <Switch defaultChecked />\n          </Field>\n          <Field label=\"SMS orqali\" orientation=\"horizontal\">\n            <Switch />\n          </Field>\n          <Field label=\"Telegram bot\" orientation=\"horizontal\">\n            <Switch defaultChecked />\n          </Field>\n        </div>\n      </Popover.Content>\n    </Popover>\n  );\n}\n" },
  "archive/v0.1/radio-group/basic": { component: Demo159, file: "archive/v0.1/radio-group/basic.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupBasic() {\n  return (\n    <RadioGroup aria-label=\"To'lov usuli\" defaultValue=\"click\">\n      <Radio value=\"click\" label=\"Click\" />\n      <Radio value=\"payme\" label=\"Payme\" />\n      <Radio value=\"cash\" label=\"Naqd pul\" />\n    </RadioGroup>\n  );\n}\n" },
  "archive/v0.1/radio-group/card": { component: Demo160, file: "archive/v0.1/radio-group/card.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RadioGroupCard() {\n  const [plan, setPlan] = useState('pro');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <RadioGroup aria-label=\"Tarif\" variant=\"card\" value={plan} onValueChange={setPlan}>\n        <Radio value=\"free\" label=\"Bepul\" description=\"1 ta do'kon, asosiy imkoniyatlar\" />\n        <Radio\n          value=\"pro\"\n          label=\"Pro · 149 000 so'm\"\n          description=\"Cheksiz do'konlar va hisobotlar\"\n        />\n        <Radio value=\"team\" label=\"Jamoa\" description=\"Tez orada\" disabled />\n      </RadioGroup>\n      <p className=\"text-sm text-text-muted\">Tanlangan tarif: {plan}</p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/radio-group/horizontal": { component: Demo161, file: "archive/v0.1/radio-group/horizontal.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupHorizontal() {\n  return (\n    <RadioGroup aria-label=\"Yetkazib berish\" orientation=\"horizontal\" defaultValue=\"express\">\n      <Radio value=\"express\" label=\"Tezkor\" />\n      <Radio value=\"standard\" label=\"Oddiy\" />\n      <Radio value=\"pickup\" label=\"Olib ketish\" />\n    </RadioGroup>\n  );\n}\n" },
  "archive/v0.1/radio-group/sizes": { component: Demo162, file: "archive/v0.1/radio-group/sizes.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-10\">\n      <RadioGroup aria-label=\"Interfeys tili (kichik)\" size=\"sm\" defaultValue=\"uz\">\n        <Radio value=\"uz\" label=\"O'zbekcha\" />\n        <Radio value=\"ru\" label=\"Ruscha\" description=\"Kirill yozuvida\" />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Interfeys tili (o'rta)\" defaultValue=\"uz\">\n        <Radio value=\"uz\" label=\"O'zbekcha\" />\n        <Radio value=\"ru\" label=\"Ruscha\" description=\"Kirill yozuvida\" />\n      </RadioGroup>\n    </div>\n  );\n}\n" },
  "archive/v0.1/radio-group/states": { component: Demo163, file: "archive/v0.1/radio-group/states.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupStates() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-10\">\n      <RadioGroup aria-label=\"Butun guruh o'chirilgan\" disabled defaultValue=\"a\">\n        <Radio value=\"a\" label=\"Tanlangan\" />\n        <Radio value=\"b\" label=\"Tanlanmagan\" />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Bitta variant o'chirilgan\">\n        <Radio value=\"a\" label=\"Omborda bor\" />\n        <Radio value=\"b\" label=\"Tugagan\" disabled />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Xato holati\" invalid>\n        <Radio value=\"yes\" label=\"Ha\" />\n        <Radio value=\"no\" label=\"Yo'q\" />\n      </RadioGroup>\n    </div>\n  );\n}\n" },
  "archive/v0.1/radio-group/with-field": { component: Demo164, file: "archive/v0.1/radio-group/with-field.tsx", source: "'use client';\n\nimport { Field, Radio, RadioGroup } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RadioGroupWithField() {\n  const [value, setValue] = useState<string>();\n\n  return (\n    <Field label=\"Yetkazib berish\" required error={value ? undefined : 'Usulni tanlang'}>\n      <RadioGroup value={value} onValueChange={setValue}>\n        <Radio value=\"courier\" label=\"Kuryer\" description=\"Ertaga, 25 000 so'm\" />\n        <Radio value=\"pickup\" label=\"Olib ketish\" description=\"Bugun, bepul\" />\n      </RadioGroup>\n    </Field>\n  );\n}\n" },
  "archive/v0.1/select/basic": { component: Demo165, file: "archive/v0.1/select/basic.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SelectBasic() {\n  const [region, setRegion] = useState('');\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field label=\"Viloyat\" description=\"Buyurtma shu viloyatga yetkaziladi\">\n        <Select value={region} onValueChange={setRegion}>\n          <Select.Item value=\"tsh\">Toshkent shahri</Select.Item>\n          <Select.Item value=\"sam\">Samarqand</Select.Item>\n          <Select.Item value=\"bux\">Buxoro</Select.Item>\n          <Select.Item value=\"and\">Andijon</Select.Item>\n          <Select.Item value=\"fer\">Farg'ona</Select.Item>\n          <Select.Item value=\"nam\">Namangan</Select.Item>\n          <Select.Item value=\"qash\">Qashqadaryo</Select.Item>\n          <Select.Item value=\"xor\">Xorazm</Select.Item>\n          <Select.Item value=\"qqr\">Qoraqalpog'iston</Select.Item>\n        </Select>\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Qiymat: <span className=\"font-medium text-text\">{region || '—'}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/select/form": { component: Demo166, file: "archive/v0.1/select/form.tsx", source: "'use client';\n\nimport { Button, Field, Select } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function SelectForm() {\n  const [error, setError] = useState<string>();\n  const [sent, setSent] = useState('—');\n\n  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    const delivery = String(new FormData(e.currentTarget).get('delivery') ?? '');\n    if (!delivery) return setError('Yetkazib berish usulini tanlang');\n    setError(undefined);\n    setSent(delivery);\n  };\n\n  return (\n    <form onSubmit={handleSubmit} className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Field label=\"Yetkazib berish\" error={error} required>\n        <Select name=\"delivery\" onValueChange={() => setError(undefined)}>\n          <Select.Item value=\"courier\">Kuryer (1 kun)</Select.Item>\n          <Select.Item value=\"pickup\">Olib ketish</Select.Item>\n          <Select.Item value=\"post\">Pochta (2–3 kun)</Select.Item>\n        </Select>\n      </Field>\n      <div className=\"flex items-center gap-3\">\n        <Button type=\"submit\" variant=\"primary\">\n          Yuborish\n        </Button>\n        <span className=\"text-sm text-text-muted\">FormData: {sent}</span>\n      </div>\n    </form>\n  );\n}\n" },
  "archive/v0.1/select/groups": { component: Demo167, file: "archive/v0.1/select/groups.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nexport default function SelectGroups() {\n  return (\n    <Field label=\"Filial\" className=\"w-full max-w-xs\">\n      <Select defaultValue=\"fer\">\n        <Select.Item value=\"tsh\">Toshkent</Select.Item>\n        <Select.Item value=\"sam\">Samarqand</Select.Item>\n        <Select.Group label=\"Vodiy\">\n          <Select.Item value=\"and\">Andijon</Select.Item>\n          <Select.Item value=\"fer\">Farg'ona</Select.Item>\n          <Select.Item value=\"nam\">Namangan</Select.Item>\n        </Select.Group>\n        <Select.Separator />\n        <Select.Group label=\"Janub\">\n          <Select.Item value=\"qash\">Qashqadaryo</Select.Item>\n          <Select.Item value=\"sur\">Surxondaryo</Select.Item>\n        </Select.Group>\n      </Select>\n    </Field>\n  );\n}\n" },
  "archive/v0.1/select/icons": { component: Demo168, file: "archive/v0.1/select/icons.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nfunction Dot({ className }: { className: string }) {\n  return <span className={`size-2 rounded-full ${className}`} />;\n}\n\nexport default function SelectIcons() {\n  return (\n    <Field label=\"Buyurtma holati\" className=\"w-full max-w-xs\">\n      <Select defaultValue=\"progress\">\n        <Select.Item value=\"new\" icon={<Dot className=\"bg-info\" />}>\n          Yangi\n        </Select.Item>\n        <Select.Item value=\"progress\" icon={<Dot className=\"bg-warning\" />}>\n          Jarayonda\n        </Select.Item>\n        <Select.Item value=\"done\" icon={<Dot className=\"bg-success\" />}>\n          Yetkazildi\n        </Select.Item>\n        <Select.Item value=\"canceled\" icon={<Dot className=\"bg-danger\" />}>\n          Bekor qilindi\n        </Select.Item>\n      </Select>\n    </Field>\n  );\n}\n" },
  "archive/v0.1/select/sizes": { component: Demo169, file: "archive/v0.1/select/sizes.tsx", source: "'use client';\n\nimport { Button, Select } from '@akhatmirzo/ui';\n\nexport default function SelectSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      {(['sm', 'md', 'lg'] as const).map((size) => (\n        <Select\n          key={size}\n          size={size}\n          aria-label={`O'lcham ${size}`}\n          placeholder={`size=\"${size}\"`}\n        >\n          <Select.Item value=\"a\">Birinchi</Select.Item>\n          <Select.Item value=\"b\">Ikkinchi</Select.Item>\n        </Select>\n      ))}\n      <div className=\"flex items-center gap-3\">\n        <Select aria-label=\"Valyuta\" defaultValue=\"uzs\" className=\"w-28\">\n          <Select.Item value=\"uzs\">UZS</Select.Item>\n          <Select.Item value=\"usd\">USD</Select.Item>\n          <Select.Item value=\"eur\">EUR</Select.Item>\n        </Select>\n        <Button variant=\"primary\">To'lash</Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/select/states": { component: Demo170, file: "archive/v0.1/select/states.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nexport default function SelectStates() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <Field label=\"O'chirilgan\" disabled>\n        <Select defaultValue=\"click\">\n          <Select.Item value=\"click\">Click</Select.Item>\n        </Select>\n      </Field>\n      <Field label=\"To'lov usuli\" error=\"To'lov usulini tanlang\" required>\n        <Select>\n          <Select.Item value=\"click\">Click</Select.Item>\n          <Select.Item value=\"payme\">Payme</Select.Item>\n        </Select>\n      </Field>\n      <Field label=\"O'chirilgan element\">\n        <Select placeholder=\"Usulni tanlang\">\n          <Select.Item value=\"click\">Click</Select.Item>\n          <Select.Item value=\"payme\">Payme</Select.Item>\n          <Select.Item value=\"uzum\" disabled>\n            Uzum (vaqtincha ishlamaydi)\n          </Select.Item>\n          <Select.Item value=\"cash\">Naqd pul</Select.Item>\n        </Select>\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/skeleton/loading-card": { component: Demo171, file: "archive/v0.1/skeleton/loading-card.tsx", source: "'use client';\n\nimport { Avatar, Button, Card, Skeleton } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SkeletonLoadingCard() {\n  const [loading, setLoading] = useState(true);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col items-start gap-3\">\n      <Button size=\"sm\" onClick={() => setLoading((l) => !l)}>\n        {loading ? \"Kontentni ko'rsatish\" : 'Yuklanish holati'}\n      </Button>\n      <Card variant=\"outline\" className=\"w-full\" aria-busy={loading}>\n        <div className=\"flex items-center gap-3\">\n          {loading ? (\n            <Skeleton variant=\"circle\" className=\"size-10\" />\n          ) : (\n            <Avatar name=\"Malika Rahimova\" />\n          )}\n          <div className=\"flex flex-1 flex-col gap-2\">\n            {loading ? (\n              <Skeleton className=\"h-4 w-2/5\" />\n            ) : (\n              <b className=\"text-sm\">Malika Rahimova</b>\n            )}\n            {loading ? (\n              <Skeleton className=\"h-3 w-1/4\" />\n            ) : (\n              <span className=\"text-xs text-text-muted\">2 soat oldin</span>\n            )}\n          </div>\n        </div>\n        {loading ? (\n          <Skeleton.Text lines={3} />\n        ) : (\n          <p className=\"text-sm\">\n            Buyurtma vaqtida yetib keldi, kuryer juda xushmuomala edi. Keyingi safar ham shu\n            do'kondan olaman.\n          </p>\n        )}\n      </Card>\n    </div>\n  );\n}\n" },
  "archive/v0.1/skeleton/shapes": { component: Demo172, file: "archive/v0.1/skeleton/shapes.tsx", source: "'use client';\n\nimport { Skeleton } from '@akhatmirzo/ui';\n\nexport default function SkeletonShapes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Skeleton variant=\"circle\" className=\"size-12\" />\n      <Skeleton className=\"h-4 w-32\" />\n      <Skeleton className=\"h-10 w-28 rounded-lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/skeleton/text": { component: Demo173, file: "archive/v0.1/skeleton/text.tsx", source: "'use client';\n\nimport { Skeleton } from '@akhatmirzo/ui';\n\nexport default function SkeletonTextDemo() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-6 sm:grid-cols-2\">\n      <Skeleton.Text lines={1} />\n      <Skeleton.Text lines={4} />\n    </div>\n  );\n}\n" },
  "archive/v0.1/spinner/colors": { component: Demo174, file: "archive/v0.1/spinner/colors.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerColors() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Spinner className=\"text-text\" />\n      <Spinner className=\"text-primary\" />\n      <Spinner className=\"text-success\" />\n      <Spinner className=\"text-danger\" />\n      <span className=\"inline-flex size-10 items-center justify-center rounded-lg bg-primary text-primary-foreground\">\n        <Spinner size=\"sm\" />\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.1/spinner/sizes": { component: Demo175, file: "archive/v0.1/spinner/sizes.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4 text-text-muted\">\n      <Spinner size=\"sm\" />\n      <Spinner size=\"md\" />\n      <Spinner size=\"lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/spinner/with-text": { component: Demo176, file: "archive/v0.1/spinner/with-text.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerWithText() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <span className=\"inline-flex items-center gap-2 text-sm text-text-muted\">\n        <Spinner size=\"sm\" aria-hidden=\"true\" />\n        Buyurtmalar yuklanmoqda...\n      </span>\n      <div className=\"flex h-32 items-center justify-center rounded-lg border border-border bg-surface text-text-muted\">\n        <Spinner size=\"lg\" label=\"Jadval yuklanmoqda\" />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/switch/basic": { component: Demo177, file: "archive/v0.1/switch/basic.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchBasic() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <Switch label=\"Bildirishnomalar\" defaultChecked />\n      <Switch label=\"Avtomatik saqlash\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/switch/controlled": { component: Demo178, file: "archive/v0.1/switch/controlled.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SwitchControlled() {\n  const [open, setOpen] = useState(true);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Switch label=\"Do'kon ochiq\" checked={open} onCheckedChange={setOpen} />\n      <span className=\"text-sm text-text-muted\">\n        {open ? 'Buyurtmalar qabul qilinmoqda' : \"Buyurtmalar to'xtatilgan\"}\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.1/switch/description": { component: Demo179, file: "archive/v0.1/switch/description.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchDescription() {\n  return (\n    <div className=\"flex max-w-sm flex-col gap-4\">\n      <Switch label=\"Qorong'i mavzu\" description=\"Tizim sozlamasidan qat'i nazar\" defaultChecked />\n      <Switch size=\"sm\" label=\"Ovozli signal\" description=\"Yangi buyurtma kelganda\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/switch/sizes": { component: Demo180, file: "archive/v0.1/switch/sizes.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-8\">\n      <Switch size=\"sm\" label=\"Kichik · 32×18\" defaultChecked />\n      <Switch size=\"md\" label=\"O'rta · 40×24\" defaultChecked />\n    </div>\n  );\n}\n" },
  "archive/v0.1/switch/states": { component: Demo181, file: "archive/v0.1/switch/states.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchStates() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <Switch label=\"O'chirilgan\" disabled />\n      <Switch label=\"O'chirilgan, yoqilgan\" disabled defaultChecked />\n      <Switch label=\"Xato\" invalid />\n    </div>\n  );\n}\n" },
  "archive/v0.1/switch/with-field": { component: Demo182, file: "archive/v0.1/switch/with-field.tsx", source: "'use client';\n\nimport { Field, Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchWithField() {\n  return (\n    <div className=\"max-w-sm\">\n      <Field label=\"Ikki bosqichli tasdiqlash\" description=\"Har kirishda SMS kod so'raladi\">\n        <Switch />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/tabs/badges": { component: Demo183, file: "archive/v0.1/tabs/badges.tsx", source: "'use client';\n\nimport { Badge, Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsBadges() {\n  return (\n    <Tabs defaultValue=\"new\">\n      <Tabs.List aria-label=\"Buyurtmalar holati\">\n        <Tabs.Trigger value=\"new\" badge={4}>\n          Yangi\n        </Tabs.Trigger>\n        <Tabs.Trigger\n          value=\"paid\"\n          badge={\n            <Badge color=\"success\" size=\"sm\">\n              +2\n            </Badge>\n          }\n        >\n          To'langan\n        </Tabs.Trigger>\n        <Tabs.Trigger value=\"canceled\" disabled>\n          Bekor qilingan\n        </Tabs.Trigger>\n      </Tabs.List>\n    </Tabs>\n  );\n}\n" },
  "archive/v0.1/tabs/controlled": { component: Demo184, file: "archive/v0.1/tabs/controlled.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst totals: Record<string, string> = {\n  day: \"1 250 000 so'm\",\n  week: \"8 740 000 so'm\",\n  month: \"36 900 000 so'm\",\n  year: \"412 500 000 so'm\",\n};\n\nexport default function TabsControlled() {\n  const [period, setPeriod] = useState('week');\n\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <Tabs value={period} onValueChange={setPeriod} variant=\"segmented\">\n        <Tabs.List aria-label=\"Davr\">\n          <Tabs.Trigger value=\"day\">Kun</Tabs.Trigger>\n          <Tabs.Trigger value=\"week\">Hafta</Tabs.Trigger>\n          <Tabs.Trigger value=\"month\">Oy</Tabs.Trigger>\n          <Tabs.Trigger value=\"year\">Yil</Tabs.Trigger>\n        </Tabs.List>\n      </Tabs>\n      <p className=\"m-0 text-sm text-text-muted\">\n        Savdo: <span className=\"font-semibold text-text\">{totals[period]}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/tabs/scrollable": { component: Demo185, file: "archive/v0.1/tabs/scrollable.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nconst months = [\n  'Yanvar',\n  'Fevral',\n  'Mart',\n  'Aprel',\n  'May',\n  'Iyun',\n  'Iyul',\n  'Avgust',\n  'Sentabr',\n  'Oktabr',\n  'Noyabr',\n  'Dekabr',\n];\n\nexport default function TabsScrollable() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Tabs defaultValue=\"Mart\">\n        <Tabs.List aria-label=\"Oylar\">\n          {months.map((m) => (\n            <Tabs.Trigger key={m} value={m}>\n              {m}\n            </Tabs.Trigger>\n          ))}\n        </Tabs.List>\n        {months.map((m) => (\n          <Tabs.Content key={m} value={m} className=\"text-text-muted\">\n            {m} oyi bo'yicha savdo hisoboti.\n          </Tabs.Content>\n        ))}\n      </Tabs>\n    </div>\n  );\n}\n" },
  "archive/v0.1/tabs/sizes": { component: Demo186, file: "archive/v0.1/tabs/sizes.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsSizes() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      {(['underline', 'pills', 'segmented'] as const).map((variant) => (\n        <Tabs key={variant} defaultValue=\"all\" variant={variant} size=\"sm\">\n          <Tabs.List aria-label=\"Holat bo'yicha\">\n            <Tabs.Trigger value=\"all\">Hammasi</Tabs.Trigger>\n            <Tabs.Trigger value=\"active\">Faol</Tabs.Trigger>\n            <Tabs.Trigger value=\"archive\">Arxiv</Tabs.Trigger>\n          </Tabs.List>\n        </Tabs>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/tabs/variants": { component: Demo187, file: "archive/v0.1/tabs/variants.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsVariants() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      {(['underline', 'pills', 'segmented'] as const).map((variant) => (\n        <Tabs key={variant} defaultValue=\"info\" variant={variant}>\n          <Tabs.List aria-label={`Mijoz (${variant})`}>\n            <Tabs.Trigger value=\"info\">Ma'lumot</Tabs.Trigger>\n            <Tabs.Trigger value=\"orders\" badge={12}>\n              Buyurtmalar\n            </Tabs.Trigger>\n            <Tabs.Trigger value=\"reviews\">Sharhlar</Tabs.Trigger>\n          </Tabs.List>\n          <Tabs.Content value=\"info\" className=\"text-text-muted\">\n            Ism, telefon va yetkazib berish manzili.\n          </Tabs.Content>\n          <Tabs.Content value=\"orders\" className=\"text-text-muted\">\n            Oxirgi 12 ta buyurtma ro'yxati.\n          </Tabs.Content>\n          <Tabs.Content value=\"reviews\" className=\"text-text-muted\">\n            Mijoz hali sharh qoldirmagan.\n          </Tabs.Content>\n        </Tabs>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/tabs/vertical": { component: Demo188, file: "archive/v0.1/tabs/vertical.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsVertical() {\n  return (\n    <Tabs defaultValue=\"profile\" orientation=\"vertical\" variant=\"pills\" className=\"w-full\">\n      <Tabs.List aria-label=\"Sozlamalar\" className=\"w-44\">\n        <Tabs.Trigger value=\"profile\">Profil</Tabs.Trigger>\n        <Tabs.Trigger value=\"security\">Xavfsizlik</Tabs.Trigger>\n        <Tabs.Trigger value=\"notifications\" badge={3}>\n          Bildirishnomalar\n        </Tabs.Trigger>\n        <Tabs.Trigger value=\"billing\" disabled>\n          To'lovlar\n        </Tabs.Trigger>\n      </Tabs.List>\n      <Tabs.Content value=\"profile\" className=\"text-text-muted\">\n        Ism, familiya va profil rasmi.\n      </Tabs.Content>\n      <Tabs.Content value=\"security\" className=\"text-text-muted\">\n        Parol va ikki bosqichli tasdiqlash.\n      </Tabs.Content>\n      <Tabs.Content value=\"notifications\" className=\"text-text-muted\">\n        SMS, email va Telegram orqali bildirishnomalar.\n      </Tabs.Content>\n    </Tabs>\n  );\n}\n" },
  "archive/v0.1/textarea/auto-resize": { component: Demo189, file: "archive/v0.1/textarea/auto-resize.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaAutoResize() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea\n        autoResize\n        minRows={2}\n        maxRows={6}\n        placeholder=\"Yozib ko'ring — maydon matn bilan birga o'sadi\"\n        aria-label=\"Xabar\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.1/textarea/basic": { component: Demo190, file: "archive/v0.1/textarea/basic.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaBasic() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea placeholder=\"Buyurtma haqida izoh qoldiring\" aria-label=\"Izoh\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/textarea/count": { component: Demo191, file: "archive/v0.1/textarea/count.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function TextareaCount() {\n  const [bio, setBio] = useState(\n    'Frontend dasturchi, Toshkent. React va TypeScript bilan ishlayman.',\n  );\n\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea\n        showCount\n        maxLength={120}\n        value={bio}\n        onChange={(e) => setBio(e.target.value)}\n        aria-label=\"O'zingiz haqingizda\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.1/textarea/states": { component: Demo192, file: "archive/v0.1/textarea/states.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaStates() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-3 sm:grid-cols-2\">\n      <Textarea minRows={2} invalid defaultValue=\"Juda qisqa\" aria-label=\"Xato\" />\n      <Textarea minRows={2} disabled defaultValue=\"O'chirilgan\" aria-label=\"O'chirilgan\" />\n      <Textarea minRows={2} readOnly defaultValue=\"Faqat o'qish uchun\" aria-label=\"Faqat o'qish\" />\n      <Textarea minRows={2} size=\"sm\" placeholder=\"Kichik o'lcham\" aria-label=\"Kichik\" />\n    </div>\n  );\n}\n" },
  "archive/v0.1/textarea/with-field": { component: Demo193, file: "archive/v0.1/textarea/with-field.tsx", source: "'use client';\n\nimport { Field, Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaWithField() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Field label=\"Izoh\" required description=\"Kuryer uchun qo'shimcha ma'lumot\">\n        <Textarea\n          autoResize\n          showCount\n          maxLength={300}\n          placeholder=\"Masalan: 3-podyezd, domofon ishlamaydi\"\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.1/theming/brand": { component: Demo194, file: "archive/v0.1/theming/brand.tsx", source: "'use client';\n\nimport { Badge, Button, Field, Input, Switch } from '@akhatmirzo/ui';\nimport { useState, type CSSProperties } from 'react';\n\nconst BRANDS = ['indigo', 'emerald', 'sky', 'rose'] as const;\n\n// Brend rangini faqat shu blok ichida almashtiramiz. color-mix — light va dark'da birdek ishlaydi.\nconst brandVars = (c: string) =>\n  ({\n    '--ak-primary': `var(--ak-${c}-600)`,\n    '--ak-primary-hover': `var(--ak-${c}-700)`,\n    '--ak-primary-soft': `color-mix(in srgb, var(--ak-${c}-500) 14%, var(--ak-surface))`,\n    '--ak-primary-soft-hover': `color-mix(in srgb, var(--ak-${c}-500) 22%, var(--ak-surface))`,\n    '--ak-primary-soft-foreground': `color-mix(in srgb, var(--ak-${c}-600) 65%, var(--ak-text))`,\n    '--ak-ring': `color-mix(in srgb, var(--ak-${c}-500) 45%, transparent)`,\n  }) as CSSProperties;\n\nexport default function ThemingBrand() {\n  const [brand, setBrand] = useState<(typeof BRANDS)[number]>('emerald');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <div className=\"flex flex-wrap gap-2\">\n        {BRANDS.map((b) => (\n          <Button\n            key={b}\n            size=\"sm\"\n            variant={b === brand ? 'outline' : 'ghost'}\n            onClick={() => setBrand(b)}\n          >\n            {b}\n          </Button>\n        ))}\n      </div>\n      <div\n        style={brandVars(brand)}\n        className=\"flex flex-col gap-4 rounded-xl border border-border bg-surface p-5\"\n      >\n        <Field label=\"Telefon\">\n          <Input placeholder=\"+998 90 123 45 67\" />\n        </Field>\n        <Switch defaultChecked label=\"Yangiliklarga obuna\" />\n        <div className=\"flex flex-wrap items-center gap-2\">\n          <Button variant=\"primary\">Saqlash</Button>\n          <Button>Bekor qilish</Button>\n          <Badge color=\"primary\">Yangi</Badge>\n        </div>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/theming/motion": { component: Demo195, file: "archive/v0.1/theming/motion.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst EASINGS = [\n  ['ease-out', 'Kirishlar (asosiy)'],\n  ['ease-in', 'Chiqishlar'],\n  ['ease-in-out', \"Joyida o'zgarish\"],\n  ['ease-spring', 'Toast, switch'],\n];\n\nexport default function ThemingMotion() {\n  const [on, setOn] = useState(false);\n\n  return (\n    <div className=\"flex w-full max-w-lg flex-col gap-4\">\n      <Button size=\"sm\" variant=\"primary\" className=\"self-start\" onClick={() => setOn((v) => !v)}>\n        {on ? 'Qaytarish' : 'Ishga tushirish'}\n      </Button>\n      {EASINGS.map(([easing, note]) => (\n        <div key={easing} className=\"flex items-center gap-3\">\n          <div className=\"flex w-28 shrink-0 flex-col text-xs\">\n            <code className=\"font-mono text-text\">{easing}</code>\n            <span className=\"text-text-muted\">{note}</span>\n          </div>\n          <div className=\"relative h-6 flex-1 rounded-full bg-surface-muted\">\n            {/* Qatlam kengligi = yo'lak − sharcha, shuning uchun translate-x-full oxirigacha olib boradi */}\n            <div\n              className={`absolute inset-y-0 left-0 w-[calc(100%-1.5rem)] transition-transform duration-slow ${easing} ${on ? 'translate-x-full' : ''}`}\n            >\n              <div className=\"size-6 rounded-full bg-primary\" />\n            </div>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/theming/palette": { component: Demo196, file: "archive/v0.1/theming/palette.tsx", source: "'use client';\n\nimport { useSyncExternalStore } from 'react';\n\nconst SCALES = {\n  indigo: ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900', '950'],\n  slate: ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900', '950'],\n  emerald: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  amber: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  rose: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  sky: ['50', '100', '300', '400', '500', '600', '700', '950'],\n};\n\nconst subscribe = () => () => {};\n// CSS o'zgaruvchilarning haqiqiy qiymatlari (serverda — bo'sh)\nconst readValues = () => {\n  const style = getComputedStyle(document.documentElement);\n  return Object.entries(SCALES)\n    .flatMap(([name, steps]) =>\n      steps.map((s) => style.getPropertyValue(`--ak-${name}-${s}`).trim()),\n    )\n    .join(',');\n};\n\nexport default function ThemingPalette() {\n  const values = useSyncExternalStore(subscribe, readValues, () => '').split(',');\n  let index = 0;\n\n  return (\n    <div className=\"flex w-full flex-col gap-5\">\n      {Object.entries(SCALES).map(([name, steps]) => (\n        <div key={name} className=\"flex flex-col gap-2\">\n          <span className=\"text-sm font-semibold text-text\">{name}</span>\n          <div className=\"grid grid-cols-4 gap-2 sm:grid-cols-6 lg:grid-cols-11\">\n            {steps.map((step) => {\n              const value = values[index++];\n              return (\n                <div key={step} className=\"flex flex-col gap-1\">\n                  <div\n                    className=\"h-10 rounded-md border border-border\"\n                    style={{ background: `var(--ak-${name}-${step})` }}\n                  />\n                  <span className=\"text-xs font-medium text-text\">{step}</span>\n                  <span className=\"font-mono text-xs text-text-muted uppercase\">{value}</span>\n                </div>\n              );\n            })}\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/theming/radius-shadow": { component: Demo197, file: "archive/v0.1/theming/radius-shadow.tsx", source: "'use client';\n\nconst RADII = [\n  ['rounded-sm', '6px'],\n  ['rounded-md', '8px'],\n  ['rounded-lg', '12px'],\n  ['rounded-xl', '16px'],\n  ['rounded-2xl', '20px'],\n  ['rounded-full', '9999px'],\n];\n\nconst SHADOWS = [\n  ['shadow-xs', 'Input, tugma'],\n  ['shadow-sm', 'Karta'],\n  ['shadow-md', 'Dropdown'],\n  ['shadow-lg', 'Popover, toast'],\n  ['shadow-xl', 'Modal, drawer'],\n];\n\nexport default function ThemingRadiusShadow() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      <div className=\"grid grid-cols-3 gap-4 sm:grid-cols-6\">\n        {RADII.map(([className, value]) => (\n          <div key={className} className=\"flex flex-col items-center gap-2 text-xs\">\n            <div className={`size-14 border-2 border-primary bg-primary-soft ${className}`} />\n            <code className=\"font-mono text-text\">{className}</code>\n            <span className=\"text-text-muted\">{value}</span>\n          </div>\n        ))}\n      </div>\n      <div className=\"grid grid-cols-2 gap-5 sm:grid-cols-5\">\n        {SHADOWS.map(([className, note]) => (\n          <div\n            key={className}\n            className={`flex h-20 flex-col items-center justify-center rounded-xl bg-surface-raised text-xs ${className}`}\n          >\n            <code className=\"font-mono text-text\">{className}</code>\n            <span className=\"text-text-muted\">{note}</span>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.1/theming/scoped": { component: Demo198, file: "archive/v0.1/theming/scoped.tsx", source: "'use client';\n\nimport { Badge, Button, Field, Input } from '@akhatmirzo/ui';\n\n// data-theme istalgan elementga qo'yiladi — tokenlar faqat shu blok ichida almashadi\nexport default function ThemingScoped() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-2\">\n      {(['light', 'dark'] as const).map((theme) => (\n        <div\n          key={theme}\n          data-theme={theme}\n          className=\"flex flex-col gap-4 rounded-xl border border-border bg-background p-5 text-text\"\n        >\n          <div className=\"flex items-center justify-between\">\n            <span className=\"text-sm font-semibold\">data-theme=\"{theme}\"</span>\n            <Badge color=\"success\" dot>\n              Faol\n            </Badge>\n          </div>\n          <Field label=\"Ism\">\n            <Input placeholder=\"Sarvar\" />\n          </Field>\n          <div className=\"flex gap-2\">\n            <Button variant=\"primary\">Saqlash</Button>\n            <Button variant=\"outline\">Bekor qilish</Button>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/theming/semantic": { component: Demo199, file: "archive/v0.1/theming/semantic.tsx", source: "'use client';\n\nimport { useSyncExternalStore } from 'react';\n\nconst TOKENS = [\n  ['background', 'Sahifa foni'],\n  ['surface', 'Karta, input, modal'],\n  ['surface-muted', 'Hover, ikkilamchi fon'],\n  ['surface-raised', 'Popover, toast'],\n  ['border', 'Oddiy chegara'],\n  ['border-strong', 'Hover chegara'],\n  ['text', 'Asosiy matn'],\n  ['text-subtle', 'Ghost tugma, ikonka'],\n  ['text-muted', 'Yordamchi matn'],\n  ['text-faint', 'Placeholder'],\n  ['primary', 'Asosiy tugma'],\n  ['primary-soft', 'Soft tugma, badge'],\n  ['primary-soft-foreground', 'Soft ustidagi matn'],\n  ['link', 'Havola'],\n  ['danger', 'Xavfli tugma'],\n  ['ring', 'Fokus halqasi'],\n] as const;\n\n// Mavzu almashganda (<html data-theme>) qiymatlar qayta o'qiladi\nconst subscribe = (onChange: () => void) => {\n  const observer = new MutationObserver(onChange);\n  observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });\n  return () => observer.disconnect();\n};\nconst readValues = () => {\n  const style = getComputedStyle(document.documentElement);\n  return TOKENS.map(([token]) => style.getPropertyValue(`--ak-${token}`).trim()).join('|');\n};\n\nexport default function ThemingSemantic() {\n  const values = useSyncExternalStore(subscribe, readValues, () => '').split('|');\n\n  return (\n    <div className=\"grid w-full gap-3 sm:grid-cols-2\">\n      {TOKENS.map(([token, note], i) => (\n        <div key={token} className=\"flex items-center gap-3\">\n          <div\n            className=\"size-10 shrink-0 rounded-lg border border-border\"\n            style={{ background: `var(--ak-${token})` }}\n          />\n          <div className=\"flex min-w-0 flex-col text-xs\">\n            <span className=\"truncate font-mono font-medium text-text\">{token}</span>\n            <span className=\"truncate text-text-muted\">{note}</span>\n            <span className=\"truncate font-mono text-text-faint\">{values[i] || '—'}</span>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/theming/status": { component: Demo200, file: "archive/v0.1/theming/status.tsx", source: "'use client';\n\nconst STATUSES = ['success', 'warning', 'danger', 'info'] as const;\n\nconst SOFT = {\n  success: 'bg-success-soft text-success-soft-foreground',\n  warning: 'bg-warning-soft text-warning-soft-foreground',\n  danger: 'bg-danger-soft text-danger-soft-foreground',\n  info: 'bg-info-soft text-info-soft-foreground',\n};\nconst SOLID = {\n  success: 'bg-success text-success-foreground',\n  warning: 'bg-warning text-warning-foreground',\n  danger: 'bg-danger text-danger-foreground',\n  info: 'bg-info text-info-foreground',\n};\n\nexport default function ThemingStatus() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      {[SOFT, SOLID].map((styles, row) => (\n        <div key={row} className=\"flex flex-wrap items-center gap-2\">\n          <code className=\"w-12 font-mono text-xs text-text-muted\">\n            {row === 0 ? 'soft' : 'solid'}\n          </code>\n          {STATUSES.map((status) => (\n            <span\n              key={status}\n              className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${styles[status]}`}\n            >\n              {status}\n            </span>\n          ))}\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/theming/typography": { component: Demo201, file: "archive/v0.1/theming/typography.tsx", source: "'use client';\n\nconst SCALE = [\n  { className: 'text-4xl font-bold', name: 'text-4xl', spec: '36 / 40' },\n  { className: 'text-3xl font-bold', name: 'text-3xl', spec: '30 / 36' },\n  { className: 'text-2xl font-semibold', name: 'text-2xl', spec: '24 / 32' },\n  { className: 'text-xl font-semibold', name: 'text-xl', spec: '20 / 28' },\n  { className: 'text-lg font-medium', name: 'text-lg', spec: '18 / 28' },\n  { className: 'text-base', name: 'text-base', spec: '16 / 24' },\n  { className: 'text-sm', name: 'text-sm', spec: '14 / 20' },\n  { className: 'text-xs font-medium', name: 'text-xs', spec: '12 / 16' },\n];\n\nexport default function ThemingTypography() {\n  return (\n    <div className=\"flex w-full flex-col divide-y divide-border\">\n      {SCALE.map((item) => (\n        <div key={item.name} className=\"flex items-baseline gap-4 py-2\">\n          <div className=\"flex w-24 shrink-0 flex-col\">\n            <code className=\"font-mono text-xs text-text\">{item.name}</code>\n            <span className=\"text-xs text-text-muted\">{item.spec}</span>\n          </div>\n          <p className={`${item.className} truncate text-text`}>O'zbekiston — Ўзбекистон</p>\n        </div>\n      ))}\n      <p className=\"pt-3 font-mono text-sm text-text-muted\">font-mono: 1 250 000 so'm · +998 90</p>\n    </div>\n  );\n}\n" },
  "archive/v0.1/toast/action": { component: Demo202, file: "archive/v0.1/toast/action.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastAction() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.success('Buyurtma yaratildi', {\n            description: \"#1042 · 1 250 000 so'm\",\n            action: { label: \"Ko'rish\", onClick: () => toast.info('Buyurtma #1042 ochildi') },\n          })\n        }\n      >\n        Amal bilan\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast(\"Mahsulot o'chirildi\", {\n            description: 'iPhone 15 Pro, 256 GB',\n            action: {\n              label: 'Qaytarish',\n              onClick: () => toast.success('Mahsulot qaytarildi'),\n            },\n          })\n        }\n      >\n        Bekor qilish (undo)\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/toast/promise": { component: Demo203, file: "archive/v0.1/toast/promise.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nasync function saveOrder() {\n  await wait(1500);\n  return 1042;\n}\n\nasync function failingRequest(): Promise<void> {\n  await wait(1200);\n  throw new Error('Server javob bermadi');\n}\n\nexport default function ToastPromise() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.promise(saveOrder, {\n            loading: 'Saqlanmoqda...',\n            success: (id) => `Buyurtma #${id} saqlandi`,\n            error: 'Xatolik yuz berdi',\n          })\n        }\n      >\n        Muvaffaqiyatli\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast\n            .promise(failingRequest, {\n              loading: 'Yuborilmoqda...',\n              success: 'Yuborildi',\n              error: (e) => `Xatolik: ${(e as Error).message}`,\n            })\n            .catch(() => {})\n        }\n      >\n        Xato bilan\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/toast/stack": { component: Demo204, file: "archive/v0.1/toast/stack.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastStack() {\n  const burst = () => {\n    toast.info(\"Yangi mijoz ro'yxatdan o'tdi\");\n    toast.success(\"To'lov qabul qilindi\", { description: \"350 000 so'm\" });\n    toast.warning('Omborda 3 ta qoldi');\n    toast('Yangi sharh qoldirildi');\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button variant=\"outline\" onClick={burst}>\n        4 tasini birdan\n      </Button>\n      <Button variant=\"ghost\" onClick={() => toast.dismiss()}>\n        Hammasini yopish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/toast/types": { component: Demo205, file: "archive/v0.1/toast/types.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastTypes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button variant=\"outline\" onClick={() => toast('Havola nusxalandi')}>\n        Oddiy\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.success(\"O'zgarishlar saqlandi\")}>\n        success\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.error(\"Ulanib bo'lmadi\", {\n            description: \"Internetni tekshirib, qayta urinib ko'ring.\",\n          })\n        }\n      >\n        error\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.warning('Obuna 3 kundan keyin tugaydi', {\n            description: \"To'lovni oldindan qiling.\",\n          })\n        }\n      >\n        warning\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.info('Yangi versiya mavjud')}>\n        info\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.loading('Hisobot tayyorlanmoqda...')}>\n        loading\n      </Button>\n      <Button variant=\"ghost\" onClick={() => toast.dismiss()}>\n        Hammasini yopish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.1/toast/update": { component: Demo206, file: "archive/v0.1/toast/update.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function ToastUpdate() {\n  const upload = async () => {\n    const id = toast.loading('Fayl yuklanmoqda...', { description: 'hisobot.xlsx' });\n    await wait(1000);\n    toast.loading('Fayl tekshirilmoqda...', { id, description: 'hisobot.xlsx' });\n    await wait(1000);\n    toast.success('Fayl yuklandi', { id, description: 'hisobot.xlsx · 2,4 MB' });\n  };\n\n  return (\n    <Button variant=\"outline\" onClick={upload}>\n      Faylni yuklash\n    </Button>\n  );\n}\n" },
  "archive/v0.1/tooltip/basic": { component: Demo207, file: "archive/v0.1/tooltip/basic.tsx", source: "'use client';\n\nimport { IconButton, Tooltip } from '@akhatmirzo/ui';\nimport { Copy, Heart, Share2, Trash2 } from 'lucide-react';\n\nexport default function TooltipBasic() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Tooltip content=\"Nusxa olish\" shortcut={['mod', 'C']}>\n        <IconButton variant=\"outline\" aria-label=\"Nusxa olish\">\n          <Copy />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"Ulashish\">\n        <IconButton variant=\"outline\" aria-label=\"Ulashish\">\n          <Share2 />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"Sevimlilarga qo'shish\">\n        <IconButton variant=\"outline\" aria-label=\"Sevimlilarga qo'shish\">\n          <Heart />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"O'chirish\" shortcut={['Del']}>\n        <IconButton variant=\"ghost\" aria-label=\"O'chirish\">\n          <Trash2 />\n        </IconButton>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "archive/v0.1/tooltip/controlled": { component: Demo208, file: "archive/v0.1/tooltip/controlled.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function TooltipControlled() {\n  const [open, setOpen] = useState(false);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"outline\" onClick={() => setOpen((o) => !o)}>\n        {open ? 'Yashirish' : \"Ko'rsatish\"}\n      </Button>\n      <Tooltip content=\"Boshqariladigan tooltip\" open={open} onOpenChange={setOpen}>\n        <Button>Nishon</Button>\n      </Tooltip>\n      <Tooltip content=\"Bu matn chiqmaydi\" disabled>\n        <Button>disabled</Button>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "archive/v0.1/tooltip/delay": { component: Demo209, file: "archive/v0.1/tooltip/delay.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipDelay() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Tooltip content=\"Darhol chiqadi\" delay={0}>\n        <Button>delay=0</Button>\n      </Tooltip>\n      <Tooltip content=\"Bir soniya kutadi\" delay={1000}>\n        <Button>delay=1000</Button>\n      </Tooltip>\n      <Tooltip content=\"Uzun izoh 240px dan oshsa, keyingi qatorga o'raladi: buyurtma holati har 5 daqiqada yangilanadi.\">\n        <Button>Uzun matn</Button>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "archive/v0.1/tooltip/disabled-button": { component: Demo210, file: "archive/v0.1/tooltip/disabled-button.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipDisabledButton() {\n  return (\n    <Tooltip content=\"Ruxsat yo'q: faqat administrator saqlay oladi\">\n      <span tabIndex={0} className=\"focus-ring inline-flex rounded-lg\">\n        <Button variant=\"primary\" disabled>\n          Saqlash\n        </Button>\n      </span>\n    </Tooltip>\n  );\n}\n" },
  "archive/v0.1/tooltip/sides": { component: Demo211, file: "archive/v0.1/tooltip/sides.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipSides() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {(['top', 'right', 'bottom', 'left'] as const).map((side) => (\n        <Tooltip key={side} content={`Tomon: ${side}`} side={side}>\n          <Button variant=\"outline\">{side}</Button>\n        </Tooltip>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.1/virtual-list/basic": { component: Demo212, file: "archive/v0.1/virtual-list/basic.tsx", source: "'use client';\n\nimport { Badge, Button, Input, VirtualList, type VirtualListHandle } from '@akhatmirzo/ui';\nimport { useMemo, useRef, useState } from 'react';\n\nconst LEVELS = [\n  { label: 'Info', color: 'info', text: 'Foydalanuvchi tizimga kirdi' },\n  { label: 'Tayyor', color: 'success', text: \"To'lov qabul qilindi\" },\n  { label: 'Ogohlantirish', color: 'warning', text: 'Omborda mahsulot kam qoldi' },\n  { label: 'Xato', color: 'danger', text: \"SMS yuborib bo'lmadi\" },\n] as const;\n\nexport default function VirtualListBasic() {\n  const logs = useMemo(\n    () => Array.from({ length: 10_000 }, (_, i) => ({ id: i + 1, ...LEVELS[i % LEVELS.length]! })),\n    [],\n  );\n  const ref = useRef<VirtualListHandle>(null);\n  const [target, setTarget] = useState('5000');\n\n  const go = () => ref.current?.scrollToIndex(Number(target) - 1, { align: 'start' });\n\n  return (\n    <div className=\"flex w-full flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Input\n          aria-label=\"Qator raqami\"\n          inputMode=\"numeric\"\n          value={target}\n          onChange={(e) => setTarget(e.target.value.replace(/\\D/g, ''))}\n          onKeyDown={(e) => e.key === 'Enter' && go()}\n          className=\"w-28\"\n        />\n        <Button variant=\"soft\" onClick={go}>\n          Qatorga o'tish\n        </Button>\n      </div>\n      <VirtualList\n        ref={ref}\n        aria-label=\"Tizim jurnali\"\n        items={logs}\n        estimateSize={48}\n        height={400}\n        overscan={8}\n        getItemKey={(log) => log.id}\n        className=\"rounded-xl border border-border bg-surface\"\n        renderItem={(log) => (\n          <div className=\"flex h-12 items-center gap-3 border-b border-border px-4 text-sm\">\n            <span className=\"w-14 shrink-0 text-text-faint tabular-nums\">#{log.id}</span>\n            <Badge color={log.color}>{log.label}</Badge>\n            <span className=\"min-w-0 flex-1 truncate\">{log.text}</span>\n          </div>\n        )}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.1/virtual-list/dynamic": { component: Demo213, file: "archive/v0.1/virtual-list/dynamic.tsx", source: "'use client';\n\nimport { Avatar, VirtualList } from '@akhatmirzo/ui';\n\nconst NAMES = ['Aziza Karimova', 'Bobur Toshmatov', \"G'ayrat Usmonov\", 'Malika Yusupova'];\nconst TEXTS = [\n  'Assalomu alaykum!',\n  \"Buyurtmam qachon yetib keladi? Kecha to'lov qilgan edim.\",\n  \"Yetkazish manzilini o'zgartirsam bo'ladimi? Hozir Samarqanddaman, kuryer oldindan qo'ng'iroq qilsin.\",\n  'Ha, albatta.',\n  \"Rahmat, mahsulot juda yoqdi. Qadoqlash ham a'lo darajada edi, do'stlarimga ham tavsiya qilaman.\",\n];\n\nconst messages = Array.from({ length: 2000 }, (_, i) => ({\n  id: i,\n  author: NAMES[(i * 3) % NAMES.length]!,\n  text: TEXTS[(i * 2 + (i >> 2)) % TEXTS.length]!,\n}));\n\nexport default function VirtualListDynamic() {\n  return (\n    <VirtualList\n      dynamic\n      aria-label=\"Mijozlar bilan yozishmalar\"\n      items={messages}\n      estimateSize={72}\n      height={400}\n      getItemKey={(m) => m.id}\n      className=\"w-full rounded-xl border border-border bg-surface\"\n      renderItem={(m) => (\n        <div className=\"flex gap-3 border-b border-border px-4 py-3\">\n          <Avatar name={m.author} size=\"sm\" />\n          <div className=\"flex min-w-0 flex-col gap-0.5\">\n            <span className=\"text-sm font-medium\">{m.author}</span>\n            <p className=\"m-0 text-sm text-text-muted\">{m.text}</p>\n          </div>\n        </div>\n      )}\n    />\n  );\n}\n" },
  "archive/v0.1/virtual-list/empty": { component: Demo214, file: "archive/v0.1/virtual-list/empty.tsx", source: "'use client';\n\nimport { VirtualList } from '@akhatmirzo/ui';\n\nexport default function VirtualListEmpty() {\n  return (\n    <VirtualList\n      aria-label=\"Bildirishnomalar\"\n      items={[]}\n      estimateSize={48}\n      height={160}\n      renderItem={() => null}\n      emptyState=\"Hali bildirishnomalar yo'q\"\n      className=\"w-full max-w-md rounded-xl border border-border bg-surface\"\n    />\n  );\n}\n" },
  "archive/v0.1/virtual-list/infinite": { component: Demo215, file: "archive/v0.1/virtual-list/infinite.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { VirtualList } from '@akhatmirzo/ui';\nimport { useCallback, useState } from 'react';\n\nconst PAGE = 40;\nconst TOTAL = 400;\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\n\nconst makeOrders = (from: number) =>\n  Array.from({ length: PAGE }, (_, i) => {\n    const id = from + i + 1;\n    return {\n      id,\n      customer: NAMES[id % NAMES.length]!,\n      total: ((id * 7919) % 90) * 15_000 + 150_000,\n    };\n  });\n\nexport default function VirtualListInfinite() {\n  const [orders, setOrders] = useState(() => makeOrders(0));\n  const [loading, setLoading] = useState(false);\n\n  const loadMore = useCallback(() => {\n    if (orders.length >= TOTAL) return;\n    setLoading(true);\n    // Haqiqiy loyihada — fetch(`/api/orders?offset=${orders.length}`)\n    setTimeout(() => {\n      setOrders((prev) => [...prev, ...makeOrders(prev.length)]);\n      setLoading(false);\n    }, 900);\n  }, [orders.length]);\n\n  return (\n    <div className=\"flex w-full flex-col gap-2\">\n      <p className=\"m-0 text-sm text-text-muted\">\n        Yuklangan: {orders.length} / {TOTAL}\n      </p>\n      <VirtualList\n        aria-label=\"Buyurtmalar\"\n        items={orders}\n        estimateSize={52}\n        height={360}\n        loadingMore={loading}\n        onEndReached={loadMore}\n        getItemKey={(o) => o.id}\n        labels={{ loadingMore: 'Buyurtmalar yuklanmoqda...' }}\n        className=\"rounded-xl border border-border bg-surface\"\n        renderItem={(o) => (\n          <div className=\"flex h-13 items-center gap-3 border-b border-border px-4 text-sm\">\n            <span className=\"w-14 shrink-0 text-text-faint tabular-nums\">№{o.id}</span>\n            <span className=\"min-w-0 flex-1 truncate\">{o.customer}</span>\n            <span className=\"shrink-0 font-medium tabular-nums\">{formatMoney(o.total)}</span>\n          </div>\n        )}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/accordion/basic": { component: Demo216, file: "archive/v0.2/accordion/basic.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nconst faq = [\n  {\n    value: 'delivery',\n    title: 'Yetkazib berish qancha vaqt oladi?',\n    body: \"Toshkent bo'ylab 1 kun, viloyatlarga 2–3 ish kuni.\",\n  },\n  {\n    value: 'payment',\n    title: \"Qanday to'lov usullari bor?\",\n    body: \"Click, Payme, Uzum va naqd pul. Karta orqali to'lov darhol tasdiqlanadi.\",\n  },\n  {\n    value: 'return',\n    title: \"Mahsulotni qaytarsa bo'ladimi?\",\n    body: \"Ha, 14 kun ichida, qadoq buzilmagan bo'lsa.\",\n  },\n];\n\nexport default function AccordionBasic() {\n  return (\n    <Accordion defaultValue=\"delivery\" className=\"max-w-xl\">\n      {faq.map((q) => (\n        <Accordion.Item key={q.value} value={q.value} title={q.title}>\n          {q.body}\n        </Accordion.Item>\n      ))}\n    </Accordion>\n  );\n}\n" },
  "archive/v0.2/accordion/composition": { component: Demo217, file: "archive/v0.2/accordion/composition.tsx", source: "'use client';\n\nimport { Accordion, Badge } from '@akhatmirzo/ui';\n\nexport default function AccordionComposition() {\n  return (\n    <Accordion variant=\"bordered\" className=\"max-w-xl\">\n      <Accordion.Item value=\"notifications\">\n        <Accordion.Trigger>\n          <span className=\"flex items-center gap-2\">\n            Bildirishnomalar\n            <Badge color=\"primary\" size=\"sm\">\n              3 ta yangi\n            </Badge>\n          </span>\n        </Accordion.Trigger>\n        <Accordion.Content>\n          <ul className=\"m-0 flex list-disc flex-col gap-1 pl-5\">\n            <li>Buyurtma #1042 yetkazildi</li>\n            <li>Yangi sharh qoldirildi</li>\n            <li>To'lov qabul qilindi</li>\n          </ul>\n        </Accordion.Content>\n      </Accordion.Item>\n      <Accordion.Item value=\"security\">\n        <Accordion.Trigger>Xavfsizlik</Accordion.Trigger>\n        <Accordion.Content>Parolni oxirgi marta 3 oy oldin o'zgartirgansiz.</Accordion.Content>\n      </Accordion.Item>\n      <Accordion.Item value=\"billing\" disabled>\n        <Accordion.Trigger>To'lov ma'lumotlari (tez orada)</Accordion.Trigger>\n        <Accordion.Content>—</Accordion.Content>\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "archive/v0.2/accordion/controlled": { component: Demo218, file: "archive/v0.2/accordion/controlled.tsx", source: "'use client';\n\nimport { Accordion, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst sections = [\n  { value: 'profile', title: \"Shaxsiy ma'lumotlar\", body: \"Ism, telefon va tug'ilgan sana.\" },\n  { value: 'address', title: 'Manzillar', body: 'Uy: Toshkent, Chilonzor tumani, 9-mavze.' },\n  { value: 'cards', title: \"To'lov kartalari\", body: 'Uzcard •• 4521, Humo •• 9087.' },\n];\n\nexport default function AccordionControlled() {\n  const [open, setOpen] = useState<string[]>(['profile']);\n\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <div className=\"flex flex-wrap gap-2\">\n        <Button size=\"sm\" variant=\"outline\" onClick={() => setOpen(sections.map((s) => s.value))}>\n          Hammasini ochish\n        </Button>\n        <Button size=\"sm\" variant=\"outline\" onClick={() => setOpen([])}>\n          Hammasini yopish\n        </Button>\n      </div>\n      <Accordion type=\"multiple\" value={open} onValueChange={setOpen}>\n        {sections.map((s) => (\n          <Accordion.Item key={s.value} value={s.value} title={s.title}>\n            {s.body}\n          </Accordion.Item>\n        ))}\n      </Accordion>\n    </div>\n  );\n}\n" },
  "archive/v0.2/accordion/multiple": { component: Demo219, file: "archive/v0.2/accordion/multiple.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionMultiple() {\n  return (\n    <Accordion type=\"multiple\" defaultValue={['delivery', 'payment']} className=\"max-w-xl\">\n      <Accordion.Item value=\"delivery\" title=\"Yetkazib berish qancha vaqt oladi?\">\n        Toshkent bo'ylab 1 kun, viloyatlarga 2–3 ish kuni.\n      </Accordion.Item>\n      <Accordion.Item value=\"payment\" title=\"Qanday to'lov usullari bor?\">\n        Click, Payme, Uzum va naqd pul.\n      </Accordion.Item>\n      <Accordion.Item value=\"return\" title=\"Mahsulotni qaytarsa bo'ladimi?\">\n        Ha, 14 kun ichida, qadoq buzilmagan bo'lsa.\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "archive/v0.2/accordion/non-collapsible": { component: Demo220, file: "archive/v0.2/accordion/non-collapsible.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionNonCollapsible() {\n  return (\n    <Accordion collapsible={false} defaultValue=\"courier\" variant=\"bordered\" className=\"max-w-xl\">\n      <Accordion.Item value=\"courier\" title=\"Kuryer orqali\">\n        Ertasi kuni eshigingizgacha. Narxi — 25 000 so'm.\n      </Accordion.Item>\n      <Accordion.Item value=\"pickup\" title=\"Olib ketish punktidan\">\n        Toshkentdagi 12 ta punktdan bepul olib ketasiz.\n      </Accordion.Item>\n      <Accordion.Item value=\"post\" title=\"Pochta orqali\">\n        Viloyatlarga 2–3 ish kuni. Narxi — 18 000 so'm.\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "archive/v0.2/accordion/variants": { component: Demo221, file: "archive/v0.2/accordion/variants.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionVariants() {\n  return (\n    <div className=\"grid w-full gap-6 md:grid-cols-3\">\n      {(['separated', 'bordered', 'ghost'] as const).map((variant) => (\n        <div key={variant} className=\"flex flex-col gap-2\">\n          <span className=\"text-xs font-medium text-text-muted\">{variant}</span>\n          <Accordion variant={variant} defaultValue=\"a\">\n            <Accordion.Item value=\"a\" title=\"Yetkazib berish\">\n              Toshkent bo'ylab 1 kun.\n            </Accordion.Item>\n            <Accordion.Item value=\"b\" title=\"To'lov\">\n              Click, Payme yoki naqd.\n            </Accordion.Item>\n            <Accordion.Item value=\"c\" title=\"Qaytarish\">\n              14 kun ichida.\n            </Accordion.Item>\n          </Accordion>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/alert/actions": { component: Demo222, file: "archive/v0.2/alert/actions.tsx", source: "'use client';\n\nimport { Alert, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function AlertActions() {\n  const [open, setOpen] = useState(true);\n\n  if (!open) {\n    return (\n      <Button size=\"sm\" onClick={() => setOpen(true)}>\n        Xabarni qaytarish\n      </Button>\n    );\n  }\n\n  return (\n    <Alert\n      className=\"max-w-xl\"\n      color=\"danger\"\n      title=\"To'lov o'tmadi\"\n      action={\n        <Button size=\"sm\" variant=\"outline\">\n          Qayta urinish\n        </Button>\n      }\n      onClose={() => setOpen(false)}\n    >\n      Bank to'lovni rad etdi. Karta ma'lumotlarini tekshiring.\n    </Alert>\n  );\n}\n" },
  "archive/v0.2/alert/banner": { component: Demo223, file: "archive/v0.2/alert/banner.tsx", source: "'use client';\n\nimport { Alert, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function AlertBanner() {\n  const [open, setOpen] = useState(true);\n\n  return (\n    <div className=\"w-full overflow-hidden rounded-lg border border-border bg-surface\">\n      {open && (\n        <Alert banner color=\"primary\" onClose={() => setOpen(false)}>\n          Bugun 23:00 dan 01:00 gacha texnik ishlar olib boriladi.\n        </Alert>\n      )}\n      <div className=\"flex items-center justify-between gap-3 p-6 text-sm text-text-muted\">\n        Sahifa kontenti\n        {!open && (\n          <Button size=\"sm\" onClick={() => setOpen(true)}>\n            Qaytarish\n          </Button>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/alert/colors": { component: Demo224, file: "archive/v0.2/alert/colors.tsx", source: "'use client';\n\nimport { Alert } from '@akhatmirzo/ui';\n\nexport default function AlertColors() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <Alert title=\"Yangi versiya chiqdi\">\n        Sahifani yangilang — o'zgarishlar darhol kuchga kiradi.\n      </Alert>\n      <Alert color=\"success\" title=\"Buyurtma qabul qilindi\">\n        Kuryer bugun 18:00 gacha qo'ng'iroq qiladi.\n      </Alert>\n      <Alert color=\"warning\" title=\"Obuna 3 kundan keyin tugaydi\">\n        To'lovni hozir qilsangiz, ma'lumotlaringiz saqlanib qoladi.\n      </Alert>\n      <Alert color=\"danger\" title=\"To'lov o'tmadi\">\n        Kartada mablag' yetarli emas. Boshqa kartani sinab ko'ring.\n      </Alert>\n      <Alert color=\"primary\" title=\"Maslahat\">\n        Tez qidirish uchun Ctrl + K ni bosing.\n      </Alert>\n      <Alert color=\"neutral\" title=\"Qoralama saqlandi\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/alert/variants": { component: Demo225, file: "archive/v0.2/alert/variants.tsx", source: "'use client';\n\nimport { Alert } from '@akhatmirzo/ui';\n\nexport default function AlertVariants() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <Alert color=\"success\" variant=\"soft\" title=\"Soft\">\n        Yumshoq fon — standart ko'rinish.\n      </Alert>\n      <Alert color=\"success\" variant=\"outline\" title=\"Outline\">\n        Rangli chegara va oddiy fon.\n      </Alert>\n      <Alert color=\"success\" variant=\"solid\" title=\"Solid\">\n        To'q fon — eng ko'p e'tibor tortadi.\n      </Alert>\n    </div>\n  );\n}\n" },
  "archive/v0.2/avatar/basic": { component: Demo226, file: "archive/v0.2/avatar/basic.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nconst people = [\n  'Sarvar Abduxoliqov',\n  'Malika Rahimova',\n  'Jasur Karimov',\n  \"O'tkir Hoshimov\",\n  'Dilnoza Yusupova',\n  'Rustam Qodirov',\n];\n\nexport default function AvatarBasic() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {people.map((name) => (\n        <Avatar key={name} name={name} />\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/avatar/group": { component: Demo227, file: "archive/v0.2/avatar/group.tsx", source: "'use client';\n\nimport { Avatar, AvatarGroup } from '@akhatmirzo/ui';\n\nconst team = [\n  'Sarvar Abduxoliqov',\n  'Malika Rahimova',\n  'Jasur Karimov',\n  'Dilnoza Yusupova',\n  'Rustam Qodirov',\n  'Gulnora Aliyeva',\n  'Bekzod Toshmatov',\n];\n\nexport default function AvatarGroupDemo() {\n  return (\n    <AvatarGroup max={4} aria-label=\"Loyiha ishtirokchilari\">\n      {team.map((name) => (\n        <Avatar key={name} name={name} />\n      ))}\n    </AvatarGroup>\n  );\n}\n" },
  "archive/v0.2/avatar/image": { component: Demo228, file: "archive/v0.2/avatar/image.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarImage() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Avatar size=\"lg\" src=\"https://github.com/Akhatmirzo.png\" name=\"Akhatmirzo\" />\n      <Avatar size=\"lg\" src=\"/mavjud-emas.png\" name=\"Gulnora Aliyeva\" />\n      <Avatar size=\"lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/avatar/sizes": { component: Demo229, file: "archive/v0.2/avatar/sizes.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarSizes() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Avatar size=\"xs\" name=\"Malika Rahimova\" />\n        <Avatar size=\"sm\" name=\"Malika Rahimova\" />\n        <Avatar size=\"md\" name=\"Malika Rahimova\" />\n        <Avatar size=\"lg\" name=\"Malika Rahimova\" />\n        <Avatar size=\"xl\" name=\"Malika Rahimova\" />\n      </div>\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Avatar size=\"sm\" shape=\"square\" name=\"Bahor Market\" />\n        <Avatar size=\"md\" shape=\"square\" name=\"Bahor Market\" />\n        <Avatar size=\"lg\" shape=\"square\" name=\"Bahor Market\" />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/avatar/status": { component: Demo230, file: "archive/v0.2/avatar/status.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarStatus() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Avatar name=\"Sarvar Abduxoliqov\" status=\"online\" />\n      <Avatar name=\"Malika Rahimova\" status=\"offline\" />\n      <Avatar name=\"Rustam Qodirov\" status=\"busy\" />\n      <Avatar name=\"Jasur Karimov\" shape=\"square\" size=\"lg\" status=\"online\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/badge/colors": { component: Demo231, file: "archive/v0.2/badge/colors.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeColors() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge>Qoralama</Badge>\n      <Badge color=\"primary\">Yangi</Badge>\n      <Badge color=\"success\">To'langan</Badge>\n      <Badge color=\"warning\">Kutilmoqda</Badge>\n      <Badge color=\"danger\">Bekor qilindi</Badge>\n      <Badge color=\"info\">Yo'lda</Badge>\n    </div>\n  );\n}\n" },
  "archive/v0.2/badge/dot": { component: Demo232, file: "archive/v0.2/badge/dot.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeDot() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge dot color=\"success\">\n        Onlayn\n      </Badge>\n      <Badge dot color=\"warning\" variant=\"outline\">\n        Tekshirilmoqda\n      </Badge>\n      <Badge dot color=\"danger\" variant=\"solid\">\n        To'xtatilgan\n      </Badge>\n    </div>\n  );\n}\n" },
  "archive/v0.2/badge/removable": { component: Demo233, file: "archive/v0.2/badge/removable.tsx", source: "'use client';\n\nimport { Badge, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst initial = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\"];\n\nexport default function BadgeRemovable() {\n  const [cities, setCities] = useState(initial);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      {cities.map((city) => (\n        <Badge\n          key={city}\n          variant=\"outline\"\n          onRemove={() => setCities((list) => list.filter((c) => c !== city))}\n          labels={{ remove: `${city} filtrini olib tashlash` }}\n        >\n          {city}\n        </Badge>\n      ))}\n      {cities.length < initial.length && (\n        <Button variant=\"link\" size=\"sm\" onClick={() => setCities(initial)}>\n          Qaytarish\n        </Button>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.2/badge/sizes": { component: Demo234, file: "archive/v0.2/badge/sizes.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge size=\"sm\" color=\"primary\">\n        Kichik\n      </Badge>\n      <Badge size=\"md\" color=\"primary\">\n        O'rta\n      </Badge>\n    </div>\n  );\n}\n" },
  "archive/v0.2/badge/variants": { component: Demo235, file: "archive/v0.2/badge/variants.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeVariants() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge variant=\"soft\" color=\"success\">\n          Soft\n        </Badge>\n        <Badge variant=\"solid\" color=\"success\">\n          Solid\n        </Badge>\n        <Badge variant=\"outline\" color=\"success\">\n          Outline\n        </Badge>\n      </div>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge variant=\"soft\" color=\"danger\">\n          Soft\n        </Badge>\n        <Badge variant=\"solid\" color=\"danger\">\n          Solid\n        </Badge>\n        <Badge variant=\"outline\" color=\"danger\">\n          Outline\n        </Badge>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/breadcrumb/basic": { component: Demo236, file: "archive/v0.2/breadcrumb/basic.tsx", source: "'use client';\n\nimport { Breadcrumb } from '@akhatmirzo/ui';\nimport { House } from 'lucide-react';\n\nexport default function BreadcrumbBasic() {\n  return (\n    <Breadcrumb\n      items={[\n        { label: 'Bosh sahifa', href: '#', icon: <House /> },\n        { label: 'Mahsulotlar', href: '#mahsulotlar' },\n        { label: 'Telefonlar', href: '#telefonlar' },\n        { label: 'iPhone 17' },\n      ]}\n    />\n  );\n}\n" },
  "archive/v0.2/breadcrumb/collapse": { component: Demo237, file: "archive/v0.2/breadcrumb/collapse.tsx", source: "'use client';\n\nimport { Breadcrumb } from '@akhatmirzo/ui';\nimport { House } from 'lucide-react';\n\nexport default function BreadcrumbCollapse() {\n  return (\n    <Breadcrumb\n      maxItems={4}\n      items={[\n        { label: 'Bosh sahifa', href: '#', icon: <House /> },\n        { label: 'Katalog', href: '#katalog' },\n        { label: 'Elektronika', href: '#elektronika' },\n        { label: 'Telefonlar', href: '#telefonlar' },\n        { label: 'Apple', href: '#apple' },\n        { label: 'iPhone 17 Pro Max 256 GB' },\n      ]}\n    />\n  );\n}\n" },
  "archive/v0.2/breadcrumb/separator": { component: Demo238, file: "archive/v0.2/breadcrumb/separator.tsx", source: "'use client';\n\nimport { Breadcrumb } from '@akhatmirzo/ui';\n\nconst items = [\n  { label: 'Sozlamalar', href: '#' },\n  { label: 'Hisob', href: '#hisob' },\n  { label: 'Xavfsizlik' },\n];\n\nexport default function BreadcrumbSeparator() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      <Breadcrumb items={items} separator=\"/\" />\n      <Breadcrumb items={items} size=\"sm\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/button/as-child": { component: Demo239, file: "archive/v0.2/button/as-child.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { ArrowRight } from 'lucide-react';\n\nexport default function ButtonAsChild() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button asChild variant=\"outline\" rightIcon={<ArrowRight />}>\n        <a href=\"#accessibility\">Accessibility bo'limiga</a>\n      </Button>\n      <Button asChild variant=\"link\">\n        <a href=\"https://github.com/Akhatmirzo/akhatmirzo-toolkit\">GitHub</a>\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/button/full-width": { component: Demo240, file: "archive/v0.2/button/full-width.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonFullWidth() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Button variant=\"primary\" fullWidth>\n        Kirish\n      </Button>\n      <Button variant=\"outline\" fullWidth>\n        Ro'yxatdan o'tish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/button/icons": { component: Demo241, file: "archive/v0.2/button/icons.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { ArrowRight, Plus, Trash2 } from 'lucide-react';\n\nexport default function ButtonIcons() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\" leftIcon={<Plus />}>\n        Qo'shish\n      </Button>\n      <Button rightIcon={<ArrowRight />}>Davom etish</Button>\n      <Button variant=\"danger\" leftIcon={<Trash2 />}>\n        O'chirish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/button/loading": { component: Demo242, file: "archive/v0.2/button/loading.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function ButtonLoading() {\n  const [saving, setSaving] = useState(false);\n\n  const save = () => {\n    setSaving(true);\n    setTimeout(() => {\n      setSaving(false);\n      toast.success('Saqlandi');\n    }, 1500);\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\" loading={saving} onClick={save}>\n        Saqlash\n      </Button>\n      <Button variant=\"outline\" loading labels={{ loading: 'Yuborilmoqda' }}>\n        Yuborish\n      </Button>\n      <Button disabled>O'chirilgan</Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/button/sizes": { component: Demo243, file: "archive/v0.2/button/sizes.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button size=\"sm\">Kichik · 32</Button>\n      <Button size=\"md\">O'rta · 40</Button>\n      <Button size=\"lg\">Katta · 48</Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/button/variants": { component: Demo244, file: "archive/v0.2/button/variants.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonVariants() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\">Saqlash</Button>\n      <Button>Soft</Button>\n      <Button variant=\"outline\">Outline</Button>\n      <Button variant=\"ghost\">Ghost</Button>\n      <Button variant=\"danger\">O'chirish</Button>\n      <Button variant=\"link\">Batafsil</Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/card/basic": { component: Demo245, file: "archive/v0.2/card/basic.tsx", source: "'use client';\n\nimport { Avatar, Badge, Button, Card } from '@akhatmirzo/ui';\n\nexport default function CardBasic() {\n  return (\n    <Card className=\"w-full max-w-md\">\n      <Card.Header\n        title=\"Buyurtma #1042\"\n        description=\"Bugun, 14:20\"\n        action={\n          <Badge color=\"primary\" dot>\n            Yangi\n          </Badge>\n        }\n      />\n      <Card.Body>\n        <div className=\"flex items-center gap-3\">\n          <Avatar name=\"Sarvar Abduxoliqov\" size=\"sm\" />\n          <div className=\"flex flex-col\">\n            <span className=\"font-medium\">Sarvar Abduxoliqov</span>\n            <span className=\"text-text-muted\">3 ta mahsulot · 245 000 so'm</span>\n          </div>\n        </div>\n      </Card.Body>\n      <Card.Footer className=\"justify-end\">\n        <Button variant=\"ghost\">Bekor qilish</Button>\n        <Button variant=\"primary\">Tasdiqlash</Button>\n      </Card.Footer>\n    </Card>\n  );\n}\n" },
  "archive/v0.2/card/interactive": { component: Demo246, file: "archive/v0.2/card/interactive.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nconst reports = [\n  { title: 'Sotuvlar', description: \"Oktyabr · 48 250 000 so'm\" },\n  { title: 'Mijozlar', description: '1 204 ta faol mijoz' },\n];\n\nexport default function CardInteractive() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-2\">\n      {reports.map((report) => (\n        <Card key={report.title} variant=\"outline\" interactive asChild>\n          <a href=\"#props\">\n            <Card.Header title={report.title} description={report.description} />\n          </a>\n        </Card>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/card/media": { component: Demo247, file: "archive/v0.2/card/media.tsx", source: "'use client';\n\nimport { Badge, Card } from '@akhatmirzo/ui';\n\nexport default function CardMedia() {\n  return (\n    <Card padding=\"none\" className=\"w-full max-w-sm overflow-hidden\">\n      <div className=\"h-32 bg-linear-to-br from-primary to-info\" />\n      <div className=\"flex flex-col gap-3 p-6\">\n        <Card.Header title=\"Samarqand bo'ylab sayohat\" description=\"2 kun · 4 ta joy\" />\n        <Card.Footer>\n          <Badge color=\"success\" size=\"sm\">\n            Joy bor\n          </Badge>\n          <Badge size=\"sm\">Guruh</Badge>\n        </Card.Footer>\n      </div>\n    </Card>\n  );\n}\n" },
  "archive/v0.2/card/padding": { component: Demo248, file: "archive/v0.2/card/padding.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nconst paddings = [\n  { padding: 'sm', px: 16 },\n  { padding: 'md', px: 24 },\n  { padding: 'lg', px: 32 },\n] as const;\n\nexport default function CardPadding() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-3\">\n      {paddings.map(({ padding, px }) => (\n        <Card key={padding} variant=\"outline\" padding={padding}>\n          <div className=\"rounded-md bg-primary-soft p-2 text-xs font-medium text-primary-soft-foreground\">\n            {padding} · {px}px\n          </div>\n        </Card>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/card/variants": { component: Demo249, file: "archive/v0.2/card/variants.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nexport default function CardVariants() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-3\">\n      <Card variant=\"elevated\" padding=\"sm\">\n        <Card.Header title=\"Elevated\" description=\"Soya va chegara (standart)\" />\n      </Card>\n      <Card variant=\"outline\" padding=\"sm\">\n        <Card.Header title=\"Outline\" description=\"Faqat chegara\" />\n      </Card>\n      <Card variant=\"soft\" padding=\"sm\">\n        <Card.Header title=\"Soft\" description=\"Och kulrang fon\" />\n      </Card>\n    </div>\n  );\n}\n" },
  "archive/v0.2/checkbox/basic": { component: Demo250, file: "archive/v0.2/checkbox/basic.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxBasic() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <Checkbox label=\"Shartlarga roziman\" />\n      <Checkbox label=\"Meni eslab qol\" defaultChecked />\n      <Checkbox label=\"Qisman tanlangan\" checked=\"indeterminate\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/checkbox/description": { component: Demo251, file: "archive/v0.2/checkbox/description.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxDescription() {\n  return (\n    <div className=\"flex max-w-sm flex-col gap-4\">\n      <Checkbox\n        label=\"Yangiliklar\"\n        description=\"Haftasiga bir marta yangi imkoniyatlar haqida xat\"\n        defaultChecked\n      />\n      <Checkbox\n        size=\"sm\"\n        label=\"Qurilmani eslab qolish\"\n        description=\"30 kun davomida qayta kod so'ralmaydi\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/checkbox/select-all": { component: Demo252, file: "archive/v0.2/checkbox/select-all.tsx", source: "'use client';\n\nimport { Checkbox, type CheckedState } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst channels = ['Email', 'SMS', 'Telegram'];\n\nexport default function CheckboxSelectAll() {\n  const [selected, setSelected] = useState<string[]>(['Email']);\n  const all: CheckedState =\n    selected.length === channels.length ? true : selected.length > 0 ? 'indeterminate' : false;\n\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <Checkbox\n        label=\"Barcha kanallar\"\n        checked={all}\n        onCheckedChange={(checked) => setSelected(checked ? channels : [])}\n      />\n      <div className=\"flex flex-col gap-3 pl-7\">\n        {channels.map((channel) => (\n          <Checkbox\n            key={channel}\n            label={channel}\n            checked={selected.includes(channel)}\n            onCheckedChange={(checked) =>\n              setSelected((s) => (checked ? [...s, channel] : s.filter((c) => c !== channel)))\n            }\n          />\n        ))}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/checkbox/sizes": { component: Demo253, file: "archive/v0.2/checkbox/sizes.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-6\">\n      <Checkbox size=\"sm\" label=\"Kichik · 16\" defaultChecked />\n      <Checkbox size=\"md\" label=\"O'rta · 20\" defaultChecked />\n    </div>\n  );\n}\n" },
  "archive/v0.2/checkbox/states": { component: Demo254, file: "archive/v0.2/checkbox/states.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxStates() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <Checkbox label=\"O'chirilgan\" disabled />\n      <Checkbox label=\"O'chirilgan, belgilangan\" disabled defaultChecked />\n      <Checkbox label=\"Xato\" invalid />\n    </div>\n  );\n}\n" },
  "archive/v0.2/checkbox/with-field": { component: Demo255, file: "archive/v0.2/checkbox/with-field.tsx", source: "'use client';\n\nimport { Checkbox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CheckboxWithField() {\n  const [agree, setAgree] = useState(false);\n\n  return (\n    <div className=\"max-w-sm\">\n      <Field\n        label=\"Foydalanish shartlari\"\n        required\n        error={agree ? undefined : 'Davom etish uchun rozilik kerak'}\n      >\n        <Checkbox label=\"Shartlar bilan tanishdim\" checked={agree} onCheckedChange={setAgree} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/combobox/basic": { component: Demo256, file: "archive/v0.2/combobox/basic.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst cities = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Xiva',\n  'Namangan',\n  'Andijon',\n  \"Farg'ona\",\n  \"Qo'qon\",\n  \"Marg'ilon\",\n  'Nukus',\n  'Qarshi',\n  'Termiz',\n].map((label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }));\n\nexport default function ComboboxBasic() {\n  const [city, setCity] = useState<string | null>(null);\n\n  return (\n    <Field\n      label=\"Shahar\"\n      description={city ? `Qiymat: ${city}` : 'Hali tanlanmagan'}\n      className=\"w-full max-w-xs\"\n    >\n      <Combobox\n        options={cities}\n        value={city}\n        onValueChange={setCity}\n        placeholder=\"Shahar tanlang\"\n        clearable\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.2/combobox/creatable": { component: Demo257, file: "archive/v0.2/combobox/creatable.tsx", source: "'use client';\n\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst initialTags: ComboboxOption[] = ['dizayn', 'frontend', 'backend', 'mobil'].map((t) => ({\n  value: t,\n  label: t,\n}));\n\nexport default function ComboboxCreatable() {\n  const [tags, setTags] = useState(initialTags);\n  const [chosen, setChosen] = useState<string[]>(['frontend']);\n\n  return (\n    <Field\n      label=\"Teglar\"\n      description=\"Ro'yxatda yo'q tegni yozing va Enter bosing\"\n      className=\"w-full max-w-sm\"\n    >\n      <Combobox\n        multiple\n        creatable\n        options={tags}\n        value={chosen}\n        onValueChange={setChosen}\n        onCreate={(text) => {\n          const option = { value: text.toLowerCase(), label: text };\n          setTags((prev) => [...prev, option]);\n          return option;\n        }}\n        placeholder=\"Teg qo'shing\"\n        leftIcon={null}\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.2/combobox/details": { component: Demo258, file: "archive/v0.2/combobox/details.tsx", source: "'use client';\n\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\n\nfunction Dot({ className }: { className: string }) {\n  return <span className={`size-2.5 rounded-full ${className}`} />;\n}\n\nconst statuses: ComboboxOption[] = [\n  {\n    value: 'new',\n    label: 'Yangi',\n    description: 'Buyurtma qabul qilindi',\n    icon: <Dot className=\"bg-info\" />,\n  },\n  {\n    value: 'packing',\n    label: \"Yig'ilmoqda\",\n    description: 'Omborda tayyorlanmoqda',\n    icon: <Dot className=\"bg-warning\" />,\n  },\n  {\n    value: 'shipping',\n    label: \"Yo'lda\",\n    description: 'Kuryerga topshirildi',\n    icon: <Dot className=\"bg-primary\" />,\n  },\n  {\n    value: 'cancelled',\n    label: 'Bekor qilingan',\n    description: 'Arxivlangan holat',\n    icon: <Dot className=\"bg-danger\" />,\n    disabled: true,\n  },\n];\n\nexport default function ComboboxDetails() {\n  return (\n    <Field label=\"Buyurtma holati\" className=\"w-full max-w-xs\">\n      <Combobox options={statuses} defaultValue=\"packing\" leftIcon={null} />\n    </Field>\n  );\n}\n" },
  "archive/v0.2/combobox/multiple": { component: Demo259, file: "archive/v0.2/combobox/multiple.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst branches = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Namangan',\n  'Andijon',\n  \"Farg'ona\",\n  'Nukus',\n].map((label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }));\n\nexport default function ComboboxMultiple() {\n  const [selected, setSelected] = useState<string[]>(['toshkent', 'samarqand']);\n\n  return (\n    <Field\n      label=\"Filiallar\"\n      description={`${selected.length} ta tanlangan`}\n      className=\"w-full max-w-sm\"\n    >\n      <Combobox\n        multiple\n        options={branches}\n        value={selected}\n        onValueChange={setSelected}\n        placeholder=\"Filiallarni tanlang\"\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.2/combobox/server": { component: Demo260, file: "archive/v0.2/combobox/server.tsx", source: "'use client';\n\nimport { searchMatch } from '@akhatmirzo/core';\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\nimport { useRef, useState } from 'react';\n\nconst all: ComboboxOption[] = ['Toshkent', 'Samarqand', 'Buxoro', 'Xiva', 'Nukus', 'Termiz'].map(\n  (label) => ({ value: label.toLowerCase(), label }),\n);\n\nexport default function ComboboxServer() {\n  const [options, setOptions] = useState(all.slice(0, 3));\n  const [loading, setLoading] = useState(false);\n  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);\n\n  // Server so'rovini taqlid qiladi: javob 700ms dan keyin keladi\n  const search = (query: string) => {\n    clearTimeout(timer.current);\n    setLoading(true);\n    timer.current = setTimeout(() => {\n      setOptions(query ? all.filter((o) => searchMatch(o.label, query).match) : all.slice(0, 3));\n      setLoading(false);\n    }, 700);\n  };\n\n  return (\n    <Field label=\"Shahar (serverdan)\" className=\"w-full max-w-xs\">\n      <Combobox\n        options={options}\n        loading={loading}\n        onSearch={search}\n        placeholder=\"Qidirib tanlang\"\n        searchPlaceholder=\"Shahar nomi...\"\n        emptyText=\"Server hech narsa qaytarmadi\"\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.2/combobox/sizes": { component: Demo261, file: "archive/v0.2/combobox/sizes.tsx", source: "'use client';\n\nimport { Combobox } from '@akhatmirzo/ui';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro'].map((label) => ({\n  value: label.toLowerCase(),\n  label,\n}));\n\nexport default function ComboboxSizes() {\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Combobox size=\"sm\" options={cities} aria-label=\"Shahar\" placeholder=\"sm — 32px\" />\n      <Combobox size=\"md\" options={cities} aria-label=\"Shahar\" placeholder=\"md — 40px\" />\n      <Combobox size=\"lg\" options={cities} aria-label=\"Shahar\" placeholder=\"lg — 48px\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/combobox/states": { component: Demo262, file: "archive/v0.2/combobox/states.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro'].map((label) => ({\n  value: label.toLowerCase(),\n  label,\n}));\n\nexport default function ComboboxStates() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <Field label=\"O'chirilgan\" disabled>\n        <Combobox options={cities} defaultValue=\"toshkent\" />\n      </Field>\n      <Field label=\"Shahar\" error=\"Shaharni tanlang\" required>\n        <Combobox options={cities} placeholder=\"Shahar tanlang\" />\n      </Field>\n      <Field label=\"Yuklanmoqda\">\n        <Combobox options={[]} loading placeholder=\"Ochib ko'ring\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/combobox/uzbek-search": { component: Demo263, file: "archive/v0.2/combobox/uzbek-search.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\n\nconst districts = [\n  'Gʻuzor',\n  \"G'allaorol\",\n  'Oʻrta Chirchiq',\n  \"Qo'shrabot\",\n  'Shahrisabz',\n  'Chilonzor',\n  'Yunusobod',\n  \"Mirzo Ulug'bek\",\n  'Toshkent tumani',\n].map((label, i) => ({ value: String(i), label }));\n\nexport default function ComboboxUzbekSearch() {\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field label=\"Tuman\">\n        <Combobox options={districts} placeholder=\"Tumanni tanlang\" />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Yozib ko'ring: <span className=\"font-medium text-text\">guzor</span>,{' '}\n        <span className=\"font-medium text-text\">g‘allaorol</span>,{' '}\n        <span className=\"font-medium text-text\">Чилонзор</span>,{' '}\n        <span className=\"font-medium text-text\">ulugbek</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/command-palette/basic": { component: Demo264, file: "archive/v0.2/command-palette/basic.tsx", source: "'use client';\n\nimport { Button, CommandPalette, Kbd, toast, type CommandPaletteGroup } from '@akhatmirzo/ui';\nimport {\n  ChartColumn,\n  FileSpreadsheet,\n  House,\n  Package,\n  Plus,\n  Search,\n  Settings,\n  UserPlus,\n  Users,\n} from 'lucide-react';\n\nconst run = (label: string) => () => toast(`\"${label}\" bajarildi`);\n\nconst groups: CommandPaletteGroup[] = [\n  {\n    heading: 'Sahifalar',\n    items: [\n      { label: 'Bosh sahifa', icon: <House />, onSelect: run('Bosh sahifa') },\n      {\n        label: 'Buyurtmalar',\n        icon: <Package />,\n        keywords: ['zakaz', 'savdo'],\n        onSelect: run('Buyurtmalar'),\n      },\n      { label: 'Mijozlar', icon: <Users />, onSelect: run('Mijozlar') },\n      {\n        label: 'Hisobotlar',\n        icon: <ChartColumn />,\n        keywords: ['statistika'],\n        onSelect: run('Hisobotlar'),\n      },\n      {\n        label: 'Sozlamalar',\n        icon: <Settings />,\n        shortcut: ['mod', ','],\n        onSelect: run('Sozlamalar'),\n      },\n    ],\n  },\n  {\n    heading: 'Amallar',\n    items: [\n      {\n        label: 'Yangi buyurtma',\n        icon: <Plus />,\n        shortcut: ['mod', 'N'],\n        onSelect: run('Yangi buyurtma'),\n      },\n      { label: \"Mijoz qo'shish\", icon: <UserPlus />, onSelect: run(\"Mijoz qo'shish\") },\n      {\n        label: 'Eksport (Excel)',\n        icon: <FileSpreadsheet />,\n        keywords: ['xlsx'],\n        onSelect: run('Eksport'),\n      },\n    ],\n  },\n];\n\nexport default function CommandPaletteBasic() {\n  return (\n    // Docs saytida Ctrl+K qidiruvga band, shuning uchun bu yerda mod+J\n    <CommandPalette groups={groups} hotkey=\"mod+j\">\n      <Button variant=\"outline\" leftIcon={<Search />} className=\"min-w-64 justify-start\">\n        <span className=\"flex-1 text-left text-text-muted\">Qidirish...</span>\n        <Kbd keys={['mod', 'J']} />\n      </Button>\n    </CommandPalette>\n  );\n}\n" },
  "archive/v0.2/command-palette/pages": { component: Demo265, file: "archive/v0.2/command-palette/pages.tsx", source: "'use client';\n\nimport { Button, CommandPalette, toast, type CommandPaletteGroup } from '@akhatmirzo/ui';\nimport { Globe, Moon, Sun, User } from 'lucide-react';\n\nconst customers = ['Aziza Karimova', 'Bobur Toshmatov', \"G'ayrat Usmonov\", 'Malika Yusupova'];\n\nconst groups: CommandPaletteGroup[] = [\n  {\n    heading: 'Sozlamalar',\n    items: [\n      {\n        label: 'Mavzuni almashtirish',\n        icon: <Moon />,\n        keywords: ['tungi rejim', 'dark'],\n        page: {\n          title: 'Mavzu',\n          placeholder: 'Mavzu tanlang...',\n          groups: [\n            {\n              heading: 'Mavzu',\n              items: [\n                {\n                  id: 'theme-light',\n                  label: \"Yorug'\",\n                  icon: <Sun />,\n                  onSelect: () => toast(\"Yorug' mavzu\"),\n                },\n                {\n                  id: 'theme-dark',\n                  label: \"Qorong'i\",\n                  icon: <Moon />,\n                  onSelect: () => toast(\"Qorong'i mavzu\"),\n                },\n              ],\n            },\n          ],\n        },\n      },\n      {\n        label: 'Tilni almashtirish',\n        icon: <Globe />,\n        page: {\n          title: 'Til',\n          groups: [\n            {\n              heading: 'Til',\n              items: [\n                { id: 'lang-uz', label: \"O'zbekcha\", onSelect: () => toast(\"O'zbekcha\") },\n                { id: 'lang-en', label: 'English', disabled: true },\n              ],\n            },\n          ],\n        },\n      },\n    ],\n  },\n  {\n    heading: 'Mijozlar',\n    searchOnly: true,\n    items: customers.map((name) => ({ label: name, icon: <User />, onSelect: () => toast(name) })),\n  },\n];\n\nexport default function CommandPalettePages() {\n  return (\n    <CommandPalette groups={groups} hotkey={false} recent={false}>\n      <Button variant=\"soft\">Sozlamalarni ochish</Button>\n    </CommandPalette>\n  );\n}\n" },
  "archive/v0.2/command-palette/server": { component: Demo266, file: "archive/v0.2/command-palette/server.tsx", source: "'use client';\n\nimport { Button, CommandPalette, toast, type CommandPaletteItem } from '@akhatmirzo/ui';\nimport { Plus, User } from 'lucide-react';\n\nconst customers = [\n  ['Akmal Ergashev', '+998 90 123 45 67'],\n  ['Akbar Sobirov', '+998 93 555 12 34'],\n  ['Kamola Akramova', '+998 97 700 00 11'],\n  ['Nodira Ahmedova', '+998 91 444 22 33'],\n] as const;\n\n/** Server qidiruvini taqlid qiladi (700ms); yangi so'rov eskisini bekor qiladi */\nfunction searchCustomers(query: string, { signal }: { signal: AbortSignal }) {\n  return new Promise<CommandPaletteItem[]>((resolve, reject) => {\n    const timer = setTimeout(() => {\n      const q = query.toLowerCase();\n      resolve(\n        customers\n          .filter(([name]) => name.toLowerCase().includes(q))\n          .map(([name, phone]) => ({\n            id: `customer-${name}`,\n            label: name,\n            description: phone,\n            icon: <User />,\n            onSelect: () => toast(name),\n          })),\n      );\n    }, 700);\n    signal.addEventListener('abort', () => {\n      clearTimeout(timer);\n      reject(new DOMException('Bekor qilindi', 'AbortError'));\n    });\n  });\n}\n\nexport default function CommandPaletteServer() {\n  return (\n    <CommandPalette\n      hotkey={false}\n      recentKey=\"docs:command-palette:server\"\n      placeholder=\"Mijoz yoki buyruq qidirish...\"\n      onSearch={searchCustomers}\n      labels={{ results: 'Mijozlar (serverdan)' }}\n      groups={[\n        {\n          heading: 'Amallar',\n          items: [\n            { label: \"Mijoz qo'shish\", icon: <Plus />, onSelect: () => toast(\"Mijoz qo'shish\") },\n          ],\n        },\n      ]}\n    >\n      <Button variant=\"outline\">Mijoz qidirish</Button>\n    </CommandPalette>\n  );\n}\n" },
  "archive/v0.2/core/api-errors": { component: Demo267, file: "archive/v0.2/core/api-errors.tsx", source: "'use client';\n\nimport { createApiClient, isApiError, type FetchLike } from '@akhatmirzo/core';\nimport { Badge, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\n// Haqiqiy server o'rniga: `/status/404` → 404 javob, `/sekin` → hech qachon javob bermaydi\nconst fakeFetch: FetchLike = (url, init) =>\n  new Promise((resolve, reject) => {\n    if (url.endsWith('/sekin')) {\n      init.signal?.addEventListener('abort', () => reject(new Error('aborted')));\n      return;\n    }\n    const status = Number(url.split('/').pop());\n    resolve({ ok: status < 400, status, headers: { get: () => null }, text: async () => '' });\n  });\n\nconst api = createApiClient({ baseUrl: '/api', timeout: 1500, fetch: fakeFetch });\n\nexport default function CoreApiErrors() {\n  const [result, setResult] = useState<{ code: string; message: string } | null>(null);\n\n  const request = async (path: string) => {\n    try {\n      await api.get(path);\n      setResult({ code: 'OK', message: 'Muvaffaqiyatli' });\n    } catch (error) {\n      if (isApiError(error)) setResult({ code: error.code, message: error.message });\n    }\n  };\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div className=\"flex flex-wrap gap-2\">\n        {['401', '403', '404', '422', '500'].map((s) => (\n          <Button key={s} size=\"sm\" variant=\"outline\" onClick={() => request(`/status/${s}`)}>\n            {s}\n          </Button>\n        ))}\n        <Button size=\"sm\" variant=\"outline\" onClick={() => request('/sekin')}>\n          Timeout\n        </Button>\n      </div>\n      {result && (\n        <div className=\"flex items-center gap-2 text-sm\">\n          <Badge color={result.code === 'OK' ? 'success' : 'danger'}>{result.code}</Badge>\n          <span className=\"text-text\">{result.message}</span>\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/card-validate": { component: Demo268, file: "archive/v0.2/core/card-validate.tsx", source: "'use client';\n\nimport { detectCardBrand, formatCardNumber, isValidCardNumber } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst BRANDS = { uzcard: 'Uzcard', humo: 'Humo', visa: 'Visa', mastercard: 'Mastercard' };\n\nexport default function CoreCardValidate() {\n  const [digits, setDigits] = useState('8600');\n  const brand = detectCardBrand(digits);\n  const complete = digits.length === 16;\n  const valid = isValidCardNumber(digits);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field\n        label=\"Karta raqami\"\n        description=\"To'g'ri namuna: 4111 1111 1111 1111\"\n        error={complete && !valid ? \"Karta raqami noto'g'ri\" : undefined}\n      >\n        <Input\n          value={formatCardNumber(digits)}\n          onChange={(e) => setDigits(e.target.value.replace(/\\D/g, '').slice(0, 16))}\n          inputMode=\"numeric\"\n          placeholder=\"0000 0000 0000 0000\"\n          suffix={brand ? BRANDS[brand] : undefined}\n        />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={brand ? 'info' : 'neutral'}>{brand ? BRANDS[brand] : \"Brend noma'lum\"}</Badge>\n        <Badge color={!complete ? 'neutral' : valid ? 'success' : 'danger'} dot>\n          {!complete ? `${digits.length}/16` : valid ? \"Luhn: to'g'ri\" : 'Luhn: xato'}\n        </Badge>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/date": { component: Demo269, file: "archive/v0.2/core/date.tsx", source: "'use client';\n\nimport { formatDate, parseDate } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst PATTERNS = ['dd.MM.yyyy', 'd MMMM yyyy, EEEE', 'd MMM, EEE', 'EEEE, d MMMM [soat] HH:mm'];\nconst DATE = new Date(2026, 9, 21, 14, 30);\n\nexport default function CoreDate() {\n  const [pattern, setPattern] = useState('d MMMM yyyy, EEEE');\n  const [input, setInput] = useState('31.02.2026');\n  const parsed = parseDate(input);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field\n        label=\"Shablon\"\n        description={`formatDate(sana, shablon) → ${formatDate(DATE, pattern)}`}\n      >\n        <Input value={pattern} onChange={(e) => setPattern(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        {PATTERNS.map((p) => (\n          <button key={p} type=\"button\" onClick={() => setPattern(p)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{p}</Badge>\n          </button>\n        ))}\n      </div>\n      <Field\n        label=\"parseDate (dd.MM.yyyy)\"\n        description={parsed ? formatDate(parsed, 'EEEE, d MMMM yyyy') : \"null — bunday sana yo'q\"}\n      >\n        <Input value={input} onChange={(e) => setInput(e.target.value)} invalid={!parsed} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/debounce-throttle": { component: Demo270, file: "archive/v0.2/core/debounce-throttle.tsx", source: "'use client';\n\nimport { debounce, throttle } from '@akhatmirzo/core';\nimport { Button } from '@akhatmirzo/ui';\nimport { useEffect, useMemo, useState } from 'react';\n\ntype Counts = { raw: number; throttled: number; debounced: number };\nconst ZERO: Counts = { raw: 0, throttled: 0, debounced: 0 };\nconst inc = (key: keyof Counts) => (c: Counts) => ({ ...c, [key]: c[key] + 1 });\n\nexport default function CoreDebounceThrottle() {\n  const [counts, setCounts] = useState(ZERO);\n\n  const onDebounced = useMemo(() => debounce(() => setCounts(inc('debounced')), 400), []);\n  const onThrottled = useMemo(() => throttle(() => setCounts(inc('throttled')), 400), []);\n\n  useEffect(\n    () => () => {\n      onDebounced.cancel();\n      onThrottled.cancel();\n    },\n    [onDebounced, onThrottled],\n  );\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div\n        onPointerMove={() => {\n          setCounts(inc('raw'));\n          onDebounced();\n          onThrottled();\n        }}\n        className=\"flex h-32 touch-none items-center justify-center rounded-xl border border-dashed border-border-strong bg-surface-muted text-sm text-text-muted\"\n      >\n        Sichqoncha yoki barmoqni shu yerda yurgizing\n      </div>\n      <dl className=\"grid grid-cols-3 gap-2 text-center text-sm\">\n        {(['raw', 'throttled', 'debounced'] as const).map((key) => (\n          <div key={key} className=\"rounded-lg border border-border bg-surface p-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{key}</dt>\n            <dd className=\"text-xl font-semibold text-text tabular-nums\">{counts[key]}</dd>\n          </div>\n        ))}\n      </dl>\n      <Button size=\"sm\" variant=\"ghost\" onClick={() => setCounts(ZERO)}>\n        Nolga qaytarish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/fuzzy": { component: Demo271, file: "archive/v0.2/core/fuzzy.tsx", source: "'use client';\n\nimport { fuzzyMatch, splitByRanges } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst COMMANDS = [\n  'Yangi buyurtma',\n  \"Buyurtmalar ro'yxati\",\n  \"Mijoz qo'shish\",\n  'Hisobotlar',\n  'Sozlamalar',\n  'Profilni tahrirlash',\n  'Mavzuni almashtirish',\n];\n\nexport default function CoreFuzzy() {\n  const [query, setQuery] = useState('ybu');\n  const results = COMMANDS.flatMap((label) => {\n    const result = fuzzyMatch(label, query);\n    return result ? [{ label, ...result }] : [];\n  }).sort((a, b) => b.score - a.score);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Field label=\"Buyruq\" description=\"Harflar tartibi muhim: mq, hsb, prof\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <ul className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {results.map(({ label, ranges, score }) => (\n          <li key={label} className=\"flex items-center justify-between gap-3 px-3 py-2\">\n            <span>\n              {splitByRanges(label, ranges).map((part, i) =>\n                part.match ? (\n                  <strong key={i} className=\"font-semibold text-primary-soft-foreground\">\n                    {part.text}\n                  </strong>\n                ) : (\n                  <span key={i}>{part.text}</span>\n                ),\n              )}\n            </span>\n            <span className=\"font-mono text-xs text-text-muted\">{score}</span>\n          </li>\n        ))}\n        {results.length === 0 && <li className=\"px-3 py-2 text-text-muted\">Mos buyruq yo'q</li>}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/money": { component: Demo272, file: "archive/v0.2/core/money.tsx", source: "'use client';\n\nimport { formatMoney, formatNumber, type MoneyCurrency } from '@akhatmirzo/core';\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CURRENCIES: MoneyCurrency[] = [\"so'm\", 'UZS', false];\n\nexport default function CoreMoney() {\n  const [raw, setRaw] = useState('1250000.5');\n  const [currency, setCurrency] = useState<MoneyCurrency>(\"so'm\");\n  const n = Number(raw.replace(',', '.').replace(/\\s/g, ''));\n\n  const rows = [\n    { call: 'formatNumber(n)', value: formatNumber(n) },\n    { call: 'formatNumber(n, { decimals: 2 })', value: formatNumber(n, { decimals: 2 }) },\n    { call: 'formatMoney(n, { currency })', value: formatMoney(n, { currency }) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Son\">\n        <Input value={raw} onChange={(e) => setRaw(e.target.value)} inputMode=\"decimal\" />\n      </Field>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        {CURRENCIES.map((c) => (\n          <Button\n            key={String(c)}\n            size=\"sm\"\n            variant={currency === c ? 'primary' : 'outline'}\n            onClick={() => setCurrency(c)}\n          >\n            {c === false ? 'false' : c}\n          </Button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.call} className=\"flex flex-wrap justify-between gap-x-4 gap-y-1 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.call}</dt>\n            <dd className=\"font-mono font-medium text-text tabular-nums\">{row.value || \"''\"}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/password": { component: Demo273, file: "archive/v0.2/core/password.tsx", source: "'use client';\n\nimport { passwordStrength } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst BAR = ['bg-danger', 'bg-danger', 'bg-warning', 'bg-success', 'bg-success'];\nconst COLOR = ['danger', 'danger', 'warning', 'success', 'success'] as const;\nconst CHECKS = {\n  length: 'Kamida 8 belgi',\n  lower: 'Kichik harf',\n  upper: 'Katta harf',\n  digit: 'Raqam',\n  symbol: 'Belgi (!@#…)',\n};\n\nexport default function CorePassword() {\n  const [password, setPassword] = useState('Parol123');\n  const { score, label, checks } = passwordStrength(password);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Parol\">\n        <Input type=\"password\" value={password} onChange={(e) => setPassword(e.target.value)} />\n      </Field>\n      <div className=\"flex gap-1\" aria-hidden>\n        {[1, 2, 3, 4].map((i) => (\n          <span\n            key={i}\n            className={`h-1.5 flex-1 rounded-full ${password && i <= Math.max(score, 1) ? BAR[score] : 'bg-surface-muted'}`}\n          />\n        ))}\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Badge color={COLOR[score]}>{label}</Badge>\n        <span className=\"text-xs text-text-muted\">score: {score}/4</span>\n      </div>\n      <ul className=\"flex flex-col gap-1 text-sm\">\n        {(Object.keys(CHECKS) as (keyof typeof CHECKS)[]).map((key) => (\n          <li key={key} className={checks[key] ? 'text-text' : 'text-text-muted'}>\n            {checks[key] ? '✓' : '○'} {CHECKS[key]}\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/phone-card": { component: Demo274, file: "archive/v0.2/core/phone-card.tsx", source: "'use client';\n\nimport { formatCardNumber, formatPhone } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst digitsOf = (s: string) => s.replace(/\\D/g, '');\n\nexport default function CorePhoneCard() {\n  const [phone, setPhone] = useState('90123');\n  const [card, setCard] = useState('8600 1234');\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" description={`formatPhone: ${formatPhone(phone) || '—'}`}>\n        <Input\n          prefix=\"+998\"\n          value={formatPhone(phone, 'national')}\n          onChange={(e) => setPhone(digitsOf(e.target.value).slice(0, 9))}\n          inputMode=\"tel\"\n          placeholder=\"(90) 123-45-67\"\n        />\n      </Field>\n      <Field label=\"Karta raqami\" description={`Toza qiymat: ${digitsOf(card) || '—'}`}>\n        <Input\n          value={card}\n          onChange={(e) => setCard(formatCardNumber(digitsOf(e.target.value).slice(0, 16)))}\n          inputMode=\"numeric\"\n          placeholder=\"0000 0000 0000 0000\"\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/phone-validate": { component: Demo275, file: "archive/v0.2/core/phone-validate.tsx", source: "'use client';\n\nimport { isValidEmail, parsePhone } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CorePhoneValidate() {\n  const [phone, setPhone] = useState('+998 90 123-45-67');\n  const [email, setEmail] = useState('sarvar@mail');\n  const parsed = parsePhone(phone);\n  const code = parsed.digits.slice(0, 2);\n  const phoneError =\n    code.length === 2 && !parsed.operator ? `\"${code}\" — bunday operator kodi yo'q` : undefined;\n  const emailValid = isValidEmail(email);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" error={phoneError} description={`digits: ${parsed.digits || '—'}`}>\n        <Input value={phone} onChange={(e) => setPhone(e.target.value)} inputMode=\"tel\" />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={parsed.valid ? 'success' : 'neutral'} dot>\n          {parsed.valid ? \"To'g'ri raqam\" : \"To'liq emas\"}\n        </Badge>\n        {parsed.operator && <Badge color=\"info\">Operator: {parsed.operator}</Badge>}\n      </div>\n      <Field\n        label=\"Email\"\n        error={email.trim() && !emailValid ? \"Email manzil noto'g'ri\" : undefined}\n      >\n        <Input type=\"email\" value={email} onChange={(e) => setEmail(e.target.value)} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/search": { component: Demo276, file: "archive/v0.2/core/search.tsx", source: "'use client';\n\nimport { searchMatch, splitByRanges } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CITIES = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  \"Farg'ona\",\n  'Qo‘qon',\n  'Shahrisabz',\n  'Chirchiq',\n  'Ғузор',\n  'Ўрта Чирчиқ',\n  'Шаҳрихон',\n];\n\nexport default function CoreSearch() {\n  const [query, setQuery] = useState('шаҳ');\n  const results = CITIES.map((city) => ({ city, ...searchMatch(city, query) })).filter(\n    (r) => r.match,\n  );\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Field label=\"Shahar qidirish\" description=\"Sinab ko'ring: chir, ғуз, fargona, qo'qon\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <ul className=\"flex flex-wrap gap-2\">\n        {results.map(({ city, ranges }) => (\n          <li key={city} className=\"rounded-lg border border-border bg-surface px-3 py-1.5 text-sm\">\n            {splitByRanges(city, ranges).map((part, i) =>\n              part.match ? (\n                <mark key={i} className=\"rounded-sm bg-primary-soft text-primary-soft-foreground\">\n                  {part.text}\n                </mark>\n              ) : (\n                <span key={i}>{part.text}</span>\n              ),\n            )}\n          </li>\n        ))}\n        {results.length === 0 && <li className=\"text-sm text-text-muted\">Hech narsa topilmadi</li>}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/storage": { component: Demo277, file: "archive/v0.2/core/storage.tsx", source: "'use client';\n\nimport { createStorage } from '@akhatmirzo/core';\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst store = createStorage({ prefix: 'docs-demo:' });\n\nexport default function CoreStorage() {\n  const [value, setValue] = useState('Sarvar');\n  const [result, setResult] = useState('—');\n\n  const save = (ttl?: number) => {\n    const ok = store.set('ism', value, { ttl });\n    setResult(\n      ok ? `Saqlandi${ttl ? ` (${ttl / 1000} soniya)` : ' (muddatsiz)'}` : \"Saqlab bo'lmadi\",\n    );\n  };\n\n  const read = () => {\n    const saved = store.get<string>('ism');\n    setResult(saved === null ? \"null — yo'q yoki muddati o'tgan\" : JSON.stringify(saved));\n  };\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Qiymat\" description=\"Kalit: docs-demo:ism\">\n        <Input value={value} onChange={(e) => setValue(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Button variant=\"primary\" onClick={() => save(5000)}>\n          5 soniyaga saqlash\n        </Button>\n        <Button variant=\"outline\" onClick={() => save()}>\n          Muddatsiz\n        </Button>\n        <Button variant=\"ghost\" onClick={read}>\n          O'qish\n        </Button>\n      </div>\n      <p className=\"text-sm text-text-muted\">\n        Natija: <code className=\"font-mono text-text\">{result}</code>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/time-ago": { component: Demo278, file: "archive/v0.2/core/time-ago.tsx", source: "'use client';\n\nimport { timeAgo } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst MINUTE = 60_000;\nconst NOW = new Date(2026, 9, 21, 12, 0);\nconst OFFSETS = [5, 180, 1440, 4320, 20160, 136800, -120, -1440];\n\nexport default function CoreTimeAgo() {\n  const [minutes, setMinutes] = useState('90');\n  const custom = new Date(NOW.getTime() - Number(minutes || 0) * MINUTE);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Necha daqiqa oldin\" description={`timeAgo → ${timeAgo(custom, NOW)}`}>\n        <Input\n          value={minutes}\n          onChange={(e) => setMinutes(e.target.value.replace(/[^\\d-]/g, ''))}\n          inputMode=\"numeric\"\n          suffix=\"daqiqa\"\n        />\n      </Field>\n      <ul className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {OFFSETS.map((m) => (\n          <li key={m} className=\"flex justify-between gap-4 px-3 py-2\">\n            <span className=\"font-mono text-xs text-text-muted\">{m} daqiqa</span>\n            <span className=\"text-text\">{timeAgo(NOW.getTime() - m * MINUTE, NOW)}</span>\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/translit": { component: Demo279, file: "archive/v0.2/core/translit.tsx", source: "'use client';\n\nimport { cyrToLat, latToCyr, normalizeUz } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst SAMPLES = ['Ғузор тумани', \"O'zbekiston\", 'Gʻuzor', 'ер, поезд, маъно', 'SHAHAR'];\n\nexport default function CoreTranslit() {\n  const [text, setText] = useState('Ғузор тумани');\n\n  const rows = [\n    { name: 'cyrToLat', value: cyrToLat(text) },\n    { name: 'latToCyr', value: latToCyr(text) },\n    { name: 'normalizeUz', value: normalizeUz(text) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Matn\">\n        <Input value={text} onChange={(e) => setText(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        {SAMPLES.map((s) => (\n          <button key={s} type=\"button\" onClick={() => setText(s)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{s}</Badge>\n          </button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.name} className=\"flex items-center justify-between gap-4 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.name}</dt>\n            <dd className=\"font-mono break-all text-text\">{row.value || '—'}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.2/core/truncate": { component: Demo280, file: "archive/v0.2/core/truncate.tsx", source: "'use client';\n\nimport { slugify, truncate, truncateMiddle } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst FILE = 'shartnoma-mchj-akhatmirzo-imzolangan.docx';\n\nexport default function CoreTruncate() {\n  const [title, setTitle] = useState(\"Farg'ona viloyati — 2026\");\n  const [max, setMax] = useState(24);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Sarlavha\" description={`slugify: ${slugify(title) || '—'}`}>\n        <Input value={title} onChange={(e) => setTitle(e.target.value)} />\n      </Field>\n      <label className=\"flex flex-col gap-2 text-sm font-medium text-text\">\n        Maksimal uzunlik: {max}\n        <input\n          type=\"range\"\n          min={6}\n          max={44}\n          value={max}\n          onChange={(e) => setMax(Number(e.target.value))}\n          className=\"w-full accent-primary\"\n        />\n      </label>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        <div className=\"flex flex-col gap-1 px-3 py-2\">\n          <dt className=\"font-mono text-xs text-text-muted\">truncateMiddle</dt>\n          <dd className=\"font-mono text-text\">{truncateMiddle(FILE, max)}</dd>\n        </div>\n        <div className=\"flex flex-col gap-1 px-3 py-2\">\n          <dt className=\"font-mono text-xs text-text-muted\">truncate</dt>\n          <dd className=\"font-mono text-text\">{truncate(FILE, max)}</dd>\n        </div>\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.2/data-table/basic": { component: Demo281, file: "archive/v0.2/data-table/basic.tsx", source: "'use client';\n\nimport { formatDate, formatMoney } from '@akhatmirzo/core';\nimport { Badge, Button, DataTable, toast, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Plus } from 'lucide-react';\n\ntype Status = 'paid' | 'pending' | 'shipped' | 'cancelled';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  date: Date;\n  status: Status;\n  total: number;\n}\n\nconst STATUS = {\n  paid: { label: \"To'langan\", color: 'success' },\n  pending: { label: 'Kutilmoqda', color: 'warning' },\n  shipped: { label: \"Yo'lda\", color: 'info' },\n  cancelled: { label: 'Bekor qilingan', color: 'danger' },\n} as const;\n\nconst NAMES = [\n  'Jasur Karimov',\n  'Malika Rahimova',\n  \"Bekzod G'aniyev\",\n  'Nodira Saidova',\n  'Aziz Normatov',\n];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\", 'Xorazm'];\nconst STATUSES = Object.keys(STATUS) as Status[];\n\nconst orders: Order[] = Array.from({ length: 48 }, (_, i) => ({\n  id: 1042 + i,\n  customer: NAMES[(i * 3) % NAMES.length]!,\n  region: REGIONS[(i * 7) % REGIONS.length]!,\n  date: new Date(2026, 9, 21 - (i % 30)),\n  status: STATUSES[(i * 5 + (i >> 2)) % 4]!,\n  total: 85_000 + ((i * 377_311) % 4_800_000),\n}));\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88, sortable: true, cell: (o) => `#${o.id}` },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  { key: 'region', header: 'Viloyat', sortable: true, filter: 'select' },\n  { key: 'date', header: 'Sana', sortable: true, cell: (o) => formatDate(o.date) },\n  {\n    key: 'status',\n    header: 'Holat',\n    filter: 'multiselect',\n    filterOptions: STATUSES.map((s) => ({ value: s, label: STATUS[s].label })),\n    searchValue: (o) => STATUS[o.status].label,\n    cell: (o) => (\n      <Badge dot color={STATUS[o.status].color}>\n        {STATUS[o.status].label}\n      </Badge>\n    ),\n  },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableBasic() {\n  return (\n    <DataTable\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      searchable\n      pagination={{ pageSize: 5, pageSizeOptions: [5, 10, 25] }}\n      className=\"w-full\"\n      toolbar={\n        <Button variant=\"primary\" leftIcon={<Plus />} onClick={() => toast('Yangi buyurtma')}>\n          Qo'shish\n        </Button>\n      }\n    />\n  );\n}\n" },
  "archive/v0.2/data-table/cards": { component: Demo282, file: "archive/v0.2/data-table/cards.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, toast, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  total: number;\n}\n\nconst orders: Order[] = [\n  { id: 1042, customer: 'Jasur Karimov', region: 'Toshkent', total: 1_250_000 },\n  { id: 1043, customer: 'Malika Rahimova', region: 'Samarqand', total: 480_000 },\n  { id: 1044, customer: 'Aziz Normatov', region: \"Farg'ona\", total: 2_730_000 },\n];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№' },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'region', header: 'Viloyat' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nexport default function DataTableCards() {\n  return (\n    <DataTable\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      mobileView=\"cards\"\n      selectable\n      onRowClick={(o) => toast(`Buyurtma #${o.id}`)}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.2/data-table/density": { component: Demo283, file: "archive/v0.2/data-table/density.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Employee {\n  id: number;\n  name: string;\n  position: string;\n  department: string;\n  phone: string;\n  city: string;\n  salary: number;\n}\n\nconst employees: Employee[] = [\n  {\n    id: 1,\n    name: 'Sarvar Abduxoliqov',\n    position: 'Frontend dasturchi',\n    department: 'IT',\n    phone: '+998 90 123 45 67',\n    city: 'Toshkent',\n    salary: 14_500_000,\n  },\n  {\n    id: 2,\n    name: \"Gulnora O'rinova\",\n    position: 'Buxgalter',\n    department: 'Moliya',\n    phone: '+998 93 555 12 34',\n    city: 'Samarqand',\n    salary: 9_800_000,\n  },\n  {\n    id: 3,\n    name: 'Javohir Ismoilov',\n    position: 'Dizayner',\n    department: 'Marketing',\n    phone: '+998 97 700 00 11',\n    city: 'Buxoro',\n    salary: 11_200_000,\n  },\n];\n\nconst columns: DataTableColumn<Employee>[] = [\n  { key: 'name', header: 'Xodim', width: 200, hideable: false },\n  { key: 'position', header: 'Lavozim' },\n  { key: 'department', header: \"Bo'lim\" },\n  { key: 'phone', header: 'Telefon', className: 'tabular-nums' },\n  { key: 'city', header: 'Shahar', hidden: true },\n  { key: 'salary', header: 'Maosh', numeric: true, cell: (e) => formatMoney(e.salary) },\n];\n\nexport default function DataTableDensity() {\n  return (\n    <DataTable\n      label=\"Xodimlar\"\n      data={employees}\n      columns={columns}\n      density=\"compact\"\n      stickyFirstColumn\n      selectable\n      tableClassName=\"min-w-[860px]\"\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.2/data-table/filters": { component: Demo284, file: "archive/v0.2/data-table/filters.tsx", source: "'use client';\n\nimport { formatDate, formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Payment {\n  id: number;\n  client: string;\n  method: string;\n  region: string;\n  date: Date;\n  amount: number;\n}\n\nconst METHODS = ['Click', 'Payme', 'Uzcard', 'Naqd'];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Andijon', 'Namangan'];\nconst CLIENTS = ['Dilnoza Yusupova', 'Otabek Qodirov', 'Shahnoza Ergasheva', 'Rustam Xolmatov'];\n\nconst payments: Payment[] = Array.from({ length: 40 }, (_, i) => ({\n  id: 501 + i,\n  client: CLIENTS[(i * 3) % CLIENTS.length]!,\n  method: METHODS[(i * 5) % METHODS.length]!,\n  region: REGIONS[(i + (i >> 2)) % REGIONS.length]!,\n  date: new Date(2026, 9, 25 - i),\n  amount: 50_000 + ((i * 213_457) % 3_000_000),\n}));\n\nconst columns: DataTableColumn<Payment>[] = [\n  { key: 'id', header: '№', width: 72, cell: (p) => `#${p.id}` },\n  { key: 'client', header: 'Mijoz' },\n  { key: 'method', header: \"To'lov turi\", filter: 'select' },\n  { key: 'region', header: 'Viloyat', filter: 'multiselect' },\n  { key: 'date', header: 'Sana', filter: 'date', sortable: true, cell: (p) => formatDate(p.date) },\n  {\n    key: 'amount',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    filter: 'range',\n    cell: (p) => formatMoney(p.amount),\n  },\n];\n\nexport default function DataTableFilters() {\n  return (\n    <DataTable\n      label=\"To'lovlar\"\n      data={payments}\n      columns={columns}\n      searchable\n      pagination={{ pageSize: 5 }}\n      initialState={{ filters: { method: 'Click' } }}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.2/data-table/selection": { component: Demo285, file: "archive/v0.2/data-table/selection.tsx", source: "'use client';\n\nimport {\n  DataTable,\n  DropdownMenu,\n  IconButton,\n  toast,\n  type DataTableColumn,\n  Button,\n} from '@akhatmirzo/ui';\nimport { Download, Ellipsis, Eye, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\ninterface Product {\n  id: string;\n  name: string;\n  sku: string;\n  stock: number;\n}\n\nconst initial: Product[] = [\n  { id: 'p1', name: \"Paxta ko'ylak\", sku: 'KY-001', stock: 42 },\n  { id: 'p2', name: \"Atlas ro'mol\", sku: 'RM-014', stock: 8 },\n  { id: 'p3', name: 'Choynak (1.5 l)', sku: 'CH-203', stock: 0 },\n  { id: 'p4', name: \"Do'ppi\", sku: 'DP-077', stock: 120 },\n  { id: 'p5', name: 'Sopol lagan', sku: 'LG-310', stock: 15 },\n];\n\nconst columns: DataTableColumn<Product>[] = [\n  { key: 'name', header: 'Mahsulot', sortable: true },\n  { key: 'sku', header: 'Artikul' },\n  { key: 'stock', header: 'Qoldiq', numeric: true, sortable: true },\n];\n\nexport default function DataTableSelection() {\n  const [products, setProducts] = useState(initial);\n  const remove = (ids: string[]) => setProducts((prev) => prev.filter((p) => !ids.includes(p.id)));\n\n  return (\n    <DataTable\n      label=\"Mahsulotlar\"\n      data={products}\n      columns={columns}\n      selectable\n      className=\"w-full\"\n      onRowClick={(p) => toast(`${p.name} ochildi`)}\n      bulkActions={(rows, clear) => (\n        <>\n          <Button\n            variant=\"outline\"\n            size=\"sm\"\n            leftIcon={<Download />}\n            onClick={() => toast(`${rows.length} ta eksport qilindi`)}\n          >\n            Eksport\n          </Button>\n          <Button\n            variant=\"danger\"\n            size=\"sm\"\n            leftIcon={<Trash2 />}\n            onClick={() => {\n              remove(rows.map((r) => r.id));\n              clear();\n            }}\n          >\n            O'chirish\n          </Button>\n        </>\n      )}\n      rowActions={(p) => (\n        <DropdownMenu>\n          <DropdownMenu.Trigger asChild>\n            <IconButton variant=\"ghost\" size=\"sm\" aria-label={`${p.name}: amallar`}>\n              <Ellipsis />\n            </IconButton>\n          </DropdownMenu.Trigger>\n          <DropdownMenu.Content align=\"end\">\n            <DropdownMenu.Item icon={<Eye />} onSelect={() => toast(p.name)}>\n              Ko'rish\n            </DropdownMenu.Item>\n            <DropdownMenu.Item variant=\"danger\" icon={<Trash2 />} onSelect={() => remove([p.id])}>\n              O'chirish\n            </DropdownMenu.Item>\n          </DropdownMenu.Content>\n        </DropdownMenu>\n      )}\n    />\n  );\n}\n" },
  "archive/v0.2/data-table/server": { component: Demo286, file: "archive/v0.2/data-table/server.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn, type DataTableState } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\ninterface Page {\n  rows: Order[];\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\nconst DB: Order[] = Array.from({ length: 137 }, (_, i) => ({\n  id: 2001 + i,\n  customer: NAMES[i % NAMES.length]!,\n  total: 90_000 + ((i * 271_828) % 3_500_000),\n}));\n\n/** \"Server\": qidiradi, saralaydi, sahifalaydi. Haqiqiy loyihada — fetch('/api/orders?...') */\nfunction fetchOrders({ search, sorting, pagination }: DataTableState): Promise<Page> {\n  let rows = DB.filter((o) => o.customer.toLowerCase().includes(search.toLowerCase()));\n  const sort = sorting[0];\n  if (sort) {\n    const key = sort.id as keyof Order;\n    rows = [...rows].sort((a, b) => (a[key] > b[key] ? 1 : -1) * (sort.desc ? -1 : 1));\n  }\n  const start = pagination.pageIndex * pagination.pageSize;\n  const page = { rows: rows.slice(start, start + pagination.pageSize), total: rows.length };\n  return new Promise((resolve) => setTimeout(() => resolve(page), 600));\n}\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88, sortable: true },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableServer() {\n  const [query, setQuery] = useState<DataTableState>({\n    sorting: [],\n    search: '',\n    filters: {},\n    pagination: { pageIndex: 0, pageSize: 10 },\n  });\n  const [result, setResult] = useState<Page>({ rows: [], total: 0 });\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    let active = true;\n    fetchOrders(query).then((page) => {\n      if (!active) return;\n      setResult(page);\n      setLoading(false);\n    });\n    return () => {\n      active = false;\n    };\n  }, [query]);\n\n  return (\n    <DataTable\n      label=\"Server buyurtmalari\"\n      data={result.rows}\n      rowCount={result.total}\n      columns={columns}\n      manual\n      searchable\n      pagination={{ pageSize: 10 }}\n      loading={loading}\n      onStateChange={(state) => {\n        setLoading(true);\n        setQuery(state);\n      }}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.2/data-table/states": { component: Demo287, file: "archive/v0.2/data-table/states.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { Button, DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\nimport { useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\nconst orders: Order[] = [\n  { id: 1042, customer: 'Jasur Karimov', total: 1_250_000 },\n  { id: 1043, customer: 'Malika Rahimova', total: 480_000 },\n  { id: 1044, customer: 'Aziz Normatov', total: 2_730_000 },\n];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88 },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nconst STATES = {\n  data: \"Ma'lumot\",\n  first: 'Birinchi yuklanish',\n  refetch: 'Qayta yuklanish',\n  empty: \"Bo'sh\",\n  error: 'Xato',\n} as const;\n\ntype State = keyof typeof STATES;\n\nexport default function DataTableStates() {\n  const [state, setState] = useState<State>('first');\n\n  return (\n    <div className=\"flex w-full flex-col gap-4\">\n      <div className=\"flex flex-wrap gap-2\">\n        {(Object.keys(STATES) as State[]).map((s) => (\n          <Button\n            key={s}\n            size=\"sm\"\n            variant={s === state ? 'primary' : 'outline'}\n            aria-pressed={s === state}\n            onClick={() => setState(s)}\n          >\n            {STATES[s]}\n          </Button>\n        ))}\n      </div>\n      <DataTable\n        label=\"Holatlar\"\n        data={state === 'data' || state === 'refetch' ? orders : []}\n        columns={columns}\n        columnToggle={false}\n        loading={state === 'first' || state === 'refetch'}\n        error={\n          state === 'error' ? 'Server javob bermadi. Internet aloqasini tekshiring.' : undefined\n        }\n        onRetry={() => setState('data')}\n        empty={{\n          icon: <Inbox />,\n          title: \"Hali buyurtmalar yo'q\",\n          description: \"Birinchi buyurtmani qo'shing — u shu yerda ko'rinadi.\",\n          action: (\n            <Button size=\"sm\" variant=\"primary\" leftIcon={<Plus />}>\n              Buyurtma qo'shish\n            </Button>\n          ),\n        }}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/data-table/virtual": { component: Demo288, file: "archive/v0.2/data-table/virtual.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { useMemo } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Farhod Tursunov', 'Mohira Nazarova'];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Buxoro', 'Navoiy', 'Xorazm'];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 96, sortable: true },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  { key: 'region', header: 'Viloyat', filter: 'select' },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableVirtual() {\n  const orders = useMemo<Order[]>(\n    () =>\n      Array.from({ length: 10_000 }, (_, i) => ({\n        id: i + 1,\n        customer: NAMES[i % NAMES.length]!,\n        region: REGIONS[(i * 3) % REGIONS.length]!,\n        total: 50_000 + ((i * 377_311) % 4_800_000),\n      })),\n    [],\n  );\n\n  return (\n    <DataTable\n      label=\"10 000 buyurtma\"\n      data={orders}\n      columns={columns}\n      virtual\n      maxHeight={400}\n      density=\"compact\"\n      searchable\n      columnToggle={false}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.2/date-picker/basic": { component: Demo289, file: "archive/v0.2/date-picker/basic.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DatePicker, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst isSunday = (date: Date) => date.getDay() === 0;\n\nexport default function DatePickerBasic() {\n  const [date, setDate] = useState<Date | null>(null);\n\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Field\n        label=\"Yetkazish sanasi\"\n        description={date ? formatDate(date, 'd MMMM yyyy, EEEE') : 'Yakshanba — dam olish kuni'}\n      >\n        <DatePicker\n          value={date}\n          onValueChange={setDate}\n          minDate={new Date()}\n          disabledDates={isSunday}\n          presets\n          clearable\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/date-picker/birthday": { component: Demo290, file: "archive/v0.2/date-picker/birthday.tsx", source: "'use client';\n\nimport { DatePicker, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DatePickerBirthday() {\n  const [birthday, setBirthday] = useState<Date | null>(new Date(1995, 4, 17));\n\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Field label=\"Tug'ilgan sana\" description=\"Sarlavhani bosing — oy va yilni tanlash\">\n        <DatePicker\n          value={birthday}\n          onValueChange={setBirthday}\n          minDate={new Date(1920, 0, 1)}\n          maxDate={new Date()}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/date-picker/calendar-range": { component: Demo291, file: "archive/v0.2/date-picker/calendar-range.tsx", source: "'use client';\n\nimport { Calendar, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);\n\nexport default function CalendarRange() {\n  const today = new Date();\n  const [range, setRange] = useState<DateRangeValue>({\n    from: addDays(today, -3),\n    to: addDays(today, 4),\n  });\n\n  return (\n    <div className=\"flex flex-col items-center gap-2\">\n      <Calendar\n        mode=\"range\"\n        numberOfMonths={2}\n        value={range}\n        onValueChange={setRange}\n        className=\"rounded-xl border border-border bg-surface p-3\"\n      />\n      <span className=\"text-sm text-text-muted\">\n        {range.from && !range.to ? 'Tugash sanasini tanlang' : 'Oraliq tanlandi'}\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.2/date-picker/calendar": { component: Demo292, file: "archive/v0.2/date-picker/calendar.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { Calendar } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CalendarInline() {\n  const [date, setDate] = useState<Date | null>(new Date());\n\n  return (\n    <div className=\"flex flex-col items-center gap-2\">\n      <Calendar\n        value={date}\n        onValueChange={setDate}\n        disabledDates={(d) => d.getDay() === 0}\n        className=\"rounded-xl border border-border bg-surface p-3\"\n      />\n      <span className=\"text-sm text-text-muted\">\n        {date ? formatDate(date, 'd MMMM yyyy, EEEE') : 'Sana tanlanmagan'}\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.2/date-picker/range-presets": { component: Demo293, file: "archive/v0.2/date-picker/range-presets.tsx", source: "'use client';\n\nimport { DateRangePicker, Field, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);\n\nexport default function DateRangePickerPresets() {\n  const [vacation, setVacation] = useState<DateRangeValue | null>(null);\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Ta'til\" description=\"Yakshanbalar yopiq\">\n        <DateRangePicker\n          value={vacation}\n          onValueChange={setVacation}\n          minDate={new Date()}\n          disabledDates={(d) => d.getDay() === 0}\n          clearable\n          name=\"tatil\"\n          presets={[\n            { label: 'Bir hafta', range: (t) => ({ from: addDays(t, 1), to: addDays(t, 7) }) },\n            { label: 'Ikki hafta', range: (t) => ({ from: addDays(t, 1), to: addDays(t, 14) }) },\n          ]}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/date-picker/range": { component: Demo294, file: "archive/v0.2/date-picker/range.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DateRangePicker, Field, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst daysAgo = (n: number) => {\n  const d = new Date();\n  return new Date(d.getFullYear(), d.getMonth(), d.getDate() - n);\n};\n\nexport default function DateRangePickerBasic() {\n  const [range, setRange] = useState<DateRangeValue | null>({ from: daysAgo(6), to: daysAgo(0) });\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field\n        label=\"Hisobot davri\"\n        description={\n          range?.from && range.to\n            ? `${formatDate(range.from, 'd MMM')} – ${formatDate(range.to, 'd MMM yyyy')}`\n            : 'Davr tanlanmagan'\n        }\n      >\n        <DateRangePicker value={range} onValueChange={setRange} presets maxDate={new Date()} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/date-picker/sizes": { component: Demo295, file: "archive/v0.2/date-picker/sizes.tsx", source: "'use client';\n\nimport { DatePicker } from '@akhatmirzo/ui';\n\nexport default function DatePickerSizes() {\n  const today = new Date();\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <DatePicker size=\"sm\" aria-label=\"Kichik\" defaultValue={today} />\n      <DatePicker size=\"md\" aria-label=\"O'rta\" defaultValue={today} />\n      <DatePicker size=\"lg\" aria-label=\"Katta\" defaultValue={today} />\n    </div>\n  );\n}\n" },
  "archive/v0.2/date-picker/states": { component: Demo296, file: "archive/v0.2/date-picker/states.tsx", source: "'use client';\n\nimport { DatePicker, Field } from '@akhatmirzo/ui';\n\nexport default function DatePickerStates() {\n  const today = new Date();\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"O'chirilgan\" disabled>\n        <DatePicker defaultValue={today} />\n      </Field>\n      <Field label=\"Faqat o'qish\">\n        <DatePicker defaultValue={today} readOnly />\n      </Field>\n      <Field label=\"Muddat\" error=\"Sanani tanlang\" required>\n        <DatePicker />\n      </Field>\n      <Field label=\"Boshqa format\" description=\"d MMMM yyyy\">\n        <DatePicker format=\"d MMMM yyyy\" defaultValue={today} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/date-picker/typing": { component: Demo297, file: "archive/v0.2/date-picker/typing.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DatePicker, Field, type DatePickerError } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst errorText: Record<DatePickerError, string> = {\n  invalid: \"Bunday sana yo'q\",\n  unavailable: \"O'tgan sanani tanlab bo'lmaydi\",\n};\n\nexport default function DatePickerTyping() {\n  const [date, setDate] = useState<Date | null>(null);\n  const [error, setError] = useState<DatePickerError | null>(null);\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field\n        label=\"Uchrashuv sanasi\"\n        required\n        error={error ? errorText[error] : undefined}\n        description=\"Sinab ko'ring: 31022026\"\n      >\n        <DatePicker\n          value={date}\n          onValueChange={setDate}\n          onErrorChange={setError}\n          minDate={new Date()}\n        />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Qiymat: <code>{date ? formatDate(date, 'yyyy-MM-dd') : 'null'}</code>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/dialog/async-submit": { component: Demo298, file: "archive/v0.2/dialog/async-submit.tsx", source: "'use client';\n\nimport { Button, Dialog, Field, Input, Textarea, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function DialogAsyncSubmit() {\n  const [open, setOpen] = useState(false);\n  const [sending, setSending] = useState(false);\n\n  const send = async () => {\n    setSending(true);\n    await wait(1500);\n    setSending(false);\n    setOpen(false);\n    toast.success('Fikringiz yuborildi');\n  };\n\n  return (\n    <Dialog open={open} onOpenChange={(next) => !sending && setOpen(next)}>\n      <Dialog.Trigger asChild>\n        <Button>Fikr bildirish</Button>\n      </Dialog.Trigger>\n      <Dialog.Content title=\"Fikr bildirish\" size=\"lg\" dismissible={!sending}>\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Mavzu\" required>\n            <Input placeholder=\"Masalan: yetkazib berish\" />\n          </Field>\n          <Field label=\"Xabar\">\n            <Textarea minRows={4} placeholder=\"Fikringizni yozing...\" />\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button disabled={sending}>Bekor qilish</Button>\n          </Dialog.Close>\n          <Button variant=\"primary\" loading={sending} onClick={send}>\n            Yuborish\n          </Button>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "archive/v0.2/dialog/basic": { component: Demo299, file: "archive/v0.2/dialog/basic.tsx", source: "'use client';\n\nimport { Button, Dialog, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DialogBasic() {\n  const [open, setOpen] = useState(false);\n  const [name, setName] = useState('Sarvar');\n  const [phone, setPhone] = useState('+998 90 123 45 67');\n\n  return (\n    <Dialog open={open} onOpenChange={setOpen}>\n      <Dialog.Trigger asChild>\n        <Button variant=\"primary\">Profilni tahrirlash</Button>\n      </Dialog.Trigger>\n      <Dialog.Content title=\"Profilni tahrirlash\" description=\"O'zgarishlar darhol saqlanadi.\">\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Ism\">\n            <Input value={name} onChange={(e) => setName(e.target.value)} />\n          </Field>\n          <Field label=\"Telefon\" description=\"Tasdiqlash uchun SMS kod yuboriladi\">\n            <Input value={phone} onChange={(e) => setPhone(e.target.value)} />\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button>Bekor qilish</Button>\n          </Dialog.Close>\n          <Button variant=\"primary\" onClick={() => setOpen(false)}>\n            Saqlash\n          </Button>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "archive/v0.2/dialog/confirm-dialog": { component: Demo300, file: "archive/v0.2/dialog/confirm-dialog.tsx", source: "'use client';\n\nimport { Button, ConfirmDialog, toast } from '@akhatmirzo/ui';\n\nexport default function DialogConfirmDeclarative() {\n  return (\n    <ConfirmDialog\n      trigger={<Button variant=\"outline\">Hisobdan chiqish</Button>}\n      title=\"Hisobdan chiqilsinmi?\"\n      description=\"Qayta kirish uchun SMS kod kerak bo'ladi.\"\n      confirmText=\"Chiqish\"\n      onConfirm={() => toast('Hisobdan chiqdingiz')}\n      onCancel={() => toast.info('Hisobda qoldingiz')}\n    />\n  );\n}\n" },
  "archive/v0.2/dialog/confirm": { component: Demo301, file: "archive/v0.2/dialog/confirm.tsx", source: "'use client';\n\nimport { Button, confirm, toast } from '@akhatmirzo/ui';\nimport { Trash2 } from 'lucide-react';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function DialogConfirm() {\n  const removeOrder = async () => {\n    const ok = await confirm({\n      title: \"Buyurtma o'chirilsinmi?\",\n      description: \"Bu amalni qaytarib bo'lmaydi.\",\n      confirmText: \"O'chirish\",\n      variant: 'danger',\n    });\n    if (ok) toast.success(\"Buyurtma #1042 o'chirildi\");\n  };\n\n  const publish = async () => {\n    const ok = await confirm({\n      title: 'Mahsulot nashr qilinsinmi?',\n      description: \"Mahsulot do'konda hammaga ko'rinadi.\",\n      confirmText: 'Nashr qilish',\n      // Promise tugaguncha tugma loading, oyna ochiq turadi\n      onConfirm: () => wait(1500),\n    });\n    if (ok) toast.success('Mahsulot nashr qilindi');\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"danger\" leftIcon={<Trash2 />} onClick={removeOrder}>\n        O'chirish\n      </Button>\n      <Button variant=\"primary\" onClick={publish}>\n        Nashr qilish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/dialog/options": { component: Demo302, file: "archive/v0.2/dialog/options.tsx", source: "'use client';\n\nimport { Button, Dialog } from '@akhatmirzo/ui';\n\nexport default function DialogOptions() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">dismissible=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content\n          title=\"Shartlarni o'qing\"\n          description=\"Tashqariga bosish yopmaydi — faqat tugma yoki Esc.\"\n          dismissible={false}\n        >\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Roziman</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">closeButton=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content title=\"✕ tugmasisiz\" closeButton={false} size=\"sm\">\n          <p className=\"m-0 text-sm text-text-muted\">Oyna faqat pastdagi tugma bilan yopiladi.</p>\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Yopish</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">hideTitle</Button>\n        </Dialog.Trigger>\n        <Dialog.Content title=\"Mahsulot rasmi\" hideTitle size=\"sm\">\n          <div className=\"grid h-40 place-items-center rounded-xl bg-surface-muted text-sm text-text-muted\">\n            Sarlavha faqat ekran o'quvchi uchun\n          </div>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">mobileSheet=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content\n          title=\"Doim markazda\"\n          description=\"Telefonda ham pastdan chiqmaydi.\"\n          mobileSheet={false}\n          size=\"sm\"\n        >\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Yaxshi</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n    </div>\n  );\n}\n" },
  "archive/v0.2/dialog/sizes": { component: Demo303, file: "archive/v0.2/dialog/sizes.tsx", source: "'use client';\n\nimport { Button, Dialog, type DialogSize } from '@akhatmirzo/ui';\n\nconst sizes: { size: DialogSize; width: string }[] = [\n  { size: 'sm', width: '400px' },\n  { size: 'md', width: '520px' },\n  { size: 'lg', width: '640px' },\n  { size: 'xl', width: '800px' },\n  { size: 'full', width: 'butun ekran' },\n];\n\nexport default function DialogSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sizes.map(({ size, width }) => (\n        <Dialog key={size}>\n          <Dialog.Trigger asChild>\n            <Button variant=\"outline\">{size}</Button>\n          </Dialog.Trigger>\n          <Dialog.Content\n            title={`O'lcham: ${size}`}\n            description={`Kenglik — ${width}.`}\n            size={size}\n          >\n            <p className=\"m-0 text-sm text-text-muted\">\n              Ekran tor bo'lsa, chetlarda 16px joy qoladi. Telefonda oyna pastdan chiqadi.\n            </p>\n            <Dialog.Footer>\n              <Dialog.Close asChild>\n                <Button variant=\"primary\">Tushunarli</Button>\n              </Dialog.Close>\n            </Dialog.Footer>\n          </Dialog.Content>\n        </Dialog>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/dialog/with-select": { component: Demo304, file: "archive/v0.2/dialog/with-select.tsx", source: "'use client';\n\nimport { Button, Combobox, Dialog, Field, Select } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro', 'Andijon', \"Farg'ona\", 'Namangan'].map(\n  (label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }),\n);\n\nexport default function DialogWithSelect() {\n  const [city, setCity] = useState<string | null>('toshkent');\n\n  return (\n    <Dialog>\n      <Dialog.Trigger asChild>\n        <Button variant=\"outline\">Yetkazib berish manzili</Button>\n      </Dialog.Trigger>\n      <Dialog.Content\n        title=\"Yetkazib berish manzili\"\n        description=\"Ro'yxatlar oyna ustida ochiladi.\"\n      >\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Shahar\">\n            <Combobox options={cities} value={city} onValueChange={setCity} clearable />\n          </Field>\n          <Field label=\"Yetkazish vaqti\">\n            <Select defaultValue=\"morning\">\n              <Select.Item value=\"morning\">Ertalab (9:00–12:00)</Select.Item>\n              <Select.Item value=\"day\">Kunduzi (12:00–17:00)</Select.Item>\n              <Select.Item value=\"evening\">Kechqurun (17:00–21:00)</Select.Item>\n            </Select>\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button>Bekor qilish</Button>\n          </Dialog.Close>\n          <Dialog.Close asChild>\n            <Button variant=\"primary\">Saqlash</Button>\n          </Dialog.Close>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "archive/v0.2/divider/basic": { component: Demo305, file: "archive/v0.2/divider/basic.tsx", source: "'use client';\n\nimport { Divider } from '@akhatmirzo/ui';\n\nexport default function DividerBasic() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3 text-sm text-text\">\n      <div className=\"flex justify-between\">\n        <span>Mahsulotlar</span>\n        <span>220 000 so'm</span>\n      </div>\n      <div className=\"flex justify-between text-text-muted\">\n        <span>Yetkazib berish</span>\n        <span>25 000 so'm</span>\n      </div>\n      <Divider />\n      <div className=\"flex justify-between font-semibold\">\n        <span>Jami</span>\n        <span>245 000 so'm</span>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/divider/label": { component: Demo306, file: "archive/v0.2/divider/label.tsx", source: "'use client';\n\nimport { Button, Divider } from '@akhatmirzo/ui';\n\nexport default function DividerLabel() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Button variant=\"primary\" fullWidth>\n        Telefon orqali kirish\n      </Button>\n      <Divider label=\"yoki\" />\n      <Button variant=\"outline\" fullWidth>\n        Google orqali kirish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/divider/vertical": { component: Demo307, file: "archive/v0.2/divider/vertical.tsx", source: "'use client';\n\nimport { Divider } from '@akhatmirzo/ui';\n\nexport default function DividerVertical() {\n  return (\n    <div className=\"flex h-5 items-center gap-3 text-sm font-medium text-text-subtle\">\n      <span>Bosh sahifa</span>\n      <Divider orientation=\"vertical\" decorative />\n      <span>Buyurtmalar</span>\n      <Divider orientation=\"vertical\" decorative />\n      <span>Sozlamalar</span>\n    </div>\n  );\n}\n" },
  "archive/v0.2/drawer/details": { component: Demo308, file: "archive/v0.2/drawer/details.tsx", source: "'use client';\n\nimport { Button, Drawer } from '@akhatmirzo/ui';\n\nconst rows = [\n  ['Mijoz', 'Sarvar Abduxoliqov'],\n  ['Telefon', '+998 90 123 45 67'],\n  ['Manzil', 'Toshkent, Chilonzor tumani, 9-mavze'],\n  [\"To'lov\", 'Naqd, yetkazib berilganda'],\n  ['Jami', \"1 250 000 so'm\"],\n];\n\nexport default function DrawerDetails() {\n  return (\n    <Drawer>\n      <Drawer.Trigger asChild>\n        <Button>Buyurtma #1042</Button>\n      </Drawer.Trigger>\n      <Drawer.Content size=\"lg\" title=\"Buyurtma #1042\" description=\"21-oktabr, 14:32\">\n        <dl className=\"m-0 grid grid-cols-[auto_1fr] gap-x-6 gap-y-3 text-sm\">\n          {rows.map(([label, value]) => (\n            <div key={label} className=\"contents\">\n              <dt className=\"text-text-muted\">{label}</dt>\n              <dd className=\"m-0 font-medium text-text\">{value}</dd>\n            </div>\n          ))}\n        </dl>\n        <Drawer.Footer>\n          <Drawer.Close asChild>\n            <Button>Yopish</Button>\n          </Drawer.Close>\n          <Button variant=\"primary\">Yetkazildi deb belgilash</Button>\n        </Drawer.Footer>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "archive/v0.2/drawer/filters": { component: Demo309, file: "archive/v0.2/drawer/filters.tsx", source: "'use client';\n\nimport { Button, Checkbox, Drawer, Field, Input, Switch } from '@akhatmirzo/ui';\nimport { SlidersHorizontal } from 'lucide-react';\nimport { useState } from 'react';\n\nconst categories = ['Elektronika', 'Kiyim-kechak', \"Uy-ro'zg'or\", 'Kitoblar'];\n\nexport default function DrawerFilters() {\n  const [open, setOpen] = useState(false);\n  const [selected, setSelected] = useState<string[]>(['Elektronika']);\n\n  const toggle = (name: string, on: boolean) =>\n    setSelected((prev) => (on ? [...prev, name] : prev.filter((x) => x !== name)));\n\n  return (\n    <Drawer open={open} onOpenChange={setOpen}>\n      <Drawer.Trigger asChild>\n        <Button variant=\"outline\" leftIcon={<SlidersHorizontal />}>\n          Filtrlar\n        </Button>\n      </Drawer.Trigger>\n      <Drawer.Content title=\"Filtrlar\" description=\"Natijalarni toraytiring.\">\n        <div className=\"flex flex-col gap-5\">\n          <div className=\"grid grid-cols-2 gap-3\">\n            <Field label=\"Narxdan\">\n              <Input inputMode=\"numeric\" placeholder=\"0\" suffix=\"so'm\" />\n            </Field>\n            <Field label=\"Narxgacha\">\n              <Input inputMode=\"numeric\" placeholder=\"1 000 000\" suffix=\"so'm\" />\n            </Field>\n          </div>\n          <div className=\"flex flex-col gap-3\">\n            {categories.map((c) => (\n              <Checkbox\n                key={c}\n                label={c}\n                checked={selected.includes(c)}\n                onCheckedChange={(on) => toggle(c, on)}\n              />\n            ))}\n          </div>\n          <Switch label=\"Faqat mavjudlari\" defaultChecked />\n        </div>\n        <Drawer.Footer>\n          <Button onClick={() => setSelected([])}>Tozalash</Button>\n          <Button variant=\"primary\" onClick={() => setOpen(false)}>\n            Qo'llash\n          </Button>\n        </Drawer.Footer>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "archive/v0.2/drawer/mobile-menu": { component: Demo310, file: "archive/v0.2/drawer/mobile-menu.tsx", source: "'use client';\n\nimport { Button, Drawer } from '@akhatmirzo/ui';\nimport { Menu } from 'lucide-react';\nimport { useState } from 'react';\n\nconst items = ['Bosh sahifa', 'Buyurtmalar', 'Mahsulotlar', 'Mijozlar', 'Hisobotlar'];\n\nexport default function DrawerMobileMenu() {\n  const [active, setActive] = useState('Buyurtmalar');\n\n  return (\n    <Drawer>\n      <Drawer.Trigger asChild>\n        <Button variant=\"ghost\" leftIcon={<Menu />}>\n          Menyu\n        </Button>\n      </Drawer.Trigger>\n      <Drawer.Content\n        side=\"left\"\n        size=\"sm\"\n        title=\"Menyu\"\n        hideTitle\n        labels={{ close: 'Menyuni yopish' }}\n      >\n        <nav aria-label=\"Asosiy menyu\" className=\"-mx-2 flex flex-col gap-1\">\n          {items.map((item) => (\n            <Drawer.Close asChild key={item}>\n              <button\n                type=\"button\"\n                aria-current={item === active ? 'page' : undefined}\n                onClick={() => setActive(item)}\n                className=\"focus-ring flex h-10 cursor-pointer items-center rounded-lg border-0 bg-transparent px-3 text-left text-sm font-medium text-text hover:bg-surface-muted aria-[current=page]:bg-primary-soft aria-[current=page]:text-primary-soft-foreground\"\n              >\n                {item}\n              </button>\n            </Drawer.Close>\n          ))}\n        </nav>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "archive/v0.2/drawer/sides": { component: Demo311, file: "archive/v0.2/drawer/sides.tsx", source: "'use client';\n\nimport { Button, Drawer, type DrawerSide } from '@akhatmirzo/ui';\n\nconst sides: { side: DrawerSide; label: string }[] = [\n  { side: 'right', label: \"O'ngdan\" },\n  { side: 'left', label: 'Chapdan' },\n  { side: 'bottom', label: 'Pastdan' },\n  { side: 'top', label: 'Tepadan' },\n];\n\nexport default function DrawerSides() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sides.map(({ side, label }) => (\n        <Drawer key={side}>\n          <Drawer.Trigger asChild>\n            <Button variant=\"outline\">{label}</Button>\n          </Drawer.Trigger>\n          <Drawer.Content side={side} title={label} description={`side=\"${side}\"`}>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Panel ekran chetidan siljib chiqadi. Pastdan chiqqanda tepada tutqich chizig'i bor.\n            </p>\n            <Drawer.Footer>\n              <Drawer.Close asChild>\n                <Button variant=\"primary\">Yopish</Button>\n              </Drawer.Close>\n            </Drawer.Footer>\n          </Drawer.Content>\n        </Drawer>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/drawer/sizes": { component: Demo312, file: "archive/v0.2/drawer/sizes.tsx", source: "'use client';\n\nimport { Button, Drawer, type DrawerSize } from '@akhatmirzo/ui';\n\nconst sizes: { size: DrawerSize; px: string }[] = [\n  { size: 'sm', px: '320px' },\n  { size: 'md', px: '420px' },\n  { size: 'lg', px: '560px' },\n];\n\nexport default function DrawerSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sizes.map(({ size, px }) => (\n        <Drawer key={size}>\n          <Drawer.Trigger asChild>\n            <Button variant=\"outline\">\n              {size} — {px}\n            </Button>\n          </Drawer.Trigger>\n          <Drawer.Content size={size} title={`O'lcham: ${size}`} description={`Kenglik ${px}`}>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Chap va o'ngda o'lcham kenglikni, past va tepada balandlikni belgilaydi.\n            </p>\n          </Drawer.Content>\n        </Drawer>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/dropdown-menu/basic": { component: Demo313, file: "archive/v0.2/dropdown-menu/basic.tsx", source: "'use client';\n\nimport { Button, DropdownMenu, toast } from '@akhatmirzo/ui';\nimport { Archive, ChevronDown, Copy, Pencil, Trash2 } from 'lucide-react';\n\nexport default function DropdownMenuBasic() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <Button variant=\"outline\" rightIcon={<ChevronDown />}>\n          Amallar\n        </Button>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content>\n        <DropdownMenu.Item\n          icon={<Pencil />}\n          shortcut={['mod', 'E']}\n          onSelect={() => toast('Tahrirlash')}\n        >\n          Tahrirlash\n        </DropdownMenu.Item>\n        <DropdownMenu.Item\n          icon={<Copy />}\n          shortcut={['mod', 'D']}\n          onSelect={() => toast('Nusxa olindi')}\n        >\n          Nusxa olish\n        </DropdownMenu.Item>\n        <DropdownMenu.Item icon={<Archive />} onSelect={() => toast('Arxivlandi')}>\n          Arxivlash\n        </DropdownMenu.Item>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\" onSelect={() => toast(\"O'chirildi\")}>\n          O'chirish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "archive/v0.2/dropdown-menu/checkbox-radio": { component: Demo314, file: "archive/v0.2/dropdown-menu/checkbox-radio.tsx", source: "'use client';\n\nimport { DropdownMenu } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DropdownMenuCheckboxRadio() {\n  const [columns, setColumns] = useState({ price: true, stock: true, sku: false });\n  const [sort, setSort] = useState('new');\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <DropdownMenu>\n        <DropdownMenu.Trigger>Ustunlar</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Label>Jadvalda ko'rsatish</DropdownMenu.Label>\n          {(\n            [\n              ['price', 'Narx'],\n              ['stock', 'Ombordagi soni'],\n              ['sku', 'Artikul'],\n            ] as const\n          ).map(([key, label]) => (\n            <DropdownMenu.CheckboxItem\n              key={key}\n              checked={columns[key]}\n              onCheckedChange={(on) => setColumns((c) => ({ ...c, [key]: on }))}\n              // Menyu yopilmasin — bir nechtasini ketma-ket belgilash uchun\n              onSelect={(e) => e.preventDefault()}\n            >\n              {label}\n            </DropdownMenu.CheckboxItem>\n          ))}\n        </DropdownMenu.Content>\n      </DropdownMenu>\n\n      <DropdownMenu>\n        <DropdownMenu.Trigger>Saralash</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Label>Tartib</DropdownMenu.Label>\n          <DropdownMenu.RadioGroup value={sort} onValueChange={setSort}>\n            <DropdownMenu.RadioItem value=\"new\">Avval yangilari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"cheap\">Avval arzonlari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"expensive\">Avval qimmatlari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"popular\" disabled>\n              Ommabop (tez orada)\n            </DropdownMenu.RadioItem>\n          </DropdownMenu.RadioGroup>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n      <span className=\"text-sm text-text-muted\">Saralash: {sort}</span>\n    </div>\n  );\n}\n" },
  "archive/v0.2/dropdown-menu/profile": { component: Demo315, file: "archive/v0.2/dropdown-menu/profile.tsx", source: "'use client';\n\nimport { Button, DropdownMenu } from '@akhatmirzo/ui';\nimport { LogOut, Send, Settings, User } from 'lucide-react';\n\nexport default function DropdownMenuProfile() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <Button variant=\"ghost\" leftIcon={<User />}>\n          Akmal Karimov\n        </Button>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content align=\"end\" className=\"w-56\">\n        <DropdownMenu.Label>akmal@misol.uz</DropdownMenu.Label>\n        <DropdownMenu.Group>\n          <DropdownMenu.Item icon={<User />} shortcut={['mod', 'P']}>\n            Profil\n          </DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Settings />} shortcut={['mod', ',']}>\n            Sozlamalar\n          </DropdownMenu.Item>\n          <DropdownMenu.Item asChild icon={<Send />}>\n            <a href=\"https://github.com/Akhatmirzo/akhatmirzo-toolkit\">Loyiha GitHub'da</a>\n          </DropdownMenu.Item>\n        </DropdownMenu.Group>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<LogOut />} variant=\"danger\">\n          Chiqish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "archive/v0.2/dropdown-menu/states": { component: Demo316, file: "archive/v0.2/dropdown-menu/states.tsx", source: "'use client';\n\nimport { Button, DropdownMenu } from '@akhatmirzo/ui';\nimport { Copy, Pencil, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function DropdownMenuStates() {\n  const [open, setOpen] = useState(false);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <DropdownMenu>\n        <DropdownMenu.Trigger>O'chirilgan elementlar</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Item icon={<Pencil />}>Tahrirlash</DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Copy />} disabled>\n            Nusxa olish (ruxsat yo'q)\n          </DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\" disabled>\n            O'chirish (ruxsat yo'q)\n          </DropdownMenu.Item>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n\n      <DropdownMenu open={open} onOpenChange={setOpen}>\n        <DropdownMenu.Trigger>Boshqariladigan</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Item>Birinchi</DropdownMenu.Item>\n          <DropdownMenu.Item>Ikkinchi</DropdownMenu.Item>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n      <Button variant=\"ghost\" onClick={() => setOpen(true)}>\n        Tashqaridan ochish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/dropdown-menu/submenu": { component: Demo317, file: "archive/v0.2/dropdown-menu/submenu.tsx", source: "'use client';\n\nimport { DropdownMenu, IconButton } from '@akhatmirzo/ui';\nimport { Archive, Ellipsis, Pencil, Share2, Trash2 } from 'lucide-react';\n\nexport default function DropdownMenuSubmenu() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <IconButton variant=\"outline\" aria-label=\"Ko'proq amallar\">\n          <Ellipsis />\n        </IconButton>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content>\n        <DropdownMenu.Item icon={<Pencil />}>Nomini o'zgartirish</DropdownMenu.Item>\n        <DropdownMenu.Sub>\n          <DropdownMenu.SubTrigger icon={<Share2 />}>Ulashish</DropdownMenu.SubTrigger>\n          <DropdownMenu.SubContent>\n            <DropdownMenu.Item>Telegram</DropdownMenu.Item>\n            <DropdownMenu.Item>Email orqali</DropdownMenu.Item>\n            <DropdownMenu.Item shortcut={['mod', 'L']}>Havolani nusxalash</DropdownMenu.Item>\n          </DropdownMenu.SubContent>\n        </DropdownMenu.Sub>\n        <DropdownMenu.Sub>\n          <DropdownMenu.SubTrigger icon={<Archive />}>Ko'chirish</DropdownMenu.SubTrigger>\n          <DropdownMenu.SubContent>\n            <DropdownMenu.Item>Kiruvchi</DropdownMenu.Item>\n            <DropdownMenu.Item>Arxiv</DropdownMenu.Item>\n          </DropdownMenu.SubContent>\n        </DropdownMenu.Sub>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\">\n          O'chirish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "archive/v0.2/empty-state/basic": { component: Demo318, file: "archive/v0.2/empty-state/basic.tsx", source: "'use client';\n\nimport { Button, EmptyState } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\n\nexport default function EmptyStateBasic() {\n  return (\n    <EmptyState\n      icon={<Inbox />}\n      title=\"Buyurtmalar hali yo'q\"\n      description=\"Birinchi buyurtma kelganda shu yerda ko'rinadi.\"\n      action={\n        <Button variant=\"primary\" leftIcon={<Plus />}>\n          Mahsulot qo'shish\n        </Button>\n      }\n      secondaryAction={<Button variant=\"ghost\">Qo'llanma</Button>}\n    />\n  );\n}\n" },
  "archive/v0.2/empty-state/data-table": { component: Demo319, file: "archive/v0.2/empty-state/data-table.tsx", source: "'use client';\n\nimport { Button, DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: string;\n}\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№' },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa' },\n];\n\nconst orders: Order[] = [];\n\nexport default function EmptyStateDataTable() {\n  return (\n    <DataTable\n      className=\"w-full\"\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      empty={{\n        icon: <Inbox />,\n        title: \"Buyurtmalar hali yo'q\",\n        description: \"Birinchi buyurtma kelganda shu yerda ko'rinadi.\",\n        action: (\n          <Button size=\"sm\" variant=\"primary\" leftIcon={<Plus />}>\n            Buyurtma qo'shish\n          </Button>\n        ),\n      }}\n    />\n  );\n}\n" },
  "archive/v0.2/empty-state/search": { component: Demo320, file: "archive/v0.2/empty-state/search.tsx", source: "'use client';\n\nimport { Button, EmptyState, Input } from '@akhatmirzo/ui';\nimport { SearchX } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function EmptyStateSearch() {\n  const [query, setQuery] = useState('Namangan');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Input\n        aria-label=\"Shahar qidirish\"\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Shahar nomi\"\n      />\n      <EmptyState\n        size=\"sm\"\n        bordered\n        icon={<SearchX />}\n        title=\"Hech narsa topilmadi\"\n        description={`\"${query}\" bo'yicha natija yo'q. So'zni o'zgartirib ko'ring.`}\n        action={\n          <Button size=\"sm\" onClick={() => setQuery('')}>\n            Qidiruvni tozalash\n          </Button>\n        }\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/empty-state/sizes": { component: Demo321, file: "archive/v0.2/empty-state/sizes.tsx", source: "'use client';\n\nimport { EmptyState } from '@akhatmirzo/ui';\nimport { FolderOpen } from 'lucide-react';\n\nexport default function EmptyStateSizes() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <EmptyState bordered size=\"sm\" icon={<FolderOpen />} title=\"Kichik\" description=\"sm\" />\n      <EmptyState bordered size=\"md\" icon={<FolderOpen />} title=\"O'rta\" description=\"md\" />\n      <EmptyState bordered size=\"lg\" icon={<FolderOpen />} title=\"Katta\" description=\"lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/field/basic": { component: Demo322, file: "archive/v0.2/field/basic.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function FieldBasic() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" required description=\"Tasdiqlash kodi SMS orqali yuboriladi\">\n        <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" />\n      </Field>\n      <Field label=\"Email\" error=\"Email manzil noto'g'ri\">\n        <Input type=\"email\" defaultValue=\"sarvar@mail\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/field/custom-control": { component: Demo323, file: "archive/v0.2/field/custom-control.tsx", source: "'use client';\n\nimport { Field, useFieldControl } from '@akhatmirzo/ui';\n\nfunction CitySelect() {\n  const { controlProps, invalid, disabled } = useFieldControl();\n  return (\n    <select\n      {...controlProps}\n      disabled={disabled}\n      data-invalid={invalid ? '' : undefined}\n      className=\"h-10 rounded-lg border border-border bg-surface px-3 text-sm text-text data-invalid:border-danger\"\n    >\n      <option value=\"\">Tanlang</option>\n      <option>Toshkent</option>\n      <option>Samarqand</option>\n      <option>Buxoro</option>\n    </select>\n  );\n}\n\nexport default function FieldCustomControl() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Shahar\" required error=\"Shaharni tanlang\">\n        <CitySelect />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/field/disabled": { component: Demo324, file: "archive/v0.2/field/disabled.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function FieldDisabled() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Hudud\" description=\"Hudud administrator tomonidan belgilanadi\" disabled>\n        <Input defaultValue=\"Toshkent shahri\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/field/horizontal": { component: Demo325, file: "archive/v0.2/field/horizontal.tsx", source: "'use client';\n\nimport { Field, Input, Textarea } from '@akhatmirzo/ui';\n\nexport default function FieldHorizontal() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-4\">\n      <Field orientation=\"horizontal\" label=\"Do'kon nomi\" description=\"Chekda ko'rinadi\">\n        <Input defaultValue=\"Bahor Market\" />\n      </Field>\n      <Field orientation=\"horizontal\" label=\"Manzil\">\n        <Textarea minRows={2} defaultValue=\"Toshkent, Chilonzor tumani, 9-kvartal\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/field/validation": { component: Demo326, file: "archive/v0.2/field/validation.tsx", source: "'use client';\n\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function FieldValidation() {\n  const [name, setName] = useState('');\n  const [submitted, setSubmitted] = useState(false);\n  const error = submitted && name.trim().length < 3 ? 'Kamida 3 ta harf kiriting' : undefined;\n\n  const submit = (event: FormEvent) => {\n    event.preventDefault();\n    setSubmitted(true);\n  };\n\n  return (\n    <form onSubmit={submit} noValidate className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"To'liq ism\" required error={error}>\n        <Input\n          value={name}\n          onChange={(e) => setName(e.target.value)}\n          placeholder=\"Sarvar Abduxoliqov\"\n          autoComplete=\"name\"\n        />\n      </Field>\n      <Button type=\"submit\" variant=\"primary\">\n        Davom etish\n      </Button>\n    </form>\n  );\n}\n" },
  "archive/v0.2/file-upload/basic": { component: Demo327, file: "archive/v0.2/file-upload/basic.tsx", source: "'use client';\n\nimport { Field, FileUpload, type FileUploadContext, type FileUploadItem } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst MB = 1024 * 1024;\n\n/** Soxta yuklash: progress bilan ~2 soniya. Nomida \"xato\" bo'lsa — tarmoq xatosi */\nfunction fakeUpload(file: File, { onProgress, signal }: FileUploadContext) {\n  return new Promise<{ url: string }>((resolve, reject) => {\n    let progress = 0;\n    const timer = setInterval(() => {\n      progress = Math.min(100, progress + 8);\n      onProgress(progress);\n      if (file.name.includes('xato') && progress > 50) {\n        clearInterval(timer);\n        reject(new Error('network'));\n      } else if (progress === 100) {\n        clearInterval(timer);\n        resolve({ url: `/uploads/${encodeURIComponent(file.name)}` });\n      }\n    }, 150);\n    signal.addEventListener('abort', () => clearInterval(timer));\n  });\n}\n\nexport default function FileUploadBasic() {\n  const [files, setFiles] = useState<FileUploadItem[]>([]);\n  const done = files.filter((f) => f.status === 'done').length;\n\n  return (\n    <div className=\"flex w-full max-w-lg flex-col gap-2\">\n      <Field label=\"Hujjatlar\">\n        <FileUpload\n          accept={['image/*', '.pdf']}\n          maxSize={5 * MB}\n          maxFiles={5}\n          multiple\n          upload={fakeUpload}\n          onFilesChange={setFiles}\n        />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Jami: {files.length} · yuklandi: {done}\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/file-upload/button": { component: Demo328, file: "archive/v0.2/file-upload/button.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadButton() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Pasport nusxasi\" description=\"Old va orqa tomoni\">\n        <FileUpload\n          variant=\"button\"\n          accept={['image/*', '.pdf']}\n          maxSize={5 * 1024 * 1024}\n          maxFiles={2}\n          multiple\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/file-upload/form": { component: Demo329, file: "archive/v0.2/file-upload/form.tsx", source: "'use client';\n\nimport { formatFileSize } from '@akhatmirzo/core';\nimport { Button, Field, FileUpload } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function FileUploadForm() {\n  const [sent, setSent] = useState<string | null>(null);\n\n  const onSubmit = (e: FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    const files = (new FormData(e.currentTarget).getAll('rezyume') as File[]).filter(\n      (f) => f.size > 0,\n    );\n    setSent(files.map((f) => `${f.name} (${formatFileSize(f.size)})`).join(', ') || \"Fayl yo'q\");\n  };\n\n  return (\n    <form onSubmit={onSubmit} className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Rezyume\" description=\"PDF yoki DOCX, 2 MB gacha\">\n        <FileUpload\n          variant=\"button\"\n          name=\"rezyume\"\n          accept={['.pdf', '.docx']}\n          maxSize={2 * 1024 * 1024}\n        />\n      </Field>\n      <div className=\"flex items-center gap-3\">\n        <Button type=\"submit\" variant=\"primary\" size=\"sm\">\n          Yuborish\n        </Button>\n        {sent && <span className=\"text-sm text-text-muted\">{sent}</span>}\n      </div>\n    </form>\n  );\n}\n" },
  "archive/v0.2/file-upload/paste": { component: Demo330, file: "archive/v0.2/file-upload/paste.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadPaste() {\n  return (\n    <div className=\"w-full max-w-lg\">\n      <Field\n        label=\"Skrinshot\"\n        description=\"Rasmni nusxalang va sahifaning istalgan joyida Ctrl+V bosing\"\n      >\n        <FileUpload accept={['image/*']} multiple maxFiles={3} paste=\"global\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/file-upload/states": { component: Demo331, file: "archive/v0.2/file-upload/states.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadStates() {\n  return (\n    <div className=\"grid w-full gap-4 md:grid-cols-2\">\n      <Field label=\"Faqat rasm\" description=\"Bitta fayl — yangisi eskisini almashtiradi\">\n        <FileUpload accept={['image/png', 'image/jpeg']} maxSize={1024 * 1024} />\n      </Field>\n      <Field label=\"Shartnoma\" error=\"Kamida bitta hujjat yuklang\" required>\n        <FileUpload accept={['.pdf']} />\n      </Field>\n      <Field label=\"O'chirilgan\" disabled>\n        <FileUpload />\n      </Field>\n      <Field label=\"O'z cheklov matni bilan\">\n        <FileUpload hint=\"Excel yoki CSV · 10 MB gacha\" accept={['.xlsx', '.csv']} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/async": { component: Demo332, file: "archive/v0.2/hooks/async.tsx", source: "'use client';\n\nimport { useAsync, useToggle } from '@akhatmirzo/hooks';\nimport { Badge, Button, Switch } from '@akhatmirzo/ui';\n\nconst CITIES = ['Toshkent', 'Samarqand', 'Buxoro', 'Xiva', 'Namangan', 'Andijon', 'Nukus'];\nconst STATUS_COLOR = {\n  idle: 'neutral',\n  loading: 'info',\n  success: 'success',\n  error: 'danger',\n} as const;\n\nfunction fetchCities(fail: boolean): Promise<string[]> {\n  const delay = 500 + Math.random() * 1000;\n  return new Promise((resolve, reject) =>\n    setTimeout(() => {\n      if (fail) reject(new Error('Server javob bermadi'));\n      else resolve(CITIES.slice(0, 2 + Math.floor(Math.random() * 5)));\n    }, delay),\n  );\n}\n\nexport default function HooksAsync() {\n  const [fail, , setFail] = useToggle(false);\n  const { status, data, error, run } = useAsync(fetchCities, [], { immediate: false });\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Button onClick={() => void run(fail)} loading={status === 'loading'}>\n          Yuklash\n        </Button>\n        <Badge color={STATUS_COLOR[status]} dot>\n          {status}\n        </Badge>\n      </div>\n      <Switch checked={fail} onCheckedChange={setFail} label=\"Xato bilan tugasin\" />\n      {status === 'error' && error instanceof Error && (\n        <p className=\"text-sm text-danger-soft-foreground\">{error.message}</p>\n      )}\n      {data && <p className=\"text-sm text-text\">{data.join(', ')}</p>}\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/click-outside": { component: Demo333, file: "archive/v0.2/hooks/click-outside.tsx", source: "'use client';\n\nimport { useClickOutside, useHotkeys, useToggle } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useRef } from 'react';\n\nexport default function HooksClickOutside() {\n  const [open, toggle, setOpen] = useToggle(false);\n  const triggerRef = useRef<HTMLButtonElement>(null);\n  const panelRef = useRef<HTMLDivElement>(null);\n\n  useClickOutside([triggerRef, panelRef], () => setOpen(false), open);\n  useHotkeys('esc', () => setOpen(false), { enabled: open });\n\n  return (\n    <div className=\"relative flex flex-col items-center gap-2\">\n      <Button ref={triggerRef} variant=\"outline\" onClick={toggle} aria-expanded={open}>\n        Filtrlar\n      </Button>\n      {open && (\n        <div\n          ref={panelRef}\n          className=\"w-64 rounded-xl border border-border bg-surface-raised p-4 text-sm text-text shadow-lg\"\n        >\n          Panel tashqarisiga bosing yoki <kbd className=\"font-mono\">Esc</kbd> ni bosing — yopiladi.\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/controllable-state": { component: Demo334, file: "archive/v0.2/hooks/controllable-state.tsx", source: "'use client';\n\nimport { useControllableState } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\ninterface StepperProps {\n  value?: number;\n  defaultValue?: number;\n  onValueChange?: (value: number) => void;\n}\n\nfunction Stepper({ value, defaultValue = 0, onValueChange }: StepperProps) {\n  const [count, setCount] = useControllableState({ value, defaultValue, onChange: onValueChange });\n  return (\n    <div className=\"flex items-center gap-2\">\n      <Button size=\"sm\" variant=\"outline\" onClick={() => setCount((n) => n - 1)}>\n        −\n      </Button>\n      <span className=\"min-w-8 text-center font-semibold text-text tabular-nums\">{count}</span>\n      <Button size=\"sm\" variant=\"outline\" onClick={() => setCount((n) => n + 1)}>\n        +\n      </Button>\n    </div>\n  );\n}\n\nexport default function HooksControllableState() {\n  const [value, setValue] = useState(10);\n\n  return (\n    <div className=\"grid w-full max-w-md gap-6 sm:grid-cols-2\">\n      <div className=\"flex flex-col gap-2\">\n        <p className=\"text-xs font-medium text-text-muted\">Boshqarilmaydigan (defaultValue=3)</p>\n        <Stepper defaultValue={3} />\n      </div>\n      <div className=\"flex flex-col gap-2\">\n        <p className=\"text-xs font-medium text-text-muted\">Boshqariladigan (0…20)</p>\n        <Stepper value={value} onValueChange={(v) => setValue(Math.min(20, Math.max(0, v)))} />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/copy": { component: Demo335, file: "archive/v0.2/hooks/copy.tsx", source: "'use client';\n\nimport { useCopyToClipboard } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { Check, Copy } from 'lucide-react';\n\nexport default function HooksCopy() {\n  const { copied, copy } = useCopyToClipboard();\n  const command = 'pnpm add @akhatmirzo/hooks';\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <code className=\"rounded-lg border border-border bg-surface-muted px-3 py-2 font-mono text-sm text-text\">\n        {command}\n      </code>\n      <Button\n        variant={copied ? 'soft' : 'outline'}\n        leftIcon={copied ? <Check /> : <Copy />}\n        onClick={() => void copy(command)}\n      >\n        {copied ? 'Nusxalandi' : 'Nusxa olish'}\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/debounce": { component: Demo336, file: "archive/v0.2/hooks/debounce.tsx", source: "'use client';\n\nimport { useDebounce } from '@akhatmirzo/hooks';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CITIES = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Xiva',\n  'Namangan',\n  'Andijon',\n  'Nukus',\n  'Termiz',\n];\n\nexport default function HooksDebounce() {\n  const [query, setQuery] = useState('');\n  const debounced = useDebounce(query, 400);\n  const results = CITIES.filter((c) => c.toLowerCase().includes(debounced.trim().toLowerCase()));\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Shahar qidirish\" description=\"Natija yozishni to'xtatganingizdan 400 ms keyin\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <Badge color={query === debounced ? 'success' : 'warning'} dot className=\"self-start\">\n        {query === debounced ? 'Yangilangan' : 'Kutilmoqda…'}\n      </Badge>\n      <div className=\"flex flex-wrap gap-2\">\n        {results.map((city) => (\n          <Badge key={city} variant=\"outline\">\n            {city}\n          </Badge>\n        ))}\n        {results.length === 0 && (\n          <span className=\"text-sm text-text-muted\">Hech narsa topilmadi</span>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/debounced-callback": { component: Demo337, file: "archive/v0.2/hooks/debounced-callback.tsx", source: "'use client';\n\nimport { useDebouncedCallback } from '@akhatmirzo/hooks';\nimport { Button, Field, Textarea } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksDebouncedCallback() {\n  const [text, setText] = useState('');\n  const [saved, setSaved] = useState<string[]>([]);\n\n  const save = useDebouncedCallback((value: string) => {\n    setSaved((list) => [`${value.length} belgi saqlandi`, ...list].slice(0, 3));\n  }, 800);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Izoh\" description=\"Avtomatik saqlash: yozishni to'xtatgach 800 ms o'tib\">\n        <Textarea\n          value={text}\n          onChange={(e) => {\n            setText(e.target.value);\n            save(e.target.value);\n          }}\n          minRows={3}\n        />\n      </Field>\n      <Button size=\"sm\" variant=\"outline\" className=\"self-start\" onClick={save.flush}>\n        Hozir saqlash\n      </Button>\n      <ul className=\"text-sm text-text-muted\">\n        {saved.map((line, i) => (\n          <li key={i}>{line}</li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/hotkeys": { component: Demo338, file: "archive/v0.2/hooks/hotkeys.tsx", source: "'use client';\n\nimport { useHotkeys } from '@akhatmirzo/hooks';\nimport { Badge, Kbd } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksHotkeys() {\n  const [last, setLast] = useState<string | null>(null);\n  const [count, setCount] = useState(0);\n\n  const hit = (name: string) => {\n    setLast(name);\n    setCount((n) => n + 1);\n  };\n\n  useHotkeys('alt+k', () => hit('alt+k'));\n  useHotkeys('?', () => hit('?'));\n  // Bir nechta kombinatsiya — vergul bilan\n  useHotkeys('g, alt+g', () => hit('g'));\n\n  return (\n    <div className=\"flex flex-col items-center gap-3 text-sm text-text\">\n      <div className=\"flex flex-wrap items-center justify-center gap-3\">\n        <Kbd keys={['Alt', 'K']} />\n        <Kbd>?</Kbd>\n        <Kbd>G</Kbd>\n      </div>\n      <p className=\"text-text-muted\">Yuqoridagi tugmalardan birini bosing</p>\n      {last && (\n        <Badge color=\"primary\">\n          {last} · {count} marta\n        </Badge>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/intersection": { component: Demo339, file: "archive/v0.2/hooks/intersection.tsx", source: "'use client';\n\nimport { useIntersection } from '@akhatmirzo/hooks';\nimport { Spinner } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\nconst MAX = 60;\n\nexport default function HooksIntersection() {\n  const [count, setCount] = useState(12);\n  const done = count >= MAX;\n  const [sentinelRef, entry] = useIntersection<HTMLDivElement>({\n    rootMargin: '40px',\n    enabled: !done,\n  });\n  const visible = entry?.isIntersecting ?? false;\n\n  useEffect(() => {\n    if (!visible || done) return;\n    // Haqiqiy ilovada — keyingi sahifani serverdan yuklash\n    const timer = setTimeout(() => setCount((n) => Math.min(MAX, n + 12)), 500);\n    return () => clearTimeout(timer);\n  }, [visible, done, count]);\n\n  return (\n    <div className=\"h-64 w-full max-w-sm overflow-auto rounded-xl border border-border bg-surface\">\n      <ul className=\"divide-y divide-border text-sm text-text\">\n        {Array.from({ length: count }, (_, i) => (\n          <li key={i} className=\"px-4 py-2\">\n            Buyurtma #{1000 + i}\n          </li>\n        ))}\n      </ul>\n      <div\n        ref={sentinelRef}\n        className=\"flex items-center justify-center gap-2 p-3 text-sm text-text-muted\"\n      >\n        {done ? (\n          'Hammasi yuklandi'\n        ) : (\n          <>\n            <Spinner size=\"sm\" /> Yuklanmoqda…\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/local-storage": { component: Demo340, file: "archive/v0.2/hooks/local-storage.tsx", source: "'use client';\n\nimport { useLocalStorage } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\n\nfunction Mirror() {\n  const [count] = useLocalStorage('docs-demo:counter', 0);\n  return (\n    <p className=\"text-sm text-text-muted\">\n      Boshqa komponent ko'rayotgan qiymat: <strong className=\"text-text\">{count}</strong>\n    </p>\n  );\n}\n\nexport default function HooksLocalStorage() {\n  const [count, setCount, remove] = useLocalStorage('docs-demo:counter', 0);\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <div className=\"flex items-center gap-2\">\n        <Button variant=\"outline\" onClick={() => setCount((n) => n - 1)}>\n          −\n        </Button>\n        <span className=\"min-w-12 text-center text-2xl font-semibold text-text tabular-nums\">\n          {count}\n        </span>\n        <Button variant=\"outline\" onClick={() => setCount((n) => n + 1)}>\n          +\n        </Button>\n        <Button variant=\"ghost\" onClick={remove}>\n          O'chirish\n        </Button>\n      </div>\n      <Mirror />\n      <p className=\"text-xs text-text-faint\">\n        Sahifani boshqa tabda oching — qiymat sinxron o'zgaradi\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/media-query": { component: Demo341, file: "archive/v0.2/hooks/media-query.tsx", source: "'use client';\n\nimport { useMediaQuery } from '@akhatmirzo/hooks';\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function HooksMediaQuery() {\n  const queries = [\n    { label: '≥ 640px', on: useMediaQuery('(min-width: 640px)') },\n    { label: '≥ 1024px', on: useMediaQuery('(min-width: 1024px)') },\n    { label: \"Tizim: qorong'i mavzu\", on: useMediaQuery('(prefers-color-scheme: dark)') },\n    { label: 'Kam animatsiya', on: useMediaQuery('(prefers-reduced-motion: reduce)') },\n    { label: 'Sichqoncha (hover)', on: useMediaQuery('(hover: hover)') },\n  ];\n\n  return (\n    <div className=\"flex flex-wrap justify-center gap-2\">\n      {queries.map(({ label, on }) => (\n        <Badge key={label} color={on ? 'success' : 'neutral'} variant={on ? 'soft' : 'outline'} dot>\n          {label}\n        </Badge>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/pagination": { component: Demo342, file: "archive/v0.2/hooks/pagination.tsx", source: "'use client';\n\nimport { usePagination } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksPagination() {\n  const [page, setPage] = useState(5);\n  const { pages, hasPrev, hasNext, from, to } = usePagination({ total: 200, pageSize: 10, page });\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <nav aria-label=\"Sahifalar\" className=\"flex flex-wrap items-center justify-center gap-1\">\n        <Button size=\"sm\" variant=\"ghost\" disabled={!hasPrev} onClick={() => setPage(page - 1)}>\n          Oldingi\n        </Button>\n        {pages.map((p, i) =>\n          p === 'ellipsis' ? (\n            <span key={`e${i}`} className=\"px-2 text-text-muted\">\n              …\n            </span>\n          ) : (\n            <Button\n              key={p}\n              size=\"sm\"\n              variant={p === page ? 'primary' : 'ghost'}\n              aria-current={p === page ? 'page' : undefined}\n              onClick={() => setPage(p)}\n            >\n              {p}\n            </Button>\n          ),\n        )}\n        <Button size=\"sm\" variant=\"ghost\" disabled={!hasNext} onClick={() => setPage(page + 1)}>\n          Keyingi\n        </Button>\n      </nav>\n      <p className=\"text-sm text-text-muted\">\n        {from}–{to} / 200 ta yozuv\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/hooks/toggle": { component: Demo343, file: "archive/v0.2/hooks/toggle.tsx", source: "'use client';\n\nimport { useToggle } from '@akhatmirzo/hooks';\nimport { Button, Switch } from '@akhatmirzo/ui';\n\nexport default function HooksToggle() {\n  const [notify, toggleNotify, setNotify] = useToggle(true);\n\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Switch\n        checked={notify}\n        onCheckedChange={setNotify}\n        label=\"SMS xabarnomalar\"\n        description={notify ? 'Yoqilgan' : \"O'chirilgan\"}\n      />\n      <div className=\"flex flex-wrap gap-2\">\n        <Button variant=\"outline\" onClick={toggleNotify}>\n          Almashtirish\n        </Button>\n        <Button variant=\"ghost\" onClick={() => setNotify(false)}>\n          O'chirish\n        </Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/icon-button/as-child": { component: Demo344, file: "archive/v0.2/icon-button/as-child.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Settings } from 'lucide-react';\n\nexport default function IconButtonAsChild() {\n  return (\n    <IconButton asChild variant=\"outline\" aria-label=\"Sozlamalar\">\n      <a href=\"#props\">\n        <Settings />\n      </a>\n    </IconButton>\n  );\n}\n" },
  "archive/v0.2/icon-button/sizes": { component: Demo345, file: "archive/v0.2/icon-button/sizes.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { X } from 'lucide-react';\n\nexport default function IconButtonSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton variant=\"outline\" size=\"sm\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n      <IconButton variant=\"outline\" size=\"md\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n      <IconButton variant=\"outline\" size=\"lg\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.2/icon-button/states": { component: Demo346, file: "archive/v0.2/icon-button/states.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Download, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function IconButtonStates() {\n  const [loading, setLoading] = useState(false);\n\n  const download = () => {\n    setLoading(true);\n    setTimeout(() => setLoading(false), 1500);\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton\n        variant=\"primary\"\n        loading={loading}\n        onClick={download}\n        aria-label=\"Hisobotni yuklab olish\"\n        labels={{ loading: 'Yuklab olinmoqda' }}\n      >\n        <Download />\n      </IconButton>\n      <IconButton variant=\"danger\" disabled aria-label=\"O'chirish\">\n        <Trash2 />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.2/icon-button/toolbar": { component: Demo347, file: "archive/v0.2/icon-button/toolbar.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Bold, Italic, Plus, Underline } from 'lucide-react';\n\nexport default function IconButtonToolbar() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <div\n        role=\"toolbar\"\n        aria-label=\"Matn formati\"\n        className=\"flex items-center gap-1 rounded-lg border border-border bg-surface p-1\"\n      >\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Qalin\">\n          <Bold />\n        </IconButton>\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Kursiv\">\n          <Italic />\n        </IconButton>\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Tagiga chizilgan\">\n          <Underline />\n        </IconButton>\n      </div>\n      <IconButton variant=\"primary\" size=\"lg\" className=\"rounded-full\" aria-label=\"Yangi buyurtma\">\n        <Plus />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.2/icon-button/variants": { component: Demo348, file: "archive/v0.2/icon-button/variants.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Heart, Pencil, Plus, Share2, Trash2 } from 'lucide-react';\n\nexport default function IconButtonVariants() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton variant=\"primary\" aria-label=\"Qo'shish\">\n        <Plus />\n      </IconButton>\n      <IconButton aria-label=\"Sevimlilarga qo'shish\">\n        <Heart />\n      </IconButton>\n      <IconButton variant=\"outline\" aria-label=\"Tahrirlash\">\n        <Pencil />\n      </IconButton>\n      <IconButton variant=\"ghost\" aria-label=\"Ulashish\">\n        <Share2 />\n      </IconButton>\n      <IconButton variant=\"danger\" aria-label=\"O'chirish\">\n        <Trash2 />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.2/input/addons": { component: Demo349, file: "archive/v0.2/input/addons.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Mail } from 'lucide-react';\n\nexport default function InputAddons() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" aria-label=\"Telefon\" />\n      <Input suffix=\"so'm\" placeholder=\"1 250 000\" inputMode=\"numeric\" aria-label=\"Narx\" />\n      <Input rightIcon={<Mail />} type=\"email\" placeholder=\"email@misol.uz\" aria-label=\"Email\" />\n      <Input prefix=\"https://\" suffix=\".uz\" placeholder=\"dokon\" aria-label=\"Sayt manzili\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/input/basic": { component: Demo350, file: "archive/v0.2/input/basic.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Search } from 'lucide-react';\n\nexport default function InputBasic() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Input leftIcon={<Search />} placeholder=\"Mahsulot qidirish\" aria-label=\"Mahsulot qidirish\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/input/clearable": { component: Demo351, file: "archive/v0.2/input/clearable.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Search } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function InputClearable() {\n  const [query, setQuery] = useState('Samarqand');\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-2\">\n      <Input\n        leftIcon={<Search />}\n        clearable\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Shahar qidirish\"\n        aria-label=\"Shahar qidirish\"\n      />\n      <p className=\"text-xs text-text-muted\">Qiymat: {query || '—'}</p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/input/password": { component: Demo352, file: "archive/v0.2/input/password.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function InputPassword() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Parol\" description=\"Kamida 8 ta belgi\">\n        <Input type=\"password\" defaultValue=\"maxfiy123\" autoComplete=\"current-password\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/input/sizes": { component: Demo353, file: "archive/v0.2/input/sizes.tsx", source: "'use client';\n\nimport { Button, Input } from '@akhatmirzo/ui';\n\nexport default function InputSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"sm\" placeholder=\"Kichik · 32\" aria-label=\"Kichik\" />\n        <Button size=\"sm\">Qo'llash</Button>\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"md\" placeholder=\"O'rta · 40\" aria-label=\"O'rta\" />\n        <Button size=\"md\">Qo'llash</Button>\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"lg\" placeholder=\"Katta · 48\" aria-label=\"Katta\" />\n        <Button size=\"lg\">Qo'llash</Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/input/states": { component: Demo354, file: "archive/v0.2/input/states.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\n\nexport default function InputStates() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-3 sm:grid-cols-2\">\n      <Input placeholder=\"Oddiy\" aria-label=\"Oddiy\" />\n      <Input invalid defaultValue=\"sarvar@mail\" aria-label=\"Xato\" />\n      <Input disabled defaultValue=\"O'chirilgan\" aria-label=\"O'chirilgan\" />\n      <Input readOnly defaultValue=\"Faqat o'qish uchun\" aria-label=\"Faqat o'qish\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/input/with-field": { component: Demo355, file: "archive/v0.2/input/with-field.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { Mail } from 'lucide-react';\n\nexport default function InputWithField() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" required description=\"Tasdiqlash kodi SMS orqali keladi\">\n        <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" />\n      </Field>\n      <Field label=\"Email\" error=\"Email manzil noto'g'ri\">\n        <Input leftIcon={<Mail />} defaultValue=\"sarvar@mail\" clearable />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/kbd/basic": { component: Demo356, file: "archive/v0.2/kbd/basic.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdBasic() {\n  return (\n    <p className=\"text-sm text-text\">\n      Qidiruvni ochish uchun <Kbd keys={['mod', 'K']} /> ni bosing, yopish uchun <Kbd>Esc</Kbd>.\n    </p>\n  );\n}\n" },
  "archive/v0.2/kbd/keys": { component: Demo357, file: "archive/v0.2/kbd/keys.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdKeys() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Kbd keys={['mod', 'K']} />\n      <Kbd keys={['mod', 'Shift', 'P']} />\n      <Kbd keys={['Alt', 'F4']} />\n      <Kbd>Esc</Kbd>\n      <Kbd>↵</Kbd>\n      <Kbd>↑</Kbd>\n      <Kbd>↓</Kbd>\n    </div>\n  );\n}\n" },
  "archive/v0.2/kbd/menu": { component: Demo358, file: "archive/v0.2/kbd/menu.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nconst items = [\n  { label: 'Nusxa olish', keys: ['mod', 'C'] },\n  { label: \"Qo'yish\", keys: ['mod', 'V'] },\n  { label: 'Hammasini tanlash', keys: ['mod', 'A'] },\n];\n\nexport default function KbdMenu() {\n  return (\n    <ul className=\"flex w-64 flex-col rounded-lg border border-border bg-surface p-1 text-sm text-text\">\n      {items.map((item) => (\n        <li key={item.label} className=\"flex items-center justify-between rounded-md px-2 py-1.5\">\n          {item.label}\n          <Kbd keys={item.keys} />\n        </li>\n      ))}\n    </ul>\n  );\n}\n" },
  "archive/v0.2/kbd/sizes": { component: Demo359, file: "archive/v0.2/kbd/sizes.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Kbd keys={['mod', 'C']} />\n      <Kbd size=\"md\" keys={['mod', 'C']} />\n    </div>\n  );\n}\n" },
  "archive/v0.2/masked-input/card": { component: Demo360, file: "archive/v0.2/masked-input/card.tsx", source: "'use client';\n\nimport { CardInput, Field, getCardDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CardInputDemo() {\n  const [card, setCard] = useState('');\n  const { complete, valid, brand } = getCardDetails(card);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field\n        label=\"Karta raqami\"\n        error={complete && !valid ? \"Karta raqami noto'g'ri\" : undefined}\n        description={\n          valid ? `Karta to'g'ri · ${brand ?? 'boshqa'}` : \"Sinab ko'ring: 4111 1111 1111 1111\"\n        }\n      >\n        <CardInput value={card} onValueChange={setCard} />\n      </Field>\n      <div className=\"flex flex-col gap-3\">\n        <CardInput aria-label=\"Uzcard\" defaultValue=\"8600123412341234\" />\n        <CardInput aria-label=\"Humo\" defaultValue=\"9860010203040506\" />\n        <CardInput aria-label=\"Luhn xato\" defaultValue=\"4111111111111112\" />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/masked-input/custom-mask": { component: Demo361, file: "archive/v0.2/masked-input/custom-mask.tsx", source: "'use client';\n\nimport { Field, MaskedInput } from '@akhatmirzo/ui';\n\nexport default function MaskedInputCustom() {\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Avtomobil raqami\" description='mask=\"99 A 999 AA\"'>\n        <MaskedInput mask=\"99 A 999 AA\" uppercase placeholder=\"01 A 123 BC\" />\n      </Field>\n      <Field label=\"JShShIR\" description=\"14 ta raqam\">\n        <MaskedInput mask=\"99999999999999\" inputMode=\"numeric\" placeholder=\"14 raqam\" />\n      </Field>\n      <Field label=\"Vaqt\" description='mask=\"99:99\"'>\n        <MaskedInput mask=\"99:99\" inputMode=\"numeric\" placeholder=\"09:30\" />\n      </Field>\n      <Field label=\"Promo-kod\" description='mask=\"****-****\"'>\n        <MaskedInput mask=\"****-****\" uppercase placeholder=\"XXXX-XXXX\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/masked-input/money": { component: Demo362, file: "archive/v0.2/masked-input/money.tsx", source: "'use client';\n\nimport { Field, MoneyInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MoneyInputDemo() {\n  const [price, setPrice] = useState<number | null>(null);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Narx\" description={`Qiymat: ${price ?? 'null'}`}>\n        <MoneyInput value={price} onValueChange={setPrice} clearable />\n      </Field>\n      <Field label=\"Kurs\" description='decimals={2}, currency=\"$\"'>\n        <MoneyInput decimals={2} currency=\"$\" defaultValue={12.5} />\n      </Field>\n      <Field label=\"Oylik to'lov\" description=\"100 000 dan 50 000 000 gacha\">\n        <MoneyInput min={100000} max={50000000} />\n      </Field>\n      <Field label=\"Valyutasiz\" description=\"currency={null}\">\n        <MoneyInput currency={null} defaultValue={980000} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/masked-input/overview": { component: Demo363, file: "archive/v0.2/masked-input/overview.tsx", source: "'use client';\n\nimport { CardInput, Field, MaskedInput, MoneyInput, PhoneInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MaskedInputOverview() {\n  const [phone, setPhone] = useState('');\n  const [sum, setSum] = useState<number | null>(1250000);\n  const [card, setCard] = useState('');\n  const [passport, setPassport] = useState('');\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Telefon\" description={`Qiymat: \"${phone}\"`}>\n        <PhoneInput value={phone} onValueChange={setPhone} />\n      </Field>\n      <Field label=\"Summa\" description={`Qiymat: ${sum ?? 'null'}`}>\n        <MoneyInput value={sum} onValueChange={setSum} />\n      </Field>\n      <Field label=\"Karta raqami\" description={`Qiymat: \"${card}\"`}>\n        <CardInput value={card} onValueChange={setCard} />\n      </Field>\n      <Field label=\"Pasport\" description={`Qiymat: \"${passport}\"`}>\n        <MaskedInput\n          mask=\"AA 9999999\"\n          uppercase\n          placeholder=\"AB 1234567\"\n          value={passport}\n          onValueChange={setPassport}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/masked-input/phone": { component: Demo364, file: "archive/v0.2/masked-input/phone.tsx", source: "'use client';\n\nimport { Field, PhoneInput, type PhoneInputDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PhoneInputDemo() {\n  const [phone, setPhone] = useState('');\n  const [details, setDetails] = useState<PhoneInputDetails | null>(null);\n\n  const badOperator = phone.length >= 2 && !details?.operator;\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Field\n        label=\"Telefon raqami\"\n        required\n        error={badOperator ? `\"${phone.slice(0, 2)}\" — bunday operator kodi yo'q` : undefined}\n        description={\n          details?.valid ? `Operator: ${details.operator}` : '+998 90 123 45 67 ni joylang'\n        }\n      >\n        <PhoneInput\n          value={phone}\n          onValueChange={(value, info) => {\n            setPhone(value);\n            setDetails(info);\n          }}\n        />\n      </Field>\n      <PhoneInput aria-label=\"Kichik\" size=\"sm\" defaultValue=\"991234567\" />\n      <PhoneInput aria-label=\"Faqat o'qish\" readOnly defaultValue=\"935554433\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/otp-input/length": { component: Demo365, file: "archive/v0.2/otp-input/length.tsx", source: "'use client';\n\nimport { OtpInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function OtpInputLength() {\n  const [promo, setPromo] = useState('');\n\n  return (\n    <div className=\"flex flex-col items-start gap-5\">\n      <OtpInput length={4} aria-label=\"4 xonali PIN\" />\n      <OtpInput length={6} groupSize={2} aria-label=\"Juft guruhli kod\" />\n      <div className=\"flex flex-col gap-2\">\n        <OtpInput\n          type=\"alphanumeric\"\n          groupSize={3}\n          aria-label=\"Harfli kod\"\n          value={promo}\n          onValueChange={setPromo}\n        />\n        <span className=\"text-sm text-text-muted\">Qiymat: {promo || '—'}</span>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/otp-input/resend": { component: Demo366, file: "archive/v0.2/otp-input/resend.tsx", source: "'use client';\n\nimport { OtpInput, toast } from '@akhatmirzo/ui';\n\nconst sendSms = () =>\n  new Promise<void>((resolve) => {\n    setTimeout(() => {\n      toast('SMS qayta yuborildi');\n      resolve();\n    }, 800);\n  });\n\nexport default function OtpResendTimer() {\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <OtpInput.ResendTimer seconds={5} onResend={() => toast('Kod qayta yuborildi')} />\n      <OtpInput.ResendTimer\n        seconds={3}\n        labels={{ resend: 'SMS ni qayta olish' }}\n        onResend={sendSms}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/otp-input/states": { component: Demo367, file: "archive/v0.2/otp-input/states.tsx", source: "'use client';\n\nimport { OtpInput } from '@akhatmirzo/ui';\n\nexport default function OtpInputStates() {\n  return (\n    <div className=\"flex flex-col items-start gap-5\">\n      <OtpInput invalid defaultValue=\"482913\" groupSize={3} aria-label=\"Xato kod\" />\n      <OtpInput disabled defaultValue=\"12\" groupSize={3} aria-label=\"O'chirilgan\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/otp-input/verify": { component: Demo368, file: "archive/v0.2/otp-input/verify.tsx", source: "'use client';\n\nimport { Field, OtpInput, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CORRECT = '123456';\n\nexport default function OtpInputVerify() {\n  const [code, setCode] = useState('');\n  const [status, setStatus] = useState<'idle' | 'error' | 'ok'>('idle');\n\n  return (\n    <div className=\"flex flex-col gap-2\">\n      <Field\n        label=\"Tasdiqlash kodi\"\n        description={\n          status === 'ok' ? 'Kod tasdiqlandi' : `+998 90 *** ** 67 ga yuborildi. Kod: ${CORRECT}`\n        }\n        error={status === 'error' ? \"Kod noto'g'ri. Qayta urinib ko'ring.\" : undefined}\n      >\n        <OtpInput\n          groupSize={3}\n          value={code}\n          disabled={status === 'ok'}\n          onValueChange={(value) => {\n            setCode(value);\n            if (status === 'error') setStatus('idle');\n          }}\n          onComplete={(value) => setStatus(value === CORRECT ? 'ok' : 'error')}\n        />\n      </Field>\n      <OtpInput.ResendTimer\n        onResend={() => {\n          setCode('');\n          setStatus('idle');\n          toast('Yangi kod yuborildi');\n        }}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/pagination/basic": { component: Demo369, file: "archive/v0.2/pagination/basic.tsx", source: "'use client';\n\nimport { Pagination, PaginationInfo } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PaginationBasic() {\n  const [page, setPage] = useState(3);\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <Pagination page={page} onPageChange={setPage} total={230} pageSize={10} />\n      <PaginationInfo page={page} pageSize={10} total={230} />\n    </div>\n  );\n}\n" },
  "archive/v0.2/pagination/compact": { component: Demo370, file: "archive/v0.2/pagination/compact.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\n\nexport default function PaginationCompact() {\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Pagination defaultPage={3} pageCount={24} compact />\n      <Pagination defaultPage={3} pageCount={24} compact size=\"sm\" showFirstLast />\n    </div>\n  );\n}\n" },
  "archive/v0.2/pagination/data-table": { component: Demo371, file: "archive/v0.2/pagination/data-table.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, Pagination, PaginationInfo, type DataTableColumn } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\nconst ORDERS: Order[] = Array.from({ length: 47 }, (_, i) => ({\n  id: 3001 + i,\n  customer: NAMES[i % NAMES.length]!,\n  total: 120_000 + ((i * 314_159) % 2_500_000),\n}));\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88 },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nconst PAGE_SIZE = 5;\n\nexport default function PaginationDataTable() {\n  const [page, setPage] = useState(1);\n  const rows = ORDERS.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);\n\n  return (\n    <div className=\"flex w-full flex-col gap-3\">\n      <DataTable label=\"Buyurtmalar\" data={rows} columns={columns} className=\"w-full\" />\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <PaginationInfo page={page} pageSize={PAGE_SIZE} total={ORDERS.length} />\n        <Pagination\n          page={page}\n          onPageChange={setPage}\n          total={ORDERS.length}\n          pageSize={PAGE_SIZE}\n          size=\"sm\"\n        />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/pagination/first-last": { component: Demo372, file: "archive/v0.2/pagination/first-last.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\n\nexport default function PaginationFirstLast() {\n  return <Pagination defaultPage={10} pageCount={40} siblings={2} showFirstLast compact={false} />;\n}\n" },
  "archive/v0.2/pagination/links": { component: Demo373, file: "archive/v0.2/pagination/links.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PaginationLinks() {\n  // Haqiqiy loyihada sahifa URL'dan o'qiladi: ?page=3\n  const [page, setPage] = useState(1);\n\n  return (\n    <Pagination page={page} onPageChange={setPage} pageCount={8} getHref={(p) => `#sahifa-${p}`} />\n  );\n}\n" },
  "archive/v0.2/pagination/sizes": { component: Demo374, file: "archive/v0.2/pagination/sizes.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\n\nexport default function PaginationSizes() {\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Pagination defaultPage={4} pageCount={12} size=\"sm\" compact={false} />\n      <Pagination defaultPage={4} pageCount={12} compact={false} />\n    </div>\n  );\n}\n" },
  "archive/v0.2/popover/color-picker": { component: Demo375, file: "archive/v0.2/popover/color-picker.tsx", source: "'use client';\n\nimport { Button, Popover } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst colors = [\n  { name: 'Asosiy', className: 'bg-primary' },\n  { name: 'Yashil', className: 'bg-success' },\n  { name: 'Sariq', className: 'bg-warning' },\n  { name: 'Qizil', className: 'bg-danger' },\n  { name: \"Ko'k\", className: 'bg-info' },\n];\n\nexport default function PopoverColorPicker() {\n  const [color, setColor] = useState(colors[0]!);\n\n  return (\n    <Popover>\n      <Popover.Trigger asChild>\n        <Button\n          variant=\"outline\"\n          leftIcon={<span className={`size-3 rounded-full ${color.className}`} />}\n        >\n          Teg rangi\n        </Button>\n      </Popover.Trigger>\n      <Popover.Content className=\"w-auto\" aria-label=\"Rang tanlash\">\n        <div className=\"flex gap-2\">\n          {colors.map((c) => (\n            <Popover.Close key={c.name} asChild>\n              <button\n                type=\"button\"\n                aria-label={c.name}\n                aria-pressed={c.name === color.name}\n                onClick={() => setColor(c)}\n                className={`focus-ring size-7 cursor-pointer rounded-full border-2 border-surface-raised ${c.className} aria-pressed:ring-2 aria-pressed:ring-primary`}\n              />\n            </Popover.Close>\n          ))}\n        </div>\n      </Popover.Content>\n    </Popover>\n  );\n}\n" },
  "archive/v0.2/popover/filter": { component: Demo376, file: "archive/v0.2/popover/filter.tsx", source: "'use client';\n\nimport { Button, Input, Popover } from '@akhatmirzo/ui';\nimport { Funnel } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function PopoverFilter() {\n  const [open, setOpen] = useState(false);\n  const [range, setRange] = useState({ from: '', to: '' });\n  const [applied, setApplied] = useState<string | null>(null);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Popover open={open} onOpenChange={setOpen}>\n        <Popover.Trigger asChild>\n          <Button leftIcon={<Funnel />}>Narx</Button>\n        </Popover.Trigger>\n        <Popover.Content align=\"start\" aria-label=\"Narx filtri\">\n          <form\n            className=\"flex flex-col gap-3\"\n            onSubmit={(e) => {\n              e.preventDefault();\n              setApplied(`${range.from || '0'} – ${range.to || '∞'} so'm`);\n              setOpen(false);\n            }}\n          >\n            <p className=\"m-0 font-semibold\">Narx oralig'i</p>\n            <Input\n              size=\"sm\"\n              inputMode=\"numeric\"\n              placeholder=\"dan\"\n              suffix=\"so'm\"\n              aria-label=\"Narx: dan\"\n              value={range.from}\n              onChange={(e) => setRange((r) => ({ ...r, from: e.target.value }))}\n            />\n            <Input\n              size=\"sm\"\n              inputMode=\"numeric\"\n              placeholder=\"gacha\"\n              suffix=\"so'm\"\n              aria-label=\"Narx: gacha\"\n              value={range.to}\n              onChange={(e) => setRange((r) => ({ ...r, to: e.target.value }))}\n            />\n            <div className=\"mt-1 flex justify-end gap-2\">\n              <Popover.Close asChild>\n                <Button size=\"sm\">Bekor</Button>\n              </Popover.Close>\n              <Button size=\"sm\" variant=\"primary\" type=\"submit\">\n                Qo'llash\n              </Button>\n            </div>\n          </form>\n        </Popover.Content>\n      </Popover>\n      <span className=\"text-sm text-text-muted\">{applied ?? \"Filtr qo'llanmagan\"}</span>\n    </div>\n  );\n}\n" },
  "archive/v0.2/popover/placement": { component: Demo377, file: "archive/v0.2/popover/placement.tsx", source: "'use client';\n\nimport { Button, Popover } from '@akhatmirzo/ui';\n\nexport default function PopoverPlacement() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {(['top', 'right', 'bottom', 'left'] as const).map((side) => (\n        <Popover key={side}>\n          <Popover.Trigger asChild>\n            <Button variant=\"outline\">{side}</Button>\n          </Popover.Trigger>\n          <Popover.Content side={side} arrow className=\"w-56\" aria-label={`Tomon: ${side}`}>\n            <p className=\"m-0 text-text-muted\">\n              Panel <b className=\"text-text\">{side}</b> tomonda, triggerdan 6px uzoqlikda.\n            </p>\n          </Popover.Content>\n        </Popover>\n      ))}\n      <Popover>\n        <Popover.Trigger asChild>\n          <Button variant=\"outline\">align=end</Button>\n        </Popover.Trigger>\n        <Popover.Content align=\"end\" className=\"w-56\" aria-label=\"O'ngga tekislangan\">\n          <p className=\"m-0 text-text-muted\">Panel triggerning o'ng chetiga tekislangan.</p>\n        </Popover.Content>\n      </Popover>\n    </div>\n  );\n}\n" },
  "archive/v0.2/popover/settings": { component: Demo378, file: "archive/v0.2/popover/settings.tsx", source: "'use client';\n\nimport { Field, IconButton, Popover, Switch } from '@akhatmirzo/ui';\nimport { Bell } from 'lucide-react';\n\nexport default function PopoverSettings() {\n  return (\n    <Popover>\n      <Popover.Trigger asChild>\n        <IconButton variant=\"outline\" aria-label=\"Bildirishnoma sozlamalari\">\n          <Bell />\n        </IconButton>\n      </Popover.Trigger>\n      <Popover.Content side=\"right\" align=\"start\" arrow aria-label=\"Bildirishnomalar\">\n        <div className=\"flex flex-col gap-3\">\n          <p className=\"m-0 font-semibold\">Bildirishnomalar</p>\n          <Field label=\"Email orqali\" orientation=\"horizontal\">\n            <Switch defaultChecked />\n          </Field>\n          <Field label=\"SMS orqali\" orientation=\"horizontal\">\n            <Switch />\n          </Field>\n          <Field label=\"Telegram bot\" orientation=\"horizontal\">\n            <Switch defaultChecked />\n          </Field>\n        </div>\n      </Popover.Content>\n    </Popover>\n  );\n}\n" },
  "archive/v0.2/progress/basic": { component: Demo379, file: "archive/v0.2/progress/basic.tsx", source: "'use client';\n\nimport { Progress } from '@akhatmirzo/ui';\n\nexport default function ProgressBasic() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-6\">\n      <Progress value={64} label=\"Yuklanmoqda\" showValue />\n      <Progress\n        value={3}\n        max={5}\n        label=\"Profil to'ldirildi\"\n        showValue\n        formatValue={(value, max) => `${value} / ${max}`}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/progress/circle": { component: Demo380, file: "archive/v0.2/progress/circle.tsx", source: "'use client';\n\nimport { ProgressCircle } from '@akhatmirzo/ui';\n\nexport default function ProgressCircleDemo() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <ProgressCircle value={30} size=\"sm\" label=\"Sinxronlash\" />\n      <ProgressCircle value={58} showValue label=\"Saqlash\" />\n      <ProgressCircle value={72} size=\"lg\" showValue label=\"Kurs\" color=\"success\" />\n      <ProgressCircle value={100} size=\"lg\" showValue label=\"Tayyor\" color=\"success\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/progress/colors-sizes": { component: Demo381, file: "archive/v0.2/progress/colors-sizes.tsx", source: "'use client';\n\nimport { Progress } from '@akhatmirzo/ui';\n\nexport default function ProgressColorsSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-5\">\n      <Progress value={40} size=\"sm\" aria-label=\"Kichik chiziq\" />\n      <Progress value={55} color=\"success\" aria-label=\"O'rta chiziq\" />\n      <Progress value={80} size=\"lg\" color=\"warning\" aria-label=\"Katta chiziq\" />\n      <Progress value={95} color=\"danger\" label=\"Disk to'lib bormoqda\" showValue />\n    </div>\n  );\n}\n" },
  "archive/v0.2/progress/indeterminate": { component: Demo382, file: "archive/v0.2/progress/indeterminate.tsx", source: "'use client';\n\nimport { Progress, ProgressCircle } from '@akhatmirzo/ui';\n\nexport default function ProgressIndeterminate() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-6\">\n      <Progress value={null} label=\"Fayl tayyorlanmoqda\" />\n      <ProgressCircle value={null} label=\"Yuklanmoqda\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/progress/upload": { component: Demo383, file: "archive/v0.2/progress/upload.tsx", source: "'use client';\n\nimport { Button, Progress } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\nexport default function ProgressUpload() {\n  const [value, setValue] = useState(0);\n  const [running, setRunning] = useState(false);\n\n  useEffect(() => {\n    if (!running) return;\n    const id = setInterval(() => setValue((v) => Math.min(v + 8, 100)), 300);\n    return () => clearInterval(id);\n  }, [running]);\n\n  const done = value === 100;\n  if (done && running) setRunning(false);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Progress value={value} label=\"hisobot.pdf\" showValue color={done ? 'success' : 'primary'} />\n      <Button\n        size=\"sm\"\n        className=\"self-start\"\n        disabled={running}\n        onClick={() => {\n          setValue(0);\n          setRunning(true);\n        }}\n      >\n        {done ? 'Qayta yuklash' : 'Yuklashni boshlash'}\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/radio-group/basic": { component: Demo384, file: "archive/v0.2/radio-group/basic.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupBasic() {\n  return (\n    <RadioGroup aria-label=\"To'lov usuli\" defaultValue=\"click\">\n      <Radio value=\"click\" label=\"Click\" />\n      <Radio value=\"payme\" label=\"Payme\" />\n      <Radio value=\"cash\" label=\"Naqd pul\" />\n    </RadioGroup>\n  );\n}\n" },
  "archive/v0.2/radio-group/card": { component: Demo385, file: "archive/v0.2/radio-group/card.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RadioGroupCard() {\n  const [plan, setPlan] = useState('pro');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <RadioGroup aria-label=\"Tarif\" variant=\"card\" value={plan} onValueChange={setPlan}>\n        <Radio value=\"free\" label=\"Bepul\" description=\"1 ta do'kon, asosiy imkoniyatlar\" />\n        <Radio\n          value=\"pro\"\n          label=\"Pro · 149 000 so'm\"\n          description=\"Cheksiz do'konlar va hisobotlar\"\n        />\n        <Radio value=\"team\" label=\"Jamoa\" description=\"Tez orada\" disabled />\n      </RadioGroup>\n      <p className=\"text-sm text-text-muted\">Tanlangan tarif: {plan}</p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/radio-group/horizontal": { component: Demo386, file: "archive/v0.2/radio-group/horizontal.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupHorizontal() {\n  return (\n    <RadioGroup aria-label=\"Yetkazib berish\" orientation=\"horizontal\" defaultValue=\"express\">\n      <Radio value=\"express\" label=\"Tezkor\" />\n      <Radio value=\"standard\" label=\"Oddiy\" />\n      <Radio value=\"pickup\" label=\"Olib ketish\" />\n    </RadioGroup>\n  );\n}\n" },
  "archive/v0.2/radio-group/sizes": { component: Demo387, file: "archive/v0.2/radio-group/sizes.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-10\">\n      <RadioGroup aria-label=\"Interfeys tili (kichik)\" size=\"sm\" defaultValue=\"uz\">\n        <Radio value=\"uz\" label=\"O'zbekcha\" />\n        <Radio value=\"ru\" label=\"Ruscha\" description=\"Kirill yozuvida\" />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Interfeys tili (o'rta)\" defaultValue=\"uz\">\n        <Radio value=\"uz\" label=\"O'zbekcha\" />\n        <Radio value=\"ru\" label=\"Ruscha\" description=\"Kirill yozuvida\" />\n      </RadioGroup>\n    </div>\n  );\n}\n" },
  "archive/v0.2/radio-group/states": { component: Demo388, file: "archive/v0.2/radio-group/states.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupStates() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-10\">\n      <RadioGroup aria-label=\"Butun guruh o'chirilgan\" disabled defaultValue=\"a\">\n        <Radio value=\"a\" label=\"Tanlangan\" />\n        <Radio value=\"b\" label=\"Tanlanmagan\" />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Bitta variant o'chirilgan\">\n        <Radio value=\"a\" label=\"Omborda bor\" />\n        <Radio value=\"b\" label=\"Tugagan\" disabled />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Xato holati\" invalid>\n        <Radio value=\"yes\" label=\"Ha\" />\n        <Radio value=\"no\" label=\"Yo'q\" />\n      </RadioGroup>\n    </div>\n  );\n}\n" },
  "archive/v0.2/radio-group/with-field": { component: Demo389, file: "archive/v0.2/radio-group/with-field.tsx", source: "'use client';\n\nimport { Field, Radio, RadioGroup } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RadioGroupWithField() {\n  const [value, setValue] = useState<string>();\n\n  return (\n    <Field label=\"Yetkazib berish\" required error={value ? undefined : 'Usulni tanlang'}>\n      <RadioGroup value={value} onValueChange={setValue}>\n        <Radio value=\"courier\" label=\"Kuryer\" description=\"Ertaga, 25 000 so'm\" />\n        <Radio value=\"pickup\" label=\"Olib ketish\" description=\"Bugun, bepul\" />\n      </RadioGroup>\n    </Field>\n  );\n}\n" },
  "archive/v0.2/segmented-control/basic": { component: Demo390, file: "archive/v0.2/segmented-control/basic.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\n\nexport default function SegmentedControlBasic() {\n  return (\n    <SegmentedControl defaultValue=\"month\" aria-label=\"Davr\">\n      <SegmentedControl.Item value=\"day\">Kun</SegmentedControl.Item>\n      <SegmentedControl.Item value=\"week\">Hafta</SegmentedControl.Item>\n      <SegmentedControl.Item value=\"month\">Oy</SegmentedControl.Item>\n      <SegmentedControl.Item value=\"year\">Yil</SegmentedControl.Item>\n    </SegmentedControl>\n  );\n}\n" },
  "archive/v0.2/segmented-control/controlled": { component: Demo391, file: "archive/v0.2/segmented-control/controlled.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst totals: Record<string, string> = {\n  day: \"1 250 000 so'm\",\n  week: \"8 740 000 so'm\",\n  month: \"36 900 000 so'm\",\n};\n\nexport default function SegmentedControlControlled() {\n  const [period, setPeriod] = useState('week');\n\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <SegmentedControl value={period} onValueChange={setPeriod} aria-label=\"Davr\">\n        <SegmentedControl.Item value=\"day\">Kun</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"week\">Hafta</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"month\">Oy</SegmentedControl.Item>\n      </SegmentedControl>\n      <p className=\"m-0 text-sm text-text-muted\">\n        Savdo: <span className=\"font-semibold text-text\">{totals[period]}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/segmented-control/disabled": { component: Demo392, file: "archive/v0.2/segmented-control/disabled.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\n\nexport default function SegmentedControlDisabled() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      <SegmentedControl defaultValue=\"card\" aria-label=\"To'lov usuli\">\n        <SegmentedControl.Item value=\"cash\">Naqd</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"card\">Karta</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"credit\" disabled>\n          Nasiya\n        </SegmentedControl.Item>\n      </SegmentedControl>\n      <SegmentedControl defaultValue=\"uz\" disabled aria-label=\"Til\">\n        <SegmentedControl.Item value=\"uz\">O'zbekcha</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"ru\">Ruscha</SegmentedControl.Item>\n      </SegmentedControl>\n    </div>\n  );\n}\n" },
  "archive/v0.2/segmented-control/full-width": { component: Demo393, file: "archive/v0.2/segmented-control/full-width.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\n\nexport default function SegmentedControlFullWidth() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <SegmentedControl fullWidth defaultValue=\"delivery\" aria-label=\"Olib ketish usuli\">\n        <SegmentedControl.Item value=\"delivery\">Yetkazib berish</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"pickup\">Olib ketish</SegmentedControl.Item>\n      </SegmentedControl>\n    </div>\n  );\n}\n" },
  "archive/v0.2/segmented-control/icons": { component: Demo394, file: "archive/v0.2/segmented-control/icons.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\nimport { LayoutGrid, List, MapIcon } from 'lucide-react';\n\nexport default function SegmentedControlIcons() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <SegmentedControl defaultValue=\"grid\" aria-label=\"Ko'rinish\">\n        <SegmentedControl.Item value=\"grid\" icon={<LayoutGrid />} aria-label=\"Katakli\" />\n        <SegmentedControl.Item value=\"list\" icon={<List />} aria-label=\"Ro'yxat\" />\n        <SegmentedControl.Item value=\"map\" icon={<MapIcon />} aria-label=\"Xarita\" />\n      </SegmentedControl>\n      <SegmentedControl defaultValue=\"list\" aria-label=\"Ko'rinish\">\n        <SegmentedControl.Item value=\"grid\" icon={<LayoutGrid />}>\n          Katakli\n        </SegmentedControl.Item>\n        <SegmentedControl.Item value=\"list\" icon={<List />}>\n          Ro'yxat\n        </SegmentedControl.Item>\n      </SegmentedControl>\n    </div>\n  );\n}\n" },
  "archive/v0.2/segmented-control/sizes": { component: Demo395, file: "archive/v0.2/segmented-control/sizes.tsx", source: "'use client';\n\nimport { Button, SegmentedControl } from '@akhatmirzo/ui';\n\nconst sizes = ['sm', 'md', 'lg'] as const;\n\nexport default function SegmentedControlSizes() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      {sizes.map((size) => (\n        <div key={size} className=\"flex items-center gap-3\">\n          <SegmentedControl size={size} defaultValue=\"all\" aria-label={`Holat, ${size}`}>\n            <SegmentedControl.Item value=\"all\">Hammasi</SegmentedControl.Item>\n            <SegmentedControl.Item value=\"paid\">To'langan</SegmentedControl.Item>\n            <SegmentedControl.Item value=\"debt\">Qarz</SegmentedControl.Item>\n          </SegmentedControl>\n          <Button size={size} variant=\"outline\">\n            Eksport\n          </Button>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/select/basic": { component: Demo396, file: "archive/v0.2/select/basic.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SelectBasic() {\n  const [region, setRegion] = useState('');\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field label=\"Viloyat\" description=\"Buyurtma shu viloyatga yetkaziladi\">\n        <Select value={region} onValueChange={setRegion}>\n          <Select.Item value=\"tsh\">Toshkent shahri</Select.Item>\n          <Select.Item value=\"sam\">Samarqand</Select.Item>\n          <Select.Item value=\"bux\">Buxoro</Select.Item>\n          <Select.Item value=\"and\">Andijon</Select.Item>\n          <Select.Item value=\"fer\">Farg'ona</Select.Item>\n          <Select.Item value=\"nam\">Namangan</Select.Item>\n          <Select.Item value=\"qash\">Qashqadaryo</Select.Item>\n          <Select.Item value=\"xor\">Xorazm</Select.Item>\n          <Select.Item value=\"qqr\">Qoraqalpog'iston</Select.Item>\n        </Select>\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Qiymat: <span className=\"font-medium text-text\">{region || '—'}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/select/form": { component: Demo397, file: "archive/v0.2/select/form.tsx", source: "'use client';\n\nimport { Button, Field, Select } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function SelectForm() {\n  const [error, setError] = useState<string>();\n  const [sent, setSent] = useState('—');\n\n  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    const delivery = String(new FormData(e.currentTarget).get('delivery') ?? '');\n    if (!delivery) return setError('Yetkazib berish usulini tanlang');\n    setError(undefined);\n    setSent(delivery);\n  };\n\n  return (\n    <form onSubmit={handleSubmit} className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Field label=\"Yetkazib berish\" error={error} required>\n        <Select name=\"delivery\" onValueChange={() => setError(undefined)}>\n          <Select.Item value=\"courier\">Kuryer (1 kun)</Select.Item>\n          <Select.Item value=\"pickup\">Olib ketish</Select.Item>\n          <Select.Item value=\"post\">Pochta (2–3 kun)</Select.Item>\n        </Select>\n      </Field>\n      <div className=\"flex items-center gap-3\">\n        <Button type=\"submit\" variant=\"primary\">\n          Yuborish\n        </Button>\n        <span className=\"text-sm text-text-muted\">FormData: {sent}</span>\n      </div>\n    </form>\n  );\n}\n" },
  "archive/v0.2/select/groups": { component: Demo398, file: "archive/v0.2/select/groups.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nexport default function SelectGroups() {\n  return (\n    <Field label=\"Filial\" className=\"w-full max-w-xs\">\n      <Select defaultValue=\"fer\">\n        <Select.Item value=\"tsh\">Toshkent</Select.Item>\n        <Select.Item value=\"sam\">Samarqand</Select.Item>\n        <Select.Group label=\"Vodiy\">\n          <Select.Item value=\"and\">Andijon</Select.Item>\n          <Select.Item value=\"fer\">Farg'ona</Select.Item>\n          <Select.Item value=\"nam\">Namangan</Select.Item>\n        </Select.Group>\n        <Select.Separator />\n        <Select.Group label=\"Janub\">\n          <Select.Item value=\"qash\">Qashqadaryo</Select.Item>\n          <Select.Item value=\"sur\">Surxondaryo</Select.Item>\n        </Select.Group>\n      </Select>\n    </Field>\n  );\n}\n" },
  "archive/v0.2/select/icons": { component: Demo399, file: "archive/v0.2/select/icons.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nfunction Dot({ className }: { className: string }) {\n  return <span className={`size-2 rounded-full ${className}`} />;\n}\n\nexport default function SelectIcons() {\n  return (\n    <Field label=\"Buyurtma holati\" className=\"w-full max-w-xs\">\n      <Select defaultValue=\"progress\">\n        <Select.Item value=\"new\" icon={<Dot className=\"bg-info\" />}>\n          Yangi\n        </Select.Item>\n        <Select.Item value=\"progress\" icon={<Dot className=\"bg-warning\" />}>\n          Jarayonda\n        </Select.Item>\n        <Select.Item value=\"done\" icon={<Dot className=\"bg-success\" />}>\n          Yetkazildi\n        </Select.Item>\n        <Select.Item value=\"canceled\" icon={<Dot className=\"bg-danger\" />}>\n          Bekor qilindi\n        </Select.Item>\n      </Select>\n    </Field>\n  );\n}\n" },
  "archive/v0.2/select/sizes": { component: Demo400, file: "archive/v0.2/select/sizes.tsx", source: "'use client';\n\nimport { Button, Select } from '@akhatmirzo/ui';\n\nexport default function SelectSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      {(['sm', 'md', 'lg'] as const).map((size) => (\n        <Select\n          key={size}\n          size={size}\n          aria-label={`O'lcham ${size}`}\n          placeholder={`size=\"${size}\"`}\n        >\n          <Select.Item value=\"a\">Birinchi</Select.Item>\n          <Select.Item value=\"b\">Ikkinchi</Select.Item>\n        </Select>\n      ))}\n      <div className=\"flex items-center gap-3\">\n        <Select aria-label=\"Valyuta\" defaultValue=\"uzs\" className=\"w-28\">\n          <Select.Item value=\"uzs\">UZS</Select.Item>\n          <Select.Item value=\"usd\">USD</Select.Item>\n          <Select.Item value=\"eur\">EUR</Select.Item>\n        </Select>\n        <Button variant=\"primary\">To'lash</Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/select/states": { component: Demo401, file: "archive/v0.2/select/states.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nexport default function SelectStates() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <Field label=\"O'chirilgan\" disabled>\n        <Select defaultValue=\"click\">\n          <Select.Item value=\"click\">Click</Select.Item>\n        </Select>\n      </Field>\n      <Field label=\"To'lov usuli\" error=\"To'lov usulini tanlang\" required>\n        <Select>\n          <Select.Item value=\"click\">Click</Select.Item>\n          <Select.Item value=\"payme\">Payme</Select.Item>\n        </Select>\n      </Field>\n      <Field label=\"O'chirilgan element\">\n        <Select placeholder=\"Usulni tanlang\">\n          <Select.Item value=\"click\">Click</Select.Item>\n          <Select.Item value=\"payme\">Payme</Select.Item>\n          <Select.Item value=\"uzum\" disabled>\n            Uzum (vaqtincha ishlamaydi)\n          </Select.Item>\n          <Select.Item value=\"cash\">Naqd pul</Select.Item>\n        </Select>\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/skeleton/loading-card": { component: Demo402, file: "archive/v0.2/skeleton/loading-card.tsx", source: "'use client';\n\nimport { Avatar, Button, Card, Skeleton } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SkeletonLoadingCard() {\n  const [loading, setLoading] = useState(true);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col items-start gap-3\">\n      <Button size=\"sm\" onClick={() => setLoading((l) => !l)}>\n        {loading ? \"Kontentni ko'rsatish\" : 'Yuklanish holati'}\n      </Button>\n      <Card variant=\"outline\" className=\"w-full\" aria-busy={loading}>\n        <div className=\"flex items-center gap-3\">\n          {loading ? (\n            <Skeleton variant=\"circle\" className=\"size-10\" />\n          ) : (\n            <Avatar name=\"Malika Rahimova\" />\n          )}\n          <div className=\"flex flex-1 flex-col gap-2\">\n            {loading ? (\n              <Skeleton className=\"h-4 w-2/5\" />\n            ) : (\n              <b className=\"text-sm\">Malika Rahimova</b>\n            )}\n            {loading ? (\n              <Skeleton className=\"h-3 w-1/4\" />\n            ) : (\n              <span className=\"text-xs text-text-muted\">2 soat oldin</span>\n            )}\n          </div>\n        </div>\n        {loading ? (\n          <Skeleton.Text lines={3} />\n        ) : (\n          <p className=\"text-sm\">\n            Buyurtma vaqtida yetib keldi, kuryer juda xushmuomala edi. Keyingi safar ham shu\n            do'kondan olaman.\n          </p>\n        )}\n      </Card>\n    </div>\n  );\n}\n" },
  "archive/v0.2/skeleton/shapes": { component: Demo403, file: "archive/v0.2/skeleton/shapes.tsx", source: "'use client';\n\nimport { Skeleton } from '@akhatmirzo/ui';\n\nexport default function SkeletonShapes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Skeleton variant=\"circle\" className=\"size-12\" />\n      <Skeleton className=\"h-4 w-32\" />\n      <Skeleton className=\"h-10 w-28 rounded-lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/skeleton/text": { component: Demo404, file: "archive/v0.2/skeleton/text.tsx", source: "'use client';\n\nimport { Skeleton } from '@akhatmirzo/ui';\n\nexport default function SkeletonTextDemo() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-6 sm:grid-cols-2\">\n      <Skeleton.Text lines={1} />\n      <Skeleton.Text lines={4} />\n    </div>\n  );\n}\n" },
  "archive/v0.2/slider/basic": { component: Demo405, file: "archive/v0.2/slider/basic.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderBasic() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Slider defaultValue={[40]} aria-label=\"Yorqinlik\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/slider/marks": { component: Demo406, file: "archive/v0.2/slider/marks.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nconst marks = [\n  { value: 0, label: '0%' },\n  { value: 25, label: '25%' },\n  { value: 50, label: '50%' },\n  { value: 75, label: '75%' },\n  { value: 100, label: '100%' },\n];\n\nexport default function SliderMarks() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Slider\n        defaultValue={[25]}\n        step={25}\n        marks={marks}\n        formatValue={(v) => `${v}%`}\n        aria-label=\"Chegirma\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/slider/range": { component: Demo407, file: "archive/v0.2/slider/range.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { Slider } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SliderRange() {\n  const [price, setPrice] = useState([1_000_000, 3_500_000]);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Slider\n        value={price}\n        onValueChange={setPrice}\n        min={0}\n        max={5_000_000}\n        step={50_000}\n        minStepsBetweenThumbs={2}\n        formatValue={(v) => formatMoney(v)}\n        aria-label=\"Narx\"\n      />\n      <p className=\"m-0 text-sm text-text-muted\">\n        Narx:{' '}\n        <span className=\"font-semibold text-text tabular-nums\">\n          {formatMoney(price[0]!)} — {formatMoney(price[1]!)}\n        </span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/slider/show-value": { component: Demo408, file: "archive/v0.2/slider/show-value.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderShowValue() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-10 pt-8\">\n      <Slider defaultValue={[30]} showValue=\"active\" aria-label=\"Faol paytda\" />\n      <Slider defaultValue={[60]} showValue=\"always\" aria-label=\"Doim\" />\n      <Slider defaultValue={[80]} showValue=\"never\" aria-label=\"Hech qachon\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/slider/sizes": { component: Demo409, file: "archive/v0.2/slider/sizes.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderSizes() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-8\">\n      <Slider size=\"sm\" defaultValue={[35]} aria-label=\"Kichik\" />\n      <Slider size=\"md\" defaultValue={[65]} aria-label=\"O'rta\" />\n      <Slider defaultValue={[50]} disabled aria-label=\"O'chirilgan\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/slider/vertical": { component: Demo410, file: "archive/v0.2/slider/vertical.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderVertical() {\n  return (\n    <div className=\"flex h-48 items-stretch gap-10 pl-12\">\n      <Slider orientation=\"vertical\" defaultValue={[70]} aria-label=\"Ovoz\" />\n      <Slider orientation=\"vertical\" defaultValue={[20, 60]} aria-label=\"Harorat\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/slider/with-field": { component: Demo411, file: "archive/v0.2/slider/with-field.tsx", source: "'use client';\n\nimport { Field, Slider } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SliderWithField() {\n  const [km, setKm] = useState([45]);\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field\n        label=\"Yetkazib berish radiusi\"\n        description=\"Do'kondan necha km uzoqlikkacha yetkazasiz\"\n        error={km[0]! > 40 ? \"40 km dan uzoqqa kuryer yo'q\" : undefined}\n      >\n        <Slider value={km} onValueChange={setKm} max={60} formatValue={(v) => `${v} km`} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/spinner/colors": { component: Demo412, file: "archive/v0.2/spinner/colors.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerColors() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Spinner className=\"text-text\" />\n      <Spinner className=\"text-primary\" />\n      <Spinner className=\"text-success\" />\n      <Spinner className=\"text-danger\" />\n      <span className=\"inline-flex size-10 items-center justify-center rounded-lg bg-primary text-primary-foreground\">\n        <Spinner size=\"sm\" />\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.2/spinner/sizes": { component: Demo413, file: "archive/v0.2/spinner/sizes.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4 text-text-muted\">\n      <Spinner size=\"sm\" />\n      <Spinner size=\"md\" />\n      <Spinner size=\"lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/spinner/with-text": { component: Demo414, file: "archive/v0.2/spinner/with-text.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerWithText() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <span className=\"inline-flex items-center gap-2 text-sm text-text-muted\">\n        <Spinner size=\"sm\" aria-hidden=\"true\" />\n        Buyurtmalar yuklanmoqda...\n      </span>\n      <div className=\"flex h-32 items-center justify-center rounded-lg border border-border bg-surface text-text-muted\">\n        <Spinner size=\"lg\" label=\"Jadval yuklanmoqda\" />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/stepper/basic": { component: Demo415, file: "archive/v0.2/stepper/basic.tsx", source: "'use client';\n\nimport { Button, Stepper } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst steps = [\n  { title: 'Savat' },\n  { title: 'Yetkazib berish', description: 'Manzil va vaqt' },\n  { title: \"To'lov\" },\n  { title: 'Tasdiqlash', optional: true },\n];\n\nexport default function StepperBasic() {\n  const [step, setStep] = useState(1);\n\n  return (\n    <div className=\"flex w-full flex-col gap-6\">\n      <Stepper steps={steps} value={step} onValueChange={setStep} aria-label=\"Buyurtma\" />\n      <div className=\"flex gap-2\">\n        <Button size=\"sm\" disabled={step === 0} onClick={() => setStep(step - 1)}>\n          Orqaga\n        </Button>\n        <Button\n          size=\"sm\"\n          variant=\"primary\"\n          disabled={step === steps.length}\n          onClick={() => setStep(step + 1)}\n        >\n          Davom etish\n        </Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/stepper/compact": { component: Demo416, file: "archive/v0.2/stepper/compact.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\n\nconst steps = [\n  { title: 'Savat' },\n  { title: 'Yetkazib berish' },\n  { title: \"To'lov\" },\n  { title: 'Tasdiqlash' },\n];\n\nexport default function StepperCompact() {\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Stepper steps={steps} value={1} compact />\n    </div>\n  );\n}\n" },
  "archive/v0.2/stepper/sizes": { component: Demo417, file: "archive/v0.2/stepper/sizes.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\n\nconst steps = [{ title: 'Savat' }, { title: 'Yetkazib berish' }, { title: \"To'lov\" }];\n\nexport default function StepperSizes() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      <Stepper steps={steps} defaultValue={1} size=\"sm\" aria-label=\"Kichik\" />\n      <Stepper steps={steps} defaultValue={1} aria-label=\"O'rtacha\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/stepper/states": { component: Demo418, file: "archive/v0.2/stepper/states.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\n\nexport default function StepperStates() {\n  return (\n    <Stepper\n      aria-label=\"Ariza\"\n      value={2}\n      className=\"w-full\"\n      steps={[\n        { title: \"Ma'lumotlar\" },\n        { title: 'Hujjatlar', status: 'error', description: \"Pasport rasmi o'qilmadi\" },\n        { title: 'Tekshiruv' },\n        { title: 'Shartnoma' },\n      ]}\n    />\n  );\n}\n" },
  "archive/v0.2/stepper/vertical": { component: Demo419, file: "archive/v0.2/stepper/vertical.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function StepperVertical() {\n  const [step, setStep] = useState(1);\n\n  return (\n    <Stepper\n      orientation=\"vertical\"\n      aria-label=\"Do'konni sozlash\"\n      value={step}\n      onValueChange={setStep}\n      allowFutureSteps\n      steps={[\n        { title: \"Do'kon nomi\", description: \"Mijozlar ko'radigan nom\" },\n        { title: \"To'lov usullari\", description: 'Click, Payme, naqd' },\n        { title: 'Yetkazib berish', description: 'Hududlar va narxlar' },\n        { title: 'Ishga tushirish' },\n      ]}\n    />\n  );\n}\n" },
  "archive/v0.2/switch/basic": { component: Demo420, file: "archive/v0.2/switch/basic.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchBasic() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <Switch label=\"Bildirishnomalar\" defaultChecked />\n      <Switch label=\"Avtomatik saqlash\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/switch/controlled": { component: Demo421, file: "archive/v0.2/switch/controlled.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SwitchControlled() {\n  const [open, setOpen] = useState(true);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Switch label=\"Do'kon ochiq\" checked={open} onCheckedChange={setOpen} />\n      <span className=\"text-sm text-text-muted\">\n        {open ? 'Buyurtmalar qabul qilinmoqda' : \"Buyurtmalar to'xtatilgan\"}\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.2/switch/description": { component: Demo422, file: "archive/v0.2/switch/description.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchDescription() {\n  return (\n    <div className=\"flex max-w-sm flex-col gap-4\">\n      <Switch label=\"Qorong'i mavzu\" description=\"Tizim sozlamasidan qat'i nazar\" defaultChecked />\n      <Switch size=\"sm\" label=\"Ovozli signal\" description=\"Yangi buyurtma kelganda\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/switch/sizes": { component: Demo423, file: "archive/v0.2/switch/sizes.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-8\">\n      <Switch size=\"sm\" label=\"Kichik · 32×18\" defaultChecked />\n      <Switch size=\"md\" label=\"O'rta · 40×24\" defaultChecked />\n    </div>\n  );\n}\n" },
  "archive/v0.2/switch/states": { component: Demo424, file: "archive/v0.2/switch/states.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchStates() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <Switch label=\"O'chirilgan\" disabled />\n      <Switch label=\"O'chirilgan, yoqilgan\" disabled defaultChecked />\n      <Switch label=\"Xato\" invalid />\n    </div>\n  );\n}\n" },
  "archive/v0.2/switch/with-field": { component: Demo425, file: "archive/v0.2/switch/with-field.tsx", source: "'use client';\n\nimport { Field, Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchWithField() {\n  return (\n    <div className=\"max-w-sm\">\n      <Field label=\"Ikki bosqichli tasdiqlash\" description=\"Har kirishda SMS kod so'raladi\">\n        <Switch />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/tabs/badges": { component: Demo426, file: "archive/v0.2/tabs/badges.tsx", source: "'use client';\n\nimport { Badge, Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsBadges() {\n  return (\n    <Tabs defaultValue=\"new\">\n      <Tabs.List aria-label=\"Buyurtmalar holati\">\n        <Tabs.Trigger value=\"new\" badge={4}>\n          Yangi\n        </Tabs.Trigger>\n        <Tabs.Trigger\n          value=\"paid\"\n          badge={\n            <Badge color=\"success\" size=\"sm\">\n              +2\n            </Badge>\n          }\n        >\n          To'langan\n        </Tabs.Trigger>\n        <Tabs.Trigger value=\"canceled\" disabled>\n          Bekor qilingan\n        </Tabs.Trigger>\n      </Tabs.List>\n    </Tabs>\n  );\n}\n" },
  "archive/v0.2/tabs/controlled": { component: Demo427, file: "archive/v0.2/tabs/controlled.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst totals: Record<string, string> = {\n  day: \"1 250 000 so'm\",\n  week: \"8 740 000 so'm\",\n  month: \"36 900 000 so'm\",\n  year: \"412 500 000 so'm\",\n};\n\nexport default function TabsControlled() {\n  const [period, setPeriod] = useState('week');\n\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <Tabs value={period} onValueChange={setPeriod} variant=\"segmented\">\n        <Tabs.List aria-label=\"Davr\">\n          <Tabs.Trigger value=\"day\">Kun</Tabs.Trigger>\n          <Tabs.Trigger value=\"week\">Hafta</Tabs.Trigger>\n          <Tabs.Trigger value=\"month\">Oy</Tabs.Trigger>\n          <Tabs.Trigger value=\"year\">Yil</Tabs.Trigger>\n        </Tabs.List>\n      </Tabs>\n      <p className=\"m-0 text-sm text-text-muted\">\n        Savdo: <span className=\"font-semibold text-text\">{totals[period]}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/tabs/scrollable": { component: Demo428, file: "archive/v0.2/tabs/scrollable.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nconst months = [\n  'Yanvar',\n  'Fevral',\n  'Mart',\n  'Aprel',\n  'May',\n  'Iyun',\n  'Iyul',\n  'Avgust',\n  'Sentabr',\n  'Oktabr',\n  'Noyabr',\n  'Dekabr',\n];\n\nexport default function TabsScrollable() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Tabs defaultValue=\"Mart\">\n        <Tabs.List aria-label=\"Oylar\">\n          {months.map((m) => (\n            <Tabs.Trigger key={m} value={m}>\n              {m}\n            </Tabs.Trigger>\n          ))}\n        </Tabs.List>\n        {months.map((m) => (\n          <Tabs.Content key={m} value={m} className=\"text-text-muted\">\n            {m} oyi bo'yicha savdo hisoboti.\n          </Tabs.Content>\n        ))}\n      </Tabs>\n    </div>\n  );\n}\n" },
  "archive/v0.2/tabs/sizes": { component: Demo429, file: "archive/v0.2/tabs/sizes.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsSizes() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      {(['underline', 'pills', 'segmented'] as const).map((variant) => (\n        <Tabs key={variant} defaultValue=\"all\" variant={variant} size=\"sm\">\n          <Tabs.List aria-label=\"Holat bo'yicha\">\n            <Tabs.Trigger value=\"all\">Hammasi</Tabs.Trigger>\n            <Tabs.Trigger value=\"active\">Faol</Tabs.Trigger>\n            <Tabs.Trigger value=\"archive\">Arxiv</Tabs.Trigger>\n          </Tabs.List>\n        </Tabs>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/tabs/variants": { component: Demo430, file: "archive/v0.2/tabs/variants.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsVariants() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      {(['underline', 'pills', 'segmented'] as const).map((variant) => (\n        <Tabs key={variant} defaultValue=\"info\" variant={variant}>\n          <Tabs.List aria-label={`Mijoz (${variant})`}>\n            <Tabs.Trigger value=\"info\">Ma'lumot</Tabs.Trigger>\n            <Tabs.Trigger value=\"orders\" badge={12}>\n              Buyurtmalar\n            </Tabs.Trigger>\n            <Tabs.Trigger value=\"reviews\">Sharhlar</Tabs.Trigger>\n          </Tabs.List>\n          <Tabs.Content value=\"info\" className=\"text-text-muted\">\n            Ism, telefon va yetkazib berish manzili.\n          </Tabs.Content>\n          <Tabs.Content value=\"orders\" className=\"text-text-muted\">\n            Oxirgi 12 ta buyurtma ro'yxati.\n          </Tabs.Content>\n          <Tabs.Content value=\"reviews\" className=\"text-text-muted\">\n            Mijoz hali sharh qoldirmagan.\n          </Tabs.Content>\n        </Tabs>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/tabs/vertical": { component: Demo431, file: "archive/v0.2/tabs/vertical.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsVertical() {\n  return (\n    <Tabs defaultValue=\"profile\" orientation=\"vertical\" variant=\"pills\" className=\"w-full\">\n      <Tabs.List aria-label=\"Sozlamalar\" className=\"w-44\">\n        <Tabs.Trigger value=\"profile\">Profil</Tabs.Trigger>\n        <Tabs.Trigger value=\"security\">Xavfsizlik</Tabs.Trigger>\n        <Tabs.Trigger value=\"notifications\" badge={3}>\n          Bildirishnomalar\n        </Tabs.Trigger>\n        <Tabs.Trigger value=\"billing\" disabled>\n          To'lovlar\n        </Tabs.Trigger>\n      </Tabs.List>\n      <Tabs.Content value=\"profile\" className=\"text-text-muted\">\n        Ism, familiya va profil rasmi.\n      </Tabs.Content>\n      <Tabs.Content value=\"security\" className=\"text-text-muted\">\n        Parol va ikki bosqichli tasdiqlash.\n      </Tabs.Content>\n      <Tabs.Content value=\"notifications\" className=\"text-text-muted\">\n        SMS, email va Telegram orqali bildirishnomalar.\n      </Tabs.Content>\n    </Tabs>\n  );\n}\n" },
  "archive/v0.2/textarea/auto-resize": { component: Demo432, file: "archive/v0.2/textarea/auto-resize.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaAutoResize() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea\n        autoResize\n        minRows={2}\n        maxRows={6}\n        placeholder=\"Yozib ko'ring — maydon matn bilan birga o'sadi\"\n        aria-label=\"Xabar\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/textarea/basic": { component: Demo433, file: "archive/v0.2/textarea/basic.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaBasic() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea placeholder=\"Buyurtma haqida izoh qoldiring\" aria-label=\"Izoh\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/textarea/count": { component: Demo434, file: "archive/v0.2/textarea/count.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function TextareaCount() {\n  const [bio, setBio] = useState(\n    'Frontend dasturchi, Toshkent. React va TypeScript bilan ishlayman.',\n  );\n\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea\n        showCount\n        maxLength={120}\n        value={bio}\n        onChange={(e) => setBio(e.target.value)}\n        aria-label=\"O'zingiz haqingizda\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/textarea/states": { component: Demo435, file: "archive/v0.2/textarea/states.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaStates() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-3 sm:grid-cols-2\">\n      <Textarea minRows={2} invalid defaultValue=\"Juda qisqa\" aria-label=\"Xato\" />\n      <Textarea minRows={2} disabled defaultValue=\"O'chirilgan\" aria-label=\"O'chirilgan\" />\n      <Textarea minRows={2} readOnly defaultValue=\"Faqat o'qish uchun\" aria-label=\"Faqat o'qish\" />\n      <Textarea minRows={2} size=\"sm\" placeholder=\"Kichik o'lcham\" aria-label=\"Kichik\" />\n    </div>\n  );\n}\n" },
  "archive/v0.2/textarea/with-field": { component: Demo436, file: "archive/v0.2/textarea/with-field.tsx", source: "'use client';\n\nimport { Field, Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaWithField() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Field label=\"Izoh\" required description=\"Kuryer uchun qo'shimcha ma'lumot\">\n        <Textarea\n          autoResize\n          showCount\n          maxLength={300}\n          placeholder=\"Masalan: 3-podyezd, domofon ishlamaydi\"\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.2/theming/brand": { component: Demo437, file: "archive/v0.2/theming/brand.tsx", source: "'use client';\n\nimport { Badge, Button, Field, Input, Switch } from '@akhatmirzo/ui';\nimport { useState, type CSSProperties } from 'react';\n\nconst BRANDS = ['indigo', 'emerald', 'sky', 'rose'] as const;\n\n// Brend rangini faqat shu blok ichida almashtiramiz. color-mix — light va dark'da birdek ishlaydi.\nconst brandVars = (c: string) =>\n  ({\n    '--ak-primary': `var(--ak-${c}-600)`,\n    '--ak-primary-hover': `var(--ak-${c}-700)`,\n    '--ak-primary-soft': `color-mix(in srgb, var(--ak-${c}-500) 14%, var(--ak-surface))`,\n    '--ak-primary-soft-hover': `color-mix(in srgb, var(--ak-${c}-500) 22%, var(--ak-surface))`,\n    '--ak-primary-soft-foreground': `color-mix(in srgb, var(--ak-${c}-600) 65%, var(--ak-text))`,\n    '--ak-ring': `color-mix(in srgb, var(--ak-${c}-500) 45%, transparent)`,\n  }) as CSSProperties;\n\nexport default function ThemingBrand() {\n  const [brand, setBrand] = useState<(typeof BRANDS)[number]>('emerald');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <div className=\"flex flex-wrap gap-2\">\n        {BRANDS.map((b) => (\n          <Button\n            key={b}\n            size=\"sm\"\n            variant={b === brand ? 'outline' : 'ghost'}\n            onClick={() => setBrand(b)}\n          >\n            {b}\n          </Button>\n        ))}\n      </div>\n      <div\n        style={brandVars(brand)}\n        className=\"flex flex-col gap-4 rounded-xl border border-border bg-surface p-5\"\n      >\n        <Field label=\"Telefon\">\n          <Input placeholder=\"+998 90 123 45 67\" />\n        </Field>\n        <Switch defaultChecked label=\"Yangiliklarga obuna\" />\n        <div className=\"flex flex-wrap items-center gap-2\">\n          <Button variant=\"primary\">Saqlash</Button>\n          <Button>Bekor qilish</Button>\n          <Badge color=\"primary\">Yangi</Badge>\n        </div>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/theming/motion": { component: Demo438, file: "archive/v0.2/theming/motion.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst EASINGS = [\n  ['ease-out', 'Kirishlar (asosiy)'],\n  ['ease-in', 'Chiqishlar'],\n  ['ease-in-out', \"Joyida o'zgarish\"],\n  ['ease-spring', 'Toast, switch'],\n];\n\nexport default function ThemingMotion() {\n  const [on, setOn] = useState(false);\n\n  return (\n    <div className=\"flex w-full max-w-lg flex-col gap-4\">\n      <Button size=\"sm\" variant=\"primary\" className=\"self-start\" onClick={() => setOn((v) => !v)}>\n        {on ? 'Qaytarish' : 'Ishga tushirish'}\n      </Button>\n      {EASINGS.map(([easing, note]) => (\n        <div key={easing} className=\"flex items-center gap-3\">\n          <div className=\"flex w-28 shrink-0 flex-col text-xs\">\n            <code className=\"font-mono text-text\">{easing}</code>\n            <span className=\"text-text-muted\">{note}</span>\n          </div>\n          <div className=\"relative h-6 flex-1 rounded-full bg-surface-muted\">\n            {/* Qatlam kengligi = yo'lak − sharcha, shuning uchun translate-x-full oxirigacha olib boradi */}\n            <div\n              className={`absolute inset-y-0 left-0 w-[calc(100%-1.5rem)] transition-transform duration-slow ${easing} ${on ? 'translate-x-full' : ''}`}\n            >\n              <div className=\"size-6 rounded-full bg-primary\" />\n            </div>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/theming/palette": { component: Demo439, file: "archive/v0.2/theming/palette.tsx", source: "'use client';\n\nimport { useSyncExternalStore } from 'react';\n\nconst SCALES = {\n  indigo: ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900', '950'],\n  slate: ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900', '950'],\n  emerald: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  amber: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  rose: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  sky: ['50', '100', '300', '400', '500', '600', '700', '950'],\n};\n\nconst subscribe = () => () => {};\n// CSS o'zgaruvchilarning haqiqiy qiymatlari (serverda — bo'sh)\nconst readValues = () => {\n  const style = getComputedStyle(document.documentElement);\n  return Object.entries(SCALES)\n    .flatMap(([name, steps]) =>\n      steps.map((s) => style.getPropertyValue(`--ak-${name}-${s}`).trim()),\n    )\n    .join(',');\n};\n\nexport default function ThemingPalette() {\n  const values = useSyncExternalStore(subscribe, readValues, () => '').split(',');\n  let index = 0;\n\n  return (\n    <div className=\"flex w-full flex-col gap-5\">\n      {Object.entries(SCALES).map(([name, steps]) => (\n        <div key={name} className=\"flex flex-col gap-2\">\n          <span className=\"text-sm font-semibold text-text\">{name}</span>\n          <div className=\"grid grid-cols-4 gap-2 sm:grid-cols-6 lg:grid-cols-11\">\n            {steps.map((step) => {\n              const value = values[index++];\n              return (\n                <div key={step} className=\"flex flex-col gap-1\">\n                  <div\n                    className=\"h-10 rounded-md border border-border\"\n                    style={{ background: `var(--ak-${name}-${step})` }}\n                  />\n                  <span className=\"text-xs font-medium text-text\">{step}</span>\n                  <span className=\"font-mono text-xs text-text-muted uppercase\">{value}</span>\n                </div>\n              );\n            })}\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/theming/radius-shadow": { component: Demo440, file: "archive/v0.2/theming/radius-shadow.tsx", source: "'use client';\n\nconst RADII = [\n  ['rounded-sm', '6px'],\n  ['rounded-md', '8px'],\n  ['rounded-lg', '12px'],\n  ['rounded-xl', '16px'],\n  ['rounded-2xl', '20px'],\n  ['rounded-full', '9999px'],\n];\n\nconst SHADOWS = [\n  ['shadow-xs', 'Input, tugma'],\n  ['shadow-sm', 'Karta'],\n  ['shadow-md', 'Dropdown'],\n  ['shadow-lg', 'Popover, toast'],\n  ['shadow-xl', 'Modal, drawer'],\n];\n\nexport default function ThemingRadiusShadow() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      <div className=\"grid grid-cols-3 gap-4 sm:grid-cols-6\">\n        {RADII.map(([className, value]) => (\n          <div key={className} className=\"flex flex-col items-center gap-2 text-xs\">\n            <div className={`size-14 border-2 border-primary bg-primary-soft ${className}`} />\n            <code className=\"font-mono text-text\">{className}</code>\n            <span className=\"text-text-muted\">{value}</span>\n          </div>\n        ))}\n      </div>\n      <div className=\"grid grid-cols-2 gap-5 sm:grid-cols-5\">\n        {SHADOWS.map(([className, note]) => (\n          <div\n            key={className}\n            className={`flex h-20 flex-col items-center justify-center rounded-xl bg-surface-raised text-xs ${className}`}\n          >\n            <code className=\"font-mono text-text\">{className}</code>\n            <span className=\"text-text-muted\">{note}</span>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.2/theming/scoped": { component: Demo441, file: "archive/v0.2/theming/scoped.tsx", source: "'use client';\n\nimport { Badge, Button, Field, Input } from '@akhatmirzo/ui';\n\n// data-theme istalgan elementga qo'yiladi — tokenlar faqat shu blok ichida almashadi\nexport default function ThemingScoped() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-2\">\n      {(['light', 'dark'] as const).map((theme) => (\n        <div\n          key={theme}\n          data-theme={theme}\n          className=\"flex flex-col gap-4 rounded-xl border border-border bg-background p-5 text-text\"\n        >\n          <div className=\"flex items-center justify-between\">\n            <span className=\"text-sm font-semibold\">data-theme=\"{theme}\"</span>\n            <Badge color=\"success\" dot>\n              Faol\n            </Badge>\n          </div>\n          <Field label=\"Ism\">\n            <Input placeholder=\"Sarvar\" />\n          </Field>\n          <div className=\"flex gap-2\">\n            <Button variant=\"primary\">Saqlash</Button>\n            <Button variant=\"outline\">Bekor qilish</Button>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/theming/semantic": { component: Demo442, file: "archive/v0.2/theming/semantic.tsx", source: "'use client';\n\nimport { useSyncExternalStore } from 'react';\n\nconst TOKENS = [\n  ['background', 'Sahifa foni'],\n  ['surface', 'Karta, input, modal'],\n  ['surface-muted', 'Hover, ikkilamchi fon'],\n  ['surface-raised', 'Popover, toast'],\n  ['border', 'Oddiy chegara'],\n  ['border-strong', 'Hover chegara'],\n  ['text', 'Asosiy matn'],\n  ['text-subtle', 'Ghost tugma, ikonka'],\n  ['text-muted', 'Yordamchi matn'],\n  ['text-faint', 'Placeholder'],\n  ['primary', 'Asosiy tugma'],\n  ['primary-soft', 'Soft tugma, badge'],\n  ['primary-soft-foreground', 'Soft ustidagi matn'],\n  ['link', 'Havola'],\n  ['danger', 'Xavfli tugma'],\n  ['ring', 'Fokus halqasi'],\n] as const;\n\n// Mavzu almashganda (<html data-theme>) qiymatlar qayta o'qiladi\nconst subscribe = (onChange: () => void) => {\n  const observer = new MutationObserver(onChange);\n  observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });\n  return () => observer.disconnect();\n};\nconst readValues = () => {\n  const style = getComputedStyle(document.documentElement);\n  return TOKENS.map(([token]) => style.getPropertyValue(`--ak-${token}`).trim()).join('|');\n};\n\nexport default function ThemingSemantic() {\n  const values = useSyncExternalStore(subscribe, readValues, () => '').split('|');\n\n  return (\n    <div className=\"grid w-full gap-3 sm:grid-cols-2\">\n      {TOKENS.map(([token, note], i) => (\n        <div key={token} className=\"flex items-center gap-3\">\n          <div\n            className=\"size-10 shrink-0 rounded-lg border border-border\"\n            style={{ background: `var(--ak-${token})` }}\n          />\n          <div className=\"flex min-w-0 flex-col text-xs\">\n            <span className=\"truncate font-mono font-medium text-text\">{token}</span>\n            <span className=\"truncate text-text-muted\">{note}</span>\n            <span className=\"truncate font-mono text-text-faint\">{values[i] || '—'}</span>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/theming/status": { component: Demo443, file: "archive/v0.2/theming/status.tsx", source: "'use client';\n\nconst STATUSES = ['success', 'warning', 'danger', 'info'] as const;\n\nconst SOFT = {\n  success: 'bg-success-soft text-success-soft-foreground',\n  warning: 'bg-warning-soft text-warning-soft-foreground',\n  danger: 'bg-danger-soft text-danger-soft-foreground',\n  info: 'bg-info-soft text-info-soft-foreground',\n};\nconst SOLID = {\n  success: 'bg-success text-success-foreground',\n  warning: 'bg-warning text-warning-foreground',\n  danger: 'bg-danger text-danger-foreground',\n  info: 'bg-info text-info-foreground',\n};\n\nexport default function ThemingStatus() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      {[SOFT, SOLID].map((styles, row) => (\n        <div key={row} className=\"flex flex-wrap items-center gap-2\">\n          <code className=\"w-12 font-mono text-xs text-text-muted\">\n            {row === 0 ? 'soft' : 'solid'}\n          </code>\n          {STATUSES.map((status) => (\n            <span\n              key={status}\n              className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${styles[status]}`}\n            >\n              {status}\n            </span>\n          ))}\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/theming/typography": { component: Demo444, file: "archive/v0.2/theming/typography.tsx", source: "'use client';\n\nconst SCALE = [\n  { className: 'text-4xl font-bold', name: 'text-4xl', spec: '36 / 40' },\n  { className: 'text-3xl font-bold', name: 'text-3xl', spec: '30 / 36' },\n  { className: 'text-2xl font-semibold', name: 'text-2xl', spec: '24 / 32' },\n  { className: 'text-xl font-semibold', name: 'text-xl', spec: '20 / 28' },\n  { className: 'text-lg font-medium', name: 'text-lg', spec: '18 / 28' },\n  { className: 'text-base', name: 'text-base', spec: '16 / 24' },\n  { className: 'text-sm', name: 'text-sm', spec: '14 / 20' },\n  { className: 'text-xs font-medium', name: 'text-xs', spec: '12 / 16' },\n];\n\nexport default function ThemingTypography() {\n  return (\n    <div className=\"flex w-full flex-col divide-y divide-border\">\n      {SCALE.map((item) => (\n        <div key={item.name} className=\"flex items-baseline gap-4 py-2\">\n          <div className=\"flex w-24 shrink-0 flex-col\">\n            <code className=\"font-mono text-xs text-text\">{item.name}</code>\n            <span className=\"text-xs text-text-muted\">{item.spec}</span>\n          </div>\n          <p className={`${item.className} truncate text-text`}>O'zbekiston — Ўзбекистон</p>\n        </div>\n      ))}\n      <p className=\"pt-3 font-mono text-sm text-text-muted\">font-mono: 1 250 000 so'm · +998 90</p>\n    </div>\n  );\n}\n" },
  "archive/v0.2/toast/action": { component: Demo445, file: "archive/v0.2/toast/action.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastAction() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.success('Buyurtma yaratildi', {\n            description: \"#1042 · 1 250 000 so'm\",\n            action: { label: \"Ko'rish\", onClick: () => toast.info('Buyurtma #1042 ochildi') },\n          })\n        }\n      >\n        Amal bilan\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast(\"Mahsulot o'chirildi\", {\n            description: 'iPhone 15 Pro, 256 GB',\n            action: {\n              label: 'Qaytarish',\n              onClick: () => toast.success('Mahsulot qaytarildi'),\n            },\n          })\n        }\n      >\n        Bekor qilish (undo)\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/toast/promise": { component: Demo446, file: "archive/v0.2/toast/promise.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nasync function saveOrder() {\n  await wait(1500);\n  return 1042;\n}\n\nasync function failingRequest(): Promise<void> {\n  await wait(1200);\n  throw new Error('Server javob bermadi');\n}\n\nexport default function ToastPromise() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.promise(saveOrder, {\n            loading: 'Saqlanmoqda...',\n            success: (id) => `Buyurtma #${id} saqlandi`,\n            error: 'Xatolik yuz berdi',\n          })\n        }\n      >\n        Muvaffaqiyatli\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast\n            .promise(failingRequest, {\n              loading: 'Yuborilmoqda...',\n              success: 'Yuborildi',\n              error: (e) => `Xatolik: ${(e as Error).message}`,\n            })\n            .catch(() => {})\n        }\n      >\n        Xato bilan\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/toast/stack": { component: Demo447, file: "archive/v0.2/toast/stack.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastStack() {\n  const burst = () => {\n    toast.info(\"Yangi mijoz ro'yxatdan o'tdi\");\n    toast.success(\"To'lov qabul qilindi\", { description: \"350 000 so'm\" });\n    toast.warning('Omborda 3 ta qoldi');\n    toast('Yangi sharh qoldirildi');\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button variant=\"outline\" onClick={burst}>\n        4 tasini birdan\n      </Button>\n      <Button variant=\"ghost\" onClick={() => toast.dismiss()}>\n        Hammasini yopish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/toast/types": { component: Demo448, file: "archive/v0.2/toast/types.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastTypes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button variant=\"outline\" onClick={() => toast('Havola nusxalandi')}>\n        Oddiy\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.success(\"O'zgarishlar saqlandi\")}>\n        success\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.error(\"Ulanib bo'lmadi\", {\n            description: \"Internetni tekshirib, qayta urinib ko'ring.\",\n          })\n        }\n      >\n        error\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.warning('Obuna 3 kundan keyin tugaydi', {\n            description: \"To'lovni oldindan qiling.\",\n          })\n        }\n      >\n        warning\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.info('Yangi versiya mavjud')}>\n        info\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.loading('Hisobot tayyorlanmoqda...')}>\n        loading\n      </Button>\n      <Button variant=\"ghost\" onClick={() => toast.dismiss()}>\n        Hammasini yopish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.2/toast/update": { component: Demo449, file: "archive/v0.2/toast/update.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function ToastUpdate() {\n  const upload = async () => {\n    const id = toast.loading('Fayl yuklanmoqda...', { description: 'hisobot.xlsx' });\n    await wait(1000);\n    toast.loading('Fayl tekshirilmoqda...', { id, description: 'hisobot.xlsx' });\n    await wait(1000);\n    toast.success('Fayl yuklandi', { id, description: 'hisobot.xlsx · 2,4 MB' });\n  };\n\n  return (\n    <Button variant=\"outline\" onClick={upload}>\n      Faylni yuklash\n    </Button>\n  );\n}\n" },
  "archive/v0.2/tooltip/basic": { component: Demo450, file: "archive/v0.2/tooltip/basic.tsx", source: "'use client';\n\nimport { IconButton, Tooltip } from '@akhatmirzo/ui';\nimport { Copy, Heart, Share2, Trash2 } from 'lucide-react';\n\nexport default function TooltipBasic() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Tooltip content=\"Nusxa olish\" shortcut={['mod', 'C']}>\n        <IconButton variant=\"outline\" aria-label=\"Nusxa olish\">\n          <Copy />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"Ulashish\">\n        <IconButton variant=\"outline\" aria-label=\"Ulashish\">\n          <Share2 />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"Sevimlilarga qo'shish\">\n        <IconButton variant=\"outline\" aria-label=\"Sevimlilarga qo'shish\">\n          <Heart />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"O'chirish\" shortcut={['Del']}>\n        <IconButton variant=\"ghost\" aria-label=\"O'chirish\">\n          <Trash2 />\n        </IconButton>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "archive/v0.2/tooltip/controlled": { component: Demo451, file: "archive/v0.2/tooltip/controlled.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function TooltipControlled() {\n  const [open, setOpen] = useState(false);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"outline\" onClick={() => setOpen((o) => !o)}>\n        {open ? 'Yashirish' : \"Ko'rsatish\"}\n      </Button>\n      <Tooltip content=\"Boshqariladigan tooltip\" open={open} onOpenChange={setOpen}>\n        <Button>Nishon</Button>\n      </Tooltip>\n      <Tooltip content=\"Bu matn chiqmaydi\" disabled>\n        <Button>disabled</Button>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "archive/v0.2/tooltip/delay": { component: Demo452, file: "archive/v0.2/tooltip/delay.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipDelay() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Tooltip content=\"Darhol chiqadi\" delay={0}>\n        <Button>delay=0</Button>\n      </Tooltip>\n      <Tooltip content=\"Bir soniya kutadi\" delay={1000}>\n        <Button>delay=1000</Button>\n      </Tooltip>\n      <Tooltip content=\"Uzun izoh 240px dan oshsa, keyingi qatorga o'raladi: buyurtma holati har 5 daqiqada yangilanadi.\">\n        <Button>Uzun matn</Button>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "archive/v0.2/tooltip/disabled-button": { component: Demo453, file: "archive/v0.2/tooltip/disabled-button.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipDisabledButton() {\n  return (\n    <Tooltip content=\"Ruxsat yo'q: faqat administrator saqlay oladi\">\n      <span tabIndex={0} className=\"focus-ring inline-flex rounded-lg\">\n        <Button variant=\"primary\" disabled>\n          Saqlash\n        </Button>\n      </span>\n    </Tooltip>\n  );\n}\n" },
  "archive/v0.2/tooltip/sides": { component: Demo454, file: "archive/v0.2/tooltip/sides.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipSides() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {(['top', 'right', 'bottom', 'left'] as const).map((side) => (\n        <Tooltip key={side} content={`Tomon: ${side}`} side={side}>\n          <Button variant=\"outline\">{side}</Button>\n        </Tooltip>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.2/virtual-list/basic": { component: Demo455, file: "archive/v0.2/virtual-list/basic.tsx", source: "'use client';\n\nimport { Badge, Button, Input, VirtualList, type VirtualListHandle } from '@akhatmirzo/ui';\nimport { useMemo, useRef, useState } from 'react';\n\nconst LEVELS = [\n  { label: 'Info', color: 'info', text: 'Foydalanuvchi tizimga kirdi' },\n  { label: 'Tayyor', color: 'success', text: \"To'lov qabul qilindi\" },\n  { label: 'Ogohlantirish', color: 'warning', text: 'Omborda mahsulot kam qoldi' },\n  { label: 'Xato', color: 'danger', text: \"SMS yuborib bo'lmadi\" },\n] as const;\n\nexport default function VirtualListBasic() {\n  const logs = useMemo(\n    () => Array.from({ length: 10_000 }, (_, i) => ({ id: i + 1, ...LEVELS[i % LEVELS.length]! })),\n    [],\n  );\n  const ref = useRef<VirtualListHandle>(null);\n  const [target, setTarget] = useState('5000');\n\n  const go = () => ref.current?.scrollToIndex(Number(target) - 1, { align: 'start' });\n\n  return (\n    <div className=\"flex w-full flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Input\n          aria-label=\"Qator raqami\"\n          inputMode=\"numeric\"\n          value={target}\n          onChange={(e) => setTarget(e.target.value.replace(/\\D/g, ''))}\n          onKeyDown={(e) => e.key === 'Enter' && go()}\n          className=\"w-28\"\n        />\n        <Button variant=\"soft\" onClick={go}>\n          Qatorga o'tish\n        </Button>\n      </div>\n      <VirtualList\n        ref={ref}\n        aria-label=\"Tizim jurnali\"\n        items={logs}\n        estimateSize={48}\n        height={400}\n        overscan={8}\n        getItemKey={(log) => log.id}\n        className=\"rounded-xl border border-border bg-surface\"\n        renderItem={(log) => (\n          <div className=\"flex h-12 items-center gap-3 border-b border-border px-4 text-sm\">\n            <span className=\"w-14 shrink-0 text-text-faint tabular-nums\">#{log.id}</span>\n            <Badge color={log.color}>{log.label}</Badge>\n            <span className=\"min-w-0 flex-1 truncate\">{log.text}</span>\n          </div>\n        )}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.2/virtual-list/dynamic": { component: Demo456, file: "archive/v0.2/virtual-list/dynamic.tsx", source: "'use client';\n\nimport { Avatar, VirtualList } from '@akhatmirzo/ui';\n\nconst NAMES = ['Aziza Karimova', 'Bobur Toshmatov', \"G'ayrat Usmonov\", 'Malika Yusupova'];\nconst TEXTS = [\n  'Assalomu alaykum!',\n  \"Buyurtmam qachon yetib keladi? Kecha to'lov qilgan edim.\",\n  \"Yetkazish manzilini o'zgartirsam bo'ladimi? Hozir Samarqanddaman, kuryer oldindan qo'ng'iroq qilsin.\",\n  'Ha, albatta.',\n  \"Rahmat, mahsulot juda yoqdi. Qadoqlash ham a'lo darajada edi, do'stlarimga ham tavsiya qilaman.\",\n];\n\nconst messages = Array.from({ length: 2000 }, (_, i) => ({\n  id: i,\n  author: NAMES[(i * 3) % NAMES.length]!,\n  text: TEXTS[(i * 2 + (i >> 2)) % TEXTS.length]!,\n}));\n\nexport default function VirtualListDynamic() {\n  return (\n    <VirtualList\n      dynamic\n      aria-label=\"Mijozlar bilan yozishmalar\"\n      items={messages}\n      estimateSize={72}\n      height={400}\n      getItemKey={(m) => m.id}\n      className=\"w-full rounded-xl border border-border bg-surface\"\n      renderItem={(m) => (\n        <div className=\"flex gap-3 border-b border-border px-4 py-3\">\n          <Avatar name={m.author} size=\"sm\" />\n          <div className=\"flex min-w-0 flex-col gap-0.5\">\n            <span className=\"text-sm font-medium\">{m.author}</span>\n            <p className=\"m-0 text-sm text-text-muted\">{m.text}</p>\n          </div>\n        </div>\n      )}\n    />\n  );\n}\n" },
  "archive/v0.2/virtual-list/empty": { component: Demo457, file: "archive/v0.2/virtual-list/empty.tsx", source: "'use client';\n\nimport { VirtualList } from '@akhatmirzo/ui';\n\nexport default function VirtualListEmpty() {\n  return (\n    <VirtualList\n      aria-label=\"Bildirishnomalar\"\n      items={[]}\n      estimateSize={48}\n      height={160}\n      renderItem={() => null}\n      emptyState=\"Hali bildirishnomalar yo'q\"\n      className=\"w-full max-w-md rounded-xl border border-border bg-surface\"\n    />\n  );\n}\n" },
  "archive/v0.2/virtual-list/infinite": { component: Demo458, file: "archive/v0.2/virtual-list/infinite.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { VirtualList } from '@akhatmirzo/ui';\nimport { useCallback, useState } from 'react';\n\nconst PAGE = 40;\nconst TOTAL = 400;\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\n\nconst makeOrders = (from: number) =>\n  Array.from({ length: PAGE }, (_, i) => {\n    const id = from + i + 1;\n    return {\n      id,\n      customer: NAMES[id % NAMES.length]!,\n      total: ((id * 7919) % 90) * 15_000 + 150_000,\n    };\n  });\n\nexport default function VirtualListInfinite() {\n  const [orders, setOrders] = useState(() => makeOrders(0));\n  const [loading, setLoading] = useState(false);\n\n  const loadMore = useCallback(() => {\n    if (orders.length >= TOTAL) return;\n    setLoading(true);\n    // Haqiqiy loyihada — fetch(`/api/orders?offset=${orders.length}`)\n    setTimeout(() => {\n      setOrders((prev) => [...prev, ...makeOrders(prev.length)]);\n      setLoading(false);\n    }, 900);\n  }, [orders.length]);\n\n  return (\n    <div className=\"flex w-full flex-col gap-2\">\n      <p className=\"m-0 text-sm text-text-muted\">\n        Yuklangan: {orders.length} / {TOTAL}\n      </p>\n      <VirtualList\n        aria-label=\"Buyurtmalar\"\n        items={orders}\n        estimateSize={52}\n        height={360}\n        loadingMore={loading}\n        onEndReached={loadMore}\n        getItemKey={(o) => o.id}\n        labels={{ loadingMore: 'Buyurtmalar yuklanmoqda...' }}\n        className=\"rounded-xl border border-border bg-surface\"\n        renderItem={(o) => (\n          <div className=\"flex h-13 items-center gap-3 border-b border-border px-4 text-sm\">\n            <span className=\"w-14 shrink-0 text-text-faint tabular-nums\">№{o.id}</span>\n            <span className=\"min-w-0 flex-1 truncate\">{o.customer}</span>\n            <span className=\"shrink-0 font-medium tabular-nums\">{formatMoney(o.total)}</span>\n          </div>\n        )}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/accordion/basic": { component: Demo459, file: "archive/v0.3/accordion/basic.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nconst faq = [\n  {\n    value: 'delivery',\n    title: 'Yetkazib berish qancha vaqt oladi?',\n    body: \"Toshkent bo'ylab 1 kun, viloyatlarga 2–3 ish kuni.\",\n  },\n  {\n    value: 'payment',\n    title: \"Qanday to'lov usullari bor?\",\n    body: \"Click, Payme, Uzum va naqd pul. Karta orqali to'lov darhol tasdiqlanadi.\",\n  },\n  {\n    value: 'return',\n    title: \"Mahsulotni qaytarsa bo'ladimi?\",\n    body: \"Ha, 14 kun ichida, qadoq buzilmagan bo'lsa.\",\n  },\n];\n\nexport default function AccordionBasic() {\n  return (\n    <Accordion defaultValue=\"delivery\" className=\"max-w-xl\">\n      {faq.map((q) => (\n        <Accordion.Item key={q.value} value={q.value} title={q.title}>\n          {q.body}\n        </Accordion.Item>\n      ))}\n    </Accordion>\n  );\n}\n" },
  "archive/v0.3/accordion/composition": { component: Demo460, file: "archive/v0.3/accordion/composition.tsx", source: "'use client';\n\nimport { Accordion, Badge } from '@akhatmirzo/ui';\n\nexport default function AccordionComposition() {\n  return (\n    <Accordion variant=\"bordered\" className=\"max-w-xl\">\n      <Accordion.Item value=\"notifications\">\n        <Accordion.Trigger>\n          <span className=\"flex items-center gap-2\">\n            Bildirishnomalar\n            <Badge color=\"primary\" size=\"sm\">\n              3 ta yangi\n            </Badge>\n          </span>\n        </Accordion.Trigger>\n        <Accordion.Content>\n          <ul className=\"m-0 flex list-disc flex-col gap-1 pl-5\">\n            <li>Buyurtma #1042 yetkazildi</li>\n            <li>Yangi sharh qoldirildi</li>\n            <li>To'lov qabul qilindi</li>\n          </ul>\n        </Accordion.Content>\n      </Accordion.Item>\n      <Accordion.Item value=\"security\">\n        <Accordion.Trigger>Xavfsizlik</Accordion.Trigger>\n        <Accordion.Content>Parolni oxirgi marta 3 oy oldin o'zgartirgansiz.</Accordion.Content>\n      </Accordion.Item>\n      <Accordion.Item value=\"billing\" disabled>\n        <Accordion.Trigger>To'lov ma'lumotlari (tez orada)</Accordion.Trigger>\n        <Accordion.Content>—</Accordion.Content>\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "archive/v0.3/accordion/controlled": { component: Demo461, file: "archive/v0.3/accordion/controlled.tsx", source: "'use client';\n\nimport { Accordion, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst sections = [\n  { value: 'profile', title: \"Shaxsiy ma'lumotlar\", body: \"Ism, telefon va tug'ilgan sana.\" },\n  { value: 'address', title: 'Manzillar', body: 'Uy: Toshkent, Chilonzor tumani, 9-mavze.' },\n  { value: 'cards', title: \"To'lov kartalari\", body: 'Uzcard •• 4521, Humo •• 9087.' },\n];\n\nexport default function AccordionControlled() {\n  const [open, setOpen] = useState<string[]>(['profile']);\n\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <div className=\"flex flex-wrap gap-2\">\n        <Button size=\"sm\" variant=\"outline\" onClick={() => setOpen(sections.map((s) => s.value))}>\n          Hammasini ochish\n        </Button>\n        <Button size=\"sm\" variant=\"outline\" onClick={() => setOpen([])}>\n          Hammasini yopish\n        </Button>\n      </div>\n      <Accordion type=\"multiple\" value={open} onValueChange={setOpen}>\n        {sections.map((s) => (\n          <Accordion.Item key={s.value} value={s.value} title={s.title}>\n            {s.body}\n          </Accordion.Item>\n        ))}\n      </Accordion>\n    </div>\n  );\n}\n" },
  "archive/v0.3/accordion/multiple": { component: Demo462, file: "archive/v0.3/accordion/multiple.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionMultiple() {\n  return (\n    <Accordion type=\"multiple\" defaultValue={['delivery', 'payment']} className=\"max-w-xl\">\n      <Accordion.Item value=\"delivery\" title=\"Yetkazib berish qancha vaqt oladi?\">\n        Toshkent bo'ylab 1 kun, viloyatlarga 2–3 ish kuni.\n      </Accordion.Item>\n      <Accordion.Item value=\"payment\" title=\"Qanday to'lov usullari bor?\">\n        Click, Payme, Uzum va naqd pul.\n      </Accordion.Item>\n      <Accordion.Item value=\"return\" title=\"Mahsulotni qaytarsa bo'ladimi?\">\n        Ha, 14 kun ichida, qadoq buzilmagan bo'lsa.\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "archive/v0.3/accordion/non-collapsible": { component: Demo463, file: "archive/v0.3/accordion/non-collapsible.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionNonCollapsible() {\n  return (\n    <Accordion collapsible={false} defaultValue=\"courier\" variant=\"bordered\" className=\"max-w-xl\">\n      <Accordion.Item value=\"courier\" title=\"Kuryer orqali\">\n        Ertasi kuni eshigingizgacha. Narxi — 25 000 so'm.\n      </Accordion.Item>\n      <Accordion.Item value=\"pickup\" title=\"Olib ketish punktidan\">\n        Toshkentdagi 12 ta punktdan bepul olib ketasiz.\n      </Accordion.Item>\n      <Accordion.Item value=\"post\" title=\"Pochta orqali\">\n        Viloyatlarga 2–3 ish kuni. Narxi — 18 000 so'm.\n      </Accordion.Item>\n    </Accordion>\n  );\n}\n" },
  "archive/v0.3/accordion/variants": { component: Demo464, file: "archive/v0.3/accordion/variants.tsx", source: "'use client';\n\nimport { Accordion } from '@akhatmirzo/ui';\n\nexport default function AccordionVariants() {\n  return (\n    <div className=\"grid w-full gap-6 md:grid-cols-3\">\n      {(['separated', 'bordered', 'ghost'] as const).map((variant) => (\n        <div key={variant} className=\"flex flex-col gap-2\">\n          <span className=\"text-xs font-medium text-text-muted\">{variant}</span>\n          <Accordion variant={variant} defaultValue=\"a\">\n            <Accordion.Item value=\"a\" title=\"Yetkazib berish\">\n              Toshkent bo'ylab 1 kun.\n            </Accordion.Item>\n            <Accordion.Item value=\"b\" title=\"To'lov\">\n              Click, Payme yoki naqd.\n            </Accordion.Item>\n            <Accordion.Item value=\"c\" title=\"Qaytarish\">\n              14 kun ichida.\n            </Accordion.Item>\n          </Accordion>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/alert/actions": { component: Demo465, file: "archive/v0.3/alert/actions.tsx", source: "'use client';\n\nimport { Alert, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function AlertActions() {\n  const [open, setOpen] = useState(true);\n\n  if (!open) {\n    return (\n      <Button size=\"sm\" onClick={() => setOpen(true)}>\n        Xabarni qaytarish\n      </Button>\n    );\n  }\n\n  return (\n    <Alert\n      className=\"max-w-xl\"\n      color=\"danger\"\n      title=\"To'lov o'tmadi\"\n      action={\n        <Button size=\"sm\" variant=\"outline\">\n          Qayta urinish\n        </Button>\n      }\n      onClose={() => setOpen(false)}\n    >\n      Bank to'lovni rad etdi. Karta ma'lumotlarini tekshiring.\n    </Alert>\n  );\n}\n" },
  "archive/v0.3/alert/banner": { component: Demo466, file: "archive/v0.3/alert/banner.tsx", source: "'use client';\n\nimport { Alert, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function AlertBanner() {\n  const [open, setOpen] = useState(true);\n\n  return (\n    <div className=\"w-full overflow-hidden rounded-lg border border-border bg-surface\">\n      {open && (\n        <Alert banner color=\"primary\" onClose={() => setOpen(false)}>\n          Bugun 23:00 dan 01:00 gacha texnik ishlar olib boriladi.\n        </Alert>\n      )}\n      <div className=\"flex items-center justify-between gap-3 p-6 text-sm text-text-muted\">\n        Sahifa kontenti\n        {!open && (\n          <Button size=\"sm\" onClick={() => setOpen(true)}>\n            Qaytarish\n          </Button>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/alert/colors": { component: Demo467, file: "archive/v0.3/alert/colors.tsx", source: "'use client';\n\nimport { Alert } from '@akhatmirzo/ui';\n\nexport default function AlertColors() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <Alert title=\"Yangi versiya chiqdi\">\n        Sahifani yangilang — o'zgarishlar darhol kuchga kiradi.\n      </Alert>\n      <Alert color=\"success\" title=\"Buyurtma qabul qilindi\">\n        Kuryer bugun 18:00 gacha qo'ng'iroq qiladi.\n      </Alert>\n      <Alert color=\"warning\" title=\"Obuna 3 kundan keyin tugaydi\">\n        To'lovni hozir qilsangiz, ma'lumotlaringiz saqlanib qoladi.\n      </Alert>\n      <Alert color=\"danger\" title=\"To'lov o'tmadi\">\n        Kartada mablag' yetarli emas. Boshqa kartani sinab ko'ring.\n      </Alert>\n      <Alert color=\"primary\" title=\"Maslahat\">\n        Tez qidirish uchun Ctrl + K ni bosing.\n      </Alert>\n      <Alert color=\"neutral\" title=\"Qoralama saqlandi\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/alert/variants": { component: Demo468, file: "archive/v0.3/alert/variants.tsx", source: "'use client';\n\nimport { Alert } from '@akhatmirzo/ui';\n\nexport default function AlertVariants() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      <Alert color=\"success\" variant=\"soft\" title=\"Soft\">\n        Yumshoq fon — standart ko'rinish.\n      </Alert>\n      <Alert color=\"success\" variant=\"outline\" title=\"Outline\">\n        Rangli chegara va oddiy fon.\n      </Alert>\n      <Alert color=\"success\" variant=\"solid\" title=\"Solid\">\n        To'q fon — eng ko'p e'tibor tortadi.\n      </Alert>\n    </div>\n  );\n}\n" },
  "archive/v0.3/avatar/basic": { component: Demo469, file: "archive/v0.3/avatar/basic.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nconst people = [\n  'Sarvar Abduxoliqov',\n  'Malika Rahimova',\n  'Jasur Karimov',\n  \"O'tkir Hoshimov\",\n  'Dilnoza Yusupova',\n  'Rustam Qodirov',\n];\n\nexport default function AvatarBasic() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {people.map((name) => (\n        <Avatar key={name} name={name} />\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/avatar/group": { component: Demo470, file: "archive/v0.3/avatar/group.tsx", source: "'use client';\n\nimport { Avatar, AvatarGroup } from '@akhatmirzo/ui';\n\nconst team = [\n  'Sarvar Abduxoliqov',\n  'Malika Rahimova',\n  'Jasur Karimov',\n  'Dilnoza Yusupova',\n  'Rustam Qodirov',\n  'Gulnora Aliyeva',\n  'Bekzod Toshmatov',\n];\n\nexport default function AvatarGroupDemo() {\n  return (\n    <AvatarGroup max={4} aria-label=\"Loyiha ishtirokchilari\">\n      {team.map((name) => (\n        <Avatar key={name} name={name} />\n      ))}\n    </AvatarGroup>\n  );\n}\n" },
  "archive/v0.3/avatar/image": { component: Demo471, file: "archive/v0.3/avatar/image.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarImage() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Avatar size=\"lg\" src=\"https://github.com/Akhatmirzo.png\" name=\"Akhatmirzo\" />\n      <Avatar size=\"lg\" src=\"/mavjud-emas.png\" name=\"Gulnora Aliyeva\" />\n      <Avatar size=\"lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/avatar/sizes": { component: Demo472, file: "archive/v0.3/avatar/sizes.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarSizes() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Avatar size=\"xs\" name=\"Malika Rahimova\" />\n        <Avatar size=\"sm\" name=\"Malika Rahimova\" />\n        <Avatar size=\"md\" name=\"Malika Rahimova\" />\n        <Avatar size=\"lg\" name=\"Malika Rahimova\" />\n        <Avatar size=\"xl\" name=\"Malika Rahimova\" />\n      </div>\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Avatar size=\"sm\" shape=\"square\" name=\"Bahor Market\" />\n        <Avatar size=\"md\" shape=\"square\" name=\"Bahor Market\" />\n        <Avatar size=\"lg\" shape=\"square\" name=\"Bahor Market\" />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/avatar/status": { component: Demo473, file: "archive/v0.3/avatar/status.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarStatus() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Avatar name=\"Sarvar Abduxoliqov\" status=\"online\" />\n      <Avatar name=\"Malika Rahimova\" status=\"offline\" />\n      <Avatar name=\"Rustam Qodirov\" status=\"busy\" />\n      <Avatar name=\"Jasur Karimov\" shape=\"square\" size=\"lg\" status=\"online\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/badge/colors": { component: Demo474, file: "archive/v0.3/badge/colors.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeColors() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge>Qoralama</Badge>\n      <Badge color=\"primary\">Yangi</Badge>\n      <Badge color=\"success\">To'langan</Badge>\n      <Badge color=\"warning\">Kutilmoqda</Badge>\n      <Badge color=\"danger\">Bekor qilindi</Badge>\n      <Badge color=\"info\">Yo'lda</Badge>\n    </div>\n  );\n}\n" },
  "archive/v0.3/badge/dot": { component: Demo475, file: "archive/v0.3/badge/dot.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeDot() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge dot color=\"success\">\n        Onlayn\n      </Badge>\n      <Badge dot color=\"warning\" variant=\"outline\">\n        Tekshirilmoqda\n      </Badge>\n      <Badge dot color=\"danger\" variant=\"solid\">\n        To'xtatilgan\n      </Badge>\n    </div>\n  );\n}\n" },
  "archive/v0.3/badge/removable": { component: Demo476, file: "archive/v0.3/badge/removable.tsx", source: "'use client';\n\nimport { Badge, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst initial = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\"];\n\nexport default function BadgeRemovable() {\n  const [cities, setCities] = useState(initial);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      {cities.map((city) => (\n        <Badge\n          key={city}\n          variant=\"outline\"\n          onRemove={() => setCities((list) => list.filter((c) => c !== city))}\n          labels={{ remove: `${city} filtrini olib tashlash` }}\n        >\n          {city}\n        </Badge>\n      ))}\n      {cities.length < initial.length && (\n        <Button variant=\"link\" size=\"sm\" onClick={() => setCities(initial)}>\n          Qaytarish\n        </Button>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.3/badge/sizes": { component: Demo477, file: "archive/v0.3/badge/sizes.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge size=\"sm\" color=\"primary\">\n        Kichik\n      </Badge>\n      <Badge size=\"md\" color=\"primary\">\n        O'rta\n      </Badge>\n    </div>\n  );\n}\n" },
  "archive/v0.3/badge/variants": { component: Demo478, file: "archive/v0.3/badge/variants.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeVariants() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge variant=\"soft\" color=\"success\">\n          Soft\n        </Badge>\n        <Badge variant=\"solid\" color=\"success\">\n          Solid\n        </Badge>\n        <Badge variant=\"outline\" color=\"success\">\n          Outline\n        </Badge>\n      </div>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge variant=\"soft\" color=\"danger\">\n          Soft\n        </Badge>\n        <Badge variant=\"solid\" color=\"danger\">\n          Solid\n        </Badge>\n        <Badge variant=\"outline\" color=\"danger\">\n          Outline\n        </Badge>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/breadcrumb/basic": { component: Demo479, file: "archive/v0.3/breadcrumb/basic.tsx", source: "'use client';\n\nimport { Breadcrumb } from '@akhatmirzo/ui';\nimport { House } from 'lucide-react';\n\nexport default function BreadcrumbBasic() {\n  return (\n    <Breadcrumb\n      items={[\n        { label: 'Bosh sahifa', href: '#', icon: <House /> },\n        { label: 'Mahsulotlar', href: '#mahsulotlar' },\n        { label: 'Telefonlar', href: '#telefonlar' },\n        { label: 'iPhone 17' },\n      ]}\n    />\n  );\n}\n" },
  "archive/v0.3/breadcrumb/collapse": { component: Demo480, file: "archive/v0.3/breadcrumb/collapse.tsx", source: "'use client';\n\nimport { Breadcrumb } from '@akhatmirzo/ui';\nimport { House } from 'lucide-react';\n\nexport default function BreadcrumbCollapse() {\n  return (\n    <Breadcrumb\n      maxItems={4}\n      items={[\n        { label: 'Bosh sahifa', href: '#', icon: <House /> },\n        { label: 'Katalog', href: '#katalog' },\n        { label: 'Elektronika', href: '#elektronika' },\n        { label: 'Telefonlar', href: '#telefonlar' },\n        { label: 'Apple', href: '#apple' },\n        { label: 'iPhone 17 Pro Max 256 GB' },\n      ]}\n    />\n  );\n}\n" },
  "archive/v0.3/breadcrumb/separator": { component: Demo481, file: "archive/v0.3/breadcrumb/separator.tsx", source: "'use client';\n\nimport { Breadcrumb } from '@akhatmirzo/ui';\n\nconst items = [\n  { label: 'Sozlamalar', href: '#' },\n  { label: 'Hisob', href: '#hisob' },\n  { label: 'Xavfsizlik' },\n];\n\nexport default function BreadcrumbSeparator() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      <Breadcrumb items={items} separator=\"/\" />\n      <Breadcrumb items={items} size=\"sm\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/button/as-child": { component: Demo482, file: "archive/v0.3/button/as-child.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { ArrowRight } from 'lucide-react';\n\nexport default function ButtonAsChild() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button asChild variant=\"outline\" rightIcon={<ArrowRight />}>\n        <a href=\"#accessibility\">Accessibility bo'limiga</a>\n      </Button>\n      <Button asChild variant=\"link\">\n        <a href=\"https://github.com/Akhatmirzo/akhatmirzo-toolkit\">GitHub</a>\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/button/full-width": { component: Demo483, file: "archive/v0.3/button/full-width.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonFullWidth() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Button variant=\"primary\" fullWidth>\n        Kirish\n      </Button>\n      <Button variant=\"outline\" fullWidth>\n        Ro'yxatdan o'tish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/button/icons": { component: Demo484, file: "archive/v0.3/button/icons.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { ArrowRight, Plus, Trash2 } from 'lucide-react';\n\nexport default function ButtonIcons() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\" leftIcon={<Plus />}>\n        Qo'shish\n      </Button>\n      <Button rightIcon={<ArrowRight />}>Davom etish</Button>\n      <Button variant=\"danger\" leftIcon={<Trash2 />}>\n        O'chirish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/button/loading": { component: Demo485, file: "archive/v0.3/button/loading.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function ButtonLoading() {\n  const [saving, setSaving] = useState(false);\n\n  const save = () => {\n    setSaving(true);\n    setTimeout(() => {\n      setSaving(false);\n      toast.success('Saqlandi');\n    }, 1500);\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\" loading={saving} onClick={save}>\n        Saqlash\n      </Button>\n      <Button variant=\"outline\" loading labels={{ loading: 'Yuborilmoqda' }}>\n        Yuborish\n      </Button>\n      <Button disabled>O'chirilgan</Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/button/sizes": { component: Demo486, file: "archive/v0.3/button/sizes.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button size=\"sm\">Kichik · 32</Button>\n      <Button size=\"md\">O'rta · 40</Button>\n      <Button size=\"lg\">Katta · 48</Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/button/variants": { component: Demo487, file: "archive/v0.3/button/variants.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonVariants() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\">Saqlash</Button>\n      <Button>Soft</Button>\n      <Button variant=\"outline\">Outline</Button>\n      <Button variant=\"ghost\">Ghost</Button>\n      <Button variant=\"danger\">O'chirish</Button>\n      <Button variant=\"link\">Batafsil</Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/card/basic": { component: Demo488, file: "archive/v0.3/card/basic.tsx", source: "'use client';\n\nimport { Avatar, Badge, Button, Card } from '@akhatmirzo/ui';\n\nexport default function CardBasic() {\n  return (\n    <Card className=\"w-full max-w-md\">\n      <Card.Header\n        title=\"Buyurtma #1042\"\n        description=\"Bugun, 14:20\"\n        action={\n          <Badge color=\"primary\" dot>\n            Yangi\n          </Badge>\n        }\n      />\n      <Card.Body>\n        <div className=\"flex items-center gap-3\">\n          <Avatar name=\"Sarvar Abduxoliqov\" size=\"sm\" />\n          <div className=\"flex flex-col\">\n            <span className=\"font-medium\">Sarvar Abduxoliqov</span>\n            <span className=\"text-text-muted\">3 ta mahsulot · 245 000 so'm</span>\n          </div>\n        </div>\n      </Card.Body>\n      <Card.Footer className=\"justify-end\">\n        <Button variant=\"ghost\">Bekor qilish</Button>\n        <Button variant=\"primary\">Tasdiqlash</Button>\n      </Card.Footer>\n    </Card>\n  );\n}\n" },
  "archive/v0.3/card/interactive": { component: Demo489, file: "archive/v0.3/card/interactive.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nconst reports = [\n  { title: 'Sotuvlar', description: \"Oktyabr · 48 250 000 so'm\" },\n  { title: 'Mijozlar', description: '1 204 ta faol mijoz' },\n];\n\nexport default function CardInteractive() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-2\">\n      {reports.map((report) => (\n        <Card key={report.title} variant=\"outline\" interactive asChild>\n          <a href=\"#props\">\n            <Card.Header title={report.title} description={report.description} />\n          </a>\n        </Card>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/card/media": { component: Demo490, file: "archive/v0.3/card/media.tsx", source: "'use client';\n\nimport { Badge, Card } from '@akhatmirzo/ui';\n\nexport default function CardMedia() {\n  return (\n    <Card padding=\"none\" className=\"w-full max-w-sm overflow-hidden\">\n      <div className=\"h-32 bg-linear-to-br from-primary to-info\" />\n      <div className=\"flex flex-col gap-3 p-6\">\n        <Card.Header title=\"Samarqand bo'ylab sayohat\" description=\"2 kun · 4 ta joy\" />\n        <Card.Footer>\n          <Badge color=\"success\" size=\"sm\">\n            Joy bor\n          </Badge>\n          <Badge size=\"sm\">Guruh</Badge>\n        </Card.Footer>\n      </div>\n    </Card>\n  );\n}\n" },
  "archive/v0.3/card/padding": { component: Demo491, file: "archive/v0.3/card/padding.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nconst paddings = [\n  { padding: 'sm', px: 16 },\n  { padding: 'md', px: 24 },\n  { padding: 'lg', px: 32 },\n] as const;\n\nexport default function CardPadding() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-3\">\n      {paddings.map(({ padding, px }) => (\n        <Card key={padding} variant=\"outline\" padding={padding}>\n          <div className=\"rounded-md bg-primary-soft p-2 text-xs font-medium text-primary-soft-foreground\">\n            {padding} · {px}px\n          </div>\n        </Card>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/card/variants": { component: Demo492, file: "archive/v0.3/card/variants.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nexport default function CardVariants() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-3\">\n      <Card variant=\"elevated\" padding=\"sm\">\n        <Card.Header title=\"Elevated\" description=\"Soya va chegara (standart)\" />\n      </Card>\n      <Card variant=\"outline\" padding=\"sm\">\n        <Card.Header title=\"Outline\" description=\"Faqat chegara\" />\n      </Card>\n      <Card variant=\"soft\" padding=\"sm\">\n        <Card.Header title=\"Soft\" description=\"Och kulrang fon\" />\n      </Card>\n    </div>\n  );\n}\n" },
  "archive/v0.3/checkbox/basic": { component: Demo493, file: "archive/v0.3/checkbox/basic.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxBasic() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <Checkbox label=\"Shartlarga roziman\" />\n      <Checkbox label=\"Meni eslab qol\" defaultChecked />\n      <Checkbox label=\"Qisman tanlangan\" checked=\"indeterminate\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/checkbox/description": { component: Demo494, file: "archive/v0.3/checkbox/description.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxDescription() {\n  return (\n    <div className=\"flex max-w-sm flex-col gap-4\">\n      <Checkbox\n        label=\"Yangiliklar\"\n        description=\"Haftasiga bir marta yangi imkoniyatlar haqida xat\"\n        defaultChecked\n      />\n      <Checkbox\n        size=\"sm\"\n        label=\"Qurilmani eslab qolish\"\n        description=\"30 kun davomida qayta kod so'ralmaydi\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/checkbox/select-all": { component: Demo495, file: "archive/v0.3/checkbox/select-all.tsx", source: "'use client';\n\nimport { Checkbox, type CheckedState } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst channels = ['Email', 'SMS', 'Telegram'];\n\nexport default function CheckboxSelectAll() {\n  const [selected, setSelected] = useState<string[]>(['Email']);\n  const all: CheckedState =\n    selected.length === channels.length ? true : selected.length > 0 ? 'indeterminate' : false;\n\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <Checkbox\n        label=\"Barcha kanallar\"\n        checked={all}\n        onCheckedChange={(checked) => setSelected(checked ? channels : [])}\n      />\n      <div className=\"flex flex-col gap-3 pl-7\">\n        {channels.map((channel) => (\n          <Checkbox\n            key={channel}\n            label={channel}\n            checked={selected.includes(channel)}\n            onCheckedChange={(checked) =>\n              setSelected((s) => (checked ? [...s, channel] : s.filter((c) => c !== channel)))\n            }\n          />\n        ))}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/checkbox/sizes": { component: Demo496, file: "archive/v0.3/checkbox/sizes.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-6\">\n      <Checkbox size=\"sm\" label=\"Kichik · 16\" defaultChecked />\n      <Checkbox size=\"md\" label=\"O'rta · 20\" defaultChecked />\n    </div>\n  );\n}\n" },
  "archive/v0.3/checkbox/states": { component: Demo497, file: "archive/v0.3/checkbox/states.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxStates() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <Checkbox label=\"O'chirilgan\" disabled />\n      <Checkbox label=\"O'chirilgan, belgilangan\" disabled defaultChecked />\n      <Checkbox label=\"Xato\" invalid />\n    </div>\n  );\n}\n" },
  "archive/v0.3/checkbox/with-field": { component: Demo498, file: "archive/v0.3/checkbox/with-field.tsx", source: "'use client';\n\nimport { Checkbox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CheckboxWithField() {\n  const [agree, setAgree] = useState(false);\n\n  return (\n    <div className=\"max-w-sm\">\n      <Field\n        label=\"Foydalanish shartlari\"\n        required\n        error={agree ? undefined : 'Davom etish uchun rozilik kerak'}\n      >\n        <Checkbox label=\"Shartlar bilan tanishdim\" checked={agree} onCheckedChange={setAgree} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/combobox/basic": { component: Demo499, file: "archive/v0.3/combobox/basic.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst cities = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Xiva',\n  'Namangan',\n  'Andijon',\n  \"Farg'ona\",\n  \"Qo'qon\",\n  \"Marg'ilon\",\n  'Nukus',\n  'Qarshi',\n  'Termiz',\n].map((label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }));\n\nexport default function ComboboxBasic() {\n  const [city, setCity] = useState<string | null>(null);\n\n  return (\n    <Field\n      label=\"Shahar\"\n      description={city ? `Qiymat: ${city}` : 'Hali tanlanmagan'}\n      className=\"w-full max-w-xs\"\n    >\n      <Combobox\n        options={cities}\n        value={city}\n        onValueChange={setCity}\n        placeholder=\"Shahar tanlang\"\n        clearable\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.3/combobox/creatable": { component: Demo500, file: "archive/v0.3/combobox/creatable.tsx", source: "'use client';\n\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst initialTags: ComboboxOption[] = ['dizayn', 'frontend', 'backend', 'mobil'].map((t) => ({\n  value: t,\n  label: t,\n}));\n\nexport default function ComboboxCreatable() {\n  const [tags, setTags] = useState(initialTags);\n  const [chosen, setChosen] = useState<string[]>(['frontend']);\n\n  return (\n    <Field\n      label=\"Teglar\"\n      description=\"Ro'yxatda yo'q tegni yozing va Enter bosing\"\n      className=\"w-full max-w-sm\"\n    >\n      <Combobox\n        multiple\n        creatable\n        options={tags}\n        value={chosen}\n        onValueChange={setChosen}\n        onCreate={(text) => {\n          const option = { value: text.toLowerCase(), label: text };\n          setTags((prev) => [...prev, option]);\n          return option;\n        }}\n        placeholder=\"Teg qo'shing\"\n        leftIcon={null}\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.3/combobox/details": { component: Demo501, file: "archive/v0.3/combobox/details.tsx", source: "'use client';\n\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\n\nfunction Dot({ className }: { className: string }) {\n  return <span className={`size-2.5 rounded-full ${className}`} />;\n}\n\nconst statuses: ComboboxOption[] = [\n  {\n    value: 'new',\n    label: 'Yangi',\n    description: 'Buyurtma qabul qilindi',\n    icon: <Dot className=\"bg-info\" />,\n  },\n  {\n    value: 'packing',\n    label: \"Yig'ilmoqda\",\n    description: 'Omborda tayyorlanmoqda',\n    icon: <Dot className=\"bg-warning\" />,\n  },\n  {\n    value: 'shipping',\n    label: \"Yo'lda\",\n    description: 'Kuryerga topshirildi',\n    icon: <Dot className=\"bg-primary\" />,\n  },\n  {\n    value: 'cancelled',\n    label: 'Bekor qilingan',\n    description: 'Arxivlangan holat',\n    icon: <Dot className=\"bg-danger\" />,\n    disabled: true,\n  },\n];\n\nexport default function ComboboxDetails() {\n  return (\n    <Field label=\"Buyurtma holati\" className=\"w-full max-w-xs\">\n      <Combobox options={statuses} defaultValue=\"packing\" leftIcon={null} />\n    </Field>\n  );\n}\n" },
  "archive/v0.3/combobox/multiple": { component: Demo502, file: "archive/v0.3/combobox/multiple.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst branches = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Namangan',\n  'Andijon',\n  \"Farg'ona\",\n  'Nukus',\n].map((label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }));\n\nexport default function ComboboxMultiple() {\n  const [selected, setSelected] = useState<string[]>(['toshkent', 'samarqand']);\n\n  return (\n    <Field\n      label=\"Filiallar\"\n      description={`${selected.length} ta tanlangan`}\n      className=\"w-full max-w-sm\"\n    >\n      <Combobox\n        multiple\n        options={branches}\n        value={selected}\n        onValueChange={setSelected}\n        placeholder=\"Filiallarni tanlang\"\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.3/combobox/server": { component: Demo503, file: "archive/v0.3/combobox/server.tsx", source: "'use client';\n\nimport { searchMatch } from '@akhatmirzo/core';\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\nimport { useRef, useState } from 'react';\n\nconst all: ComboboxOption[] = ['Toshkent', 'Samarqand', 'Buxoro', 'Xiva', 'Nukus', 'Termiz'].map(\n  (label) => ({ value: label.toLowerCase(), label }),\n);\n\nexport default function ComboboxServer() {\n  const [options, setOptions] = useState(all.slice(0, 3));\n  const [loading, setLoading] = useState(false);\n  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);\n\n  // Server so'rovini taqlid qiladi: javob 700ms dan keyin keladi\n  const search = (query: string) => {\n    clearTimeout(timer.current);\n    setLoading(true);\n    timer.current = setTimeout(() => {\n      setOptions(query ? all.filter((o) => searchMatch(o.label, query).match) : all.slice(0, 3));\n      setLoading(false);\n    }, 700);\n  };\n\n  return (\n    <Field label=\"Shahar (serverdan)\" className=\"w-full max-w-xs\">\n      <Combobox\n        options={options}\n        loading={loading}\n        onSearch={search}\n        placeholder=\"Qidirib tanlang\"\n        searchPlaceholder=\"Shahar nomi...\"\n        emptyText=\"Server hech narsa qaytarmadi\"\n      />\n    </Field>\n  );\n}\n" },
  "archive/v0.3/combobox/sizes": { component: Demo504, file: "archive/v0.3/combobox/sizes.tsx", source: "'use client';\n\nimport { Combobox } from '@akhatmirzo/ui';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro'].map((label) => ({\n  value: label.toLowerCase(),\n  label,\n}));\n\nexport default function ComboboxSizes() {\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Combobox size=\"sm\" options={cities} aria-label=\"Shahar\" placeholder=\"sm — 32px\" />\n      <Combobox size=\"md\" options={cities} aria-label=\"Shahar\" placeholder=\"md — 40px\" />\n      <Combobox size=\"lg\" options={cities} aria-label=\"Shahar\" placeholder=\"lg — 48px\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/combobox/states": { component: Demo505, file: "archive/v0.3/combobox/states.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro'].map((label) => ({\n  value: label.toLowerCase(),\n  label,\n}));\n\nexport default function ComboboxStates() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <Field label=\"O'chirilgan\" disabled>\n        <Combobox options={cities} defaultValue=\"toshkent\" />\n      </Field>\n      <Field label=\"Shahar\" error=\"Shaharni tanlang\" required>\n        <Combobox options={cities} placeholder=\"Shahar tanlang\" />\n      </Field>\n      <Field label=\"Yuklanmoqda\">\n        <Combobox options={[]} loading placeholder=\"Ochib ko'ring\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/combobox/uzbek-search": { component: Demo506, file: "archive/v0.3/combobox/uzbek-search.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\n\nconst districts = [\n  'Gʻuzor',\n  \"G'allaorol\",\n  'Oʻrta Chirchiq',\n  \"Qo'shrabot\",\n  'Shahrisabz',\n  'Chilonzor',\n  'Yunusobod',\n  \"Mirzo Ulug'bek\",\n  'Toshkent tumani',\n].map((label, i) => ({ value: String(i), label }));\n\nexport default function ComboboxUzbekSearch() {\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field label=\"Tuman\">\n        <Combobox options={districts} placeholder=\"Tumanni tanlang\" />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Yozib ko'ring: <span className=\"font-medium text-text\">guzor</span>,{' '}\n        <span className=\"font-medium text-text\">g‘allaorol</span>,{' '}\n        <span className=\"font-medium text-text\">Чилонзор</span>,{' '}\n        <span className=\"font-medium text-text\">ulugbek</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/command-palette/basic": { component: Demo507, file: "archive/v0.3/command-palette/basic.tsx", source: "'use client';\n\nimport { Button, CommandPalette, Kbd, toast, type CommandPaletteGroup } from '@akhatmirzo/ui';\nimport {\n  ChartColumn,\n  FileSpreadsheet,\n  House,\n  Package,\n  Plus,\n  Search,\n  Settings,\n  UserPlus,\n  Users,\n} from 'lucide-react';\n\nconst run = (label: string) => () => toast(`\"${label}\" bajarildi`);\n\nconst groups: CommandPaletteGroup[] = [\n  {\n    heading: 'Sahifalar',\n    items: [\n      { label: 'Bosh sahifa', icon: <House />, onSelect: run('Bosh sahifa') },\n      {\n        label: 'Buyurtmalar',\n        icon: <Package />,\n        keywords: ['zakaz', 'savdo'],\n        onSelect: run('Buyurtmalar'),\n      },\n      { label: 'Mijozlar', icon: <Users />, onSelect: run('Mijozlar') },\n      {\n        label: 'Hisobotlar',\n        icon: <ChartColumn />,\n        keywords: ['statistika'],\n        onSelect: run('Hisobotlar'),\n      },\n      {\n        label: 'Sozlamalar',\n        icon: <Settings />,\n        shortcut: ['mod', ','],\n        onSelect: run('Sozlamalar'),\n      },\n    ],\n  },\n  {\n    heading: 'Amallar',\n    items: [\n      {\n        label: 'Yangi buyurtma',\n        icon: <Plus />,\n        shortcut: ['mod', 'N'],\n        onSelect: run('Yangi buyurtma'),\n      },\n      { label: \"Mijoz qo'shish\", icon: <UserPlus />, onSelect: run(\"Mijoz qo'shish\") },\n      {\n        label: 'Eksport (Excel)',\n        icon: <FileSpreadsheet />,\n        keywords: ['xlsx'],\n        onSelect: run('Eksport'),\n      },\n    ],\n  },\n];\n\nexport default function CommandPaletteBasic() {\n  return (\n    // Docs saytida Ctrl+K qidiruvga band, shuning uchun bu yerda mod+J\n    <CommandPalette groups={groups} hotkey=\"mod+j\">\n      <Button variant=\"outline\" leftIcon={<Search />} className=\"min-w-64 justify-start\">\n        <span className=\"flex-1 text-left text-text-muted\">Qidirish...</span>\n        <Kbd keys={['mod', 'J']} />\n      </Button>\n    </CommandPalette>\n  );\n}\n" },
  "archive/v0.3/command-palette/pages": { component: Demo508, file: "archive/v0.3/command-palette/pages.tsx", source: "'use client';\n\nimport { Button, CommandPalette, toast, type CommandPaletteGroup } from '@akhatmirzo/ui';\nimport { Globe, Moon, Sun, User } from 'lucide-react';\n\nconst customers = ['Aziza Karimova', 'Bobur Toshmatov', \"G'ayrat Usmonov\", 'Malika Yusupova'];\n\nconst groups: CommandPaletteGroup[] = [\n  {\n    heading: 'Sozlamalar',\n    items: [\n      {\n        label: 'Mavzuni almashtirish',\n        icon: <Moon />,\n        keywords: ['tungi rejim', 'dark'],\n        page: {\n          title: 'Mavzu',\n          placeholder: 'Mavzu tanlang...',\n          groups: [\n            {\n              heading: 'Mavzu',\n              items: [\n                {\n                  id: 'theme-light',\n                  label: \"Yorug'\",\n                  icon: <Sun />,\n                  onSelect: () => toast(\"Yorug' mavzu\"),\n                },\n                {\n                  id: 'theme-dark',\n                  label: \"Qorong'i\",\n                  icon: <Moon />,\n                  onSelect: () => toast(\"Qorong'i mavzu\"),\n                },\n              ],\n            },\n          ],\n        },\n      },\n      {\n        label: 'Tilni almashtirish',\n        icon: <Globe />,\n        page: {\n          title: 'Til',\n          groups: [\n            {\n              heading: 'Til',\n              items: [\n                { id: 'lang-uz', label: \"O'zbekcha\", onSelect: () => toast(\"O'zbekcha\") },\n                { id: 'lang-en', label: 'English', disabled: true },\n              ],\n            },\n          ],\n        },\n      },\n    ],\n  },\n  {\n    heading: 'Mijozlar',\n    searchOnly: true,\n    items: customers.map((name) => ({ label: name, icon: <User />, onSelect: () => toast(name) })),\n  },\n];\n\nexport default function CommandPalettePages() {\n  return (\n    <CommandPalette groups={groups} hotkey={false} recent={false}>\n      <Button variant=\"soft\">Sozlamalarni ochish</Button>\n    </CommandPalette>\n  );\n}\n" },
  "archive/v0.3/command-palette/server": { component: Demo509, file: "archive/v0.3/command-palette/server.tsx", source: "'use client';\n\nimport { Button, CommandPalette, toast, type CommandPaletteItem } from '@akhatmirzo/ui';\nimport { Plus, User } from 'lucide-react';\n\nconst customers = [\n  ['Akmal Ergashev', '+998 90 123 45 67'],\n  ['Akbar Sobirov', '+998 93 555 12 34'],\n  ['Kamola Akramova', '+998 97 700 00 11'],\n  ['Nodira Ahmedova', '+998 91 444 22 33'],\n] as const;\n\n/** Server qidiruvini taqlid qiladi (700ms); yangi so'rov eskisini bekor qiladi */\nfunction searchCustomers(query: string, { signal }: { signal: AbortSignal }) {\n  return new Promise<CommandPaletteItem[]>((resolve, reject) => {\n    const timer = setTimeout(() => {\n      const q = query.toLowerCase();\n      resolve(\n        customers\n          .filter(([name]) => name.toLowerCase().includes(q))\n          .map(([name, phone]) => ({\n            id: `customer-${name}`,\n            label: name,\n            description: phone,\n            icon: <User />,\n            onSelect: () => toast(name),\n          })),\n      );\n    }, 700);\n    signal.addEventListener('abort', () => {\n      clearTimeout(timer);\n      reject(new DOMException('Bekor qilindi', 'AbortError'));\n    });\n  });\n}\n\nexport default function CommandPaletteServer() {\n  return (\n    <CommandPalette\n      hotkey={false}\n      recentKey=\"docs:command-palette:server\"\n      placeholder=\"Mijoz yoki buyruq qidirish...\"\n      onSearch={searchCustomers}\n      labels={{ results: 'Mijozlar (serverdan)' }}\n      groups={[\n        {\n          heading: 'Amallar',\n          items: [\n            { label: \"Mijoz qo'shish\", icon: <Plus />, onSelect: () => toast(\"Mijoz qo'shish\") },\n          ],\n        },\n      ]}\n    >\n      <Button variant=\"outline\">Mijoz qidirish</Button>\n    </CommandPalette>\n  );\n}\n" },
  "archive/v0.3/core/api-errors": { component: Demo510, file: "archive/v0.3/core/api-errors.tsx", source: "'use client';\n\nimport { createApiClient, isApiError, type FetchLike } from '@akhatmirzo/core';\nimport { Badge, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\n// Haqiqiy server o'rniga: `/status/404` → 404 javob, `/sekin` → hech qachon javob bermaydi\nconst fakeFetch: FetchLike = (url, init) =>\n  new Promise((resolve, reject) => {\n    if (url.endsWith('/sekin')) {\n      init.signal?.addEventListener('abort', () => reject(new Error('aborted')));\n      return;\n    }\n    const status = Number(url.split('/').pop());\n    resolve({ ok: status < 400, status, headers: { get: () => null }, text: async () => '' });\n  });\n\nconst api = createApiClient({ baseUrl: '/api', timeout: 1500, fetch: fakeFetch });\n\nexport default function CoreApiErrors() {\n  const [result, setResult] = useState<{ code: string; message: string } | null>(null);\n\n  const request = async (path: string) => {\n    try {\n      await api.get(path);\n      setResult({ code: 'OK', message: 'Muvaffaqiyatli' });\n    } catch (error) {\n      if (isApiError(error)) setResult({ code: error.code, message: error.message });\n    }\n  };\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div className=\"flex flex-wrap gap-2\">\n        {['401', '403', '404', '422', '500'].map((s) => (\n          <Button key={s} size=\"sm\" variant=\"outline\" onClick={() => request(`/status/${s}`)}>\n            {s}\n          </Button>\n        ))}\n        <Button size=\"sm\" variant=\"outline\" onClick={() => request('/sekin')}>\n          Timeout\n        </Button>\n      </div>\n      {result && (\n        <div className=\"flex items-center gap-2 text-sm\">\n          <Badge color={result.code === 'OK' ? 'success' : 'danger'}>{result.code}</Badge>\n          <span className=\"text-text\">{result.message}</span>\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/card-validate": { component: Demo511, file: "archive/v0.3/core/card-validate.tsx", source: "'use client';\n\nimport { detectCardBrand, formatCardNumber, isValidCardNumber } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst BRANDS = { uzcard: 'Uzcard', humo: 'Humo', visa: 'Visa', mastercard: 'Mastercard' };\n\nexport default function CoreCardValidate() {\n  const [digits, setDigits] = useState('8600');\n  const brand = detectCardBrand(digits);\n  const complete = digits.length === 16;\n  const valid = isValidCardNumber(digits);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field\n        label=\"Karta raqami\"\n        description=\"To'g'ri namuna: 4111 1111 1111 1111\"\n        error={complete && !valid ? \"Karta raqami noto'g'ri\" : undefined}\n      >\n        <Input\n          value={formatCardNumber(digits)}\n          onChange={(e) => setDigits(e.target.value.replace(/\\D/g, '').slice(0, 16))}\n          inputMode=\"numeric\"\n          placeholder=\"0000 0000 0000 0000\"\n          suffix={brand ? BRANDS[brand] : undefined}\n        />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={brand ? 'info' : 'neutral'}>{brand ? BRANDS[brand] : \"Brend noma'lum\"}</Badge>\n        <Badge color={!complete ? 'neutral' : valid ? 'success' : 'danger'} dot>\n          {!complete ? `${digits.length}/16` : valid ? \"Luhn: to'g'ri\" : 'Luhn: xato'}\n        </Badge>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/date-uz": { component: Demo512, file: "archive/v0.3/core/date-uz.tsx", source: "'use client';\n\nimport { formatDateRange, formatDateUz, formatDuration } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst STYLES = ['long', 'full', 'short', 'dayMonth', 'monthYear'] as const;\n\nexport default function CoreDateUz() {\n  const [value, setValue] = useState('2026-10-22');\n  const [y = 2026, m = 10, d = 22] = value.split('-').map(Number);\n  const date = new Date(y, m - 1, d, 14, 30);\n  const end = new Date(y, m - 1, d + 3);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Sana\">\n        <Input type=\"date\" value={value} onChange={(e) => setValue(e.target.value)} />\n      </Field>\n      <dl className=\"grid grid-cols-[auto_1fr] gap-x-4 gap-y-2 text-sm\">\n        {STYLES.map((style) => (\n          <div key={style} className=\"contents\">\n            <dt className=\"font-mono text-xs text-text-muted\">{style}</dt>\n            <dd>{formatDateUz(date, { style })}</dd>\n          </div>\n        ))}\n        <dt className=\"font-mono text-xs text-text-muted\">kirill</dt>\n        <dd>{formatDateUz(date, { style: 'full', script: 'cyrillic' })}</dd>\n        <dt className=\"font-mono text-xs text-text-muted\">+3 kun</dt>\n        <dd>{formatDateRange(date, end)}</dd>\n        <dt className=\"font-mono text-xs text-text-muted\">davomiylik</dt>\n        <dd>{formatDuration(end.getTime() - date.getTime(), { units: 3 })}</dd>\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/date": { component: Demo513, file: "archive/v0.3/core/date.tsx", source: "'use client';\n\nimport { formatDate, parseDate } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst PATTERNS = ['dd.MM.yyyy', 'd MMMM yyyy, EEEE', 'd MMM, EEE', 'EEEE, d MMMM [soat] HH:mm'];\nconst DATE = new Date(2026, 9, 21, 14, 30);\n\nexport default function CoreDate() {\n  const [pattern, setPattern] = useState('d MMMM yyyy, EEEE');\n  const [input, setInput] = useState('31.02.2026');\n  const parsed = parseDate(input);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field\n        label=\"Shablon\"\n        description={`formatDate(sana, shablon) → ${formatDate(DATE, pattern)}`}\n      >\n        <Input value={pattern} onChange={(e) => setPattern(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        {PATTERNS.map((p) => (\n          <button key={p} type=\"button\" onClick={() => setPattern(p)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{p}</Badge>\n          </button>\n        ))}\n      </div>\n      <Field\n        label=\"parseDate (dd.MM.yyyy)\"\n        description={parsed ? formatDate(parsed, 'EEEE, d MMMM yyyy') : \"null — bunday sana yo'q\"}\n      >\n        <Input value={input} onChange={(e) => setInput(e.target.value)} invalid={!parsed} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/debounce-throttle": { component: Demo514, file: "archive/v0.3/core/debounce-throttle.tsx", source: "'use client';\n\nimport { debounce, throttle } from '@akhatmirzo/core';\nimport { Button } from '@akhatmirzo/ui';\nimport { useEffect, useMemo, useState } from 'react';\n\ntype Counts = { raw: number; throttled: number; debounced: number };\nconst ZERO: Counts = { raw: 0, throttled: 0, debounced: 0 };\nconst inc = (key: keyof Counts) => (c: Counts) => ({ ...c, [key]: c[key] + 1 });\n\nexport default function CoreDebounceThrottle() {\n  const [counts, setCounts] = useState(ZERO);\n\n  const onDebounced = useMemo(() => debounce(() => setCounts(inc('debounced')), 400), []);\n  const onThrottled = useMemo(() => throttle(() => setCounts(inc('throttled')), 400), []);\n\n  useEffect(\n    () => () => {\n      onDebounced.cancel();\n      onThrottled.cancel();\n    },\n    [onDebounced, onThrottled],\n  );\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div\n        onPointerMove={() => {\n          setCounts(inc('raw'));\n          onDebounced();\n          onThrottled();\n        }}\n        className=\"flex h-32 touch-none items-center justify-center rounded-xl border border-dashed border-border-strong bg-surface-muted text-sm text-text-muted\"\n      >\n        Sichqoncha yoki barmoqni shu yerda yurgizing\n      </div>\n      <dl className=\"grid grid-cols-3 gap-2 text-center text-sm\">\n        {(['raw', 'throttled', 'debounced'] as const).map((key) => (\n          <div key={key} className=\"rounded-lg border border-border bg-surface p-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{key}</dt>\n            <dd className=\"text-xl font-semibold text-text tabular-nums\">{counts[key]}</dd>\n          </div>\n        ))}\n      </dl>\n      <Button size=\"sm\" variant=\"ghost\" onClick={() => setCounts(ZERO)}>\n        Nolga qaytarish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/fuzzy": { component: Demo515, file: "archive/v0.3/core/fuzzy.tsx", source: "'use client';\n\nimport { fuzzyMatch, splitByRanges } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst COMMANDS = [\n  'Yangi buyurtma',\n  \"Buyurtmalar ro'yxati\",\n  \"Mijoz qo'shish\",\n  'Hisobotlar',\n  'Sozlamalar',\n  'Profilni tahrirlash',\n  'Mavzuni almashtirish',\n];\n\nexport default function CoreFuzzy() {\n  const [query, setQuery] = useState('ybu');\n  const results = COMMANDS.flatMap((label) => {\n    const result = fuzzyMatch(label, query);\n    return result ? [{ label, ...result }] : [];\n  }).sort((a, b) => b.score - a.score);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Field label=\"Buyruq\" description=\"Harflar tartibi muhim: mq, hsb, prof\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <ul className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {results.map(({ label, ranges, score }) => (\n          <li key={label} className=\"flex items-center justify-between gap-3 px-3 py-2\">\n            <span>\n              {splitByRanges(label, ranges).map((part, i) =>\n                part.match ? (\n                  <strong key={i} className=\"font-semibold text-primary-soft-foreground\">\n                    {part.text}\n                  </strong>\n                ) : (\n                  <span key={i}>{part.text}</span>\n                ),\n              )}\n            </span>\n            <span className=\"font-mono text-xs text-text-muted\">{score}</span>\n          </li>\n        ))}\n        {results.length === 0 && <li className=\"px-3 py-2 text-text-muted\">Mos buyruq yo'q</li>}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/identifiers": { component: Demo516, file: "archive/v0.3/core/identifiers.tsx", source: "'use client';\n\nimport {\n  formatCarPlate,\n  formatDate,\n  formatPinfl,\n  parseCarPlate,\n  parsePinfl,\n} from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CoreIdentifiers() {\n  const [pinfl, setPinfl] = useState('31503901234567');\n  const [plate, setPlate] = useState('01a123bc');\n  const person = parsePinfl(pinfl);\n  const car = parseCarPlate(plate);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"JShShIR\" description={formatPinfl(pinfl) || '—'}>\n        <Input value={pinfl} onChange={(e) => setPinfl(e.target.value)} inputMode=\"numeric\" />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={person ? 'success' : 'neutral'} dot>\n          {person ? \"To'g'ri\" : \"Noto'g'ri yoki to'liq emas\"}\n        </Badge>\n        {person && <Badge color=\"info\">{person.gender === 'male' ? 'Erkak' : 'Ayol'}</Badge>}\n        {person && <Badge color=\"info\">{formatDate(person.birthDate)}</Badge>}\n      </div>\n      <Field label=\"Avtomobil raqami\" description={formatCarPlate(plate) || '—'}>\n        <Input value={plate} onChange={(e) => setPlate(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={car ? 'success' : 'neutral'} dot>\n          {car ? (car.type === 'personal' ? 'Jismoniy shaxs' : 'Yuridik shaxs') : \"Noto'g'ri\"}\n        </Badge>\n        {car && <Badge color=\"info\">{car.region.name}</Badge>}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/money": { component: Demo517, file: "archive/v0.3/core/money.tsx", source: "'use client';\n\nimport { formatMoney, formatNumber, type MoneyCurrency } from '@akhatmirzo/core';\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CURRENCIES: MoneyCurrency[] = [\"so'm\", 'UZS', false];\n\nexport default function CoreMoney() {\n  const [raw, setRaw] = useState('1250000.5');\n  const [currency, setCurrency] = useState<MoneyCurrency>(\"so'm\");\n  const n = Number(raw.replace(',', '.').replace(/\\s/g, ''));\n\n  const rows = [\n    { call: 'formatNumber(n)', value: formatNumber(n) },\n    { call: 'formatNumber(n, { decimals: 2 })', value: formatNumber(n, { decimals: 2 }) },\n    { call: 'formatMoney(n, { currency })', value: formatMoney(n, { currency }) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Son\">\n        <Input value={raw} onChange={(e) => setRaw(e.target.value)} inputMode=\"decimal\" />\n      </Field>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        {CURRENCIES.map((c) => (\n          <Button\n            key={String(c)}\n            size=\"sm\"\n            variant={currency === c ? 'primary' : 'outline'}\n            onClick={() => setCurrency(c)}\n          >\n            {c === false ? 'false' : c}\n          </Button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.call} className=\"flex flex-wrap justify-between gap-x-4 gap-y-1 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.call}</dt>\n            <dd className=\"font-mono font-medium text-text tabular-nums\">{row.value || \"''\"}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/number-words": { component: Demo518, file: "archive/v0.3/core/number-words.tsx", source: "'use client';\n\nimport { moneyToWords, numberToWords, ordinalWords } from '@akhatmirzo/core';\nimport { Field, Input, SegmentedControl } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\ntype Script = 'latin' | 'cyrillic';\n\nexport default function CoreNumberWords() {\n  const [raw, setRaw] = useState('1250000.50');\n  const [script, setScript] = useState<Script>('latin');\n  const n = Number(raw.replace(',', '.').replace(/\\s/g, ''));\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Summa\">\n        <Input value={raw} onChange={(e) => setRaw(e.target.value)} inputMode=\"decimal\" />\n      </Field>\n      <SegmentedControl\n        aria-label=\"Alifbo\"\n        value={script}\n        onValueChange={(v) => setScript(v as Script)}\n      >\n        <SegmentedControl.Item value=\"latin\">Lotin</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"cyrillic\">Кирилл</SegmentedControl.Item>\n      </SegmentedControl>\n      <dl className=\"grid gap-2 text-sm\">\n        <dt className=\"font-mono text-xs text-text-muted\">numberToWords</dt>\n        <dd>{numberToWords(n, { script }) || '—'}</dd>\n        <dt className=\"font-mono text-xs text-text-muted\">moneyToWords</dt>\n        <dd>{moneyToWords(n, { script }) || '—'}</dd>\n        <dt className=\"font-mono text-xs text-text-muted\">ordinalWords</dt>\n        <dd>{ordinalWords(n, { script }) || '—'}</dd>\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/password": { component: Demo519, file: "archive/v0.3/core/password.tsx", source: "'use client';\n\nimport { passwordStrength } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst BAR = ['bg-danger', 'bg-danger', 'bg-warning', 'bg-success', 'bg-success'];\nconst COLOR = ['danger', 'danger', 'warning', 'success', 'success'] as const;\nconst CHECKS = {\n  length: 'Kamida 8 belgi',\n  lower: 'Kichik harf',\n  upper: 'Katta harf',\n  digit: 'Raqam',\n  symbol: 'Belgi (!@#…)',\n};\n\nexport default function CorePassword() {\n  const [password, setPassword] = useState('Parol123');\n  const { score, label, checks } = passwordStrength(password);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Parol\">\n        <Input type=\"password\" value={password} onChange={(e) => setPassword(e.target.value)} />\n      </Field>\n      <div className=\"flex gap-1\" aria-hidden>\n        {[1, 2, 3, 4].map((i) => (\n          <span\n            key={i}\n            className={`h-1.5 flex-1 rounded-full ${password && i <= Math.max(score, 1) ? BAR[score] : 'bg-surface-muted'}`}\n          />\n        ))}\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Badge color={COLOR[score]}>{label}</Badge>\n        <span className=\"text-xs text-text-muted\">score: {score}/4</span>\n      </div>\n      <ul className=\"flex flex-col gap-1 text-sm\">\n        {(Object.keys(CHECKS) as (keyof typeof CHECKS)[]).map((key) => (\n          <li key={key} className={checks[key] ? 'text-text' : 'text-text-muted'}>\n            {checks[key] ? '✓' : '○'} {CHECKS[key]}\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/phone-card": { component: Demo520, file: "archive/v0.3/core/phone-card.tsx", source: "'use client';\n\nimport { formatCardNumber, formatPhone } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst digitsOf = (s: string) => s.replace(/\\D/g, '');\n\nexport default function CorePhoneCard() {\n  const [phone, setPhone] = useState('90123');\n  const [card, setCard] = useState('8600 1234');\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" description={`formatPhone: ${formatPhone(phone) || '—'}`}>\n        <Input\n          prefix=\"+998\"\n          value={formatPhone(phone, 'national')}\n          onChange={(e) => setPhone(digitsOf(e.target.value).slice(0, 9))}\n          inputMode=\"tel\"\n          placeholder=\"(90) 123-45-67\"\n        />\n      </Field>\n      <Field label=\"Karta raqami\" description={`Toza qiymat: ${digitsOf(card) || '—'}`}>\n        <Input\n          value={card}\n          onChange={(e) => setCard(formatCardNumber(digitsOf(e.target.value).slice(0, 16)))}\n          inputMode=\"numeric\"\n          placeholder=\"0000 0000 0000 0000\"\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/phone-validate": { component: Demo521, file: "archive/v0.3/core/phone-validate.tsx", source: "'use client';\n\nimport { isValidEmail, parsePhone } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CorePhoneValidate() {\n  const [phone, setPhone] = useState('+998 90 123-45-67');\n  const [email, setEmail] = useState('sarvar@mail');\n  const parsed = parsePhone(phone);\n  const code = parsed.digits.slice(0, 2);\n  const phoneError =\n    code.length === 2 && !parsed.operator ? `\"${code}\" — bunday operator kodi yo'q` : undefined;\n  const emailValid = isValidEmail(email);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" error={phoneError} description={`digits: ${parsed.digits || '—'}`}>\n        <Input value={phone} onChange={(e) => setPhone(e.target.value)} inputMode=\"tel\" />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={parsed.valid ? 'success' : 'neutral'} dot>\n          {parsed.valid ? \"To'g'ri raqam\" : \"To'liq emas\"}\n        </Badge>\n        {parsed.operator && <Badge color=\"info\">Operator: {parsed.operator}</Badge>}\n      </div>\n      <Field\n        label=\"Email\"\n        error={email.trim() && !emailValid ? \"Email manzil noto'g'ri\" : undefined}\n      >\n        <Input type=\"email\" value={email} onChange={(e) => setEmail(e.target.value)} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/script": { component: Demo522, file: "archive/v0.3/core/script.tsx", source: "'use client';\n\nimport { detectScript, fixApostrophes, toScript } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst SAMPLES = [\n  \"O'zbekiston g'alabasi, ma'no\",\n  'Салом, дунё',\n  'Toshkent — Тошкент',\n  \"'Salom' dedi\",\n];\n\nexport default function CoreScript() {\n  const [text, setText] = useState(\"O'zbekiston g'alabasi, ma'no\");\n\n  const rows = [\n    { name: \"toScript(s, 'latin')\", value: toScript(text, 'latin') },\n    { name: \"toScript(s, 'cyrillic')\", value: toScript(text, 'cyrillic') },\n    { name: 'fixApostrophes', value: fixApostrophes(text) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Matn\">\n        <Input value={text} onChange={(e) => setText(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge color=\"info\">detectScript: {detectScript(text)}</Badge>\n        {SAMPLES.map((s) => (\n          <button key={s} type=\"button\" onClick={() => setText(s)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{s}</Badge>\n          </button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.name} className=\"flex items-center justify-between gap-4 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.name}</dt>\n            <dd className=\"font-mono break-all text-text\">{row.value || '—'}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/search": { component: Demo523, file: "archive/v0.3/core/search.tsx", source: "'use client';\n\nimport { searchMatch, splitByRanges } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CITIES = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  \"Farg'ona\",\n  'Qo‘qon',\n  'Shahrisabz',\n  'Chirchiq',\n  'Ғузор',\n  'Ўрта Чирчиқ',\n  'Шаҳрихон',\n];\n\nexport default function CoreSearch() {\n  const [query, setQuery] = useState('шаҳ');\n  const results = CITIES.map((city) => ({ city, ...searchMatch(city, query) })).filter(\n    (r) => r.match,\n  );\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Field label=\"Shahar qidirish\" description=\"Sinab ko'ring: chir, ғуз, fargona, qo'qon\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <ul className=\"flex flex-wrap gap-2\">\n        {results.map(({ city, ranges }) => (\n          <li key={city} className=\"rounded-lg border border-border bg-surface px-3 py-1.5 text-sm\">\n            {splitByRanges(city, ranges).map((part, i) =>\n              part.match ? (\n                <mark key={i} className=\"rounded-sm bg-primary-soft text-primary-soft-foreground\">\n                  {part.text}\n                </mark>\n              ) : (\n                <span key={i}>{part.text}</span>\n              ),\n            )}\n          </li>\n        ))}\n        {results.length === 0 && <li className=\"text-sm text-text-muted\">Hech narsa topilmadi</li>}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/storage": { component: Demo524, file: "archive/v0.3/core/storage.tsx", source: "'use client';\n\nimport { createStorage } from '@akhatmirzo/core';\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst store = createStorage({ prefix: 'docs-demo:' });\n\nexport default function CoreStorage() {\n  const [value, setValue] = useState('Sarvar');\n  const [result, setResult] = useState('—');\n\n  const save = (ttl?: number) => {\n    const ok = store.set('ism', value, { ttl });\n    setResult(\n      ok ? `Saqlandi${ttl ? ` (${ttl / 1000} soniya)` : ' (muddatsiz)'}` : \"Saqlab bo'lmadi\",\n    );\n  };\n\n  const read = () => {\n    const saved = store.get<string>('ism');\n    setResult(saved === null ? \"null — yo'q yoki muddati o'tgan\" : JSON.stringify(saved));\n  };\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Qiymat\" description=\"Kalit: docs-demo:ism\">\n        <Input value={value} onChange={(e) => setValue(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Button variant=\"primary\" onClick={() => save(5000)}>\n          5 soniyaga saqlash\n        </Button>\n        <Button variant=\"outline\" onClick={() => save()}>\n          Muddatsiz\n        </Button>\n        <Button variant=\"ghost\" onClick={read}>\n          O'qish\n        </Button>\n      </div>\n      <p className=\"text-sm text-text-muted\">\n        Natija: <code className=\"font-mono text-text\">{result}</code>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/time-ago": { component: Demo525, file: "archive/v0.3/core/time-ago.tsx", source: "'use client';\n\nimport { timeAgo } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst MINUTE = 60_000;\nconst NOW = new Date(2026, 9, 21, 12, 0);\nconst OFFSETS = [5, 180, 1440, 4320, 20160, 136800, -120, -1440];\n\nexport default function CoreTimeAgo() {\n  const [minutes, setMinutes] = useState('90');\n  const custom = new Date(NOW.getTime() - Number(minutes || 0) * MINUTE);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Necha daqiqa oldin\" description={`timeAgo → ${timeAgo(custom, NOW)}`}>\n        <Input\n          value={minutes}\n          onChange={(e) => setMinutes(e.target.value.replace(/[^\\d-]/g, ''))}\n          inputMode=\"numeric\"\n          suffix=\"daqiqa\"\n        />\n      </Field>\n      <ul className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {OFFSETS.map((m) => (\n          <li key={m} className=\"flex justify-between gap-4 px-3 py-2\">\n            <span className=\"font-mono text-xs text-text-muted\">{m} daqiqa</span>\n            <span className=\"text-text\">{timeAgo(NOW.getTime() - m * MINUTE, NOW)}</span>\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/translit": { component: Demo526, file: "archive/v0.3/core/translit.tsx", source: "'use client';\n\nimport { cyrToLat, latToCyr, normalizeUz } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst SAMPLES = ['Ғузор тумани', \"O'zbekiston\", 'Gʻuzor', 'ер, поезд, маъно', 'SHAHAR'];\n\nexport default function CoreTranslit() {\n  const [text, setText] = useState('Ғузор тумани');\n\n  const rows = [\n    { name: 'cyrToLat', value: cyrToLat(text) },\n    { name: 'latToCyr', value: latToCyr(text) },\n    { name: 'normalizeUz', value: normalizeUz(text) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Matn\">\n        <Input value={text} onChange={(e) => setText(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        {SAMPLES.map((s) => (\n          <button key={s} type=\"button\" onClick={() => setText(s)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{s}</Badge>\n          </button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.name} className=\"flex items-center justify-between gap-4 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.name}</dt>\n            <dd className=\"font-mono break-all text-text\">{row.value || '—'}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.3/core/truncate": { component: Demo527, file: "archive/v0.3/core/truncate.tsx", source: "'use client';\n\nimport { slugify, truncate, truncateMiddle } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst FILE = 'shartnoma-mchj-akhatmirzo-imzolangan.docx';\n\nexport default function CoreTruncate() {\n  const [title, setTitle] = useState(\"Farg'ona viloyati — 2026\");\n  const [max, setMax] = useState(24);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Sarlavha\" description={`slugify: ${slugify(title) || '—'}`}>\n        <Input value={title} onChange={(e) => setTitle(e.target.value)} />\n      </Field>\n      <label className=\"flex flex-col gap-2 text-sm font-medium text-text\">\n        Maksimal uzunlik: {max}\n        <input\n          type=\"range\"\n          min={6}\n          max={44}\n          value={max}\n          onChange={(e) => setMax(Number(e.target.value))}\n          className=\"w-full accent-primary\"\n        />\n      </label>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        <div className=\"flex flex-col gap-1 px-3 py-2\">\n          <dt className=\"font-mono text-xs text-text-muted\">truncateMiddle</dt>\n          <dd className=\"font-mono text-text\">{truncateMiddle(FILE, max)}</dd>\n        </div>\n        <div className=\"flex flex-col gap-1 px-3 py-2\">\n          <dt className=\"font-mono text-xs text-text-muted\">truncate</dt>\n          <dd className=\"font-mono text-text\">{truncate(FILE, max)}</dd>\n        </div>\n      </dl>\n    </div>\n  );\n}\n" },
  "archive/v0.3/data-table/basic": { component: Demo528, file: "archive/v0.3/data-table/basic.tsx", source: "'use client';\n\nimport { formatDate, formatMoney } from '@akhatmirzo/core';\nimport { Badge, Button, DataTable, toast, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Plus } from 'lucide-react';\n\ntype Status = 'paid' | 'pending' | 'shipped' | 'cancelled';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  date: Date;\n  status: Status;\n  total: number;\n}\n\nconst STATUS = {\n  paid: { label: \"To'langan\", color: 'success' },\n  pending: { label: 'Kutilmoqda', color: 'warning' },\n  shipped: { label: \"Yo'lda\", color: 'info' },\n  cancelled: { label: 'Bekor qilingan', color: 'danger' },\n} as const;\n\nconst NAMES = [\n  'Jasur Karimov',\n  'Malika Rahimova',\n  \"Bekzod G'aniyev\",\n  'Nodira Saidova',\n  'Aziz Normatov',\n];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\", 'Xorazm'];\nconst STATUSES = Object.keys(STATUS) as Status[];\n\nconst orders: Order[] = Array.from({ length: 48 }, (_, i) => ({\n  id: 1042 + i,\n  customer: NAMES[(i * 3) % NAMES.length]!,\n  region: REGIONS[(i * 7) % REGIONS.length]!,\n  date: new Date(2026, 9, 21 - (i % 30)),\n  status: STATUSES[(i * 5 + (i >> 2)) % 4]!,\n  total: 85_000 + ((i * 377_311) % 4_800_000),\n}));\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88, sortable: true, cell: (o) => `#${o.id}` },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  { key: 'region', header: 'Viloyat', sortable: true, filter: 'select' },\n  { key: 'date', header: 'Sana', sortable: true, cell: (o) => formatDate(o.date) },\n  {\n    key: 'status',\n    header: 'Holat',\n    filter: 'multiselect',\n    filterOptions: STATUSES.map((s) => ({ value: s, label: STATUS[s].label })),\n    searchValue: (o) => STATUS[o.status].label,\n    cell: (o) => (\n      <Badge dot color={STATUS[o.status].color}>\n        {STATUS[o.status].label}\n      </Badge>\n    ),\n  },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableBasic() {\n  return (\n    <DataTable\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      searchable\n      pagination={{ pageSize: 5, pageSizeOptions: [5, 10, 25] }}\n      className=\"w-full\"\n      toolbar={\n        <Button variant=\"primary\" leftIcon={<Plus />} onClick={() => toast('Yangi buyurtma')}>\n          Qo'shish\n        </Button>\n      }\n    />\n  );\n}\n" },
  "archive/v0.3/data-table/cards": { component: Demo529, file: "archive/v0.3/data-table/cards.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, toast, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  total: number;\n}\n\nconst orders: Order[] = [\n  { id: 1042, customer: 'Jasur Karimov', region: 'Toshkent', total: 1_250_000 },\n  { id: 1043, customer: 'Malika Rahimova', region: 'Samarqand', total: 480_000 },\n  { id: 1044, customer: 'Aziz Normatov', region: \"Farg'ona\", total: 2_730_000 },\n];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№' },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'region', header: 'Viloyat' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nexport default function DataTableCards() {\n  return (\n    <DataTable\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      mobileView=\"cards\"\n      selectable\n      onRowClick={(o) => toast(`Buyurtma #${o.id}`)}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.3/data-table/density": { component: Demo530, file: "archive/v0.3/data-table/density.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Employee {\n  id: number;\n  name: string;\n  position: string;\n  department: string;\n  phone: string;\n  city: string;\n  salary: number;\n}\n\nconst employees: Employee[] = [\n  {\n    id: 1,\n    name: 'Sarvar Abduxoliqov',\n    position: 'Frontend dasturchi',\n    department: 'IT',\n    phone: '+998 90 123 45 67',\n    city: 'Toshkent',\n    salary: 14_500_000,\n  },\n  {\n    id: 2,\n    name: \"Gulnora O'rinova\",\n    position: 'Buxgalter',\n    department: 'Moliya',\n    phone: '+998 93 555 12 34',\n    city: 'Samarqand',\n    salary: 9_800_000,\n  },\n  {\n    id: 3,\n    name: 'Javohir Ismoilov',\n    position: 'Dizayner',\n    department: 'Marketing',\n    phone: '+998 97 700 00 11',\n    city: 'Buxoro',\n    salary: 11_200_000,\n  },\n];\n\nconst columns: DataTableColumn<Employee>[] = [\n  { key: 'name', header: 'Xodim', width: 200, hideable: false },\n  { key: 'position', header: 'Lavozim' },\n  { key: 'department', header: \"Bo'lim\" },\n  { key: 'phone', header: 'Telefon', className: 'tabular-nums' },\n  { key: 'city', header: 'Shahar', hidden: true },\n  { key: 'salary', header: 'Maosh', numeric: true, cell: (e) => formatMoney(e.salary) },\n];\n\nexport default function DataTableDensity() {\n  return (\n    <DataTable\n      label=\"Xodimlar\"\n      data={employees}\n      columns={columns}\n      density=\"compact\"\n      stickyFirstColumn\n      selectable\n      tableClassName=\"min-w-[860px]\"\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.3/data-table/filters": { component: Demo531, file: "archive/v0.3/data-table/filters.tsx", source: "'use client';\n\nimport { formatDate, formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Payment {\n  id: number;\n  client: string;\n  method: string;\n  region: string;\n  date: Date;\n  amount: number;\n}\n\nconst METHODS = ['Click', 'Payme', 'Uzcard', 'Naqd'];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Andijon', 'Namangan'];\nconst CLIENTS = ['Dilnoza Yusupova', 'Otabek Qodirov', 'Shahnoza Ergasheva', 'Rustam Xolmatov'];\n\nconst payments: Payment[] = Array.from({ length: 40 }, (_, i) => ({\n  id: 501 + i,\n  client: CLIENTS[(i * 3) % CLIENTS.length]!,\n  method: METHODS[(i * 5) % METHODS.length]!,\n  region: REGIONS[(i + (i >> 2)) % REGIONS.length]!,\n  date: new Date(2026, 9, 25 - i),\n  amount: 50_000 + ((i * 213_457) % 3_000_000),\n}));\n\nconst columns: DataTableColumn<Payment>[] = [\n  { key: 'id', header: '№', width: 72, cell: (p) => `#${p.id}` },\n  { key: 'client', header: 'Mijoz' },\n  { key: 'method', header: \"To'lov turi\", filter: 'select' },\n  { key: 'region', header: 'Viloyat', filter: 'multiselect' },\n  { key: 'date', header: 'Sana', filter: 'date', sortable: true, cell: (p) => formatDate(p.date) },\n  {\n    key: 'amount',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    filter: 'range',\n    cell: (p) => formatMoney(p.amount),\n  },\n];\n\nexport default function DataTableFilters() {\n  return (\n    <DataTable\n      label=\"To'lovlar\"\n      data={payments}\n      columns={columns}\n      searchable\n      pagination={{ pageSize: 5 }}\n      initialState={{ filters: { method: 'Click' } }}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.3/data-table/selection": { component: Demo532, file: "archive/v0.3/data-table/selection.tsx", source: "'use client';\n\nimport {\n  DataTable,\n  DropdownMenu,\n  IconButton,\n  toast,\n  type DataTableColumn,\n  Button,\n} from '@akhatmirzo/ui';\nimport { Download, Ellipsis, Eye, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\ninterface Product {\n  id: string;\n  name: string;\n  sku: string;\n  stock: number;\n}\n\nconst initial: Product[] = [\n  { id: 'p1', name: \"Paxta ko'ylak\", sku: 'KY-001', stock: 42 },\n  { id: 'p2', name: \"Atlas ro'mol\", sku: 'RM-014', stock: 8 },\n  { id: 'p3', name: 'Choynak (1.5 l)', sku: 'CH-203', stock: 0 },\n  { id: 'p4', name: \"Do'ppi\", sku: 'DP-077', stock: 120 },\n  { id: 'p5', name: 'Sopol lagan', sku: 'LG-310', stock: 15 },\n];\n\nconst columns: DataTableColumn<Product>[] = [\n  { key: 'name', header: 'Mahsulot', sortable: true },\n  { key: 'sku', header: 'Artikul' },\n  { key: 'stock', header: 'Qoldiq', numeric: true, sortable: true },\n];\n\nexport default function DataTableSelection() {\n  const [products, setProducts] = useState(initial);\n  const remove = (ids: string[]) => setProducts((prev) => prev.filter((p) => !ids.includes(p.id)));\n\n  return (\n    <DataTable\n      label=\"Mahsulotlar\"\n      data={products}\n      columns={columns}\n      selectable\n      className=\"w-full\"\n      onRowClick={(p) => toast(`${p.name} ochildi`)}\n      bulkActions={(rows, clear) => (\n        <>\n          <Button\n            variant=\"outline\"\n            size=\"sm\"\n            leftIcon={<Download />}\n            onClick={() => toast(`${rows.length} ta eksport qilindi`)}\n          >\n            Eksport\n          </Button>\n          <Button\n            variant=\"danger\"\n            size=\"sm\"\n            leftIcon={<Trash2 />}\n            onClick={() => {\n              remove(rows.map((r) => r.id));\n              clear();\n            }}\n          >\n            O'chirish\n          </Button>\n        </>\n      )}\n      rowActions={(p) => (\n        <DropdownMenu>\n          <DropdownMenu.Trigger asChild>\n            <IconButton variant=\"ghost\" size=\"sm\" aria-label={`${p.name}: amallar`}>\n              <Ellipsis />\n            </IconButton>\n          </DropdownMenu.Trigger>\n          <DropdownMenu.Content align=\"end\">\n            <DropdownMenu.Item icon={<Eye />} onSelect={() => toast(p.name)}>\n              Ko'rish\n            </DropdownMenu.Item>\n            <DropdownMenu.Item variant=\"danger\" icon={<Trash2 />} onSelect={() => remove([p.id])}>\n              O'chirish\n            </DropdownMenu.Item>\n          </DropdownMenu.Content>\n        </DropdownMenu>\n      )}\n    />\n  );\n}\n" },
  "archive/v0.3/data-table/server": { component: Demo533, file: "archive/v0.3/data-table/server.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn, type DataTableState } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\ninterface Page {\n  rows: Order[];\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\nconst DB: Order[] = Array.from({ length: 137 }, (_, i) => ({\n  id: 2001 + i,\n  customer: NAMES[i % NAMES.length]!,\n  total: 90_000 + ((i * 271_828) % 3_500_000),\n}));\n\n/** \"Server\": qidiradi, saralaydi, sahifalaydi. Haqiqiy loyihada — fetch('/api/orders?...') */\nfunction fetchOrders({ search, sorting, pagination }: DataTableState): Promise<Page> {\n  let rows = DB.filter((o) => o.customer.toLowerCase().includes(search.toLowerCase()));\n  const sort = sorting[0];\n  if (sort) {\n    const key = sort.id as keyof Order;\n    rows = [...rows].sort((a, b) => (a[key] > b[key] ? 1 : -1) * (sort.desc ? -1 : 1));\n  }\n  const start = pagination.pageIndex * pagination.pageSize;\n  const page = { rows: rows.slice(start, start + pagination.pageSize), total: rows.length };\n  return new Promise((resolve) => setTimeout(() => resolve(page), 600));\n}\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88, sortable: true },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableServer() {\n  const [query, setQuery] = useState<DataTableState>({\n    sorting: [],\n    search: '',\n    filters: {},\n    pagination: { pageIndex: 0, pageSize: 10 },\n  });\n  const [result, setResult] = useState<Page>({ rows: [], total: 0 });\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    let active = true;\n    fetchOrders(query).then((page) => {\n      if (!active) return;\n      setResult(page);\n      setLoading(false);\n    });\n    return () => {\n      active = false;\n    };\n  }, [query]);\n\n  return (\n    <DataTable\n      label=\"Server buyurtmalari\"\n      data={result.rows}\n      rowCount={result.total}\n      columns={columns}\n      manual\n      searchable\n      pagination={{ pageSize: 10 }}\n      loading={loading}\n      onStateChange={(state) => {\n        setLoading(true);\n        setQuery(state);\n      }}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.3/data-table/states": { component: Demo534, file: "archive/v0.3/data-table/states.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { Button, DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\nimport { useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\nconst orders: Order[] = [\n  { id: 1042, customer: 'Jasur Karimov', total: 1_250_000 },\n  { id: 1043, customer: 'Malika Rahimova', total: 480_000 },\n  { id: 1044, customer: 'Aziz Normatov', total: 2_730_000 },\n];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88 },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nconst STATES = {\n  data: \"Ma'lumot\",\n  first: 'Birinchi yuklanish',\n  refetch: 'Qayta yuklanish',\n  empty: \"Bo'sh\",\n  error: 'Xato',\n} as const;\n\ntype State = keyof typeof STATES;\n\nexport default function DataTableStates() {\n  const [state, setState] = useState<State>('first');\n\n  return (\n    <div className=\"flex w-full flex-col gap-4\">\n      <div className=\"flex flex-wrap gap-2\">\n        {(Object.keys(STATES) as State[]).map((s) => (\n          <Button\n            key={s}\n            size=\"sm\"\n            variant={s === state ? 'primary' : 'outline'}\n            aria-pressed={s === state}\n            onClick={() => setState(s)}\n          >\n            {STATES[s]}\n          </Button>\n        ))}\n      </div>\n      <DataTable\n        label=\"Holatlar\"\n        data={state === 'data' || state === 'refetch' ? orders : []}\n        columns={columns}\n        columnToggle={false}\n        loading={state === 'first' || state === 'refetch'}\n        error={\n          state === 'error' ? 'Server javob bermadi. Internet aloqasini tekshiring.' : undefined\n        }\n        onRetry={() => setState('data')}\n        empty={{\n          icon: <Inbox />,\n          title: \"Hali buyurtmalar yo'q\",\n          description: \"Birinchi buyurtmani qo'shing — u shu yerda ko'rinadi.\",\n          action: (\n            <Button size=\"sm\" variant=\"primary\" leftIcon={<Plus />}>\n              Buyurtma qo'shish\n            </Button>\n          ),\n        }}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/data-table/virtual": { component: Demo535, file: "archive/v0.3/data-table/virtual.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { useMemo } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Farhod Tursunov', 'Mohira Nazarova'];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Buxoro', 'Navoiy', 'Xorazm'];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 96, sortable: true },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  { key: 'region', header: 'Viloyat', filter: 'select' },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableVirtual() {\n  const orders = useMemo<Order[]>(\n    () =>\n      Array.from({ length: 10_000 }, (_, i) => ({\n        id: i + 1,\n        customer: NAMES[i % NAMES.length]!,\n        region: REGIONS[(i * 3) % REGIONS.length]!,\n        total: 50_000 + ((i * 377_311) % 4_800_000),\n      })),\n    [],\n  );\n\n  return (\n    <DataTable\n      label=\"10 000 buyurtma\"\n      data={orders}\n      columns={columns}\n      virtual\n      maxHeight={400}\n      density=\"compact\"\n      searchable\n      columnToggle={false}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "archive/v0.3/date-picker/basic": { component: Demo536, file: "archive/v0.3/date-picker/basic.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DatePicker, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst isSunday = (date: Date) => date.getDay() === 0;\n\nexport default function DatePickerBasic() {\n  const [date, setDate] = useState<Date | null>(null);\n\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Field\n        label=\"Yetkazish sanasi\"\n        description={date ? formatDate(date, 'd MMMM yyyy, EEEE') : 'Yakshanba — dam olish kuni'}\n      >\n        <DatePicker\n          value={date}\n          onValueChange={setDate}\n          minDate={new Date()}\n          disabledDates={isSunday}\n          presets\n          clearable\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/date-picker/birthday": { component: Demo537, file: "archive/v0.3/date-picker/birthday.tsx", source: "'use client';\n\nimport { DatePicker, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DatePickerBirthday() {\n  const [birthday, setBirthday] = useState<Date | null>(new Date(1995, 4, 17));\n\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Field label=\"Tug'ilgan sana\" description=\"Sarlavhani bosing — oy va yilni tanlash\">\n        <DatePicker\n          value={birthday}\n          onValueChange={setBirthday}\n          minDate={new Date(1920, 0, 1)}\n          maxDate={new Date()}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/date-picker/calendar-range": { component: Demo538, file: "archive/v0.3/date-picker/calendar-range.tsx", source: "'use client';\n\nimport { Calendar, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);\n\nexport default function CalendarRange() {\n  const today = new Date();\n  const [range, setRange] = useState<DateRangeValue>({\n    from: addDays(today, -3),\n    to: addDays(today, 4),\n  });\n\n  return (\n    <div className=\"flex flex-col items-center gap-2\">\n      <Calendar\n        mode=\"range\"\n        numberOfMonths={2}\n        value={range}\n        onValueChange={setRange}\n        className=\"rounded-xl border border-border bg-surface p-3\"\n      />\n      <span className=\"text-sm text-text-muted\">\n        {range.from && !range.to ? 'Tugash sanasini tanlang' : 'Oraliq tanlandi'}\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.3/date-picker/calendar": { component: Demo539, file: "archive/v0.3/date-picker/calendar.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { Calendar } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CalendarInline() {\n  const [date, setDate] = useState<Date | null>(new Date());\n\n  return (\n    <div className=\"flex flex-col items-center gap-2\">\n      <Calendar\n        value={date}\n        onValueChange={setDate}\n        disabledDates={(d) => d.getDay() === 0}\n        className=\"rounded-xl border border-border bg-surface p-3\"\n      />\n      <span className=\"text-sm text-text-muted\">\n        {date ? formatDate(date, 'd MMMM yyyy, EEEE') : 'Sana tanlanmagan'}\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.3/date-picker/range-presets": { component: Demo540, file: "archive/v0.3/date-picker/range-presets.tsx", source: "'use client';\n\nimport { DateRangePicker, Field, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);\n\nexport default function DateRangePickerPresets() {\n  const [vacation, setVacation] = useState<DateRangeValue | null>(null);\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Ta'til\" description=\"Yakshanbalar yopiq\">\n        <DateRangePicker\n          value={vacation}\n          onValueChange={setVacation}\n          minDate={new Date()}\n          disabledDates={(d) => d.getDay() === 0}\n          clearable\n          name=\"tatil\"\n          presets={[\n            { label: 'Bir hafta', range: (t) => ({ from: addDays(t, 1), to: addDays(t, 7) }) },\n            { label: 'Ikki hafta', range: (t) => ({ from: addDays(t, 1), to: addDays(t, 14) }) },\n          ]}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/date-picker/range": { component: Demo541, file: "archive/v0.3/date-picker/range.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DateRangePicker, Field, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst daysAgo = (n: number) => {\n  const d = new Date();\n  return new Date(d.getFullYear(), d.getMonth(), d.getDate() - n);\n};\n\nexport default function DateRangePickerBasic() {\n  const [range, setRange] = useState<DateRangeValue | null>({ from: daysAgo(6), to: daysAgo(0) });\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field\n        label=\"Hisobot davri\"\n        description={\n          range?.from && range.to\n            ? `${formatDate(range.from, 'd MMM')} – ${formatDate(range.to, 'd MMM yyyy')}`\n            : 'Davr tanlanmagan'\n        }\n      >\n        <DateRangePicker value={range} onValueChange={setRange} presets maxDate={new Date()} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/date-picker/sizes": { component: Demo542, file: "archive/v0.3/date-picker/sizes.tsx", source: "'use client';\n\nimport { DatePicker } from '@akhatmirzo/ui';\n\nexport default function DatePickerSizes() {\n  const today = new Date();\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <DatePicker size=\"sm\" aria-label=\"Kichik\" defaultValue={today} />\n      <DatePicker size=\"md\" aria-label=\"O'rta\" defaultValue={today} />\n      <DatePicker size=\"lg\" aria-label=\"Katta\" defaultValue={today} />\n    </div>\n  );\n}\n" },
  "archive/v0.3/date-picker/states": { component: Demo543, file: "archive/v0.3/date-picker/states.tsx", source: "'use client';\n\nimport { DatePicker, Field } from '@akhatmirzo/ui';\n\nexport default function DatePickerStates() {\n  const today = new Date();\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"O'chirilgan\" disabled>\n        <DatePicker defaultValue={today} />\n      </Field>\n      <Field label=\"Faqat o'qish\">\n        <DatePicker defaultValue={today} readOnly />\n      </Field>\n      <Field label=\"Muddat\" error=\"Sanani tanlang\" required>\n        <DatePicker />\n      </Field>\n      <Field label=\"Boshqa format\" description=\"d MMMM yyyy\">\n        <DatePicker format=\"d MMMM yyyy\" defaultValue={today} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/date-picker/typing": { component: Demo544, file: "archive/v0.3/date-picker/typing.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DatePicker, Field, type DatePickerError } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst errorText: Record<DatePickerError, string> = {\n  invalid: \"Bunday sana yo'q\",\n  unavailable: \"O'tgan sanani tanlab bo'lmaydi\",\n};\n\nexport default function DatePickerTyping() {\n  const [date, setDate] = useState<Date | null>(null);\n  const [error, setError] = useState<DatePickerError | null>(null);\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field\n        label=\"Uchrashuv sanasi\"\n        required\n        error={error ? errorText[error] : undefined}\n        description=\"Sinab ko'ring: 31022026\"\n      >\n        <DatePicker\n          value={date}\n          onValueChange={setDate}\n          onErrorChange={setError}\n          minDate={new Date()}\n        />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Qiymat: <code>{date ? formatDate(date, 'yyyy-MM-dd') : 'null'}</code>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/dialog/async-submit": { component: Demo545, file: "archive/v0.3/dialog/async-submit.tsx", source: "'use client';\n\nimport { Button, Dialog, Field, Input, Textarea, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function DialogAsyncSubmit() {\n  const [open, setOpen] = useState(false);\n  const [sending, setSending] = useState(false);\n\n  const send = async () => {\n    setSending(true);\n    await wait(1500);\n    setSending(false);\n    setOpen(false);\n    toast.success('Fikringiz yuborildi');\n  };\n\n  return (\n    <Dialog open={open} onOpenChange={(next) => !sending && setOpen(next)}>\n      <Dialog.Trigger asChild>\n        <Button>Fikr bildirish</Button>\n      </Dialog.Trigger>\n      <Dialog.Content title=\"Fikr bildirish\" size=\"lg\" dismissible={!sending}>\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Mavzu\" required>\n            <Input placeholder=\"Masalan: yetkazib berish\" />\n          </Field>\n          <Field label=\"Xabar\">\n            <Textarea minRows={4} placeholder=\"Fikringizni yozing...\" />\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button disabled={sending}>Bekor qilish</Button>\n          </Dialog.Close>\n          <Button variant=\"primary\" loading={sending} onClick={send}>\n            Yuborish\n          </Button>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "archive/v0.3/dialog/basic": { component: Demo546, file: "archive/v0.3/dialog/basic.tsx", source: "'use client';\n\nimport { Button, Dialog, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DialogBasic() {\n  const [open, setOpen] = useState(false);\n  const [name, setName] = useState('Sarvar');\n  const [phone, setPhone] = useState('+998 90 123 45 67');\n\n  return (\n    <Dialog open={open} onOpenChange={setOpen}>\n      <Dialog.Trigger asChild>\n        <Button variant=\"primary\">Profilni tahrirlash</Button>\n      </Dialog.Trigger>\n      <Dialog.Content title=\"Profilni tahrirlash\" description=\"O'zgarishlar darhol saqlanadi.\">\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Ism\">\n            <Input value={name} onChange={(e) => setName(e.target.value)} />\n          </Field>\n          <Field label=\"Telefon\" description=\"Tasdiqlash uchun SMS kod yuboriladi\">\n            <Input value={phone} onChange={(e) => setPhone(e.target.value)} />\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button>Bekor qilish</Button>\n          </Dialog.Close>\n          <Button variant=\"primary\" onClick={() => setOpen(false)}>\n            Saqlash\n          </Button>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "archive/v0.3/dialog/confirm-dialog": { component: Demo547, file: "archive/v0.3/dialog/confirm-dialog.tsx", source: "'use client';\n\nimport { Button, ConfirmDialog, toast } from '@akhatmirzo/ui';\n\nexport default function DialogConfirmDeclarative() {\n  return (\n    <ConfirmDialog\n      trigger={<Button variant=\"outline\">Hisobdan chiqish</Button>}\n      title=\"Hisobdan chiqilsinmi?\"\n      description=\"Qayta kirish uchun SMS kod kerak bo'ladi.\"\n      confirmText=\"Chiqish\"\n      onConfirm={() => toast('Hisobdan chiqdingiz')}\n      onCancel={() => toast.info('Hisobda qoldingiz')}\n    />\n  );\n}\n" },
  "archive/v0.3/dialog/confirm": { component: Demo548, file: "archive/v0.3/dialog/confirm.tsx", source: "'use client';\n\nimport { Button, confirm, toast } from '@akhatmirzo/ui';\nimport { Trash2 } from 'lucide-react';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function DialogConfirm() {\n  const removeOrder = async () => {\n    const ok = await confirm({\n      title: \"Buyurtma o'chirilsinmi?\",\n      description: \"Bu amalni qaytarib bo'lmaydi.\",\n      confirmText: \"O'chirish\",\n      variant: 'danger',\n    });\n    if (ok) toast.success(\"Buyurtma #1042 o'chirildi\");\n  };\n\n  const publish = async () => {\n    const ok = await confirm({\n      title: 'Mahsulot nashr qilinsinmi?',\n      description: \"Mahsulot do'konda hammaga ko'rinadi.\",\n      confirmText: 'Nashr qilish',\n      // Promise tugaguncha tugma loading, oyna ochiq turadi\n      onConfirm: () => wait(1500),\n    });\n    if (ok) toast.success('Mahsulot nashr qilindi');\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"danger\" leftIcon={<Trash2 />} onClick={removeOrder}>\n        O'chirish\n      </Button>\n      <Button variant=\"primary\" onClick={publish}>\n        Nashr qilish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/dialog/options": { component: Demo549, file: "archive/v0.3/dialog/options.tsx", source: "'use client';\n\nimport { Button, Dialog } from '@akhatmirzo/ui';\n\nexport default function DialogOptions() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">dismissible=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content\n          title=\"Shartlarni o'qing\"\n          description=\"Tashqariga bosish yopmaydi — faqat tugma yoki Esc.\"\n          dismissible={false}\n        >\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Roziman</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">closeButton=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content title=\"✕ tugmasisiz\" closeButton={false} size=\"sm\">\n          <p className=\"m-0 text-sm text-text-muted\">Oyna faqat pastdagi tugma bilan yopiladi.</p>\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Yopish</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">hideTitle</Button>\n        </Dialog.Trigger>\n        <Dialog.Content title=\"Mahsulot rasmi\" hideTitle size=\"sm\">\n          <div className=\"grid h-40 place-items-center rounded-xl bg-surface-muted text-sm text-text-muted\">\n            Sarlavha faqat ekran o'quvchi uchun\n          </div>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">mobileSheet=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content\n          title=\"Doim markazda\"\n          description=\"Telefonda ham pastdan chiqmaydi.\"\n          mobileSheet={false}\n          size=\"sm\"\n        >\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Yaxshi</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n    </div>\n  );\n}\n" },
  "archive/v0.3/dialog/sizes": { component: Demo550, file: "archive/v0.3/dialog/sizes.tsx", source: "'use client';\n\nimport { Button, Dialog, type DialogSize } from '@akhatmirzo/ui';\n\nconst sizes: { size: DialogSize; width: string }[] = [\n  { size: 'sm', width: '400px' },\n  { size: 'md', width: '520px' },\n  { size: 'lg', width: '640px' },\n  { size: 'xl', width: '800px' },\n  { size: 'full', width: 'butun ekran' },\n];\n\nexport default function DialogSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sizes.map(({ size, width }) => (\n        <Dialog key={size}>\n          <Dialog.Trigger asChild>\n            <Button variant=\"outline\">{size}</Button>\n          </Dialog.Trigger>\n          <Dialog.Content\n            title={`O'lcham: ${size}`}\n            description={`Kenglik — ${width}.`}\n            size={size}\n          >\n            <p className=\"m-0 text-sm text-text-muted\">\n              Ekran tor bo'lsa, chetlarda 16px joy qoladi. Telefonda oyna pastdan chiqadi.\n            </p>\n            <Dialog.Footer>\n              <Dialog.Close asChild>\n                <Button variant=\"primary\">Tushunarli</Button>\n              </Dialog.Close>\n            </Dialog.Footer>\n          </Dialog.Content>\n        </Dialog>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/dialog/with-select": { component: Demo551, file: "archive/v0.3/dialog/with-select.tsx", source: "'use client';\n\nimport { Button, Combobox, Dialog, Field, Select } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro', 'Andijon', \"Farg'ona\", 'Namangan'].map(\n  (label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }),\n);\n\nexport default function DialogWithSelect() {\n  const [city, setCity] = useState<string | null>('toshkent');\n\n  return (\n    <Dialog>\n      <Dialog.Trigger asChild>\n        <Button variant=\"outline\">Yetkazib berish manzili</Button>\n      </Dialog.Trigger>\n      <Dialog.Content\n        title=\"Yetkazib berish manzili\"\n        description=\"Ro'yxatlar oyna ustida ochiladi.\"\n      >\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Shahar\">\n            <Combobox options={cities} value={city} onValueChange={setCity} clearable />\n          </Field>\n          <Field label=\"Yetkazish vaqti\">\n            <Select defaultValue=\"morning\">\n              <Select.Item value=\"morning\">Ertalab (9:00–12:00)</Select.Item>\n              <Select.Item value=\"day\">Kunduzi (12:00–17:00)</Select.Item>\n              <Select.Item value=\"evening\">Kechqurun (17:00–21:00)</Select.Item>\n            </Select>\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button>Bekor qilish</Button>\n          </Dialog.Close>\n          <Dialog.Close asChild>\n            <Button variant=\"primary\">Saqlash</Button>\n          </Dialog.Close>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "archive/v0.3/divider/basic": { component: Demo552, file: "archive/v0.3/divider/basic.tsx", source: "'use client';\n\nimport { Divider } from '@akhatmirzo/ui';\n\nexport default function DividerBasic() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3 text-sm text-text\">\n      <div className=\"flex justify-between\">\n        <span>Mahsulotlar</span>\n        <span>220 000 so'm</span>\n      </div>\n      <div className=\"flex justify-between text-text-muted\">\n        <span>Yetkazib berish</span>\n        <span>25 000 so'm</span>\n      </div>\n      <Divider />\n      <div className=\"flex justify-between font-semibold\">\n        <span>Jami</span>\n        <span>245 000 so'm</span>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/divider/label": { component: Demo553, file: "archive/v0.3/divider/label.tsx", source: "'use client';\n\nimport { Button, Divider } from '@akhatmirzo/ui';\n\nexport default function DividerLabel() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Button variant=\"primary\" fullWidth>\n        Telefon orqali kirish\n      </Button>\n      <Divider label=\"yoki\" />\n      <Button variant=\"outline\" fullWidth>\n        Google orqali kirish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/divider/vertical": { component: Demo554, file: "archive/v0.3/divider/vertical.tsx", source: "'use client';\n\nimport { Divider } from '@akhatmirzo/ui';\n\nexport default function DividerVertical() {\n  return (\n    <div className=\"flex h-5 items-center gap-3 text-sm font-medium text-text-subtle\">\n      <span>Bosh sahifa</span>\n      <Divider orientation=\"vertical\" decorative />\n      <span>Buyurtmalar</span>\n      <Divider orientation=\"vertical\" decorative />\n      <span>Sozlamalar</span>\n    </div>\n  );\n}\n" },
  "archive/v0.3/document-inputs/car-plate": { component: Demo555, file: "archive/v0.3/document-inputs/car-plate.tsx", source: "'use client';\n\nimport { CarPlateInput, Field, type CarPlateInputDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CarPlateDemo() {\n  const [details, setDetails] = useState<CarPlateInputDetails | null>(null);\n\n  const type =\n    details?.type === 'legal' ? 'yuridik shaxs' : details?.type ? 'jismoniy shaxs' : null;\n  const description = [details?.region?.name, type].filter(Boolean).join(' · ');\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Jismoniy shaxs\" description={description || '01 A 123 BC'}>\n        <CarPlateInput defaultValue=\"01A123BC\" onDetails={setDetails} />\n      </Field>\n      <Field label=\"Yuridik shaxs\" description=\"01 123 ABC\">\n        <CarPlateInput defaultValue=\"30123ABC\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/document-inputs/overview": { component: Demo556, file: "archive/v0.3/document-inputs/overview.tsx", source: "'use client';\n\nimport {\n  BankAccountInput,\n  CarPlateInput,\n  Field,\n  InnInput,\n  PassportInput,\n  PinflInput,\n} from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DocumentInputsOverview() {\n  const [pinfl, setPinfl] = useState('');\n  const [passport, setPassport] = useState('');\n  const [inn, setInn] = useState('');\n  const [plate, setPlate] = useState('');\n  const [account, setAccount] = useState('');\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"JShShIR\" description={`Qiymat: \"${pinfl}\"`}>\n        <PinflInput value={pinfl} onValueChange={setPinfl} />\n      </Field>\n      <Field label=\"Pasport yoki ID karta\" description={`Qiymat: \"${passport}\"`}>\n        <PassportInput value={passport} onValueChange={setPassport} />\n      </Field>\n      <Field label=\"STIR\" description={`Qiymat: \"${inn}\"`}>\n        <InnInput value={inn} onValueChange={setInn} />\n      </Field>\n      <Field label=\"Avtomobil raqami\" description={`Qiymat: \"${plate}\"`}>\n        <CarPlateInput value={plate} onValueChange={setPlate} />\n      </Field>\n      <Field label=\"Hisob raqami\" description={`Qiymat: \"${account}\"`} className=\"sm:col-span-2\">\n        <BankAccountInput value={account} onValueChange={setAccount} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/document-inputs/pinfl": { component: Demo557, file: "archive/v0.3/document-inputs/pinfl.tsx", source: "'use client';\n\nimport { Field, PinflInput, type PinflInputDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PinflDemo() {\n  const [details, setDetails] = useState<PinflInputDetails | null>(null);\n\n  const info =\n    details?.valid && details.birthDate\n      ? `${details.gender === 'male' ? 'Erkak' : 'Ayol'}, tugʻilgan: ${details.birthDate.toLocaleDateString('uz-UZ')}`\n      : undefined;\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field\n        label=\"JShShIR\"\n        description={info ?? '14 raqam — pasportdagi shaxsiy raqam'}\n        error={details && !details.valid ? 'JShShIR notoʻgʻri' : undefined}\n      >\n        <PinflInput\n          onValueChange={(_, d) => {\n            if (!d.complete) setDetails(null);\n          }}\n          onDetails={setDetails}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/document-inputs/validation": { component: Demo558, file: "archive/v0.3/document-inputs/validation.tsx", source: "'use client';\n\nimport { Field, InnInput, PassportInput } from '@akhatmirzo/ui';\n\nexport default function DocumentValidation() {\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"STIR\" description=\"0 bilan boshlanmaydi — darhol xato\">\n        <InnInput defaultValue=\"012345678\" />\n      </Field>\n      <Field label=\"Pasport\" description=\"validate={false} — tekshiruvsiz\">\n        <PassportInput defaultValue=\"AB1234567\" validate={false} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/drawer/details": { component: Demo559, file: "archive/v0.3/drawer/details.tsx", source: "'use client';\n\nimport { Button, Drawer } from '@akhatmirzo/ui';\n\nconst rows = [\n  ['Mijoz', 'Sarvar Abduxoliqov'],\n  ['Telefon', '+998 90 123 45 67'],\n  ['Manzil', 'Toshkent, Chilonzor tumani, 9-mavze'],\n  [\"To'lov\", 'Naqd, yetkazib berilganda'],\n  ['Jami', \"1 250 000 so'm\"],\n];\n\nexport default function DrawerDetails() {\n  return (\n    <Drawer>\n      <Drawer.Trigger asChild>\n        <Button>Buyurtma #1042</Button>\n      </Drawer.Trigger>\n      <Drawer.Content size=\"lg\" title=\"Buyurtma #1042\" description=\"21-oktabr, 14:32\">\n        <dl className=\"m-0 grid grid-cols-[auto_1fr] gap-x-6 gap-y-3 text-sm\">\n          {rows.map(([label, value]) => (\n            <div key={label} className=\"contents\">\n              <dt className=\"text-text-muted\">{label}</dt>\n              <dd className=\"m-0 font-medium text-text\">{value}</dd>\n            </div>\n          ))}\n        </dl>\n        <Drawer.Footer>\n          <Drawer.Close asChild>\n            <Button>Yopish</Button>\n          </Drawer.Close>\n          <Button variant=\"primary\">Yetkazildi deb belgilash</Button>\n        </Drawer.Footer>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "archive/v0.3/drawer/filters": { component: Demo560, file: "archive/v0.3/drawer/filters.tsx", source: "'use client';\n\nimport { Button, Checkbox, Drawer, Field, Input, Switch } from '@akhatmirzo/ui';\nimport { SlidersHorizontal } from 'lucide-react';\nimport { useState } from 'react';\n\nconst categories = ['Elektronika', 'Kiyim-kechak', \"Uy-ro'zg'or\", 'Kitoblar'];\n\nexport default function DrawerFilters() {\n  const [open, setOpen] = useState(false);\n  const [selected, setSelected] = useState<string[]>(['Elektronika']);\n\n  const toggle = (name: string, on: boolean) =>\n    setSelected((prev) => (on ? [...prev, name] : prev.filter((x) => x !== name)));\n\n  return (\n    <Drawer open={open} onOpenChange={setOpen}>\n      <Drawer.Trigger asChild>\n        <Button variant=\"outline\" leftIcon={<SlidersHorizontal />}>\n          Filtrlar\n        </Button>\n      </Drawer.Trigger>\n      <Drawer.Content title=\"Filtrlar\" description=\"Natijalarni toraytiring.\">\n        <div className=\"flex flex-col gap-5\">\n          <div className=\"grid grid-cols-2 gap-3\">\n            <Field label=\"Narxdan\">\n              <Input inputMode=\"numeric\" placeholder=\"0\" suffix=\"so'm\" />\n            </Field>\n            <Field label=\"Narxgacha\">\n              <Input inputMode=\"numeric\" placeholder=\"1 000 000\" suffix=\"so'm\" />\n            </Field>\n          </div>\n          <div className=\"flex flex-col gap-3\">\n            {categories.map((c) => (\n              <Checkbox\n                key={c}\n                label={c}\n                checked={selected.includes(c)}\n                onCheckedChange={(on) => toggle(c, on)}\n              />\n            ))}\n          </div>\n          <Switch label=\"Faqat mavjudlari\" defaultChecked />\n        </div>\n        <Drawer.Footer>\n          <Button onClick={() => setSelected([])}>Tozalash</Button>\n          <Button variant=\"primary\" onClick={() => setOpen(false)}>\n            Qo'llash\n          </Button>\n        </Drawer.Footer>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "archive/v0.3/drawer/mobile-menu": { component: Demo561, file: "archive/v0.3/drawer/mobile-menu.tsx", source: "'use client';\n\nimport { Button, Drawer } from '@akhatmirzo/ui';\nimport { Menu } from 'lucide-react';\nimport { useState } from 'react';\n\nconst items = ['Bosh sahifa', 'Buyurtmalar', 'Mahsulotlar', 'Mijozlar', 'Hisobotlar'];\n\nexport default function DrawerMobileMenu() {\n  const [active, setActive] = useState('Buyurtmalar');\n\n  return (\n    <Drawer>\n      <Drawer.Trigger asChild>\n        <Button variant=\"ghost\" leftIcon={<Menu />}>\n          Menyu\n        </Button>\n      </Drawer.Trigger>\n      <Drawer.Content\n        side=\"left\"\n        size=\"sm\"\n        title=\"Menyu\"\n        hideTitle\n        labels={{ close: 'Menyuni yopish' }}\n      >\n        <nav aria-label=\"Asosiy menyu\" className=\"-mx-2 flex flex-col gap-1\">\n          {items.map((item) => (\n            <Drawer.Close asChild key={item}>\n              <button\n                type=\"button\"\n                aria-current={item === active ? 'page' : undefined}\n                onClick={() => setActive(item)}\n                className=\"focus-ring flex h-10 cursor-pointer items-center rounded-lg border-0 bg-transparent px-3 text-left text-sm font-medium text-text hover:bg-surface-muted aria-[current=page]:bg-primary-soft aria-[current=page]:text-primary-soft-foreground\"\n              >\n                {item}\n              </button>\n            </Drawer.Close>\n          ))}\n        </nav>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "archive/v0.3/drawer/sides": { component: Demo562, file: "archive/v0.3/drawer/sides.tsx", source: "'use client';\n\nimport { Button, Drawer, type DrawerSide } from '@akhatmirzo/ui';\n\nconst sides: { side: DrawerSide; label: string }[] = [\n  { side: 'right', label: \"O'ngdan\" },\n  { side: 'left', label: 'Chapdan' },\n  { side: 'bottom', label: 'Pastdan' },\n  { side: 'top', label: 'Tepadan' },\n];\n\nexport default function DrawerSides() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sides.map(({ side, label }) => (\n        <Drawer key={side}>\n          <Drawer.Trigger asChild>\n            <Button variant=\"outline\">{label}</Button>\n          </Drawer.Trigger>\n          <Drawer.Content side={side} title={label} description={`side=\"${side}\"`}>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Panel ekran chetidan siljib chiqadi. Pastdan chiqqanda tepada tutqich chizig'i bor.\n            </p>\n            <Drawer.Footer>\n              <Drawer.Close asChild>\n                <Button variant=\"primary\">Yopish</Button>\n              </Drawer.Close>\n            </Drawer.Footer>\n          </Drawer.Content>\n        </Drawer>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/drawer/sizes": { component: Demo563, file: "archive/v0.3/drawer/sizes.tsx", source: "'use client';\n\nimport { Button, Drawer, type DrawerSize } from '@akhatmirzo/ui';\n\nconst sizes: { size: DrawerSize; px: string }[] = [\n  { size: 'sm', px: '320px' },\n  { size: 'md', px: '420px' },\n  { size: 'lg', px: '560px' },\n];\n\nexport default function DrawerSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sizes.map(({ size, px }) => (\n        <Drawer key={size}>\n          <Drawer.Trigger asChild>\n            <Button variant=\"outline\">\n              {size} — {px}\n            </Button>\n          </Drawer.Trigger>\n          <Drawer.Content size={size} title={`O'lcham: ${size}`} description={`Kenglik ${px}`}>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Chap va o'ngda o'lcham kenglikni, past va tepada balandlikni belgilaydi.\n            </p>\n          </Drawer.Content>\n        </Drawer>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/dropdown-menu/basic": { component: Demo564, file: "archive/v0.3/dropdown-menu/basic.tsx", source: "'use client';\n\nimport { Button, DropdownMenu, toast } from '@akhatmirzo/ui';\nimport { Archive, ChevronDown, Copy, Pencil, Trash2 } from 'lucide-react';\n\nexport default function DropdownMenuBasic() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <Button variant=\"outline\" rightIcon={<ChevronDown />}>\n          Amallar\n        </Button>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content>\n        <DropdownMenu.Item\n          icon={<Pencil />}\n          shortcut={['mod', 'E']}\n          onSelect={() => toast('Tahrirlash')}\n        >\n          Tahrirlash\n        </DropdownMenu.Item>\n        <DropdownMenu.Item\n          icon={<Copy />}\n          shortcut={['mod', 'D']}\n          onSelect={() => toast('Nusxa olindi')}\n        >\n          Nusxa olish\n        </DropdownMenu.Item>\n        <DropdownMenu.Item icon={<Archive />} onSelect={() => toast('Arxivlandi')}>\n          Arxivlash\n        </DropdownMenu.Item>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\" onSelect={() => toast(\"O'chirildi\")}>\n          O'chirish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "archive/v0.3/dropdown-menu/checkbox-radio": { component: Demo565, file: "archive/v0.3/dropdown-menu/checkbox-radio.tsx", source: "'use client';\n\nimport { DropdownMenu } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DropdownMenuCheckboxRadio() {\n  const [columns, setColumns] = useState({ price: true, stock: true, sku: false });\n  const [sort, setSort] = useState('new');\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <DropdownMenu>\n        <DropdownMenu.Trigger>Ustunlar</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Label>Jadvalda ko'rsatish</DropdownMenu.Label>\n          {(\n            [\n              ['price', 'Narx'],\n              ['stock', 'Ombordagi soni'],\n              ['sku', 'Artikul'],\n            ] as const\n          ).map(([key, label]) => (\n            <DropdownMenu.CheckboxItem\n              key={key}\n              checked={columns[key]}\n              onCheckedChange={(on) => setColumns((c) => ({ ...c, [key]: on }))}\n              // Menyu yopilmasin — bir nechtasini ketma-ket belgilash uchun\n              onSelect={(e) => e.preventDefault()}\n            >\n              {label}\n            </DropdownMenu.CheckboxItem>\n          ))}\n        </DropdownMenu.Content>\n      </DropdownMenu>\n\n      <DropdownMenu>\n        <DropdownMenu.Trigger>Saralash</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Label>Tartib</DropdownMenu.Label>\n          <DropdownMenu.RadioGroup value={sort} onValueChange={setSort}>\n            <DropdownMenu.RadioItem value=\"new\">Avval yangilari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"cheap\">Avval arzonlari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"expensive\">Avval qimmatlari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"popular\" disabled>\n              Ommabop (tez orada)\n            </DropdownMenu.RadioItem>\n          </DropdownMenu.RadioGroup>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n      <span className=\"text-sm text-text-muted\">Saralash: {sort}</span>\n    </div>\n  );\n}\n" },
  "archive/v0.3/dropdown-menu/profile": { component: Demo566, file: "archive/v0.3/dropdown-menu/profile.tsx", source: "'use client';\n\nimport { Button, DropdownMenu } from '@akhatmirzo/ui';\nimport { LogOut, Send, Settings, User } from 'lucide-react';\n\nexport default function DropdownMenuProfile() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <Button variant=\"ghost\" leftIcon={<User />}>\n          Akmal Karimov\n        </Button>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content align=\"end\" className=\"w-56\">\n        <DropdownMenu.Label>akmal@misol.uz</DropdownMenu.Label>\n        <DropdownMenu.Group>\n          <DropdownMenu.Item icon={<User />} shortcut={['mod', 'P']}>\n            Profil\n          </DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Settings />} shortcut={['mod', ',']}>\n            Sozlamalar\n          </DropdownMenu.Item>\n          <DropdownMenu.Item asChild icon={<Send />}>\n            <a href=\"https://github.com/Akhatmirzo/akhatmirzo-toolkit\">Loyiha GitHub'da</a>\n          </DropdownMenu.Item>\n        </DropdownMenu.Group>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<LogOut />} variant=\"danger\">\n          Chiqish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "archive/v0.3/dropdown-menu/states": { component: Demo567, file: "archive/v0.3/dropdown-menu/states.tsx", source: "'use client';\n\nimport { Button, DropdownMenu } from '@akhatmirzo/ui';\nimport { Copy, Pencil, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function DropdownMenuStates() {\n  const [open, setOpen] = useState(false);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <DropdownMenu>\n        <DropdownMenu.Trigger>O'chirilgan elementlar</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Item icon={<Pencil />}>Tahrirlash</DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Copy />} disabled>\n            Nusxa olish (ruxsat yo'q)\n          </DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\" disabled>\n            O'chirish (ruxsat yo'q)\n          </DropdownMenu.Item>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n\n      <DropdownMenu open={open} onOpenChange={setOpen}>\n        <DropdownMenu.Trigger>Boshqariladigan</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Item>Birinchi</DropdownMenu.Item>\n          <DropdownMenu.Item>Ikkinchi</DropdownMenu.Item>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n      <Button variant=\"ghost\" onClick={() => setOpen(true)}>\n        Tashqaridan ochish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/dropdown-menu/submenu": { component: Demo568, file: "archive/v0.3/dropdown-menu/submenu.tsx", source: "'use client';\n\nimport { DropdownMenu, IconButton } from '@akhatmirzo/ui';\nimport { Archive, Ellipsis, Pencil, Share2, Trash2 } from 'lucide-react';\n\nexport default function DropdownMenuSubmenu() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <IconButton variant=\"outline\" aria-label=\"Ko'proq amallar\">\n          <Ellipsis />\n        </IconButton>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content>\n        <DropdownMenu.Item icon={<Pencil />}>Nomini o'zgartirish</DropdownMenu.Item>\n        <DropdownMenu.Sub>\n          <DropdownMenu.SubTrigger icon={<Share2 />}>Ulashish</DropdownMenu.SubTrigger>\n          <DropdownMenu.SubContent>\n            <DropdownMenu.Item>Telegram</DropdownMenu.Item>\n            <DropdownMenu.Item>Email orqali</DropdownMenu.Item>\n            <DropdownMenu.Item shortcut={['mod', 'L']}>Havolani nusxalash</DropdownMenu.Item>\n          </DropdownMenu.SubContent>\n        </DropdownMenu.Sub>\n        <DropdownMenu.Sub>\n          <DropdownMenu.SubTrigger icon={<Archive />}>Ko'chirish</DropdownMenu.SubTrigger>\n          <DropdownMenu.SubContent>\n            <DropdownMenu.Item>Kiruvchi</DropdownMenu.Item>\n            <DropdownMenu.Item>Arxiv</DropdownMenu.Item>\n          </DropdownMenu.SubContent>\n        </DropdownMenu.Sub>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\">\n          O'chirish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "archive/v0.3/empty-state/basic": { component: Demo569, file: "archive/v0.3/empty-state/basic.tsx", source: "'use client';\n\nimport { Button, EmptyState } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\n\nexport default function EmptyStateBasic() {\n  return (\n    <EmptyState\n      icon={<Inbox />}\n      title=\"Buyurtmalar hali yo'q\"\n      description=\"Birinchi buyurtma kelganda shu yerda ko'rinadi.\"\n      action={\n        <Button variant=\"primary\" leftIcon={<Plus />}>\n          Mahsulot qo'shish\n        </Button>\n      }\n      secondaryAction={<Button variant=\"ghost\">Qo'llanma</Button>}\n    />\n  );\n}\n" },
  "archive/v0.3/empty-state/data-table": { component: Demo570, file: "archive/v0.3/empty-state/data-table.tsx", source: "'use client';\n\nimport { Button, DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: string;\n}\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№' },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa' },\n];\n\nconst orders: Order[] = [];\n\nexport default function EmptyStateDataTable() {\n  return (\n    <DataTable\n      className=\"w-full\"\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      empty={{\n        icon: <Inbox />,\n        title: \"Buyurtmalar hali yo'q\",\n        description: \"Birinchi buyurtma kelganda shu yerda ko'rinadi.\",\n        action: (\n          <Button size=\"sm\" variant=\"primary\" leftIcon={<Plus />}>\n            Buyurtma qo'shish\n          </Button>\n        ),\n      }}\n    />\n  );\n}\n" },
  "archive/v0.3/empty-state/search": { component: Demo571, file: "archive/v0.3/empty-state/search.tsx", source: "'use client';\n\nimport { Button, EmptyState, Input } from '@akhatmirzo/ui';\nimport { SearchX } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function EmptyStateSearch() {\n  const [query, setQuery] = useState('Namangan');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Input\n        aria-label=\"Shahar qidirish\"\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Shahar nomi\"\n      />\n      <EmptyState\n        size=\"sm\"\n        bordered\n        icon={<SearchX />}\n        title=\"Hech narsa topilmadi\"\n        description={`\"${query}\" bo'yicha natija yo'q. So'zni o'zgartirib ko'ring.`}\n        action={\n          <Button size=\"sm\" onClick={() => setQuery('')}>\n            Qidiruvni tozalash\n          </Button>\n        }\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/empty-state/sizes": { component: Demo572, file: "archive/v0.3/empty-state/sizes.tsx", source: "'use client';\n\nimport { EmptyState } from '@akhatmirzo/ui';\nimport { FolderOpen } from 'lucide-react';\n\nexport default function EmptyStateSizes() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <EmptyState bordered size=\"sm\" icon={<FolderOpen />} title=\"Kichik\" description=\"sm\" />\n      <EmptyState bordered size=\"md\" icon={<FolderOpen />} title=\"O'rta\" description=\"md\" />\n      <EmptyState bordered size=\"lg\" icon={<FolderOpen />} title=\"Katta\" description=\"lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/field/basic": { component: Demo573, file: "archive/v0.3/field/basic.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function FieldBasic() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" required description=\"Tasdiqlash kodi SMS orqali yuboriladi\">\n        <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" />\n      </Field>\n      <Field label=\"Email\" error=\"Email manzil noto'g'ri\">\n        <Input type=\"email\" defaultValue=\"sarvar@mail\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/field/custom-control": { component: Demo574, file: "archive/v0.3/field/custom-control.tsx", source: "'use client';\n\nimport { Field, useFieldControl } from '@akhatmirzo/ui';\n\nfunction CitySelect() {\n  const { controlProps, invalid, disabled } = useFieldControl();\n  return (\n    <select\n      {...controlProps}\n      disabled={disabled}\n      data-invalid={invalid ? '' : undefined}\n      className=\"h-10 rounded-lg border border-border bg-surface px-3 text-sm text-text data-invalid:border-danger\"\n    >\n      <option value=\"\">Tanlang</option>\n      <option>Toshkent</option>\n      <option>Samarqand</option>\n      <option>Buxoro</option>\n    </select>\n  );\n}\n\nexport default function FieldCustomControl() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Shahar\" required error=\"Shaharni tanlang\">\n        <CitySelect />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/field/disabled": { component: Demo575, file: "archive/v0.3/field/disabled.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function FieldDisabled() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Hudud\" description=\"Hudud administrator tomonidan belgilanadi\" disabled>\n        <Input defaultValue=\"Toshkent shahri\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/field/horizontal": { component: Demo576, file: "archive/v0.3/field/horizontal.tsx", source: "'use client';\n\nimport { Field, Input, Textarea } from '@akhatmirzo/ui';\n\nexport default function FieldHorizontal() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-4\">\n      <Field orientation=\"horizontal\" label=\"Do'kon nomi\" description=\"Chekda ko'rinadi\">\n        <Input defaultValue=\"Bahor Market\" />\n      </Field>\n      <Field orientation=\"horizontal\" label=\"Manzil\">\n        <Textarea minRows={2} defaultValue=\"Toshkent, Chilonzor tumani, 9-kvartal\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/field/validation": { component: Demo577, file: "archive/v0.3/field/validation.tsx", source: "'use client';\n\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function FieldValidation() {\n  const [name, setName] = useState('');\n  const [submitted, setSubmitted] = useState(false);\n  const error = submitted && name.trim().length < 3 ? 'Kamida 3 ta harf kiriting' : undefined;\n\n  const submit = (event: FormEvent) => {\n    event.preventDefault();\n    setSubmitted(true);\n  };\n\n  return (\n    <form onSubmit={submit} noValidate className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"To'liq ism\" required error={error}>\n        <Input\n          value={name}\n          onChange={(e) => setName(e.target.value)}\n          placeholder=\"Sarvar Abduxoliqov\"\n          autoComplete=\"name\"\n        />\n      </Field>\n      <Button type=\"submit\" variant=\"primary\">\n        Davom etish\n      </Button>\n    </form>\n  );\n}\n" },
  "archive/v0.3/file-upload/basic": { component: Demo578, file: "archive/v0.3/file-upload/basic.tsx", source: "'use client';\n\nimport { Field, FileUpload, type FileUploadContext, type FileUploadItem } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst MB = 1024 * 1024;\n\n/** Soxta yuklash: progress bilan ~2 soniya. Nomida \"xato\" bo'lsa — tarmoq xatosi */\nfunction fakeUpload(file: File, { onProgress, signal }: FileUploadContext) {\n  return new Promise<{ url: string }>((resolve, reject) => {\n    let progress = 0;\n    const timer = setInterval(() => {\n      progress = Math.min(100, progress + 8);\n      onProgress(progress);\n      if (file.name.includes('xato') && progress > 50) {\n        clearInterval(timer);\n        reject(new Error('network'));\n      } else if (progress === 100) {\n        clearInterval(timer);\n        resolve({ url: `/uploads/${encodeURIComponent(file.name)}` });\n      }\n    }, 150);\n    signal.addEventListener('abort', () => clearInterval(timer));\n  });\n}\n\nexport default function FileUploadBasic() {\n  const [files, setFiles] = useState<FileUploadItem[]>([]);\n  const done = files.filter((f) => f.status === 'done').length;\n\n  return (\n    <div className=\"flex w-full max-w-lg flex-col gap-2\">\n      <Field label=\"Hujjatlar\">\n        <FileUpload\n          accept={['image/*', '.pdf']}\n          maxSize={5 * MB}\n          maxFiles={5}\n          multiple\n          upload={fakeUpload}\n          onFilesChange={setFiles}\n        />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Jami: {files.length} · yuklandi: {done}\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/file-upload/button": { component: Demo579, file: "archive/v0.3/file-upload/button.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadButton() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Pasport nusxasi\" description=\"Old va orqa tomoni\">\n        <FileUpload\n          variant=\"button\"\n          accept={['image/*', '.pdf']}\n          maxSize={5 * 1024 * 1024}\n          maxFiles={2}\n          multiple\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/file-upload/form": { component: Demo580, file: "archive/v0.3/file-upload/form.tsx", source: "'use client';\n\nimport { formatFileSize } from '@akhatmirzo/core';\nimport { Button, Field, FileUpload } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function FileUploadForm() {\n  const [sent, setSent] = useState<string | null>(null);\n\n  const onSubmit = (e: FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    const files = (new FormData(e.currentTarget).getAll('rezyume') as File[]).filter(\n      (f) => f.size > 0,\n    );\n    setSent(files.map((f) => `${f.name} (${formatFileSize(f.size)})`).join(', ') || \"Fayl yo'q\");\n  };\n\n  return (\n    <form onSubmit={onSubmit} className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Rezyume\" description=\"PDF yoki DOCX, 2 MB gacha\">\n        <FileUpload\n          variant=\"button\"\n          name=\"rezyume\"\n          accept={['.pdf', '.docx']}\n          maxSize={2 * 1024 * 1024}\n        />\n      </Field>\n      <div className=\"flex items-center gap-3\">\n        <Button type=\"submit\" variant=\"primary\" size=\"sm\">\n          Yuborish\n        </Button>\n        {sent && <span className=\"text-sm text-text-muted\">{sent}</span>}\n      </div>\n    </form>\n  );\n}\n" },
  "archive/v0.3/file-upload/paste": { component: Demo581, file: "archive/v0.3/file-upload/paste.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadPaste() {\n  return (\n    <div className=\"w-full max-w-lg\">\n      <Field\n        label=\"Skrinshot\"\n        description=\"Rasmni nusxalang va sahifaning istalgan joyida Ctrl+V bosing\"\n      >\n        <FileUpload accept={['image/*']} multiple maxFiles={3} paste=\"global\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/file-upload/states": { component: Demo582, file: "archive/v0.3/file-upload/states.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadStates() {\n  return (\n    <div className=\"grid w-full gap-4 md:grid-cols-2\">\n      <Field label=\"Faqat rasm\" description=\"Bitta fayl — yangisi eskisini almashtiradi\">\n        <FileUpload accept={['image/png', 'image/jpeg']} maxSize={1024 * 1024} />\n      </Field>\n      <Field label=\"Shartnoma\" error=\"Kamida bitta hujjat yuklang\" required>\n        <FileUpload accept={['.pdf']} />\n      </Field>\n      <Field label=\"O'chirilgan\" disabled>\n        <FileUpload />\n      </Field>\n      <Field label=\"O'z cheklov matni bilan\">\n        <FileUpload hint=\"Excel yoki CSV · 10 MB gacha\" accept={['.xlsx', '.csv']} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/async": { component: Demo583, file: "archive/v0.3/hooks/async.tsx", source: "'use client';\n\nimport { useAsync, useToggle } from '@akhatmirzo/hooks';\nimport { Badge, Button, Switch } from '@akhatmirzo/ui';\n\nconst CITIES = ['Toshkent', 'Samarqand', 'Buxoro', 'Xiva', 'Namangan', 'Andijon', 'Nukus'];\nconst STATUS_COLOR = {\n  idle: 'neutral',\n  loading: 'info',\n  success: 'success',\n  error: 'danger',\n} as const;\n\nfunction fetchCities(fail: boolean): Promise<string[]> {\n  const delay = 500 + Math.random() * 1000;\n  return new Promise((resolve, reject) =>\n    setTimeout(() => {\n      if (fail) reject(new Error('Server javob bermadi'));\n      else resolve(CITIES.slice(0, 2 + Math.floor(Math.random() * 5)));\n    }, delay),\n  );\n}\n\nexport default function HooksAsync() {\n  const [fail, , setFail] = useToggle(false);\n  const { status, data, error, run } = useAsync(fetchCities, [], { immediate: false });\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Button onClick={() => void run(fail)} loading={status === 'loading'}>\n          Yuklash\n        </Button>\n        <Badge color={STATUS_COLOR[status]} dot>\n          {status}\n        </Badge>\n      </div>\n      <Switch checked={fail} onCheckedChange={setFail} label=\"Xato bilan tugasin\" />\n      {status === 'error' && error instanceof Error && (\n        <p className=\"text-sm text-danger-soft-foreground\">{error.message}</p>\n      )}\n      {data && <p className=\"text-sm text-text\">{data.join(', ')}</p>}\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/click-outside": { component: Demo584, file: "archive/v0.3/hooks/click-outside.tsx", source: "'use client';\n\nimport { useClickOutside, useHotkeys, useToggle } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useRef } from 'react';\n\nexport default function HooksClickOutside() {\n  const [open, toggle, setOpen] = useToggle(false);\n  const triggerRef = useRef<HTMLButtonElement>(null);\n  const panelRef = useRef<HTMLDivElement>(null);\n\n  useClickOutside([triggerRef, panelRef], () => setOpen(false), open);\n  useHotkeys('esc', () => setOpen(false), { enabled: open });\n\n  return (\n    <div className=\"relative flex flex-col items-center gap-2\">\n      <Button ref={triggerRef} variant=\"outline\" onClick={toggle} aria-expanded={open}>\n        Filtrlar\n      </Button>\n      {open && (\n        <div\n          ref={panelRef}\n          className=\"w-64 rounded-xl border border-border bg-surface-raised p-4 text-sm text-text shadow-lg\"\n        >\n          Panel tashqarisiga bosing yoki <kbd className=\"font-mono\">Esc</kbd> ni bosing — yopiladi.\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/controllable-state": { component: Demo585, file: "archive/v0.3/hooks/controllable-state.tsx", source: "'use client';\n\nimport { useControllableState } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\ninterface StepperProps {\n  value?: number;\n  defaultValue?: number;\n  onValueChange?: (value: number) => void;\n}\n\nfunction Stepper({ value, defaultValue = 0, onValueChange }: StepperProps) {\n  const [count, setCount] = useControllableState({ value, defaultValue, onChange: onValueChange });\n  return (\n    <div className=\"flex items-center gap-2\">\n      <Button size=\"sm\" variant=\"outline\" onClick={() => setCount((n) => n - 1)}>\n        −\n      </Button>\n      <span className=\"min-w-8 text-center font-semibold text-text tabular-nums\">{count}</span>\n      <Button size=\"sm\" variant=\"outline\" onClick={() => setCount((n) => n + 1)}>\n        +\n      </Button>\n    </div>\n  );\n}\n\nexport default function HooksControllableState() {\n  const [value, setValue] = useState(10);\n\n  return (\n    <div className=\"grid w-full max-w-md gap-6 sm:grid-cols-2\">\n      <div className=\"flex flex-col gap-2\">\n        <p className=\"text-xs font-medium text-text-muted\">Boshqarilmaydigan (defaultValue=3)</p>\n        <Stepper defaultValue={3} />\n      </div>\n      <div className=\"flex flex-col gap-2\">\n        <p className=\"text-xs font-medium text-text-muted\">Boshqariladigan (0…20)</p>\n        <Stepper value={value} onValueChange={(v) => setValue(Math.min(20, Math.max(0, v)))} />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/copy": { component: Demo586, file: "archive/v0.3/hooks/copy.tsx", source: "'use client';\n\nimport { useCopyToClipboard } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { Check, Copy } from 'lucide-react';\n\nexport default function HooksCopy() {\n  const { copied, copy } = useCopyToClipboard();\n  const command = 'pnpm add @akhatmirzo/hooks';\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <code className=\"rounded-lg border border-border bg-surface-muted px-3 py-2 font-mono text-sm text-text\">\n        {command}\n      </code>\n      <Button\n        variant={copied ? 'soft' : 'outline'}\n        leftIcon={copied ? <Check /> : <Copy />}\n        onClick={() => void copy(command)}\n      >\n        {copied ? 'Nusxalandi' : 'Nusxa olish'}\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/debounce": { component: Demo587, file: "archive/v0.3/hooks/debounce.tsx", source: "'use client';\n\nimport { useDebounce } from '@akhatmirzo/hooks';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CITIES = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Xiva',\n  'Namangan',\n  'Andijon',\n  'Nukus',\n  'Termiz',\n];\n\nexport default function HooksDebounce() {\n  const [query, setQuery] = useState('');\n  const debounced = useDebounce(query, 400);\n  const results = CITIES.filter((c) => c.toLowerCase().includes(debounced.trim().toLowerCase()));\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Shahar qidirish\" description=\"Natija yozishni to'xtatganingizdan 400 ms keyin\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <Badge color={query === debounced ? 'success' : 'warning'} dot className=\"self-start\">\n        {query === debounced ? 'Yangilangan' : 'Kutilmoqda…'}\n      </Badge>\n      <div className=\"flex flex-wrap gap-2\">\n        {results.map((city) => (\n          <Badge key={city} variant=\"outline\">\n            {city}\n          </Badge>\n        ))}\n        {results.length === 0 && (\n          <span className=\"text-sm text-text-muted\">Hech narsa topilmadi</span>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/debounced-callback": { component: Demo588, file: "archive/v0.3/hooks/debounced-callback.tsx", source: "'use client';\n\nimport { useDebouncedCallback } from '@akhatmirzo/hooks';\nimport { Button, Field, Textarea } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksDebouncedCallback() {\n  const [text, setText] = useState('');\n  const [saved, setSaved] = useState<string[]>([]);\n\n  const save = useDebouncedCallback((value: string) => {\n    setSaved((list) => [`${value.length} belgi saqlandi`, ...list].slice(0, 3));\n  }, 800);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Izoh\" description=\"Avtomatik saqlash: yozishni to'xtatgach 800 ms o'tib\">\n        <Textarea\n          value={text}\n          onChange={(e) => {\n            setText(e.target.value);\n            save(e.target.value);\n          }}\n          minRows={3}\n        />\n      </Field>\n      <Button size=\"sm\" variant=\"outline\" className=\"self-start\" onClick={save.flush}>\n        Hozir saqlash\n      </Button>\n      <ul className=\"text-sm text-text-muted\">\n        {saved.map((line, i) => (\n          <li key={i}>{line}</li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/hotkeys": { component: Demo589, file: "archive/v0.3/hooks/hotkeys.tsx", source: "'use client';\n\nimport { useHotkeys } from '@akhatmirzo/hooks';\nimport { Badge, Kbd } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksHotkeys() {\n  const [last, setLast] = useState<string | null>(null);\n  const [count, setCount] = useState(0);\n\n  const hit = (name: string) => {\n    setLast(name);\n    setCount((n) => n + 1);\n  };\n\n  useHotkeys('alt+k', () => hit('alt+k'));\n  useHotkeys('?', () => hit('?'));\n  // Bir nechta kombinatsiya — vergul bilan\n  useHotkeys('g, alt+g', () => hit('g'));\n\n  return (\n    <div className=\"flex flex-col items-center gap-3 text-sm text-text\">\n      <div className=\"flex flex-wrap items-center justify-center gap-3\">\n        <Kbd keys={['Alt', 'K']} />\n        <Kbd>?</Kbd>\n        <Kbd>G</Kbd>\n      </div>\n      <p className=\"text-text-muted\">Yuqoridagi tugmalardan birini bosing</p>\n      {last && (\n        <Badge color=\"primary\">\n          {last} · {count} marta\n        </Badge>\n      )}\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/intersection": { component: Demo590, file: "archive/v0.3/hooks/intersection.tsx", source: "'use client';\n\nimport { useIntersection } from '@akhatmirzo/hooks';\nimport { Spinner } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\nconst MAX = 60;\n\nexport default function HooksIntersection() {\n  const [count, setCount] = useState(12);\n  const done = count >= MAX;\n  const [sentinelRef, entry] = useIntersection<HTMLDivElement>({\n    rootMargin: '40px',\n    enabled: !done,\n  });\n  const visible = entry?.isIntersecting ?? false;\n\n  useEffect(() => {\n    if (!visible || done) return;\n    // Haqiqiy ilovada — keyingi sahifani serverdan yuklash\n    const timer = setTimeout(() => setCount((n) => Math.min(MAX, n + 12)), 500);\n    return () => clearTimeout(timer);\n  }, [visible, done, count]);\n\n  return (\n    <div className=\"h-64 w-full max-w-sm overflow-auto rounded-xl border border-border bg-surface\">\n      <ul className=\"divide-y divide-border text-sm text-text\">\n        {Array.from({ length: count }, (_, i) => (\n          <li key={i} className=\"px-4 py-2\">\n            Buyurtma #{1000 + i}\n          </li>\n        ))}\n      </ul>\n      <div\n        ref={sentinelRef}\n        className=\"flex items-center justify-center gap-2 p-3 text-sm text-text-muted\"\n      >\n        {done ? (\n          'Hammasi yuklandi'\n        ) : (\n          <>\n            <Spinner size=\"sm\" /> Yuklanmoqda…\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/local-storage": { component: Demo591, file: "archive/v0.3/hooks/local-storage.tsx", source: "'use client';\n\nimport { useLocalStorage } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\n\nfunction Mirror() {\n  const [count] = useLocalStorage('docs-demo:counter', 0);\n  return (\n    <p className=\"text-sm text-text-muted\">\n      Boshqa komponent ko'rayotgan qiymat: <strong className=\"text-text\">{count}</strong>\n    </p>\n  );\n}\n\nexport default function HooksLocalStorage() {\n  const [count, setCount, remove] = useLocalStorage('docs-demo:counter', 0);\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <div className=\"flex items-center gap-2\">\n        <Button variant=\"outline\" onClick={() => setCount((n) => n - 1)}>\n          −\n        </Button>\n        <span className=\"min-w-12 text-center text-2xl font-semibold text-text tabular-nums\">\n          {count}\n        </span>\n        <Button variant=\"outline\" onClick={() => setCount((n) => n + 1)}>\n          +\n        </Button>\n        <Button variant=\"ghost\" onClick={remove}>\n          O'chirish\n        </Button>\n      </div>\n      <Mirror />\n      <p className=\"text-xs text-text-faint\">\n        Sahifani boshqa tabda oching — qiymat sinxron o'zgaradi\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/media-query": { component: Demo592, file: "archive/v0.3/hooks/media-query.tsx", source: "'use client';\n\nimport { useMediaQuery } from '@akhatmirzo/hooks';\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function HooksMediaQuery() {\n  const queries = [\n    { label: '≥ 640px', on: useMediaQuery('(min-width: 640px)') },\n    { label: '≥ 1024px', on: useMediaQuery('(min-width: 1024px)') },\n    { label: \"Tizim: qorong'i mavzu\", on: useMediaQuery('(prefers-color-scheme: dark)') },\n    { label: 'Kam animatsiya', on: useMediaQuery('(prefers-reduced-motion: reduce)') },\n    { label: 'Sichqoncha (hover)', on: useMediaQuery('(hover: hover)') },\n  ];\n\n  return (\n    <div className=\"flex flex-wrap justify-center gap-2\">\n      {queries.map(({ label, on }) => (\n        <Badge key={label} color={on ? 'success' : 'neutral'} variant={on ? 'soft' : 'outline'} dot>\n          {label}\n        </Badge>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/pagination": { component: Demo593, file: "archive/v0.3/hooks/pagination.tsx", source: "'use client';\n\nimport { usePagination } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksPagination() {\n  const [page, setPage] = useState(5);\n  const { pages, hasPrev, hasNext, from, to } = usePagination({ total: 200, pageSize: 10, page });\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <nav aria-label=\"Sahifalar\" className=\"flex flex-wrap items-center justify-center gap-1\">\n        <Button size=\"sm\" variant=\"ghost\" disabled={!hasPrev} onClick={() => setPage(page - 1)}>\n          Oldingi\n        </Button>\n        {pages.map((p, i) =>\n          p === 'ellipsis' ? (\n            <span key={`e${i}`} className=\"px-2 text-text-muted\">\n              …\n            </span>\n          ) : (\n            <Button\n              key={p}\n              size=\"sm\"\n              variant={p === page ? 'primary' : 'ghost'}\n              aria-current={p === page ? 'page' : undefined}\n              onClick={() => setPage(p)}\n            >\n              {p}\n            </Button>\n          ),\n        )}\n        <Button size=\"sm\" variant=\"ghost\" disabled={!hasNext} onClick={() => setPage(page + 1)}>\n          Keyingi\n        </Button>\n      </nav>\n      <p className=\"text-sm text-text-muted\">\n        {from}–{to} / 200 ta yozuv\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/hooks/toggle": { component: Demo594, file: "archive/v0.3/hooks/toggle.tsx", source: "'use client';\n\nimport { useToggle } from '@akhatmirzo/hooks';\nimport { Button, Switch } from '@akhatmirzo/ui';\n\nexport default function HooksToggle() {\n  const [notify, toggleNotify, setNotify] = useToggle(true);\n\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Switch\n        checked={notify}\n        onCheckedChange={setNotify}\n        label=\"SMS xabarnomalar\"\n        description={notify ? 'Yoqilgan' : \"O'chirilgan\"}\n      />\n      <div className=\"flex flex-wrap gap-2\">\n        <Button variant=\"outline\" onClick={toggleNotify}>\n          Almashtirish\n        </Button>\n        <Button variant=\"ghost\" onClick={() => setNotify(false)}>\n          O'chirish\n        </Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/icon-button/as-child": { component: Demo595, file: "archive/v0.3/icon-button/as-child.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Settings } from 'lucide-react';\n\nexport default function IconButtonAsChild() {\n  return (\n    <IconButton asChild variant=\"outline\" aria-label=\"Sozlamalar\">\n      <a href=\"#props\">\n        <Settings />\n      </a>\n    </IconButton>\n  );\n}\n" },
  "archive/v0.3/icon-button/sizes": { component: Demo596, file: "archive/v0.3/icon-button/sizes.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { X } from 'lucide-react';\n\nexport default function IconButtonSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton variant=\"outline\" size=\"sm\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n      <IconButton variant=\"outline\" size=\"md\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n      <IconButton variant=\"outline\" size=\"lg\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.3/icon-button/states": { component: Demo597, file: "archive/v0.3/icon-button/states.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Download, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function IconButtonStates() {\n  const [loading, setLoading] = useState(false);\n\n  const download = () => {\n    setLoading(true);\n    setTimeout(() => setLoading(false), 1500);\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton\n        variant=\"primary\"\n        loading={loading}\n        onClick={download}\n        aria-label=\"Hisobotni yuklab olish\"\n        labels={{ loading: 'Yuklab olinmoqda' }}\n      >\n        <Download />\n      </IconButton>\n      <IconButton variant=\"danger\" disabled aria-label=\"O'chirish\">\n        <Trash2 />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.3/icon-button/toolbar": { component: Demo598, file: "archive/v0.3/icon-button/toolbar.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Bold, Italic, Plus, Underline } from 'lucide-react';\n\nexport default function IconButtonToolbar() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <div\n        role=\"toolbar\"\n        aria-label=\"Matn formati\"\n        className=\"flex items-center gap-1 rounded-lg border border-border bg-surface p-1\"\n      >\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Qalin\">\n          <Bold />\n        </IconButton>\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Kursiv\">\n          <Italic />\n        </IconButton>\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Tagiga chizilgan\">\n          <Underline />\n        </IconButton>\n      </div>\n      <IconButton variant=\"primary\" size=\"lg\" className=\"rounded-full\" aria-label=\"Yangi buyurtma\">\n        <Plus />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.3/icon-button/variants": { component: Demo599, file: "archive/v0.3/icon-button/variants.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Heart, Pencil, Plus, Share2, Trash2 } from 'lucide-react';\n\nexport default function IconButtonVariants() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton variant=\"primary\" aria-label=\"Qo'shish\">\n        <Plus />\n      </IconButton>\n      <IconButton aria-label=\"Sevimlilarga qo'shish\">\n        <Heart />\n      </IconButton>\n      <IconButton variant=\"outline\" aria-label=\"Tahrirlash\">\n        <Pencil />\n      </IconButton>\n      <IconButton variant=\"ghost\" aria-label=\"Ulashish\">\n        <Share2 />\n      </IconButton>\n      <IconButton variant=\"danger\" aria-label=\"O'chirish\">\n        <Trash2 />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "archive/v0.3/input/addons": { component: Demo600, file: "archive/v0.3/input/addons.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Mail } from 'lucide-react';\n\nexport default function InputAddons() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" aria-label=\"Telefon\" />\n      <Input suffix=\"so'm\" placeholder=\"1 250 000\" inputMode=\"numeric\" aria-label=\"Narx\" />\n      <Input rightIcon={<Mail />} type=\"email\" placeholder=\"email@misol.uz\" aria-label=\"Email\" />\n      <Input prefix=\"https://\" suffix=\".uz\" placeholder=\"dokon\" aria-label=\"Sayt manzili\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/input/basic": { component: Demo601, file: "archive/v0.3/input/basic.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Search } from 'lucide-react';\n\nexport default function InputBasic() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Input leftIcon={<Search />} placeholder=\"Mahsulot qidirish\" aria-label=\"Mahsulot qidirish\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/input/clearable": { component: Demo602, file: "archive/v0.3/input/clearable.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Search } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function InputClearable() {\n  const [query, setQuery] = useState('Samarqand');\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-2\">\n      <Input\n        leftIcon={<Search />}\n        clearable\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Shahar qidirish\"\n        aria-label=\"Shahar qidirish\"\n      />\n      <p className=\"text-xs text-text-muted\">Qiymat: {query || '—'}</p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/input/password": { component: Demo603, file: "archive/v0.3/input/password.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function InputPassword() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Parol\" description=\"Kamida 8 ta belgi\">\n        <Input type=\"password\" defaultValue=\"maxfiy123\" autoComplete=\"current-password\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/input/sizes": { component: Demo604, file: "archive/v0.3/input/sizes.tsx", source: "'use client';\n\nimport { Button, Input } from '@akhatmirzo/ui';\n\nexport default function InputSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"sm\" placeholder=\"Kichik · 32\" aria-label=\"Kichik\" />\n        <Button size=\"sm\">Qo'llash</Button>\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"md\" placeholder=\"O'rta · 40\" aria-label=\"O'rta\" />\n        <Button size=\"md\">Qo'llash</Button>\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"lg\" placeholder=\"Katta · 48\" aria-label=\"Katta\" />\n        <Button size=\"lg\">Qo'llash</Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/input/states": { component: Demo605, file: "archive/v0.3/input/states.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\n\nexport default function InputStates() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-3 sm:grid-cols-2\">\n      <Input placeholder=\"Oddiy\" aria-label=\"Oddiy\" />\n      <Input invalid defaultValue=\"sarvar@mail\" aria-label=\"Xato\" />\n      <Input disabled defaultValue=\"O'chirilgan\" aria-label=\"O'chirilgan\" />\n      <Input readOnly defaultValue=\"Faqat o'qish uchun\" aria-label=\"Faqat o'qish\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/input/with-field": { component: Demo606, file: "archive/v0.3/input/with-field.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { Mail } from 'lucide-react';\n\nexport default function InputWithField() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" required description=\"Tasdiqlash kodi SMS orqali keladi\">\n        <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" />\n      </Field>\n      <Field label=\"Email\" error=\"Email manzil noto'g'ri\">\n        <Input leftIcon={<Mail />} defaultValue=\"sarvar@mail\" clearable />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/kbd/basic": { component: Demo607, file: "archive/v0.3/kbd/basic.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdBasic() {\n  return (\n    <p className=\"text-sm text-text\">\n      Qidiruvni ochish uchun <Kbd keys={['mod', 'K']} /> ni bosing, yopish uchun <Kbd>Esc</Kbd>.\n    </p>\n  );\n}\n" },
  "archive/v0.3/kbd/keys": { component: Demo608, file: "archive/v0.3/kbd/keys.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdKeys() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Kbd keys={['mod', 'K']} />\n      <Kbd keys={['mod', 'Shift', 'P']} />\n      <Kbd keys={['Alt', 'F4']} />\n      <Kbd>Esc</Kbd>\n      <Kbd>↵</Kbd>\n      <Kbd>↑</Kbd>\n      <Kbd>↓</Kbd>\n    </div>\n  );\n}\n" },
  "archive/v0.3/kbd/menu": { component: Demo609, file: "archive/v0.3/kbd/menu.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nconst items = [\n  { label: 'Nusxa olish', keys: ['mod', 'C'] },\n  { label: \"Qo'yish\", keys: ['mod', 'V'] },\n  { label: 'Hammasini tanlash', keys: ['mod', 'A'] },\n];\n\nexport default function KbdMenu() {\n  return (\n    <ul className=\"flex w-64 flex-col rounded-lg border border-border bg-surface p-1 text-sm text-text\">\n      {items.map((item) => (\n        <li key={item.label} className=\"flex items-center justify-between rounded-md px-2 py-1.5\">\n          {item.label}\n          <Kbd keys={item.keys} />\n        </li>\n      ))}\n    </ul>\n  );\n}\n" },
  "archive/v0.3/kbd/sizes": { component: Demo610, file: "archive/v0.3/kbd/sizes.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Kbd keys={['mod', 'C']} />\n      <Kbd size=\"md\" keys={['mod', 'C']} />\n    </div>\n  );\n}\n" },
  "archive/v0.3/masked-input/card": { component: Demo611, file: "archive/v0.3/masked-input/card.tsx", source: "'use client';\n\nimport { CardInput, Field, getCardDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CardInputDemo() {\n  const [card, setCard] = useState('');\n  const { complete, valid, brand } = getCardDetails(card);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field\n        label=\"Karta raqami\"\n        error={complete && !valid ? \"Karta raqami noto'g'ri\" : undefined}\n        description={\n          valid ? `Karta to'g'ri · ${brand ?? 'boshqa'}` : \"Sinab ko'ring: 4111 1111 1111 1111\"\n        }\n      >\n        <CardInput value={card} onValueChange={setCard} />\n      </Field>\n      <div className=\"flex flex-col gap-3\">\n        <CardInput aria-label=\"Uzcard\" defaultValue=\"8600123412341234\" />\n        <CardInput aria-label=\"Humo\" defaultValue=\"9860010203040506\" />\n        <CardInput aria-label=\"Luhn xato\" defaultValue=\"4111111111111112\" />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/masked-input/custom-mask": { component: Demo612, file: "archive/v0.3/masked-input/custom-mask.tsx", source: "'use client';\n\nimport { Field, MaskedInput } from '@akhatmirzo/ui';\n\nexport default function MaskedInputCustom() {\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Avtomobil raqami\" description='mask=\"99 A 999 AA\"'>\n        <MaskedInput mask=\"99 A 999 AA\" uppercase placeholder=\"01 A 123 BC\" />\n      </Field>\n      <Field label=\"JShShIR\" description=\"14 ta raqam\">\n        <MaskedInput mask=\"99999999999999\" inputMode=\"numeric\" placeholder=\"14 raqam\" />\n      </Field>\n      <Field label=\"Vaqt\" description='mask=\"99:99\"'>\n        <MaskedInput mask=\"99:99\" inputMode=\"numeric\" placeholder=\"09:30\" />\n      </Field>\n      <Field label=\"Promo-kod\" description='mask=\"****-****\"'>\n        <MaskedInput mask=\"****-****\" uppercase placeholder=\"XXXX-XXXX\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/masked-input/money-words": { component: Demo613, file: "archive/v0.3/masked-input/money-words.tsx", source: "'use client';\n\nimport { Field, MoneyInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MoneyWords() {\n  const [amount, setAmount] = useState<number | null>(1250000);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Shartnoma summasi\">\n        <MoneyInput value={amount} onValueChange={setAmount} showWords />\n      </Field>\n      <Field label=\"Кирилл, расмий\">\n        <MoneyInput\n          value={amount}\n          onValueChange={setAmount}\n          showWords={{ script: 'cyrillic', formal: true }}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/masked-input/money": { component: Demo614, file: "archive/v0.3/masked-input/money.tsx", source: "'use client';\n\nimport { Field, MoneyInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MoneyInputDemo() {\n  const [price, setPrice] = useState<number | null>(null);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Narx\" description={`Qiymat: ${price ?? 'null'}`}>\n        <MoneyInput value={price} onValueChange={setPrice} clearable />\n      </Field>\n      <Field label=\"Kurs\" description='decimals={2}, currency=\"$\"'>\n        <MoneyInput decimals={2} currency=\"$\" defaultValue={12.5} />\n      </Field>\n      <Field label=\"Oylik to'lov\" description=\"100 000 dan 50 000 000 gacha\">\n        <MoneyInput min={100000} max={50000000} />\n      </Field>\n      <Field label=\"Valyutasiz\" description=\"currency={null}\">\n        <MoneyInput currency={null} defaultValue={980000} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/masked-input/overview": { component: Demo615, file: "archive/v0.3/masked-input/overview.tsx", source: "'use client';\n\nimport { CardInput, Field, MaskedInput, MoneyInput, PhoneInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MaskedInputOverview() {\n  const [phone, setPhone] = useState('');\n  const [sum, setSum] = useState<number | null>(1250000);\n  const [card, setCard] = useState('');\n  const [passport, setPassport] = useState('');\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Telefon\" description={`Qiymat: \"${phone}\"`}>\n        <PhoneInput value={phone} onValueChange={setPhone} />\n      </Field>\n      <Field label=\"Summa\" description={`Qiymat: ${sum ?? 'null'}`}>\n        <MoneyInput value={sum} onValueChange={setSum} />\n      </Field>\n      <Field label=\"Karta raqami\" description={`Qiymat: \"${card}\"`}>\n        <CardInput value={card} onValueChange={setCard} />\n      </Field>\n      <Field label=\"Pasport\" description={`Qiymat: \"${passport}\"`}>\n        <MaskedInput\n          mask=\"AA 9999999\"\n          uppercase\n          placeholder=\"AB 1234567\"\n          value={passport}\n          onValueChange={setPassport}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/masked-input/phone": { component: Demo616, file: "archive/v0.3/masked-input/phone.tsx", source: "'use client';\n\nimport { Field, PhoneInput, type PhoneInputDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PhoneInputDemo() {\n  const [phone, setPhone] = useState('');\n  const [details, setDetails] = useState<PhoneInputDetails | null>(null);\n\n  const badOperator = phone.length >= 2 && !details?.operator;\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Field\n        label=\"Telefon raqami\"\n        required\n        error={badOperator ? `\"${phone.slice(0, 2)}\" — bunday operator kodi yo'q` : undefined}\n        description={\n          details?.valid ? `Operator: ${details.operator}` : '+998 90 123 45 67 ni joylang'\n        }\n      >\n        <PhoneInput\n          value={phone}\n          onValueChange={(value, info) => {\n            setPhone(value);\n            setDetails(info);\n          }}\n        />\n      </Field>\n      <PhoneInput aria-label=\"Kichik\" size=\"sm\" defaultValue=\"991234567\" />\n      <PhoneInput aria-label=\"Faqat o'qish\" readOnly defaultValue=\"935554433\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/otp-input/length": { component: Demo617, file: "archive/v0.3/otp-input/length.tsx", source: "'use client';\n\nimport { OtpInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function OtpInputLength() {\n  const [promo, setPromo] = useState('');\n\n  return (\n    <div className=\"flex flex-col items-start gap-5\">\n      <OtpInput length={4} aria-label=\"4 xonali PIN\" />\n      <OtpInput length={6} groupSize={2} aria-label=\"Juft guruhli kod\" />\n      <div className=\"flex flex-col gap-2\">\n        <OtpInput\n          type=\"alphanumeric\"\n          groupSize={3}\n          aria-label=\"Harfli kod\"\n          value={promo}\n          onValueChange={setPromo}\n        />\n        <span className=\"text-sm text-text-muted\">Qiymat: {promo || '—'}</span>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/otp-input/resend": { component: Demo618, file: "archive/v0.3/otp-input/resend.tsx", source: "'use client';\n\nimport { OtpInput, toast } from '@akhatmirzo/ui';\n\nconst sendSms = () =>\n  new Promise<void>((resolve) => {\n    setTimeout(() => {\n      toast('SMS qayta yuborildi');\n      resolve();\n    }, 800);\n  });\n\nexport default function OtpResendTimer() {\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <OtpInput.ResendTimer seconds={5} onResend={() => toast('Kod qayta yuborildi')} />\n      <OtpInput.ResendTimer\n        seconds={3}\n        labels={{ resend: 'SMS ni qayta olish' }}\n        onResend={sendSms}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/otp-input/states": { component: Demo619, file: "archive/v0.3/otp-input/states.tsx", source: "'use client';\n\nimport { OtpInput } from '@akhatmirzo/ui';\n\nexport default function OtpInputStates() {\n  return (\n    <div className=\"flex flex-col items-start gap-5\">\n      <OtpInput invalid defaultValue=\"482913\" groupSize={3} aria-label=\"Xato kod\" />\n      <OtpInput disabled defaultValue=\"12\" groupSize={3} aria-label=\"O'chirilgan\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/otp-input/verify": { component: Demo620, file: "archive/v0.3/otp-input/verify.tsx", source: "'use client';\n\nimport { Field, OtpInput, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CORRECT = '123456';\n\nexport default function OtpInputVerify() {\n  const [code, setCode] = useState('');\n  const [status, setStatus] = useState<'idle' | 'error' | 'ok'>('idle');\n\n  return (\n    <div className=\"flex flex-col gap-2\">\n      <Field\n        label=\"Tasdiqlash kodi\"\n        description={\n          status === 'ok' ? 'Kod tasdiqlandi' : `+998 90 *** ** 67 ga yuborildi. Kod: ${CORRECT}`\n        }\n        error={status === 'error' ? \"Kod noto'g'ri. Qayta urinib ko'ring.\" : undefined}\n      >\n        <OtpInput\n          groupSize={3}\n          value={code}\n          disabled={status === 'ok'}\n          onValueChange={(value) => {\n            setCode(value);\n            if (status === 'error') setStatus('idle');\n          }}\n          onComplete={(value) => setStatus(value === CORRECT ? 'ok' : 'error')}\n        />\n      </Field>\n      <OtpInput.ResendTimer\n        onResend={() => {\n          setCode('');\n          setStatus('idle');\n          toast('Yangi kod yuborildi');\n        }}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/pagination/basic": { component: Demo621, file: "archive/v0.3/pagination/basic.tsx", source: "'use client';\n\nimport { Pagination, PaginationInfo } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PaginationBasic() {\n  const [page, setPage] = useState(3);\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <Pagination page={page} onPageChange={setPage} total={230} pageSize={10} />\n      <PaginationInfo page={page} pageSize={10} total={230} />\n    </div>\n  );\n}\n" },
  "archive/v0.3/pagination/compact": { component: Demo622, file: "archive/v0.3/pagination/compact.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\n\nexport default function PaginationCompact() {\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Pagination defaultPage={3} pageCount={24} compact />\n      <Pagination defaultPage={3} pageCount={24} compact size=\"sm\" showFirstLast />\n    </div>\n  );\n}\n" },
  "archive/v0.3/pagination/data-table": { component: Demo623, file: "archive/v0.3/pagination/data-table.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, Pagination, PaginationInfo, type DataTableColumn } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\nconst ORDERS: Order[] = Array.from({ length: 47 }, (_, i) => ({\n  id: 3001 + i,\n  customer: NAMES[i % NAMES.length]!,\n  total: 120_000 + ((i * 314_159) % 2_500_000),\n}));\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88 },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nconst PAGE_SIZE = 5;\n\nexport default function PaginationDataTable() {\n  const [page, setPage] = useState(1);\n  const rows = ORDERS.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);\n\n  return (\n    <div className=\"flex w-full flex-col gap-3\">\n      <DataTable label=\"Buyurtmalar\" data={rows} columns={columns} className=\"w-full\" />\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <PaginationInfo page={page} pageSize={PAGE_SIZE} total={ORDERS.length} />\n        <Pagination\n          page={page}\n          onPageChange={setPage}\n          total={ORDERS.length}\n          pageSize={PAGE_SIZE}\n          size=\"sm\"\n        />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/pagination/first-last": { component: Demo624, file: "archive/v0.3/pagination/first-last.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\n\nexport default function PaginationFirstLast() {\n  return <Pagination defaultPage={10} pageCount={40} siblings={2} showFirstLast compact={false} />;\n}\n" },
  "archive/v0.3/pagination/links": { component: Demo625, file: "archive/v0.3/pagination/links.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PaginationLinks() {\n  // Haqiqiy loyihada sahifa URL'dan o'qiladi: ?page=3\n  const [page, setPage] = useState(1);\n\n  return (\n    <Pagination page={page} onPageChange={setPage} pageCount={8} getHref={(p) => `#sahifa-${p}`} />\n  );\n}\n" },
  "archive/v0.3/pagination/sizes": { component: Demo626, file: "archive/v0.3/pagination/sizes.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\n\nexport default function PaginationSizes() {\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Pagination defaultPage={4} pageCount={12} size=\"sm\" compact={false} />\n      <Pagination defaultPage={4} pageCount={12} compact={false} />\n    </div>\n  );\n}\n" },
  "archive/v0.3/popover/color-picker": { component: Demo627, file: "archive/v0.3/popover/color-picker.tsx", source: "'use client';\n\nimport { Button, Popover } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst colors = [\n  { name: 'Asosiy', className: 'bg-primary' },\n  { name: 'Yashil', className: 'bg-success' },\n  { name: 'Sariq', className: 'bg-warning' },\n  { name: 'Qizil', className: 'bg-danger' },\n  { name: \"Ko'k\", className: 'bg-info' },\n];\n\nexport default function PopoverColorPicker() {\n  const [color, setColor] = useState(colors[0]!);\n\n  return (\n    <Popover>\n      <Popover.Trigger asChild>\n        <Button\n          variant=\"outline\"\n          leftIcon={<span className={`size-3 rounded-full ${color.className}`} />}\n        >\n          Teg rangi\n        </Button>\n      </Popover.Trigger>\n      <Popover.Content className=\"w-auto\" aria-label=\"Rang tanlash\">\n        <div className=\"flex gap-2\">\n          {colors.map((c) => (\n            <Popover.Close key={c.name} asChild>\n              <button\n                type=\"button\"\n                aria-label={c.name}\n                aria-pressed={c.name === color.name}\n                onClick={() => setColor(c)}\n                className={`focus-ring size-7 cursor-pointer rounded-full border-2 border-surface-raised ${c.className} aria-pressed:ring-2 aria-pressed:ring-primary`}\n              />\n            </Popover.Close>\n          ))}\n        </div>\n      </Popover.Content>\n    </Popover>\n  );\n}\n" },
  "archive/v0.3/popover/filter": { component: Demo628, file: "archive/v0.3/popover/filter.tsx", source: "'use client';\n\nimport { Button, Input, Popover } from '@akhatmirzo/ui';\nimport { Funnel } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function PopoverFilter() {\n  const [open, setOpen] = useState(false);\n  const [range, setRange] = useState({ from: '', to: '' });\n  const [applied, setApplied] = useState<string | null>(null);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Popover open={open} onOpenChange={setOpen}>\n        <Popover.Trigger asChild>\n          <Button leftIcon={<Funnel />}>Narx</Button>\n        </Popover.Trigger>\n        <Popover.Content align=\"start\" aria-label=\"Narx filtri\">\n          <form\n            className=\"flex flex-col gap-3\"\n            onSubmit={(e) => {\n              e.preventDefault();\n              setApplied(`${range.from || '0'} – ${range.to || '∞'} so'm`);\n              setOpen(false);\n            }}\n          >\n            <p className=\"m-0 font-semibold\">Narx oralig'i</p>\n            <Input\n              size=\"sm\"\n              inputMode=\"numeric\"\n              placeholder=\"dan\"\n              suffix=\"so'm\"\n              aria-label=\"Narx: dan\"\n              value={range.from}\n              onChange={(e) => setRange((r) => ({ ...r, from: e.target.value }))}\n            />\n            <Input\n              size=\"sm\"\n              inputMode=\"numeric\"\n              placeholder=\"gacha\"\n              suffix=\"so'm\"\n              aria-label=\"Narx: gacha\"\n              value={range.to}\n              onChange={(e) => setRange((r) => ({ ...r, to: e.target.value }))}\n            />\n            <div className=\"mt-1 flex justify-end gap-2\">\n              <Popover.Close asChild>\n                <Button size=\"sm\">Bekor</Button>\n              </Popover.Close>\n              <Button size=\"sm\" variant=\"primary\" type=\"submit\">\n                Qo'llash\n              </Button>\n            </div>\n          </form>\n        </Popover.Content>\n      </Popover>\n      <span className=\"text-sm text-text-muted\">{applied ?? \"Filtr qo'llanmagan\"}</span>\n    </div>\n  );\n}\n" },
  "archive/v0.3/popover/placement": { component: Demo629, file: "archive/v0.3/popover/placement.tsx", source: "'use client';\n\nimport { Button, Popover } from '@akhatmirzo/ui';\n\nexport default function PopoverPlacement() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {(['top', 'right', 'bottom', 'left'] as const).map((side) => (\n        <Popover key={side}>\n          <Popover.Trigger asChild>\n            <Button variant=\"outline\">{side}</Button>\n          </Popover.Trigger>\n          <Popover.Content side={side} arrow className=\"w-56\" aria-label={`Tomon: ${side}`}>\n            <p className=\"m-0 text-text-muted\">\n              Panel <b className=\"text-text\">{side}</b> tomonda, triggerdan 6px uzoqlikda.\n            </p>\n          </Popover.Content>\n        </Popover>\n      ))}\n      <Popover>\n        <Popover.Trigger asChild>\n          <Button variant=\"outline\">align=end</Button>\n        </Popover.Trigger>\n        <Popover.Content align=\"end\" className=\"w-56\" aria-label=\"O'ngga tekislangan\">\n          <p className=\"m-0 text-text-muted\">Panel triggerning o'ng chetiga tekislangan.</p>\n        </Popover.Content>\n      </Popover>\n    </div>\n  );\n}\n" },
  "archive/v0.3/popover/settings": { component: Demo630, file: "archive/v0.3/popover/settings.tsx", source: "'use client';\n\nimport { Field, IconButton, Popover, Switch } from '@akhatmirzo/ui';\nimport { Bell } from 'lucide-react';\n\nexport default function PopoverSettings() {\n  return (\n    <Popover>\n      <Popover.Trigger asChild>\n        <IconButton variant=\"outline\" aria-label=\"Bildirishnoma sozlamalari\">\n          <Bell />\n        </IconButton>\n      </Popover.Trigger>\n      <Popover.Content side=\"right\" align=\"start\" arrow aria-label=\"Bildirishnomalar\">\n        <div className=\"flex flex-col gap-3\">\n          <p className=\"m-0 font-semibold\">Bildirishnomalar</p>\n          <Field label=\"Email orqali\" orientation=\"horizontal\">\n            <Switch defaultChecked />\n          </Field>\n          <Field label=\"SMS orqali\" orientation=\"horizontal\">\n            <Switch />\n          </Field>\n          <Field label=\"Telegram bot\" orientation=\"horizontal\">\n            <Switch defaultChecked />\n          </Field>\n        </div>\n      </Popover.Content>\n    </Popover>\n  );\n}\n" },
  "archive/v0.3/progress/basic": { component: Demo631, file: "archive/v0.3/progress/basic.tsx", source: "'use client';\n\nimport { Progress } from '@akhatmirzo/ui';\n\nexport default function ProgressBasic() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-6\">\n      <Progress value={64} label=\"Yuklanmoqda\" showValue />\n      <Progress\n        value={3}\n        max={5}\n        label=\"Profil to'ldirildi\"\n        showValue\n        formatValue={(value, max) => `${value} / ${max}`}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/progress/circle": { component: Demo632, file: "archive/v0.3/progress/circle.tsx", source: "'use client';\n\nimport { ProgressCircle } from '@akhatmirzo/ui';\n\nexport default function ProgressCircleDemo() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <ProgressCircle value={30} size=\"sm\" label=\"Sinxronlash\" />\n      <ProgressCircle value={58} showValue label=\"Saqlash\" />\n      <ProgressCircle value={72} size=\"lg\" showValue label=\"Kurs\" color=\"success\" />\n      <ProgressCircle value={100} size=\"lg\" showValue label=\"Tayyor\" color=\"success\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/progress/colors-sizes": { component: Demo633, file: "archive/v0.3/progress/colors-sizes.tsx", source: "'use client';\n\nimport { Progress } from '@akhatmirzo/ui';\n\nexport default function ProgressColorsSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-5\">\n      <Progress value={40} size=\"sm\" aria-label=\"Kichik chiziq\" />\n      <Progress value={55} color=\"success\" aria-label=\"O'rta chiziq\" />\n      <Progress value={80} size=\"lg\" color=\"warning\" aria-label=\"Katta chiziq\" />\n      <Progress value={95} color=\"danger\" label=\"Disk to'lib bormoqda\" showValue />\n    </div>\n  );\n}\n" },
  "archive/v0.3/progress/indeterminate": { component: Demo634, file: "archive/v0.3/progress/indeterminate.tsx", source: "'use client';\n\nimport { Progress, ProgressCircle } from '@akhatmirzo/ui';\n\nexport default function ProgressIndeterminate() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-6\">\n      <Progress value={null} label=\"Fayl tayyorlanmoqda\" />\n      <ProgressCircle value={null} label=\"Yuklanmoqda\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/progress/upload": { component: Demo635, file: "archive/v0.3/progress/upload.tsx", source: "'use client';\n\nimport { Button, Progress } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\nexport default function ProgressUpload() {\n  const [value, setValue] = useState(0);\n  const [running, setRunning] = useState(false);\n\n  useEffect(() => {\n    if (!running) return;\n    const id = setInterval(() => setValue((v) => Math.min(v + 8, 100)), 300);\n    return () => clearInterval(id);\n  }, [running]);\n\n  const done = value === 100;\n  if (done && running) setRunning(false);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Progress value={value} label=\"hisobot.pdf\" showValue color={done ? 'success' : 'primary'} />\n      <Button\n        size=\"sm\"\n        className=\"self-start\"\n        disabled={running}\n        onClick={() => {\n          setValue(0);\n          setRunning(true);\n        }}\n      >\n        {done ? 'Qayta yuklash' : 'Yuklashni boshlash'}\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/radio-group/basic": { component: Demo636, file: "archive/v0.3/radio-group/basic.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupBasic() {\n  return (\n    <RadioGroup aria-label=\"To'lov usuli\" defaultValue=\"click\">\n      <Radio value=\"click\" label=\"Click\" />\n      <Radio value=\"payme\" label=\"Payme\" />\n      <Radio value=\"cash\" label=\"Naqd pul\" />\n    </RadioGroup>\n  );\n}\n" },
  "archive/v0.3/radio-group/card": { component: Demo637, file: "archive/v0.3/radio-group/card.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RadioGroupCard() {\n  const [plan, setPlan] = useState('pro');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <RadioGroup aria-label=\"Tarif\" variant=\"card\" value={plan} onValueChange={setPlan}>\n        <Radio value=\"free\" label=\"Bepul\" description=\"1 ta do'kon, asosiy imkoniyatlar\" />\n        <Radio\n          value=\"pro\"\n          label=\"Pro · 149 000 so'm\"\n          description=\"Cheksiz do'konlar va hisobotlar\"\n        />\n        <Radio value=\"team\" label=\"Jamoa\" description=\"Tez orada\" disabled />\n      </RadioGroup>\n      <p className=\"text-sm text-text-muted\">Tanlangan tarif: {plan}</p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/radio-group/horizontal": { component: Demo638, file: "archive/v0.3/radio-group/horizontal.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupHorizontal() {\n  return (\n    <RadioGroup aria-label=\"Yetkazib berish\" orientation=\"horizontal\" defaultValue=\"express\">\n      <Radio value=\"express\" label=\"Tezkor\" />\n      <Radio value=\"standard\" label=\"Oddiy\" />\n      <Radio value=\"pickup\" label=\"Olib ketish\" />\n    </RadioGroup>\n  );\n}\n" },
  "archive/v0.3/radio-group/sizes": { component: Demo639, file: "archive/v0.3/radio-group/sizes.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-10\">\n      <RadioGroup aria-label=\"Interfeys tili (kichik)\" size=\"sm\" defaultValue=\"uz\">\n        <Radio value=\"uz\" label=\"O'zbekcha\" />\n        <Radio value=\"ru\" label=\"Ruscha\" description=\"Kirill yozuvida\" />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Interfeys tili (o'rta)\" defaultValue=\"uz\">\n        <Radio value=\"uz\" label=\"O'zbekcha\" />\n        <Radio value=\"ru\" label=\"Ruscha\" description=\"Kirill yozuvida\" />\n      </RadioGroup>\n    </div>\n  );\n}\n" },
  "archive/v0.3/radio-group/states": { component: Demo640, file: "archive/v0.3/radio-group/states.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupStates() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-10\">\n      <RadioGroup aria-label=\"Butun guruh o'chirilgan\" disabled defaultValue=\"a\">\n        <Radio value=\"a\" label=\"Tanlangan\" />\n        <Radio value=\"b\" label=\"Tanlanmagan\" />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Bitta variant o'chirilgan\">\n        <Radio value=\"a\" label=\"Omborda bor\" />\n        <Radio value=\"b\" label=\"Tugagan\" disabled />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Xato holati\" invalid>\n        <Radio value=\"yes\" label=\"Ha\" />\n        <Radio value=\"no\" label=\"Yo'q\" />\n      </RadioGroup>\n    </div>\n  );\n}\n" },
  "archive/v0.3/radio-group/with-field": { component: Demo641, file: "archive/v0.3/radio-group/with-field.tsx", source: "'use client';\n\nimport { Field, Radio, RadioGroup } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RadioGroupWithField() {\n  const [value, setValue] = useState<string>();\n\n  return (\n    <Field label=\"Yetkazib berish\" required error={value ? undefined : 'Usulni tanlang'}>\n      <RadioGroup value={value} onValueChange={setValue}>\n        <Radio value=\"courier\" label=\"Kuryer\" description=\"Ertaga, 25 000 so'm\" />\n        <Radio value=\"pickup\" label=\"Olib ketish\" description=\"Bugun, bepul\" />\n      </RadioGroup>\n    </Field>\n  );\n}\n" },
  "archive/v0.3/script/overview": { component: Demo642, file: "archive/v0.3/script/overview.tsx", source: "'use client';\n\nimport { ScriptProvider, ScriptToggle, Translit } from '@akhatmirzo/ui';\n\nexport default function ScriptOverview() {\n  return (\n    <ScriptProvider defaultScript=\"latin\">\n      <div className=\"flex w-full max-w-md flex-col items-start gap-4\">\n        <ScriptToggle size=\"sm\" />\n        <Translit as=\"h3\" className=\"text-lg font-semibold text-text\">\n          Oʻzbekiston boʻylab yetkazib berish\n        </Translit>\n        <Translit as=\"p\" className=\"text-sm text-text-muted\">\n          Buyurtmangiz 2–3 kun ichida eshigingizgacha yetkaziladi. Toʻlov — naqd yoki karta orqali.\n        </Translit>\n      </div>\n    </ScriptProvider>\n  );\n}\n" },
  "archive/v0.3/script/persist": { component: Demo643, file: "archive/v0.3/script/persist.tsx", source: "'use client';\n\nimport { ScriptProvider, ScriptToggle, Translit } from '@akhatmirzo/ui';\n\nexport default function ScriptPersist() {\n  return (\n    <ScriptProvider defaultScript=\"latin\" storageKey=\"docs-script-demo\">\n      <div className=\"flex flex-col items-start gap-3\">\n        <ScriptToggle labels={{ latin: 'Lotincha', cyrillic: 'Кириллча' }} />\n        <Translit className=\"text-sm text-text-muted\">\n          Tanlovingiz eslab qolinadi — sahifani yangilab koʻring.\n        </Translit>\n      </div>\n    </ScriptProvider>\n  );\n}\n" },
  "archive/v0.3/script/use-script": { component: Demo644, file: "archive/v0.3/script/use-script.tsx", source: "'use client';\n\nimport { Button, ScriptProvider, ScriptToggle, useScript } from '@akhatmirzo/ui';\n\nfunction Cart() {\n  const { script, t } = useScript();\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <p className=\"text-sm text-text-muted\">\n        script: <code>{script}</code>\n      </p>\n      <Button variant=\"primary\">{t('Savatga qoʻshish')}</Button>\n      <input\n        className=\"h-10 w-full rounded-lg border border-border bg-surface px-3 text-sm text-text\"\n        placeholder={t('Mahsulot qidirish')}\n        aria-label={t('Mahsulot qidirish')}\n      />\n    </div>\n  );\n}\n\nexport default function UseScriptDemo() {\n  return (\n    <ScriptProvider defaultScript=\"cyrillic\">\n      <div className=\"flex w-full max-w-sm flex-col gap-4\">\n        <ScriptToggle />\n        <Cart />\n      </div>\n    </ScriptProvider>\n  );\n}\n" },
  "archive/v0.3/segmented-control/basic": { component: Demo645, file: "archive/v0.3/segmented-control/basic.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\n\nexport default function SegmentedControlBasic() {\n  return (\n    <SegmentedControl defaultValue=\"month\" aria-label=\"Davr\">\n      <SegmentedControl.Item value=\"day\">Kun</SegmentedControl.Item>\n      <SegmentedControl.Item value=\"week\">Hafta</SegmentedControl.Item>\n      <SegmentedControl.Item value=\"month\">Oy</SegmentedControl.Item>\n      <SegmentedControl.Item value=\"year\">Yil</SegmentedControl.Item>\n    </SegmentedControl>\n  );\n}\n" },
  "archive/v0.3/segmented-control/controlled": { component: Demo646, file: "archive/v0.3/segmented-control/controlled.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst totals: Record<string, string> = {\n  day: \"1 250 000 so'm\",\n  week: \"8 740 000 so'm\",\n  month: \"36 900 000 so'm\",\n};\n\nexport default function SegmentedControlControlled() {\n  const [period, setPeriod] = useState('week');\n\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <SegmentedControl value={period} onValueChange={setPeriod} aria-label=\"Davr\">\n        <SegmentedControl.Item value=\"day\">Kun</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"week\">Hafta</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"month\">Oy</SegmentedControl.Item>\n      </SegmentedControl>\n      <p className=\"m-0 text-sm text-text-muted\">\n        Savdo: <span className=\"font-semibold text-text\">{totals[period]}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/segmented-control/disabled": { component: Demo647, file: "archive/v0.3/segmented-control/disabled.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\n\nexport default function SegmentedControlDisabled() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      <SegmentedControl defaultValue=\"card\" aria-label=\"To'lov usuli\">\n        <SegmentedControl.Item value=\"cash\">Naqd</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"card\">Karta</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"credit\" disabled>\n          Nasiya\n        </SegmentedControl.Item>\n      </SegmentedControl>\n      <SegmentedControl defaultValue=\"uz\" disabled aria-label=\"Til\">\n        <SegmentedControl.Item value=\"uz\">O'zbekcha</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"ru\">Ruscha</SegmentedControl.Item>\n      </SegmentedControl>\n    </div>\n  );\n}\n" },
  "archive/v0.3/segmented-control/full-width": { component: Demo648, file: "archive/v0.3/segmented-control/full-width.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\n\nexport default function SegmentedControlFullWidth() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <SegmentedControl fullWidth defaultValue=\"delivery\" aria-label=\"Olib ketish usuli\">\n        <SegmentedControl.Item value=\"delivery\">Yetkazib berish</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"pickup\">Olib ketish</SegmentedControl.Item>\n      </SegmentedControl>\n    </div>\n  );\n}\n" },
  "archive/v0.3/segmented-control/icons": { component: Demo649, file: "archive/v0.3/segmented-control/icons.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\nimport { LayoutGrid, List, MapIcon } from 'lucide-react';\n\nexport default function SegmentedControlIcons() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <SegmentedControl defaultValue=\"grid\" aria-label=\"Ko'rinish\">\n        <SegmentedControl.Item value=\"grid\" icon={<LayoutGrid />} aria-label=\"Katakli\" />\n        <SegmentedControl.Item value=\"list\" icon={<List />} aria-label=\"Ro'yxat\" />\n        <SegmentedControl.Item value=\"map\" icon={<MapIcon />} aria-label=\"Xarita\" />\n      </SegmentedControl>\n      <SegmentedControl defaultValue=\"list\" aria-label=\"Ko'rinish\">\n        <SegmentedControl.Item value=\"grid\" icon={<LayoutGrid />}>\n          Katakli\n        </SegmentedControl.Item>\n        <SegmentedControl.Item value=\"list\" icon={<List />}>\n          Ro'yxat\n        </SegmentedControl.Item>\n      </SegmentedControl>\n    </div>\n  );\n}\n" },
  "archive/v0.3/segmented-control/sizes": { component: Demo650, file: "archive/v0.3/segmented-control/sizes.tsx", source: "'use client';\n\nimport { Button, SegmentedControl } from '@akhatmirzo/ui';\n\nconst sizes = ['sm', 'md', 'lg'] as const;\n\nexport default function SegmentedControlSizes() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      {sizes.map((size) => (\n        <div key={size} className=\"flex items-center gap-3\">\n          <SegmentedControl size={size} defaultValue=\"all\" aria-label={`Holat, ${size}`}>\n            <SegmentedControl.Item value=\"all\">Hammasi</SegmentedControl.Item>\n            <SegmentedControl.Item value=\"paid\">To'langan</SegmentedControl.Item>\n            <SegmentedControl.Item value=\"debt\">Qarz</SegmentedControl.Item>\n          </SegmentedControl>\n          <Button size={size} variant=\"outline\">\n            Eksport\n          </Button>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/select/basic": { component: Demo651, file: "archive/v0.3/select/basic.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SelectBasic() {\n  const [region, setRegion] = useState('');\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field label=\"Viloyat\" description=\"Buyurtma shu viloyatga yetkaziladi\">\n        <Select value={region} onValueChange={setRegion}>\n          <Select.Item value=\"tsh\">Toshkent shahri</Select.Item>\n          <Select.Item value=\"sam\">Samarqand</Select.Item>\n          <Select.Item value=\"bux\">Buxoro</Select.Item>\n          <Select.Item value=\"and\">Andijon</Select.Item>\n          <Select.Item value=\"fer\">Farg'ona</Select.Item>\n          <Select.Item value=\"nam\">Namangan</Select.Item>\n          <Select.Item value=\"qash\">Qashqadaryo</Select.Item>\n          <Select.Item value=\"xor\">Xorazm</Select.Item>\n          <Select.Item value=\"qqr\">Qoraqalpog'iston</Select.Item>\n        </Select>\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Qiymat: <span className=\"font-medium text-text\">{region || '—'}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/select/form": { component: Demo652, file: "archive/v0.3/select/form.tsx", source: "'use client';\n\nimport { Button, Field, Select } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function SelectForm() {\n  const [error, setError] = useState<string>();\n  const [sent, setSent] = useState('—');\n\n  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    const delivery = String(new FormData(e.currentTarget).get('delivery') ?? '');\n    if (!delivery) return setError('Yetkazib berish usulini tanlang');\n    setError(undefined);\n    setSent(delivery);\n  };\n\n  return (\n    <form onSubmit={handleSubmit} className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Field label=\"Yetkazib berish\" error={error} required>\n        <Select name=\"delivery\" onValueChange={() => setError(undefined)}>\n          <Select.Item value=\"courier\">Kuryer (1 kun)</Select.Item>\n          <Select.Item value=\"pickup\">Olib ketish</Select.Item>\n          <Select.Item value=\"post\">Pochta (2–3 kun)</Select.Item>\n        </Select>\n      </Field>\n      <div className=\"flex items-center gap-3\">\n        <Button type=\"submit\" variant=\"primary\">\n          Yuborish\n        </Button>\n        <span className=\"text-sm text-text-muted\">FormData: {sent}</span>\n      </div>\n    </form>\n  );\n}\n" },
  "archive/v0.3/select/groups": { component: Demo653, file: "archive/v0.3/select/groups.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nexport default function SelectGroups() {\n  return (\n    <Field label=\"Filial\" className=\"w-full max-w-xs\">\n      <Select defaultValue=\"fer\">\n        <Select.Item value=\"tsh\">Toshkent</Select.Item>\n        <Select.Item value=\"sam\">Samarqand</Select.Item>\n        <Select.Group label=\"Vodiy\">\n          <Select.Item value=\"and\">Andijon</Select.Item>\n          <Select.Item value=\"fer\">Farg'ona</Select.Item>\n          <Select.Item value=\"nam\">Namangan</Select.Item>\n        </Select.Group>\n        <Select.Separator />\n        <Select.Group label=\"Janub\">\n          <Select.Item value=\"qash\">Qashqadaryo</Select.Item>\n          <Select.Item value=\"sur\">Surxondaryo</Select.Item>\n        </Select.Group>\n      </Select>\n    </Field>\n  );\n}\n" },
  "archive/v0.3/select/icons": { component: Demo654, file: "archive/v0.3/select/icons.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nfunction Dot({ className }: { className: string }) {\n  return <span className={`size-2 rounded-full ${className}`} />;\n}\n\nexport default function SelectIcons() {\n  return (\n    <Field label=\"Buyurtma holati\" className=\"w-full max-w-xs\">\n      <Select defaultValue=\"progress\">\n        <Select.Item value=\"new\" icon={<Dot className=\"bg-info\" />}>\n          Yangi\n        </Select.Item>\n        <Select.Item value=\"progress\" icon={<Dot className=\"bg-warning\" />}>\n          Jarayonda\n        </Select.Item>\n        <Select.Item value=\"done\" icon={<Dot className=\"bg-success\" />}>\n          Yetkazildi\n        </Select.Item>\n        <Select.Item value=\"canceled\" icon={<Dot className=\"bg-danger\" />}>\n          Bekor qilindi\n        </Select.Item>\n      </Select>\n    </Field>\n  );\n}\n" },
  "archive/v0.3/select/region": { component: Demo655, file: "archive/v0.3/select/region.tsx", source: "'use client';\n\nimport type { UzRegionId } from '@akhatmirzo/core';\nimport { Field, RegionSelect, ScriptProvider, ScriptToggle } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RegionSelectDemo() {\n  const [region, setRegion] = useState<UzRegionId>('samarkand');\n\n  return (\n    <ScriptProvider>\n      <div className=\"flex w-full max-w-sm flex-col gap-4\">\n        <ScriptToggle size=\"sm\" />\n        <Field label=\"Hudud\" description={`Qiymat: \"${region}\"`}>\n          <RegionSelect value={region} onValueChange={setRegion} />\n        </Field>\n        <Field label=\"Viloyat\" description=\"includeCity={false}\">\n          <RegionSelect includeCity={false} />\n        </Field>\n      </div>\n    </ScriptProvider>\n  );\n}\n" },
  "archive/v0.3/select/sizes": { component: Demo656, file: "archive/v0.3/select/sizes.tsx", source: "'use client';\n\nimport { Button, Select } from '@akhatmirzo/ui';\n\nexport default function SelectSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      {(['sm', 'md', 'lg'] as const).map((size) => (\n        <Select\n          key={size}\n          size={size}\n          aria-label={`O'lcham ${size}`}\n          placeholder={`size=\"${size}\"`}\n        >\n          <Select.Item value=\"a\">Birinchi</Select.Item>\n          <Select.Item value=\"b\">Ikkinchi</Select.Item>\n        </Select>\n      ))}\n      <div className=\"flex items-center gap-3\">\n        <Select aria-label=\"Valyuta\" defaultValue=\"uzs\" className=\"w-28\">\n          <Select.Item value=\"uzs\">UZS</Select.Item>\n          <Select.Item value=\"usd\">USD</Select.Item>\n          <Select.Item value=\"eur\">EUR</Select.Item>\n        </Select>\n        <Button variant=\"primary\">To'lash</Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/select/states": { component: Demo657, file: "archive/v0.3/select/states.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nexport default function SelectStates() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <Field label=\"O'chirilgan\" disabled>\n        <Select defaultValue=\"click\">\n          <Select.Item value=\"click\">Click</Select.Item>\n        </Select>\n      </Field>\n      <Field label=\"To'lov usuli\" error=\"To'lov usulini tanlang\" required>\n        <Select>\n          <Select.Item value=\"click\">Click</Select.Item>\n          <Select.Item value=\"payme\">Payme</Select.Item>\n        </Select>\n      </Field>\n      <Field label=\"O'chirilgan element\">\n        <Select placeholder=\"Usulni tanlang\">\n          <Select.Item value=\"click\">Click</Select.Item>\n          <Select.Item value=\"payme\">Payme</Select.Item>\n          <Select.Item value=\"uzum\" disabled>\n            Uzum (vaqtincha ishlamaydi)\n          </Select.Item>\n          <Select.Item value=\"cash\">Naqd pul</Select.Item>\n        </Select>\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/skeleton/loading-card": { component: Demo658, file: "archive/v0.3/skeleton/loading-card.tsx", source: "'use client';\n\nimport { Avatar, Button, Card, Skeleton } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SkeletonLoadingCard() {\n  const [loading, setLoading] = useState(true);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col items-start gap-3\">\n      <Button size=\"sm\" onClick={() => setLoading((l) => !l)}>\n        {loading ? \"Kontentni ko'rsatish\" : 'Yuklanish holati'}\n      </Button>\n      <Card variant=\"outline\" className=\"w-full\" aria-busy={loading}>\n        <div className=\"flex items-center gap-3\">\n          {loading ? (\n            <Skeleton variant=\"circle\" className=\"size-10\" />\n          ) : (\n            <Avatar name=\"Malika Rahimova\" />\n          )}\n          <div className=\"flex flex-1 flex-col gap-2\">\n            {loading ? (\n              <Skeleton className=\"h-4 w-2/5\" />\n            ) : (\n              <b className=\"text-sm\">Malika Rahimova</b>\n            )}\n            {loading ? (\n              <Skeleton className=\"h-3 w-1/4\" />\n            ) : (\n              <span className=\"text-xs text-text-muted\">2 soat oldin</span>\n            )}\n          </div>\n        </div>\n        {loading ? (\n          <Skeleton.Text lines={3} />\n        ) : (\n          <p className=\"text-sm\">\n            Buyurtma vaqtida yetib keldi, kuryer juda xushmuomala edi. Keyingi safar ham shu\n            do'kondan olaman.\n          </p>\n        )}\n      </Card>\n    </div>\n  );\n}\n" },
  "archive/v0.3/skeleton/shapes": { component: Demo659, file: "archive/v0.3/skeleton/shapes.tsx", source: "'use client';\n\nimport { Skeleton } from '@akhatmirzo/ui';\n\nexport default function SkeletonShapes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Skeleton variant=\"circle\" className=\"size-12\" />\n      <Skeleton className=\"h-4 w-32\" />\n      <Skeleton className=\"h-10 w-28 rounded-lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/skeleton/text": { component: Demo660, file: "archive/v0.3/skeleton/text.tsx", source: "'use client';\n\nimport { Skeleton } from '@akhatmirzo/ui';\n\nexport default function SkeletonTextDemo() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-6 sm:grid-cols-2\">\n      <Skeleton.Text lines={1} />\n      <Skeleton.Text lines={4} />\n    </div>\n  );\n}\n" },
  "archive/v0.3/slider/basic": { component: Demo661, file: "archive/v0.3/slider/basic.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderBasic() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Slider defaultValue={[40]} aria-label=\"Yorqinlik\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/slider/marks": { component: Demo662, file: "archive/v0.3/slider/marks.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nconst marks = [\n  { value: 0, label: '0%' },\n  { value: 25, label: '25%' },\n  { value: 50, label: '50%' },\n  { value: 75, label: '75%' },\n  { value: 100, label: '100%' },\n];\n\nexport default function SliderMarks() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Slider\n        defaultValue={[25]}\n        step={25}\n        marks={marks}\n        formatValue={(v) => `${v}%`}\n        aria-label=\"Chegirma\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/slider/range": { component: Demo663, file: "archive/v0.3/slider/range.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { Slider } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SliderRange() {\n  const [price, setPrice] = useState([1_000_000, 3_500_000]);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Slider\n        value={price}\n        onValueChange={setPrice}\n        min={0}\n        max={5_000_000}\n        step={50_000}\n        minStepsBetweenThumbs={2}\n        formatValue={(v) => formatMoney(v)}\n        aria-label=\"Narx\"\n      />\n      <p className=\"m-0 text-sm text-text-muted\">\n        Narx:{' '}\n        <span className=\"font-semibold text-text tabular-nums\">\n          {formatMoney(price[0]!)} — {formatMoney(price[1]!)}\n        </span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/slider/show-value": { component: Demo664, file: "archive/v0.3/slider/show-value.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderShowValue() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-10 pt-8\">\n      <Slider defaultValue={[30]} showValue=\"active\" aria-label=\"Faol paytda\" />\n      <Slider defaultValue={[60]} showValue=\"always\" aria-label=\"Doim\" />\n      <Slider defaultValue={[80]} showValue=\"never\" aria-label=\"Hech qachon\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/slider/sizes": { component: Demo665, file: "archive/v0.3/slider/sizes.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderSizes() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-8\">\n      <Slider size=\"sm\" defaultValue={[35]} aria-label=\"Kichik\" />\n      <Slider size=\"md\" defaultValue={[65]} aria-label=\"O'rta\" />\n      <Slider defaultValue={[50]} disabled aria-label=\"O'chirilgan\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/slider/vertical": { component: Demo666, file: "archive/v0.3/slider/vertical.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderVertical() {\n  return (\n    <div className=\"flex h-48 items-stretch gap-10 pl-12\">\n      <Slider orientation=\"vertical\" defaultValue={[70]} aria-label=\"Ovoz\" />\n      <Slider orientation=\"vertical\" defaultValue={[20, 60]} aria-label=\"Harorat\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/slider/with-field": { component: Demo667, file: "archive/v0.3/slider/with-field.tsx", source: "'use client';\n\nimport { Field, Slider } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SliderWithField() {\n  const [km, setKm] = useState([45]);\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field\n        label=\"Yetkazib berish radiusi\"\n        description=\"Do'kondan necha km uzoqlikkacha yetkazasiz\"\n        error={km[0]! > 40 ? \"40 km dan uzoqqa kuryer yo'q\" : undefined}\n      >\n        <Slider value={km} onValueChange={setKm} max={60} formatValue={(v) => `${v} km`} />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/spinner/colors": { component: Demo668, file: "archive/v0.3/spinner/colors.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerColors() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Spinner className=\"text-text\" />\n      <Spinner className=\"text-primary\" />\n      <Spinner className=\"text-success\" />\n      <Spinner className=\"text-danger\" />\n      <span className=\"inline-flex size-10 items-center justify-center rounded-lg bg-primary text-primary-foreground\">\n        <Spinner size=\"sm\" />\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.3/spinner/sizes": { component: Demo669, file: "archive/v0.3/spinner/sizes.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4 text-text-muted\">\n      <Spinner size=\"sm\" />\n      <Spinner size=\"md\" />\n      <Spinner size=\"lg\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/spinner/with-text": { component: Demo670, file: "archive/v0.3/spinner/with-text.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerWithText() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <span className=\"inline-flex items-center gap-2 text-sm text-text-muted\">\n        <Spinner size=\"sm\" aria-hidden=\"true\" />\n        Buyurtmalar yuklanmoqda...\n      </span>\n      <div className=\"flex h-32 items-center justify-center rounded-lg border border-border bg-surface text-text-muted\">\n        <Spinner size=\"lg\" label=\"Jadval yuklanmoqda\" />\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/stepper/basic": { component: Demo671, file: "archive/v0.3/stepper/basic.tsx", source: "'use client';\n\nimport { Button, Stepper } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst steps = [\n  { title: 'Savat' },\n  { title: 'Yetkazib berish', description: 'Manzil va vaqt' },\n  { title: \"To'lov\" },\n  { title: 'Tasdiqlash', optional: true },\n];\n\nexport default function StepperBasic() {\n  const [step, setStep] = useState(1);\n\n  return (\n    <div className=\"flex w-full flex-col gap-6\">\n      <Stepper steps={steps} value={step} onValueChange={setStep} aria-label=\"Buyurtma\" />\n      <div className=\"flex gap-2\">\n        <Button size=\"sm\" disabled={step === 0} onClick={() => setStep(step - 1)}>\n          Orqaga\n        </Button>\n        <Button\n          size=\"sm\"\n          variant=\"primary\"\n          disabled={step === steps.length}\n          onClick={() => setStep(step + 1)}\n        >\n          Davom etish\n        </Button>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/stepper/compact": { component: Demo672, file: "archive/v0.3/stepper/compact.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\n\nconst steps = [\n  { title: 'Savat' },\n  { title: 'Yetkazib berish' },\n  { title: \"To'lov\" },\n  { title: 'Tasdiqlash' },\n];\n\nexport default function StepperCompact() {\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Stepper steps={steps} value={1} compact />\n    </div>\n  );\n}\n" },
  "archive/v0.3/stepper/sizes": { component: Demo673, file: "archive/v0.3/stepper/sizes.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\n\nconst steps = [{ title: 'Savat' }, { title: 'Yetkazib berish' }, { title: \"To'lov\" }];\n\nexport default function StepperSizes() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      <Stepper steps={steps} defaultValue={1} size=\"sm\" aria-label=\"Kichik\" />\n      <Stepper steps={steps} defaultValue={1} aria-label=\"O'rtacha\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/stepper/states": { component: Demo674, file: "archive/v0.3/stepper/states.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\n\nexport default function StepperStates() {\n  return (\n    <Stepper\n      aria-label=\"Ariza\"\n      value={2}\n      className=\"w-full\"\n      steps={[\n        { title: \"Ma'lumotlar\" },\n        { title: 'Hujjatlar', status: 'error', description: \"Pasport rasmi o'qilmadi\" },\n        { title: 'Tekshiruv' },\n        { title: 'Shartnoma' },\n      ]}\n    />\n  );\n}\n" },
  "archive/v0.3/stepper/vertical": { component: Demo675, file: "archive/v0.3/stepper/vertical.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function StepperVertical() {\n  const [step, setStep] = useState(1);\n\n  return (\n    <Stepper\n      orientation=\"vertical\"\n      aria-label=\"Do'konni sozlash\"\n      value={step}\n      onValueChange={setStep}\n      allowFutureSteps\n      steps={[\n        { title: \"Do'kon nomi\", description: \"Mijozlar ko'radigan nom\" },\n        { title: \"To'lov usullari\", description: 'Click, Payme, naqd' },\n        { title: 'Yetkazib berish', description: 'Hududlar va narxlar' },\n        { title: 'Ishga tushirish' },\n      ]}\n    />\n  );\n}\n" },
  "archive/v0.3/switch/basic": { component: Demo676, file: "archive/v0.3/switch/basic.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchBasic() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <Switch label=\"Bildirishnomalar\" defaultChecked />\n      <Switch label=\"Avtomatik saqlash\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/switch/controlled": { component: Demo677, file: "archive/v0.3/switch/controlled.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SwitchControlled() {\n  const [open, setOpen] = useState(true);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Switch label=\"Do'kon ochiq\" checked={open} onCheckedChange={setOpen} />\n      <span className=\"text-sm text-text-muted\">\n        {open ? 'Buyurtmalar qabul qilinmoqda' : \"Buyurtmalar to'xtatilgan\"}\n      </span>\n    </div>\n  );\n}\n" },
  "archive/v0.3/switch/description": { component: Demo678, file: "archive/v0.3/switch/description.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchDescription() {\n  return (\n    <div className=\"flex max-w-sm flex-col gap-4\">\n      <Switch label=\"Qorong'i mavzu\" description=\"Tizim sozlamasidan qat'i nazar\" defaultChecked />\n      <Switch size=\"sm\" label=\"Ovozli signal\" description=\"Yangi buyurtma kelganda\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/switch/sizes": { component: Demo679, file: "archive/v0.3/switch/sizes.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-8\">\n      <Switch size=\"sm\" label=\"Kichik · 32×18\" defaultChecked />\n      <Switch size=\"md\" label=\"O'rta · 40×24\" defaultChecked />\n    </div>\n  );\n}\n" },
  "archive/v0.3/switch/states": { component: Demo680, file: "archive/v0.3/switch/states.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchStates() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <Switch label=\"O'chirilgan\" disabled />\n      <Switch label=\"O'chirilgan, yoqilgan\" disabled defaultChecked />\n      <Switch label=\"Xato\" invalid />\n    </div>\n  );\n}\n" },
  "archive/v0.3/switch/with-field": { component: Demo681, file: "archive/v0.3/switch/with-field.tsx", source: "'use client';\n\nimport { Field, Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchWithField() {\n  return (\n    <div className=\"max-w-sm\">\n      <Field label=\"Ikki bosqichli tasdiqlash\" description=\"Har kirishda SMS kod so'raladi\">\n        <Switch />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/tabs/badges": { component: Demo682, file: "archive/v0.3/tabs/badges.tsx", source: "'use client';\n\nimport { Badge, Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsBadges() {\n  return (\n    <Tabs defaultValue=\"new\">\n      <Tabs.List aria-label=\"Buyurtmalar holati\">\n        <Tabs.Trigger value=\"new\" badge={4}>\n          Yangi\n        </Tabs.Trigger>\n        <Tabs.Trigger\n          value=\"paid\"\n          badge={\n            <Badge color=\"success\" size=\"sm\">\n              +2\n            </Badge>\n          }\n        >\n          To'langan\n        </Tabs.Trigger>\n        <Tabs.Trigger value=\"canceled\" disabled>\n          Bekor qilingan\n        </Tabs.Trigger>\n      </Tabs.List>\n    </Tabs>\n  );\n}\n" },
  "archive/v0.3/tabs/controlled": { component: Demo683, file: "archive/v0.3/tabs/controlled.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst totals: Record<string, string> = {\n  day: \"1 250 000 so'm\",\n  week: \"8 740 000 so'm\",\n  month: \"36 900 000 so'm\",\n  year: \"412 500 000 so'm\",\n};\n\nexport default function TabsControlled() {\n  const [period, setPeriod] = useState('week');\n\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <Tabs value={period} onValueChange={setPeriod} variant=\"segmented\">\n        <Tabs.List aria-label=\"Davr\">\n          <Tabs.Trigger value=\"day\">Kun</Tabs.Trigger>\n          <Tabs.Trigger value=\"week\">Hafta</Tabs.Trigger>\n          <Tabs.Trigger value=\"month\">Oy</Tabs.Trigger>\n          <Tabs.Trigger value=\"year\">Yil</Tabs.Trigger>\n        </Tabs.List>\n      </Tabs>\n      <p className=\"m-0 text-sm text-text-muted\">\n        Savdo: <span className=\"font-semibold text-text\">{totals[period]}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/tabs/scrollable": { component: Demo684, file: "archive/v0.3/tabs/scrollable.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nconst months = [\n  'Yanvar',\n  'Fevral',\n  'Mart',\n  'Aprel',\n  'May',\n  'Iyun',\n  'Iyul',\n  'Avgust',\n  'Sentabr',\n  'Oktabr',\n  'Noyabr',\n  'Dekabr',\n];\n\nexport default function TabsScrollable() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Tabs defaultValue=\"Mart\">\n        <Tabs.List aria-label=\"Oylar\">\n          {months.map((m) => (\n            <Tabs.Trigger key={m} value={m}>\n              {m}\n            </Tabs.Trigger>\n          ))}\n        </Tabs.List>\n        {months.map((m) => (\n          <Tabs.Content key={m} value={m} className=\"text-text-muted\">\n            {m} oyi bo'yicha savdo hisoboti.\n          </Tabs.Content>\n        ))}\n      </Tabs>\n    </div>\n  );\n}\n" },
  "archive/v0.3/tabs/sizes": { component: Demo685, file: "archive/v0.3/tabs/sizes.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsSizes() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      {(['underline', 'pills', 'segmented'] as const).map((variant) => (\n        <Tabs key={variant} defaultValue=\"all\" variant={variant} size=\"sm\">\n          <Tabs.List aria-label=\"Holat bo'yicha\">\n            <Tabs.Trigger value=\"all\">Hammasi</Tabs.Trigger>\n            <Tabs.Trigger value=\"active\">Faol</Tabs.Trigger>\n            <Tabs.Trigger value=\"archive\">Arxiv</Tabs.Trigger>\n          </Tabs.List>\n        </Tabs>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/tabs/variants": { component: Demo686, file: "archive/v0.3/tabs/variants.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsVariants() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      {(['underline', 'pills', 'segmented'] as const).map((variant) => (\n        <Tabs key={variant} defaultValue=\"info\" variant={variant}>\n          <Tabs.List aria-label={`Mijoz (${variant})`}>\n            <Tabs.Trigger value=\"info\">Ma'lumot</Tabs.Trigger>\n            <Tabs.Trigger value=\"orders\" badge={12}>\n              Buyurtmalar\n            </Tabs.Trigger>\n            <Tabs.Trigger value=\"reviews\">Sharhlar</Tabs.Trigger>\n          </Tabs.List>\n          <Tabs.Content value=\"info\" className=\"text-text-muted\">\n            Ism, telefon va yetkazib berish manzili.\n          </Tabs.Content>\n          <Tabs.Content value=\"orders\" className=\"text-text-muted\">\n            Oxirgi 12 ta buyurtma ro'yxati.\n          </Tabs.Content>\n          <Tabs.Content value=\"reviews\" className=\"text-text-muted\">\n            Mijoz hali sharh qoldirmagan.\n          </Tabs.Content>\n        </Tabs>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/tabs/vertical": { component: Demo687, file: "archive/v0.3/tabs/vertical.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsVertical() {\n  return (\n    <Tabs defaultValue=\"profile\" orientation=\"vertical\" variant=\"pills\" className=\"w-full\">\n      <Tabs.List aria-label=\"Sozlamalar\" className=\"w-44\">\n        <Tabs.Trigger value=\"profile\">Profil</Tabs.Trigger>\n        <Tabs.Trigger value=\"security\">Xavfsizlik</Tabs.Trigger>\n        <Tabs.Trigger value=\"notifications\" badge={3}>\n          Bildirishnomalar\n        </Tabs.Trigger>\n        <Tabs.Trigger value=\"billing\" disabled>\n          To'lovlar\n        </Tabs.Trigger>\n      </Tabs.List>\n      <Tabs.Content value=\"profile\" className=\"text-text-muted\">\n        Ism, familiya va profil rasmi.\n      </Tabs.Content>\n      <Tabs.Content value=\"security\" className=\"text-text-muted\">\n        Parol va ikki bosqichli tasdiqlash.\n      </Tabs.Content>\n      <Tabs.Content value=\"notifications\" className=\"text-text-muted\">\n        SMS, email va Telegram orqali bildirishnomalar.\n      </Tabs.Content>\n    </Tabs>\n  );\n}\n" },
  "archive/v0.3/textarea/auto-resize": { component: Demo688, file: "archive/v0.3/textarea/auto-resize.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaAutoResize() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea\n        autoResize\n        minRows={2}\n        maxRows={6}\n        placeholder=\"Yozib ko'ring — maydon matn bilan birga o'sadi\"\n        aria-label=\"Xabar\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/textarea/basic": { component: Demo689, file: "archive/v0.3/textarea/basic.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaBasic() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea placeholder=\"Buyurtma haqida izoh qoldiring\" aria-label=\"Izoh\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/textarea/count": { component: Demo690, file: "archive/v0.3/textarea/count.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function TextareaCount() {\n  const [bio, setBio] = useState(\n    'Frontend dasturchi, Toshkent. React va TypeScript bilan ishlayman.',\n  );\n\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea\n        showCount\n        maxLength={120}\n        value={bio}\n        onChange={(e) => setBio(e.target.value)}\n        aria-label=\"O'zingiz haqingizda\"\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/textarea/states": { component: Demo691, file: "archive/v0.3/textarea/states.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaStates() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-3 sm:grid-cols-2\">\n      <Textarea minRows={2} invalid defaultValue=\"Juda qisqa\" aria-label=\"Xato\" />\n      <Textarea minRows={2} disabled defaultValue=\"O'chirilgan\" aria-label=\"O'chirilgan\" />\n      <Textarea minRows={2} readOnly defaultValue=\"Faqat o'qish uchun\" aria-label=\"Faqat o'qish\" />\n      <Textarea minRows={2} size=\"sm\" placeholder=\"Kichik o'lcham\" aria-label=\"Kichik\" />\n    </div>\n  );\n}\n" },
  "archive/v0.3/textarea/with-field": { component: Demo692, file: "archive/v0.3/textarea/with-field.tsx", source: "'use client';\n\nimport { Field, Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaWithField() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Field label=\"Izoh\" required description=\"Kuryer uchun qo'shimcha ma'lumot\">\n        <Textarea\n          autoResize\n          showCount\n          maxLength={300}\n          placeholder=\"Masalan: 3-podyezd, domofon ishlamaydi\"\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "archive/v0.3/theming/brand": { component: Demo693, file: "archive/v0.3/theming/brand.tsx", source: "'use client';\n\nimport { Badge, Button, Field, Input, Switch } from '@akhatmirzo/ui';\nimport { useState, type CSSProperties } from 'react';\n\nconst BRANDS = ['indigo', 'emerald', 'sky', 'rose'] as const;\n\n// Brend rangini faqat shu blok ichida almashtiramiz. color-mix — light va dark'da birdek ishlaydi.\nconst brandVars = (c: string) =>\n  ({\n    '--ak-primary': `var(--ak-${c}-600)`,\n    '--ak-primary-hover': `var(--ak-${c}-700)`,\n    '--ak-primary-soft': `color-mix(in srgb, var(--ak-${c}-500) 14%, var(--ak-surface))`,\n    '--ak-primary-soft-hover': `color-mix(in srgb, var(--ak-${c}-500) 22%, var(--ak-surface))`,\n    '--ak-primary-soft-foreground': `color-mix(in srgb, var(--ak-${c}-600) 65%, var(--ak-text))`,\n    '--ak-ring': `color-mix(in srgb, var(--ak-${c}-500) 45%, transparent)`,\n  }) as CSSProperties;\n\nexport default function ThemingBrand() {\n  const [brand, setBrand] = useState<(typeof BRANDS)[number]>('emerald');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <div className=\"flex flex-wrap gap-2\">\n        {BRANDS.map((b) => (\n          <Button\n            key={b}\n            size=\"sm\"\n            variant={b === brand ? 'outline' : 'ghost'}\n            onClick={() => setBrand(b)}\n          >\n            {b}\n          </Button>\n        ))}\n      </div>\n      <div\n        style={brandVars(brand)}\n        className=\"flex flex-col gap-4 rounded-xl border border-border bg-surface p-5\"\n      >\n        <Field label=\"Telefon\">\n          <Input placeholder=\"+998 90 123 45 67\" />\n        </Field>\n        <Switch defaultChecked label=\"Yangiliklarga obuna\" />\n        <div className=\"flex flex-wrap items-center gap-2\">\n          <Button variant=\"primary\">Saqlash</Button>\n          <Button>Bekor qilish</Button>\n          <Badge color=\"primary\">Yangi</Badge>\n        </div>\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/theming/motion": { component: Demo694, file: "archive/v0.3/theming/motion.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst EASINGS = [\n  ['ease-out', 'Kirishlar (asosiy)'],\n  ['ease-in', 'Chiqishlar'],\n  ['ease-in-out', \"Joyida o'zgarish\"],\n  ['ease-spring', 'Toast, switch'],\n];\n\nexport default function ThemingMotion() {\n  const [on, setOn] = useState(false);\n\n  return (\n    <div className=\"flex w-full max-w-lg flex-col gap-4\">\n      <Button size=\"sm\" variant=\"primary\" className=\"self-start\" onClick={() => setOn((v) => !v)}>\n        {on ? 'Qaytarish' : 'Ishga tushirish'}\n      </Button>\n      {EASINGS.map(([easing, note]) => (\n        <div key={easing} className=\"flex items-center gap-3\">\n          <div className=\"flex w-28 shrink-0 flex-col text-xs\">\n            <code className=\"font-mono text-text\">{easing}</code>\n            <span className=\"text-text-muted\">{note}</span>\n          </div>\n          <div className=\"relative h-6 flex-1 rounded-full bg-surface-muted\">\n            {/* Qatlam kengligi = yo'lak − sharcha, shuning uchun translate-x-full oxirigacha olib boradi */}\n            <div\n              className={`absolute inset-y-0 left-0 w-[calc(100%-1.5rem)] transition-transform duration-slow ${easing} ${on ? 'translate-x-full' : ''}`}\n            >\n              <div className=\"size-6 rounded-full bg-primary\" />\n            </div>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/theming/palette": { component: Demo695, file: "archive/v0.3/theming/palette.tsx", source: "'use client';\n\nimport { useSyncExternalStore } from 'react';\n\nconst SCALES = {\n  indigo: ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900', '950'],\n  slate: ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900', '950'],\n  emerald: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  amber: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  rose: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  sky: ['50', '100', '300', '400', '500', '600', '700', '950'],\n};\n\nconst subscribe = () => () => {};\n// CSS o'zgaruvchilarning haqiqiy qiymatlari (serverda — bo'sh)\nconst readValues = () => {\n  const style = getComputedStyle(document.documentElement);\n  return Object.entries(SCALES)\n    .flatMap(([name, steps]) =>\n      steps.map((s) => style.getPropertyValue(`--ak-${name}-${s}`).trim()),\n    )\n    .join(',');\n};\n\nexport default function ThemingPalette() {\n  const values = useSyncExternalStore(subscribe, readValues, () => '').split(',');\n  let index = 0;\n\n  return (\n    <div className=\"flex w-full flex-col gap-5\">\n      {Object.entries(SCALES).map(([name, steps]) => (\n        <div key={name} className=\"flex flex-col gap-2\">\n          <span className=\"text-sm font-semibold text-text\">{name}</span>\n          <div className=\"grid grid-cols-4 gap-2 sm:grid-cols-6 lg:grid-cols-11\">\n            {steps.map((step) => {\n              const value = values[index++];\n              return (\n                <div key={step} className=\"flex flex-col gap-1\">\n                  <div\n                    className=\"h-10 rounded-md border border-border\"\n                    style={{ background: `var(--ak-${name}-${step})` }}\n                  />\n                  <span className=\"text-xs font-medium text-text\">{step}</span>\n                  <span className=\"font-mono text-xs text-text-muted uppercase\">{value}</span>\n                </div>\n              );\n            })}\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/theming/radius-shadow": { component: Demo696, file: "archive/v0.3/theming/radius-shadow.tsx", source: "'use client';\n\nconst RADII = [\n  ['rounded-sm', '6px'],\n  ['rounded-md', '8px'],\n  ['rounded-lg', '12px'],\n  ['rounded-xl', '16px'],\n  ['rounded-2xl', '20px'],\n  ['rounded-full', '9999px'],\n];\n\nconst SHADOWS = [\n  ['shadow-xs', 'Input, tugma'],\n  ['shadow-sm', 'Karta'],\n  ['shadow-md', 'Dropdown'],\n  ['shadow-lg', 'Popover, toast'],\n  ['shadow-xl', 'Modal, drawer'],\n];\n\nexport default function ThemingRadiusShadow() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      <div className=\"grid grid-cols-3 gap-4 sm:grid-cols-6\">\n        {RADII.map(([className, value]) => (\n          <div key={className} className=\"flex flex-col items-center gap-2 text-xs\">\n            <div className={`size-14 border-2 border-primary bg-primary-soft ${className}`} />\n            <code className=\"font-mono text-text\">{className}</code>\n            <span className=\"text-text-muted\">{value}</span>\n          </div>\n        ))}\n      </div>\n      <div className=\"grid grid-cols-2 gap-5 sm:grid-cols-5\">\n        {SHADOWS.map(([className, note]) => (\n          <div\n            key={className}\n            className={`flex h-20 flex-col items-center justify-center rounded-xl bg-surface-raised text-xs ${className}`}\n          >\n            <code className=\"font-mono text-text\">{className}</code>\n            <span className=\"text-text-muted\">{note}</span>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n" },
  "archive/v0.3/theming/scoped": { component: Demo697, file: "archive/v0.3/theming/scoped.tsx", source: "'use client';\n\nimport { Badge, Button, Field, Input } from '@akhatmirzo/ui';\n\n// data-theme istalgan elementga qo'yiladi — tokenlar faqat shu blok ichida almashadi\nexport default function ThemingScoped() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-2\">\n      {(['light', 'dark'] as const).map((theme) => (\n        <div\n          key={theme}\n          data-theme={theme}\n          className=\"flex flex-col gap-4 rounded-xl border border-border bg-background p-5 text-text\"\n        >\n          <div className=\"flex items-center justify-between\">\n            <span className=\"text-sm font-semibold\">data-theme=\"{theme}\"</span>\n            <Badge color=\"success\" dot>\n              Faol\n            </Badge>\n          </div>\n          <Field label=\"Ism\">\n            <Input placeholder=\"Sarvar\" />\n          </Field>\n          <div className=\"flex gap-2\">\n            <Button variant=\"primary\">Saqlash</Button>\n            <Button variant=\"outline\">Bekor qilish</Button>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/theming/semantic": { component: Demo698, file: "archive/v0.3/theming/semantic.tsx", source: "'use client';\n\nimport { useSyncExternalStore } from 'react';\n\nconst TOKENS = [\n  ['background', 'Sahifa foni'],\n  ['surface', 'Karta, input, modal'],\n  ['surface-muted', 'Hover, ikkilamchi fon'],\n  ['surface-raised', 'Popover, toast'],\n  ['border', 'Oddiy chegara'],\n  ['border-strong', 'Hover chegara'],\n  ['text', 'Asosiy matn'],\n  ['text-subtle', 'Ghost tugma, ikonka'],\n  ['text-muted', 'Yordamchi matn'],\n  ['text-faint', 'Placeholder'],\n  ['primary', 'Asosiy tugma'],\n  ['primary-soft', 'Soft tugma, badge'],\n  ['primary-soft-foreground', 'Soft ustidagi matn'],\n  ['link', 'Havola'],\n  ['danger', 'Xavfli tugma'],\n  ['ring', 'Fokus halqasi'],\n] as const;\n\n// Mavzu almashganda (<html data-theme>) qiymatlar qayta o'qiladi\nconst subscribe = (onChange: () => void) => {\n  const observer = new MutationObserver(onChange);\n  observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });\n  return () => observer.disconnect();\n};\nconst readValues = () => {\n  const style = getComputedStyle(document.documentElement);\n  return TOKENS.map(([token]) => style.getPropertyValue(`--ak-${token}`).trim()).join('|');\n};\n\nexport default function ThemingSemantic() {\n  const values = useSyncExternalStore(subscribe, readValues, () => '').split('|');\n\n  return (\n    <div className=\"grid w-full gap-3 sm:grid-cols-2\">\n      {TOKENS.map(([token, note], i) => (\n        <div key={token} className=\"flex items-center gap-3\">\n          <div\n            className=\"size-10 shrink-0 rounded-lg border border-border\"\n            style={{ background: `var(--ak-${token})` }}\n          />\n          <div className=\"flex min-w-0 flex-col text-xs\">\n            <span className=\"truncate font-mono font-medium text-text\">{token}</span>\n            <span className=\"truncate text-text-muted\">{note}</span>\n            <span className=\"truncate font-mono text-text-faint\">{values[i] || '—'}</span>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/theming/status": { component: Demo699, file: "archive/v0.3/theming/status.tsx", source: "'use client';\n\nconst STATUSES = ['success', 'warning', 'danger', 'info'] as const;\n\nconst SOFT = {\n  success: 'bg-success-soft text-success-soft-foreground',\n  warning: 'bg-warning-soft text-warning-soft-foreground',\n  danger: 'bg-danger-soft text-danger-soft-foreground',\n  info: 'bg-info-soft text-info-soft-foreground',\n};\nconst SOLID = {\n  success: 'bg-success text-success-foreground',\n  warning: 'bg-warning text-warning-foreground',\n  danger: 'bg-danger text-danger-foreground',\n  info: 'bg-info text-info-foreground',\n};\n\nexport default function ThemingStatus() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      {[SOFT, SOLID].map((styles, row) => (\n        <div key={row} className=\"flex flex-wrap items-center gap-2\">\n          <code className=\"w-12 font-mono text-xs text-text-muted\">\n            {row === 0 ? 'soft' : 'solid'}\n          </code>\n          {STATUSES.map((status) => (\n            <span\n              key={status}\n              className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${styles[status]}`}\n            >\n              {status}\n            </span>\n          ))}\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/theming/typography": { component: Demo700, file: "archive/v0.3/theming/typography.tsx", source: "'use client';\n\nconst SCALE = [\n  { className: 'text-4xl font-bold', name: 'text-4xl', spec: '36 / 40' },\n  { className: 'text-3xl font-bold', name: 'text-3xl', spec: '30 / 36' },\n  { className: 'text-2xl font-semibold', name: 'text-2xl', spec: '24 / 32' },\n  { className: 'text-xl font-semibold', name: 'text-xl', spec: '20 / 28' },\n  { className: 'text-lg font-medium', name: 'text-lg', spec: '18 / 28' },\n  { className: 'text-base', name: 'text-base', spec: '16 / 24' },\n  { className: 'text-sm', name: 'text-sm', spec: '14 / 20' },\n  { className: 'text-xs font-medium', name: 'text-xs', spec: '12 / 16' },\n];\n\nexport default function ThemingTypography() {\n  return (\n    <div className=\"flex w-full flex-col divide-y divide-border\">\n      {SCALE.map((item) => (\n        <div key={item.name} className=\"flex items-baseline gap-4 py-2\">\n          <div className=\"flex w-24 shrink-0 flex-col\">\n            <code className=\"font-mono text-xs text-text\">{item.name}</code>\n            <span className=\"text-xs text-text-muted\">{item.spec}</span>\n          </div>\n          <p className={`${item.className} truncate text-text`}>O'zbekiston — Ўзбекистон</p>\n        </div>\n      ))}\n      <p className=\"pt-3 font-mono text-sm text-text-muted\">font-mono: 1 250 000 so'm · +998 90</p>\n    </div>\n  );\n}\n" },
  "archive/v0.3/toast/action": { component: Demo701, file: "archive/v0.3/toast/action.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastAction() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.success('Buyurtma yaratildi', {\n            description: \"#1042 · 1 250 000 so'm\",\n            action: { label: \"Ko'rish\", onClick: () => toast.info('Buyurtma #1042 ochildi') },\n          })\n        }\n      >\n        Amal bilan\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast(\"Mahsulot o'chirildi\", {\n            description: 'iPhone 15 Pro, 256 GB',\n            action: {\n              label: 'Qaytarish',\n              onClick: () => toast.success('Mahsulot qaytarildi'),\n            },\n          })\n        }\n      >\n        Bekor qilish (undo)\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/toast/promise": { component: Demo702, file: "archive/v0.3/toast/promise.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nasync function saveOrder() {\n  await wait(1500);\n  return 1042;\n}\n\nasync function failingRequest(): Promise<void> {\n  await wait(1200);\n  throw new Error('Server javob bermadi');\n}\n\nexport default function ToastPromise() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.promise(saveOrder, {\n            loading: 'Saqlanmoqda...',\n            success: (id) => `Buyurtma #${id} saqlandi`,\n            error: 'Xatolik yuz berdi',\n          })\n        }\n      >\n        Muvaffaqiyatli\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast\n            .promise(failingRequest, {\n              loading: 'Yuborilmoqda...',\n              success: 'Yuborildi',\n              error: (e) => `Xatolik: ${(e as Error).message}`,\n            })\n            .catch(() => {})\n        }\n      >\n        Xato bilan\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/toast/stack": { component: Demo703, file: "archive/v0.3/toast/stack.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastStack() {\n  const burst = () => {\n    toast.info(\"Yangi mijoz ro'yxatdan o'tdi\");\n    toast.success(\"To'lov qabul qilindi\", { description: \"350 000 so'm\" });\n    toast.warning('Omborda 3 ta qoldi');\n    toast('Yangi sharh qoldirildi');\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button variant=\"outline\" onClick={burst}>\n        4 tasini birdan\n      </Button>\n      <Button variant=\"ghost\" onClick={() => toast.dismiss()}>\n        Hammasini yopish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/toast/types": { component: Demo704, file: "archive/v0.3/toast/types.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastTypes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button variant=\"outline\" onClick={() => toast('Havola nusxalandi')}>\n        Oddiy\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.success(\"O'zgarishlar saqlandi\")}>\n        success\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.error(\"Ulanib bo'lmadi\", {\n            description: \"Internetni tekshirib, qayta urinib ko'ring.\",\n          })\n        }\n      >\n        error\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.warning('Obuna 3 kundan keyin tugaydi', {\n            description: \"To'lovni oldindan qiling.\",\n          })\n        }\n      >\n        warning\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.info('Yangi versiya mavjud')}>\n        info\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.loading('Hisobot tayyorlanmoqda...')}>\n        loading\n      </Button>\n      <Button variant=\"ghost\" onClick={() => toast.dismiss()}>\n        Hammasini yopish\n      </Button>\n    </div>\n  );\n}\n" },
  "archive/v0.3/toast/update": { component: Demo705, file: "archive/v0.3/toast/update.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function ToastUpdate() {\n  const upload = async () => {\n    const id = toast.loading('Fayl yuklanmoqda...', { description: 'hisobot.xlsx' });\n    await wait(1000);\n    toast.loading('Fayl tekshirilmoqda...', { id, description: 'hisobot.xlsx' });\n    await wait(1000);\n    toast.success('Fayl yuklandi', { id, description: 'hisobot.xlsx · 2,4 MB' });\n  };\n\n  return (\n    <Button variant=\"outline\" onClick={upload}>\n      Faylni yuklash\n    </Button>\n  );\n}\n" },
  "archive/v0.3/tooltip/basic": { component: Demo706, file: "archive/v0.3/tooltip/basic.tsx", source: "'use client';\n\nimport { IconButton, Tooltip } from '@akhatmirzo/ui';\nimport { Copy, Heart, Share2, Trash2 } from 'lucide-react';\n\nexport default function TooltipBasic() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Tooltip content=\"Nusxa olish\" shortcut={['mod', 'C']}>\n        <IconButton variant=\"outline\" aria-label=\"Nusxa olish\">\n          <Copy />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"Ulashish\">\n        <IconButton variant=\"outline\" aria-label=\"Ulashish\">\n          <Share2 />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"Sevimlilarga qo'shish\">\n        <IconButton variant=\"outline\" aria-label=\"Sevimlilarga qo'shish\">\n          <Heart />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"O'chirish\" shortcut={['Del']}>\n        <IconButton variant=\"ghost\" aria-label=\"O'chirish\">\n          <Trash2 />\n        </IconButton>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "archive/v0.3/tooltip/controlled": { component: Demo707, file: "archive/v0.3/tooltip/controlled.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function TooltipControlled() {\n  const [open, setOpen] = useState(false);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"outline\" onClick={() => setOpen((o) => !o)}>\n        {open ? 'Yashirish' : \"Ko'rsatish\"}\n      </Button>\n      <Tooltip content=\"Boshqariladigan tooltip\" open={open} onOpenChange={setOpen}>\n        <Button>Nishon</Button>\n      </Tooltip>\n      <Tooltip content=\"Bu matn chiqmaydi\" disabled>\n        <Button>disabled</Button>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "archive/v0.3/tooltip/delay": { component: Demo708, file: "archive/v0.3/tooltip/delay.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipDelay() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Tooltip content=\"Darhol chiqadi\" delay={0}>\n        <Button>delay=0</Button>\n      </Tooltip>\n      <Tooltip content=\"Bir soniya kutadi\" delay={1000}>\n        <Button>delay=1000</Button>\n      </Tooltip>\n      <Tooltip content=\"Uzun izoh 240px dan oshsa, keyingi qatorga o'raladi: buyurtma holati har 5 daqiqada yangilanadi.\">\n        <Button>Uzun matn</Button>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "archive/v0.3/tooltip/disabled-button": { component: Demo709, file: "archive/v0.3/tooltip/disabled-button.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipDisabledButton() {\n  return (\n    <Tooltip content=\"Ruxsat yo'q: faqat administrator saqlay oladi\">\n      <span tabIndex={0} className=\"focus-ring inline-flex rounded-lg\">\n        <Button variant=\"primary\" disabled>\n          Saqlash\n        </Button>\n      </span>\n    </Tooltip>\n  );\n}\n" },
  "archive/v0.3/tooltip/sides": { component: Demo710, file: "archive/v0.3/tooltip/sides.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipSides() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {(['top', 'right', 'bottom', 'left'] as const).map((side) => (\n        <Tooltip key={side} content={`Tomon: ${side}`} side={side}>\n          <Button variant=\"outline\">{side}</Button>\n        </Tooltip>\n      ))}\n    </div>\n  );\n}\n" },
  "archive/v0.3/virtual-list/basic": { component: Demo711, file: "archive/v0.3/virtual-list/basic.tsx", source: "'use client';\n\nimport { Badge, Button, Input, VirtualList, type VirtualListHandle } from '@akhatmirzo/ui';\nimport { useMemo, useRef, useState } from 'react';\n\nconst LEVELS = [\n  { label: 'Info', color: 'info', text: 'Foydalanuvchi tizimga kirdi' },\n  { label: 'Tayyor', color: 'success', text: \"To'lov qabul qilindi\" },\n  { label: 'Ogohlantirish', color: 'warning', text: 'Omborda mahsulot kam qoldi' },\n  { label: 'Xato', color: 'danger', text: \"SMS yuborib bo'lmadi\" },\n] as const;\n\nexport default function VirtualListBasic() {\n  const logs = useMemo(\n    () => Array.from({ length: 10_000 }, (_, i) => ({ id: i + 1, ...LEVELS[i % LEVELS.length]! })),\n    [],\n  );\n  const ref = useRef<VirtualListHandle>(null);\n  const [target, setTarget] = useState('5000');\n\n  const go = () => ref.current?.scrollToIndex(Number(target) - 1, { align: 'start' });\n\n  return (\n    <div className=\"flex w-full flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Input\n          aria-label=\"Qator raqami\"\n          inputMode=\"numeric\"\n          value={target}\n          onChange={(e) => setTarget(e.target.value.replace(/\\D/g, ''))}\n          onKeyDown={(e) => e.key === 'Enter' && go()}\n          className=\"w-28\"\n        />\n        <Button variant=\"soft\" onClick={go}>\n          Qatorga o'tish\n        </Button>\n      </div>\n      <VirtualList\n        ref={ref}\n        aria-label=\"Tizim jurnali\"\n        items={logs}\n        estimateSize={48}\n        height={400}\n        overscan={8}\n        getItemKey={(log) => log.id}\n        className=\"rounded-xl border border-border bg-surface\"\n        renderItem={(log) => (\n          <div className=\"flex h-12 items-center gap-3 border-b border-border px-4 text-sm\">\n            <span className=\"w-14 shrink-0 text-text-faint tabular-nums\">#{log.id}</span>\n            <Badge color={log.color}>{log.label}</Badge>\n            <span className=\"min-w-0 flex-1 truncate\">{log.text}</span>\n          </div>\n        )}\n      />\n    </div>\n  );\n}\n" },
  "archive/v0.3/virtual-list/dynamic": { component: Demo712, file: "archive/v0.3/virtual-list/dynamic.tsx", source: "'use client';\n\nimport { Avatar, VirtualList } from '@akhatmirzo/ui';\n\nconst NAMES = ['Aziza Karimova', 'Bobur Toshmatov', \"G'ayrat Usmonov\", 'Malika Yusupova'];\nconst TEXTS = [\n  'Assalomu alaykum!',\n  \"Buyurtmam qachon yetib keladi? Kecha to'lov qilgan edim.\",\n  \"Yetkazish manzilini o'zgartirsam bo'ladimi? Hozir Samarqanddaman, kuryer oldindan qo'ng'iroq qilsin.\",\n  'Ha, albatta.',\n  \"Rahmat, mahsulot juda yoqdi. Qadoqlash ham a'lo darajada edi, do'stlarimga ham tavsiya qilaman.\",\n];\n\nconst messages = Array.from({ length: 2000 }, (_, i) => ({\n  id: i,\n  author: NAMES[(i * 3) % NAMES.length]!,\n  text: TEXTS[(i * 2 + (i >> 2)) % TEXTS.length]!,\n}));\n\nexport default function VirtualListDynamic() {\n  return (\n    <VirtualList\n      dynamic\n      aria-label=\"Mijozlar bilan yozishmalar\"\n      items={messages}\n      estimateSize={72}\n      height={400}\n      getItemKey={(m) => m.id}\n      className=\"w-full rounded-xl border border-border bg-surface\"\n      renderItem={(m) => (\n        <div className=\"flex gap-3 border-b border-border px-4 py-3\">\n          <Avatar name={m.author} size=\"sm\" />\n          <div className=\"flex min-w-0 flex-col gap-0.5\">\n            <span className=\"text-sm font-medium\">{m.author}</span>\n            <p className=\"m-0 text-sm text-text-muted\">{m.text}</p>\n          </div>\n        </div>\n      )}\n    />\n  );\n}\n" },
  "archive/v0.3/virtual-list/empty": { component: Demo713, file: "archive/v0.3/virtual-list/empty.tsx", source: "'use client';\n\nimport { VirtualList } from '@akhatmirzo/ui';\n\nexport default function VirtualListEmpty() {\n  return (\n    <VirtualList\n      aria-label=\"Bildirishnomalar\"\n      items={[]}\n      estimateSize={48}\n      height={160}\n      renderItem={() => null}\n      emptyState=\"Hali bildirishnomalar yo'q\"\n      className=\"w-full max-w-md rounded-xl border border-border bg-surface\"\n    />\n  );\n}\n" },
  "archive/v0.3/virtual-list/infinite": { component: Demo714, file: "archive/v0.3/virtual-list/infinite.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { VirtualList } from '@akhatmirzo/ui';\nimport { useCallback, useState } from 'react';\n\nconst PAGE = 40;\nconst TOTAL = 400;\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\n\nconst makeOrders = (from: number) =>\n  Array.from({ length: PAGE }, (_, i) => {\n    const id = from + i + 1;\n    return {\n      id,\n      customer: NAMES[id % NAMES.length]!,\n      total: ((id * 7919) % 90) * 15_000 + 150_000,\n    };\n  });\n\nexport default function VirtualListInfinite() {\n  const [orders, setOrders] = useState(() => makeOrders(0));\n  const [loading, setLoading] = useState(false);\n\n  const loadMore = useCallback(() => {\n    if (orders.length >= TOTAL) return;\n    setLoading(true);\n    // Haqiqiy loyihada — fetch(`/api/orders?offset=${orders.length}`)\n    setTimeout(() => {\n      setOrders((prev) => [...prev, ...makeOrders(prev.length)]);\n      setLoading(false);\n    }, 900);\n  }, [orders.length]);\n\n  return (\n    <div className=\"flex w-full flex-col gap-2\">\n      <p className=\"m-0 text-sm text-text-muted\">\n        Yuklangan: {orders.length} / {TOTAL}\n      </p>\n      <VirtualList\n        aria-label=\"Buyurtmalar\"\n        items={orders}\n        estimateSize={52}\n        height={360}\n        loadingMore={loading}\n        onEndReached={loadMore}\n        getItemKey={(o) => o.id}\n        labels={{ loadingMore: 'Buyurtmalar yuklanmoqda...' }}\n        className=\"rounded-xl border border-border bg-surface\"\n        renderItem={(o) => (\n          <div className=\"flex h-13 items-center gap-3 border-b border-border px-4 text-sm\">\n            <span className=\"w-14 shrink-0 text-text-faint tabular-nums\">№{o.id}</span>\n            <span className=\"min-w-0 flex-1 truncate\">{o.customer}</span>\n            <span className=\"shrink-0 font-medium tabular-nums\">{formatMoney(o.total)}</span>\n          </div>\n        )}\n      />\n    </div>\n  );\n}\n" },
  "avatar/basic": { component: Demo715, file: "avatar/basic.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nconst people = [\n  'Sarvar Abduxoliqov',\n  'Malika Rahimova',\n  'Jasur Karimov',\n  \"O'tkir Hoshimov\",\n  'Dilnoza Yusupova',\n  'Rustam Qodirov',\n];\n\nexport default function AvatarBasic() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {people.map((name) => (\n        <Avatar key={name} name={name} />\n      ))}\n    </div>\n  );\n}\n" },
  "avatar/group": { component: Demo716, file: "avatar/group.tsx", source: "'use client';\n\nimport { Avatar, AvatarGroup } from '@akhatmirzo/ui';\n\nconst team = [\n  'Sarvar Abduxoliqov',\n  'Malika Rahimova',\n  'Jasur Karimov',\n  'Dilnoza Yusupova',\n  'Rustam Qodirov',\n  'Gulnora Aliyeva',\n  'Bekzod Toshmatov',\n];\n\nexport default function AvatarGroupDemo() {\n  return (\n    <AvatarGroup max={4} aria-label=\"Loyiha ishtirokchilari\">\n      {team.map((name) => (\n        <Avatar key={name} name={name} />\n      ))}\n    </AvatarGroup>\n  );\n}\n" },
  "avatar/image": { component: Demo717, file: "avatar/image.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarImage() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Avatar size=\"lg\" src=\"https://github.com/Akhatmirzo.png\" name=\"Akhatmirzo\" />\n      <Avatar size=\"lg\" src=\"/mavjud-emas.png\" name=\"Gulnora Aliyeva\" />\n      <Avatar size=\"lg\" />\n    </div>\n  );\n}\n" },
  "avatar/sizes": { component: Demo718, file: "avatar/sizes.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarSizes() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Avatar size=\"xs\" name=\"Malika Rahimova\" />\n        <Avatar size=\"sm\" name=\"Malika Rahimova\" />\n        <Avatar size=\"md\" name=\"Malika Rahimova\" />\n        <Avatar size=\"lg\" name=\"Malika Rahimova\" />\n        <Avatar size=\"xl\" name=\"Malika Rahimova\" />\n      </div>\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Avatar size=\"sm\" shape=\"square\" name=\"Bahor Market\" />\n        <Avatar size=\"md\" shape=\"square\" name=\"Bahor Market\" />\n        <Avatar size=\"lg\" shape=\"square\" name=\"Bahor Market\" />\n      </div>\n    </div>\n  );\n}\n" },
  "avatar/status": { component: Demo719, file: "avatar/status.tsx", source: "'use client';\n\nimport { Avatar } from '@akhatmirzo/ui';\n\nexport default function AvatarStatus() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Avatar name=\"Sarvar Abduxoliqov\" status=\"online\" />\n      <Avatar name=\"Malika Rahimova\" status=\"offline\" />\n      <Avatar name=\"Rustam Qodirov\" status=\"busy\" />\n      <Avatar name=\"Jasur Karimov\" shape=\"square\" size=\"lg\" status=\"online\" />\n    </div>\n  );\n}\n" },
  "badge/colors": { component: Demo720, file: "badge/colors.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeColors() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge>Qoralama</Badge>\n      <Badge color=\"primary\">Yangi</Badge>\n      <Badge color=\"success\">To'langan</Badge>\n      <Badge color=\"warning\">Kutilmoqda</Badge>\n      <Badge color=\"danger\">Bekor qilindi</Badge>\n      <Badge color=\"info\">Yo'lda</Badge>\n    </div>\n  );\n}\n" },
  "badge/dot": { component: Demo721, file: "badge/dot.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeDot() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge dot color=\"success\">\n        Onlayn\n      </Badge>\n      <Badge dot color=\"warning\" variant=\"outline\">\n        Tekshirilmoqda\n      </Badge>\n      <Badge dot color=\"danger\" variant=\"solid\">\n        To'xtatilgan\n      </Badge>\n    </div>\n  );\n}\n" },
  "badge/removable": { component: Demo722, file: "badge/removable.tsx", source: "'use client';\n\nimport { Badge, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst initial = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\"];\n\nexport default function BadgeRemovable() {\n  const [cities, setCities] = useState(initial);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      {cities.map((city) => (\n        <Badge\n          key={city}\n          variant=\"outline\"\n          onRemove={() => setCities((list) => list.filter((c) => c !== city))}\n          labels={{ remove: `${city} filtrini olib tashlash` }}\n        >\n          {city}\n        </Badge>\n      ))}\n      {cities.length < initial.length && (\n        <Button variant=\"link\" size=\"sm\" onClick={() => setCities(initial)}>\n          Qaytarish\n        </Button>\n      )}\n    </div>\n  );\n}\n" },
  "badge/sizes": { component: Demo723, file: "badge/sizes.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Badge size=\"sm\" color=\"primary\">\n        Kichik\n      </Badge>\n      <Badge size=\"md\" color=\"primary\">\n        O'rta\n      </Badge>\n    </div>\n  );\n}\n" },
  "badge/variants": { component: Demo724, file: "badge/variants.tsx", source: "'use client';\n\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function BadgeVariants() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge variant=\"soft\" color=\"success\">\n          Soft\n        </Badge>\n        <Badge variant=\"solid\" color=\"success\">\n          Solid\n        </Badge>\n        <Badge variant=\"outline\" color=\"success\">\n          Outline\n        </Badge>\n      </div>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge variant=\"soft\" color=\"danger\">\n          Soft\n        </Badge>\n        <Badge variant=\"solid\" color=\"danger\">\n          Solid\n        </Badge>\n        <Badge variant=\"outline\" color=\"danger\">\n          Outline\n        </Badge>\n      </div>\n    </div>\n  );\n}\n" },
  "breadcrumb/basic": { component: Demo725, file: "breadcrumb/basic.tsx", source: "'use client';\n\nimport { Breadcrumb } from '@akhatmirzo/ui';\nimport { House } from 'lucide-react';\n\nexport default function BreadcrumbBasic() {\n  return (\n    <Breadcrumb\n      items={[\n        { label: 'Bosh sahifa', href: '#', icon: <House /> },\n        { label: 'Mahsulotlar', href: '#mahsulotlar' },\n        { label: 'Telefonlar', href: '#telefonlar' },\n        { label: 'iPhone 17' },\n      ]}\n    />\n  );\n}\n" },
  "breadcrumb/collapse": { component: Demo726, file: "breadcrumb/collapse.tsx", source: "'use client';\n\nimport { Breadcrumb } from '@akhatmirzo/ui';\nimport { House } from 'lucide-react';\n\nexport default function BreadcrumbCollapse() {\n  return (\n    <Breadcrumb\n      maxItems={4}\n      items={[\n        { label: 'Bosh sahifa', href: '#', icon: <House /> },\n        { label: 'Katalog', href: '#katalog' },\n        { label: 'Elektronika', href: '#elektronika' },\n        { label: 'Telefonlar', href: '#telefonlar' },\n        { label: 'Apple', href: '#apple' },\n        { label: 'iPhone 17 Pro Max 256 GB' },\n      ]}\n    />\n  );\n}\n" },
  "breadcrumb/separator": { component: Demo727, file: "breadcrumb/separator.tsx", source: "'use client';\n\nimport { Breadcrumb } from '@akhatmirzo/ui';\n\nconst items = [\n  { label: 'Sozlamalar', href: '#' },\n  { label: 'Hisob', href: '#hisob' },\n  { label: 'Xavfsizlik' },\n];\n\nexport default function BreadcrumbSeparator() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      <Breadcrumb items={items} separator=\"/\" />\n      <Breadcrumb items={items} size=\"sm\" />\n    </div>\n  );\n}\n" },
  "button/as-child": { component: Demo728, file: "button/as-child.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { ArrowRight } from 'lucide-react';\n\nexport default function ButtonAsChild() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button asChild variant=\"outline\" rightIcon={<ArrowRight />}>\n        <a href=\"#accessibility\">Accessibility bo'limiga</a>\n      </Button>\n      <Button asChild variant=\"link\">\n        <a href=\"https://github.com/Akhatmirzo/akhatmirzo-toolkit\">GitHub</a>\n      </Button>\n    </div>\n  );\n}\n" },
  "button/full-width": { component: Demo729, file: "button/full-width.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonFullWidth() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Button variant=\"primary\" fullWidth>\n        Kirish\n      </Button>\n      <Button variant=\"outline\" fullWidth>\n        Ro'yxatdan o'tish\n      </Button>\n    </div>\n  );\n}\n" },
  "button/icons": { component: Demo730, file: "button/icons.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { ArrowRight, Plus, Trash2 } from 'lucide-react';\n\nexport default function ButtonIcons() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\" leftIcon={<Plus />}>\n        Qo'shish\n      </Button>\n      <Button rightIcon={<ArrowRight />}>Davom etish</Button>\n      <Button variant=\"danger\" leftIcon={<Trash2 />}>\n        O'chirish\n      </Button>\n    </div>\n  );\n}\n" },
  "button/loading": { component: Demo731, file: "button/loading.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function ButtonLoading() {\n  const [saving, setSaving] = useState(false);\n\n  const save = () => {\n    setSaving(true);\n    setTimeout(() => {\n      setSaving(false);\n      toast.success('Saqlandi');\n    }, 1500);\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\" loading={saving} onClick={save}>\n        Saqlash\n      </Button>\n      <Button variant=\"outline\" loading labels={{ loading: 'Yuborilmoqda' }}>\n        Yuborish\n      </Button>\n      <Button disabled>O'chirilgan</Button>\n    </div>\n  );\n}\n" },
  "button/sizes": { component: Demo732, file: "button/sizes.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button size=\"sm\">Kichik · 32</Button>\n      <Button size=\"md\">O'rta · 40</Button>\n      <Button size=\"lg\">Katta · 48</Button>\n    </div>\n  );\n}\n" },
  "button/variants": { component: Demo733, file: "button/variants.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\n\nexport default function ButtonVariants() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"primary\">Saqlash</Button>\n      <Button>Soft</Button>\n      <Button variant=\"outline\">Outline</Button>\n      <Button variant=\"ghost\">Ghost</Button>\n      <Button variant=\"danger\">O'chirish</Button>\n      <Button variant=\"link\">Batafsil</Button>\n    </div>\n  );\n}\n" },
  "card/basic": { component: Demo734, file: "card/basic.tsx", source: "'use client';\n\nimport { Avatar, Badge, Button, Card } from '@akhatmirzo/ui';\n\nexport default function CardBasic() {\n  return (\n    <Card className=\"w-full max-w-md\">\n      <Card.Header\n        title=\"Buyurtma #1042\"\n        description=\"Bugun, 14:20\"\n        action={\n          <Badge color=\"primary\" dot>\n            Yangi\n          </Badge>\n        }\n      />\n      <Card.Body>\n        <div className=\"flex items-center gap-3\">\n          <Avatar name=\"Sarvar Abduxoliqov\" size=\"sm\" />\n          <div className=\"flex flex-col\">\n            <span className=\"font-medium\">Sarvar Abduxoliqov</span>\n            <span className=\"text-text-muted\">3 ta mahsulot · 245 000 so'm</span>\n          </div>\n        </div>\n      </Card.Body>\n      <Card.Footer className=\"justify-end\">\n        <Button variant=\"ghost\">Bekor qilish</Button>\n        <Button variant=\"primary\">Tasdiqlash</Button>\n      </Card.Footer>\n    </Card>\n  );\n}\n" },
  "card/interactive": { component: Demo735, file: "card/interactive.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nconst reports = [\n  { title: 'Sotuvlar', description: \"Oktyabr · 48 250 000 so'm\" },\n  { title: 'Mijozlar', description: '1 204 ta faol mijoz' },\n];\n\nexport default function CardInteractive() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-2\">\n      {reports.map((report) => (\n        <Card key={report.title} variant=\"outline\" interactive asChild>\n          <a href=\"#props\">\n            <Card.Header title={report.title} description={report.description} />\n          </a>\n        </Card>\n      ))}\n    </div>\n  );\n}\n" },
  "card/media": { component: Demo736, file: "card/media.tsx", source: "'use client';\n\nimport { Badge, Card } from '@akhatmirzo/ui';\n\nexport default function CardMedia() {\n  return (\n    <Card padding=\"none\" className=\"w-full max-w-sm overflow-hidden\">\n      <div className=\"h-32 bg-linear-to-br from-primary to-info\" />\n      <div className=\"flex flex-col gap-3 p-6\">\n        <Card.Header title=\"Samarqand bo'ylab sayohat\" description=\"2 kun · 4 ta joy\" />\n        <Card.Footer>\n          <Badge color=\"success\" size=\"sm\">\n            Joy bor\n          </Badge>\n          <Badge size=\"sm\">Guruh</Badge>\n        </Card.Footer>\n      </div>\n    </Card>\n  );\n}\n" },
  "card/padding": { component: Demo737, file: "card/padding.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nconst paddings = [\n  { padding: 'sm', px: 16 },\n  { padding: 'md', px: 24 },\n  { padding: 'lg', px: 32 },\n] as const;\n\nexport default function CardPadding() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-3\">\n      {paddings.map(({ padding, px }) => (\n        <Card key={padding} variant=\"outline\" padding={padding}>\n          <div className=\"rounded-md bg-primary-soft p-2 text-xs font-medium text-primary-soft-foreground\">\n            {padding} · {px}px\n          </div>\n        </Card>\n      ))}\n    </div>\n  );\n}\n" },
  "card/variants": { component: Demo738, file: "card/variants.tsx", source: "'use client';\n\nimport { Card } from '@akhatmirzo/ui';\n\nexport default function CardVariants() {\n  return (\n    <div className=\"grid w-full grid-cols-1 gap-4 sm:grid-cols-3\">\n      <Card variant=\"elevated\" padding=\"sm\">\n        <Card.Header title=\"Elevated\" description=\"Soya va chegara (standart)\" />\n      </Card>\n      <Card variant=\"outline\" padding=\"sm\">\n        <Card.Header title=\"Outline\" description=\"Faqat chegara\" />\n      </Card>\n      <Card variant=\"soft\" padding=\"sm\">\n        <Card.Header title=\"Soft\" description=\"Och kulrang fon\" />\n      </Card>\n    </div>\n  );\n}\n" },
  "charts/area": { component: Demo739, file: "charts/area.tsx", source: "'use client';\n\nimport { AreaChart } from '@akhatmirzo/ui/charts';\n\nconst sales = [\n  { month: 'Yan', tushum: 42_500_000, xarajat: 28_300_000 },\n  { month: 'Fev', tushum: 38_900_000, xarajat: 26_100_000 },\n  { month: 'Mar', tushum: 51_200_000, xarajat: 30_400_000 },\n  { month: 'Apr', tushum: 47_800_000, xarajat: 31_900_000 },\n  { month: 'May', tushum: 58_300_000, xarajat: 33_200_000 },\n  { month: 'Iyn', tushum: 63_100_000, xarajat: 35_700_000 },\n];\n\n/** Qisqa ko'rinish: 42,5 mln so'm */\nconst short = (v: number) => `${(v / 1_000_000).toFixed(1).replace('.', ',')} mln so'm`;\n\nexport default function ChartsArea() {\n  return (\n    <AreaChart\n      aria-label=\"Oylik tushum va xarajat, yanvar–iyun\"\n      className=\"w-full\"\n      data={sales}\n      index=\"month\"\n      series={[\n        { key: 'tushum', label: 'Tushum' },\n        { key: 'xarajat', label: 'Xarajat', color: 'amber' },\n      ]}\n      valueFormat={short}\n      height={280}\n    />\n  );\n}\n" },
  "charts/bar-horizontal": { component: Demo740, file: "charts/bar-horizontal.tsx", source: "'use client';\n\nimport { BarChart } from '@akhatmirzo/ui/charts';\n\nconst products = [\n  { name: 'Smartfonlar', tushum: 184_000_000 },\n  { name: 'Noutbuklar', tushum: 142_500_000 },\n  { name: 'Quloqchinlar', tushum: 61_200_000 },\n  { name: 'Aqlli soatlar', tushum: 48_900_000 },\n  { name: 'Aksessuarlar', tushum: 23_400_000 },\n];\n\nconst short = (v: number) => `${Math.round(v / 1_000_000)} mln so'm`;\n\nexport default function ChartsBarHorizontal() {\n  return (\n    <BarChart\n      aria-label=\"Eng ko'p sotilgan toifalar, tushum bo'yicha\"\n      className=\"w-full\"\n      data={products}\n      index=\"name\"\n      series={[{ key: 'tushum', label: 'Tushum', color: 'emerald' }]}\n      valueFormat={short}\n      orientation=\"horizontal\"\n      legend={false}\n      height={240}\n    />\n  );\n}\n" },
  "charts/bar": { component: Demo741, file: "charts/bar.tsx", source: "'use client';\n\nimport { formatNumber } from '@akhatmirzo/core';\nimport { BarChart } from '@akhatmirzo/ui/charts';\n\nconst orders = [\n  { region: 'Toshkent', onlayn: 1240, dokon: 860 },\n  { region: 'Samarqand', onlayn: 610, dokon: 540 },\n  { region: \"Farg'ona\", onlayn: 480, dokon: 520 },\n  { region: 'Buxoro', onlayn: 350, dokon: 290 },\n  { region: 'Namangan', onlayn: 410, dokon: 380 },\n];\n\nexport default function ChartsBar() {\n  return (\n    <BarChart\n      aria-label=\"Viloyatlar bo'yicha buyurtmalar: onlayn va do'kondan\"\n      className=\"w-full\"\n      data={orders}\n      index=\"region\"\n      series={[\n        { key: 'onlayn', label: 'Onlayn' },\n        { key: 'dokon', label: \"Do'kondan\", color: 'sky' },\n      ]}\n      valueFormat={(v) => `${formatNumber(v)} ta`}\n      stacked\n    />\n  );\n}\n" },
  "charts/custom": { component: Demo742, file: "charts/custom.tsx", source: "'use client';\n\nimport {\n  ChartContainer,\n  ChartLegend,\n  ChartTooltip,\n  axisProps,\n  cursorProps,\n  gridProps,\n  type ChartConfig,\n} from '@akhatmirzo/ui/charts';\nimport { Bar, CartesianGrid, ComposedChart, Legend, Line, Tooltip, XAxis, YAxis } from 'recharts';\n\nconst data = [\n  { month: 'Yan', buyurtma: 820, konversiya: 2.4 },\n  { month: 'Fev', buyurtma: 760, konversiya: 2.1 },\n  { month: 'Mar', buyurtma: 940, konversiya: 2.8 },\n  { month: 'Apr', buyurtma: 1010, konversiya: 3.1 },\n  { month: 'May', buyurtma: 1180, konversiya: 3.4 },\n];\n\n// Har kalit → `var(--chart-<kalit>)`; label — tooltip va legend'da\nconst config: ChartConfig = {\n  buyurtma: { label: 'Buyurtmalar', color: 'primary' },\n  konversiya: { label: 'Konversiya, %', color: 'amber' },\n};\n\nexport default function ChartsCustom() {\n  return (\n    <ChartContainer aria-label=\"Buyurtmalar va konversiya\" config={config} className=\"h-72\">\n      <ComposedChart data={data} margin={{ top: 8, right: 4, left: 0, bottom: 0 }}>\n        <CartesianGrid {...gridProps} />\n        <XAxis dataKey=\"month\" {...axisProps} tickMargin={8} />\n        <YAxis yAxisId=\"left\" {...axisProps} width=\"auto\" />\n        <YAxis yAxisId=\"right\" orientation=\"right\" {...axisProps} width=\"auto\" />\n        <Tooltip cursor={cursorProps} content={<ChartTooltip />} />\n        <Legend content={<ChartLegend className=\"pt-3\" />} />\n        <Bar yAxisId=\"left\" dataKey=\"buyurtma\" fill=\"var(--chart-buyurtma)\" radius={[6, 6, 0, 0]} />\n        <Line\n          yAxisId=\"right\"\n          dataKey=\"konversiya\"\n          stroke=\"var(--chart-konversiya)\"\n          strokeWidth={2}\n          dot={false}\n        />\n      </ComposedChart>\n    </ChartContainer>\n  );\n}\n" },
  "charts/donut": { component: Demo743, file: "charts/donut.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DonutChart } from '@akhatmirzo/ui/charts';\n\nconst expenses = [\n  { name: 'Oziq-ovqat', total: 3_850_000 },\n  { name: 'Transport', total: 1_240_000 },\n  { name: 'Kommunal', total: 960_000 },\n  { name: \"Ko'ngilochar\", total: 720_000 },\n  { name: 'Boshqalar', total: 430_000 },\n];\n\nconst total = expenses.reduce((sum, e) => sum + e.total, 0);\n\nexport default function ChartsDonut() {\n  return (\n    <DonutChart\n      aria-label=\"Oktabr xarajatlari toifalar bo'yicha\"\n      className=\"w-full max-w-sm\"\n      data={expenses}\n      index=\"name\"\n      value=\"total\"\n      valueFormat={(v) => formatMoney(v)}\n      centerLabel=\"Jami, so'm\"\n      centerValue={`${(total / 1_000_000).toFixed(1).replace('.', ',')} mln`}\n      height={220}\n    />\n  );\n}\n" },
  "charts/line": { component: Demo744, file: "charts/line.tsx", source: "'use client';\n\nimport { LineChart } from '@akhatmirzo/ui/charts';\n\nconst visits = [\n  { day: 'Du', yangi: 320, qaytgan: 540 },\n  { day: 'Se', yangi: 410, qaytgan: 580 },\n  { day: 'Ch', yangi: 380, qaytgan: 610 },\n  { day: 'Pa', yangi: 520, qaytgan: 640 },\n  { day: 'Ju', yangi: 610, qaytgan: 700 },\n  { day: 'Sh', yangi: 450, qaytgan: 520 },\n  { day: 'Ya', yangi: 300, qaytgan: 410 },\n];\n\nexport default function ChartsLine() {\n  return (\n    <LineChart\n      aria-label=\"Haftalik tashriflar: yangi va qaytgan foydalanuvchilar\"\n      className=\"w-full\"\n      data={visits}\n      index=\"day\"\n      series={[\n        { key: 'yangi', label: 'Yangi' },\n        { key: 'qaytgan', label: 'Qaytgan', color: 'success' },\n      ]}\n      curve=\"linear\"\n      height={240}\n    />\n  );\n}\n" },
  "charts/sparkline": { component: Demo745, file: "charts/sparkline.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { Card } from '@akhatmirzo/ui';\nimport { Sparkline } from '@akhatmirzo/ui/charts';\n\nconst kpis = [\n  { title: 'Tushum', value: formatMoney(63_100_000), trend: [42, 39, 51, 48, 58, 63], up: true },\n  { title: 'Qaytarishlar', value: '38 ta', trend: [52, 47, 49, 44, 41, 38], up: false },\n];\n\nexport default function ChartsSparkline() {\n  return (\n    <div className=\"grid w-full max-w-xl gap-3 sm:grid-cols-2\">\n      {kpis.map((kpi) => (\n        <Card key={kpi.title} padding=\"sm\" className=\"gap-2\">\n          <p className=\"text-sm text-text-muted\">{kpi.title}</p>\n          <div className=\"flex items-end justify-between gap-3\">\n            <p className=\"text-xl font-bold whitespace-nowrap tabular-nums\">{kpi.value}</p>\n            {/* Qiymat matn bilan berilgan — grafik faqat bezak */}\n            <Sparkline\n              aria-hidden\n              data={kpi.trend}\n              color={kpi.up ? 'success' : 'danger'}\n              className=\"w-24\"\n            />\n          </div>\n        </Card>\n      ))}\n    </div>\n  );\n}\n" },
  "charts/states": { component: Demo746, file: "charts/states.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\nimport { AreaChart } from '@akhatmirzo/ui/charts';\nimport { useState } from 'react';\n\nconst data = [\n  { week: '1-hafta', buyurtma: 120 },\n  { week: '2-hafta', buyurtma: 164 },\n  { week: '3-hafta', buyurtma: 142 },\n  { week: '4-hafta', buyurtma: 190 },\n];\n\nexport default function ChartsStates() {\n  const [state, setState] = useState('ready');\n  return (\n    <div className=\"flex w-full flex-col gap-4\">\n      <SegmentedControl value={state} onValueChange={setState} aria-label=\"Holat\" size=\"sm\">\n        <SegmentedControl.Item value=\"ready\">Ma&apos;lumot</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"loading\">Yuklanmoqda</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"empty\">Bo&apos;sh</SegmentedControl.Item>\n      </SegmentedControl>\n      <AreaChart\n        aria-label=\"Haftalik buyurtmalar\"\n        data={state === 'empty' ? [] : data}\n        index=\"week\"\n        series={[{ key: 'buyurtma', label: 'Buyurtmalar' }]}\n        loading={state === 'loading'}\n        legend={false}\n        height={220}\n      />\n    </div>\n  );\n}\n" },
  "charts/table-view": { component: Demo747, file: "charts/table-view.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { SegmentedControl } from '@akhatmirzo/ui';\nimport { BarChart } from '@akhatmirzo/ui/charts';\nimport { useState } from 'react';\n\nconst data = [\n  { quarter: 'I chorak', tushum: 132_600_000 },\n  { quarter: 'II chorak', tushum: 169_200_000 },\n  { quarter: 'III chorak', tushum: 151_800_000 },\n];\n\nexport default function ChartsTableView() {\n  const [view, setView] = useState('chart');\n  return (\n    <div className=\"flex w-full flex-col gap-4\">\n      <SegmentedControl value={view} onValueChange={setView} aria-label=\"Ko'rinish\" size=\"sm\">\n        <SegmentedControl.Item value=\"chart\">Grafik</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"table\">Jadval</SegmentedControl.Item>\n      </SegmentedControl>\n      {view === 'chart' ? (\n        <BarChart\n          aria-label=\"Choraklar bo'yicha tushum\"\n          data={data}\n          index=\"quarter\"\n          series={[{ key: 'tushum', label: 'Tushum' }]}\n          valueFormat={(v) => formatMoney(v)}\n          legend={false}\n          height={220}\n        />\n      ) : (\n        <table className=\"w-full text-sm\">\n          <caption className=\"sr-only\">Choraklar bo&apos;yicha tushum</caption>\n          <thead className=\"text-left text-text-muted\">\n            <tr>\n              <th className=\"py-2 font-medium\">Chorak</th>\n              <th className=\"py-2 text-right font-medium\">Tushum</th>\n            </tr>\n          </thead>\n          <tbody>\n            {data.map((row) => (\n              <tr key={row.quarter} className=\"border-t border-border\">\n                <td className=\"py-2\">{row.quarter}</td>\n                <td className=\"py-2 text-right tabular-nums\">{formatMoney(row.tushum)}</td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      )}\n    </div>\n  );\n}\n" },
  "checkbox/basic": { component: Demo748, file: "checkbox/basic.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxBasic() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <Checkbox label=\"Shartlarga roziman\" />\n      <Checkbox label=\"Meni eslab qol\" defaultChecked />\n      <Checkbox label=\"Qisman tanlangan\" checked=\"indeterminate\" />\n    </div>\n  );\n}\n" },
  "checkbox/description": { component: Demo749, file: "checkbox/description.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxDescription() {\n  return (\n    <div className=\"flex max-w-sm flex-col gap-4\">\n      <Checkbox\n        label=\"Yangiliklar\"\n        description=\"Haftasiga bir marta yangi imkoniyatlar haqida xat\"\n        defaultChecked\n      />\n      <Checkbox\n        size=\"sm\"\n        label=\"Qurilmani eslab qolish\"\n        description=\"30 kun davomida qayta kod so'ralmaydi\"\n      />\n    </div>\n  );\n}\n" },
  "checkbox/select-all": { component: Demo750, file: "checkbox/select-all.tsx", source: "'use client';\n\nimport { Checkbox, type CheckedState } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst channels = ['Email', 'SMS', 'Telegram'];\n\nexport default function CheckboxSelectAll() {\n  const [selected, setSelected] = useState<string[]>(['Email']);\n  const all: CheckedState =\n    selected.length === channels.length ? true : selected.length > 0 ? 'indeterminate' : false;\n\n  return (\n    <div className=\"flex flex-col gap-3\">\n      <Checkbox\n        label=\"Barcha kanallar\"\n        checked={all}\n        onCheckedChange={(checked) => setSelected(checked ? channels : [])}\n      />\n      <div className=\"flex flex-col gap-3 pl-7\">\n        {channels.map((channel) => (\n          <Checkbox\n            key={channel}\n            label={channel}\n            checked={selected.includes(channel)}\n            onCheckedChange={(checked) =>\n              setSelected((s) => (checked ? [...s, channel] : s.filter((c) => c !== channel)))\n            }\n          />\n        ))}\n      </div>\n    </div>\n  );\n}\n" },
  "checkbox/sizes": { component: Demo751, file: "checkbox/sizes.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-6\">\n      <Checkbox size=\"sm\" label=\"Kichik · 16\" defaultChecked />\n      <Checkbox size=\"md\" label=\"O'rta · 20\" defaultChecked />\n    </div>\n  );\n}\n" },
  "checkbox/states": { component: Demo752, file: "checkbox/states.tsx", source: "'use client';\n\nimport { Checkbox } from '@akhatmirzo/ui';\n\nexport default function CheckboxStates() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <Checkbox label=\"O'chirilgan\" disabled />\n      <Checkbox label=\"O'chirilgan, belgilangan\" disabled defaultChecked />\n      <Checkbox label=\"Xato\" invalid />\n    </div>\n  );\n}\n" },
  "checkbox/with-field": { component: Demo753, file: "checkbox/with-field.tsx", source: "'use client';\n\nimport { Checkbox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CheckboxWithField() {\n  const [agree, setAgree] = useState(false);\n\n  return (\n    <div className=\"max-w-sm\">\n      <Field\n        label=\"Foydalanish shartlari\"\n        required\n        error={agree ? undefined : 'Davom etish uchun rozilik kerak'}\n      >\n        <Checkbox label=\"Shartlar bilan tanishdim\" checked={agree} onCheckedChange={setAgree} />\n      </Field>\n    </div>\n  );\n}\n" },
  "color-picker/alpha": { component: Demo754, file: "color-picker/alpha.tsx", source: "'use client';\n\nimport { ColorPicker } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function ColorPickerAlpha() {\n  const [color, setColor] = useState('#10b98180');\n\n  return (\n    <div className=\"flex w-full max-w-60 flex-col gap-2\">\n      <ColorPicker alpha value={color} onValueChange={setColor} aria-label=\"Fon rangi\" />\n      <p className=\"m-0 text-sm text-text-muted\">\n        Qiymat: <span className=\"font-mono text-text\">{color}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "color-picker/basic": { component: Demo755, file: "color-picker/basic.tsx", source: "'use client';\n\nimport { ColorPicker } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function ColorPickerBasic() {\n  const [color, setColor] = useState('#4f46e5');\n\n  return (\n    <div className=\"w-full max-w-60\">\n      <ColorPicker value={color} onValueChange={setColor} aria-label=\"Asosiy rang\" />\n    </div>\n  );\n}\n" },
  "color-picker/sizes": { component: Demo756, file: "color-picker/sizes.tsx", source: "'use client';\n\nimport { ColorPicker } from '@akhatmirzo/ui';\n\nexport default function ColorPickerSizes() {\n  return (\n    <div className=\"flex w-full max-w-60 flex-col gap-3\">\n      <ColorPicker size=\"sm\" aria-label=\"Kichik\" />\n      <ColorPicker aria-label=\"O'rtacha\" />\n      <ColorPicker size=\"lg\" aria-label=\"Katta\" />\n      <ColorPicker disabled aria-label=\"O'chirilgan\" />\n    </div>\n  );\n}\n" },
  "color-picker/swatches": { component: Demo757, file: "color-picker/swatches.tsx", source: "'use client';\n\nimport { ColorPicker } from '@akhatmirzo/ui';\n\n// Faqat brend palitrasidagi ranglar\nconst brand = ['#4f46e5', '#0ea5e9', '#10b981', '#f59e0b', '#e11d48'];\n\nexport default function ColorPickerSwatches() {\n  return (\n    <div className=\"w-full max-w-60\">\n      <ColorPicker swatches={brand} defaultValue=\"#10b981\" aria-label=\"Teg rangi\" />\n    </div>\n  );\n}\n" },
  "color-picker/with-field": { component: Demo758, file: "color-picker/with-field.tsx", source: "'use client';\n\nimport { ColorPicker, Field } from '@akhatmirzo/ui';\n\nexport default function ColorPickerWithField() {\n  return (\n    <div className=\"w-full max-w-60\">\n      <Field label=\"Brend rangi\" description=\"Tugmalar va havolalarda ishlatiladi\">\n        <ColorPicker name=\"brand\" defaultValue=\"#0ea5e9\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "combobox/basic": { component: Demo759, file: "combobox/basic.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst cities = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Xiva',\n  'Namangan',\n  'Andijon',\n  \"Farg'ona\",\n  \"Qo'qon\",\n  \"Marg'ilon\",\n  'Nukus',\n  'Qarshi',\n  'Termiz',\n].map((label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }));\n\nexport default function ComboboxBasic() {\n  const [city, setCity] = useState<string | null>(null);\n\n  return (\n    <Field\n      label=\"Shahar\"\n      description={city ? `Qiymat: ${city}` : 'Hali tanlanmagan'}\n      className=\"w-full max-w-xs\"\n    >\n      <Combobox\n        options={cities}\n        value={city}\n        onValueChange={setCity}\n        placeholder=\"Shahar tanlang\"\n        clearable\n      />\n    </Field>\n  );\n}\n" },
  "combobox/creatable": { component: Demo760, file: "combobox/creatable.tsx", source: "'use client';\n\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst initialTags: ComboboxOption[] = ['dizayn', 'frontend', 'backend', 'mobil'].map((t) => ({\n  value: t,\n  label: t,\n}));\n\nexport default function ComboboxCreatable() {\n  const [tags, setTags] = useState(initialTags);\n  const [chosen, setChosen] = useState<string[]>(['frontend']);\n\n  return (\n    <Field\n      label=\"Teglar\"\n      description=\"Ro'yxatda yo'q tegni yozing va Enter bosing\"\n      className=\"w-full max-w-sm\"\n    >\n      <Combobox\n        multiple\n        creatable\n        options={tags}\n        value={chosen}\n        onValueChange={setChosen}\n        onCreate={(text) => {\n          const option = { value: text.toLowerCase(), label: text };\n          setTags((prev) => [...prev, option]);\n          return option;\n        }}\n        placeholder=\"Teg qo'shing\"\n        leftIcon={null}\n      />\n    </Field>\n  );\n}\n" },
  "combobox/details": { component: Demo761, file: "combobox/details.tsx", source: "'use client';\n\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\n\nfunction Dot({ className }: { className: string }) {\n  return <span className={`size-2.5 rounded-full ${className}`} />;\n}\n\nconst statuses: ComboboxOption[] = [\n  {\n    value: 'new',\n    label: 'Yangi',\n    description: 'Buyurtma qabul qilindi',\n    icon: <Dot className=\"bg-info\" />,\n  },\n  {\n    value: 'packing',\n    label: \"Yig'ilmoqda\",\n    description: 'Omborda tayyorlanmoqda',\n    icon: <Dot className=\"bg-warning\" />,\n  },\n  {\n    value: 'shipping',\n    label: \"Yo'lda\",\n    description: 'Kuryerga topshirildi',\n    icon: <Dot className=\"bg-primary\" />,\n  },\n  {\n    value: 'cancelled',\n    label: 'Bekor qilingan',\n    description: 'Arxivlangan holat',\n    icon: <Dot className=\"bg-danger\" />,\n    disabled: true,\n  },\n];\n\nexport default function ComboboxDetails() {\n  return (\n    <Field label=\"Buyurtma holati\" className=\"w-full max-w-xs\">\n      <Combobox options={statuses} defaultValue=\"packing\" leftIcon={null} />\n    </Field>\n  );\n}\n" },
  "combobox/multiple": { component: Demo762, file: "combobox/multiple.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst branches = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Namangan',\n  'Andijon',\n  \"Farg'ona\",\n  'Nukus',\n].map((label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }));\n\nexport default function ComboboxMultiple() {\n  const [selected, setSelected] = useState<string[]>(['toshkent', 'samarqand']);\n\n  return (\n    <Field\n      label=\"Filiallar\"\n      description={`${selected.length} ta tanlangan`}\n      className=\"w-full max-w-sm\"\n    >\n      <Combobox\n        multiple\n        options={branches}\n        value={selected}\n        onValueChange={setSelected}\n        placeholder=\"Filiallarni tanlang\"\n      />\n    </Field>\n  );\n}\n" },
  "combobox/server": { component: Demo763, file: "combobox/server.tsx", source: "'use client';\n\nimport { searchMatch } from '@akhatmirzo/core';\nimport { Combobox, Field, type ComboboxOption } from '@akhatmirzo/ui';\nimport { useRef, useState } from 'react';\n\nconst all: ComboboxOption[] = ['Toshkent', 'Samarqand', 'Buxoro', 'Xiva', 'Nukus', 'Termiz'].map(\n  (label) => ({ value: label.toLowerCase(), label }),\n);\n\nexport default function ComboboxServer() {\n  const [options, setOptions] = useState(all.slice(0, 3));\n  const [loading, setLoading] = useState(false);\n  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);\n\n  // Server so'rovini taqlid qiladi: javob 700ms dan keyin keladi\n  const search = (query: string) => {\n    clearTimeout(timer.current);\n    setLoading(true);\n    timer.current = setTimeout(() => {\n      setOptions(query ? all.filter((o) => searchMatch(o.label, query).match) : all.slice(0, 3));\n      setLoading(false);\n    }, 700);\n  };\n\n  return (\n    <Field label=\"Shahar (serverdan)\" className=\"w-full max-w-xs\">\n      <Combobox\n        options={options}\n        loading={loading}\n        onSearch={search}\n        placeholder=\"Qidirib tanlang\"\n        searchPlaceholder=\"Shahar nomi...\"\n        emptyText=\"Server hech narsa qaytarmadi\"\n      />\n    </Field>\n  );\n}\n" },
  "combobox/sizes": { component: Demo764, file: "combobox/sizes.tsx", source: "'use client';\n\nimport { Combobox } from '@akhatmirzo/ui';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro'].map((label) => ({\n  value: label.toLowerCase(),\n  label,\n}));\n\nexport default function ComboboxSizes() {\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Combobox size=\"sm\" options={cities} aria-label=\"Shahar\" placeholder=\"sm — 32px\" />\n      <Combobox size=\"md\" options={cities} aria-label=\"Shahar\" placeholder=\"md — 40px\" />\n      <Combobox size=\"lg\" options={cities} aria-label=\"Shahar\" placeholder=\"lg — 48px\" />\n    </div>\n  );\n}\n" },
  "combobox/states": { component: Demo765, file: "combobox/states.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro'].map((label) => ({\n  value: label.toLowerCase(),\n  label,\n}));\n\nexport default function ComboboxStates() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <Field label=\"O'chirilgan\" disabled>\n        <Combobox options={cities} defaultValue=\"toshkent\" />\n      </Field>\n      <Field label=\"Shahar\" error=\"Shaharni tanlang\" required>\n        <Combobox options={cities} placeholder=\"Shahar tanlang\" />\n      </Field>\n      <Field label=\"Yuklanmoqda\">\n        <Combobox options={[]} loading placeholder=\"Ochib ko'ring\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "combobox/uzbek-search": { component: Demo766, file: "combobox/uzbek-search.tsx", source: "'use client';\n\nimport { Combobox, Field } from '@akhatmirzo/ui';\n\nconst districts = [\n  'Gʻuzor',\n  \"G'allaorol\",\n  'Oʻrta Chirchiq',\n  \"Qo'shrabot\",\n  'Shahrisabz',\n  'Chilonzor',\n  'Yunusobod',\n  \"Mirzo Ulug'bek\",\n  'Toshkent tumani',\n].map((label, i) => ({ value: String(i), label }));\n\nexport default function ComboboxUzbekSearch() {\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field label=\"Tuman\">\n        <Combobox options={districts} placeholder=\"Tumanni tanlang\" />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Yozib ko'ring: <span className=\"font-medium text-text\">guzor</span>,{' '}\n        <span className=\"font-medium text-text\">g‘allaorol</span>,{' '}\n        <span className=\"font-medium text-text\">Чилонзор</span>,{' '}\n        <span className=\"font-medium text-text\">ulugbek</span>\n      </p>\n    </div>\n  );\n}\n" },
  "command-palette/basic": { component: Demo767, file: "command-palette/basic.tsx", source: "'use client';\n\nimport { Button, CommandPalette, Kbd, toast, type CommandPaletteGroup } from '@akhatmirzo/ui';\nimport {\n  ChartColumn,\n  FileSpreadsheet,\n  House,\n  Package,\n  Plus,\n  Search,\n  Settings,\n  UserPlus,\n  Users,\n} from 'lucide-react';\n\nconst run = (label: string) => () => toast(`\"${label}\" bajarildi`);\n\nconst groups: CommandPaletteGroup[] = [\n  {\n    heading: 'Sahifalar',\n    items: [\n      { label: 'Bosh sahifa', icon: <House />, onSelect: run('Bosh sahifa') },\n      {\n        label: 'Buyurtmalar',\n        icon: <Package />,\n        keywords: ['zakaz', 'savdo'],\n        onSelect: run('Buyurtmalar'),\n      },\n      { label: 'Mijozlar', icon: <Users />, onSelect: run('Mijozlar') },\n      {\n        label: 'Hisobotlar',\n        icon: <ChartColumn />,\n        keywords: ['statistika'],\n        onSelect: run('Hisobotlar'),\n      },\n      {\n        label: 'Sozlamalar',\n        icon: <Settings />,\n        shortcut: ['mod', ','],\n        onSelect: run('Sozlamalar'),\n      },\n    ],\n  },\n  {\n    heading: 'Amallar',\n    items: [\n      {\n        label: 'Yangi buyurtma',\n        icon: <Plus />,\n        shortcut: ['mod', 'N'],\n        onSelect: run('Yangi buyurtma'),\n      },\n      { label: \"Mijoz qo'shish\", icon: <UserPlus />, onSelect: run(\"Mijoz qo'shish\") },\n      {\n        label: 'Eksport (Excel)',\n        icon: <FileSpreadsheet />,\n        keywords: ['xlsx'],\n        onSelect: run('Eksport'),\n      },\n    ],\n  },\n];\n\nexport default function CommandPaletteBasic() {\n  return (\n    // Docs saytida Ctrl+K qidiruvga band, shuning uchun bu yerda mod+J\n    <CommandPalette groups={groups} hotkey=\"mod+j\">\n      <Button variant=\"outline\" leftIcon={<Search />} className=\"min-w-64 justify-start\">\n        <span className=\"flex-1 text-left text-text-muted\">Qidirish...</span>\n        <Kbd keys={['mod', 'J']} />\n      </Button>\n    </CommandPalette>\n  );\n}\n" },
  "command-palette/pages": { component: Demo768, file: "command-palette/pages.tsx", source: "'use client';\n\nimport { Button, CommandPalette, toast, type CommandPaletteGroup } from '@akhatmirzo/ui';\nimport { Globe, Moon, Sun, User } from 'lucide-react';\n\nconst customers = ['Aziza Karimova', 'Bobur Toshmatov', \"G'ayrat Usmonov\", 'Malika Yusupova'];\n\nconst groups: CommandPaletteGroup[] = [\n  {\n    heading: 'Sozlamalar',\n    items: [\n      {\n        label: 'Mavzuni almashtirish',\n        icon: <Moon />,\n        keywords: ['tungi rejim', 'dark'],\n        page: {\n          title: 'Mavzu',\n          placeholder: 'Mavzu tanlang...',\n          groups: [\n            {\n              heading: 'Mavzu',\n              items: [\n                {\n                  id: 'theme-light',\n                  label: \"Yorug'\",\n                  icon: <Sun />,\n                  onSelect: () => toast(\"Yorug' mavzu\"),\n                },\n                {\n                  id: 'theme-dark',\n                  label: \"Qorong'i\",\n                  icon: <Moon />,\n                  onSelect: () => toast(\"Qorong'i mavzu\"),\n                },\n              ],\n            },\n          ],\n        },\n      },\n      {\n        label: 'Tilni almashtirish',\n        icon: <Globe />,\n        page: {\n          title: 'Til',\n          groups: [\n            {\n              heading: 'Til',\n              items: [\n                { id: 'lang-uz', label: \"O'zbekcha\", onSelect: () => toast(\"O'zbekcha\") },\n                { id: 'lang-en', label: 'English', disabled: true },\n              ],\n            },\n          ],\n        },\n      },\n    ],\n  },\n  {\n    heading: 'Mijozlar',\n    searchOnly: true,\n    items: customers.map((name) => ({ label: name, icon: <User />, onSelect: () => toast(name) })),\n  },\n];\n\nexport default function CommandPalettePages() {\n  return (\n    <CommandPalette groups={groups} hotkey={false} recent={false}>\n      <Button variant=\"soft\">Sozlamalarni ochish</Button>\n    </CommandPalette>\n  );\n}\n" },
  "command-palette/server": { component: Demo769, file: "command-palette/server.tsx", source: "'use client';\n\nimport { Button, CommandPalette, toast, type CommandPaletteItem } from '@akhatmirzo/ui';\nimport { Plus, User } from 'lucide-react';\n\nconst customers = [\n  ['Akmal Ergashev', '+998 90 123 45 67'],\n  ['Akbar Sobirov', '+998 93 555 12 34'],\n  ['Kamola Akramova', '+998 97 700 00 11'],\n  ['Nodira Ahmedova', '+998 91 444 22 33'],\n] as const;\n\n/** Server qidiruvini taqlid qiladi (700ms); yangi so'rov eskisini bekor qiladi */\nfunction searchCustomers(query: string, { signal }: { signal: AbortSignal }) {\n  return new Promise<CommandPaletteItem[]>((resolve, reject) => {\n    const timer = setTimeout(() => {\n      const q = query.toLowerCase();\n      resolve(\n        customers\n          .filter(([name]) => name.toLowerCase().includes(q))\n          .map(([name, phone]) => ({\n            id: `customer-${name}`,\n            label: name,\n            description: phone,\n            icon: <User />,\n            onSelect: () => toast(name),\n          })),\n      );\n    }, 700);\n    signal.addEventListener('abort', () => {\n      clearTimeout(timer);\n      reject(new DOMException('Bekor qilindi', 'AbortError'));\n    });\n  });\n}\n\nexport default function CommandPaletteServer() {\n  return (\n    <CommandPalette\n      hotkey={false}\n      recentKey=\"docs:command-palette:server\"\n      placeholder=\"Mijoz yoki buyruq qidirish...\"\n      onSearch={searchCustomers}\n      labels={{ results: 'Mijozlar (serverdan)' }}\n      groups={[\n        {\n          heading: 'Amallar',\n          items: [\n            { label: \"Mijoz qo'shish\", icon: <Plus />, onSelect: () => toast(\"Mijoz qo'shish\") },\n          ],\n        },\n      ]}\n    >\n      <Button variant=\"outline\">Mijoz qidirish</Button>\n    </CommandPalette>\n  );\n}\n" },
  "context-menu/basic": { component: Demo770, file: "context-menu/basic.tsx", source: "'use client';\n\nimport { ContextMenu, toast } from '@akhatmirzo/ui';\nimport { Copy, Download, FileText, Pencil, Trash2 } from 'lucide-react';\n\nexport default function ContextMenuBasic() {\n  return (\n    <ContextMenu>\n      <ContextMenu.Trigger asChild>\n        <div className=\"flex w-72 items-center gap-3 rounded-xl border border-dashed border-border-strong bg-surface p-4 select-none\">\n          <span className=\"grid size-10 place-items-center rounded-lg bg-primary-soft text-primary-soft-foreground\">\n            <FileText className=\"size-5\" aria-hidden=\"true\" />\n          </span>\n          <span className=\"flex flex-col\">\n            <span className=\"text-sm font-medium\">Hisobot-2026.pdf</span>\n            <span className=\"text-xs text-text-muted\">O'ng tugma bilan bosing</span>\n          </span>\n        </div>\n      </ContextMenu.Trigger>\n      <ContextMenu.Content>\n        <ContextMenu.Item\n          icon={<Pencil />}\n          shortcut={['mod', 'E']}\n          onSelect={() => toast('Tahrirlash')}\n        >\n          Tahrirlash\n        </ContextMenu.Item>\n        <ContextMenu.Item\n          icon={<Copy />}\n          shortcut={['mod', 'D']}\n          onSelect={() => toast('Nusxa olindi')}\n        >\n          Nusxa olish\n        </ContextMenu.Item>\n        <ContextMenu.Item icon={<Download />} onSelect={() => toast('Yuklanmoqda')}>\n          Yuklab olish\n        </ContextMenu.Item>\n        <ContextMenu.Separator />\n        <ContextMenu.Item icon={<Trash2 />} variant=\"danger\" onSelect={() => toast(\"O'chirildi\")}>\n          O'chirish\n        </ContextMenu.Item>\n      </ContextMenu.Content>\n    </ContextMenu>\n  );\n}\n" },
  "context-menu/checkbox-radio": { component: Demo771, file: "context-menu/checkbox-radio.tsx", source: "'use client';\n\nimport { ContextMenu, cn } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function ContextMenuCheckboxRadio() {\n  const [grid, setGrid] = useState(true);\n  const [rulers, setRulers] = useState(false);\n  const [zoom, setZoom] = useState('100');\n\n  return (\n    <ContextMenu>\n      <ContextMenu.Trigger asChild>\n        <div\n          className={cn(\n            'grid h-48 w-full max-w-md place-items-center rounded-xl border border-border bg-surface text-sm text-text-muted select-none',\n            grid && 'border-dashed',\n            rulers && 'border-l-4 border-t-4',\n          )}\n        >\n          Kanvas · {zoom}% — o'ng tugma bilan bosing\n        </div>\n      </ContextMenu.Trigger>\n      <ContextMenu.Content>\n        <ContextMenu.Label>Ko'rinish</ContextMenu.Label>\n        <ContextMenu.CheckboxItem checked={grid} onCheckedChange={setGrid}>\n          Panjara\n        </ContextMenu.CheckboxItem>\n        <ContextMenu.CheckboxItem checked={rulers} onCheckedChange={setRulers}>\n          Chizg'ichlar\n        </ContextMenu.CheckboxItem>\n        <ContextMenu.Separator />\n        <ContextMenu.Label>Masshtab</ContextMenu.Label>\n        <ContextMenu.RadioGroup value={zoom} onValueChange={setZoom}>\n          <ContextMenu.RadioItem value=\"50\">50%</ContextMenu.RadioItem>\n          <ContextMenu.RadioItem value=\"100\">100%</ContextMenu.RadioItem>\n          <ContextMenu.RadioItem value=\"200\">200%</ContextMenu.RadioItem>\n        </ContextMenu.RadioGroup>\n      </ContextMenu.Content>\n    </ContextMenu>\n  );\n}\n" },
  "context-menu/table-row": { component: Demo772, file: "context-menu/table-row.tsx", source: "'use client';\n\nimport { ContextMenu, DropdownMenu, IconButton, toast } from '@akhatmirzo/ui';\nimport { Ellipsis, Pencil, Send, Trash2 } from 'lucide-react';\n\nconst orders = [\n  { id: '#1042', customer: 'Dilnoza Karimova', total: \"1 250 000 so'm\" },\n  { id: '#1043', customer: 'Javohir Toshmatov', total: \"480 000 so'm\" },\n];\n\n/** ContextMenu va DropdownMenu qismlari bir xil — amallar bir marta yoziladi */\nfunction Actions({ id, Menu }: { id: string; Menu: typeof ContextMenu | typeof DropdownMenu }) {\n  return (\n    <>\n      <Menu.Item icon={<Pencil />} onSelect={() => toast(`${id} tahrirlanmoqda`)}>\n        Tahrirlash\n      </Menu.Item>\n      <Menu.Sub>\n        <Menu.SubTrigger icon={<Send />}>Yuborish</Menu.SubTrigger>\n        <Menu.SubContent>\n          <Menu.Item onSelect={() => toast('Telegram')}>Telegram</Menu.Item>\n          <Menu.Item onSelect={() => toast('Email')}>Email</Menu.Item>\n        </Menu.SubContent>\n      </Menu.Sub>\n      <Menu.Separator />\n      <Menu.Item icon={<Trash2 />} variant=\"danger\" onSelect={() => toast(`${id} o'chirildi`)}>\n        O'chirish\n      </Menu.Item>\n    </>\n  );\n}\n\nexport default function ContextMenuTableRow() {\n  return (\n    <ul className=\"m-0 w-full max-w-lg list-none rounded-xl border border-border bg-surface p-0\">\n      {orders.map((o) => (\n        <ContextMenu key={o.id}>\n          <ContextMenu.Trigger asChild>\n            <li className=\"flex items-center gap-3 border-b border-border px-4 py-2 text-sm last:border-b-0\">\n              <span className=\"font-medium\">{o.id}</span>\n              <span className=\"truncate text-text-muted\">{o.customer}</span>\n              <span className=\"ml-auto tabular-nums\">{o.total}</span>\n              {/* Xuddi shu amallar tugma orqali ham mavjud */}\n              <DropdownMenu>\n                <DropdownMenu.Trigger asChild>\n                  <IconButton size=\"sm\" variant=\"ghost\" aria-label={`${o.id} amallari`}>\n                    <Ellipsis />\n                  </IconButton>\n                </DropdownMenu.Trigger>\n                <DropdownMenu.Content align=\"end\">\n                  <Actions id={o.id} Menu={DropdownMenu} />\n                </DropdownMenu.Content>\n              </DropdownMenu>\n            </li>\n          </ContextMenu.Trigger>\n          <ContextMenu.Content>\n            <Actions id={o.id} Menu={ContextMenu} />\n          </ContextMenu.Content>\n        </ContextMenu>\n      ))}\n    </ul>\n  );\n}\n" },
  "core/api-errors": { component: Demo773, file: "core/api-errors.tsx", source: "'use client';\n\nimport { createApiClient, isApiError, type FetchLike } from '@akhatmirzo/core';\nimport { Badge, Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\n// Haqiqiy server o'rniga: `/status/404` → 404 javob, `/sekin` → hech qachon javob bermaydi\nconst fakeFetch: FetchLike = (url, init) =>\n  new Promise((resolve, reject) => {\n    if (url.endsWith('/sekin')) {\n      init.signal?.addEventListener('abort', () => reject(new Error('aborted')));\n      return;\n    }\n    const status = Number(url.split('/').pop());\n    resolve({ ok: status < 400, status, headers: { get: () => null }, text: async () => '' });\n  });\n\nconst api = createApiClient({ baseUrl: '/api', timeout: 1500, fetch: fakeFetch });\n\nexport default function CoreApiErrors() {\n  const [result, setResult] = useState<{ code: string; message: string } | null>(null);\n\n  const request = async (path: string) => {\n    try {\n      await api.get(path);\n      setResult({ code: 'OK', message: 'Muvaffaqiyatli' });\n    } catch (error) {\n      if (isApiError(error)) setResult({ code: error.code, message: error.message });\n    }\n  };\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div className=\"flex flex-wrap gap-2\">\n        {['401', '403', '404', '422', '500'].map((s) => (\n          <Button key={s} size=\"sm\" variant=\"outline\" onClick={() => request(`/status/${s}`)}>\n            {s}\n          </Button>\n        ))}\n        <Button size=\"sm\" variant=\"outline\" onClick={() => request('/sekin')}>\n          Timeout\n        </Button>\n      </div>\n      {result && (\n        <div className=\"flex items-center gap-2 text-sm\">\n          <Badge color={result.code === 'OK' ? 'success' : 'danger'}>{result.code}</Badge>\n          <span className=\"text-text\">{result.message}</span>\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  "core/card-validate": { component: Demo774, file: "core/card-validate.tsx", source: "'use client';\n\nimport { detectCardBrand, formatCardNumber, isValidCardNumber } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst BRANDS = { uzcard: 'Uzcard', humo: 'Humo', visa: 'Visa', mastercard: 'Mastercard' };\n\nexport default function CoreCardValidate() {\n  const [digits, setDigits] = useState('8600');\n  const brand = detectCardBrand(digits);\n  const complete = digits.length === 16;\n  const valid = isValidCardNumber(digits);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field\n        label=\"Karta raqami\"\n        description=\"To'g'ri namuna: 4111 1111 1111 1111\"\n        error={complete && !valid ? \"Karta raqami noto'g'ri\" : undefined}\n      >\n        <Input\n          value={formatCardNumber(digits)}\n          onChange={(e) => setDigits(e.target.value.replace(/\\D/g, '').slice(0, 16))}\n          inputMode=\"numeric\"\n          placeholder=\"0000 0000 0000 0000\"\n          suffix={brand ? BRANDS[brand] : undefined}\n        />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={brand ? 'info' : 'neutral'}>{brand ? BRANDS[brand] : \"Brend noma'lum\"}</Badge>\n        <Badge color={!complete ? 'neutral' : valid ? 'success' : 'danger'} dot>\n          {!complete ? `${digits.length}/16` : valid ? \"Luhn: to'g'ri\" : 'Luhn: xato'}\n        </Badge>\n      </div>\n    </div>\n  );\n}\n" },
  "core/date-uz": { component: Demo775, file: "core/date-uz.tsx", source: "'use client';\n\nimport { formatDateRange, formatDateUz, formatDuration } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst STYLES = ['long', 'full', 'short', 'dayMonth', 'monthYear'] as const;\n\nexport default function CoreDateUz() {\n  const [value, setValue] = useState('2026-10-22');\n  const [y = 2026, m = 10, d = 22] = value.split('-').map(Number);\n  const date = new Date(y, m - 1, d, 14, 30);\n  const end = new Date(y, m - 1, d + 3);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Sana\">\n        <Input type=\"date\" value={value} onChange={(e) => setValue(e.target.value)} />\n      </Field>\n      <dl className=\"grid grid-cols-[auto_1fr] gap-x-4 gap-y-2 text-sm\">\n        {STYLES.map((style) => (\n          <div key={style} className=\"contents\">\n            <dt className=\"font-mono text-xs text-text-muted\">{style}</dt>\n            <dd>{formatDateUz(date, { style })}</dd>\n          </div>\n        ))}\n        <dt className=\"font-mono text-xs text-text-muted\">kirill</dt>\n        <dd>{formatDateUz(date, { style: 'full', script: 'cyrillic' })}</dd>\n        <dt className=\"font-mono text-xs text-text-muted\">+3 kun</dt>\n        <dd>{formatDateRange(date, end)}</dd>\n        <dt className=\"font-mono text-xs text-text-muted\">davomiylik</dt>\n        <dd>{formatDuration(end.getTime() - date.getTime(), { units: 3 })}</dd>\n      </dl>\n    </div>\n  );\n}\n" },
  "core/date": { component: Demo776, file: "core/date.tsx", source: "'use client';\n\nimport { formatDate, parseDate } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst PATTERNS = ['dd.MM.yyyy', 'd MMMM yyyy, EEEE', 'd MMM, EEE', 'EEEE, d MMMM [soat] HH:mm'];\nconst DATE = new Date(2026, 9, 21, 14, 30);\n\nexport default function CoreDate() {\n  const [pattern, setPattern] = useState('d MMMM yyyy, EEEE');\n  const [input, setInput] = useState('31.02.2026');\n  const parsed = parseDate(input);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field\n        label=\"Shablon\"\n        description={`formatDate(sana, shablon) → ${formatDate(DATE, pattern)}`}\n      >\n        <Input value={pattern} onChange={(e) => setPattern(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        {PATTERNS.map((p) => (\n          <button key={p} type=\"button\" onClick={() => setPattern(p)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{p}</Badge>\n          </button>\n        ))}\n      </div>\n      <Field\n        label=\"parseDate (dd.MM.yyyy)\"\n        description={parsed ? formatDate(parsed, 'EEEE, d MMMM yyyy') : \"null — bunday sana yo'q\"}\n      >\n        <Input value={input} onChange={(e) => setInput(e.target.value)} invalid={!parsed} />\n      </Field>\n    </div>\n  );\n}\n" },
  "core/debounce-throttle": { component: Demo777, file: "core/debounce-throttle.tsx", source: "'use client';\n\nimport { debounce, throttle } from '@akhatmirzo/core';\nimport { Button } from '@akhatmirzo/ui';\nimport { useEffect, useMemo, useState } from 'react';\n\ntype Counts = { raw: number; throttled: number; debounced: number };\nconst ZERO: Counts = { raw: 0, throttled: 0, debounced: 0 };\nconst inc = (key: keyof Counts) => (c: Counts) => ({ ...c, [key]: c[key] + 1 });\n\nexport default function CoreDebounceThrottle() {\n  const [counts, setCounts] = useState(ZERO);\n\n  const onDebounced = useMemo(() => debounce(() => setCounts(inc('debounced')), 400), []);\n  const onThrottled = useMemo(() => throttle(() => setCounts(inc('throttled')), 400), []);\n\n  useEffect(\n    () => () => {\n      onDebounced.cancel();\n      onThrottled.cancel();\n    },\n    [onDebounced, onThrottled],\n  );\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div\n        onPointerMove={() => {\n          setCounts(inc('raw'));\n          onDebounced();\n          onThrottled();\n        }}\n        className=\"flex h-32 touch-none items-center justify-center rounded-xl border border-dashed border-border-strong bg-surface-muted text-sm text-text-muted\"\n      >\n        Sichqoncha yoki barmoqni shu yerda yurgizing\n      </div>\n      <dl className=\"grid grid-cols-3 gap-2 text-center text-sm\">\n        {(['raw', 'throttled', 'debounced'] as const).map((key) => (\n          <div key={key} className=\"rounded-lg border border-border bg-surface p-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{key}</dt>\n            <dd className=\"text-xl font-semibold text-text tabular-nums\">{counts[key]}</dd>\n          </div>\n        ))}\n      </dl>\n      <Button size=\"sm\" variant=\"ghost\" onClick={() => setCounts(ZERO)}>\n        Nolga qaytarish\n      </Button>\n    </div>\n  );\n}\n" },
  "core/fuzzy": { component: Demo778, file: "core/fuzzy.tsx", source: "'use client';\n\nimport { fuzzyMatch, splitByRanges } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst COMMANDS = [\n  'Yangi buyurtma',\n  \"Buyurtmalar ro'yxati\",\n  \"Mijoz qo'shish\",\n  'Hisobotlar',\n  'Sozlamalar',\n  'Profilni tahrirlash',\n  'Mavzuni almashtirish',\n];\n\nexport default function CoreFuzzy() {\n  const [query, setQuery] = useState('ybu');\n  const results = COMMANDS.flatMap((label) => {\n    const result = fuzzyMatch(label, query);\n    return result ? [{ label, ...result }] : [];\n  }).sort((a, b) => b.score - a.score);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Field label=\"Buyruq\" description=\"Harflar tartibi muhim: mq, hsb, prof\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <ul className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {results.map(({ label, ranges, score }) => (\n          <li key={label} className=\"flex items-center justify-between gap-3 px-3 py-2\">\n            <span>\n              {splitByRanges(label, ranges).map((part, i) =>\n                part.match ? (\n                  <strong key={i} className=\"font-semibold text-primary-soft-foreground\">\n                    {part.text}\n                  </strong>\n                ) : (\n                  <span key={i}>{part.text}</span>\n                ),\n              )}\n            </span>\n            <span className=\"font-mono text-xs text-text-muted\">{score}</span>\n          </li>\n        ))}\n        {results.length === 0 && <li className=\"px-3 py-2 text-text-muted\">Mos buyruq yo'q</li>}\n      </ul>\n    </div>\n  );\n}\n" },
  "core/identifiers": { component: Demo779, file: "core/identifiers.tsx", source: "'use client';\n\nimport {\n  formatCarPlate,\n  formatDate,\n  formatPinfl,\n  parseCarPlate,\n  parsePinfl,\n} from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CoreIdentifiers() {\n  const [pinfl, setPinfl] = useState('31503901234567');\n  const [plate, setPlate] = useState('01a123bc');\n  const person = parsePinfl(pinfl);\n  const car = parseCarPlate(plate);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"JShShIR\" description={formatPinfl(pinfl) || '—'}>\n        <Input value={pinfl} onChange={(e) => setPinfl(e.target.value)} inputMode=\"numeric\" />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={person ? 'success' : 'neutral'} dot>\n          {person ? \"To'g'ri\" : \"Noto'g'ri yoki to'liq emas\"}\n        </Badge>\n        {person && <Badge color=\"info\">{person.gender === 'male' ? 'Erkak' : 'Ayol'}</Badge>}\n        {person && <Badge color=\"info\">{formatDate(person.birthDate)}</Badge>}\n      </div>\n      <Field label=\"Avtomobil raqami\" description={formatCarPlate(plate) || '—'}>\n        <Input value={plate} onChange={(e) => setPlate(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={car ? 'success' : 'neutral'} dot>\n          {car ? (car.type === 'personal' ? 'Jismoniy shaxs' : 'Yuridik shaxs') : \"Noto'g'ri\"}\n        </Badge>\n        {car && <Badge color=\"info\">{car.region.name}</Badge>}\n      </div>\n    </div>\n  );\n}\n" },
  "core/money": { component: Demo780, file: "core/money.tsx", source: "'use client';\n\nimport { formatMoney, formatNumber, type MoneyCurrency } from '@akhatmirzo/core';\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CURRENCIES: MoneyCurrency[] = [\"so'm\", 'UZS', false];\n\nexport default function CoreMoney() {\n  const [raw, setRaw] = useState('1250000.5');\n  const [currency, setCurrency] = useState<MoneyCurrency>(\"so'm\");\n  const n = Number(raw.replace(',', '.').replace(/\\s/g, ''));\n\n  const rows = [\n    { call: 'formatNumber(n)', value: formatNumber(n) },\n    { call: 'formatNumber(n, { decimals: 2 })', value: formatNumber(n, { decimals: 2 }) },\n    { call: 'formatMoney(n, { currency })', value: formatMoney(n, { currency }) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Son\">\n        <Input value={raw} onChange={(e) => setRaw(e.target.value)} inputMode=\"decimal\" />\n      </Field>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        {CURRENCIES.map((c) => (\n          <Button\n            key={String(c)}\n            size=\"sm\"\n            variant={currency === c ? 'primary' : 'outline'}\n            onClick={() => setCurrency(c)}\n          >\n            {c === false ? 'false' : c}\n          </Button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.call} className=\"flex flex-wrap justify-between gap-x-4 gap-y-1 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.call}</dt>\n            <dd className=\"font-mono font-medium text-text tabular-nums\">{row.value || \"''\"}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "core/number-words": { component: Demo781, file: "core/number-words.tsx", source: "'use client';\n\nimport { moneyToWords, numberToWords, ordinalWords } from '@akhatmirzo/core';\nimport { Field, Input, SegmentedControl } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\ntype Script = 'latin' | 'cyrillic';\n\nexport default function CoreNumberWords() {\n  const [raw, setRaw] = useState('1250000.50');\n  const [script, setScript] = useState<Script>('latin');\n  const n = Number(raw.replace(',', '.').replace(/\\s/g, ''));\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Summa\">\n        <Input value={raw} onChange={(e) => setRaw(e.target.value)} inputMode=\"decimal\" />\n      </Field>\n      <SegmentedControl\n        aria-label=\"Alifbo\"\n        value={script}\n        onValueChange={(v) => setScript(v as Script)}\n      >\n        <SegmentedControl.Item value=\"latin\">Lotin</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"cyrillic\">Кирилл</SegmentedControl.Item>\n      </SegmentedControl>\n      <dl className=\"grid gap-2 text-sm\">\n        <dt className=\"font-mono text-xs text-text-muted\">numberToWords</dt>\n        <dd>{numberToWords(n, { script }) || '—'}</dd>\n        <dt className=\"font-mono text-xs text-text-muted\">moneyToWords</dt>\n        <dd>{moneyToWords(n, { script }) || '—'}</dd>\n        <dt className=\"font-mono text-xs text-text-muted\">ordinalWords</dt>\n        <dd>{ordinalWords(n, { script }) || '—'}</dd>\n      </dl>\n    </div>\n  );\n}\n" },
  "core/password": { component: Demo782, file: "core/password.tsx", source: "'use client';\n\nimport { passwordStrength } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst BAR = ['bg-danger', 'bg-danger', 'bg-warning', 'bg-success', 'bg-success'];\nconst COLOR = ['danger', 'danger', 'warning', 'success', 'success'] as const;\nconst CHECKS = {\n  length: 'Kamida 8 belgi',\n  lower: 'Kichik harf',\n  upper: 'Katta harf',\n  digit: 'Raqam',\n  symbol: 'Belgi (!@#…)',\n};\n\nexport default function CorePassword() {\n  const [password, setPassword] = useState('Parol123');\n  const { score, label, checks } = passwordStrength(password);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Parol\">\n        <Input type=\"password\" value={password} onChange={(e) => setPassword(e.target.value)} />\n      </Field>\n      <div className=\"flex gap-1\" aria-hidden>\n        {[1, 2, 3, 4].map((i) => (\n          <span\n            key={i}\n            className={`h-1.5 flex-1 rounded-full ${password && i <= Math.max(score, 1) ? BAR[score] : 'bg-surface-muted'}`}\n          />\n        ))}\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Badge color={COLOR[score]}>{label}</Badge>\n        <span className=\"text-xs text-text-muted\">score: {score}/4</span>\n      </div>\n      <ul className=\"flex flex-col gap-1 text-sm\">\n        {(Object.keys(CHECKS) as (keyof typeof CHECKS)[]).map((key) => (\n          <li key={key} className={checks[key] ? 'text-text' : 'text-text-muted'}>\n            {checks[key] ? '✓' : '○'} {CHECKS[key]}\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "core/phone-card": { component: Demo783, file: "core/phone-card.tsx", source: "'use client';\n\nimport { formatCardNumber, formatPhone } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst digitsOf = (s: string) => s.replace(/\\D/g, '');\n\nexport default function CorePhoneCard() {\n  const [phone, setPhone] = useState('90123');\n  const [card, setCard] = useState('8600 1234');\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" description={`formatPhone: ${formatPhone(phone) || '—'}`}>\n        <Input\n          prefix=\"+998\"\n          value={formatPhone(phone, 'national')}\n          onChange={(e) => setPhone(digitsOf(e.target.value).slice(0, 9))}\n          inputMode=\"tel\"\n          placeholder=\"(90) 123-45-67\"\n        />\n      </Field>\n      <Field label=\"Karta raqami\" description={`Toza qiymat: ${digitsOf(card) || '—'}`}>\n        <Input\n          value={card}\n          onChange={(e) => setCard(formatCardNumber(digitsOf(e.target.value).slice(0, 16)))}\n          inputMode=\"numeric\"\n          placeholder=\"0000 0000 0000 0000\"\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "core/phone-validate": { component: Demo784, file: "core/phone-validate.tsx", source: "'use client';\n\nimport { isValidEmail, parsePhone } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CorePhoneValidate() {\n  const [phone, setPhone] = useState('+998 90 123-45-67');\n  const [email, setEmail] = useState('sarvar@mail');\n  const parsed = parsePhone(phone);\n  const code = parsed.digits.slice(0, 2);\n  const phoneError =\n    code.length === 2 && !parsed.operator ? `\"${code}\" — bunday operator kodi yo'q` : undefined;\n  const emailValid = isValidEmail(email);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" error={phoneError} description={`digits: ${parsed.digits || '—'}`}>\n        <Input value={phone} onChange={(e) => setPhone(e.target.value)} inputMode=\"tel\" />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge color={parsed.valid ? 'success' : 'neutral'} dot>\n          {parsed.valid ? \"To'g'ri raqam\" : \"To'liq emas\"}\n        </Badge>\n        {parsed.operator && <Badge color=\"info\">Operator: {parsed.operator}</Badge>}\n      </div>\n      <Field\n        label=\"Email\"\n        error={email.trim() && !emailValid ? \"Email manzil noto'g'ri\" : undefined}\n      >\n        <Input type=\"email\" value={email} onChange={(e) => setEmail(e.target.value)} />\n      </Field>\n    </div>\n  );\n}\n" },
  "core/script": { component: Demo785, file: "core/script.tsx", source: "'use client';\n\nimport { detectScript, fixApostrophes, toScript } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst SAMPLES = [\n  \"O'zbekiston g'alabasi, ma'no\",\n  'Салом, дунё',\n  'Toshkent — Тошкент',\n  \"'Salom' dedi\",\n];\n\nexport default function CoreScript() {\n  const [text, setText] = useState(\"O'zbekiston g'alabasi, ma'no\");\n\n  const rows = [\n    { name: \"toScript(s, 'latin')\", value: toScript(text, 'latin') },\n    { name: \"toScript(s, 'cyrillic')\", value: toScript(text, 'cyrillic') },\n    { name: 'fixApostrophes', value: fixApostrophes(text) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Matn\">\n        <Input value={text} onChange={(e) => setText(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Badge color=\"info\">detectScript: {detectScript(text)}</Badge>\n        {SAMPLES.map((s) => (\n          <button key={s} type=\"button\" onClick={() => setText(s)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{s}</Badge>\n          </button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.name} className=\"flex items-center justify-between gap-4 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.name}</dt>\n            <dd className=\"font-mono break-all text-text\">{row.value || '—'}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "core/search": { component: Demo786, file: "core/search.tsx", source: "'use client';\n\nimport { searchMatch, splitByRanges } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CITIES = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  \"Farg'ona\",\n  'Qo‘qon',\n  'Shahrisabz',\n  'Chirchiq',\n  'Ғузор',\n  'Ўрта Чирчиқ',\n  'Шаҳрихон',\n];\n\nexport default function CoreSearch() {\n  const [query, setQuery] = useState('шаҳ');\n  const results = CITIES.map((city) => ({ city, ...searchMatch(city, query) })).filter(\n    (r) => r.match,\n  );\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Field label=\"Shahar qidirish\" description=\"Sinab ko'ring: chir, ғуз, fargona, qo'qon\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <ul className=\"flex flex-wrap gap-2\">\n        {results.map(({ city, ranges }) => (\n          <li key={city} className=\"rounded-lg border border-border bg-surface px-3 py-1.5 text-sm\">\n            {splitByRanges(city, ranges).map((part, i) =>\n              part.match ? (\n                <mark key={i} className=\"rounded-sm bg-primary-soft text-primary-soft-foreground\">\n                  {part.text}\n                </mark>\n              ) : (\n                <span key={i}>{part.text}</span>\n              ),\n            )}\n          </li>\n        ))}\n        {results.length === 0 && <li className=\"text-sm text-text-muted\">Hech narsa topilmadi</li>}\n      </ul>\n    </div>\n  );\n}\n" },
  "core/storage": { component: Demo787, file: "core/storage.tsx", source: "'use client';\n\nimport { createStorage } from '@akhatmirzo/core';\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst store = createStorage({ prefix: 'docs-demo:' });\n\nexport default function CoreStorage() {\n  const [value, setValue] = useState('Sarvar');\n  const [result, setResult] = useState('—');\n\n  const save = (ttl?: number) => {\n    const ok = store.set('ism', value, { ttl });\n    setResult(\n      ok ? `Saqlandi${ttl ? ` (${ttl / 1000} soniya)` : ' (muddatsiz)'}` : \"Saqlab bo'lmadi\",\n    );\n  };\n\n  const read = () => {\n    const saved = store.get<string>('ism');\n    setResult(saved === null ? \"null — yo'q yoki muddati o'tgan\" : JSON.stringify(saved));\n  };\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Qiymat\" description=\"Kalit: docs-demo:ism\">\n        <Input value={value} onChange={(e) => setValue(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        <Button variant=\"primary\" onClick={() => save(5000)}>\n          5 soniyaga saqlash\n        </Button>\n        <Button variant=\"outline\" onClick={() => save()}>\n          Muddatsiz\n        </Button>\n        <Button variant=\"ghost\" onClick={read}>\n          O'qish\n        </Button>\n      </div>\n      <p className=\"text-sm text-text-muted\">\n        Natija: <code className=\"font-mono text-text\">{result}</code>\n      </p>\n    </div>\n  );\n}\n" },
  "core/time-ago": { component: Demo788, file: "core/time-ago.tsx", source: "'use client';\n\nimport { timeAgo } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst MINUTE = 60_000;\nconst NOW = new Date(2026, 9, 21, 12, 0);\nconst OFFSETS = [5, 180, 1440, 4320, 20160, 136800, -120, -1440];\n\nexport default function CoreTimeAgo() {\n  const [minutes, setMinutes] = useState('90');\n  const custom = new Date(NOW.getTime() - Number(minutes || 0) * MINUTE);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Necha daqiqa oldin\" description={`timeAgo → ${timeAgo(custom, NOW)}`}>\n        <Input\n          value={minutes}\n          onChange={(e) => setMinutes(e.target.value.replace(/[^\\d-]/g, ''))}\n          inputMode=\"numeric\"\n          suffix=\"daqiqa\"\n        />\n      </Field>\n      <ul className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {OFFSETS.map((m) => (\n          <li key={m} className=\"flex justify-between gap-4 px-3 py-2\">\n            <span className=\"font-mono text-xs text-text-muted\">{m} daqiqa</span>\n            <span className=\"text-text\">{timeAgo(NOW.getTime() - m * MINUTE, NOW)}</span>\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "core/translit": { component: Demo789, file: "core/translit.tsx", source: "'use client';\n\nimport { cyrToLat, latToCyr, normalizeUz } from '@akhatmirzo/core';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst SAMPLES = ['Ғузор тумани', \"O'zbekiston\", 'Gʻuzor', 'ер, поезд, маъно', 'SHAHAR'];\n\nexport default function CoreTranslit() {\n  const [text, setText] = useState('Ғузор тумани');\n\n  const rows = [\n    { name: 'cyrToLat', value: cyrToLat(text) },\n    { name: 'latToCyr', value: latToCyr(text) },\n    { name: 'normalizeUz', value: normalizeUz(text) },\n  ];\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Matn\">\n        <Input value={text} onChange={(e) => setText(e.target.value)} />\n      </Field>\n      <div className=\"flex flex-wrap gap-2\">\n        {SAMPLES.map((s) => (\n          <button key={s} type=\"button\" onClick={() => setText(s)} className=\"cursor-pointer\">\n            <Badge variant=\"outline\">{s}</Badge>\n          </button>\n        ))}\n      </div>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        {rows.map((row) => (\n          <div key={row.name} className=\"flex items-center justify-between gap-4 px-3 py-2\">\n            <dt className=\"font-mono text-xs text-text-muted\">{row.name}</dt>\n            <dd className=\"font-mono break-all text-text\">{row.value || '—'}</dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n}\n" },
  "core/truncate": { component: Demo790, file: "core/truncate.tsx", source: "'use client';\n\nimport { slugify, truncate, truncateMiddle } from '@akhatmirzo/core';\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst FILE = 'shartnoma-mchj-akhatmirzo-imzolangan.docx';\n\nexport default function CoreTruncate() {\n  const [title, setTitle] = useState(\"Farg'ona viloyati — 2026\");\n  const [max, setMax] = useState(24);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Field label=\"Sarlavha\" description={`slugify: ${slugify(title) || '—'}`}>\n        <Input value={title} onChange={(e) => setTitle(e.target.value)} />\n      </Field>\n      <label className=\"flex flex-col gap-2 text-sm font-medium text-text\">\n        Maksimal uzunlik: {max}\n        <input\n          type=\"range\"\n          min={6}\n          max={44}\n          value={max}\n          onChange={(e) => setMax(Number(e.target.value))}\n          className=\"w-full accent-primary\"\n        />\n      </label>\n      <dl className=\"divide-y divide-border rounded-xl border border-border bg-surface text-sm\">\n        <div className=\"flex flex-col gap-1 px-3 py-2\">\n          <dt className=\"font-mono text-xs text-text-muted\">truncateMiddle</dt>\n          <dd className=\"font-mono text-text\">{truncateMiddle(FILE, max)}</dd>\n        </div>\n        <div className=\"flex flex-col gap-1 px-3 py-2\">\n          <dt className=\"font-mono text-xs text-text-muted\">truncate</dt>\n          <dd className=\"font-mono text-text\">{truncate(FILE, max)}</dd>\n        </div>\n      </dl>\n    </div>\n  );\n}\n" },
  "core/zod": { component: Demo791, file: "core/zod.tsx", source: "'use client';\n\nimport { zUz } from '@akhatmirzo/core/zod';\nimport { Field, Input, Select } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst schemas = {\n  phone: zUz.phone(),\n  pinfl: zUz.pinfl(),\n  passport: zUz.passport(),\n  carPlate: zUz.carPlate(),\n  card: zUz.card(),\n  money: zUz.money({ min: 1000 }),\n  password: zUz.password(),\n};\n\ntype Kind = keyof typeof schemas;\n\nexport default function CoreZod() {\n  const [kind, setKind] = useState<Kind>('phone');\n  const [text, setText] = useState('+998 90 123 45 67');\n  const result = schemas[kind].safeParse(text);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Sxema\">\n        <Select value={kind} onValueChange={(v) => setKind(v as Kind)}>\n          {Object.keys(schemas).map((k) => (\n            <Select.Item key={k} value={k}>{`zUz.${k}()`}</Select.Item>\n          ))}\n        </Select>\n      </Field>\n      <Field\n        label=\"Kiritilgan qiymat\"\n        error={result.success ? undefined : result.error.issues[0]?.message}\n      >\n        <Input value={text} onChange={(e) => setText(e.target.value)} />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Natija:{' '}\n        <code className=\"text-text\">{result.success ? JSON.stringify(result.data) : '—'}</code>\n      </p>\n    </div>\n  );\n}\n" },
  "data-table/basic": { component: Demo792, file: "data-table/basic.tsx", source: "'use client';\n\nimport { formatDate, formatMoney } from '@akhatmirzo/core';\nimport { Badge, Button, DataTable, toast, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Plus } from 'lucide-react';\n\ntype Status = 'paid' | 'pending' | 'shipped' | 'cancelled';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  date: Date;\n  status: Status;\n  total: number;\n}\n\nconst STATUS = {\n  paid: { label: \"To'langan\", color: 'success' },\n  pending: { label: 'Kutilmoqda', color: 'warning' },\n  shipped: { label: \"Yo'lda\", color: 'info' },\n  cancelled: { label: 'Bekor qilingan', color: 'danger' },\n} as const;\n\nconst NAMES = [\n  'Jasur Karimov',\n  'Malika Rahimova',\n  \"Bekzod G'aniyev\",\n  'Nodira Saidova',\n  'Aziz Normatov',\n];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\", 'Xorazm'];\nconst STATUSES = Object.keys(STATUS) as Status[];\n\nconst orders: Order[] = Array.from({ length: 48 }, (_, i) => ({\n  id: 1042 + i,\n  customer: NAMES[(i * 3) % NAMES.length]!,\n  region: REGIONS[(i * 7) % REGIONS.length]!,\n  date: new Date(2026, 9, 21 - (i % 30)),\n  status: STATUSES[(i * 5 + (i >> 2)) % 4]!,\n  total: 85_000 + ((i * 377_311) % 4_800_000),\n}));\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88, sortable: true, cell: (o) => `#${o.id}` },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  { key: 'region', header: 'Viloyat', sortable: true, filter: 'select' },\n  { key: 'date', header: 'Sana', sortable: true, cell: (o) => formatDate(o.date) },\n  {\n    key: 'status',\n    header: 'Holat',\n    filter: 'multiselect',\n    filterOptions: STATUSES.map((s) => ({ value: s, label: STATUS[s].label })),\n    searchValue: (o) => STATUS[o.status].label,\n    cell: (o) => (\n      <Badge dot color={STATUS[o.status].color}>\n        {STATUS[o.status].label}\n      </Badge>\n    ),\n  },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableBasic() {\n  return (\n    <DataTable\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      searchable\n      pagination={{ pageSize: 5, pageSizeOptions: [5, 10, 25] }}\n      className=\"w-full\"\n      toolbar={\n        <Button variant=\"primary\" leftIcon={<Plus />} onClick={() => toast('Yangi buyurtma')}>\n          Qo'shish\n        </Button>\n      }\n    />\n  );\n}\n" },
  "data-table/cards": { component: Demo793, file: "data-table/cards.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, toast, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  total: number;\n}\n\nconst orders: Order[] = [\n  { id: 1042, customer: 'Jasur Karimov', region: 'Toshkent', total: 1_250_000 },\n  { id: 1043, customer: 'Malika Rahimova', region: 'Samarqand', total: 480_000 },\n  { id: 1044, customer: 'Aziz Normatov', region: \"Farg'ona\", total: 2_730_000 },\n];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№' },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'region', header: 'Viloyat' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nexport default function DataTableCards() {\n  return (\n    <DataTable\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      mobileView=\"cards\"\n      selectable\n      onRowClick={(o) => toast(`Buyurtma #${o.id}`)}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "data-table/density": { component: Demo794, file: "data-table/density.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Employee {\n  id: number;\n  name: string;\n  position: string;\n  department: string;\n  phone: string;\n  city: string;\n  salary: number;\n}\n\nconst employees: Employee[] = [\n  {\n    id: 1,\n    name: 'Sarvar Abduxoliqov',\n    position: 'Frontend dasturchi',\n    department: 'IT',\n    phone: '+998 90 123 45 67',\n    city: 'Toshkent',\n    salary: 14_500_000,\n  },\n  {\n    id: 2,\n    name: \"Gulnora O'rinova\",\n    position: 'Buxgalter',\n    department: 'Moliya',\n    phone: '+998 93 555 12 34',\n    city: 'Samarqand',\n    salary: 9_800_000,\n  },\n  {\n    id: 3,\n    name: 'Javohir Ismoilov',\n    position: 'Dizayner',\n    department: 'Marketing',\n    phone: '+998 97 700 00 11',\n    city: 'Buxoro',\n    salary: 11_200_000,\n  },\n];\n\nconst columns: DataTableColumn<Employee>[] = [\n  { key: 'name', header: 'Xodim', width: 200, hideable: false },\n  { key: 'position', header: 'Lavozim' },\n  { key: 'department', header: \"Bo'lim\" },\n  { key: 'phone', header: 'Telefon', className: 'tabular-nums' },\n  { key: 'city', header: 'Shahar', hidden: true },\n  { key: 'salary', header: 'Maosh', numeric: true, cell: (e) => formatMoney(e.salary) },\n];\n\nexport default function DataTableDensity() {\n  return (\n    <DataTable\n      label=\"Xodimlar\"\n      data={employees}\n      columns={columns}\n      density=\"compact\"\n      stickyFirstColumn\n      selectable\n      tableClassName=\"min-w-[860px]\"\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "data-table/filters": { component: Demo795, file: "data-table/filters.tsx", source: "'use client';\n\nimport { formatDate, formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\n\ninterface Payment {\n  id: number;\n  client: string;\n  method: string;\n  region: string;\n  date: Date;\n  amount: number;\n}\n\nconst METHODS = ['Click', 'Payme', 'Uzcard', 'Naqd'];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Andijon', 'Namangan'];\nconst CLIENTS = ['Dilnoza Yusupova', 'Otabek Qodirov', 'Shahnoza Ergasheva', 'Rustam Xolmatov'];\n\nconst payments: Payment[] = Array.from({ length: 40 }, (_, i) => ({\n  id: 501 + i,\n  client: CLIENTS[(i * 3) % CLIENTS.length]!,\n  method: METHODS[(i * 5) % METHODS.length]!,\n  region: REGIONS[(i + (i >> 2)) % REGIONS.length]!,\n  date: new Date(2026, 9, 25 - i),\n  amount: 50_000 + ((i * 213_457) % 3_000_000),\n}));\n\nconst columns: DataTableColumn<Payment>[] = [\n  { key: 'id', header: '№', width: 72, cell: (p) => `#${p.id}` },\n  { key: 'client', header: 'Mijoz' },\n  { key: 'method', header: \"To'lov turi\", filter: 'select' },\n  { key: 'region', header: 'Viloyat', filter: 'multiselect' },\n  { key: 'date', header: 'Sana', filter: 'date', sortable: true, cell: (p) => formatDate(p.date) },\n  {\n    key: 'amount',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    filter: 'range',\n    cell: (p) => formatMoney(p.amount),\n  },\n];\n\nexport default function DataTableFilters() {\n  return (\n    <DataTable\n      label=\"To'lovlar\"\n      data={payments}\n      columns={columns}\n      searchable\n      pagination={{ pageSize: 5 }}\n      initialState={{ filters: { method: 'Click' } }}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "data-table/selection": { component: Demo796, file: "data-table/selection.tsx", source: "'use client';\n\nimport {\n  DataTable,\n  DropdownMenu,\n  IconButton,\n  toast,\n  type DataTableColumn,\n  Button,\n} from '@akhatmirzo/ui';\nimport { Download, Ellipsis, Eye, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\ninterface Product {\n  id: string;\n  name: string;\n  sku: string;\n  stock: number;\n}\n\nconst initial: Product[] = [\n  { id: 'p1', name: \"Paxta ko'ylak\", sku: 'KY-001', stock: 42 },\n  { id: 'p2', name: \"Atlas ro'mol\", sku: 'RM-014', stock: 8 },\n  { id: 'p3', name: 'Choynak (1.5 l)', sku: 'CH-203', stock: 0 },\n  { id: 'p4', name: \"Do'ppi\", sku: 'DP-077', stock: 120 },\n  { id: 'p5', name: 'Sopol lagan', sku: 'LG-310', stock: 15 },\n];\n\nconst columns: DataTableColumn<Product>[] = [\n  { key: 'name', header: 'Mahsulot', sortable: true },\n  { key: 'sku', header: 'Artikul' },\n  { key: 'stock', header: 'Qoldiq', numeric: true, sortable: true },\n];\n\nexport default function DataTableSelection() {\n  const [products, setProducts] = useState(initial);\n  const remove = (ids: string[]) => setProducts((prev) => prev.filter((p) => !ids.includes(p.id)));\n\n  return (\n    <DataTable\n      label=\"Mahsulotlar\"\n      data={products}\n      columns={columns}\n      selectable\n      className=\"w-full\"\n      onRowClick={(p) => toast(`${p.name} ochildi`)}\n      bulkActions={(rows, clear) => (\n        <>\n          <Button\n            variant=\"outline\"\n            size=\"sm\"\n            leftIcon={<Download />}\n            onClick={() => toast(`${rows.length} ta eksport qilindi`)}\n          >\n            Eksport\n          </Button>\n          <Button\n            variant=\"danger\"\n            size=\"sm\"\n            leftIcon={<Trash2 />}\n            onClick={() => {\n              remove(rows.map((r) => r.id));\n              clear();\n            }}\n          >\n            O'chirish\n          </Button>\n        </>\n      )}\n      rowActions={(p) => (\n        <DropdownMenu>\n          <DropdownMenu.Trigger asChild>\n            <IconButton variant=\"ghost\" size=\"sm\" aria-label={`${p.name}: amallar`}>\n              <Ellipsis />\n            </IconButton>\n          </DropdownMenu.Trigger>\n          <DropdownMenu.Content align=\"end\">\n            <DropdownMenu.Item icon={<Eye />} onSelect={() => toast(p.name)}>\n              Ko'rish\n            </DropdownMenu.Item>\n            <DropdownMenu.Item variant=\"danger\" icon={<Trash2 />} onSelect={() => remove([p.id])}>\n              O'chirish\n            </DropdownMenu.Item>\n          </DropdownMenu.Content>\n        </DropdownMenu>\n      )}\n    />\n  );\n}\n" },
  "data-table/server": { component: Demo797, file: "data-table/server.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn, type DataTableState } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\ninterface Page {\n  rows: Order[];\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\nconst DB: Order[] = Array.from({ length: 137 }, (_, i) => ({\n  id: 2001 + i,\n  customer: NAMES[i % NAMES.length]!,\n  total: 90_000 + ((i * 271_828) % 3_500_000),\n}));\n\n/** \"Server\": qidiradi, saralaydi, sahifalaydi. Haqiqiy loyihada — fetch('/api/orders?...') */\nfunction fetchOrders({ search, sorting, pagination }: DataTableState): Promise<Page> {\n  let rows = DB.filter((o) => o.customer.toLowerCase().includes(search.toLowerCase()));\n  const sort = sorting[0];\n  if (sort) {\n    const key = sort.id as keyof Order;\n    rows = [...rows].sort((a, b) => (a[key] > b[key] ? 1 : -1) * (sort.desc ? -1 : 1));\n  }\n  const start = pagination.pageIndex * pagination.pageSize;\n  const page = { rows: rows.slice(start, start + pagination.pageSize), total: rows.length };\n  return new Promise((resolve) => setTimeout(() => resolve(page), 600));\n}\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88, sortable: true },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableServer() {\n  const [query, setQuery] = useState<DataTableState>({\n    sorting: [],\n    search: '',\n    filters: {},\n    pagination: { pageIndex: 0, pageSize: 10 },\n  });\n  const [result, setResult] = useState<Page>({ rows: [], total: 0 });\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    let active = true;\n    fetchOrders(query).then((page) => {\n      if (!active) return;\n      setResult(page);\n      setLoading(false);\n    });\n    return () => {\n      active = false;\n    };\n  }, [query]);\n\n  return (\n    <DataTable\n      label=\"Server buyurtmalari\"\n      data={result.rows}\n      rowCount={result.total}\n      columns={columns}\n      manual\n      searchable\n      pagination={{ pageSize: 10 }}\n      loading={loading}\n      onStateChange={(state) => {\n        setLoading(true);\n        setQuery(state);\n      }}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "data-table/states": { component: Demo798, file: "data-table/states.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { Button, DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\nimport { useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\nconst orders: Order[] = [\n  { id: 1042, customer: 'Jasur Karimov', total: 1_250_000 },\n  { id: 1043, customer: 'Malika Rahimova', total: 480_000 },\n  { id: 1044, customer: 'Aziz Normatov', total: 2_730_000 },\n];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88 },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nconst STATES = {\n  data: \"Ma'lumot\",\n  first: 'Birinchi yuklanish',\n  refetch: 'Qayta yuklanish',\n  empty: \"Bo'sh\",\n  error: 'Xato',\n} as const;\n\ntype State = keyof typeof STATES;\n\nexport default function DataTableStates() {\n  const [state, setState] = useState<State>('first');\n\n  return (\n    <div className=\"flex w-full flex-col gap-4\">\n      <div className=\"flex flex-wrap gap-2\">\n        {(Object.keys(STATES) as State[]).map((s) => (\n          <Button\n            key={s}\n            size=\"sm\"\n            variant={s === state ? 'primary' : 'outline'}\n            aria-pressed={s === state}\n            onClick={() => setState(s)}\n          >\n            {STATES[s]}\n          </Button>\n        ))}\n      </div>\n      <DataTable\n        label=\"Holatlar\"\n        data={state === 'data' || state === 'refetch' ? orders : []}\n        columns={columns}\n        columnToggle={false}\n        loading={state === 'first' || state === 'refetch'}\n        error={\n          state === 'error' ? 'Server javob bermadi. Internet aloqasini tekshiring.' : undefined\n        }\n        onRetry={() => setState('data')}\n        empty={{\n          icon: <Inbox />,\n          title: \"Hali buyurtmalar yo'q\",\n          description: \"Birinchi buyurtmani qo'shing — u shu yerda ko'rinadi.\",\n          action: (\n            <Button size=\"sm\" variant=\"primary\" leftIcon={<Plus />}>\n              Buyurtma qo'shish\n            </Button>\n          ),\n        }}\n      />\n    </div>\n  );\n}\n" },
  "data-table/virtual": { component: Demo799, file: "data-table/virtual.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { useMemo } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  region: string;\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Farhod Tursunov', 'Mohira Nazarova'];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Buxoro', 'Navoiy', 'Xorazm'];\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 96, sortable: true },\n  { key: 'customer', header: 'Mijoz', sortable: true },\n  { key: 'region', header: 'Viloyat', filter: 'select' },\n  {\n    key: 'total',\n    header: 'Summa',\n    numeric: true,\n    sortable: true,\n    cell: (o) => formatMoney(o.total),\n  },\n];\n\nexport default function DataTableVirtual() {\n  const orders = useMemo<Order[]>(\n    () =>\n      Array.from({ length: 10_000 }, (_, i) => ({\n        id: i + 1,\n        customer: NAMES[i % NAMES.length]!,\n        region: REGIONS[(i * 3) % REGIONS.length]!,\n        total: 50_000 + ((i * 377_311) % 4_800_000),\n      })),\n    [],\n  );\n\n  return (\n    <DataTable\n      label=\"10 000 buyurtma\"\n      data={orders}\n      columns={columns}\n      virtual\n      maxHeight={400}\n      density=\"compact\"\n      searchable\n      columnToggle={false}\n      className=\"w-full\"\n    />\n  );\n}\n" },
  "date-picker/basic": { component: Demo800, file: "date-picker/basic.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DatePicker, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst isSunday = (date: Date) => date.getDay() === 0;\n\nexport default function DatePickerBasic() {\n  const [date, setDate] = useState<Date | null>(null);\n\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Field\n        label=\"Yetkazish sanasi\"\n        description={date ? formatDate(date, 'd MMMM yyyy, EEEE') : 'Yakshanba — dam olish kuni'}\n      >\n        <DatePicker\n          value={date}\n          onValueChange={setDate}\n          minDate={new Date()}\n          disabledDates={isSunday}\n          presets\n          clearable\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "date-picker/birthday": { component: Demo801, file: "date-picker/birthday.tsx", source: "'use client';\n\nimport { DatePicker, Field } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DatePickerBirthday() {\n  const [birthday, setBirthday] = useState<Date | null>(new Date(1995, 4, 17));\n\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Field label=\"Tug'ilgan sana\" description=\"Sarlavhani bosing — oy va yilni tanlash\">\n        <DatePicker\n          value={birthday}\n          onValueChange={setBirthday}\n          minDate={new Date(1920, 0, 1)}\n          maxDate={new Date()}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "date-picker/calendar-range": { component: Demo802, file: "date-picker/calendar-range.tsx", source: "'use client';\n\nimport { Calendar, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);\n\nexport default function CalendarRange() {\n  const today = new Date();\n  const [range, setRange] = useState<DateRangeValue>({\n    from: addDays(today, -3),\n    to: addDays(today, 4),\n  });\n\n  return (\n    <div className=\"flex flex-col items-center gap-2\">\n      <Calendar\n        mode=\"range\"\n        numberOfMonths={2}\n        value={range}\n        onValueChange={setRange}\n        className=\"rounded-xl border border-border bg-surface p-3\"\n      />\n      <span className=\"text-sm text-text-muted\">\n        {range.from && !range.to ? 'Tugash sanasini tanlang' : 'Oraliq tanlandi'}\n      </span>\n    </div>\n  );\n}\n" },
  "date-picker/calendar": { component: Demo803, file: "date-picker/calendar.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { Calendar } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CalendarInline() {\n  const [date, setDate] = useState<Date | null>(new Date());\n\n  return (\n    <div className=\"flex flex-col items-center gap-2\">\n      <Calendar\n        value={date}\n        onValueChange={setDate}\n        disabledDates={(d) => d.getDay() === 0}\n        className=\"rounded-xl border border-border bg-surface p-3\"\n      />\n      <span className=\"text-sm text-text-muted\">\n        {date ? formatDate(date, 'd MMMM yyyy, EEEE') : 'Sana tanlanmagan'}\n      </span>\n    </div>\n  );\n}\n" },
  "date-picker/range-presets": { component: Demo804, file: "date-picker/range-presets.tsx", source: "'use client';\n\nimport { DateRangePicker, Field, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);\n\nexport default function DateRangePickerPresets() {\n  const [vacation, setVacation] = useState<DateRangeValue | null>(null);\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Ta'til\" description=\"Yakshanbalar yopiq\">\n        <DateRangePicker\n          value={vacation}\n          onValueChange={setVacation}\n          minDate={new Date()}\n          disabledDates={(d) => d.getDay() === 0}\n          clearable\n          name=\"tatil\"\n          presets={[\n            { label: 'Bir hafta', range: (t) => ({ from: addDays(t, 1), to: addDays(t, 7) }) },\n            { label: 'Ikki hafta', range: (t) => ({ from: addDays(t, 1), to: addDays(t, 14) }) },\n          ]}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "date-picker/range": { component: Demo805, file: "date-picker/range.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DateRangePicker, Field, type DateRangeValue } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst daysAgo = (n: number) => {\n  const d = new Date();\n  return new Date(d.getFullYear(), d.getMonth(), d.getDate() - n);\n};\n\nexport default function DateRangePickerBasic() {\n  const [range, setRange] = useState<DateRangeValue | null>({ from: daysAgo(6), to: daysAgo(0) });\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field\n        label=\"Hisobot davri\"\n        description={\n          range?.from && range.to\n            ? `${formatDate(range.from, 'd MMM')} – ${formatDate(range.to, 'd MMM yyyy')}`\n            : 'Davr tanlanmagan'\n        }\n      >\n        <DateRangePicker value={range} onValueChange={setRange} presets maxDate={new Date()} />\n      </Field>\n    </div>\n  );\n}\n" },
  "date-picker/sizes": { component: Demo806, file: "date-picker/sizes.tsx", source: "'use client';\n\nimport { DatePicker } from '@akhatmirzo/ui';\n\nexport default function DatePickerSizes() {\n  const today = new Date();\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <DatePicker size=\"sm\" aria-label=\"Kichik\" defaultValue={today} />\n      <DatePicker size=\"md\" aria-label=\"O'rta\" defaultValue={today} />\n      <DatePicker size=\"lg\" aria-label=\"Katta\" defaultValue={today} />\n    </div>\n  );\n}\n" },
  "date-picker/states": { component: Demo807, file: "date-picker/states.tsx", source: "'use client';\n\nimport { DatePicker, Field } from '@akhatmirzo/ui';\n\nexport default function DatePickerStates() {\n  const today = new Date();\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"O'chirilgan\" disabled>\n        <DatePicker defaultValue={today} />\n      </Field>\n      <Field label=\"Faqat o'qish\">\n        <DatePicker defaultValue={today} readOnly />\n      </Field>\n      <Field label=\"Muddat\" error=\"Sanani tanlang\" required>\n        <DatePicker />\n      </Field>\n      <Field label=\"Boshqa format\" description=\"d MMMM yyyy\">\n        <DatePicker format=\"d MMMM yyyy\" defaultValue={today} />\n      </Field>\n    </div>\n  );\n}\n" },
  "date-picker/typing": { component: Demo808, file: "date-picker/typing.tsx", source: "'use client';\n\nimport { formatDate } from '@akhatmirzo/core';\nimport { DatePicker, Field, type DatePickerError } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst errorText: Record<DatePickerError, string> = {\n  invalid: \"Bunday sana yo'q\",\n  unavailable: \"O'tgan sanani tanlab bo'lmaydi\",\n};\n\nexport default function DatePickerTyping() {\n  const [date, setDate] = useState<Date | null>(null);\n  const [error, setError] = useState<DatePickerError | null>(null);\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field\n        label=\"Uchrashuv sanasi\"\n        required\n        error={error ? errorText[error] : undefined}\n        description=\"Sinab ko'ring: 31022026\"\n      >\n        <DatePicker\n          value={date}\n          onValueChange={setDate}\n          onErrorChange={setError}\n          minDate={new Date()}\n        />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Qiymat: <code>{date ? formatDate(date, 'yyyy-MM-dd') : 'null'}</code>\n      </p>\n    </div>\n  );\n}\n" },
  "dialog/async-submit": { component: Demo809, file: "dialog/async-submit.tsx", source: "'use client';\n\nimport { Button, Dialog, Field, Input, Textarea, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function DialogAsyncSubmit() {\n  const [open, setOpen] = useState(false);\n  const [sending, setSending] = useState(false);\n\n  const send = async () => {\n    setSending(true);\n    await wait(1500);\n    setSending(false);\n    setOpen(false);\n    toast.success('Fikringiz yuborildi');\n  };\n\n  return (\n    <Dialog open={open} onOpenChange={(next) => !sending && setOpen(next)}>\n      <Dialog.Trigger asChild>\n        <Button>Fikr bildirish</Button>\n      </Dialog.Trigger>\n      <Dialog.Content title=\"Fikr bildirish\" size=\"lg\" dismissible={!sending}>\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Mavzu\" required>\n            <Input placeholder=\"Masalan: yetkazib berish\" />\n          </Field>\n          <Field label=\"Xabar\">\n            <Textarea minRows={4} placeholder=\"Fikringizni yozing...\" />\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button disabled={sending}>Bekor qilish</Button>\n          </Dialog.Close>\n          <Button variant=\"primary\" loading={sending} onClick={send}>\n            Yuborish\n          </Button>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "dialog/basic": { component: Demo810, file: "dialog/basic.tsx", source: "'use client';\n\nimport { Button, Dialog, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DialogBasic() {\n  const [open, setOpen] = useState(false);\n  const [name, setName] = useState('Sarvar');\n  const [phone, setPhone] = useState('+998 90 123 45 67');\n\n  return (\n    <Dialog open={open} onOpenChange={setOpen}>\n      <Dialog.Trigger asChild>\n        <Button variant=\"primary\">Profilni tahrirlash</Button>\n      </Dialog.Trigger>\n      <Dialog.Content title=\"Profilni tahrirlash\" description=\"O'zgarishlar darhol saqlanadi.\">\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Ism\">\n            <Input value={name} onChange={(e) => setName(e.target.value)} />\n          </Field>\n          <Field label=\"Telefon\" description=\"Tasdiqlash uchun SMS kod yuboriladi\">\n            <Input value={phone} onChange={(e) => setPhone(e.target.value)} />\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button>Bekor qilish</Button>\n          </Dialog.Close>\n          <Button variant=\"primary\" onClick={() => setOpen(false)}>\n            Saqlash\n          </Button>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "dialog/confirm-dialog": { component: Demo811, file: "dialog/confirm-dialog.tsx", source: "'use client';\n\nimport { Button, ConfirmDialog, toast } from '@akhatmirzo/ui';\n\nexport default function DialogConfirmDeclarative() {\n  return (\n    <ConfirmDialog\n      trigger={<Button variant=\"outline\">Hisobdan chiqish</Button>}\n      title=\"Hisobdan chiqilsinmi?\"\n      description=\"Qayta kirish uchun SMS kod kerak bo'ladi.\"\n      confirmText=\"Chiqish\"\n      onConfirm={() => toast('Hisobdan chiqdingiz')}\n      onCancel={() => toast.info('Hisobda qoldingiz')}\n    />\n  );\n}\n" },
  "dialog/confirm": { component: Demo812, file: "dialog/confirm.tsx", source: "'use client';\n\nimport { Button, confirm, toast } from '@akhatmirzo/ui';\nimport { Trash2 } from 'lucide-react';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function DialogConfirm() {\n  const removeOrder = async () => {\n    const ok = await confirm({\n      title: \"Buyurtma o'chirilsinmi?\",\n      description: \"Bu amalni qaytarib bo'lmaydi.\",\n      confirmText: \"O'chirish\",\n      variant: 'danger',\n    });\n    if (ok) toast.success(\"Buyurtma #1042 o'chirildi\");\n  };\n\n  const publish = async () => {\n    const ok = await confirm({\n      title: 'Mahsulot nashr qilinsinmi?',\n      description: \"Mahsulot do'konda hammaga ko'rinadi.\",\n      confirmText: 'Nashr qilish',\n      // Promise tugaguncha tugma loading, oyna ochiq turadi\n      onConfirm: () => wait(1500),\n    });\n    if (ok) toast.success('Mahsulot nashr qilindi');\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"danger\" leftIcon={<Trash2 />} onClick={removeOrder}>\n        O'chirish\n      </Button>\n      <Button variant=\"primary\" onClick={publish}>\n        Nashr qilish\n      </Button>\n    </div>\n  );\n}\n" },
  "dialog/options": { component: Demo813, file: "dialog/options.tsx", source: "'use client';\n\nimport { Button, Dialog } from '@akhatmirzo/ui';\n\nexport default function DialogOptions() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">dismissible=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content\n          title=\"Shartlarni o'qing\"\n          description=\"Tashqariga bosish yopmaydi — faqat tugma yoki Esc.\"\n          dismissible={false}\n        >\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Roziman</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">closeButton=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content title=\"✕ tugmasisiz\" closeButton={false} size=\"sm\">\n          <p className=\"m-0 text-sm text-text-muted\">Oyna faqat pastdagi tugma bilan yopiladi.</p>\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Yopish</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">hideTitle</Button>\n        </Dialog.Trigger>\n        <Dialog.Content title=\"Mahsulot rasmi\" hideTitle size=\"sm\">\n          <div className=\"grid h-40 place-items-center rounded-xl bg-surface-muted text-sm text-text-muted\">\n            Sarlavha faqat ekran o'quvchi uchun\n          </div>\n        </Dialog.Content>\n      </Dialog>\n\n      <Dialog>\n        <Dialog.Trigger asChild>\n          <Button variant=\"outline\">mobileSheet=false</Button>\n        </Dialog.Trigger>\n        <Dialog.Content\n          title=\"Doim markazda\"\n          description=\"Telefonda ham pastdan chiqmaydi.\"\n          mobileSheet={false}\n          size=\"sm\"\n        >\n          <Dialog.Footer>\n            <Dialog.Close asChild>\n              <Button variant=\"primary\">Yaxshi</Button>\n            </Dialog.Close>\n          </Dialog.Footer>\n        </Dialog.Content>\n      </Dialog>\n    </div>\n  );\n}\n" },
  "dialog/sizes": { component: Demo814, file: "dialog/sizes.tsx", source: "'use client';\n\nimport { Button, Dialog, type DialogSize } from '@akhatmirzo/ui';\n\nconst sizes: { size: DialogSize; width: string }[] = [\n  { size: 'sm', width: '400px' },\n  { size: 'md', width: '520px' },\n  { size: 'lg', width: '640px' },\n  { size: 'xl', width: '800px' },\n  { size: 'full', width: 'butun ekran' },\n];\n\nexport default function DialogSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sizes.map(({ size, width }) => (\n        <Dialog key={size}>\n          <Dialog.Trigger asChild>\n            <Button variant=\"outline\">{size}</Button>\n          </Dialog.Trigger>\n          <Dialog.Content\n            title={`O'lcham: ${size}`}\n            description={`Kenglik — ${width}.`}\n            size={size}\n          >\n            <p className=\"m-0 text-sm text-text-muted\">\n              Ekran tor bo'lsa, chetlarda 16px joy qoladi. Telefonda oyna pastdan chiqadi.\n            </p>\n            <Dialog.Footer>\n              <Dialog.Close asChild>\n                <Button variant=\"primary\">Tushunarli</Button>\n              </Dialog.Close>\n            </Dialog.Footer>\n          </Dialog.Content>\n        </Dialog>\n      ))}\n    </div>\n  );\n}\n" },
  "dialog/with-select": { component: Demo815, file: "dialog/with-select.tsx", source: "'use client';\n\nimport { Button, Combobox, Dialog, Field, Select } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro', 'Andijon', \"Farg'ona\", 'Namangan'].map(\n  (label) => ({ value: label.toLowerCase().replace(/'/g, ''), label }),\n);\n\nexport default function DialogWithSelect() {\n  const [city, setCity] = useState<string | null>('toshkent');\n\n  return (\n    <Dialog>\n      <Dialog.Trigger asChild>\n        <Button variant=\"outline\">Yetkazib berish manzili</Button>\n      </Dialog.Trigger>\n      <Dialog.Content\n        title=\"Yetkazib berish manzili\"\n        description=\"Ro'yxatlar oyna ustida ochiladi.\"\n      >\n        <div className=\"flex flex-col gap-4\">\n          <Field label=\"Shahar\">\n            <Combobox options={cities} value={city} onValueChange={setCity} clearable />\n          </Field>\n          <Field label=\"Yetkazish vaqti\">\n            <Select defaultValue=\"morning\">\n              <Select.Item value=\"morning\">Ertalab (9:00–12:00)</Select.Item>\n              <Select.Item value=\"day\">Kunduzi (12:00–17:00)</Select.Item>\n              <Select.Item value=\"evening\">Kechqurun (17:00–21:00)</Select.Item>\n            </Select>\n          </Field>\n        </div>\n        <Dialog.Footer>\n          <Dialog.Close asChild>\n            <Button>Bekor qilish</Button>\n          </Dialog.Close>\n          <Dialog.Close asChild>\n            <Button variant=\"primary\">Saqlash</Button>\n          </Dialog.Close>\n        </Dialog.Footer>\n      </Dialog.Content>\n    </Dialog>\n  );\n}\n" },
  "divider/basic": { component: Demo816, file: "divider/basic.tsx", source: "'use client';\n\nimport { Divider } from '@akhatmirzo/ui';\n\nexport default function DividerBasic() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3 text-sm text-text\">\n      <div className=\"flex justify-between\">\n        <span>Mahsulotlar</span>\n        <span>220 000 so'm</span>\n      </div>\n      <div className=\"flex justify-between text-text-muted\">\n        <span>Yetkazib berish</span>\n        <span>25 000 so'm</span>\n      </div>\n      <Divider />\n      <div className=\"flex justify-between font-semibold\">\n        <span>Jami</span>\n        <span>245 000 so'm</span>\n      </div>\n    </div>\n  );\n}\n" },
  "divider/label": { component: Demo817, file: "divider/label.tsx", source: "'use client';\n\nimport { Button, Divider } from '@akhatmirzo/ui';\n\nexport default function DividerLabel() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Button variant=\"primary\" fullWidth>\n        Telefon orqali kirish\n      </Button>\n      <Divider label=\"yoki\" />\n      <Button variant=\"outline\" fullWidth>\n        Google orqali kirish\n      </Button>\n    </div>\n  );\n}\n" },
  "divider/vertical": { component: Demo818, file: "divider/vertical.tsx", source: "'use client';\n\nimport { Divider } from '@akhatmirzo/ui';\n\nexport default function DividerVertical() {\n  return (\n    <div className=\"flex h-5 items-center gap-3 text-sm font-medium text-text-subtle\">\n      <span>Bosh sahifa</span>\n      <Divider orientation=\"vertical\" decorative />\n      <span>Buyurtmalar</span>\n      <Divider orientation=\"vertical\" decorative />\n      <span>Sozlamalar</span>\n    </div>\n  );\n}\n" },
  "document-inputs/car-plate": { component: Demo819, file: "document-inputs/car-plate.tsx", source: "'use client';\n\nimport { CarPlateInput, Field, type CarPlateInputDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CarPlateDemo() {\n  const [details, setDetails] = useState<CarPlateInputDetails | null>(null);\n\n  const type =\n    details?.type === 'legal' ? 'yuridik shaxs' : details?.type ? 'jismoniy shaxs' : null;\n  const description = [details?.region?.name, type].filter(Boolean).join(' · ');\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Jismoniy shaxs\" description={description || '01 A 123 BC'}>\n        <CarPlateInput defaultValue=\"01A123BC\" onDetails={setDetails} />\n      </Field>\n      <Field label=\"Yuridik shaxs\" description=\"01 123 ABC\">\n        <CarPlateInput defaultValue=\"30123ABC\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "document-inputs/overview": { component: Demo820, file: "document-inputs/overview.tsx", source: "'use client';\n\nimport {\n  BankAccountInput,\n  CarPlateInput,\n  Field,\n  InnInput,\n  PassportInput,\n  PinflInput,\n} from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DocumentInputsOverview() {\n  const [pinfl, setPinfl] = useState('');\n  const [passport, setPassport] = useState('');\n  const [inn, setInn] = useState('');\n  const [plate, setPlate] = useState('');\n  const [account, setAccount] = useState('');\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"JShShIR\" description={`Qiymat: \"${pinfl}\"`}>\n        <PinflInput value={pinfl} onValueChange={setPinfl} />\n      </Field>\n      <Field label=\"Pasport yoki ID karta\" description={`Qiymat: \"${passport}\"`}>\n        <PassportInput value={passport} onValueChange={setPassport} />\n      </Field>\n      <Field label=\"STIR\" description={`Qiymat: \"${inn}\"`}>\n        <InnInput value={inn} onValueChange={setInn} />\n      </Field>\n      <Field label=\"Avtomobil raqami\" description={`Qiymat: \"${plate}\"`}>\n        <CarPlateInput value={plate} onValueChange={setPlate} />\n      </Field>\n      <Field label=\"Hisob raqami\" description={`Qiymat: \"${account}\"`} className=\"sm:col-span-2\">\n        <BankAccountInput value={account} onValueChange={setAccount} />\n      </Field>\n    </div>\n  );\n}\n" },
  "document-inputs/pinfl": { component: Demo821, file: "document-inputs/pinfl.tsx", source: "'use client';\n\nimport { Field, PinflInput, type PinflInputDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PinflDemo() {\n  const [details, setDetails] = useState<PinflInputDetails | null>(null);\n\n  const info =\n    details?.valid && details.birthDate\n      ? `${details.gender === 'male' ? 'Erkak' : 'Ayol'}, tugʻilgan: ${details.birthDate.toLocaleDateString('uz-UZ')}`\n      : undefined;\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field\n        label=\"JShShIR\"\n        description={info ?? '14 raqam — pasportdagi shaxsiy raqam'}\n        error={details && !details.valid ? 'JShShIR notoʻgʻri' : undefined}\n      >\n        <PinflInput\n          onValueChange={(_, d) => {\n            if (!d.complete) setDetails(null);\n          }}\n          onDetails={setDetails}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "document-inputs/validation": { component: Demo822, file: "document-inputs/validation.tsx", source: "'use client';\n\nimport { Field, InnInput, PassportInput } from '@akhatmirzo/ui';\n\nexport default function DocumentValidation() {\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"STIR\" description=\"0 bilan boshlanmaydi — darhol xato\">\n        <InnInput defaultValue=\"012345678\" />\n      </Field>\n      <Field label=\"Pasport\" description=\"validate={false} — tekshiruvsiz\">\n        <PassportInput defaultValue=\"AB1234567\" validate={false} />\n      </Field>\n    </div>\n  );\n}\n" },
  "drawer/details": { component: Demo823, file: "drawer/details.tsx", source: "'use client';\n\nimport { Button, Drawer } from '@akhatmirzo/ui';\n\nconst rows = [\n  ['Mijoz', 'Sarvar Abduxoliqov'],\n  ['Telefon', '+998 90 123 45 67'],\n  ['Manzil', 'Toshkent, Chilonzor tumani, 9-mavze'],\n  [\"To'lov\", 'Naqd, yetkazib berilganda'],\n  ['Jami', \"1 250 000 so'm\"],\n];\n\nexport default function DrawerDetails() {\n  return (\n    <Drawer>\n      <Drawer.Trigger asChild>\n        <Button>Buyurtma #1042</Button>\n      </Drawer.Trigger>\n      <Drawer.Content size=\"lg\" title=\"Buyurtma #1042\" description=\"21-oktabr, 14:32\">\n        <dl className=\"m-0 grid grid-cols-[auto_1fr] gap-x-6 gap-y-3 text-sm\">\n          {rows.map(([label, value]) => (\n            <div key={label} className=\"contents\">\n              <dt className=\"text-text-muted\">{label}</dt>\n              <dd className=\"m-0 font-medium text-text\">{value}</dd>\n            </div>\n          ))}\n        </dl>\n        <Drawer.Footer>\n          <Drawer.Close asChild>\n            <Button>Yopish</Button>\n          </Drawer.Close>\n          <Button variant=\"primary\">Yetkazildi deb belgilash</Button>\n        </Drawer.Footer>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "drawer/filters": { component: Demo824, file: "drawer/filters.tsx", source: "'use client';\n\nimport { Button, Checkbox, Drawer, Field, Input, Switch } from '@akhatmirzo/ui';\nimport { SlidersHorizontal } from 'lucide-react';\nimport { useState } from 'react';\n\nconst categories = ['Elektronika', 'Kiyim-kechak', \"Uy-ro'zg'or\", 'Kitoblar'];\n\nexport default function DrawerFilters() {\n  const [open, setOpen] = useState(false);\n  const [selected, setSelected] = useState<string[]>(['Elektronika']);\n\n  const toggle = (name: string, on: boolean) =>\n    setSelected((prev) => (on ? [...prev, name] : prev.filter((x) => x !== name)));\n\n  return (\n    <Drawer open={open} onOpenChange={setOpen}>\n      <Drawer.Trigger asChild>\n        <Button variant=\"outline\" leftIcon={<SlidersHorizontal />}>\n          Filtrlar\n        </Button>\n      </Drawer.Trigger>\n      <Drawer.Content title=\"Filtrlar\" description=\"Natijalarni toraytiring.\">\n        <div className=\"flex flex-col gap-5\">\n          <div className=\"grid grid-cols-2 gap-3\">\n            <Field label=\"Narxdan\">\n              <Input inputMode=\"numeric\" placeholder=\"0\" suffix=\"so'm\" />\n            </Field>\n            <Field label=\"Narxgacha\">\n              <Input inputMode=\"numeric\" placeholder=\"1 000 000\" suffix=\"so'm\" />\n            </Field>\n          </div>\n          <div className=\"flex flex-col gap-3\">\n            {categories.map((c) => (\n              <Checkbox\n                key={c}\n                label={c}\n                checked={selected.includes(c)}\n                onCheckedChange={(on) => toggle(c, on)}\n              />\n            ))}\n          </div>\n          <Switch label=\"Faqat mavjudlari\" defaultChecked />\n        </div>\n        <Drawer.Footer>\n          <Button onClick={() => setSelected([])}>Tozalash</Button>\n          <Button variant=\"primary\" onClick={() => setOpen(false)}>\n            Qo'llash\n          </Button>\n        </Drawer.Footer>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "drawer/mobile-menu": { component: Demo825, file: "drawer/mobile-menu.tsx", source: "'use client';\n\nimport { Button, Drawer } from '@akhatmirzo/ui';\nimport { Menu } from 'lucide-react';\nimport { useState } from 'react';\n\nconst items = ['Bosh sahifa', 'Buyurtmalar', 'Mahsulotlar', 'Mijozlar', 'Hisobotlar'];\n\nexport default function DrawerMobileMenu() {\n  const [active, setActive] = useState('Buyurtmalar');\n\n  return (\n    <Drawer>\n      <Drawer.Trigger asChild>\n        <Button variant=\"ghost\" leftIcon={<Menu />}>\n          Menyu\n        </Button>\n      </Drawer.Trigger>\n      <Drawer.Content\n        side=\"left\"\n        size=\"sm\"\n        title=\"Menyu\"\n        hideTitle\n        labels={{ close: 'Menyuni yopish' }}\n      >\n        <nav aria-label=\"Asosiy menyu\" className=\"-mx-2 flex flex-col gap-1\">\n          {items.map((item) => (\n            <Drawer.Close asChild key={item}>\n              <button\n                type=\"button\"\n                aria-current={item === active ? 'page' : undefined}\n                onClick={() => setActive(item)}\n                className=\"focus-ring flex h-10 cursor-pointer items-center rounded-lg border-0 bg-transparent px-3 text-left text-sm font-medium text-text hover:bg-surface-muted aria-[current=page]:bg-primary-soft aria-[current=page]:text-primary-soft-foreground\"\n              >\n                {item}\n              </button>\n            </Drawer.Close>\n          ))}\n        </nav>\n      </Drawer.Content>\n    </Drawer>\n  );\n}\n" },
  "drawer/sides": { component: Demo826, file: "drawer/sides.tsx", source: "'use client';\n\nimport { Button, Drawer, type DrawerSide } from '@akhatmirzo/ui';\n\nconst sides: { side: DrawerSide; label: string }[] = [\n  { side: 'right', label: \"O'ngdan\" },\n  { side: 'left', label: 'Chapdan' },\n  { side: 'bottom', label: 'Pastdan' },\n  { side: 'top', label: 'Tepadan' },\n];\n\nexport default function DrawerSides() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sides.map(({ side, label }) => (\n        <Drawer key={side}>\n          <Drawer.Trigger asChild>\n            <Button variant=\"outline\">{label}</Button>\n          </Drawer.Trigger>\n          <Drawer.Content side={side} title={label} description={`side=\"${side}\"`}>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Panel ekran chetidan siljib chiqadi. Pastdan chiqqanda tepada tutqich chizig'i bor.\n            </p>\n            <Drawer.Footer>\n              <Drawer.Close asChild>\n                <Button variant=\"primary\">Yopish</Button>\n              </Drawer.Close>\n            </Drawer.Footer>\n          </Drawer.Content>\n        </Drawer>\n      ))}\n    </div>\n  );\n}\n" },
  "drawer/sizes": { component: Demo827, file: "drawer/sizes.tsx", source: "'use client';\n\nimport { Button, Drawer, type DrawerSize } from '@akhatmirzo/ui';\n\nconst sizes: { size: DrawerSize; px: string }[] = [\n  { size: 'sm', px: '320px' },\n  { size: 'md', px: '420px' },\n  { size: 'lg', px: '560px' },\n];\n\nexport default function DrawerSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sizes.map(({ size, px }) => (\n        <Drawer key={size}>\n          <Drawer.Trigger asChild>\n            <Button variant=\"outline\">\n              {size} — {px}\n            </Button>\n          </Drawer.Trigger>\n          <Drawer.Content size={size} title={`O'lcham: ${size}`} description={`Kenglik ${px}`}>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Chap va o'ngda o'lcham kenglikni, past va tepada balandlikni belgilaydi.\n            </p>\n          </Drawer.Content>\n        </Drawer>\n      ))}\n    </div>\n  );\n}\n" },
  "dropdown-menu/basic": { component: Demo828, file: "dropdown-menu/basic.tsx", source: "'use client';\n\nimport { Button, DropdownMenu, toast } from '@akhatmirzo/ui';\nimport { Archive, ChevronDown, Copy, Pencil, Trash2 } from 'lucide-react';\n\nexport default function DropdownMenuBasic() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <Button variant=\"outline\" rightIcon={<ChevronDown />}>\n          Amallar\n        </Button>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content>\n        <DropdownMenu.Item\n          icon={<Pencil />}\n          shortcut={['mod', 'E']}\n          onSelect={() => toast('Tahrirlash')}\n        >\n          Tahrirlash\n        </DropdownMenu.Item>\n        <DropdownMenu.Item\n          icon={<Copy />}\n          shortcut={['mod', 'D']}\n          onSelect={() => toast('Nusxa olindi')}\n        >\n          Nusxa olish\n        </DropdownMenu.Item>\n        <DropdownMenu.Item icon={<Archive />} onSelect={() => toast('Arxivlandi')}>\n          Arxivlash\n        </DropdownMenu.Item>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\" onSelect={() => toast(\"O'chirildi\")}>\n          O'chirish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "dropdown-menu/checkbox-radio": { component: Demo829, file: "dropdown-menu/checkbox-radio.tsx", source: "'use client';\n\nimport { DropdownMenu } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function DropdownMenuCheckboxRadio() {\n  const [columns, setColumns] = useState({ price: true, stock: true, sku: false });\n  const [sort, setSort] = useState('new');\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <DropdownMenu>\n        <DropdownMenu.Trigger>Ustunlar</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Label>Jadvalda ko'rsatish</DropdownMenu.Label>\n          {(\n            [\n              ['price', 'Narx'],\n              ['stock', 'Ombordagi soni'],\n              ['sku', 'Artikul'],\n            ] as const\n          ).map(([key, label]) => (\n            <DropdownMenu.CheckboxItem\n              key={key}\n              checked={columns[key]}\n              onCheckedChange={(on) => setColumns((c) => ({ ...c, [key]: on }))}\n              // Menyu yopilmasin — bir nechtasini ketma-ket belgilash uchun\n              onSelect={(e) => e.preventDefault()}\n            >\n              {label}\n            </DropdownMenu.CheckboxItem>\n          ))}\n        </DropdownMenu.Content>\n      </DropdownMenu>\n\n      <DropdownMenu>\n        <DropdownMenu.Trigger>Saralash</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Label>Tartib</DropdownMenu.Label>\n          <DropdownMenu.RadioGroup value={sort} onValueChange={setSort}>\n            <DropdownMenu.RadioItem value=\"new\">Avval yangilari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"cheap\">Avval arzonlari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"expensive\">Avval qimmatlari</DropdownMenu.RadioItem>\n            <DropdownMenu.RadioItem value=\"popular\" disabled>\n              Ommabop (tez orada)\n            </DropdownMenu.RadioItem>\n          </DropdownMenu.RadioGroup>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n      <span className=\"text-sm text-text-muted\">Saralash: {sort}</span>\n    </div>\n  );\n}\n" },
  "dropdown-menu/profile": { component: Demo830, file: "dropdown-menu/profile.tsx", source: "'use client';\n\nimport { Button, DropdownMenu } from '@akhatmirzo/ui';\nimport { LogOut, Send, Settings, User } from 'lucide-react';\n\nexport default function DropdownMenuProfile() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <Button variant=\"ghost\" leftIcon={<User />}>\n          Akmal Karimov\n        </Button>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content align=\"end\" className=\"w-56\">\n        <DropdownMenu.Label>akmal@misol.uz</DropdownMenu.Label>\n        <DropdownMenu.Group>\n          <DropdownMenu.Item icon={<User />} shortcut={['mod', 'P']}>\n            Profil\n          </DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Settings />} shortcut={['mod', ',']}>\n            Sozlamalar\n          </DropdownMenu.Item>\n          <DropdownMenu.Item asChild icon={<Send />}>\n            <a href=\"https://github.com/Akhatmirzo/akhatmirzo-toolkit\">Loyiha GitHub'da</a>\n          </DropdownMenu.Item>\n        </DropdownMenu.Group>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<LogOut />} variant=\"danger\">\n          Chiqish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "dropdown-menu/states": { component: Demo831, file: "dropdown-menu/states.tsx", source: "'use client';\n\nimport { Button, DropdownMenu } from '@akhatmirzo/ui';\nimport { Copy, Pencil, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function DropdownMenuStates() {\n  const [open, setOpen] = useState(false);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <DropdownMenu>\n        <DropdownMenu.Trigger>O'chirilgan elementlar</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Item icon={<Pencil />}>Tahrirlash</DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Copy />} disabled>\n            Nusxa olish (ruxsat yo'q)\n          </DropdownMenu.Item>\n          <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\" disabled>\n            O'chirish (ruxsat yo'q)\n          </DropdownMenu.Item>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n\n      <DropdownMenu open={open} onOpenChange={setOpen}>\n        <DropdownMenu.Trigger>Boshqariladigan</DropdownMenu.Trigger>\n        <DropdownMenu.Content>\n          <DropdownMenu.Item>Birinchi</DropdownMenu.Item>\n          <DropdownMenu.Item>Ikkinchi</DropdownMenu.Item>\n        </DropdownMenu.Content>\n      </DropdownMenu>\n      <Button variant=\"ghost\" onClick={() => setOpen(true)}>\n        Tashqaridan ochish\n      </Button>\n    </div>\n  );\n}\n" },
  "dropdown-menu/submenu": { component: Demo832, file: "dropdown-menu/submenu.tsx", source: "'use client';\n\nimport { DropdownMenu, IconButton } from '@akhatmirzo/ui';\nimport { Archive, Ellipsis, Pencil, Share2, Trash2 } from 'lucide-react';\n\nexport default function DropdownMenuSubmenu() {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>\n        <IconButton variant=\"outline\" aria-label=\"Ko'proq amallar\">\n          <Ellipsis />\n        </IconButton>\n      </DropdownMenu.Trigger>\n      <DropdownMenu.Content>\n        <DropdownMenu.Item icon={<Pencil />}>Nomini o'zgartirish</DropdownMenu.Item>\n        <DropdownMenu.Sub>\n          <DropdownMenu.SubTrigger icon={<Share2 />}>Ulashish</DropdownMenu.SubTrigger>\n          <DropdownMenu.SubContent>\n            <DropdownMenu.Item>Telegram</DropdownMenu.Item>\n            <DropdownMenu.Item>Email orqali</DropdownMenu.Item>\n            <DropdownMenu.Item shortcut={['mod', 'L']}>Havolani nusxalash</DropdownMenu.Item>\n          </DropdownMenu.SubContent>\n        </DropdownMenu.Sub>\n        <DropdownMenu.Sub>\n          <DropdownMenu.SubTrigger icon={<Archive />}>Ko'chirish</DropdownMenu.SubTrigger>\n          <DropdownMenu.SubContent>\n            <DropdownMenu.Item>Kiruvchi</DropdownMenu.Item>\n            <DropdownMenu.Item>Arxiv</DropdownMenu.Item>\n          </DropdownMenu.SubContent>\n        </DropdownMenu.Sub>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<Trash2 />} variant=\"danger\">\n          O'chirish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n" },
  "empty-state/basic": { component: Demo833, file: "empty-state/basic.tsx", source: "'use client';\n\nimport { Button, EmptyState } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\n\nexport default function EmptyStateBasic() {\n  return (\n    <EmptyState\n      icon={<Inbox />}\n      title=\"Buyurtmalar hali yo'q\"\n      description=\"Birinchi buyurtma kelganda shu yerda ko'rinadi.\"\n      action={\n        <Button variant=\"primary\" leftIcon={<Plus />}>\n          Mahsulot qo'shish\n        </Button>\n      }\n      secondaryAction={<Button variant=\"ghost\">Qo'llanma</Button>}\n    />\n  );\n}\n" },
  "empty-state/data-table": { component: Demo834, file: "empty-state/data-table.tsx", source: "'use client';\n\nimport { Button, DataTable, type DataTableColumn } from '@akhatmirzo/ui';\nimport { Inbox, Plus } from 'lucide-react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: string;\n}\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№' },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa' },\n];\n\nconst orders: Order[] = [];\n\nexport default function EmptyStateDataTable() {\n  return (\n    <DataTable\n      className=\"w-full\"\n      label=\"Buyurtmalar\"\n      data={orders}\n      columns={columns}\n      empty={{\n        icon: <Inbox />,\n        title: \"Buyurtmalar hali yo'q\",\n        description: \"Birinchi buyurtma kelganda shu yerda ko'rinadi.\",\n        action: (\n          <Button size=\"sm\" variant=\"primary\" leftIcon={<Plus />}>\n            Buyurtma qo'shish\n          </Button>\n        ),\n      }}\n    />\n  );\n}\n" },
  "empty-state/search": { component: Demo835, file: "empty-state/search.tsx", source: "'use client';\n\nimport { Button, EmptyState, Input } from '@akhatmirzo/ui';\nimport { SearchX } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function EmptyStateSearch() {\n  const [query, setQuery] = useState('Namangan');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Input\n        aria-label=\"Shahar qidirish\"\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Shahar nomi\"\n      />\n      <EmptyState\n        size=\"sm\"\n        bordered\n        icon={<SearchX />}\n        title=\"Hech narsa topilmadi\"\n        description={`\"${query}\" bo'yicha natija yo'q. So'zni o'zgartirib ko'ring.`}\n        action={\n          <Button size=\"sm\" onClick={() => setQuery('')}>\n            Qidiruvni tozalash\n          </Button>\n        }\n      />\n    </div>\n  );\n}\n" },
  "empty-state/sizes": { component: Demo836, file: "empty-state/sizes.tsx", source: "'use client';\n\nimport { EmptyState } from '@akhatmirzo/ui';\nimport { FolderOpen } from 'lucide-react';\n\nexport default function EmptyStateSizes() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <EmptyState bordered size=\"sm\" icon={<FolderOpen />} title=\"Kichik\" description=\"sm\" />\n      <EmptyState bordered size=\"md\" icon={<FolderOpen />} title=\"O'rta\" description=\"md\" />\n      <EmptyState bordered size=\"lg\" icon={<FolderOpen />} title=\"Katta\" description=\"lg\" />\n    </div>\n  );\n}\n" },
  "field/basic": { component: Demo837, file: "field/basic.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function FieldBasic() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" required description=\"Tasdiqlash kodi SMS orqali yuboriladi\">\n        <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" />\n      </Field>\n      <Field label=\"Email\" error=\"Email manzil noto'g'ri\">\n        <Input type=\"email\" defaultValue=\"sarvar@mail\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "field/custom-control": { component: Demo838, file: "field/custom-control.tsx", source: "'use client';\n\nimport { Field, useFieldControl } from '@akhatmirzo/ui';\n\nfunction CitySelect() {\n  const { controlProps, invalid, disabled } = useFieldControl();\n  return (\n    <select\n      {...controlProps}\n      disabled={disabled}\n      data-invalid={invalid ? '' : undefined}\n      className=\"h-10 rounded-lg border border-border bg-surface px-3 text-sm text-text data-invalid:border-danger\"\n    >\n      <option value=\"\">Tanlang</option>\n      <option>Toshkent</option>\n      <option>Samarqand</option>\n      <option>Buxoro</option>\n    </select>\n  );\n}\n\nexport default function FieldCustomControl() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Shahar\" required error=\"Shaharni tanlang\">\n        <CitySelect />\n      </Field>\n    </div>\n  );\n}\n" },
  "field/disabled": { component: Demo839, file: "field/disabled.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function FieldDisabled() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Hudud\" description=\"Hudud administrator tomonidan belgilanadi\" disabled>\n        <Input defaultValue=\"Toshkent shahri\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "field/horizontal": { component: Demo840, file: "field/horizontal.tsx", source: "'use client';\n\nimport { Field, Input, Textarea } from '@akhatmirzo/ui';\n\nexport default function FieldHorizontal() {\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-4\">\n      <Field orientation=\"horizontal\" label=\"Do'kon nomi\" description=\"Chekda ko'rinadi\">\n        <Input defaultValue=\"Bahor Market\" />\n      </Field>\n      <Field orientation=\"horizontal\" label=\"Manzil\">\n        <Textarea minRows={2} defaultValue=\"Toshkent, Chilonzor tumani, 9-kvartal\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "field/validation": { component: Demo841, file: "field/validation.tsx", source: "'use client';\n\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function FieldValidation() {\n  const [name, setName] = useState('');\n  const [submitted, setSubmitted] = useState(false);\n  const error = submitted && name.trim().length < 3 ? 'Kamida 3 ta harf kiriting' : undefined;\n\n  const submit = (event: FormEvent) => {\n    event.preventDefault();\n    setSubmitted(true);\n  };\n\n  return (\n    <form onSubmit={submit} noValidate className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"To'liq ism\" required error={error}>\n        <Input\n          value={name}\n          onChange={(e) => setName(e.target.value)}\n          placeholder=\"Sarvar Abduxoliqov\"\n          autoComplete=\"name\"\n        />\n      </Field>\n      <Button type=\"submit\" variant=\"primary\">\n        Davom etish\n      </Button>\n    </form>\n  );\n}\n" },
  "file-upload/basic": { component: Demo842, file: "file-upload/basic.tsx", source: "'use client';\n\nimport { Field, FileUpload, type FileUploadContext, type FileUploadItem } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst MB = 1024 * 1024;\n\n/** Soxta yuklash: progress bilan ~2 soniya. Nomida \"xato\" bo'lsa — tarmoq xatosi */\nfunction fakeUpload(file: File, { onProgress, signal }: FileUploadContext) {\n  return new Promise<{ url: string }>((resolve, reject) => {\n    let progress = 0;\n    const timer = setInterval(() => {\n      progress = Math.min(100, progress + 8);\n      onProgress(progress);\n      if (file.name.includes('xato') && progress > 50) {\n        clearInterval(timer);\n        reject(new Error('network'));\n      } else if (progress === 100) {\n        clearInterval(timer);\n        resolve({ url: `/uploads/${encodeURIComponent(file.name)}` });\n      }\n    }, 150);\n    signal.addEventListener('abort', () => clearInterval(timer));\n  });\n}\n\nexport default function FileUploadBasic() {\n  const [files, setFiles] = useState<FileUploadItem[]>([]);\n  const done = files.filter((f) => f.status === 'done').length;\n\n  return (\n    <div className=\"flex w-full max-w-lg flex-col gap-2\">\n      <Field label=\"Hujjatlar\">\n        <FileUpload\n          accept={['image/*', '.pdf']}\n          maxSize={5 * MB}\n          maxFiles={5}\n          multiple\n          upload={fakeUpload}\n          onFilesChange={setFiles}\n        />\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Jami: {files.length} · yuklandi: {done}\n      </p>\n    </div>\n  );\n}\n" },
  "file-upload/button": { component: Demo843, file: "file-upload/button.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadButton() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Pasport nusxasi\" description=\"Old va orqa tomoni\">\n        <FileUpload\n          variant=\"button\"\n          accept={['image/*', '.pdf']}\n          maxSize={5 * 1024 * 1024}\n          maxFiles={2}\n          multiple\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "file-upload/form": { component: Demo844, file: "file-upload/form.tsx", source: "'use client';\n\nimport { formatFileSize } from '@akhatmirzo/core';\nimport { Button, Field, FileUpload } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function FileUploadForm() {\n  const [sent, setSent] = useState<string | null>(null);\n\n  const onSubmit = (e: FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    const files = (new FormData(e.currentTarget).getAll('rezyume') as File[]).filter(\n      (f) => f.size > 0,\n    );\n    setSent(files.map((f) => `${f.name} (${formatFileSize(f.size)})`).join(', ') || \"Fayl yo'q\");\n  };\n\n  return (\n    <form onSubmit={onSubmit} className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Rezyume\" description=\"PDF yoki DOCX, 2 MB gacha\">\n        <FileUpload\n          variant=\"button\"\n          name=\"rezyume\"\n          accept={['.pdf', '.docx']}\n          maxSize={2 * 1024 * 1024}\n        />\n      </Field>\n      <div className=\"flex items-center gap-3\">\n        <Button type=\"submit\" variant=\"primary\" size=\"sm\">\n          Yuborish\n        </Button>\n        {sent && <span className=\"text-sm text-text-muted\">{sent}</span>}\n      </div>\n    </form>\n  );\n}\n" },
  "file-upload/paste": { component: Demo845, file: "file-upload/paste.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadPaste() {\n  return (\n    <div className=\"w-full max-w-lg\">\n      <Field\n        label=\"Skrinshot\"\n        description=\"Rasmni nusxalang va sahifaning istalgan joyida Ctrl+V bosing\"\n      >\n        <FileUpload accept={['image/*']} multiple maxFiles={3} paste=\"global\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "file-upload/states": { component: Demo846, file: "file-upload/states.tsx", source: "'use client';\n\nimport { Field, FileUpload } from '@akhatmirzo/ui';\n\nexport default function FileUploadStates() {\n  return (\n    <div className=\"grid w-full gap-4 md:grid-cols-2\">\n      <Field label=\"Faqat rasm\" description=\"Bitta fayl — yangisi eskisini almashtiradi\">\n        <FileUpload accept={['image/png', 'image/jpeg']} maxSize={1024 * 1024} />\n      </Field>\n      <Field label=\"Shartnoma\" error=\"Kamida bitta hujjat yuklang\" required>\n        <FileUpload accept={['.pdf']} />\n      </Field>\n      <Field label=\"O'chirilgan\" disabled>\n        <FileUpload />\n      </Field>\n      <Field label=\"O'z cheklov matni bilan\">\n        <FileUpload hint=\"Excel yoki CSV · 10 MB gacha\" accept={['.xlsx', '.csv']} />\n      </Field>\n    </div>\n  );\n}\n" },
  "form/listing": { component: Demo847, file: "form/listing.tsx", source: "'use client';\n\nimport { zUz } from '@akhatmirzo/core/zod';\nimport { FileUpload, MoneyInput, SegmentedControl, TagInput, toast } from '@akhatmirzo/ui';\nimport { Form, FormField, FormSubmit } from '@akhatmirzo/ui/form';\nimport { zodResolver } from '@hookform/resolvers/zod';\nimport { useForm } from 'react-hook-form';\nimport { z } from 'zod';\n\nconst schema = z.object({\n  condition: z.enum(['new', 'used'], { error: 'Holatini tanlang' }),\n  price: zUz.money({ min: 10_000, max: 500_000_000 }),\n  tags: z.array(z.string()).min(1, 'Kamida bitta teg').max(5, \"Ko'pi bilan 5 ta teg\"),\n  photos: z.array(z.unknown()).min(1, 'Kamida bitta rasm yuklang'),\n});\n\nexport default function FormListing() {\n  const form = useForm({\n    resolver: zodResolver(schema),\n    defaultValues: { price: null, tags: [], photos: [] },\n  });\n\n  return (\n    <Form\n      form={form}\n      onSubmit={(data) => {\n        toast.success(\"E'lon saqlandi\", {\n          description: `${data.price} so'm · ${data.tags.join(', ')}`,\n        });\n        form.reset();\n      }}\n      className=\"flex w-full max-w-md flex-col gap-4\"\n    >\n      <FormField name=\"condition\" label=\"Holati\">\n        <SegmentedControl fullWidth>\n          <SegmentedControl.Item value=\"new\">Yangi</SegmentedControl.Item>\n          <SegmentedControl.Item value=\"used\">Ishlatilgan</SegmentedControl.Item>\n        </SegmentedControl>\n      </FormField>\n      <FormField name=\"price\" label=\"Narxi\" description=\"10 000 so'mdan 500 mln so'mgacha\">\n        <MoneyInput showWords />\n      </FormField>\n      <FormField name=\"tags\" label=\"Teglar\" description=\"Enter yoki vergul bilan qo'shing\">\n        <TagInput placeholder=\"telefon, samsung\" />\n      </FormField>\n      <FormField name=\"photos\" label=\"Rasmlar\">\n        <FileUpload accept={['image/*']} multiple maxFiles={4} />\n      </FormField>\n      <FormSubmit>E'lonni joylash</FormSubmit>\n    </Form>\n  );\n}\n" },
  "form/registration": { component: Demo848, file: "form/registration.tsx", source: "'use client';\n\nimport { zUz } from '@akhatmirzo/core/zod';\nimport {\n  Checkbox,\n  DatePicker,\n  Input,\n  PhoneInput,\n  PinflInput,\n  Radio,\n  RadioGroup,\n  RegionSelect,\n} from '@akhatmirzo/ui';\nimport { Form, FormField, FormRootError, FormSubmit } from '@akhatmirzo/ui/form';\nimport { zodResolver } from '@hookform/resolvers/zod';\nimport { useState } from 'react';\nimport { useForm } from 'react-hook-form';\nimport { z } from 'zod';\n\nconst schema = z.object({\n  fullName: z.string().trim().min(3, \"To'liq ismingizni kiriting\"),\n  phone: zUz.phone(),\n  pinfl: zUz.pinfl(),\n  birthDate: z.date({ error: \"Tug'ilgan sanani kiriting\" }),\n  gender: z.enum(['male', 'female'], { error: 'Jinsni tanlang' }),\n  region: zUz.region(),\n  password: zUz.password({ minScore: 2 }),\n  terms: z.literal(true, { error: 'Shartlarga rozilik bering' }),\n});\n\ntype Registration = z.output<typeof schema>;\n\nexport default function FormRegistration() {\n  const [saved, setSaved] = useState<Registration | null>(null);\n  const form = useForm({\n    resolver: zodResolver(schema),\n    defaultValues: { fullName: '', phone: '', pinfl: '', region: '', password: '' },\n  });\n\n  const save = async (data: Registration) => {\n    await new Promise((r) => setTimeout(r, 600));\n    if (data.pinfl.startsWith('6')) {\n      form.setError('root', {\n        message: \"Bu JShShIR bilan foydalanuvchi allaqachon ro'yxatdan o'tgan\",\n      });\n      return;\n    }\n    setSaved(data);\n  };\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Form form={form} onSubmit={save} className=\"flex flex-col gap-4\">\n        <FormField name=\"fullName\" label=\"To'liq ism\" required>\n          <Input placeholder=\"Sarvar Abduxoliqov\" autoComplete=\"name\" />\n        </FormField>\n        <FormField name=\"phone\" label=\"Telefon\" description=\"SMS kod yuboriladi\" required>\n          <PhoneInput />\n        </FormField>\n        <FormField name=\"pinfl\" label=\"JShShIR\" description=\"Pasportdagi 14 xonali raqam\" required>\n          <PinflInput />\n        </FormField>\n        <FormField name=\"birthDate\" label=\"Tug'ilgan sana\" required>\n          <DatePicker />\n        </FormField>\n        <FormField name=\"gender\" label=\"Jinsi\" required>\n          <RadioGroup orientation=\"horizontal\">\n            <Radio value=\"male\" label=\"Erkak\" />\n            <Radio value=\"female\" label=\"Ayol\" />\n          </RadioGroup>\n        </FormField>\n        <FormField name=\"region\" label=\"Hudud\" required>\n          <RegionSelect />\n        </FormField>\n        <FormField name=\"password\" label=\"Parol\" required>\n          <Input type=\"password\" autoComplete=\"new-password\" />\n        </FormField>\n        <FormField name=\"terms\">\n          <Checkbox label=\"Foydalanish shartlariga roziman\" />\n        </FormField>\n        <FormRootError />\n        <FormSubmit fullWidth>Ro'yxatdan o'tish</FormSubmit>\n      </Form>\n      {saved && (\n        <pre className=\"overflow-x-auto rounded-lg bg-surface-muted p-3 text-xs text-text-muted\">\n          {JSON.stringify(saved, null, 2)}\n        </pre>\n      )}\n    </div>\n  );\n}\n" },
  "form/render-fallback": { component: Demo849, file: "form/render-fallback.tsx", source: "'use client';\n\nimport { cn } from '@akhatmirzo/ui';\nimport { Form, FormField, FormSubmit } from '@akhatmirzo/ui/form';\nimport { zodResolver } from '@hookform/resolvers/zod';\nimport { useForm } from 'react-hook-form';\nimport { z } from 'zod';\n\nconst slots = ['09:00–12:00', '12:00–15:00', '15:00–18:00', '18:00–21:00'];\n\nconst schema = z.object({\n  slot: z.string().min(1, 'Yetkazib berish vaqtini tanlang'),\n});\n\nexport default function FormRenderFallback() {\n  const form = useForm({ resolver: zodResolver(schema), defaultValues: { slot: '' } });\n\n  return (\n    <Form\n      form={form}\n      onSubmit={(data) => alert(`Tanlandi: ${data.slot}`)}\n      className=\"flex w-full max-w-sm flex-col gap-4\"\n    >\n      <FormField\n        name=\"slot\"\n        label=\"Yetkazib berish vaqti\"\n        render={({ value, onValueChange, controlProps, invalid }) => (\n          <div {...controlProps} role=\"radiogroup\" className=\"grid grid-cols-2 gap-2\">\n            {slots.map((slot) => (\n              <button\n                key={slot}\n                type=\"button\"\n                role=\"radio\"\n                aria-checked={value === slot}\n                onClick={() => onValueChange(slot)}\n                className={cn(\n                  'rounded-lg border px-3 py-2 text-sm tabular-nums',\n                  value === slot\n                    ? 'border-primary bg-primary-soft text-primary-soft-foreground'\n                    : 'border-border bg-surface text-text',\n                  invalid && value !== slot && 'border-danger',\n                )}\n              >\n                {slot}\n              </button>\n            ))}\n          </div>\n        )}\n      />\n      <FormSubmit>Tasdiqlash</FormSubmit>\n    </Form>\n  );\n}\n" },
  "hooks/async": { component: Demo850, file: "hooks/async.tsx", source: "'use client';\n\nimport { useAsync, useToggle } from '@akhatmirzo/hooks';\nimport { Badge, Button, Switch } from '@akhatmirzo/ui';\n\nconst CITIES = ['Toshkent', 'Samarqand', 'Buxoro', 'Xiva', 'Namangan', 'Andijon', 'Nukus'];\nconst STATUS_COLOR = {\n  idle: 'neutral',\n  loading: 'info',\n  success: 'success',\n  error: 'danger',\n} as const;\n\nfunction fetchCities(fail: boolean): Promise<string[]> {\n  const delay = 500 + Math.random() * 1000;\n  return new Promise((resolve, reject) =>\n    setTimeout(() => {\n      if (fail) reject(new Error('Server javob bermadi'));\n      else resolve(CITIES.slice(0, 2 + Math.floor(Math.random() * 5)));\n    }, delay),\n  );\n}\n\nexport default function HooksAsync() {\n  const [fail, , setFail] = useToggle(false);\n  const { status, data, error, run } = useAsync(fetchCities, [], { immediate: false });\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Button onClick={() => void run(fail)} loading={status === 'loading'}>\n          Yuklash\n        </Button>\n        <Badge color={STATUS_COLOR[status]} dot>\n          {status}\n        </Badge>\n      </div>\n      <Switch checked={fail} onCheckedChange={setFail} label=\"Xato bilan tugasin\" />\n      {status === 'error' && error instanceof Error && (\n        <p className=\"text-sm text-danger-soft-foreground\">{error.message}</p>\n      )}\n      {data && <p className=\"text-sm text-text\">{data.join(', ')}</p>}\n    </div>\n  );\n}\n" },
  "hooks/click-outside": { component: Demo851, file: "hooks/click-outside.tsx", source: "'use client';\n\nimport { useClickOutside, useHotkeys, useToggle } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useRef } from 'react';\n\nexport default function HooksClickOutside() {\n  const [open, toggle, setOpen] = useToggle(false);\n  const triggerRef = useRef<HTMLButtonElement>(null);\n  const panelRef = useRef<HTMLDivElement>(null);\n\n  useClickOutside([triggerRef, panelRef], () => setOpen(false), open);\n  useHotkeys('esc', () => setOpen(false), { enabled: open });\n\n  return (\n    <div className=\"relative flex flex-col items-center gap-2\">\n      <Button ref={triggerRef} variant=\"outline\" onClick={toggle} aria-expanded={open}>\n        Filtrlar\n      </Button>\n      {open && (\n        <div\n          ref={panelRef}\n          className=\"w-64 rounded-xl border border-border bg-surface-raised p-4 text-sm text-text shadow-lg\"\n        >\n          Panel tashqarisiga bosing yoki <kbd className=\"font-mono\">Esc</kbd> ni bosing — yopiladi.\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  "hooks/controllable-state": { component: Demo852, file: "hooks/controllable-state.tsx", source: "'use client';\n\nimport { useControllableState } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\ninterface StepperProps {\n  value?: number;\n  defaultValue?: number;\n  onValueChange?: (value: number) => void;\n}\n\nfunction Stepper({ value, defaultValue = 0, onValueChange }: StepperProps) {\n  const [count, setCount] = useControllableState({ value, defaultValue, onChange: onValueChange });\n  return (\n    <div className=\"flex items-center gap-2\">\n      <Button size=\"sm\" variant=\"outline\" onClick={() => setCount((n) => n - 1)}>\n        −\n      </Button>\n      <span className=\"min-w-8 text-center font-semibold text-text tabular-nums\">{count}</span>\n      <Button size=\"sm\" variant=\"outline\" onClick={() => setCount((n) => n + 1)}>\n        +\n      </Button>\n    </div>\n  );\n}\n\nexport default function HooksControllableState() {\n  const [value, setValue] = useState(10);\n\n  return (\n    <div className=\"grid w-full max-w-md gap-6 sm:grid-cols-2\">\n      <div className=\"flex flex-col gap-2\">\n        <p className=\"text-xs font-medium text-text-muted\">Boshqarilmaydigan (defaultValue=3)</p>\n        <Stepper defaultValue={3} />\n      </div>\n      <div className=\"flex flex-col gap-2\">\n        <p className=\"text-xs font-medium text-text-muted\">Boshqariladigan (0…20)</p>\n        <Stepper value={value} onValueChange={(v) => setValue(Math.min(20, Math.max(0, v)))} />\n      </div>\n    </div>\n  );\n}\n" },
  "hooks/copy": { component: Demo853, file: "hooks/copy.tsx", source: "'use client';\n\nimport { useCopyToClipboard } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { Check, Copy } from 'lucide-react';\n\nexport default function HooksCopy() {\n  const { copied, copy } = useCopyToClipboard();\n  const command = 'pnpm add @akhatmirzo/hooks';\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <code className=\"rounded-lg border border-border bg-surface-muted px-3 py-2 font-mono text-sm text-text\">\n        {command}\n      </code>\n      <Button\n        variant={copied ? 'soft' : 'outline'}\n        leftIcon={copied ? <Check /> : <Copy />}\n        onClick={() => void copy(command)}\n      >\n        {copied ? 'Nusxalandi' : 'Nusxa olish'}\n      </Button>\n    </div>\n  );\n}\n" },
  "hooks/countdown": { component: Demo854, file: "hooks/countdown.tsx", source: "'use client';\n\nimport { useCountdown } from '@akhatmirzo/hooks';\nimport { Button, Field, OtpInput, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksCountdown() {\n  const [code, setCode] = useState('');\n  const { formatted, isRunning, restart } = useCountdown(59);\n\n  const resend = () => {\n    // Haqiqiy ilovada — SMS yuborish so'rovi\n    setCode('');\n    toast('Yangi kod +998 90 *** ** 67 ga yuborildi');\n    restart();\n  };\n\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <Field label=\"Tasdiqlash kodi\" description=\"+998 90 *** ** 67 ga yuborildi\">\n        <OtpInput groupSize={3} value={code} onValueChange={setCode} />\n      </Field>\n      <Button variant=\"ghost\" size=\"sm\" disabled={isRunning} onClick={resend}>\n        {isRunning ? `Kodni qayta yuborish (${formatted})` : 'Kodni qayta yuborish'}\n      </Button>\n    </div>\n  );\n}\n" },
  "hooks/debounce": { component: Demo855, file: "hooks/debounce.tsx", source: "'use client';\n\nimport { useDebounce } from '@akhatmirzo/hooks';\nimport { Badge, Field, Input } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CITIES = [\n  'Toshkent',\n  'Samarqand',\n  'Buxoro',\n  'Xiva',\n  'Namangan',\n  'Andijon',\n  'Nukus',\n  'Termiz',\n];\n\nexport default function HooksDebounce() {\n  const [query, setQuery] = useState('');\n  const debounced = useDebounce(query, 400);\n  const results = CITIES.filter((c) => c.toLowerCase().includes(debounced.trim().toLowerCase()));\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Shahar qidirish\" description=\"Natija yozishni to'xtatganingizdan 400 ms keyin\">\n        <Input value={query} onChange={(e) => setQuery(e.target.value)} clearable />\n      </Field>\n      <Badge color={query === debounced ? 'success' : 'warning'} dot className=\"self-start\">\n        {query === debounced ? 'Yangilangan' : 'Kutilmoqda…'}\n      </Badge>\n      <div className=\"flex flex-wrap gap-2\">\n        {results.map((city) => (\n          <Badge key={city} variant=\"outline\">\n            {city}\n          </Badge>\n        ))}\n        {results.length === 0 && (\n          <span className=\"text-sm text-text-muted\">Hech narsa topilmadi</span>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "hooks/debounced-callback": { component: Demo856, file: "hooks/debounced-callback.tsx", source: "'use client';\n\nimport { useDebouncedCallback } from '@akhatmirzo/hooks';\nimport { Button, Field, Textarea } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksDebouncedCallback() {\n  const [text, setText] = useState('');\n  const [saved, setSaved] = useState<string[]>([]);\n\n  const save = useDebouncedCallback((value: string) => {\n    setSaved((list) => [`${value.length} belgi saqlandi`, ...list].slice(0, 3));\n  }, 800);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Field label=\"Izoh\" description=\"Avtomatik saqlash: yozishni to'xtatgach 800 ms o'tib\">\n        <Textarea\n          value={text}\n          onChange={(e) => {\n            setText(e.target.value);\n            save(e.target.value);\n          }}\n          minRows={3}\n        />\n      </Field>\n      <Button size=\"sm\" variant=\"outline\" className=\"self-start\" onClick={save.flush}>\n        Hozir saqlash\n      </Button>\n      <ul className=\"text-sm text-text-muted\">\n        {saved.map((line, i) => (\n          <li key={i}>{line}</li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n" },
  "hooks/document-visibility": { component: Demo857, file: "hooks/document-visibility.tsx", source: "'use client';\n\nimport { useDocumentVisibility } from '@akhatmirzo/hooks';\nimport { Badge } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\nexport default function HooksDocumentVisibility() {\n  const visibility = useDocumentVisibility();\n  const [seconds, setSeconds] = useState(0);\n\n  // Tab yashirin bo'lsa, taymer to'xtaydi — resurs tejaladi\n  useEffect(() => {\n    if (visibility === 'hidden') return;\n    const id = setInterval(() => setSeconds((s) => s + 1), 1000);\n    return () => clearInterval(id);\n  }, [visibility]);\n\n  return (\n    <div className=\"flex flex-col items-center gap-3 text-sm text-text\">\n      <Badge color={visibility === 'visible' ? 'success' : 'neutral'} dot>\n        {visibility === 'visible' ? \"Tab ko'rinib turibdi\" : 'Tab yashirin'}\n      </Badge>\n      <p>\n        Faol vaqt: <span className=\"font-mono\">{seconds} s</span>\n      </p>\n      <p className=\"text-text-muted\">Boshqa tabga o'tib qayting — hisob to'xtab turadi</p>\n    </div>\n  );\n}\n" },
  "hooks/event-listener": { component: Demo858, file: "hooks/event-listener.tsx", source: "'use client';\n\nimport { useEventListener } from '@akhatmirzo/hooks';\nimport { Badge, Kbd } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksEventListener() {\n  const [width, setWidth] = useState<number | null>(null);\n  const [lastKey, setLastKey] = useState<string | null>(null);\n\n  // Qisqa shakl — window uchun, SSR-xavfsiz\n  useEventListener('resize', () => setWidth(window.innerWidth));\n  useEventListener('keydown', (event) => setLastKey(event.key));\n\n  return (\n    <div className=\"flex flex-col items-center gap-3 text-sm text-text\">\n      <p className=\"text-text-muted\">Oyna o'lchamini o'zgartiring yoki istalgan tugmani bosing</p>\n      <div className=\"flex flex-wrap items-center justify-center gap-2\">\n        <Badge variant=\"outline\">Kenglik: {width === null ? '—' : `${width}px`}</Badge>\n        <span className=\"flex items-center gap-1\">\n          Oxirgi tugma: {lastKey ? <Kbd>{lastKey === ' ' ? 'Space' : lastKey}</Kbd> : '—'}\n        </span>\n      </div>\n    </div>\n  );\n}\n" },
  "hooks/focus-trap": { component: Demo859, file: "hooks/focus-trap.tsx", source: "'use client';\n\nimport { useFocusTrap, useHotkeys, useToggle } from '@akhatmirzo/hooks';\nimport { Button, Field, Input } from '@akhatmirzo/ui';\nimport { useRef } from 'react';\n\nexport default function HooksFocusTrap() {\n  const [open, toggle, setOpen] = useToggle(false);\n  const panelRef = useRef<HTMLDivElement>(null);\n  const inputRef = useRef<HTMLInputElement>(null);\n\n  useFocusTrap(panelRef, open, { initialFocus: inputRef });\n  useHotkeys('esc', () => setOpen(false), { enabled: open, enableOnInputs: true });\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col items-center gap-3\">\n      <Button variant=\"outline\" onClick={toggle} aria-expanded={open}>\n        {open ? 'Yopish' : \"Manzil qo'shish\"}\n      </Button>\n      {open && (\n        <div\n          ref={panelRef}\n          className=\"flex w-full flex-col gap-3 rounded-xl border border-border bg-surface-raised p-4 shadow-lg\"\n        >\n          <Field label=\"Shahar\">\n            <Input ref={inputRef} placeholder=\"Toshkent\" />\n          </Field>\n          <Field label=\"Ko'cha\">\n            <Input placeholder=\"Amir Temur ko'chasi, 15\" />\n          </Field>\n          <div className=\"flex justify-end gap-2\">\n            <Button variant=\"ghost\" onClick={() => setOpen(false)}>\n              Bekor qilish\n            </Button>\n            <Button variant=\"primary\" onClick={() => setOpen(false)}>\n              Saqlash\n            </Button>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  "hooks/hotkeys": { component: Demo860, file: "hooks/hotkeys.tsx", source: "'use client';\n\nimport { useHotkeys } from '@akhatmirzo/hooks';\nimport { Badge, Kbd } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksHotkeys() {\n  const [last, setLast] = useState<string | null>(null);\n  const [count, setCount] = useState(0);\n\n  const hit = (name: string) => {\n    setLast(name);\n    setCount((n) => n + 1);\n  };\n\n  useHotkeys('alt+k', () => hit('alt+k'));\n  useHotkeys('?', () => hit('?'));\n  // Bir nechta kombinatsiya — vergul bilan\n  useHotkeys('g, alt+g', () => hit('g'));\n\n  return (\n    <div className=\"flex flex-col items-center gap-3 text-sm text-text\">\n      <div className=\"flex flex-wrap items-center justify-center gap-3\">\n        <Kbd keys={['Alt', 'K']} />\n        <Kbd>?</Kbd>\n        <Kbd>G</Kbd>\n      </div>\n      <p className=\"text-text-muted\">Yuqoridagi tugmalardan birini bosing</p>\n      {last && (\n        <Badge color=\"primary\">\n          {last} · {count} marta\n        </Badge>\n      )}\n    </div>\n  );\n}\n" },
  "hooks/idle": { component: Demo861, file: "hooks/idle.tsx", source: "'use client';\n\nimport { useIdle, useOnline } from '@akhatmirzo/hooks';\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function HooksIdle() {\n  const idle = useIdle(5000);\n  const online = useOnline();\n\n  return (\n    <div className=\"flex flex-col items-center gap-3 text-center\">\n      <div className=\"flex flex-wrap justify-center gap-2\">\n        <Badge color={idle ? 'warning' : 'success'} dot>\n          {idle ? 'Nofaol' : 'Faol'}\n        </Badge>\n        <Badge color={online ? 'success' : 'danger'} dot>\n          {online ? 'Internet bor' : \"Internet yo'q\"}\n        </Badge>\n      </div>\n      <p className=\"max-w-xs text-sm text-text-muted\">\n        5 soniya sichqoncha va klaviaturaga tegmang. Tarmoqni o'chirib ko'ring — holat darhol\n        yangilanadi.\n      </p>\n    </div>\n  );\n}\n" },
  "hooks/infinite-scroll": { component: Demo862, file: "hooks/infinite-scroll.tsx", source: "'use client';\n\nimport { useInfiniteScroll } from '@akhatmirzo/hooks';\nimport { Spinner } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst TOTAL = 60;\nconst PAGE = 12;\n\nexport default function HooksInfiniteScroll() {\n  const [items, setItems] = useState(PAGE);\n  const [loading, setLoading] = useState(false);\n  const hasMore = items < TOTAL;\n\n  const { sentinelRef } = useInfiniteScroll({\n    hasMore,\n    loading,\n    rootMargin: '40px',\n    onLoadMore: () => {\n      // Haqiqiy ilovada — keyingi sahifani serverdan yuklash\n      setLoading(true);\n      setTimeout(() => {\n        setItems((n) => Math.min(TOTAL, n + PAGE));\n        setLoading(false);\n      }, 600);\n    },\n  });\n\n  return (\n    <div className=\"h-64 w-full max-w-sm overflow-auto rounded-xl border border-border bg-surface\">\n      <ul className=\"divide-y divide-border text-sm text-text\">\n        {Array.from({ length: items }, (_, i) => (\n          <li key={i} className=\"px-4 py-2\">\n            Buyurtma #{1000 + i}\n          </li>\n        ))}\n      </ul>\n      <div\n        ref={sentinelRef}\n        className=\"flex items-center justify-center gap-2 p-3 text-sm text-text-muted\"\n      >\n        {hasMore ? (\n          <>\n            <Spinner size=\"sm\" /> Yuklanmoqda…\n          </>\n        ) : (\n          'Hammasi yuklandi'\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "hooks/intersection": { component: Demo863, file: "hooks/intersection.tsx", source: "'use client';\n\nimport { useIntersection } from '@akhatmirzo/hooks';\nimport { Spinner } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\nconst MAX = 60;\n\nexport default function HooksIntersection() {\n  const [count, setCount] = useState(12);\n  const done = count >= MAX;\n  const [sentinelRef, entry] = useIntersection<HTMLDivElement>({\n    rootMargin: '40px',\n    enabled: !done,\n  });\n  const visible = entry?.isIntersecting ?? false;\n\n  useEffect(() => {\n    if (!visible || done) return;\n    // Haqiqiy ilovada — keyingi sahifani serverdan yuklash\n    const timer = setTimeout(() => setCount((n) => Math.min(MAX, n + 12)), 500);\n    return () => clearTimeout(timer);\n  }, [visible, done, count]);\n\n  return (\n    <div className=\"h-64 w-full max-w-sm overflow-auto rounded-xl border border-border bg-surface\">\n      <ul className=\"divide-y divide-border text-sm text-text\">\n        {Array.from({ length: count }, (_, i) => (\n          <li key={i} className=\"px-4 py-2\">\n            Buyurtma #{1000 + i}\n          </li>\n        ))}\n      </ul>\n      <div\n        ref={sentinelRef}\n        className=\"flex items-center justify-center gap-2 p-3 text-sm text-text-muted\"\n      >\n        {done ? (\n          'Hammasi yuklandi'\n        ) : (\n          <>\n            <Spinner size=\"sm\" /> Yuklanmoqda…\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n" },
  "hooks/interval": { component: Demo864, file: "hooks/interval.tsx", source: "'use client';\n\nimport { useInterval } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksInterval() {\n  const [seconds, setSeconds] = useState(0);\n  const [running, setRunning] = useState(true);\n\n  // null — interval to'xtaydi\n  useInterval(() => setSeconds((s) => s + 1), running ? 1000 : null);\n\n  const mm = String(Math.floor(seconds / 60)).padStart(2, '0');\n  const ss = String(seconds % 60).padStart(2, '0');\n\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <span className=\"text-3xl font-semibold tabular-nums text-text\">\n        {mm}:{ss}\n      </span>\n      <div className=\"flex gap-2\">\n        <Button variant=\"primary\" onClick={() => setRunning((r) => !r)}>\n          {running ? \"To'xtatish\" : 'Davom ettirish'}\n        </Button>\n        <Button variant=\"ghost\" onClick={() => setSeconds(0)}>\n          Nolga qaytarish\n        </Button>\n      </div>\n    </div>\n  );\n}\n" },
  "hooks/local-storage": { component: Demo865, file: "hooks/local-storage.tsx", source: "'use client';\n\nimport { useLocalStorage } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\n\nfunction Mirror() {\n  const [count] = useLocalStorage('docs-demo:counter', 0);\n  return (\n    <p className=\"text-sm text-text-muted\">\n      Boshqa komponent ko'rayotgan qiymat: <strong className=\"text-text\">{count}</strong>\n    </p>\n  );\n}\n\nexport default function HooksLocalStorage() {\n  const [count, setCount, remove] = useLocalStorage('docs-demo:counter', 0);\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <div className=\"flex items-center gap-2\">\n        <Button variant=\"outline\" onClick={() => setCount((n) => n - 1)}>\n          −\n        </Button>\n        <span className=\"min-w-12 text-center text-2xl font-semibold text-text tabular-nums\">\n          {count}\n        </span>\n        <Button variant=\"outline\" onClick={() => setCount((n) => n + 1)}>\n          +\n        </Button>\n        <Button variant=\"ghost\" onClick={remove}>\n          O'chirish\n        </Button>\n      </div>\n      <Mirror />\n      <p className=\"text-xs text-text-faint\">\n        Sahifani boshqa tabda oching — qiymat sinxron o'zgaradi\n      </p>\n    </div>\n  );\n}\n" },
  "hooks/long-press": { component: Demo866, file: "hooks/long-press.tsx", source: "'use client';\n\nimport { useLongPress } from '@akhatmirzo/hooks';\nimport { Badge } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksLongPress() {\n  const [status, setStatus] = useState<'idle' | 'pressing' | 'done' | 'cancelled'>('idle');\n  const handlers = useLongPress<HTMLButtonElement>(() => setStatus('done'), {\n    delay: 700,\n    onStart: () => setStatus('pressing'),\n    onCancel: () => setStatus('cancelled'),\n  });\n\n  const label = {\n    idle: 'Kutilmoqda',\n    pressing: 'Bosib turibsiz…',\n    done: \"Buyurtma o'chirishga tanlandi\",\n    cancelled: 'Bekor qilindi',\n  }[status];\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <button\n        type=\"button\"\n        {...handlers}\n        className=\"w-64 touch-none select-none rounded-xl border border-border bg-surface px-4 py-3 text-left text-sm text-text transition-colors active:bg-surface-muted\"\n      >\n        <span className=\"font-medium\">Buyurtma #1024</span>\n        <span className=\"block text-text-muted\">1 250 000 so'm · 0,7 s bosib turing</span>\n      </button>\n      <Badge\n        color={status === 'done' ? 'success' : status === 'cancelled' ? 'warning' : 'neutral'}\n        dot\n      >\n        {label}\n      </Badge>\n    </div>\n  );\n}\n" },
  "hooks/media-query": { component: Demo867, file: "hooks/media-query.tsx", source: "'use client';\n\nimport { useMediaQuery } from '@akhatmirzo/hooks';\nimport { Badge } from '@akhatmirzo/ui';\n\nexport default function HooksMediaQuery() {\n  const queries = [\n    { label: '≥ 640px', on: useMediaQuery('(min-width: 640px)') },\n    { label: '≥ 1024px', on: useMediaQuery('(min-width: 1024px)') },\n    { label: \"Tizim: qorong'i mavzu\", on: useMediaQuery('(prefers-color-scheme: dark)') },\n    { label: 'Kam animatsiya', on: useMediaQuery('(prefers-reduced-motion: reduce)') },\n    { label: 'Sichqoncha (hover)', on: useMediaQuery('(hover: hover)') },\n  ];\n\n  return (\n    <div className=\"flex flex-wrap justify-center gap-2\">\n      {queries.map(({ label, on }) => (\n        <Badge key={label} color={on ? 'success' : 'neutral'} variant={on ? 'soft' : 'outline'} dot>\n          {label}\n        </Badge>\n      ))}\n    </div>\n  );\n}\n" },
  "hooks/pagination": { component: Demo868, file: "hooks/pagination.tsx", source: "'use client';\n\nimport { usePagination } from '@akhatmirzo/hooks';\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function HooksPagination() {\n  const [page, setPage] = useState(5);\n  const { pages, hasPrev, hasNext, from, to } = usePagination({ total: 200, pageSize: 10, page });\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <nav aria-label=\"Sahifalar\" className=\"flex flex-wrap items-center justify-center gap-1\">\n        <Button size=\"sm\" variant=\"ghost\" disabled={!hasPrev} onClick={() => setPage(page - 1)}>\n          Oldingi\n        </Button>\n        {pages.map((p, i) =>\n          p === 'ellipsis' ? (\n            <span key={`e${i}`} className=\"px-2 text-text-muted\">\n              …\n            </span>\n          ) : (\n            <Button\n              key={p}\n              size=\"sm\"\n              variant={p === page ? 'primary' : 'ghost'}\n              aria-current={p === page ? 'page' : undefined}\n              onClick={() => setPage(p)}\n            >\n              {p}\n            </Button>\n          ),\n        )}\n        <Button size=\"sm\" variant=\"ghost\" disabled={!hasNext} onClick={() => setPage(page + 1)}>\n          Keyingi\n        </Button>\n      </nav>\n      <p className=\"text-sm text-text-muted\">\n        {from}–{to} / 200 ta yozuv\n      </p>\n    </div>\n  );\n}\n" },
  "hooks/resize-observer": { component: Demo869, file: "hooks/resize-observer.tsx", source: "'use client';\n\nimport { useResizeObserver } from '@akhatmirzo/hooks';\nimport { Badge } from '@akhatmirzo/ui';\nimport { useRef } from 'react';\n\nexport default function HooksResizeObserver() {\n  const ref = useRef<HTMLDivElement>(null);\n  const size = useResizeObserver(ref, { box: 'border-box' });\n  const compact = size !== null && size.width < 240;\n\n  return (\n    <div\n      ref={ref}\n      className=\"flex h-40 w-72 min-w-40 max-w-full resize flex-col items-center justify-center gap-2 overflow-auto rounded-xl border border-border bg-surface p-4 text-sm text-text\"\n    >\n      <Badge color={compact ? 'warning' : 'success'} dot>\n        {compact ? 'Ixcham' : 'Keng'}\n      </Badge>\n      <span className=\"font-mono text-text-muted\">\n        {size ? `${Math.round(size.width)} × ${Math.round(size.height)}` : '…'}\n      </span>\n      <span className=\"text-xs text-text-muted\">O'ng pastki burchakdan torting</span>\n    </div>\n  );\n}\n" },
  "hooks/scroll-lock": { component: Demo870, file: "hooks/scroll-lock.tsx", source: "'use client';\n\nimport { useScrollLock, useToggle } from '@akhatmirzo/hooks';\nimport { Badge, Button } from '@akhatmirzo/ui';\n\nexport default function HooksScrollLock() {\n  const [locked, toggle] = useToggle(false);\n  useScrollLock(locked);\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <Button variant={locked ? 'primary' : 'outline'} onClick={toggle} aria-pressed={locked}>\n        {locked ? 'Scroll qulfini ochish' : \"Sahifa scroll'ini qulflash\"}\n      </Button>\n      <Badge color={locked ? 'warning' : 'neutral'} dot>\n        {locked ? \"Sahifa qulflangan — g'ildirak bilan aylantirib ko'ring\" : 'Sahifa erkin'}\n      </Badge>\n    </div>\n  );\n}\n" },
  "hooks/step": { component: Demo871, file: "hooks/step.tsx", source: "'use client';\n\nimport { useStep } from '@akhatmirzo/hooks';\nimport { Button, Progress, Stepper, toast } from '@akhatmirzo/ui';\n\nconst steps = [\n  { title: 'Savat' },\n  { title: 'Yetkazib berish', description: 'Manzil va vaqt' },\n  { title: \"To'lov\" },\n  { title: 'Tasdiqlash' },\n];\n\nexport default function HooksStep() {\n  const { step, next, prev, goTo, reset, isFirst, isLast, progress } = useStep(steps.length);\n\n  return (\n    <div className=\"flex w-full flex-col gap-6\">\n      <Stepper steps={steps} value={step} onValueChange={goTo} aria-label=\"Buyurtma\" />\n      <Progress value={progress * 100} aria-label=\"Jarayon\" />\n      <div className=\"flex gap-2\">\n        <Button size=\"sm\" disabled={isFirst} onClick={prev}>\n          Orqaga\n        </Button>\n        <Button\n          size=\"sm\"\n          variant=\"primary\"\n          onClick={() => {\n            if (!isLast) return next();\n            toast('Buyurtma qabul qilindi');\n            reset();\n          }}\n        >\n          {isLast ? 'Buyurtma berish' : 'Davom etish'}\n        </Button>\n      </div>\n    </div>\n  );\n}\n" },
  "hooks/toggle": { component: Demo872, file: "hooks/toggle.tsx", source: "'use client';\n\nimport { useToggle } from '@akhatmirzo/hooks';\nimport { Button, Switch } from '@akhatmirzo/ui';\n\nexport default function HooksToggle() {\n  const [notify, toggleNotify, setNotify] = useToggle(true);\n\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Switch\n        checked={notify}\n        onCheckedChange={setNotify}\n        label=\"SMS xabarnomalar\"\n        description={notify ? 'Yoqilgan' : \"O'chirilgan\"}\n      />\n      <div className=\"flex flex-wrap gap-2\">\n        <Button variant=\"outline\" onClick={toggleNotify}>\n          Almashtirish\n        </Button>\n        <Button variant=\"ghost\" onClick={() => setNotify(false)}>\n          O'chirish\n        </Button>\n      </div>\n    </div>\n  );\n}\n" },
  "hover-card/placement": { component: Demo873, file: "hover-card/placement.tsx", source: "'use client';\n\nimport { Button, HoverCard } from '@akhatmirzo/ui';\n\nconst sides = ['top', 'right', 'bottom', 'left'] as const;\n\nexport default function HoverCardPlacement() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {sides.map((side) => (\n        <HoverCard key={side} openDelay={200} closeDelay={100}>\n          <HoverCard.Trigger asChild>\n            <Button variant=\"outline\">{side}</Button>\n          </HoverCard.Trigger>\n          <HoverCard.Content side={side} size=\"sm\">\n            <p className=\"m-0\">\n              Panel <b>{side}</b> tomonda. Ekran chetiga yetsa, o'zi teskari tomonga o'tadi.\n            </p>\n          </HoverCard.Content>\n        </HoverCard>\n      ))}\n    </div>\n  );\n}\n" },
  "hover-card/profile": { component: Demo874, file: "hover-card/profile.tsx", source: "'use client';\n\nimport { Avatar, Badge, HoverCard } from '@akhatmirzo/ui';\nimport { CalendarDays } from 'lucide-react';\n\nexport default function HoverCardProfile() {\n  return (\n    <p className=\"m-0 text-sm\">\n      Kutubxona muallifi —{' '}\n      <HoverCard>\n        <HoverCard.Trigger asChild>\n          <a\n            href=\"https://github.com/Akhatmirzo\"\n            className=\"focus-ring rounded-sm font-medium text-primary underline-offset-4 hover:underline\"\n          >\n            @akhatmirzo\n          </a>\n        </HoverCard.Trigger>\n        <HoverCard.Content align=\"start\">\n          <div className=\"flex gap-3\">\n            <Avatar name=\"Akhatmirzo Umarov\" />\n            <div className=\"flex min-w-0 flex-col gap-1\">\n              <span className=\"font-semibold\">Akhatmirzo Umarov</span>\n              <span className=\"text-text-muted\">\n                Frontend dasturchi. React, TypeScript va o'zbekcha UI.\n              </span>\n              <span className=\"mt-1 flex items-center gap-2 text-xs text-text-muted\">\n                <CalendarDays className=\"size-3.5\" aria-hidden=\"true\" />\n                2021-yildan beri\n                <Badge size=\"sm\" color=\"success\">\n                  Ochiq\n                </Badge>\n              </span>\n            </div>\n          </div>\n        </HoverCard.Content>\n      </HoverCard>\n      .\n    </p>\n  );\n}\n" },
  "hover-card/sizes": { component: Demo875, file: "hover-card/sizes.tsx", source: "'use client';\n\nimport { HoverCard } from '@akhatmirzo/ui';\n\nexport default function HoverCardSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6 text-sm\">\n      {(['sm', 'md'] as const).map((size) => (\n        <HoverCard key={size}>\n          <HoverCard.Trigger asChild>\n            <a\n              href=\"#chorsu\"\n              className=\"focus-ring rounded-sm font-medium text-primary underline underline-offset-4\"\n            >\n              size=&quot;{size}&quot;\n            </a>\n          </HoverCard.Trigger>\n          <HoverCard.Content size={size}>\n            <p className=\"m-0 font-semibold\">Chorsu Market</p>\n            <p className=\"m-0 mt-1 text-text-muted\">\n              Toshkentdagi onlayn do'kon: 12 000+ mahsulot, 1 kunda yetkazib berish.\n            </p>\n          </HoverCard.Content>\n        </HoverCard>\n      ))}\n    </div>\n  );\n}\n" },
  "icon-button/as-child": { component: Demo876, file: "icon-button/as-child.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Settings } from 'lucide-react';\n\nexport default function IconButtonAsChild() {\n  return (\n    <IconButton asChild variant=\"outline\" aria-label=\"Sozlamalar\">\n      <a href=\"#props\">\n        <Settings />\n      </a>\n    </IconButton>\n  );\n}\n" },
  "icon-button/sizes": { component: Demo877, file: "icon-button/sizes.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { X } from 'lucide-react';\n\nexport default function IconButtonSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton variant=\"outline\" size=\"sm\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n      <IconButton variant=\"outline\" size=\"md\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n      <IconButton variant=\"outline\" size=\"lg\" aria-label=\"Yopish\">\n        <X />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "icon-button/states": { component: Demo878, file: "icon-button/states.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Download, Trash2 } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function IconButtonStates() {\n  const [loading, setLoading] = useState(false);\n\n  const download = () => {\n    setLoading(true);\n    setTimeout(() => setLoading(false), 1500);\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton\n        variant=\"primary\"\n        loading={loading}\n        onClick={download}\n        aria-label=\"Hisobotni yuklab olish\"\n        labels={{ loading: 'Yuklab olinmoqda' }}\n      >\n        <Download />\n      </IconButton>\n      <IconButton variant=\"danger\" disabled aria-label=\"O'chirish\">\n        <Trash2 />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "icon-button/toolbar": { component: Demo879, file: "icon-button/toolbar.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Bold, Italic, Plus, Underline } from 'lucide-react';\n\nexport default function IconButtonToolbar() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <div\n        role=\"toolbar\"\n        aria-label=\"Matn formati\"\n        className=\"flex items-center gap-1 rounded-lg border border-border bg-surface p-1\"\n      >\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Qalin\">\n          <Bold />\n        </IconButton>\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Kursiv\">\n          <Italic />\n        </IconButton>\n        <IconButton variant=\"ghost\" size=\"sm\" aria-label=\"Tagiga chizilgan\">\n          <Underline />\n        </IconButton>\n      </div>\n      <IconButton variant=\"primary\" size=\"lg\" className=\"rounded-full\" aria-label=\"Yangi buyurtma\">\n        <Plus />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "icon-button/variants": { component: Demo880, file: "icon-button/variants.tsx", source: "'use client';\n\nimport { IconButton } from '@akhatmirzo/ui';\nimport { Heart, Pencil, Plus, Share2, Trash2 } from 'lucide-react';\n\nexport default function IconButtonVariants() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <IconButton variant=\"primary\" aria-label=\"Qo'shish\">\n        <Plus />\n      </IconButton>\n      <IconButton aria-label=\"Sevimlilarga qo'shish\">\n        <Heart />\n      </IconButton>\n      <IconButton variant=\"outline\" aria-label=\"Tahrirlash\">\n        <Pencil />\n      </IconButton>\n      <IconButton variant=\"ghost\" aria-label=\"Ulashish\">\n        <Share2 />\n      </IconButton>\n      <IconButton variant=\"danger\" aria-label=\"O'chirish\">\n        <Trash2 />\n      </IconButton>\n    </div>\n  );\n}\n" },
  "input/addons": { component: Demo881, file: "input/addons.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Mail } from 'lucide-react';\n\nexport default function InputAddons() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" aria-label=\"Telefon\" />\n      <Input suffix=\"so'm\" placeholder=\"1 250 000\" inputMode=\"numeric\" aria-label=\"Narx\" />\n      <Input rightIcon={<Mail />} type=\"email\" placeholder=\"email@misol.uz\" aria-label=\"Email\" />\n      <Input prefix=\"https://\" suffix=\".uz\" placeholder=\"dokon\" aria-label=\"Sayt manzili\" />\n    </div>\n  );\n}\n" },
  "input/basic": { component: Demo882, file: "input/basic.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Search } from 'lucide-react';\n\nexport default function InputBasic() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Input leftIcon={<Search />} placeholder=\"Mahsulot qidirish\" aria-label=\"Mahsulot qidirish\" />\n    </div>\n  );\n}\n" },
  "input/clearable": { component: Demo883, file: "input/clearable.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\nimport { Search } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function InputClearable() {\n  const [query, setQuery] = useState('Samarqand');\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-2\">\n      <Input\n        leftIcon={<Search />}\n        clearable\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Shahar qidirish\"\n        aria-label=\"Shahar qidirish\"\n      />\n      <p className=\"text-xs text-text-muted\">Qiymat: {query || '—'}</p>\n    </div>\n  );\n}\n" },
  "input/password": { component: Demo884, file: "input/password.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\n\nexport default function InputPassword() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field label=\"Parol\" description=\"Kamida 8 ta belgi\">\n        <Input type=\"password\" defaultValue=\"maxfiy123\" autoComplete=\"current-password\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "input/sizes": { component: Demo885, file: "input/sizes.tsx", source: "'use client';\n\nimport { Button, Input } from '@akhatmirzo/ui';\n\nexport default function InputSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"sm\" placeholder=\"Kichik · 32\" aria-label=\"Kichik\" />\n        <Button size=\"sm\">Qo'llash</Button>\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"md\" placeholder=\"O'rta · 40\" aria-label=\"O'rta\" />\n        <Button size=\"md\">Qo'llash</Button>\n      </div>\n      <div className=\"flex items-center gap-2\">\n        <Input size=\"lg\" placeholder=\"Katta · 48\" aria-label=\"Katta\" />\n        <Button size=\"lg\">Qo'llash</Button>\n      </div>\n    </div>\n  );\n}\n" },
  "input/states": { component: Demo886, file: "input/states.tsx", source: "'use client';\n\nimport { Input } from '@akhatmirzo/ui';\n\nexport default function InputStates() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-3 sm:grid-cols-2\">\n      <Input placeholder=\"Oddiy\" aria-label=\"Oddiy\" />\n      <Input invalid defaultValue=\"sarvar@mail\" aria-label=\"Xato\" />\n      <Input disabled defaultValue=\"O'chirilgan\" aria-label=\"O'chirilgan\" />\n      <Input readOnly defaultValue=\"Faqat o'qish uchun\" aria-label=\"Faqat o'qish\" />\n    </div>\n  );\n}\n" },
  "input/with-field": { component: Demo887, file: "input/with-field.tsx", source: "'use client';\n\nimport { Field, Input } from '@akhatmirzo/ui';\nimport { Mail } from 'lucide-react';\n\nexport default function InputWithField() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Field label=\"Telefon\" required description=\"Tasdiqlash kodi SMS orqali keladi\">\n        <Input prefix=\"+998\" placeholder=\"90 123 45 67\" inputMode=\"tel\" />\n      </Field>\n      <Field label=\"Email\" error=\"Email manzil noto'g'ri\">\n        <Input leftIcon={<Mail />} defaultValue=\"sarvar@mail\" clearable />\n      </Field>\n    </div>\n  );\n}\n" },
  "kbd/basic": { component: Demo888, file: "kbd/basic.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdBasic() {\n  return (\n    <p className=\"text-sm text-text\">\n      Qidiruvni ochish uchun <Kbd keys={['mod', 'K']} /> ni bosing, yopish uchun <Kbd>Esc</Kbd>.\n    </p>\n  );\n}\n" },
  "kbd/keys": { component: Demo889, file: "kbd/keys.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdKeys() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Kbd keys={['mod', 'K']} />\n      <Kbd keys={['mod', 'Shift', 'P']} />\n      <Kbd keys={['Alt', 'F4']} />\n      <Kbd>Esc</Kbd>\n      <Kbd>↵</Kbd>\n      <Kbd>↑</Kbd>\n      <Kbd>↓</Kbd>\n    </div>\n  );\n}\n" },
  "kbd/menu": { component: Demo890, file: "kbd/menu.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nconst items = [\n  { label: 'Nusxa olish', keys: ['mod', 'C'] },\n  { label: \"Qo'yish\", keys: ['mod', 'V'] },\n  { label: 'Hammasini tanlash', keys: ['mod', 'A'] },\n];\n\nexport default function KbdMenu() {\n  return (\n    <ul className=\"flex w-64 flex-col rounded-lg border border-border bg-surface p-1 text-sm text-text\">\n      {items.map((item) => (\n        <li key={item.label} className=\"flex items-center justify-between rounded-md px-2 py-1.5\">\n          {item.label}\n          <Kbd keys={item.keys} />\n        </li>\n      ))}\n    </ul>\n  );\n}\n" },
  "kbd/sizes": { component: Demo891, file: "kbd/sizes.tsx", source: "'use client';\n\nimport { Kbd } from '@akhatmirzo/ui';\n\nexport default function KbdSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Kbd keys={['mod', 'C']} />\n      <Kbd size=\"md\" keys={['mod', 'C']} />\n    </div>\n  );\n}\n" },
  "masked-input/card": { component: Demo892, file: "masked-input/card.tsx", source: "'use client';\n\nimport { CardInput, Field, getCardDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function CardInputDemo() {\n  const [card, setCard] = useState('');\n  const { complete, valid, brand } = getCardDetails(card);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field\n        label=\"Karta raqami\"\n        error={complete && !valid ? \"Karta raqami noto'g'ri\" : undefined}\n        description={\n          valid ? `Karta to'g'ri · ${brand ?? 'boshqa'}` : \"Sinab ko'ring: 4111 1111 1111 1111\"\n        }\n      >\n        <CardInput value={card} onValueChange={setCard} />\n      </Field>\n      <div className=\"flex flex-col gap-3\">\n        <CardInput aria-label=\"Uzcard\" defaultValue=\"8600123412341234\" />\n        <CardInput aria-label=\"Humo\" defaultValue=\"9860010203040506\" />\n        <CardInput aria-label=\"Luhn xato\" defaultValue=\"4111111111111112\" />\n      </div>\n    </div>\n  );\n}\n" },
  "masked-input/custom-mask": { component: Demo893, file: "masked-input/custom-mask.tsx", source: "'use client';\n\nimport { Field, MaskedInput } from '@akhatmirzo/ui';\n\nexport default function MaskedInputCustom() {\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Avtomobil raqami\" description='mask=\"99 A 999 AA\"'>\n        <MaskedInput mask=\"99 A 999 AA\" uppercase placeholder=\"01 A 123 BC\" />\n      </Field>\n      <Field label=\"JShShIR\" description=\"14 ta raqam\">\n        <MaskedInput mask=\"99999999999999\" inputMode=\"numeric\" placeholder=\"14 raqam\" />\n      </Field>\n      <Field label=\"Vaqt\" description='mask=\"99:99\"'>\n        <MaskedInput mask=\"99:99\" inputMode=\"numeric\" placeholder=\"09:30\" />\n      </Field>\n      <Field label=\"Promo-kod\" description='mask=\"****-****\"'>\n        <MaskedInput mask=\"****-****\" uppercase placeholder=\"XXXX-XXXX\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "masked-input/money-words": { component: Demo894, file: "masked-input/money-words.tsx", source: "'use client';\n\nimport { Field, MoneyInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MoneyWords() {\n  const [amount, setAmount] = useState<number | null>(1250000);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Shartnoma summasi\">\n        <MoneyInput value={amount} onValueChange={setAmount} showWords />\n      </Field>\n      <Field label=\"Кирилл, расмий\">\n        <MoneyInput\n          value={amount}\n          onValueChange={setAmount}\n          showWords={{ script: 'cyrillic', formal: true }}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "masked-input/money": { component: Demo895, file: "masked-input/money.tsx", source: "'use client';\n\nimport { Field, MoneyInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MoneyInputDemo() {\n  const [price, setPrice] = useState<number | null>(null);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Narx\" description={`Qiymat: ${price ?? 'null'}`}>\n        <MoneyInput value={price} onValueChange={setPrice} clearable />\n      </Field>\n      <Field label=\"Kurs\" description='decimals={2}, currency=\"$\"'>\n        <MoneyInput decimals={2} currency=\"$\" defaultValue={12.5} />\n      </Field>\n      <Field label=\"Oylik to'lov\" description=\"100 000 dan 50 000 000 gacha\">\n        <MoneyInput min={100000} max={50000000} />\n      </Field>\n      <Field label=\"Valyutasiz\" description=\"currency={null}\">\n        <MoneyInput currency={null} defaultValue={980000} />\n      </Field>\n    </div>\n  );\n}\n" },
  "masked-input/overview": { component: Demo896, file: "masked-input/overview.tsx", source: "'use client';\n\nimport { CardInput, Field, MaskedInput, MoneyInput, PhoneInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function MaskedInputOverview() {\n  const [phone, setPhone] = useState('');\n  const [sum, setSum] = useState<number | null>(1250000);\n  const [card, setCard] = useState('');\n  const [passport, setPassport] = useState('');\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field label=\"Telefon\" description={`Qiymat: \"${phone}\"`}>\n        <PhoneInput value={phone} onValueChange={setPhone} />\n      </Field>\n      <Field label=\"Summa\" description={`Qiymat: ${sum ?? 'null'}`}>\n        <MoneyInput value={sum} onValueChange={setSum} />\n      </Field>\n      <Field label=\"Karta raqami\" description={`Qiymat: \"${card}\"`}>\n        <CardInput value={card} onValueChange={setCard} />\n      </Field>\n      <Field label=\"Pasport\" description={`Qiymat: \"${passport}\"`}>\n        <MaskedInput\n          mask=\"AA 9999999\"\n          uppercase\n          placeholder=\"AB 1234567\"\n          value={passport}\n          onValueChange={setPassport}\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "masked-input/phone": { component: Demo897, file: "masked-input/phone.tsx", source: "'use client';\n\nimport { Field, PhoneInput, type PhoneInputDetails } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PhoneInputDemo() {\n  const [phone, setPhone] = useState('');\n  const [details, setDetails] = useState<PhoneInputDetails | null>(null);\n\n  const badOperator = phone.length >= 2 && !details?.operator;\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Field\n        label=\"Telefon raqami\"\n        required\n        error={badOperator ? `\"${phone.slice(0, 2)}\" — bunday operator kodi yo'q` : undefined}\n        description={\n          details?.valid ? `Operator: ${details.operator}` : '+998 90 123 45 67 ni joylang'\n        }\n      >\n        <PhoneInput\n          value={phone}\n          onValueChange={(value, info) => {\n            setPhone(value);\n            setDetails(info);\n          }}\n        />\n      </Field>\n      <PhoneInput aria-label=\"Kichik\" size=\"sm\" defaultValue=\"991234567\" />\n      <PhoneInput aria-label=\"Faqat o'qish\" readOnly defaultValue=\"935554433\" />\n    </div>\n  );\n}\n" },
  "otp-input/length": { component: Demo898, file: "otp-input/length.tsx", source: "'use client';\n\nimport { OtpInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function OtpInputLength() {\n  const [promo, setPromo] = useState('');\n\n  return (\n    <div className=\"flex flex-col items-start gap-5\">\n      <OtpInput length={4} aria-label=\"4 xonali PIN\" />\n      <OtpInput length={6} groupSize={2} aria-label=\"Juft guruhli kod\" />\n      <div className=\"flex flex-col gap-2\">\n        <OtpInput\n          type=\"alphanumeric\"\n          groupSize={3}\n          aria-label=\"Harfli kod\"\n          value={promo}\n          onValueChange={setPromo}\n        />\n        <span className=\"text-sm text-text-muted\">Qiymat: {promo || '—'}</span>\n      </div>\n    </div>\n  );\n}\n" },
  "otp-input/resend": { component: Demo899, file: "otp-input/resend.tsx", source: "'use client';\n\nimport { OtpInput, toast } from '@akhatmirzo/ui';\n\nconst sendSms = () =>\n  new Promise<void>((resolve) => {\n    setTimeout(() => {\n      toast('SMS qayta yuborildi');\n      resolve();\n    }, 800);\n  });\n\nexport default function OtpResendTimer() {\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <OtpInput.ResendTimer seconds={5} onResend={() => toast('Kod qayta yuborildi')} />\n      <OtpInput.ResendTimer\n        seconds={3}\n        labels={{ resend: 'SMS ni qayta olish' }}\n        onResend={sendSms}\n      />\n    </div>\n  );\n}\n" },
  "otp-input/states": { component: Demo900, file: "otp-input/states.tsx", source: "'use client';\n\nimport { OtpInput } from '@akhatmirzo/ui';\n\nexport default function OtpInputStates() {\n  return (\n    <div className=\"flex flex-col items-start gap-5\">\n      <OtpInput invalid defaultValue=\"482913\" groupSize={3} aria-label=\"Xato kod\" />\n      <OtpInput disabled defaultValue=\"12\" groupSize={3} aria-label=\"O'chirilgan\" />\n    </div>\n  );\n}\n" },
  "otp-input/verify": { component: Demo901, file: "otp-input/verify.tsx", source: "'use client';\n\nimport { Field, OtpInput, toast } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst CORRECT = '123456';\n\nexport default function OtpInputVerify() {\n  const [code, setCode] = useState('');\n  const [status, setStatus] = useState<'idle' | 'error' | 'ok'>('idle');\n\n  return (\n    <div className=\"flex flex-col gap-2\">\n      <Field\n        label=\"Tasdiqlash kodi\"\n        description={\n          status === 'ok' ? 'Kod tasdiqlandi' : `+998 90 *** ** 67 ga yuborildi. Kod: ${CORRECT}`\n        }\n        error={status === 'error' ? \"Kod noto'g'ri. Qayta urinib ko'ring.\" : undefined}\n      >\n        <OtpInput\n          groupSize={3}\n          value={code}\n          disabled={status === 'ok'}\n          onValueChange={(value) => {\n            setCode(value);\n            if (status === 'error') setStatus('idle');\n          }}\n          onComplete={(value) => setStatus(value === CORRECT ? 'ok' : 'error')}\n        />\n      </Field>\n      <OtpInput.ResendTimer\n        onResend={() => {\n          setCode('');\n          setStatus('idle');\n          toast('Yangi kod yuborildi');\n        }}\n      />\n    </div>\n  );\n}\n" },
  "pagination/basic": { component: Demo902, file: "pagination/basic.tsx", source: "'use client';\n\nimport { Pagination, PaginationInfo } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PaginationBasic() {\n  const [page, setPage] = useState(3);\n\n  return (\n    <div className=\"flex flex-col items-center gap-3\">\n      <Pagination page={page} onPageChange={setPage} total={230} pageSize={10} />\n      <PaginationInfo page={page} pageSize={10} total={230} />\n    </div>\n  );\n}\n" },
  "pagination/compact": { component: Demo903, file: "pagination/compact.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\n\nexport default function PaginationCompact() {\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Pagination defaultPage={3} pageCount={24} compact />\n      <Pagination defaultPage={3} pageCount={24} compact size=\"sm\" showFirstLast />\n    </div>\n  );\n}\n" },
  "pagination/data-table": { component: Demo904, file: "pagination/data-table.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { DataTable, Pagination, PaginationInfo, type DataTableColumn } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\ninterface Order {\n  id: number;\n  customer: string;\n  total: number;\n}\n\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\nconst ORDERS: Order[] = Array.from({ length: 47 }, (_, i) => ({\n  id: 3001 + i,\n  customer: NAMES[i % NAMES.length]!,\n  total: 120_000 + ((i * 314_159) % 2_500_000),\n}));\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 88 },\n  { key: 'customer', header: 'Mijoz' },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nconst PAGE_SIZE = 5;\n\nexport default function PaginationDataTable() {\n  const [page, setPage] = useState(1);\n  const rows = ORDERS.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);\n\n  return (\n    <div className=\"flex w-full flex-col gap-3\">\n      <DataTable label=\"Buyurtmalar\" data={rows} columns={columns} className=\"w-full\" />\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <PaginationInfo page={page} pageSize={PAGE_SIZE} total={ORDERS.length} />\n        <Pagination\n          page={page}\n          onPageChange={setPage}\n          total={ORDERS.length}\n          pageSize={PAGE_SIZE}\n          size=\"sm\"\n        />\n      </div>\n    </div>\n  );\n}\n" },
  "pagination/first-last": { component: Demo905, file: "pagination/first-last.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\n\nexport default function PaginationFirstLast() {\n  return <Pagination defaultPage={10} pageCount={40} siblings={2} showFirstLast compact={false} />;\n}\n" },
  "pagination/links": { component: Demo906, file: "pagination/links.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function PaginationLinks() {\n  // Haqiqiy loyihada sahifa URL'dan o'qiladi: ?page=3\n  const [page, setPage] = useState(1);\n\n  return (\n    <Pagination page={page} onPageChange={setPage} pageCount={8} getHref={(p) => `#sahifa-${p}`} />\n  );\n}\n" },
  "pagination/sizes": { component: Demo907, file: "pagination/sizes.tsx", source: "'use client';\n\nimport { Pagination } from '@akhatmirzo/ui';\n\nexport default function PaginationSizes() {\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Pagination defaultPage={4} pageCount={12} size=\"sm\" compact={false} />\n      <Pagination defaultPage={4} pageCount={12} compact={false} />\n    </div>\n  );\n}\n" },
  "popover/color-picker": { component: Demo908, file: "popover/color-picker.tsx", source: "'use client';\n\nimport { Button, Popover } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst colors = [\n  { name: 'Asosiy', className: 'bg-primary' },\n  { name: 'Yashil', className: 'bg-success' },\n  { name: 'Sariq', className: 'bg-warning' },\n  { name: 'Qizil', className: 'bg-danger' },\n  { name: \"Ko'k\", className: 'bg-info' },\n];\n\nexport default function PopoverColorPicker() {\n  const [color, setColor] = useState(colors[0]!);\n\n  return (\n    <Popover>\n      <Popover.Trigger asChild>\n        <Button\n          variant=\"outline\"\n          leftIcon={<span className={`size-3 rounded-full ${color.className}`} />}\n        >\n          Teg rangi\n        </Button>\n      </Popover.Trigger>\n      <Popover.Content className=\"w-auto\" aria-label=\"Rang tanlash\">\n        <div className=\"flex gap-2\">\n          {colors.map((c) => (\n            <Popover.Close key={c.name} asChild>\n              <button\n                type=\"button\"\n                aria-label={c.name}\n                aria-pressed={c.name === color.name}\n                onClick={() => setColor(c)}\n                className={`focus-ring size-7 cursor-pointer rounded-full border-2 border-surface-raised ${c.className} aria-pressed:ring-2 aria-pressed:ring-primary`}\n              />\n            </Popover.Close>\n          ))}\n        </div>\n      </Popover.Content>\n    </Popover>\n  );\n}\n" },
  "popover/filter": { component: Demo909, file: "popover/filter.tsx", source: "'use client';\n\nimport { Button, Input, Popover } from '@akhatmirzo/ui';\nimport { Funnel } from 'lucide-react';\nimport { useState } from 'react';\n\nexport default function PopoverFilter() {\n  const [open, setOpen] = useState(false);\n  const [range, setRange] = useState({ from: '', to: '' });\n  const [applied, setApplied] = useState<string | null>(null);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Popover open={open} onOpenChange={setOpen}>\n        <Popover.Trigger asChild>\n          <Button leftIcon={<Funnel />}>Narx</Button>\n        </Popover.Trigger>\n        <Popover.Content align=\"start\" aria-label=\"Narx filtri\">\n          <form\n            className=\"flex flex-col gap-3\"\n            onSubmit={(e) => {\n              e.preventDefault();\n              setApplied(`${range.from || '0'} – ${range.to || '∞'} so'm`);\n              setOpen(false);\n            }}\n          >\n            <p className=\"m-0 font-semibold\">Narx oralig'i</p>\n            <Input\n              size=\"sm\"\n              inputMode=\"numeric\"\n              placeholder=\"dan\"\n              suffix=\"so'm\"\n              aria-label=\"Narx: dan\"\n              value={range.from}\n              onChange={(e) => setRange((r) => ({ ...r, from: e.target.value }))}\n            />\n            <Input\n              size=\"sm\"\n              inputMode=\"numeric\"\n              placeholder=\"gacha\"\n              suffix=\"so'm\"\n              aria-label=\"Narx: gacha\"\n              value={range.to}\n              onChange={(e) => setRange((r) => ({ ...r, to: e.target.value }))}\n            />\n            <div className=\"mt-1 flex justify-end gap-2\">\n              <Popover.Close asChild>\n                <Button size=\"sm\">Bekor</Button>\n              </Popover.Close>\n              <Button size=\"sm\" variant=\"primary\" type=\"submit\">\n                Qo'llash\n              </Button>\n            </div>\n          </form>\n        </Popover.Content>\n      </Popover>\n      <span className=\"text-sm text-text-muted\">{applied ?? \"Filtr qo'llanmagan\"}</span>\n    </div>\n  );\n}\n" },
  "popover/placement": { component: Demo910, file: "popover/placement.tsx", source: "'use client';\n\nimport { Button, Popover } from '@akhatmirzo/ui';\n\nexport default function PopoverPlacement() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {(['top', 'right', 'bottom', 'left'] as const).map((side) => (\n        <Popover key={side}>\n          <Popover.Trigger asChild>\n            <Button variant=\"outline\">{side}</Button>\n          </Popover.Trigger>\n          <Popover.Content side={side} arrow className=\"w-56\" aria-label={`Tomon: ${side}`}>\n            <p className=\"m-0 text-text-muted\">\n              Panel <b className=\"text-text\">{side}</b> tomonda, triggerdan 6px uzoqlikda.\n            </p>\n          </Popover.Content>\n        </Popover>\n      ))}\n      <Popover>\n        <Popover.Trigger asChild>\n          <Button variant=\"outline\">align=end</Button>\n        </Popover.Trigger>\n        <Popover.Content align=\"end\" className=\"w-56\" aria-label=\"O'ngga tekislangan\">\n          <p className=\"m-0 text-text-muted\">Panel triggerning o'ng chetiga tekislangan.</p>\n        </Popover.Content>\n      </Popover>\n    </div>\n  );\n}\n" },
  "popover/settings": { component: Demo911, file: "popover/settings.tsx", source: "'use client';\n\nimport { Field, IconButton, Popover, Switch } from '@akhatmirzo/ui';\nimport { Bell } from 'lucide-react';\n\nexport default function PopoverSettings() {\n  return (\n    <Popover>\n      <Popover.Trigger asChild>\n        <IconButton variant=\"outline\" aria-label=\"Bildirishnoma sozlamalari\">\n          <Bell />\n        </IconButton>\n      </Popover.Trigger>\n      <Popover.Content side=\"right\" align=\"start\" arrow aria-label=\"Bildirishnomalar\">\n        <div className=\"flex flex-col gap-3\">\n          <p className=\"m-0 font-semibold\">Bildirishnomalar</p>\n          <Field label=\"Email orqali\" orientation=\"horizontal\">\n            <Switch defaultChecked />\n          </Field>\n          <Field label=\"SMS orqali\" orientation=\"horizontal\">\n            <Switch />\n          </Field>\n          <Field label=\"Telegram bot\" orientation=\"horizontal\">\n            <Switch defaultChecked />\n          </Field>\n        </div>\n      </Popover.Content>\n    </Popover>\n  );\n}\n" },
  "progress/basic": { component: Demo912, file: "progress/basic.tsx", source: "'use client';\n\nimport { Progress } from '@akhatmirzo/ui';\n\nexport default function ProgressBasic() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-6\">\n      <Progress value={64} label=\"Yuklanmoqda\" showValue />\n      <Progress\n        value={3}\n        max={5}\n        label=\"Profil to'ldirildi\"\n        showValue\n        formatValue={(value, max) => `${value} / ${max}`}\n      />\n    </div>\n  );\n}\n" },
  "progress/circle": { component: Demo913, file: "progress/circle.tsx", source: "'use client';\n\nimport { ProgressCircle } from '@akhatmirzo/ui';\n\nexport default function ProgressCircleDemo() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <ProgressCircle value={30} size=\"sm\" label=\"Sinxronlash\" />\n      <ProgressCircle value={58} showValue label=\"Saqlash\" />\n      <ProgressCircle value={72} size=\"lg\" showValue label=\"Kurs\" color=\"success\" />\n      <ProgressCircle value={100} size=\"lg\" showValue label=\"Tayyor\" color=\"success\" />\n    </div>\n  );\n}\n" },
  "progress/colors-sizes": { component: Demo914, file: "progress/colors-sizes.tsx", source: "'use client';\n\nimport { Progress } from '@akhatmirzo/ui';\n\nexport default function ProgressColorsSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-5\">\n      <Progress value={40} size=\"sm\" aria-label=\"Kichik chiziq\" />\n      <Progress value={55} color=\"success\" aria-label=\"O'rta chiziq\" />\n      <Progress value={80} size=\"lg\" color=\"warning\" aria-label=\"Katta chiziq\" />\n      <Progress value={95} color=\"danger\" label=\"Disk to'lib bormoqda\" showValue />\n    </div>\n  );\n}\n" },
  "progress/indeterminate": { component: Demo915, file: "progress/indeterminate.tsx", source: "'use client';\n\nimport { Progress, ProgressCircle } from '@akhatmirzo/ui';\n\nexport default function ProgressIndeterminate() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-6\">\n      <Progress value={null} label=\"Fayl tayyorlanmoqda\" />\n      <ProgressCircle value={null} label=\"Yuklanmoqda\" />\n    </div>\n  );\n}\n" },
  "progress/upload": { component: Demo916, file: "progress/upload.tsx", source: "'use client';\n\nimport { Button, Progress } from '@akhatmirzo/ui';\nimport { useEffect, useState } from 'react';\n\nexport default function ProgressUpload() {\n  const [value, setValue] = useState(0);\n  const [running, setRunning] = useState(false);\n\n  useEffect(() => {\n    if (!running) return;\n    const id = setInterval(() => setValue((v) => Math.min(v + 8, 100)), 300);\n    return () => clearInterval(id);\n  }, [running]);\n\n  const done = value === 100;\n  if (done && running) setRunning(false);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <Progress value={value} label=\"hisobot.pdf\" showValue color={done ? 'success' : 'primary'} />\n      <Button\n        size=\"sm\"\n        className=\"self-start\"\n        disabled={running}\n        onClick={() => {\n          setValue(0);\n          setRunning(true);\n        }}\n      >\n        {done ? 'Qayta yuklash' : 'Yuklashni boshlash'}\n      </Button>\n    </div>\n  );\n}\n" },
  "radio-group/basic": { component: Demo917, file: "radio-group/basic.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupBasic() {\n  return (\n    <RadioGroup aria-label=\"To'lov usuli\" defaultValue=\"click\">\n      <Radio value=\"click\" label=\"Click\" />\n      <Radio value=\"payme\" label=\"Payme\" />\n      <Radio value=\"cash\" label=\"Naqd pul\" />\n    </RadioGroup>\n  );\n}\n" },
  "radio-group/card": { component: Demo918, file: "radio-group/card.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RadioGroupCard() {\n  const [plan, setPlan] = useState('pro');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <RadioGroup aria-label=\"Tarif\" variant=\"card\" value={plan} onValueChange={setPlan}>\n        <Radio value=\"free\" label=\"Bepul\" description=\"1 ta do'kon, asosiy imkoniyatlar\" />\n        <Radio\n          value=\"pro\"\n          label=\"Pro · 149 000 so'm\"\n          description=\"Cheksiz do'konlar va hisobotlar\"\n        />\n        <Radio value=\"team\" label=\"Jamoa\" description=\"Tez orada\" disabled />\n      </RadioGroup>\n      <p className=\"text-sm text-text-muted\">Tanlangan tarif: {plan}</p>\n    </div>\n  );\n}\n" },
  "radio-group/horizontal": { component: Demo919, file: "radio-group/horizontal.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupHorizontal() {\n  return (\n    <RadioGroup aria-label=\"Yetkazib berish\" orientation=\"horizontal\" defaultValue=\"express\">\n      <Radio value=\"express\" label=\"Tezkor\" />\n      <Radio value=\"standard\" label=\"Oddiy\" />\n      <Radio value=\"pickup\" label=\"Olib ketish\" />\n    </RadioGroup>\n  );\n}\n" },
  "radio-group/sizes": { component: Demo920, file: "radio-group/sizes.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-10\">\n      <RadioGroup aria-label=\"Interfeys tili (kichik)\" size=\"sm\" defaultValue=\"uz\">\n        <Radio value=\"uz\" label=\"O'zbekcha\" />\n        <Radio value=\"ru\" label=\"Ruscha\" description=\"Kirill yozuvida\" />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Interfeys tili (o'rta)\" defaultValue=\"uz\">\n        <Radio value=\"uz\" label=\"O'zbekcha\" />\n        <Radio value=\"ru\" label=\"Ruscha\" description=\"Kirill yozuvida\" />\n      </RadioGroup>\n    </div>\n  );\n}\n" },
  "radio-group/states": { component: Demo921, file: "radio-group/states.tsx", source: "'use client';\n\nimport { Radio, RadioGroup } from '@akhatmirzo/ui';\n\nexport default function RadioGroupStates() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-10\">\n      <RadioGroup aria-label=\"Butun guruh o'chirilgan\" disabled defaultValue=\"a\">\n        <Radio value=\"a\" label=\"Tanlangan\" />\n        <Radio value=\"b\" label=\"Tanlanmagan\" />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Bitta variant o'chirilgan\">\n        <Radio value=\"a\" label=\"Omborda bor\" />\n        <Radio value=\"b\" label=\"Tugagan\" disabled />\n      </RadioGroup>\n      <RadioGroup aria-label=\"Xato holati\" invalid>\n        <Radio value=\"yes\" label=\"Ha\" />\n        <Radio value=\"no\" label=\"Yo'q\" />\n      </RadioGroup>\n    </div>\n  );\n}\n" },
  "radio-group/with-field": { component: Demo922, file: "radio-group/with-field.tsx", source: "'use client';\n\nimport { Field, Radio, RadioGroup } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RadioGroupWithField() {\n  const [value, setValue] = useState<string>();\n\n  return (\n    <Field label=\"Yetkazib berish\" required error={value ? undefined : 'Usulni tanlang'}>\n      <RadioGroup value={value} onValueChange={setValue}>\n        <Radio value=\"courier\" label=\"Kuryer\" description=\"Ertaga, 25 000 so'm\" />\n        <Radio value=\"pickup\" label=\"Olib ketish\" description=\"Bugun, bepul\" />\n      </RadioGroup>\n    </Field>\n  );\n}\n" },
  "rating/basic": { component: Demo923, file: "rating/basic.tsx", source: "'use client';\n\nimport { Rating } from '@akhatmirzo/ui';\n\nexport default function RatingBasic() {\n  return <Rating defaultValue={4} />;\n}\n" },
  "rating/custom": { component: Demo924, file: "rating/custom.tsx", source: "'use client';\n\nimport { Rating } from '@akhatmirzo/ui';\nimport { Heart } from 'lucide-react';\n\nexport default function RatingCustom() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <Rating\n        defaultValue={3}\n        color=\"danger\"\n        icon={<Heart fill=\"currentColor\" strokeWidth={0} />}\n      />\n      <Rating defaultValue={2} color=\"primary\" size=\"sm\" />\n      <Rating defaultValue={7} max={10} />\n      <Rating defaultValue={3} disabled />\n    </div>\n  );\n}\n" },
  "rating/half": { component: Demo925, file: "rating/half.tsx", source: "'use client';\n\nimport { Rating } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RatingHalf() {\n  const [value, setValue] = useState(3.5);\n\n  return (\n    <div className=\"flex items-center gap-3\">\n      <Rating value={value} onValueChange={setValue} allowHalf size=\"lg\" />\n      <span className=\"text-sm text-text-muted tabular-nums\">{value} / 5</span>\n    </div>\n  );\n}\n" },
  "rating/read-only": { component: Demo926, file: "rating/read-only.tsx", source: "'use client';\n\nimport { Rating } from '@akhatmirzo/ui';\n\nconst reviews = [\n  { name: 'Dilnoza', rating: 5, text: \"Yetkazib berish tez, sifat zo'r.\" },\n  { name: 'Jasur', rating: 3.5, text: \"O'lchami biroz katta keldi.\" },\n];\n\nexport default function RatingReadOnly() {\n  return (\n    <ul className=\"m-0 flex w-full max-w-sm list-none flex-col gap-4 p-0\">\n      {reviews.map((r) => (\n        <li key={r.name} className=\"flex flex-col gap-1\">\n          <div className=\"flex items-center justify-between gap-3\">\n            <span className=\"text-sm font-medium text-text\">{r.name}</span>\n            <Rating value={r.rating} readOnly size=\"sm\" />\n          </div>\n          <p className=\"m-0 text-sm text-text-muted\">{r.text}</p>\n        </li>\n      ))}\n    </ul>\n  );\n}\n" },
  "rating/with-field": { component: Demo927, file: "rating/with-field.tsx", source: "'use client';\n\nimport { Field, Rating } from '@akhatmirzo/ui';\n\nexport default function RatingWithField() {\n  return (\n    <Field label=\"Xizmat sifati\" description=\"1 dan 5 gacha baholang\">\n      <Rating defaultValue={5} allowClear={false} />\n    </Field>\n  );\n}\n" },
  "script/overview": { component: Demo928, file: "script/overview.tsx", source: "'use client';\n\nimport { ScriptProvider, ScriptToggle, Translit } from '@akhatmirzo/ui';\n\nexport default function ScriptOverview() {\n  return (\n    <ScriptProvider defaultScript=\"latin\">\n      <div className=\"flex w-full max-w-md flex-col items-start gap-4\">\n        <ScriptToggle size=\"sm\" />\n        <Translit as=\"h3\" className=\"text-lg font-semibold text-text\">\n          Oʻzbekiston boʻylab yetkazib berish\n        </Translit>\n        <Translit as=\"p\" className=\"text-sm text-text-muted\">\n          Buyurtmangiz 2–3 kun ichida eshigingizgacha yetkaziladi. Toʻlov — naqd yoki karta orqali.\n        </Translit>\n      </div>\n    </ScriptProvider>\n  );\n}\n" },
  "script/persist": { component: Demo929, file: "script/persist.tsx", source: "'use client';\n\nimport { ScriptProvider, ScriptToggle, Translit } from '@akhatmirzo/ui';\n\nexport default function ScriptPersist() {\n  return (\n    <ScriptProvider defaultScript=\"latin\" storageKey=\"docs-script-demo\">\n      <div className=\"flex flex-col items-start gap-3\">\n        <ScriptToggle labels={{ latin: 'Lotincha', cyrillic: 'Кириллча' }} />\n        <Translit className=\"text-sm text-text-muted\">\n          Tanlovingiz eslab qolinadi — sahifani yangilab koʻring.\n        </Translit>\n      </div>\n    </ScriptProvider>\n  );\n}\n" },
  "script/use-script": { component: Demo930, file: "script/use-script.tsx", source: "'use client';\n\nimport { Button, ScriptProvider, ScriptToggle, useScript } from '@akhatmirzo/ui';\n\nfunction Cart() {\n  const { script, t } = useScript();\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <p className=\"text-sm text-text-muted\">\n        script: <code>{script}</code>\n      </p>\n      <Button variant=\"primary\">{t('Savatga qoʻshish')}</Button>\n      <input\n        className=\"h-10 w-full rounded-lg border border-border bg-surface px-3 text-sm text-text\"\n        placeholder={t('Mahsulot qidirish')}\n        aria-label={t('Mahsulot qidirish')}\n      />\n    </div>\n  );\n}\n\nexport default function UseScriptDemo() {\n  return (\n    <ScriptProvider defaultScript=\"cyrillic\">\n      <div className=\"flex w-full max-w-sm flex-col gap-4\">\n        <ScriptToggle />\n        <Cart />\n      </div>\n    </ScriptProvider>\n  );\n}\n" },
  "segmented-control/basic": { component: Demo931, file: "segmented-control/basic.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\n\nexport default function SegmentedControlBasic() {\n  return (\n    <SegmentedControl defaultValue=\"month\" aria-label=\"Davr\">\n      <SegmentedControl.Item value=\"day\">Kun</SegmentedControl.Item>\n      <SegmentedControl.Item value=\"week\">Hafta</SegmentedControl.Item>\n      <SegmentedControl.Item value=\"month\">Oy</SegmentedControl.Item>\n      <SegmentedControl.Item value=\"year\">Yil</SegmentedControl.Item>\n    </SegmentedControl>\n  );\n}\n" },
  "segmented-control/controlled": { component: Demo932, file: "segmented-control/controlled.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst totals: Record<string, string> = {\n  day: \"1 250 000 so'm\",\n  week: \"8 740 000 so'm\",\n  month: \"36 900 000 so'm\",\n};\n\nexport default function SegmentedControlControlled() {\n  const [period, setPeriod] = useState('week');\n\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <SegmentedControl value={period} onValueChange={setPeriod} aria-label=\"Davr\">\n        <SegmentedControl.Item value=\"day\">Kun</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"week\">Hafta</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"month\">Oy</SegmentedControl.Item>\n      </SegmentedControl>\n      <p className=\"m-0 text-sm text-text-muted\">\n        Savdo: <span className=\"font-semibold text-text\">{totals[period]}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "segmented-control/disabled": { component: Demo933, file: "segmented-control/disabled.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\n\nexport default function SegmentedControlDisabled() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      <SegmentedControl defaultValue=\"card\" aria-label=\"To'lov usuli\">\n        <SegmentedControl.Item value=\"cash\">Naqd</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"card\">Karta</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"credit\" disabled>\n          Nasiya\n        </SegmentedControl.Item>\n      </SegmentedControl>\n      <SegmentedControl defaultValue=\"uz\" disabled aria-label=\"Til\">\n        <SegmentedControl.Item value=\"uz\">O'zbekcha</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"ru\">Ruscha</SegmentedControl.Item>\n      </SegmentedControl>\n    </div>\n  );\n}\n" },
  "segmented-control/full-width": { component: Demo934, file: "segmented-control/full-width.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\n\nexport default function SegmentedControlFullWidth() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <SegmentedControl fullWidth defaultValue=\"delivery\" aria-label=\"Olib ketish usuli\">\n        <SegmentedControl.Item value=\"delivery\">Yetkazib berish</SegmentedControl.Item>\n        <SegmentedControl.Item value=\"pickup\">Olib ketish</SegmentedControl.Item>\n      </SegmentedControl>\n    </div>\n  );\n}\n" },
  "segmented-control/icons": { component: Demo935, file: "segmented-control/icons.tsx", source: "'use client';\n\nimport { SegmentedControl } from '@akhatmirzo/ui';\nimport { LayoutGrid, List, MapIcon } from 'lucide-react';\n\nexport default function SegmentedControlIcons() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <SegmentedControl defaultValue=\"grid\" aria-label=\"Ko'rinish\">\n        <SegmentedControl.Item value=\"grid\" icon={<LayoutGrid />} aria-label=\"Katakli\" />\n        <SegmentedControl.Item value=\"list\" icon={<List />} aria-label=\"Ro'yxat\" />\n        <SegmentedControl.Item value=\"map\" icon={<MapIcon />} aria-label=\"Xarita\" />\n      </SegmentedControl>\n      <SegmentedControl defaultValue=\"list\" aria-label=\"Ko'rinish\">\n        <SegmentedControl.Item value=\"grid\" icon={<LayoutGrid />}>\n          Katakli\n        </SegmentedControl.Item>\n        <SegmentedControl.Item value=\"list\" icon={<List />}>\n          Ro'yxat\n        </SegmentedControl.Item>\n      </SegmentedControl>\n    </div>\n  );\n}\n" },
  "segmented-control/sizes": { component: Demo936, file: "segmented-control/sizes.tsx", source: "'use client';\n\nimport { Button, SegmentedControl } from '@akhatmirzo/ui';\n\nconst sizes = ['sm', 'md', 'lg'] as const;\n\nexport default function SegmentedControlSizes() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      {sizes.map((size) => (\n        <div key={size} className=\"flex items-center gap-3\">\n          <SegmentedControl size={size} defaultValue=\"all\" aria-label={`Holat, ${size}`}>\n            <SegmentedControl.Item value=\"all\">Hammasi</SegmentedControl.Item>\n            <SegmentedControl.Item value=\"paid\">To'langan</SegmentedControl.Item>\n            <SegmentedControl.Item value=\"debt\">Qarz</SegmentedControl.Item>\n          </SegmentedControl>\n          <Button size={size} variant=\"outline\">\n            Eksport\n          </Button>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "select/basic": { component: Demo937, file: "select/basic.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SelectBasic() {\n  const [region, setRegion] = useState('');\n\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-3\">\n      <Field label=\"Viloyat\" description=\"Buyurtma shu viloyatga yetkaziladi\">\n        <Select value={region} onValueChange={setRegion}>\n          <Select.Item value=\"tsh\">Toshkent shahri</Select.Item>\n          <Select.Item value=\"sam\">Samarqand</Select.Item>\n          <Select.Item value=\"bux\">Buxoro</Select.Item>\n          <Select.Item value=\"and\">Andijon</Select.Item>\n          <Select.Item value=\"fer\">Farg'ona</Select.Item>\n          <Select.Item value=\"nam\">Namangan</Select.Item>\n          <Select.Item value=\"qash\">Qashqadaryo</Select.Item>\n          <Select.Item value=\"xor\">Xorazm</Select.Item>\n          <Select.Item value=\"qqr\">Qoraqalpog'iston</Select.Item>\n        </Select>\n      </Field>\n      <p className=\"text-sm text-text-muted\">\n        Qiymat: <span className=\"font-medium text-text\">{region || '—'}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "select/form": { component: Demo938, file: "select/form.tsx", source: "'use client';\n\nimport { Button, Field, Select } from '@akhatmirzo/ui';\nimport { useState, type FormEvent } from 'react';\n\nexport default function SelectForm() {\n  const [error, setError] = useState<string>();\n  const [sent, setSent] = useState('—');\n\n  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    const delivery = String(new FormData(e.currentTarget).get('delivery') ?? '');\n    if (!delivery) return setError('Yetkazib berish usulini tanlang');\n    setError(undefined);\n    setSent(delivery);\n  };\n\n  return (\n    <form onSubmit={handleSubmit} className=\"flex w-full max-w-xs flex-col gap-4\">\n      <Field label=\"Yetkazib berish\" error={error} required>\n        <Select name=\"delivery\" onValueChange={() => setError(undefined)}>\n          <Select.Item value=\"courier\">Kuryer (1 kun)</Select.Item>\n          <Select.Item value=\"pickup\">Olib ketish</Select.Item>\n          <Select.Item value=\"post\">Pochta (2–3 kun)</Select.Item>\n        </Select>\n      </Field>\n      <div className=\"flex items-center gap-3\">\n        <Button type=\"submit\" variant=\"primary\">\n          Yuborish\n        </Button>\n        <span className=\"text-sm text-text-muted\">FormData: {sent}</span>\n      </div>\n    </form>\n  );\n}\n" },
  "select/groups": { component: Demo939, file: "select/groups.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nexport default function SelectGroups() {\n  return (\n    <Field label=\"Filial\" className=\"w-full max-w-xs\">\n      <Select defaultValue=\"fer\">\n        <Select.Item value=\"tsh\">Toshkent</Select.Item>\n        <Select.Item value=\"sam\">Samarqand</Select.Item>\n        <Select.Group label=\"Vodiy\">\n          <Select.Item value=\"and\">Andijon</Select.Item>\n          <Select.Item value=\"fer\">Farg'ona</Select.Item>\n          <Select.Item value=\"nam\">Namangan</Select.Item>\n        </Select.Group>\n        <Select.Separator />\n        <Select.Group label=\"Janub\">\n          <Select.Item value=\"qash\">Qashqadaryo</Select.Item>\n          <Select.Item value=\"sur\">Surxondaryo</Select.Item>\n        </Select.Group>\n      </Select>\n    </Field>\n  );\n}\n" },
  "select/icons": { component: Demo940, file: "select/icons.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nfunction Dot({ className }: { className: string }) {\n  return <span className={`size-2 rounded-full ${className}`} />;\n}\n\nexport default function SelectIcons() {\n  return (\n    <Field label=\"Buyurtma holati\" className=\"w-full max-w-xs\">\n      <Select defaultValue=\"progress\">\n        <Select.Item value=\"new\" icon={<Dot className=\"bg-info\" />}>\n          Yangi\n        </Select.Item>\n        <Select.Item value=\"progress\" icon={<Dot className=\"bg-warning\" />}>\n          Jarayonda\n        </Select.Item>\n        <Select.Item value=\"done\" icon={<Dot className=\"bg-success\" />}>\n          Yetkazildi\n        </Select.Item>\n        <Select.Item value=\"canceled\" icon={<Dot className=\"bg-danger\" />}>\n          Bekor qilindi\n        </Select.Item>\n      </Select>\n    </Field>\n  );\n}\n" },
  "select/region": { component: Demo941, file: "select/region.tsx", source: "'use client';\n\nimport type { UzRegionId } from '@akhatmirzo/core';\nimport { Field, RegionSelect, ScriptProvider, ScriptToggle } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function RegionSelectDemo() {\n  const [region, setRegion] = useState<UzRegionId>('samarkand');\n\n  return (\n    <ScriptProvider>\n      <div className=\"flex w-full max-w-sm flex-col gap-4\">\n        <ScriptToggle size=\"sm\" />\n        <Field label=\"Hudud\" description={`Qiymat: \"${region}\"`}>\n          <RegionSelect value={region} onValueChange={setRegion} />\n        </Field>\n        <Field label=\"Viloyat\" description=\"includeCity={false}\">\n          <RegionSelect includeCity={false} />\n        </Field>\n      </div>\n    </ScriptProvider>\n  );\n}\n" },
  "select/sizes": { component: Demo942, file: "select/sizes.tsx", source: "'use client';\n\nimport { Button, Select } from '@akhatmirzo/ui';\n\nexport default function SelectSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      {(['sm', 'md', 'lg'] as const).map((size) => (\n        <Select\n          key={size}\n          size={size}\n          aria-label={`O'lcham ${size}`}\n          placeholder={`size=\"${size}\"`}\n        >\n          <Select.Item value=\"a\">Birinchi</Select.Item>\n          <Select.Item value=\"b\">Ikkinchi</Select.Item>\n        </Select>\n      ))}\n      <div className=\"flex items-center gap-3\">\n        <Select aria-label=\"Valyuta\" defaultValue=\"uzs\" className=\"w-28\">\n          <Select.Item value=\"uzs\">UZS</Select.Item>\n          <Select.Item value=\"usd\">USD</Select.Item>\n          <Select.Item value=\"eur\">EUR</Select.Item>\n        </Select>\n        <Button variant=\"primary\">To'lash</Button>\n      </div>\n    </div>\n  );\n}\n" },
  "select/states": { component: Demo943, file: "select/states.tsx", source: "'use client';\n\nimport { Field, Select } from '@akhatmirzo/ui';\n\nexport default function SelectStates() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-3\">\n      <Field label=\"O'chirilgan\" disabled>\n        <Select defaultValue=\"click\">\n          <Select.Item value=\"click\">Click</Select.Item>\n        </Select>\n      </Field>\n      <Field label=\"To'lov usuli\" error=\"To'lov usulini tanlang\" required>\n        <Select>\n          <Select.Item value=\"click\">Click</Select.Item>\n          <Select.Item value=\"payme\">Payme</Select.Item>\n        </Select>\n      </Field>\n      <Field label=\"O'chirilgan element\">\n        <Select placeholder=\"Usulni tanlang\">\n          <Select.Item value=\"click\">Click</Select.Item>\n          <Select.Item value=\"payme\">Payme</Select.Item>\n          <Select.Item value=\"uzum\" disabled>\n            Uzum (vaqtincha ishlamaydi)\n          </Select.Item>\n          <Select.Item value=\"cash\">Naqd pul</Select.Item>\n        </Select>\n      </Field>\n    </div>\n  );\n}\n" },
  "skeleton/loading-card": { component: Demo944, file: "skeleton/loading-card.tsx", source: "'use client';\n\nimport { Avatar, Button, Card, Skeleton } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SkeletonLoadingCard() {\n  const [loading, setLoading] = useState(true);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col items-start gap-3\">\n      <Button size=\"sm\" onClick={() => setLoading((l) => !l)}>\n        {loading ? \"Kontentni ko'rsatish\" : 'Yuklanish holati'}\n      </Button>\n      <Card variant=\"outline\" className=\"w-full\" aria-busy={loading}>\n        <div className=\"flex items-center gap-3\">\n          {loading ? (\n            <Skeleton variant=\"circle\" className=\"size-10\" />\n          ) : (\n            <Avatar name=\"Malika Rahimova\" />\n          )}\n          <div className=\"flex flex-1 flex-col gap-2\">\n            {loading ? (\n              <Skeleton className=\"h-4 w-2/5\" />\n            ) : (\n              <b className=\"text-sm\">Malika Rahimova</b>\n            )}\n            {loading ? (\n              <Skeleton className=\"h-3 w-1/4\" />\n            ) : (\n              <span className=\"text-xs text-text-muted\">2 soat oldin</span>\n            )}\n          </div>\n        </div>\n        {loading ? (\n          <Skeleton.Text lines={3} />\n        ) : (\n          <p className=\"text-sm\">\n            Buyurtma vaqtida yetib keldi, kuryer juda xushmuomala edi. Keyingi safar ham shu\n            do'kondan olaman.\n          </p>\n        )}\n      </Card>\n    </div>\n  );\n}\n" },
  "skeleton/shapes": { component: Demo945, file: "skeleton/shapes.tsx", source: "'use client';\n\nimport { Skeleton } from '@akhatmirzo/ui';\n\nexport default function SkeletonShapes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Skeleton variant=\"circle\" className=\"size-12\" />\n      <Skeleton className=\"h-4 w-32\" />\n      <Skeleton className=\"h-10 w-28 rounded-lg\" />\n    </div>\n  );\n}\n" },
  "skeleton/text": { component: Demo946, file: "skeleton/text.tsx", source: "'use client';\n\nimport { Skeleton } from '@akhatmirzo/ui';\n\nexport default function SkeletonTextDemo() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-6 sm:grid-cols-2\">\n      <Skeleton.Text lines={1} />\n      <Skeleton.Text lines={4} />\n    </div>\n  );\n}\n" },
  "slider/basic": { component: Demo947, file: "slider/basic.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderBasic() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Slider defaultValue={[40]} aria-label=\"Yorqinlik\" />\n    </div>\n  );\n}\n" },
  "slider/marks": { component: Demo948, file: "slider/marks.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nconst marks = [\n  { value: 0, label: '0%' },\n  { value: 25, label: '25%' },\n  { value: 50, label: '50%' },\n  { value: 75, label: '75%' },\n  { value: 100, label: '100%' },\n];\n\nexport default function SliderMarks() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Slider\n        defaultValue={[25]}\n        step={25}\n        marks={marks}\n        formatValue={(v) => `${v}%`}\n        aria-label=\"Chegirma\"\n      />\n    </div>\n  );\n}\n" },
  "slider/range": { component: Demo949, file: "slider/range.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { Slider } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SliderRange() {\n  const [price, setPrice] = useState([1_000_000, 3_500_000]);\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-4\">\n      <Slider\n        value={price}\n        onValueChange={setPrice}\n        min={0}\n        max={5_000_000}\n        step={50_000}\n        minStepsBetweenThumbs={2}\n        formatValue={(v) => formatMoney(v)}\n        aria-label=\"Narx\"\n      />\n      <p className=\"m-0 text-sm text-text-muted\">\n        Narx:{' '}\n        <span className=\"font-semibold text-text tabular-nums\">\n          {formatMoney(price[0]!)} — {formatMoney(price[1]!)}\n        </span>\n      </p>\n    </div>\n  );\n}\n" },
  "slider/show-value": { component: Demo950, file: "slider/show-value.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderShowValue() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-10 pt-8\">\n      <Slider defaultValue={[30]} showValue=\"active\" aria-label=\"Faol paytda\" />\n      <Slider defaultValue={[60]} showValue=\"always\" aria-label=\"Doim\" />\n      <Slider defaultValue={[80]} showValue=\"never\" aria-label=\"Hech qachon\" />\n    </div>\n  );\n}\n" },
  "slider/sizes": { component: Demo951, file: "slider/sizes.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderSizes() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-8\">\n      <Slider size=\"sm\" defaultValue={[35]} aria-label=\"Kichik\" />\n      <Slider size=\"md\" defaultValue={[65]} aria-label=\"O'rta\" />\n      <Slider defaultValue={[50]} disabled aria-label=\"O'chirilgan\" />\n    </div>\n  );\n}\n" },
  "slider/vertical": { component: Demo952, file: "slider/vertical.tsx", source: "'use client';\n\nimport { Slider } from '@akhatmirzo/ui';\n\nexport default function SliderVertical() {\n  return (\n    <div className=\"flex h-48 items-stretch gap-10 pl-12\">\n      <Slider orientation=\"vertical\" defaultValue={[70]} aria-label=\"Ovoz\" />\n      <Slider orientation=\"vertical\" defaultValue={[20, 60]} aria-label=\"Harorat\" />\n    </div>\n  );\n}\n" },
  "slider/with-field": { component: Demo953, file: "slider/with-field.tsx", source: "'use client';\n\nimport { Field, Slider } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SliderWithField() {\n  const [km, setKm] = useState([45]);\n\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Field\n        label=\"Yetkazib berish radiusi\"\n        description=\"Do'kondan necha km uzoqlikkacha yetkazasiz\"\n        error={km[0]! > 40 ? \"40 km dan uzoqqa kuryer yo'q\" : undefined}\n      >\n        <Slider value={km} onValueChange={setKm} max={60} formatValue={(v) => `${v} km`} />\n      </Field>\n    </div>\n  );\n}\n" },
  "spinner/colors": { component: Demo954, file: "spinner/colors.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerColors() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Spinner className=\"text-text\" />\n      <Spinner className=\"text-primary\" />\n      <Spinner className=\"text-success\" />\n      <Spinner className=\"text-danger\" />\n      <span className=\"inline-flex size-10 items-center justify-center rounded-lg bg-primary text-primary-foreground\">\n        <Spinner size=\"sm\" />\n      </span>\n    </div>\n  );\n}\n" },
  "spinner/sizes": { component: Demo955, file: "spinner/sizes.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerSizes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-4 text-text-muted\">\n      <Spinner size=\"sm\" />\n      <Spinner size=\"md\" />\n      <Spinner size=\"lg\" />\n    </div>\n  );\n}\n" },
  "spinner/with-text": { component: Demo956, file: "spinner/with-text.tsx", source: "'use client';\n\nimport { Spinner } from '@akhatmirzo/ui';\n\nexport default function SpinnerWithText() {\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3\">\n      <span className=\"inline-flex items-center gap-2 text-sm text-text-muted\">\n        <Spinner size=\"sm\" aria-hidden=\"true\" />\n        Buyurtmalar yuklanmoqda...\n      </span>\n      <div className=\"flex h-32 items-center justify-center rounded-lg border border-border bg-surface text-text-muted\">\n        <Spinner size=\"lg\" label=\"Jadval yuklanmoqda\" />\n      </div>\n    </div>\n  );\n}\n" },
  "stepper/basic": { component: Demo957, file: "stepper/basic.tsx", source: "'use client';\n\nimport { Button, Stepper } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst steps = [\n  { title: 'Savat' },\n  { title: 'Yetkazib berish', description: 'Manzil va vaqt' },\n  { title: \"To'lov\" },\n  { title: 'Tasdiqlash', optional: true },\n];\n\nexport default function StepperBasic() {\n  const [step, setStep] = useState(1);\n\n  return (\n    <div className=\"flex w-full flex-col gap-6\">\n      <Stepper steps={steps} value={step} onValueChange={setStep} aria-label=\"Buyurtma\" />\n      <div className=\"flex gap-2\">\n        <Button size=\"sm\" disabled={step === 0} onClick={() => setStep(step - 1)}>\n          Orqaga\n        </Button>\n        <Button\n          size=\"sm\"\n          variant=\"primary\"\n          disabled={step === steps.length}\n          onClick={() => setStep(step + 1)}\n        >\n          Davom etish\n        </Button>\n      </div>\n    </div>\n  );\n}\n" },
  "stepper/compact": { component: Demo958, file: "stepper/compact.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\n\nconst steps = [\n  { title: 'Savat' },\n  { title: 'Yetkazib berish' },\n  { title: \"To'lov\" },\n  { title: 'Tasdiqlash' },\n];\n\nexport default function StepperCompact() {\n  return (\n    <div className=\"w-full max-w-xs\">\n      <Stepper steps={steps} value={1} compact />\n    </div>\n  );\n}\n" },
  "stepper/sizes": { component: Demo959, file: "stepper/sizes.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\n\nconst steps = [{ title: 'Savat' }, { title: 'Yetkazib berish' }, { title: \"To'lov\" }];\n\nexport default function StepperSizes() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      <Stepper steps={steps} defaultValue={1} size=\"sm\" aria-label=\"Kichik\" />\n      <Stepper steps={steps} defaultValue={1} aria-label=\"O'rtacha\" />\n    </div>\n  );\n}\n" },
  "stepper/states": { component: Demo960, file: "stepper/states.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\n\nexport default function StepperStates() {\n  return (\n    <Stepper\n      aria-label=\"Ariza\"\n      value={2}\n      className=\"w-full\"\n      steps={[\n        { title: \"Ma'lumotlar\" },\n        { title: 'Hujjatlar', status: 'error', description: \"Pasport rasmi o'qilmadi\" },\n        { title: 'Tekshiruv' },\n        { title: 'Shartnoma' },\n      ]}\n    />\n  );\n}\n" },
  "stepper/vertical": { component: Demo961, file: "stepper/vertical.tsx", source: "'use client';\n\nimport { Stepper } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function StepperVertical() {\n  const [step, setStep] = useState(1);\n\n  return (\n    <Stepper\n      orientation=\"vertical\"\n      aria-label=\"Do'konni sozlash\"\n      value={step}\n      onValueChange={setStep}\n      allowFutureSteps\n      steps={[\n        { title: \"Do'kon nomi\", description: \"Mijozlar ko'radigan nom\" },\n        { title: \"To'lov usullari\", description: 'Click, Payme, naqd' },\n        { title: 'Yetkazib berish', description: 'Hududlar va narxlar' },\n        { title: 'Ishga tushirish' },\n      ]}\n    />\n  );\n}\n" },
  "switch/basic": { component: Demo962, file: "switch/basic.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchBasic() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <Switch label=\"Bildirishnomalar\" defaultChecked />\n      <Switch label=\"Avtomatik saqlash\" />\n    </div>\n  );\n}\n" },
  "switch/controlled": { component: Demo963, file: "switch/controlled.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function SwitchControlled() {\n  const [open, setOpen] = useState(true);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-4\">\n      <Switch label=\"Do'kon ochiq\" checked={open} onCheckedChange={setOpen} />\n      <span className=\"text-sm text-text-muted\">\n        {open ? 'Buyurtmalar qabul qilinmoqda' : \"Buyurtmalar to'xtatilgan\"}\n      </span>\n    </div>\n  );\n}\n" },
  "switch/description": { component: Demo964, file: "switch/description.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchDescription() {\n  return (\n    <div className=\"flex max-w-sm flex-col gap-4\">\n      <Switch label=\"Qorong'i mavzu\" description=\"Tizim sozlamasidan qat'i nazar\" defaultChecked />\n      <Switch size=\"sm\" label=\"Ovozli signal\" description=\"Yangi buyurtma kelganda\" />\n    </div>\n  );\n}\n" },
  "switch/sizes": { component: Demo965, file: "switch/sizes.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchSizes() {\n  return (\n    <div className=\"flex flex-wrap items-start gap-8\">\n      <Switch size=\"sm\" label=\"Kichik · 32×18\" defaultChecked />\n      <Switch size=\"md\" label=\"O'rta · 40×24\" defaultChecked />\n    </div>\n  );\n}\n" },
  "switch/states": { component: Demo966, file: "switch/states.tsx", source: "'use client';\n\nimport { Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchStates() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <Switch label=\"O'chirilgan\" disabled />\n      <Switch label=\"O'chirilgan, yoqilgan\" disabled defaultChecked />\n      <Switch label=\"Xato\" invalid />\n    </div>\n  );\n}\n" },
  "switch/with-field": { component: Demo967, file: "switch/with-field.tsx", source: "'use client';\n\nimport { Field, Switch } from '@akhatmirzo/ui';\n\nexport default function SwitchWithField() {\n  return (\n    <div className=\"max-w-sm\">\n      <Field label=\"Ikki bosqichli tasdiqlash\" description=\"Har kirishda SMS kod so'raladi\">\n        <Switch />\n      </Field>\n    </div>\n  );\n}\n" },
  "tabs/badges": { component: Demo968, file: "tabs/badges.tsx", source: "'use client';\n\nimport { Badge, Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsBadges() {\n  return (\n    <Tabs defaultValue=\"new\">\n      <Tabs.List aria-label=\"Buyurtmalar holati\">\n        <Tabs.Trigger value=\"new\" badge={4}>\n          Yangi\n        </Tabs.Trigger>\n        <Tabs.Trigger\n          value=\"paid\"\n          badge={\n            <Badge color=\"success\" size=\"sm\">\n              +2\n            </Badge>\n          }\n        >\n          To'langan\n        </Tabs.Trigger>\n        <Tabs.Trigger value=\"canceled\" disabled>\n          Bekor qilingan\n        </Tabs.Trigger>\n      </Tabs.List>\n    </Tabs>\n  );\n}\n" },
  "tabs/controlled": { component: Demo969, file: "tabs/controlled.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst totals: Record<string, string> = {\n  day: \"1 250 000 so'm\",\n  week: \"8 740 000 so'm\",\n  month: \"36 900 000 so'm\",\n  year: \"412 500 000 so'm\",\n};\n\nexport default function TabsControlled() {\n  const [period, setPeriod] = useState('week');\n\n  return (\n    <div className=\"flex flex-col items-start gap-3\">\n      <Tabs value={period} onValueChange={setPeriod} variant=\"segmented\">\n        <Tabs.List aria-label=\"Davr\">\n          <Tabs.Trigger value=\"day\">Kun</Tabs.Trigger>\n          <Tabs.Trigger value=\"week\">Hafta</Tabs.Trigger>\n          <Tabs.Trigger value=\"month\">Oy</Tabs.Trigger>\n          <Tabs.Trigger value=\"year\">Yil</Tabs.Trigger>\n        </Tabs.List>\n      </Tabs>\n      <p className=\"m-0 text-sm text-text-muted\">\n        Savdo: <span className=\"font-semibold text-text\">{totals[period]}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "tabs/scrollable": { component: Demo970, file: "tabs/scrollable.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nconst months = [\n  'Yanvar',\n  'Fevral',\n  'Mart',\n  'Aprel',\n  'May',\n  'Iyun',\n  'Iyul',\n  'Avgust',\n  'Sentabr',\n  'Oktabr',\n  'Noyabr',\n  'Dekabr',\n];\n\nexport default function TabsScrollable() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Tabs defaultValue=\"Mart\">\n        <Tabs.List aria-label=\"Oylar\">\n          {months.map((m) => (\n            <Tabs.Trigger key={m} value={m}>\n              {m}\n            </Tabs.Trigger>\n          ))}\n        </Tabs.List>\n        {months.map((m) => (\n          <Tabs.Content key={m} value={m} className=\"text-text-muted\">\n            {m} oyi bo'yicha savdo hisoboti.\n          </Tabs.Content>\n        ))}\n      </Tabs>\n    </div>\n  );\n}\n" },
  "tabs/sizes": { component: Demo971, file: "tabs/sizes.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsSizes() {\n  return (\n    <div className=\"flex flex-col items-start gap-4\">\n      {(['underline', 'pills', 'segmented'] as const).map((variant) => (\n        <Tabs key={variant} defaultValue=\"all\" variant={variant} size=\"sm\">\n          <Tabs.List aria-label=\"Holat bo'yicha\">\n            <Tabs.Trigger value=\"all\">Hammasi</Tabs.Trigger>\n            <Tabs.Trigger value=\"active\">Faol</Tabs.Trigger>\n            <Tabs.Trigger value=\"archive\">Arxiv</Tabs.Trigger>\n          </Tabs.List>\n        </Tabs>\n      ))}\n    </div>\n  );\n}\n" },
  "tabs/variants": { component: Demo972, file: "tabs/variants.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsVariants() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      {(['underline', 'pills', 'segmented'] as const).map((variant) => (\n        <Tabs key={variant} defaultValue=\"info\" variant={variant}>\n          <Tabs.List aria-label={`Mijoz (${variant})`}>\n            <Tabs.Trigger value=\"info\">Ma'lumot</Tabs.Trigger>\n            <Tabs.Trigger value=\"orders\" badge={12}>\n              Buyurtmalar\n            </Tabs.Trigger>\n            <Tabs.Trigger value=\"reviews\">Sharhlar</Tabs.Trigger>\n          </Tabs.List>\n          <Tabs.Content value=\"info\" className=\"text-text-muted\">\n            Ism, telefon va yetkazib berish manzili.\n          </Tabs.Content>\n          <Tabs.Content value=\"orders\" className=\"text-text-muted\">\n            Oxirgi 12 ta buyurtma ro'yxati.\n          </Tabs.Content>\n          <Tabs.Content value=\"reviews\" className=\"text-text-muted\">\n            Mijoz hali sharh qoldirmagan.\n          </Tabs.Content>\n        </Tabs>\n      ))}\n    </div>\n  );\n}\n" },
  "tabs/vertical": { component: Demo973, file: "tabs/vertical.tsx", source: "'use client';\n\nimport { Tabs } from '@akhatmirzo/ui';\n\nexport default function TabsVertical() {\n  return (\n    <Tabs defaultValue=\"profile\" orientation=\"vertical\" variant=\"pills\" className=\"w-full\">\n      <Tabs.List aria-label=\"Sozlamalar\" className=\"w-44\">\n        <Tabs.Trigger value=\"profile\">Profil</Tabs.Trigger>\n        <Tabs.Trigger value=\"security\">Xavfsizlik</Tabs.Trigger>\n        <Tabs.Trigger value=\"notifications\" badge={3}>\n          Bildirishnomalar\n        </Tabs.Trigger>\n        <Tabs.Trigger value=\"billing\" disabled>\n          To'lovlar\n        </Tabs.Trigger>\n      </Tabs.List>\n      <Tabs.Content value=\"profile\" className=\"text-text-muted\">\n        Ism, familiya va profil rasmi.\n      </Tabs.Content>\n      <Tabs.Content value=\"security\" className=\"text-text-muted\">\n        Parol va ikki bosqichli tasdiqlash.\n      </Tabs.Content>\n      <Tabs.Content value=\"notifications\" className=\"text-text-muted\">\n        SMS, email va Telegram orqali bildirishnomalar.\n      </Tabs.Content>\n    </Tabs>\n  );\n}\n" },
  "tag-input/basic": { component: Demo974, file: "tag-input/basic.tsx", source: "'use client';\n\nimport { TagInput } from '@akhatmirzo/ui';\n\nexport default function TagInputBasic() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <TagInput\n        defaultValue={['React', 'TypeScript']}\n        placeholder=\"Teg qo'shing\"\n        aria-label=\"Teglar\"\n      />\n    </div>\n  );\n}\n" },
  "tag-input/sizes": { component: Demo975, file: "tag-input/sizes.tsx", source: "'use client';\n\nimport { TagInput } from '@akhatmirzo/ui';\n\nexport default function TagInputSizes() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <TagInput size=\"sm\" defaultValue={['sm']} aria-label=\"Kichik\" />\n      <TagInput defaultValue={['md']} aria-label=\"O'rtacha\" />\n      <TagInput size=\"lg\" defaultValue={['lg']} aria-label=\"Katta\" />\n      <TagInput disabled defaultValue={[\"O'chirilgan\"]} aria-label=\"O'chirilgan\" />\n    </div>\n  );\n}\n" },
  "tag-input/suggestions": { component: Demo976, file: "tag-input/suggestions.tsx", source: "'use client';\n\nimport { Field, TagInput } from '@akhatmirzo/ui';\n\nconst cities = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\", 'Namangan', 'Andijon', 'Xiva'];\n\nexport default function TagInputSuggestions() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Field label=\"Shaharlar\" description=\"Ko'pi bilan 4 ta. «тош» deb yozib ko'ring\">\n        <TagInput suggestions={cities} maxTags={4} placeholder=\"Shahar yozing\" />\n      </Field>\n    </div>\n  );\n}\n" },
  "tag-input/validate": { component: Demo977, file: "tag-input/validate.tsx", source: "'use client';\n\nimport { isValidEmail } from '@akhatmirzo/core';\nimport { Field, TagInput } from '@akhatmirzo/ui';\n\nexport default function TagInputValidate() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Field label=\"Qabul qiluvchilar\" description=\"Bir nechta emailni vergul bilan qo'ying\">\n        <TagInput\n          validate={(email) => isValidEmail(email) || \"Email noto'g'ri\"}\n          transform={(raw) => raw.trim().toLowerCase()}\n          placeholder=\"Email qo'shing\"\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "tag-input/with-field": { component: Demo978, file: "tag-input/with-field.tsx", source: "'use client';\n\nimport { Field, TagInput } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function TagInputWithField() {\n  const [tags, setTags] = useState(['dizayn', 'frontend']);\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-3\">\n      <Field label=\"Kalit so'zlar\" description=\"Enter yoki vergul bilan qo'shing\">\n        <TagInput value={tags} onValueChange={setTags} placeholder=\"Kalit so'z\" />\n      </Field>\n      <p className=\"m-0 text-sm text-text-muted\">\n        Qiymat: <span className=\"font-mono text-text\">{JSON.stringify(tags)}</span>\n      </p>\n    </div>\n  );\n}\n" },
  "textarea/auto-resize": { component: Demo979, file: "textarea/auto-resize.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaAutoResize() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea\n        autoResize\n        minRows={2}\n        maxRows={6}\n        placeholder=\"Yozib ko'ring — maydon matn bilan birga o'sadi\"\n        aria-label=\"Xabar\"\n      />\n    </div>\n  );\n}\n" },
  "textarea/basic": { component: Demo980, file: "textarea/basic.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaBasic() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea placeholder=\"Buyurtma haqida izoh qoldiring\" aria-label=\"Izoh\" />\n    </div>\n  );\n}\n" },
  "textarea/count": { component: Demo981, file: "textarea/count.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function TextareaCount() {\n  const [bio, setBio] = useState(\n    'Frontend dasturchi, Toshkent. React va TypeScript bilan ishlayman.',\n  );\n\n  return (\n    <div className=\"w-full max-w-md\">\n      <Textarea\n        showCount\n        maxLength={120}\n        value={bio}\n        onChange={(e) => setBio(e.target.value)}\n        aria-label=\"O'zingiz haqingizda\"\n      />\n    </div>\n  );\n}\n" },
  "textarea/states": { component: Demo982, file: "textarea/states.tsx", source: "'use client';\n\nimport { Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaStates() {\n  return (\n    <div className=\"grid w-full max-w-lg grid-cols-1 gap-3 sm:grid-cols-2\">\n      <Textarea minRows={2} invalid defaultValue=\"Juda qisqa\" aria-label=\"Xato\" />\n      <Textarea minRows={2} disabled defaultValue=\"O'chirilgan\" aria-label=\"O'chirilgan\" />\n      <Textarea minRows={2} readOnly defaultValue=\"Faqat o'qish uchun\" aria-label=\"Faqat o'qish\" />\n      <Textarea minRows={2} size=\"sm\" placeholder=\"Kichik o'lcham\" aria-label=\"Kichik\" />\n    </div>\n  );\n}\n" },
  "textarea/with-field": { component: Demo983, file: "textarea/with-field.tsx", source: "'use client';\n\nimport { Field, Textarea } from '@akhatmirzo/ui';\n\nexport default function TextareaWithField() {\n  return (\n    <div className=\"w-full max-w-md\">\n      <Field label=\"Izoh\" required description=\"Kuryer uchun qo'shimcha ma'lumot\">\n        <Textarea\n          autoResize\n          showCount\n          maxLength={300}\n          placeholder=\"Masalan: 3-podyezd, domofon ishlamaydi\"\n        />\n      </Field>\n    </div>\n  );\n}\n" },
  "theming/brand": { component: Demo984, file: "theming/brand.tsx", source: "'use client';\n\nimport { Badge, Button, Field, Input, Switch } from '@akhatmirzo/ui';\nimport { useState, type CSSProperties } from 'react';\n\nconst BRANDS = ['indigo', 'emerald', 'sky', 'rose'] as const;\n\n// Brend rangini faqat shu blok ichida almashtiramiz. color-mix — light va dark'da birdek ishlaydi.\nconst brandVars = (c: string) =>\n  ({\n    '--ak-primary': `var(--ak-${c}-600)`,\n    '--ak-primary-hover': `var(--ak-${c}-700)`,\n    '--ak-primary-soft': `color-mix(in srgb, var(--ak-${c}-500) 14%, var(--ak-surface))`,\n    '--ak-primary-soft-hover': `color-mix(in srgb, var(--ak-${c}-500) 22%, var(--ak-surface))`,\n    '--ak-primary-soft-foreground': `color-mix(in srgb, var(--ak-${c}-600) 65%, var(--ak-text))`,\n    '--ak-ring': `color-mix(in srgb, var(--ak-${c}-500) 45%, transparent)`,\n  }) as CSSProperties;\n\nexport default function ThemingBrand() {\n  const [brand, setBrand] = useState<(typeof BRANDS)[number]>('emerald');\n\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-4\">\n      <div className=\"flex flex-wrap gap-2\">\n        {BRANDS.map((b) => (\n          <Button\n            key={b}\n            size=\"sm\"\n            variant={b === brand ? 'outline' : 'ghost'}\n            onClick={() => setBrand(b)}\n          >\n            {b}\n          </Button>\n        ))}\n      </div>\n      <div\n        style={brandVars(brand)}\n        className=\"flex flex-col gap-4 rounded-xl border border-border bg-surface p-5\"\n      >\n        <Field label=\"Telefon\">\n          <Input placeholder=\"+998 90 123 45 67\" />\n        </Field>\n        <Switch defaultChecked label=\"Yangiliklarga obuna\" />\n        <div className=\"flex flex-wrap items-center gap-2\">\n          <Button variant=\"primary\">Saqlash</Button>\n          <Button>Bekor qilish</Button>\n          <Badge color=\"primary\">Yangi</Badge>\n        </div>\n      </div>\n    </div>\n  );\n}\n" },
  "theming/motion": { component: Demo985, file: "theming/motion.tsx", source: "'use client';\n\nimport { Button } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nconst EASINGS = [\n  ['ease-out', 'Kirishlar (asosiy)'],\n  ['ease-in', 'Chiqishlar'],\n  ['ease-in-out', \"Joyida o'zgarish\"],\n  ['ease-spring', 'Toast, switch'],\n];\n\nexport default function ThemingMotion() {\n  const [on, setOn] = useState(false);\n\n  return (\n    <div className=\"flex w-full max-w-lg flex-col gap-4\">\n      <Button size=\"sm\" variant=\"primary\" className=\"self-start\" onClick={() => setOn((v) => !v)}>\n        {on ? 'Qaytarish' : 'Ishga tushirish'}\n      </Button>\n      {EASINGS.map(([easing, note]) => (\n        <div key={easing} className=\"flex items-center gap-3\">\n          <div className=\"flex w-28 shrink-0 flex-col text-xs\">\n            <code className=\"font-mono text-text\">{easing}</code>\n            <span className=\"text-text-muted\">{note}</span>\n          </div>\n          <div className=\"relative h-6 flex-1 rounded-full bg-surface-muted\">\n            {/* Qatlam kengligi = yo'lak − sharcha, shuning uchun translate-x-full oxirigacha olib boradi */}\n            <div\n              className={`absolute inset-y-0 left-0 w-[calc(100%-1.5rem)] transition-transform duration-slow ${easing} ${on ? 'translate-x-full' : ''}`}\n            >\n              <div className=\"size-6 rounded-full bg-primary\" />\n            </div>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "theming/palette": { component: Demo986, file: "theming/palette.tsx", source: "'use client';\n\nimport { useSyncExternalStore } from 'react';\n\nconst SCALES = {\n  indigo: ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900', '950'],\n  slate: ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900', '950'],\n  emerald: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  amber: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  rose: ['50', '100', '300', '400', '500', '600', '700', '950'],\n  sky: ['50', '100', '300', '400', '500', '600', '700', '950'],\n};\n\nconst subscribe = () => () => {};\n// CSS o'zgaruvchilarning haqiqiy qiymatlari (serverda — bo'sh)\nconst readValues = () => {\n  const style = getComputedStyle(document.documentElement);\n  return Object.entries(SCALES)\n    .flatMap(([name, steps]) =>\n      steps.map((s) => style.getPropertyValue(`--ak-${name}-${s}`).trim()),\n    )\n    .join(',');\n};\n\nexport default function ThemingPalette() {\n  const values = useSyncExternalStore(subscribe, readValues, () => '').split(',');\n  let index = 0;\n\n  return (\n    <div className=\"flex w-full flex-col gap-5\">\n      {Object.entries(SCALES).map(([name, steps]) => (\n        <div key={name} className=\"flex flex-col gap-2\">\n          <span className=\"text-sm font-semibold text-text\">{name}</span>\n          <div className=\"grid grid-cols-4 gap-2 sm:grid-cols-6 lg:grid-cols-11\">\n            {steps.map((step) => {\n              const value = values[index++];\n              return (\n                <div key={step} className=\"flex flex-col gap-1\">\n                  <div\n                    className=\"h-10 rounded-md border border-border\"\n                    style={{ background: `var(--ak-${name}-${step})` }}\n                  />\n                  <span className=\"text-xs font-medium text-text\">{step}</span>\n                  <span className=\"font-mono text-xs text-text-muted uppercase\">{value}</span>\n                </div>\n              );\n            })}\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "theming/radius-shadow": { component: Demo987, file: "theming/radius-shadow.tsx", source: "'use client';\n\nconst RADII = [\n  ['rounded-sm', '6px'],\n  ['rounded-md', '8px'],\n  ['rounded-lg', '12px'],\n  ['rounded-xl', '16px'],\n  ['rounded-2xl', '20px'],\n  ['rounded-full', '9999px'],\n];\n\nconst SHADOWS = [\n  ['shadow-xs', 'Input, tugma'],\n  ['shadow-sm', 'Karta'],\n  ['shadow-md', 'Dropdown'],\n  ['shadow-lg', 'Popover, toast'],\n  ['shadow-xl', 'Modal, drawer'],\n];\n\nexport default function ThemingRadiusShadow() {\n  return (\n    <div className=\"flex w-full flex-col gap-8\">\n      <div className=\"grid grid-cols-3 gap-4 sm:grid-cols-6\">\n        {RADII.map(([className, value]) => (\n          <div key={className} className=\"flex flex-col items-center gap-2 text-xs\">\n            <div className={`size-14 border-2 border-primary bg-primary-soft ${className}`} />\n            <code className=\"font-mono text-text\">{className}</code>\n            <span className=\"text-text-muted\">{value}</span>\n          </div>\n        ))}\n      </div>\n      <div className=\"grid grid-cols-2 gap-5 sm:grid-cols-5\">\n        {SHADOWS.map(([className, note]) => (\n          <div\n            key={className}\n            className={`flex h-20 flex-col items-center justify-center rounded-xl bg-surface-raised text-xs ${className}`}\n          >\n            <code className=\"font-mono text-text\">{className}</code>\n            <span className=\"text-text-muted\">{note}</span>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n" },
  "theming/scoped": { component: Demo988, file: "theming/scoped.tsx", source: "'use client';\n\nimport { Badge, Button, Field, Input } from '@akhatmirzo/ui';\n\n// data-theme istalgan elementga qo'yiladi — tokenlar faqat shu blok ichida almashadi\nexport default function ThemingScoped() {\n  return (\n    <div className=\"grid w-full gap-4 sm:grid-cols-2\">\n      {(['light', 'dark'] as const).map((theme) => (\n        <div\n          key={theme}\n          data-theme={theme}\n          className=\"flex flex-col gap-4 rounded-xl border border-border bg-background p-5 text-text\"\n        >\n          <div className=\"flex items-center justify-between\">\n            <span className=\"text-sm font-semibold\">data-theme=\"{theme}\"</span>\n            <Badge color=\"success\" dot>\n              Faol\n            </Badge>\n          </div>\n          <Field label=\"Ism\">\n            <Input placeholder=\"Sarvar\" />\n          </Field>\n          <div className=\"flex gap-2\">\n            <Button variant=\"primary\">Saqlash</Button>\n            <Button variant=\"outline\">Bekor qilish</Button>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "theming/semantic": { component: Demo989, file: "theming/semantic.tsx", source: "'use client';\n\nimport { useSyncExternalStore } from 'react';\n\nconst TOKENS = [\n  ['background', 'Sahifa foni'],\n  ['surface', 'Karta, input, modal'],\n  ['surface-muted', 'Hover, ikkilamchi fon'],\n  ['surface-raised', 'Popover, toast'],\n  ['border', 'Oddiy chegara'],\n  ['border-strong', 'Hover chegara'],\n  ['text', 'Asosiy matn'],\n  ['text-subtle', 'Ghost tugma, ikonka'],\n  ['text-muted', 'Yordamchi matn'],\n  ['text-faint', 'Placeholder'],\n  ['primary', 'Asosiy tugma'],\n  ['primary-soft', 'Soft tugma, badge'],\n  ['primary-soft-foreground', 'Soft ustidagi matn'],\n  ['link', 'Havola'],\n  ['danger', 'Xavfli tugma'],\n  ['ring', 'Fokus halqasi'],\n] as const;\n\n// Mavzu almashganda (<html data-theme>) qiymatlar qayta o'qiladi\nconst subscribe = (onChange: () => void) => {\n  const observer = new MutationObserver(onChange);\n  observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });\n  return () => observer.disconnect();\n};\nconst readValues = () => {\n  const style = getComputedStyle(document.documentElement);\n  return TOKENS.map(([token]) => style.getPropertyValue(`--ak-${token}`).trim()).join('|');\n};\n\nexport default function ThemingSemantic() {\n  const values = useSyncExternalStore(subscribe, readValues, () => '').split('|');\n\n  return (\n    <div className=\"grid w-full gap-3 sm:grid-cols-2\">\n      {TOKENS.map(([token, note], i) => (\n        <div key={token} className=\"flex items-center gap-3\">\n          <div\n            className=\"size-10 shrink-0 rounded-lg border border-border\"\n            style={{ background: `var(--ak-${token})` }}\n          />\n          <div className=\"flex min-w-0 flex-col text-xs\">\n            <span className=\"truncate font-mono font-medium text-text\">{token}</span>\n            <span className=\"truncate text-text-muted\">{note}</span>\n            <span className=\"truncate font-mono text-text-faint\">{values[i] || '—'}</span>\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "theming/status": { component: Demo990, file: "theming/status.tsx", source: "'use client';\n\nconst STATUSES = ['success', 'warning', 'danger', 'info'] as const;\n\nconst SOFT = {\n  success: 'bg-success-soft text-success-soft-foreground',\n  warning: 'bg-warning-soft text-warning-soft-foreground',\n  danger: 'bg-danger-soft text-danger-soft-foreground',\n  info: 'bg-info-soft text-info-soft-foreground',\n};\nconst SOLID = {\n  success: 'bg-success text-success-foreground',\n  warning: 'bg-warning text-warning-foreground',\n  danger: 'bg-danger text-danger-foreground',\n  info: 'bg-info text-info-foreground',\n};\n\nexport default function ThemingStatus() {\n  return (\n    <div className=\"flex flex-col gap-3\">\n      {[SOFT, SOLID].map((styles, row) => (\n        <div key={row} className=\"flex flex-wrap items-center gap-2\">\n          <code className=\"w-12 font-mono text-xs text-text-muted\">\n            {row === 0 ? 'soft' : 'solid'}\n          </code>\n          {STATUSES.map((status) => (\n            <span\n              key={status}\n              className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${styles[status]}`}\n            >\n              {status}\n            </span>\n          ))}\n        </div>\n      ))}\n    </div>\n  );\n}\n" },
  "theming/typography": { component: Demo991, file: "theming/typography.tsx", source: "'use client';\n\nconst SCALE = [\n  { className: 'text-4xl font-bold', name: 'text-4xl', spec: '36 / 40' },\n  { className: 'text-3xl font-bold', name: 'text-3xl', spec: '30 / 36' },\n  { className: 'text-2xl font-semibold', name: 'text-2xl', spec: '24 / 32' },\n  { className: 'text-xl font-semibold', name: 'text-xl', spec: '20 / 28' },\n  { className: 'text-lg font-medium', name: 'text-lg', spec: '18 / 28' },\n  { className: 'text-base', name: 'text-base', spec: '16 / 24' },\n  { className: 'text-sm', name: 'text-sm', spec: '14 / 20' },\n  { className: 'text-xs font-medium', name: 'text-xs', spec: '12 / 16' },\n];\n\nexport default function ThemingTypography() {\n  return (\n    <div className=\"flex w-full flex-col divide-y divide-border\">\n      {SCALE.map((item) => (\n        <div key={item.name} className=\"flex items-baseline gap-4 py-2\">\n          <div className=\"flex w-24 shrink-0 flex-col\">\n            <code className=\"font-mono text-xs text-text\">{item.name}</code>\n            <span className=\"text-xs text-text-muted\">{item.spec}</span>\n          </div>\n          <p className={`${item.className} truncate text-text`}>O'zbekiston — Ўзбекистон</p>\n        </div>\n      ))}\n      <p className=\"pt-3 font-mono text-sm text-text-muted\">font-mono: 1 250 000 so'm · +998 90</p>\n    </div>\n  );\n}\n" },
  "toast/action": { component: Demo992, file: "toast/action.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastAction() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.success('Buyurtma yaratildi', {\n            description: \"#1042 · 1 250 000 so'm\",\n            action: { label: \"Ko'rish\", onClick: () => toast.info('Buyurtma #1042 ochildi') },\n          })\n        }\n      >\n        Amal bilan\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast(\"Mahsulot o'chirildi\", {\n            description: 'iPhone 15 Pro, 256 GB',\n            action: {\n              label: 'Qaytarish',\n              onClick: () => toast.success('Mahsulot qaytarildi'),\n            },\n          })\n        }\n      >\n        Bekor qilish (undo)\n      </Button>\n    </div>\n  );\n}\n" },
  "toast/promise": { component: Demo993, file: "toast/promise.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nasync function saveOrder() {\n  await wait(1500);\n  return 1042;\n}\n\nasync function failingRequest(): Promise<void> {\n  await wait(1200);\n  throw new Error('Server javob bermadi');\n}\n\nexport default function ToastPromise() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.promise(saveOrder, {\n            loading: 'Saqlanmoqda...',\n            success: (id) => `Buyurtma #${id} saqlandi`,\n            error: 'Xatolik yuz berdi',\n          })\n        }\n      >\n        Muvaffaqiyatli\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast\n            .promise(failingRequest, {\n              loading: 'Yuborilmoqda...',\n              success: 'Yuborildi',\n              error: (e) => `Xatolik: ${(e as Error).message}`,\n            })\n            .catch(() => {})\n        }\n      >\n        Xato bilan\n      </Button>\n    </div>\n  );\n}\n" },
  "toast/stack": { component: Demo994, file: "toast/stack.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastStack() {\n  const burst = () => {\n    toast.info(\"Yangi mijoz ro'yxatdan o'tdi\");\n    toast.success(\"To'lov qabul qilindi\", { description: \"350 000 so'm\" });\n    toast.warning('Omborda 3 ta qoldi');\n    toast('Yangi sharh qoldirildi');\n  };\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button variant=\"outline\" onClick={burst}>\n        4 tasini birdan\n      </Button>\n      <Button variant=\"ghost\" onClick={() => toast.dismiss()}>\n        Hammasini yopish\n      </Button>\n    </div>\n  );\n}\n" },
  "toast/types": { component: Demo995, file: "toast/types.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nexport default function ToastTypes() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Button variant=\"outline\" onClick={() => toast('Havola nusxalandi')}>\n        Oddiy\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.success(\"O'zgarishlar saqlandi\")}>\n        success\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.error(\"Ulanib bo'lmadi\", {\n            description: \"Internetni tekshirib, qayta urinib ko'ring.\",\n          })\n        }\n      >\n        error\n      </Button>\n      <Button\n        variant=\"outline\"\n        onClick={() =>\n          toast.warning('Obuna 3 kundan keyin tugaydi', {\n            description: \"To'lovni oldindan qiling.\",\n          })\n        }\n      >\n        warning\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.info('Yangi versiya mavjud')}>\n        info\n      </Button>\n      <Button variant=\"outline\" onClick={() => toast.loading('Hisobot tayyorlanmoqda...')}>\n        loading\n      </Button>\n      <Button variant=\"ghost\" onClick={() => toast.dismiss()}>\n        Hammasini yopish\n      </Button>\n    </div>\n  );\n}\n" },
  "toast/update": { component: Demo996, file: "toast/update.tsx", source: "'use client';\n\nimport { Button, toast } from '@akhatmirzo/ui';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function ToastUpdate() {\n  const upload = async () => {\n    const id = toast.loading('Fayl yuklanmoqda...', { description: 'hisobot.xlsx' });\n    await wait(1000);\n    toast.loading('Fayl tekshirilmoqda...', { id, description: 'hisobot.xlsx' });\n    await wait(1000);\n    toast.success('Fayl yuklandi', { id, description: 'hisobot.xlsx · 2,4 MB' });\n  };\n\n  return (\n    <Button variant=\"outline\" onClick={upload}>\n      Faylni yuklash\n    </Button>\n  );\n}\n" },
  "tooltip/basic": { component: Demo997, file: "tooltip/basic.tsx", source: "'use client';\n\nimport { IconButton, Tooltip } from '@akhatmirzo/ui';\nimport { Copy, Heart, Share2, Trash2 } from 'lucide-react';\n\nexport default function TooltipBasic() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Tooltip content=\"Nusxa olish\" shortcut={['mod', 'C']}>\n        <IconButton variant=\"outline\" aria-label=\"Nusxa olish\">\n          <Copy />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"Ulashish\">\n        <IconButton variant=\"outline\" aria-label=\"Ulashish\">\n          <Share2 />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"Sevimlilarga qo'shish\">\n        <IconButton variant=\"outline\" aria-label=\"Sevimlilarga qo'shish\">\n          <Heart />\n        </IconButton>\n      </Tooltip>\n      <Tooltip content=\"O'chirish\" shortcut={['Del']}>\n        <IconButton variant=\"ghost\" aria-label=\"O'chirish\">\n          <Trash2 />\n        </IconButton>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "tooltip/controlled": { component: Demo998, file: "tooltip/controlled.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\nimport { useState } from 'react';\n\nexport default function TooltipControlled() {\n  const [open, setOpen] = useState(false);\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Button variant=\"outline\" onClick={() => setOpen((o) => !o)}>\n        {open ? 'Yashirish' : \"Ko'rsatish\"}\n      </Button>\n      <Tooltip content=\"Boshqariladigan tooltip\" open={open} onOpenChange={setOpen}>\n        <Button>Nishon</Button>\n      </Tooltip>\n      <Tooltip content=\"Bu matn chiqmaydi\" disabled>\n        <Button>disabled</Button>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "tooltip/delay": { component: Demo999, file: "tooltip/delay.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipDelay() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      <Tooltip content=\"Darhol chiqadi\" delay={0}>\n        <Button>delay=0</Button>\n      </Tooltip>\n      <Tooltip content=\"Bir soniya kutadi\" delay={1000}>\n        <Button>delay=1000</Button>\n      </Tooltip>\n      <Tooltip content=\"Uzun izoh 240px dan oshsa, keyingi qatorga o'raladi: buyurtma holati har 5 daqiqada yangilanadi.\">\n        <Button>Uzun matn</Button>\n      </Tooltip>\n    </div>\n  );\n}\n" },
  "tooltip/disabled-button": { component: Demo1000, file: "tooltip/disabled-button.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipDisabledButton() {\n  return (\n    <Tooltip content=\"Ruxsat yo'q: faqat administrator saqlay oladi\">\n      <span tabIndex={0} className=\"focus-ring inline-flex rounded-lg\">\n        <Button variant=\"primary\" disabled>\n          Saqlash\n        </Button>\n      </span>\n    </Tooltip>\n  );\n}\n" },
  "tooltip/sides": { component: Demo1001, file: "tooltip/sides.tsx", source: "'use client';\n\nimport { Button, Tooltip } from '@akhatmirzo/ui';\n\nexport default function TooltipSides() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3\">\n      {(['top', 'right', 'bottom', 'left'] as const).map((side) => (\n        <Tooltip key={side} content={`Tomon: ${side}`} side={side}>\n          <Button variant=\"outline\">{side}</Button>\n        </Tooltip>\n      ))}\n    </div>\n  );\n}\n" },
  "virtual-list/basic": { component: Demo1002, file: "virtual-list/basic.tsx", source: "'use client';\n\nimport { Badge, Button, Input, VirtualList, type VirtualListHandle } from '@akhatmirzo/ui';\nimport { useMemo, useRef, useState } from 'react';\n\nconst LEVELS = [\n  { label: 'Info', color: 'info', text: 'Foydalanuvchi tizimga kirdi' },\n  { label: 'Tayyor', color: 'success', text: \"To'lov qabul qilindi\" },\n  { label: 'Ogohlantirish', color: 'warning', text: 'Omborda mahsulot kam qoldi' },\n  { label: 'Xato', color: 'danger', text: \"SMS yuborib bo'lmadi\" },\n] as const;\n\nexport default function VirtualListBasic() {\n  const logs = useMemo(\n    () => Array.from({ length: 10_000 }, (_, i) => ({ id: i + 1, ...LEVELS[i % LEVELS.length]! })),\n    [],\n  );\n  const ref = useRef<VirtualListHandle>(null);\n  const [target, setTarget] = useState('5000');\n\n  const go = () => ref.current?.scrollToIndex(Number(target) - 1, { align: 'start' });\n\n  return (\n    <div className=\"flex w-full flex-col gap-3\">\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Input\n          aria-label=\"Qator raqami\"\n          inputMode=\"numeric\"\n          value={target}\n          onChange={(e) => setTarget(e.target.value.replace(/\\D/g, ''))}\n          onKeyDown={(e) => e.key === 'Enter' && go()}\n          className=\"w-28\"\n        />\n        <Button variant=\"soft\" onClick={go}>\n          Qatorga o'tish\n        </Button>\n      </div>\n      <VirtualList\n        ref={ref}\n        aria-label=\"Tizim jurnali\"\n        items={logs}\n        estimateSize={48}\n        height={400}\n        overscan={8}\n        getItemKey={(log) => log.id}\n        className=\"rounded-xl border border-border bg-surface\"\n        renderItem={(log) => (\n          <div className=\"flex h-12 items-center gap-3 border-b border-border px-4 text-sm\">\n            <span className=\"w-14 shrink-0 text-text-faint tabular-nums\">#{log.id}</span>\n            <Badge color={log.color}>{log.label}</Badge>\n            <span className=\"min-w-0 flex-1 truncate\">{log.text}</span>\n          </div>\n        )}\n      />\n    </div>\n  );\n}\n" },
  "virtual-list/dynamic": { component: Demo1003, file: "virtual-list/dynamic.tsx", source: "'use client';\n\nimport { Avatar, VirtualList } from '@akhatmirzo/ui';\n\nconst NAMES = ['Aziza Karimova', 'Bobur Toshmatov', \"G'ayrat Usmonov\", 'Malika Yusupova'];\nconst TEXTS = [\n  'Assalomu alaykum!',\n  \"Buyurtmam qachon yetib keladi? Kecha to'lov qilgan edim.\",\n  \"Yetkazish manzilini o'zgartirsam bo'ladimi? Hozir Samarqanddaman, kuryer oldindan qo'ng'iroq qilsin.\",\n  'Ha, albatta.',\n  \"Rahmat, mahsulot juda yoqdi. Qadoqlash ham a'lo darajada edi, do'stlarimga ham tavsiya qilaman.\",\n];\n\nconst messages = Array.from({ length: 2000 }, (_, i) => ({\n  id: i,\n  author: NAMES[(i * 3) % NAMES.length]!,\n  text: TEXTS[(i * 2 + (i >> 2)) % TEXTS.length]!,\n}));\n\nexport default function VirtualListDynamic() {\n  return (\n    <VirtualList\n      dynamic\n      aria-label=\"Mijozlar bilan yozishmalar\"\n      items={messages}\n      estimateSize={72}\n      height={400}\n      getItemKey={(m) => m.id}\n      className=\"w-full rounded-xl border border-border bg-surface\"\n      renderItem={(m) => (\n        <div className=\"flex gap-3 border-b border-border px-4 py-3\">\n          <Avatar name={m.author} size=\"sm\" />\n          <div className=\"flex min-w-0 flex-col gap-0.5\">\n            <span className=\"text-sm font-medium\">{m.author}</span>\n            <p className=\"m-0 text-sm text-text-muted\">{m.text}</p>\n          </div>\n        </div>\n      )}\n    />\n  );\n}\n" },
  "virtual-list/empty": { component: Demo1004, file: "virtual-list/empty.tsx", source: "'use client';\n\nimport { VirtualList } from '@akhatmirzo/ui';\n\nexport default function VirtualListEmpty() {\n  return (\n    <VirtualList\n      aria-label=\"Bildirishnomalar\"\n      items={[]}\n      estimateSize={48}\n      height={160}\n      renderItem={() => null}\n      emptyState=\"Hali bildirishnomalar yo'q\"\n      className=\"w-full max-w-md rounded-xl border border-border bg-surface\"\n    />\n  );\n}\n" },
  "virtual-list/infinite": { component: Demo1005, file: "virtual-list/infinite.tsx", source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { VirtualList } from '@akhatmirzo/ui';\nimport { useCallback, useState } from 'react';\n\nconst PAGE = 40;\nconst TOTAL = 400;\nconst NAMES = ['Jasur Karimov', 'Malika Rahimova', 'Nodira Saidova', 'Otabek Qodirov'];\n\nconst makeOrders = (from: number) =>\n  Array.from({ length: PAGE }, (_, i) => {\n    const id = from + i + 1;\n    return {\n      id,\n      customer: NAMES[id % NAMES.length]!,\n      total: ((id * 7919) % 90) * 15_000 + 150_000,\n    };\n  });\n\nexport default function VirtualListInfinite() {\n  const [orders, setOrders] = useState(() => makeOrders(0));\n  const [loading, setLoading] = useState(false);\n\n  const loadMore = useCallback(() => {\n    if (orders.length >= TOTAL) return;\n    setLoading(true);\n    // Haqiqiy loyihada — fetch(`/api/orders?offset=${orders.length}`)\n    setTimeout(() => {\n      setOrders((prev) => [...prev, ...makeOrders(prev.length)]);\n      setLoading(false);\n    }, 900);\n  }, [orders.length]);\n\n  return (\n    <div className=\"flex w-full flex-col gap-2\">\n      <p className=\"m-0 text-sm text-text-muted\">\n        Yuklangan: {orders.length} / {TOTAL}\n      </p>\n      <VirtualList\n        aria-label=\"Buyurtmalar\"\n        items={orders}\n        estimateSize={52}\n        height={360}\n        loadingMore={loading}\n        onEndReached={loadMore}\n        getItemKey={(o) => o.id}\n        labels={{ loadingMore: 'Buyurtmalar yuklanmoqda...' }}\n        className=\"rounded-xl border border-border bg-surface\"\n        renderItem={(o) => (\n          <div className=\"flex h-13 items-center gap-3 border-b border-border px-4 text-sm\">\n            <span className=\"w-14 shrink-0 text-text-faint tabular-nums\">№{o.id}</span>\n            <span className=\"min-w-0 flex-1 truncate\">{o.customer}</span>\n            <span className=\"shrink-0 font-medium tabular-nums\">{formatMoney(o.total)}</span>\n          </div>\n        )}\n      />\n    </div>\n  );\n}\n" },
};
